        public SkaliaBotIdleSimulation(
            Player player,
            ILogger logger,
            bool movementEnabled,
            float avoidPlayersWithinMeters,
            float turnSpeedDegreesPerSecond,
            float obstacleCheckDistanceMeters,
            float lootSearchRadiusMeters,
            float lootPickupDistanceMeters,
            float objectiveTimeoutSeconds,
            float zombieDetectionRadiusMeters,
            float zombieAttackDistanceMeters)
        {
            m_Player = player;
            m_Logger = logger;
            m_MovementEnabled = movementEnabled;
            m_AvoidPlayersWithinMeters = Mathf.Max(1f, avoidPlayersWithinMeters);
            m_TurnSpeedDegreesPerSecond = Mathf.Max(10f, turnSpeedDegreesPerSecond);
            m_ObstacleCheckDistanceMeters = Mathf.Max(0.75f, obstacleCheckDistanceMeters);
            m_LootSearchRadiusMeters = Mathf.Max(10f, lootSearchRadiusMeters);
            m_LootPickupDistanceMeters = Mathf.Max(1.5f, lootPickupDistanceMeters);
            m_ObjectiveTimeoutSeconds = Mathf.Max(20f, objectiveTimeoutSeconds);
            m_ZombieDetectionRadiusMeters = Mathf.Max(5f, zombieDetectionRadiusMeters);
            m_ZombieAttackDistanceMeters = Mathf.Clamp(zombieAttackDistanceMeters, 1f, 1.65f);
            m_BehaviorTree = BuildBehaviorTree();
        }

        private IBotBehaviorNode BuildBehaviorTree()
        {
            return new BotReactiveSelectorNode(
                new BotActionNode(TickHazardBehavior),
                // 0.1.0-y17.25: out of a deadzone in time (SkaliaBotRadiationY).
                new BotReactiveSequenceNode(
                    new BotConditionNode(IsRadiationExitRequired),
                    new BotActionNode(TickRadiationExitBehavior)),
                new BotReactiveSequenceNode(
                    new BotConditionNode(IsWaterBehaviorRequired),
                    new BotActionNode(TickWaterBehavior)),
                new BotActionNode(TickForcedMovementBehavior),
                new BotUtilitySelectorNode(
                    new BotUtilityCandidate(
                        GetBossHuntUtility,
                        new BotActionNode(TickBossHuntBehavior)),
                    new BotUtilityCandidate(
                        GetBossFleeUtility,
                        new BotActionNode(TickBossFleeBehavior),
                        true),
                    new BotUtilityCandidate(
                        GetWeaponGrabUtility,
                        new BotActionNode(TickAcquireCombatEquipmentBehavior)),
                    new BotUtilityCandidate(
                        GetLowHealthFleeUtility,
                        new BotActionNode(TickLowHealthFleeBehavior),
                        true),
                    new BotUtilityCandidate(
                        GetSwarmUtility,
                        new BotActionNode(TickSwarmBehavior),
                        true),
                    new BotUtilityCandidate(
                        GetFireZombieUtility,
                        new BotActionNode(TickFireZombieBehavior),
                        true),
                    new BotUtilityCandidate(
                        GetCombatUtility,
                        new BotActionNode(TickCombatBehavior)),
                    new BotUtilityCandidate(
                        GetCombatEquipmentUtility,
                        new BotActionNode(TickAcquireCombatEquipmentBehavior)),
                    new BotUtilityCandidate(
                        GetRefillUtility,
                        new BotActionNode(TickRefillBehavior)),
                    new BotUtilityCandidate(
                        GetLootUtility,
                        new BotActionNode(TickLootBehavior)),
                    new BotUtilityCandidate(
                        () => 100f,
                        new BotActionNode(TickExplorationBehavior)))
                    .WithCommitment(() => m_BehaviorNow, IsDecisionEmergency, DecisionCommitSeconds, 900f));
        }

        // 0.1.166: what the bot is doing keeps going for at least this long
        // before something else that is not an emergency replaces it.
        private const float DecisionCommitSeconds = 4f;

        private bool IsDecisionEmergency()
        {
            return m_BehaviorNow - m_LastZombieBiteAt < 2f
                || m_CachedNearestZombieDistance < 4f
                || m_CachedNearestFireZombieDistance < 8f
                || m_ThreatHuntingFireDistance < FireFleeHuntingMeters
                || IsLowHealth()
                || m_Player.life.isBleeding;
        }

        private float GetSwarmUtility()
        {
            // 0.1.0-y17.12: kill them all or lose them all, chosen once
            // (SkaliaBotHordeCommitY).
            if (UpdateHordeFightCommit(m_BehaviorNow))
            {
                return -1f;
            }
            // 0.2.2x8 (doc 16.16): a stalled escape gave way to a 4s fight
            // (TryYieldSwarmToFight), as does a flee with a zombie on the bot.
            if (IsFleeYielding(m_BehaviorNow))
            {
                return -1f;
            }
            if (m_SwarmEscapeActive)
            {
                return 1000f + m_CachedSurroundedZombieCount * 10f;
            }
            if (ShouldLeaveBigGroup(m_BehaviorNow))
            {
                return 900f + m_CachedSurroundedZombieCount * 10f;
            }
            if (m_CachedSurroundedZombieCount < SurroundedZombieCount)
            {
                return -1f;
            }
            if (!ShouldFightSmallGroup(m_BehaviorNow))
            {
                return 900f + m_CachedSurroundedZombieCount * 10f;
            }
            StartHordeFightCommit("grupo pequeno que da para encarar", m_BehaviorNow);
            return -1f;
        }

        // 0.1.173: the burner is fled from whoever it is (remembered,
        // ignored, marked): one hunting the bot within 30m, or any within
        // 12m, unless a loaded gun can shoot it from 10m out. The flee ends
        // at 40m, or 25m when it stopped hunting or stood still, or 30m out of
        // sight. Fighting it up close is a last resort (IsFireLastResort).
        private float GetFireZombieUtility()
        {
            var now = m_BehaviorNow;
            if (TryFindFireThreat(m_BehaviorPosition, FireZombieVisualRadiusMeters, out var threatFire))
            {
                if (m_FireFleeActive)
                {
                    return 800f;
                }
                var threatDistance = (threatFire.transform.position - m_BehaviorPosition).GetHorizontalMagnitude();
                if (ShouldStartFireFlee(threatFire, threatDistance, m_BehaviorPosition, now))
                {
                    return 800f;
                }
            }
            else if (m_FireFleeActive)
            {
                EndFireFlee(now, "zumbi de fogo sumiu");
            }
            var rememberedFireIsValid = m_RememberedFireZombie != null
                && !m_RememberedFireZombie.isDead
                && m_RememberedFireZombie.gameObject.activeInHierarchy
                && (m_RememberedFireZombie != m_IgnoredFireZombie
                    || now >= m_IgnoreFireZombieUntil);
            return rememberedFireIsValid
                   || m_CachedNearestFireZombieDistance
                      <= FireZombieVisualRadiusMeters
                ? 800f
                : -1f;
        }

        private float GetLowHealthFleeUtility()
        {
            return m_BehaviorNow >= m_LowHealthFleeBlockedUntil
                   && !IsFleeYielding(m_BehaviorNow)
                   && ShouldFleeForHealth()
                ? 950f
                : -1f;
        }

        private bool ShouldFleeForHealth()
        {
            var life = m_Player.life;
            UpdateUnarmedGroupFlee();
            if (IsCaughtByZombie())
            {
                return false;
            }
            if (m_UnarmedGroupFlee)
            {
                return true;
            }
            // 0.2.2y11: a man on the bot is answered, not run from
            // (SkaliaBotPvpHealY).
            if (IsPvpEnemyOnMe(Time.realtimeSinceStartup))
            {
                return false;
            }
            // 0.1.0-y17.3: nor with a man seen or hitting it in the last
            // 10s, unless zombies surround it. Test of 18/11, LilJuninho
            // hit by Ghost from 11m (12:04:43) and 24m (12:05:06): the run
            // went from a crawler 14m off, the second one across Ghost's
            // line, and it died with the gun in hand. The players hit
            // (rec/pvp16.py) answered the man: on their screen they shot
            // back (7 of 9 within 60m), off it they turned to him or ran
            // from him; that is the fight's own code (SkaliaBotPvpFeelY,
            // SkaliaBotPvpHealY). A shot only heard does not count: a bot
            // firing at zombies 50m off is no man on it.
            var fleeNow = Time.realtimeSinceStartup;
            if (m_PvpTarget != null
                && ((m_PvpAware && fleeNow - m_PvpLastSeenAt <= PvpActiveSeconds)
                    || fleeNow - m_LastHurtByPlayerAt <= PvpActiveSeconds)
                && m_CachedSurroundedZombieCount <= 2)
            {
                return false;
            }
            // With 16 health the flee stopped at 15m and the bot set off on a
            // 103m patrol into seven zombies. Once fleeing, keep going to 30m.
            var fleeRadius = m_LowHealthFleeActive ? LowHealthFleeReleaseMeters : FleeZombieRadiusMeters;
            if (!IsLowHealth() || m_CachedNearestZombieDistance >= fleeRadius)
            {
                return false;
            }
            // Turning around with a zombie already in reach only exposes the
            // bot's back. Keep fighting one or two zombies at arm's length and
            // flee only from a group or from zombies that are not yet in reach.
            return m_CachedNearestZombieDistance > FleeMinimumZombieDistanceMeters
                || m_CachedSurroundedZombieCount > 2;
        }

        // Bare fists against three or more zombies only ends in death: run
        // until none is within flee range or a weapon is in hand.
        private void UpdateUnarmedGroupFlee()
        {
            if (!m_UnarmedGroupFlee)
            {
                if (IsUnarmed() && m_CachedNearbyZombieCount >= UnarmedGroupFleeCount)
                {
                    m_UnarmedGroupFlee = true;
                    BotLog(LogLevel.Information,
                        "Bot desarmado com {Count} zumbis a 12m; fugindo em vez de lutar no soco.",
                        m_CachedNearbyZombieCount);
                }
                return;
            }
            if (!IsUnarmed() || m_CachedNearestZombieDistance >= FleeZombieRadiusMeters)
            {
                m_UnarmedGroupFlee = false;
                BotLog(LogLevel.Information,
                    "Fuga de desarmado encerrada: zumbi mais proximo a {Distance:0.#}m; arma {Weapon}.",
                    m_CachedNearestZombieDistance,
                    DescribeEquipped());
            }
        }

        // Zombies keep pace with a sprinting bot, so a flee that lets one get
        // within arm's reach only trades blows for hits in the back. Once
        // caught, the bot stands its ground for a moment and fights.
        private bool IsCaughtByZombie()
        {
            var now = m_BehaviorNow;
            if (m_CachedNearestBoss != null
                && m_CachedNearestBossDistance <= m_CachedNearestZombieDistance + 0.1f)
            {
                // Standing ground against a Mega only trades a knife for its
                // fists (31 and 28 damage a hit in the logs).
                return false;
            }
            if (now < m_StandGroundUntil)
            {
                return true;
            }
            if (m_CachedNearestZombieDistance > CaughtByZombieMeters)
            {
                return false;
            }
            m_StandGroundUntil = now + StandGroundSeconds;
            if (now >= m_NextStandGroundLogAt
                && (m_UnarmedGroupFlee || m_ObjectiveType == ObjectiveType.Flee))
            {
                m_NextStandGroundLogAt = now + 5f;
                BotLog(LogLevel.Information,
                    "Bot alcancado por zumbi a {Distance:0.#}m durante a fuga; revidando com {Weapon} (vida {Health}).",
                    m_CachedNearestZombieDistance,
                    DescribeEquipped(),
                    m_Player.life.health);
            }
            if (m_ObjectiveType == ObjectiveType.Flee)
            {
                ClearObjective();
            }
            return true;
        }

        // 0.1.166: at 34 health thigas ran from two zombies, then walked
        // straight back toward them for a Crossbow 63m away and ran again,
        // five times in 30s (22:20). For a minute after a low-health flee,
        // while health stays low, nothing near what it fled from is fetched.
        private Vector3 m_HealthFleeThreat;
        private float m_HealthFleeThreatUntil = float.NegativeInfinity;
        private const float HealthFleeMemorySeconds = 60f;

        private bool IsNearRecentFleeThreat(Vector3 point, float now)
        {
            return now < m_HealthFleeThreatUntil
                && IsLowHealth()
                && (point - m_HealthFleeThreat).GetHorizontalMagnitude() < LowHealthFleeReleaseMeters;
        }

        private void NoteHealthFleeThreat(Vector3 position, float now)
        {
            var best = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var distance = (zombie.transform.position - position).GetHorizontalMagnitude();
                if (distance < best)
                {
                    best = distance;
                    m_HealthFleeThreat = zombie.transform.position;
                }
            }
            if (!float.IsPositiveInfinity(best))
            {
                m_HealthFleeThreatUntil = now + HealthFleeMemorySeconds;
            }
        }

        private bool IsLowHealth()
        {
            var life = m_Player.life;
            // 0.1.0-y17.34: over serverBot:modifiers:courage.
            return life.health < FleeHealthThreshold / SkaliaBotModifiers.Courage
                || (life.isBleeding && life.health < (FleeHealthThreshold + 25f) / SkaliaBotModifiers.Courage);
        }

        private BotBehaviorStatus TickLowHealthFleeBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            if (!ShouldFleeForHealth())
            {
                if (m_ObjectiveType == ObjectiveType.Flee)
                {
                    ClearObjective();
                }
                if (m_LowHealthFleeActive)
                {
                    m_LowHealthFleeActive = false;
                    BotLog(LogLevel.Information,
                        "Fuga encerrada: vida {Health}; zumbi mais proximo a {Distance:0.#}m.",
                        m_Player.life.health,
                        m_CachedNearestZombieDistance);
                    // A flee that ended because a zombie caught the bot is a
                    // fight at arm's length, not an escape.
                    if (m_CachedNearestZombieDistance > 4f)
                    {
                        StartDisengage(
                            now < m_HealthFleeThreatUntil ? m_HealthFleeThreat : GetThreatCentroid(position, 30f),
                            "fugir com vida baixa",
                            now);
                    }
                }
                return BotBehaviorStatus.Failure;
            }
            if (m_ObjectiveType != ObjectiveType.Flee
                || now >= m_ObjectiveExpiresAt
                || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 4f)
            {
                // The forced-movement node clears a flee objective whose point
                // is within 4m, so a point that close would restart the flee
                // every tick and leave the bot frozen next to the zombie.
                if (!TryFindLowHealthEscapePoint(position, now, out var escapePoint))
                {
                    if (m_ObjectiveType == ObjectiveType.Flee)
                    {
                        ClearObjective();
                    }
                    m_LowHealthFleeActive = false;
                    m_LowHealthFleeBlockedUntil = now + 5f;
                    BotLog(LogLevel.Information,
                        "Bot com vida {Health} sem rota de fuga a partir de {Position}; continua lutando por 5s.",
                        m_Player.life.health,
                        FormatPosition(position));
                    return BotBehaviorStatus.Failure;
                }
                if (!m_LowHealthFleeActive)
                {
                    m_LowHealthFleeActive = true;
                    BotLog(LogLevel.Information,
                        "Bot com vida {Health} (sangrando {Bleeding}) fugindo de zumbi a {Distance:0.#}m para {Destination}.",
                        m_Player.life.health,
                        m_Player.life.isBleeding,
                        m_CachedNearestZombieDistance,
                        FormatPosition(escapePoint));
                }
                NoteHealthFleeThreat(position, now);
                m_FleeingFromPlayerName = "zumbis";
                SetObjective(ObjectiveType.Flee, escapePoint, now + 10f);
            }
            return BotBehaviorStatus.Running;
        }

        // With low health (and not bleeding) the bot neither patrols nor
        // explores: it walks away from zombies within 20m and otherwise stands
        // still until natural regeneration brings it back above the threshold.
        private bool TickLowHealthRest(Vector3 position, float now)
        {
            if (!LowHealthRestEnabled)
            {
                return false;
            }
            if (!IsLowHealth() || m_Player.life.isBleeding)
            {
                if (m_LowHealthResting)
                {
                    m_LowHealthResting = false;
                    BotLog(LogLevel.Information,
                        "Descanso encerrado: vida {Health}; sangrando {Bleeding}.",
                        m_Player.life.health,
                        m_Player.life.isBleeding);
                }
                return false;
            }
            if (now < m_RestSuspendedUntil)
            {
                return false;
            }
            if (!m_LowHealthResting)
            {
                m_LowHealthResting = true;
                m_RestProgressAt = now;
                m_RestBestHealth = m_Player.life.health;
                BotLog(LogLevel.Information,
                    "Bot com vida {Health} parou de explorar para descansar; zumbi mais proximo a {Distance:0.#}m.",
                    m_Player.life.health,
                    m_CachedNearestZombieDistance);
            }
            if (m_Player.life.health > m_RestBestHealth)
            {
                m_RestBestHealth = m_Player.life.health;
                m_RestProgressAt = now;
            }
            // Standing still only helps while health regenerates. Without food
            // or water above the server minimum the bot stood for 18 min.
            GetRegenThresholds(out var restRegenFood, out var restRegenWater);
            var cannotRegen = (m_Player.life.food <= restRegenFood && !TryFindMeal(false, out _, out _, out _))
                || (m_Player.life.water <= restRegenWater && !TryFindMeal(true, out _, out _, out _));
            if (cannotRegen || now - m_RestProgressAt >= 120f)
            {
                m_RestSuspendedUntil = now + (cannotRegen ? 60f : 90f);
                m_LowHealthResting = false;
                BotLog(LogLevel.Information,
                    "Descanso encerrado sem recuperar vida ({Reason}); vida {Health}, comida {Food}, agua {Water}; voltando a procurar comida/agua.",
                    cannotRegen ? "sem comida/agua para regenerar" : "2 min sem a vida subir",
                    m_Player.life.health,
                    m_Player.life.food,
                    m_Player.life.water);
                return false;
            }
            if (m_CachedNearestZombieDistance <= FleeMinimumZombieDistanceMeters + 1f
                && TryFindNearestNormalZombie(position, FleeMinimumZombieDistanceMeters + 1f, out var restAttacker))
            {
                if (m_TargetZombie != restAttacker)
                {
                    BotLog(LogLevel.Information,
                        "Descansando com zumbi colado a {Distance:0.#}m; revidando em vez de virar as costas.",
                        (restAttacker.transform.position - position).GetHorizontalMagnitude());
                }
                ForceCombatTarget(restAttacker, now);
                return true;
            }
            if (m_CachedNearestZombieDistance < LowHealthRestZombieRadiusMeters)
            {
                if ((m_ObjectiveType != ObjectiveType.Flee
                        || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 4f)
                    && TryFindLowHealthEscapePoint(position, now, out var restPoint))
                {
                    m_FleeingFromPlayerName = "zumbis";
                    SetObjective(ObjectiveType.Flee, restPoint, now + 10f);
                }
                return true;
            }
            if (m_ObjectiveType == ObjectiveType.Explore
                || m_ObjectiveType == ObjectiveType.Patrol
                || m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.Travel)
            {
                ClearObjective();
            }
            return m_ObjectiveType == ObjectiveType.None;
        }

        private bool TryFindLowHealthEscapePoint(Vector3 position, float now, out Vector3 escapePoint)
        {
            const float minimumDistance = 8f;
            escapePoint = FindZombieEscapePoint(position, now);
            if ((escapePoint - position).GetHorizontalMagnitude() >= minimumDistance)
            {
                return true;
            }

            // Fall back to running straight away from the nearest zombie.
            Zombie? nearest = null;
            var nearestDistance = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var distance = (zombie.transform.position - position).GetHorizontalMagnitude();
                if (distance < nearestDistance)
                {
                    nearest = zombie;
                    nearestDistance = distance;
                }
            }
            var away = nearest != null
                ? position - nearest.transform.position
                : Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f) * Vector3.forward;
            away.y = 0f;
            if (away.sqrMagnitude < 0.01f)
            {
                away = Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f) * Vector3.forward;
            }
            away.Normalize();
            for (var radius = 12f; radius <= 30f; radius += 6f)
            {
                for (var offsetStep = 0; offsetStep <= 4; offsetStep++)
                {
                    var angle = (offsetStep % 2 == 0 ? 1f : -1f) * ((offsetStep + 1) / 2) * 30f;
                    var candidate = FindNearestNavigablePoint(
                        position + Quaternion.Euler(0f, angle, 0f) * away * radius);
                    if ((candidate - position).GetHorizontalMagnitude() < minimumDistance
                        || WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                        || CrossesWater(position, candidate)
                        || IsHazardousPosition(candidate, now, 2f)
                        || Mathf.Abs(candidate.y - position.y) > 8f)
                    {
                        continue;
                    }
                    escapePoint = candidate;
                    return true;
                }
            }
            return false;
        }

        private string BotName
        {
            get
            {
                var owner = m_Player != null ? m_Player.channel?.owner : null;
                return owner?.playerID.characterName ?? "?";
            }
        }

        // Every bot log line starts with the bot's name so that several
        // bots can be followed in the same OpenMod log.
        private void BotLog(LogLevel level, string template, params object?[] args)
        {
            if (!m_Logger.IsEnabled(level))
            {
                return;
            }
            var prefixed = new object?[args.Length + 1];
            prefixed[0] = BotName;
            System.Array.Copy(args, 0, prefixed, 1, args.Length);
            m_Logger.Log(level, "[{Bot}] " + template, prefixed);
        }

        private bool IsUnarmed()
        {
            return !HasUsableCombatEquipment();
        }

        // Right after a kill, with no zombie close, picking up what it dropped
        // (cloth, food, ammo) comes before running to the next zombie.
        private bool IsDropPickupWindow()
        {
            if (m_BehaviorNow >= m_DropPickupUntil)
            {
                return false;
            }
            var limit = m_ObjectiveType == ObjectiveType.Loot
                ? DropPickupAbortZombieMeters
                : DropPickupStartZombieMeters;
            if (m_CachedNearestZombieDistance <= limit
                || m_CachedNearestFireZombieDistance <= 15f)
            {
                return false;
            }
            return !IsTargetZombieAlive()
                || (m_TargetZombie!.transform.position - m_BehaviorPosition).GetHorizontalMagnitude() > limit;
        }

        private float GetCombatUtility()
        {
            if (IsDropPickupWindow())
            {
                return -1f;
            }
            if (m_TreatmentPhase != 0
                && GetNearestAggroedZombieDistance() > (m_TreatmentIsMeal ? 6f : 3f))
            {
                return -1f;
            }
            // 0.1.0-y17.12: chosen to kill the group: no patrol in the middle
            // of it (LilJuninho, 22:30:59, "Patrol" with a zombie at 1.5m).
            if (m_HordeFightCommit
                && (IsTargetZombieAlive() || m_CachedNearestZombieDistance <= SmallGroupRadiusMeters))
            {
                return 650f;
            }
            var unarmed = IsUnarmed();
            if (m_UnarmedGroupFlee && !IsCaughtByZombie())
            {
                return -1f;
            }
            var hordeCaution = IsHordeCaution();
            if (hordeCaution && !unarmed)
            {
                return (IsTargetZombieAlive()
                        && (m_TargetZombie!.transform.position - m_BehaviorPosition).GetHorizontalMagnitude()
                            <= GetCautionEngagementRadius(m_TargetZombie))
                       || TryPickStealthTarget(m_BehaviorPosition, out _)
                    ? 650f
                    : -1f;
            }
            if (unarmed || IsLowHealth() || hordeCaution)
            {
                // With bare fists, low health or half health in a horde, only
                // fight what is already close; distant zombies are left alone.
                var radius = hordeCaution
                    ? HordeCautionEngagementMeters
                    : IsLowHealth()
                        ? LowHealthEngagementRadiusMeters
                        : UnarmedEngagementRadiusMeters;
                var targetDistance = IsTargetZombieAlive()
                    ? (m_TargetZombie!.transform.position - m_BehaviorPosition)
                        .GetHorizontalMagnitude()
                    : float.PositiveInfinity;
                return targetDistance <= radius
                       || m_CachedNearestZombieDistance <= radius
                    ? 650f
                    : -1f;
            }
            // Washington test: 702 trips turned into fights, many against
            // zombies 35-49m away that were not after the bot, and the trips
            // hardly moved. On a trip only a zombie hunting the bot, or one
            // within 15m, is worth stopping for.
            if (m_TravelActive
                && m_CachedNearestZombieDistance > TravelEngageMeters
                && GetNearestAggroedZombieDistance() > GetZombieEngagementRadius())
            {
                return -1f;
            }
            // 0.2.2x14: a resting group of 5+ is left alone.
            if (IsSleepingHordeAhead(m_BehaviorNow))
            {
                return -1f;
            }
            return IsTargetZombieAlive()
                   || m_CachedNearestZombieDistance <= GetZombieEngagementRadius()
                ? 650f
                : -1f;
        }

        private const float TravelEngageMeters = 15f;

        private const float WeaponGrabMaxMeters = 25f;
        private const float WeaponGrabZombieMeters = 3.5f;

        // Unarmed and already heading to a weapon close by: grab it first,
        // unless a zombie is right on top of the bot.
        private bool IsGrabbingNearbyWeapon()
        {
            return m_ObjectiveType == ObjectiveType.Loot
                && m_LootTargetIsCombatEquipment
                && IsUnarmed()
                && m_CachedNearestZombieDistance > WeaponGrabZombieMeters
                && (m_ObjectivePosition - m_BehaviorPosition).GetHorizontalMagnitude() <= WeaponGrabMaxMeters;
        }

        private float GetWeaponGrabUtility()
        {
            return IsGrabbingNearbyWeapon() ? 960f : -1f;
        }

        private float GetCombatEquipmentUtility()
        {
            if (IsUnarmed())
            {
                return m_CachedNearestZombieDistance > UnarmedEngagementRadiusMeters
                    ? 500f
                    : -1f;
            }
            return !HasCompleteWeaponRoles()
                   && !HasLootBlockingThreat(m_ObjectiveType == ObjectiveType.Loot && m_LootTargetIsCombatEquipment)
                   && m_CachedNearestZombieDistance > 6f
                ? 500f
                : -1f;
        }

        private float GetLootUtility()
        {
            if (IsDropPickupWindow())
            {
                return m_ObjectiveType == ObjectiveType.Loot ? 450f : 360f;
            }
            if (HasLootBlockingThreat(m_ObjectiveType == ObjectiveType.Loot))
            {
                return -1f;
            }
            if (IsLowHealth() && m_CachedNearestZombieDistance < LowHealthFleeReleaseMeters)
            {
                return -1f;
            }
            if (m_ObjectiveType == ObjectiveType.Loot)
            {
                return 450f;
            }
            // Off the mesh no item has a route ("Couldn't find a node close to
            // the start point"): items in a river gorge and 144m away were picked
            // 70 times in 30s during one crossing. Loot again in the next town.
            if (m_TravelActive && m_TravelPhase == 2)
            {
                return -1f;
            }
            return (m_BehaviorNow >= m_NextLootScanTime || HasPendingLoot(m_BehaviorNow) || IsLootPileActive(m_BehaviorNow))
                   && m_CachedNearestZombieDistance > LootBlockZombieMeters
                ? 350f
                : -1f;
        }

        // The maps of the loaded level, each once per map. 0.1.0-y17.33: also
        // from the plugin at the level's load (ISkaliaBotService.PrepareMaps),
        // so the new navmesh is ready before the bots come in.
        internal static void StartMaps(ILogger logger)
        {
            SkaliaBotTerrainMap.EnsureStarted(logger);
            SkaliaBotStructureMap.EnsureStarted(logger);
            SkaliaBotNavmeshAudit.EnsureStarted(logger);
            SkaliaBotUnityNavmesh.EnsureStarted(logger);
            SkaliaBotLadderMap.EnsureStarted(logger);
            SkaliaBotObjectMap.EnsureStarted(logger);
        }

        public void Start()
        {
            if (m_Running)
            {
                return;
            }

            SkaliaBotMovementDiagnostics.Register(m_Player, m_Logger);
            s_ActiveSimulations[m_Player] = this;
            m_Running = true;
            StartMaps(m_Logger);
            // 0.2.2x4 (doc 16.12): the high places of the hunt area, measured
            // and written to a CSV only.
            EnsureHuntGround();
            if (s_HasHuntGround)
            {
                SkaliaBotVantageMap.EnsureStarted(m_Logger, s_HuntCenter, s_HuntName);
            }
            RunAsync().Forget();
        }

        public void Stop()
        {
            m_Running = false;
            s_ActiveSimulations.Remove(m_Player);
            SkaliaBotMovementDiagnostics.Unregister(m_Player);
            m_PathRequestGeneration++;
            m_PathPoints.Clear();
            ReleaseLootClaim();
        }

        internal static void NotifyDamage(PlayerLife life, EDeathCause cause, byte amount)
        {
            if (amount == 0
                || life == null
                || life.player == null
                || !s_ActiveSimulations.TryGetValue(life.player, out var simulation))
            {
                return;
            }

            if (IsEnvironmentalHazard(cause))
            {
                simulation.HandleEnvironmentalHazard(cause, amount);
            }
            else if (cause == EDeathCause.ZOMBIE || cause == EDeathCause.ANIMAL)
            {
                simulation.HandleCombatDamage(amount);
            }
            else if (cause == EDeathCause.BOULDER)
            {
                simulation.HandleCombatDamage(amount);
                simulation.NoteBossBoulderHit(amount);
            }
            else if (cause == EDeathCause.SPIT)
            {
                // 0.1.173: SPIT damage is standing in the acid puddle a
                // spitter leaves (PlayerLife: 10 every 10 ticks inside an
                // ACID bubble). Step out first; the spitter reaction comes
                // 1.5s later, and never during the swarm escape.
                simulation.HandleCombatDamage(amount);
                simulation.HandleAcidDamage();
            }
        }

        internal static void NotifyZombieKilled(Player player, Zombie zombie)
        {
            if (player == null
                || zombie == null
                || !s_ActiveSimulations.TryGetValue(player, out var simulation))
            {
                return;
            }
            var now = Time.realtimeSinceStartup;
            if (simulation.m_LastKilledZombie == zombie
                && now - simulation.m_LastKilledZombieAt < 2f)
            {
                return;
            }
            simulation.m_LastKilledZombie = zombie;
            simulation.m_LastKilledZombieAt = now;
            var killGap = (zombie.transform.position - player.transform.position).GetHorizontalMagnitude();
            if (zombie.isMega)
            {
                NoteMegaKilled(zombie.transform.position);
            }
            if (Tryhard
                && IsFireZombie(zombie)
                && simulation.m_ObjectiveType == ObjectiveType.RepositionFire
                && (simulation.m_RememberedFireZombie == null || simulation.m_RememberedFireZombie == zombie))
            {
                // 0.2.2x (doc 15.2, item 3): llo killed the burner with his
                // last round (11:46:01) and still walked to the escape point
                // and stood there 8s, eating. The burner is dead: on with
                // something else.
                simulation.BotLog(LogLevel.Information,
                    "Zumbi de fogo morto; saindo do recuo dele.");
                simulation.ClearObjective();
            }
            if (zombie.isMega && Tryhard && killGap <= MegaDropReachMeters)
            {
                // 0.2.2v (doc 13.3, item 3): the Mega's drop is a pile the
                // tryhard walks to and empties (XX killed it 35m away at
                // 18:56:25 and left for a top 55m off).
                simulation.m_DropPickupUntil = now + MegaDropSeconds;
                simulation.m_DropPickupCenter = zombie.transform.position;
                simulation.m_MegaDropPending = true;
                // 0.2.2x (doc 15.2, item 13): the Mega is dead, the window
                // after running from it no longer sends the bot away from
                // its pile, and the walk to the body starts over.
                simulation.m_MegaPileArrivedAt = 0f;
                simulation.m_DisengageUntil = 0f;
                simulation.m_DropPileName = "do Mega";
                simulation.BotLog(LogLevel.Information,
                    "Mega morto a {Distance:0}m em {Position}; pegando o drop dele antes de seguir.",
                    killGap,
                    FormatPosition(zombie.transform.position));
            }
            else if (killGap <= 15f
                && !(simulation.m_MegaDropPending && now < simulation.m_DropPickupUntil))
            {
                // A common zombie killed on the way does not cancel the
                // Mega's drop.
                simulation.m_DropPickupUntil = now + 20f;
                simulation.m_DropPickupCenter = zombie.transform.position;
                simulation.m_MegaDropPending = false;
            }
            if (simulation.m_PendingLootObservations.Count >= 32)
            {
                simulation.m_PendingLootObservations.RemoveAt(0);
            }
            simulation.m_PendingLootObservations.Add(new PendingLootObservation
            {
                Position = zombie.transform.position,
                NextScanAt = now + 0.25f,
                ExpiresAt = now + 2.25f
            });
            simulation.m_LastCombatThreatAt = now;
            simulation.m_StatKills++;
            simulation.m_StatKillsTotal++;
            simulation.BotLog(LogLevel.Information,
                "Matou zumbi em {Position} com {Weapon}; vida {Health}; total de abates {Kills}; tipo {Kind}.",
                FormatPosition(zombie.transform.position),
                simulation.DescribeEquipped(),
                player.life.health,
                simulation.m_StatKillsTotal,
                DescribeZombieKind(zombie));
            // 0.2.2x7 (doc 16.13.1): the gaze, the sights and the step after
            // a kill with a gun.
            simulation.StartPostKillLook(zombie, now);
        }

        // 0.1.166: 44 tries at fire zombies and the log could not say whether
        // any died. The kill line now names the kind.
        private static string DescribeZombieKind(Zombie zombie)
        {
            switch (zombie.speciality)
            {
                case EZombieSpeciality.NONE:
                case EZombieSpeciality.NORMAL:
                    return "comum";
                case EZombieSpeciality.BURNER:
                    return "fogo";
                case EZombieSpeciality.MEGA:
                    return "Mega";
                case EZombieSpeciality.CRAWLER:
                    return "rastejante";
                case EZombieSpeciality.SPRINTER:
                    return "corredor";
                case EZombieSpeciality.ACID:
                    return "acido";
                case EZombieSpeciality.FLANKER_FRIENDLY:
                case EZombieSpeciality.FLANKER_STALK:
                    return "flanqueador";
                case EZombieSpeciality.SPIRIT:
                    return "espirito";
                default:
                    return (zombie.isBoss ? "chefe " : string.Empty) + zombie.speciality;
            }
        }

        // A spitter hits from 20m+ where no melee zombie is near, and the bot
        // stood there losing 70 health. Go kill it, or get out of its reach.
        private void ReactToSpit()
        {
            var now = Time.realtimeSinceStartup;
            if (!m_Running || m_Player.life.isDead || now < m_NextSpitReactionAt)
            {
                return;
            }
            if (m_SwarmEscapeActive)
            {
                return;
            }
            m_NextSpitReactionAt = now + 2f;
            var position = m_Player.transform.position;
            Zombie? spitter = null;
            var best = 60f;
            if (ZombieManager.regions != null)
            {
                foreach (var region in ZombieManager.regions)
                {
                    if (region?.zombies == null)
                    {
                        continue;
                    }
                    foreach (var zombie in region.zombies)
                    {
                        if (zombie == null
                            || zombie.isDead
                            || !zombie.gameObject.activeInHierarchy
                            || !(zombie.speciality == EZombieSpeciality.ACID
                                 || zombie.speciality == EZombieSpeciality.BOSS_NUCLEAR
                                 || zombie.speciality == EZombieSpeciality.BOSS_ALL))
                        {
                            continue;
                        }
                        var distance = (zombie.transform.position - position).GetHorizontalMagnitude();
                        if (distance < best)
                        {
                            best = distance;
                            spitter = zombie;
                        }
                    }
                }
            }
            if (spitter == null)
            {
                return;
            }
            m_PerceivedZombies[spitter] = now + ZombieMemorySeconds;
            if (HasUsableCombatEquipment()
                && m_Player.life.health > 40
                && !IsZombieMarkedUnreachable(spitter, now)
                && IsSpitterAttackAllowed(spitter, position, now))
            {
                if (m_TargetZombie != spitter)
                {
                    BotLog(LogLevel.Information,
                        "Bot atingido por cuspe; atacando o cuspidor a {Distance:0.#}m (vida {Health}).",
                        best,
                        m_Player.life.health);
                }
                ForceCombatTarget(spitter, now);
                return;
            }
            if (TryFindConnectedRetreatPoint(position, spitter.transform.position, now, out var retreat))
            {
                BotLog(LogLevel.Information,
                    "Bot atingido por cuspe com vida {Health}; fugindo do cuspidor a {Distance:0.#}m para {Destination}.",
                    m_Player.life.health,
                    best,
                    FormatPosition(retreat));
                m_FleeingFromPlayerName = "cuspidor";
                SetObjective(ObjectiveType.Flee, retreat, now + 8f);
            }
        }

        private void HandleCombatDamage(byte amount)
        {
            if (!m_Running || m_Player.life.isDead)
            {
                return;
            }
            var now = Time.realtimeSinceStartup;
            m_LastCombatThreatAt = now;
            m_LastZombieBiteAt = now;
            m_CombatMovementPhase = CombatMovementPhase.Retreat;
            m_CombatRetreatEndsAt = now + CombatRetreatDurationSeconds;
            m_CombatRetreatPending = false;
            m_CombatShouldSprint = true;
            m_NextCombatSteeringAt = 0f;
            m_StatDamageHits++;
            m_TotalDamageTaken++;
            m_StatDamageTaken += amount;
            var damageLevel = LogLevel.Debug;
            if (now >= m_NextDamageLogAt)
            {
                damageLevel = LogLevel.Information;
                m_NextDamageLogAt = now + 5f;
            }
            BotLog(damageLevel,
                "Bot recebeu {Damage} de dano em combate; vida {Health}; sangrando {Bleeding}; arma {Weapon}; zumbis a 4m {Surrounded}, a 12m {Nearby}; zumbi mais perto {Attacker}; recuando.",
                amount,
                m_Player.life.health,
                m_Player.life.isBleeding,
                DescribeEquipped(),
                m_CachedSurroundedZombieCount,
                m_CachedNearbyZombieCount,
                DescribeNearestZombieType());
        }

        // Which kind of zombie is closest when a hit lands: single hits of
        // 28-41 in the Washington test (normal ones 7-15) and four deaths
        // by boulder point at Mega zombies the code never named.
        private string DescribeNearestZombieType()
        {
            var position = m_Player.transform.position;
            Zombie? nearest = null;
            var best = 6f;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var distance = (zombie.transform.position - position).magnitude;
                if (distance < best)
                {
                    best = distance;
                    nearest = zombie;
                }
            }
            return nearest == null
                ? "nenhum a 6m"
                : nearest.speciality + " a " + best.ToString("0.#") + "m";
        }

        private static bool IsEnvironmentalHazard(EDeathCause cause)
        {
            return cause == EDeathCause.ACID
                || cause == EDeathCause.BURNING
                || cause == EDeathCause.BURNER
                || cause == EDeathCause.SPARK;
        }

        private void HandleEnvironmentalHazard(EDeathCause cause, byte amount)
        {
            if (!m_Running || m_Player.life.isDead)
            {
                return;
            }

            var now = Time.realtimeSinceStartup;
            var position = m_Player.transform.position;
            RefreshInteriorExitKnowledge(position, now);
            PruneHazardMemories(now);

            HazardMemory? nearby = null;
            foreach (var memory in m_HazardMemories)
            {
                if ((memory.Position - position).GetHorizontalMagnitude() <= memory.Radius)
                {
                    nearby = memory;
                    break;
                }
            }

            if (nearby == null)
            {
                nearby = new HazardMemory
                {
                    Position = position,
                    Radius = HazardRadiusMeters,
                    ExpiresAt = now + HazardMemorySeconds
                };
                m_HazardMemories.Add(nearby);
            }
            else
            {
                nearby.ExpiresAt = now + HazardMemorySeconds;
                nearby.Radius = Mathf.Min(12f, nearby.Radius + 0.5f);
            }

            if ((cause == EDeathCause.BURNER || cause == EDeathCause.BURNING)
                && m_Player.life.health > FireZombieMeleeKeepHealth
                && m_ObjectiveType == ObjectiveType.Combat
                && IsTargetZombieAlive()
                && IsFireZombie(m_TargetZombie!)
                && (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude()
                   <= FireZombieMeleeReleaseMeters)
            {
                if (now >= m_NextFireHazardIgnoreLogAt)
                {
                    m_NextFireHazardIgnoreLogAt = now + 5f;
                    BotLog(LogLevel.Information,
                        "Queimadura de {Damage} ignorada para nao fugir no meio da luta com o zumbi de fogo; vida {Health}.",
                        amount,
                        m_Player.life.health);
                }
                return;
            }

            if (!m_HazardEscapeActive)
            {
                m_PreHazardObjectiveType = m_ObjectiveType;
                m_PreHazardObjectivePosition = m_ObjectivePosition;
                m_PreHazardObjectiveRemaining = float.IsPositiveInfinity(m_ObjectiveExpiresAt)
                    ? float.PositiveInfinity
                    : Mathf.Max(5f, m_ObjectiveExpiresAt - now);
                m_HazardEscapeActive = true;
                m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                m_LocalRecoveryAnalog = 0x11;
                m_LocalRecoveryJump = false;
                ClearPath();
            }

            m_LastHazardDamageAt = now;
            if (m_ObjectiveType != ObjectiveType.EscapeHazard
                || now - m_LastHazardReplanAt >= 1.5f
                || IsHazardousPosition(m_ObjectivePosition, now, 2f))
            {
                m_LastHazardReplanAt = now;
                var escape = FindHazardEscapePoint(position, now);
                SetObjective(ObjectiveType.EscapeHazard, escape, now + 25f);
            }

            if (now - m_LastHazardLogAt >= 1.5f)
            {
                m_LastHazardLogAt = now;
                BotLog(LogLevel.Information,
                    "Bot recebeu {Damage} de dano ambiental ({Cause}) em {Position}; "
                    + "fuga prioritaria para {Destination}.",
                    amount,
                    cause,
                    FormatPosition(position),
                    FormatPosition(m_ObjectivePosition));
            }
        }

        private bool UpdateHazardEscapeState(Vector3 position, float now)
        {
            if (!m_HazardEscapeActive)
            {
                return false;
            }

            PruneHazardMemories(now);
            var underwater = WaterUtility.isPointUnderwater(position + Vector3.up * 0.5f);
            var safe = now - m_LastHazardDamageAt >= HazardSafeSeconds
                && !underwater
                && !IsHazardousPosition(position, now, 1.5f);
            if (safe)
            {
                CompleteHazardEscape(position, now);
                return false;
            }

            if (m_ObjectiveType != ObjectiveType.EscapeHazard
                || now >= m_ObjectiveExpiresAt
                || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 2.5f
                || IsHazardousPosition(m_ObjectivePosition, now, 1f))
            {
                m_LastHazardReplanAt = now;
                SetObjective(
                    ObjectiveType.EscapeHazard,
                    FindHazardEscapePoint(position, now),
                    now + 25f);
            }

            return true;
        }

        private void CompleteHazardEscape(Vector3 position, float now)
        {
            var previousType = m_PreHazardObjectiveType;
            var previousPosition = m_PreHazardObjectivePosition;
            var previousRemaining = m_PreHazardObjectiveRemaining;
            m_HazardEscapeActive = false;
            m_SwarmEscapeActive = false;
            m_SwarmJumpUntil = 0f;
            m_NavigationJumpUntil = 0f;
            m_WallAvoidanceActive = false;
            m_WallMovementBlocked = false;
            m_FurnitureDetourActive = false;
            m_NextSwarmThreatScanAt = 0f;
            m_CachedSurroundedZombieCount = 0;
            m_CachedNearbyZombieCount = 0;
            m_CachedNearestFireZombieDistance = float.PositiveInfinity;
            m_CachedNearestZombieDistance = float.PositiveInfinity;
            ClearObjective();

            if (CanResumeSuspendedObjective(previousType)
                && !IsHazardousPosition(previousPosition, now, 2f))
            {
                SetObjective(
                    previousType,
                    previousPosition,
                    float.IsPositiveInfinity(previousRemaining)
                        ? float.PositiveInfinity
                        : now + previousRemaining);
                BotLog(LogLevel.Information,
                    "Bot saiu da area perigosa em {Position}; objetivo {Objective} retomado.",
                    FormatPosition(position),
                    previousType);
                return;
            }

            BotLog(LogLevel.Information,
                "Bot saiu da area perigosa em {Position}; objetivo anterior abandonado.",
                FormatPosition(position));
        }

        private Vector3 FindHazardEscapePoint(Vector3 origin, float now)
        {
            var best = Vector3.zero;
            var bestScore = float.NegativeInfinity;
            for (var radius = 8f; radius <= 24f; radius += 4f)
            {
                for (var step = 0; step < 16; step++)
                {
                    var direction = Quaternion.Euler(0f, step * 22.5f, 0f) * Vector3.forward;
                    var candidate = FindNearestNavigablePoint(origin + direction * radius);
                    if (WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                        || Mathf.Abs(candidate.y - origin.y) > 8f
                        || IsHazardousPosition(candidate, now, 2f))
                    {
                        continue;
                    }

                    var clearance = GetHazardClearance(candidate, now);
                    var displacement = (candidate - origin).GetHorizontalMagnitude();
                    var score = clearance + displacement * 0.15f
                        - Mathf.Abs(candidate.y - origin.y) * 0.5f;
                    if (score > bestScore)
                    {
                        best = candidate;
                        bestScore = score;
                    }
                }
            }

            return bestScore > float.NegativeInfinity
                ? best
                : FindNearestDryNavigablePoint(origin, null);
        }

        private float GetHazardClearance(Vector3 position, float now)
        {
            var clearance = float.PositiveInfinity;
            foreach (var memory in m_HazardMemories)
            {
                if (memory.ExpiresAt <= now)
                {
                    continue;
                }
                clearance = Mathf.Min(
                    clearance,
                    (position - memory.Position).GetHorizontalMagnitude() - memory.Radius);
            }
            return float.IsPositiveInfinity(clearance) ? 100f : clearance;
        }

        private bool IsHazardousPosition(Vector3 position, float now, float margin)
        {
            // 0.2.2t: a live acid puddle of the game is a hazard too.
            if (IsNearAcidBubble(position, margin))
            {
                return true;
            }
            foreach (var memory in m_HazardMemories)
            {
                if (memory.ExpiresAt > now
                    && (position - memory.Position).GetHorizontalMagnitude()
                        <= memory.Radius + margin)
                {
                    return true;
                }
            }
            return false;
        }

        private void PruneHazardMemories(float now)
        {
            for (var index = m_HazardMemories.Count - 1; index >= 0; index--)
            {
                if (m_HazardMemories[index].ExpiresAt <= now)
                {
                    m_HazardMemories.RemoveAt(index);
                }
            }
        }

