            m_Player.transform.position + Vector3.up * 0.5f);
        public EPlayerStance CurrentStance => m_Player.stance.stance;

        public bool HasNearbyNavigationNode(float maximumDistanceMeters)
        {
            if (AstarPath.active == null)
            {
                return false;
            }

            var nearest = AstarPath.active.GetNearest(
                m_Player.transform.position,
                NNConstraint.Walkable);
            return nearest.node != null
                && Vector3.Distance(nearest.position, m_Player.transform.position)
                    <= maximumDistanceMeters;
        }

        public BotNavigationSnapshot GetNavigationSnapshot()
        {
            return new BotNavigationSnapshot(
                m_ObjectiveType.ToString(),
                m_Player.transform.position,
                m_ObjectivePosition,
                m_PathPoints.ToArray(),
                Mathf.Clamp(m_PathIndex, 0, m_PathPoints.Count),
                m_PathPending);
        }

        private void SynchronizePhysicalStateAfterRespawn()
        {
            var originalPosition = m_Player.transform.position;
            var originalStance = m_Player.stance.stance;

            // A real client immediately follows revive with stance and movement
            // state. The fake transport has no client process to send those
            // transitions, so apply and replicate them here.
            m_Player.stance.stance = EPlayerStance.STAND;

            var relocated = TryFindSafeRespawnPosition(
                ChooseRespawnOrigin(originalPosition),
                out var safePosition,
                out var safeArea,
                out var safeGraph);
            if (relocated)
            {
                TeleportBot(safePosition, m_Player.look.yaw);
            }

            m_Player.movement.UpdateCharacterControllerEnabled();
            m_Player.movement.updateMovement();
            m_Player.movement.canAddSimulationResultsToUpdates = true;
            m_Player.movement._isGrounded = false;
            m_Player.movement.ground = default;
            m_Player.movement.checkGround(m_Player.transform.position);

            BotLog(LogLevel.Debug,
                "Fisica pos-renascimento sincronizada: postura {OldStance}->{NewStance}; "
                + "posicao {Original}->{Current}; reposicionado {Relocated}; "
                + "distancia de correcao {RelocationDistance:0.##}m; "
                + "regiao {Area}/grafo {Graph}; grounded {Grounded}; agua {InWater}; "
                + "controller {ControllerEnabled}.",
                originalStance,
                m_Player.stance.stance,
                FormatPosition(originalPosition),
                FormatPosition(m_Player.transform.position),
                relocated,
                (m_Player.transform.position - originalPosition).magnitude,
                safeArea,
                safeGraph,
                m_Player.movement.isGrounded,
                WaterUtility.isPointUnderwater(
                    m_Player.transform.position + Vector3.up * 0.5f),
                m_Player.movement.controller != null
                    && m_Player.movement.controller.enabled);
        }

        // The game picks a random player spawn, sometimes right next to the
        // horde that just killed the bot; respawning unarmed there repeated
        // the death within seconds. Move to the quietest spawn instead.
        private Vector3 ChooseRespawnOrigin(Vector3 spawned)
        {
            var zombiesHere = CountLivingZombiesNear(spawned, RespawnZombieCheckMeters);
            var nearDeath = m_HasLastDeathPosition
                && (spawned - m_LastDeathPosition).GetHorizontalMagnitude() < RespawnAvoidDeathMeters;
            if ((zombiesHere < RespawnMaxZombies && !nearDeath) || LevelPlayers.spawns == null)
            {
                return spawned;
            }

            var bestCount = int.MaxValue;
            var best = new List<Vector3>();
            foreach (var spawn in LevelPlayers.spawns)
            {
                if (spawn == null
                    || spawn.isAlt
                    || WaterUtility.isPointUnderwater(spawn.point + Vector3.up * 0.5f)
                    || (m_HasLastDeathPosition
                        && (spawn.point - m_LastDeathPosition).GetHorizontalMagnitude()
                           < RespawnAvoidDeathMeters))
                {
                    continue;
                }
                var count = CountLivingZombiesNear(spawn.point, RespawnZombieCheckMeters);
                if (count > bestCount)
                {
                    continue;
                }
                if (count < bestCount)
                {
                    bestCount = count;
                    best.Clear();
                }
                best.Add(spawn.point + Vector3.up * 0.5f);
            }
            if (best.Count == 0 || (bestCount >= zombiesHere && !nearDeath))
            {
                return spawned;
            }

            var chosen = best[Random.Range(0, best.Count)];
            BotLog(LogLevel.Information,
                "Renascimento em {Position} tinha {Count} zumbi(s) a {Radius:0}m (perto da morte: {NearDeath}); "
                + "trocando para {Destination} ({NewCount} zumbi(s)).",
                FormatPosition(spawned),
                zombiesHere,
                RespawnZombieCheckMeters,
                nearDeath,
                FormatPosition(chosen),
                bestCount);
            return chosen;
        }

        private static int CountLivingZombiesNear(Vector3 point, float radius)
        {
            var count = 0;
            if (ZombieManager.regions == null)
            {
                return count;
            }
            foreach (var region in ZombieManager.regions)
            {
                if (region?.zombies == null)
                {
                    continue;
                }
                foreach (var zombie in region.zombies)
                {
                    if (zombie != null
                        && !zombie.isDead
                        && (zombie.transform.position - point).GetHorizontalMagnitude() <= radius)
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        private bool TryFindSafeRespawnPosition(
            Vector3 origin,
            out Vector3 safePosition,
            out uint? safeArea,
            out uint? safeGraph)
        {
            safePosition = origin;
            safeArea = null;
            safeGraph = null;
            if (AstarPath.active != null)
            {
                var bestDistanceSquared = float.PositiveInfinity;
                GraphNode? bestNode = null;
                for (var radius = 0f; radius <= 256f; radius += 16f)
                {
                    var steps = radius <= 0f ? 1 : 24;
                    for (var step = 0; step < steps; step++)
                    {
                        var direction = radius <= 0f
                            ? Vector3.zero
                            : Quaternion.Euler(0f, step * (360f / steps), 0f)
                              * Vector3.forward;
                        var probe = origin + direction * radius;
                        var nearest = AstarPath.active.GetNearest(
                            probe,
                            NNConstraint.Walkable);
                        if (nearest.node == null
                            || WaterUtility.isPointUnderwater(
                                nearest.position + Vector3.up * 0.5f)
                            || !m_Player.stance.wouldHaveHeightClearanceAtPosition(
                                nearest.position,
                                0.5f))
                        {
                            continue;
                        }

                        var distanceSquared = (nearest.position - origin).sqrMagnitude;
                        if (distanceSquared >= bestDistanceSquared)
                        {
                            continue;
                        }

                        bestDistanceSquared = distanceSquared;
                        safePosition = nearest.position;
                        bestNode = nearest.node;
                    }
                }

                if (bestNode != null)
                {
                    safeArea = bestNode.Area;
                    safeGraph = bestNode.GraphIndex;
                    return true;
                }
            }

            // Last resort for maps without an A* graph: settle vertically on a
            // dry collision surface instead of leaving the controller suspended.
            if (Physics.Raycast(
                    origin + Vector3.up * 4f,
                    Vector3.down,
                    out var groundHit,
                    512f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore)
                && !WaterUtility.isPointUnderwater(
                    groundHit.point + Vector3.up * 0.5f))
            {
                safePosition = groundHit.point;
                return true;
            }

            return false;
        }

        // One exception used to end the loop for good: thigas stood frozen
        // from 00:35 until a /kill at 01:27 in the 0.1.115 test, and stayed
        // frozen after the respawn. Restart it from a clean objective; only
        // a crash loop (5 in a minute) stops the bot.
        private async UniTaskVoid RunAsync()
        {
            var crashes = new List<float>();
            while (true)
            {
                try
                {
                    await RunCoreAsync();
                    return;
                }
                catch (System.Exception exception)
                {
                    var now = Time.realtimeSinceStartup;
                    crashes.RemoveAll(at => now - at > 60f);
                    crashes.Add(now);
                    var giveUp = crashes.Count >= 5 || !m_Running || m_Player == null;
                    m_Logger.LogError(
                        exception,
                        giveUp
                            ? "Loop principal do bot foi interrompido por uma excecao; objetivo {Objective}; parando o bot."
                            : "Loop principal do bot foi interrompido por uma excecao; objetivo {Objective}; reiniciando em 1s.",
                        m_ObjectiveType);
                    if (giveUp)
                    {
                        m_Running = false;
                        return;
                    }
                    try
                    {
                        ClearPath();
                        ClearObjective();
                    }
                    catch (System.Exception)
                    {
                        // The restart below starts from a fresh objective anyway.
                    }
                }
                await UniTask.Delay(System.TimeSpan.FromSeconds(1));
                if (!m_Running || m_Player == null)
                {
                    return;
                }
            }
        }

        private async UniTask RunCoreAsync()
        {
            await UniTask.DelayFrame(1, PlayerLoopTiming.FixedUpdate);
            if (!m_Running || m_Player == null)
            {
                return;
            }

            if (m_Player.transform.TryGetComponent<Rigidbody>(out var rigidbody))
            {
                Object.Destroy(rigidbody);
            }

            // PlayerInput survives death and can retain packets and a movement
            // correction generated before the respawn teleport. Start this local
            // client from the authoritative post-respawn state.
            m_Player.input.serversidePackets.Clear();
            m_Player.input.clientHasPendingResimulation = false;
            m_Player.movement.velocity = Vector3.zero;
            m_Player.movement.pendingLaunchVelocity = Vector3.zero;

            m_CurrentYaw = m_Player.look.yaw;
            m_DesiredYaw = m_CurrentYaw;
            m_CurrentPitch = m_Player.look.pitch;
            m_DesiredPitch = m_CurrentPitch;
            m_LastStuckCheckPosition = m_Player.transform.position;
            var now = Time.realtimeSinceStartup;
            m_NextStuckCheckTime = now + 2f;
            if (!m_Standby)
            {
                ChooseExplorationObjective(m_Player.transform.position, now);
            }

            while (m_Running && m_Player != null && m_Player.input != null)
            {
                if (!m_Player.life.isDead)
                {
                    UpdateMovementIntent();
                    FadeRecoil();
                    UpdatePostureIntent(Time.realtimeSinceStartup);
                    UpdateBotHome(Time.realtimeSinceStartup);
                    TickPvp(Time.realtimeSinceStartup);
                    if (m_InputFramesRemaining == 0)
                    {
                        CreateClientInputPacket();
                        EnqueueClientInputPacket();
                        m_InputFramesRemaining = PlayerInput.SAMPLES - 1;
                    }
                    else
                    {
                        m_InputFramesRemaining--;
                    }
                }
                else
                {
                    m_IsSprinting = false;
                    ClearObjective();
                }

                if (m_Count % 50 == 0 && m_Player.channel.owner != null)
                {
                    m_Player.channel.owner.lag(1000f / Provider.debugUPS / 1000f);
                }

                m_Count++;
                await UniTask.WaitForFixedUpdate();
            }

            BotLog(LogLevel.Warning,
                "Loop principal do bot encerrou sem excecao: running {Running}; player nulo {PlayerNull}; "
                + "input nulo {InputNull}; presente no Provider {Present}.",
                m_Running,
                m_Player == null,
                m_Player == null || m_Player.input == null,
                m_Player != null && m_Player.channel?.owner != null
                    && Provider.clients.Contains(m_Player.channel.owner));
        }

        private void CreateClientInputPacket()
        {
            // A fake transport has no Unity client to acknowledge corrections.
            // The server is authoritative, so discard the owner-only correction
            // and continue generating input from the current server position.
            if (m_Player.input.clientHasPendingResimulation)
            {
                m_Player.input.clientHasPendingResimulation = false;
            }

            m_Packet = new WalkingPlayerInputPacket
            {
                // 0x12 decodes to X=0/Y=1 in PlayerInput: normal forward input.
                // PlayerInput.FixedUpdate will consume this packet and invoke the
                // same PlayerMovement.simulate path used for a real client.
                analog = GetCurrentMovementAnalog(),
                clientPosition = m_Player.transform.position,
                pitch = GetSentPitch(),
                yaw = GetSentYaw(),
                clientSimulationFrameNumber = m_Player.input.simulation,
                recov = m_Player.input.recov
            };
            ConfigureCombatInput((WalkingPlayerInputPacket)m_Packet);
            ConfigureBedInput((WalkingPlayerInputPacket)m_Packet);
        }

        private void EnqueueClientInputPacket()
        {
            if (m_Packet is WalkingPlayerInputPacket walkingPacket)
            {
                walkingPacket.clientPosition = m_Player.transform.position;
                walkingPacket.pitch = GetSentPitch();
                walkingPacket.yaw = GetSentYaw();
                walkingPacket.analog = GetCurrentMovementAnalog();
                walkingPacket.clientSimulationFrameNumber =
                    m_Player.input.simulation
                    + (uint)m_Player.input.serversidePackets.Count;
                AttachGunHits(walkingPacket);
            }

            ushort keys = 0;
            // x18: out of breath, the key stays up until 50 (SkaliaBotStaminaX18).
            var staminaRecovering = IsStaminaRecovering();
            if (m_IsSprinting && !staminaRecovering)
            {
                keys |= m_Player.input.flags[5];
            }
            // 0.1.0-y17.27: a fight's sprint hops like the players' (SkaliaBotMoveFeelY).
            TickPvpRunHops(m_IsSprinting && !staminaRecovering);
            var swimming = m_Player.stance.stance == EPlayerStance.SWIM;
            var climbingOut = swimming
                && m_ObjectiveType == ObjectiveType.ExitWater
                && m_SwimExitActive
                && (m_ObjectivePosition - m_Player.transform.position).GetHorizontalMagnitude() <= 3.5f;
            if (m_LocalRecoveryJump
                || climbingOut
                || (m_SwarmEscapeActive
                    && Time.realtimeSinceStartup < m_SwarmJumpUntil)
                || Time.realtimeSinceStartup < m_NavigationJumpUntil)
            {
                keys |= m_Player.input.flags[0];
                // A swimmer at the surface ignores jump unless diving (looking
                // more than 20 degrees down); then jump pushes up at 3 m/s,
                // which is how a player climbs onto the bank.
                if (swimming && m_Packet is WalkingPlayerInputPacket swimPacket)
                {
                    swimPacket.pitch = 120f;
                }
            }
            // 0.2.2x14: under the surface on a long swim (SkaliaBotSwimX14).
            if (m_Packet is WalkingPlayerInputPacket divePacket)
            {
                ApplySwimDive(divePacket, ref keys, climbingOut || m_LocalRecoveryJump);
            }
            // x16: a climb starts only from standing (SkaliaBotLadderX15).
            var ladderStand = LadderNeedsStanding();
            if ((m_StealthCrouch || m_MegaSneakCrouch || IsShortcutCrouching(Time.realtimeSinceStartup))
                && !ladderStand
                && !m_IsSprinting
                && !swimming
                && (keys & m_Player.input.flags[0]) == 0)
            {
                keys |= m_Player.input.flags[3];
            }
            else if (m_PostureKey != 0
                     && !ladderStand
                     && !m_IsSprinting
                     && !swimming
                     && (keys & m_Player.input.flags[0]) == 0)
            {
                // 0.2.0: prone or crouched like a player (UpdatePostureIntent).
                keys |= m_Player.input.flags[m_PostureKey == 2 ? 4 : 3];
            }
            m_Packet.keys = keys;

            var writer = NetMessages.GetInvokableWriter();
            writer.Reset();
            m_Packet.write(writer);
            writer.Flush();

            var reader = NetMessages.GetInvokableReader();
            reader.SetBufferSegment(writer.buffer, writer.writeByteIndex);
            reader.Reset();
            m_Packet.read(m_Player.channel, reader);
            m_Player.input.serversidePackets.Enqueue(m_Packet);
            if (m_Packet is WalkingPlayerInputPacket diagnosticPacket)
            {
                SkaliaBotMovementDiagnostics.RecordEnqueued(
                    m_Player,
                    diagnosticPacket,
                    m_Player.input.serversidePackets.Count);
            }
        }

        private void UpdateMovementIntent()
        {
            // Even in standby the fake client must complete the neutral physical
            // handshake after respawn. Otherwise the simulation advances, but the
            // confirmation gate is never evaluated and diagnostics report a false
            // desync merely because the bot was intentionally stationary.
            var now = Time.realtimeSinceStartup;
            if (m_AwaitingRespawnPhysics
                && !TryConfirmRespawnPhysics(now))
            {
                m_IsWalking = false;
                m_IsSprinting = false;
                m_PrimaryAttackHeld = false;
                m_SecondaryAttackHeld = false;
                m_DesiredYaw = m_CurrentYaw;
                m_DesiredPitch = 90f;
                if (!m_Standby)
                {
                    LogPeriodicStatus(m_Player.transform.position, now);
                }
                return;
            }

            if (m_Standby)
            {
                m_IsWalking = false;
                m_IsSprinting = false;
                m_PrimaryAttackHeld = false;
                m_SecondaryAttackHeld = false;
                m_DesiredYaw = m_CurrentYaw;
                m_DesiredPitch = 90f;
                return;
            }

            if (!m_MovementEnabled
                || m_Player.stance.stance == EPlayerStance.SITTING
                || m_Player.stance.stance == EPlayerStance.DRIVING)
            {
                m_IsWalking = false;
                m_IsSprinting = false;
                return;
            }

            var position = m_Player.transform.position;
            if (m_LocalRecoveryPhase != LocalRecoveryPhase.None)
            {
                UpdateLocalRecovery(position, now);
                LogPeriodicStatus(position, now);
                return;
            }
            if (m_ObjectiveType != ObjectiveType.Ladder && m_Ladder != null)
            {
                m_Ladder = null;
                m_LadderPhase = 0;
                m_LadderDown = false;
            }
            if (m_ObjectiveType == ObjectiveType.Ladder && UpdateLadderClimb(position, now))
            {
                LogPeriodicStatus(position, now);
                return;
            }

            RecoverTimedOutPath(now);
            UpdateState(position, now);
            LogPeriodicStatus(position, now);
            if (UpdateBoulderDodge(position))
            {
                return;
            }
            // 0.2.2x11: never standing among zombies (SkaliaBotCrowdDodgeX11).
            if (UpdateCrowdDodge(position, now))
            {
                return;
            }
            if (m_TreatmentPhase != 0
                && !m_TreatmentIsMeal
                && m_CachedNearestZombieDistance > 8f
                && m_CachedNearestBossDistance > BossTreatmentRunMeters
                && IsTreatmentStopSafe()
                && ShouldStopForTreatment(position))
            {
                // Like a player: stop running to put the bandage on while the
                // zombies are still a few seconds away. 0.1.170: not with the
                // Mega within 40m (under 7s at its 6 m/s): Tadeu stood still
                // for a rag and a vaccine with it 9m away and it was on him.
                m_IsWalking = false;
                m_IsSprinting = false;
                return;
            }
            // 0.2.2x8 (doc 16.16): the route passes the Mega; wait crouched.
            if (IsMegaRouteHolding())
            {
                m_IsWalking = false;
                m_IsSprinting = false;
                return;
            }
            var isFleeingPlayer = m_ObjectiveType == ObjectiveType.Flee;
            var combatDistance = GetCombatDistance(position);
            var combatAttackDistance = GetCombatAttackDistance();
            UpdateOtherFloorTarget(position, now);
            var otherFloorRoute = m_FloorRouteActive && IsCombatTargetOnOtherFloor(position);
            var hasCombatLineOfSight = IsTargetZombieAlive()
                && !otherFloorRoute
                && HasCombatShotLine(m_TargetZombie!);
            NoteCombatLineOfSight(hasCombatLineOfSight, now);
            UpdateCombatMovementPhase(combatDistance, combatAttackDistance, now);
            var preparingRangedAttack = m_ObjectiveType == ObjectiveType.Combat
                && IsTargetZombieAlive()
                && m_Player.equipment.asset is ItemGunAsset equippedGun
                && IsEquippedGunLoaded(equippedGun)
                && combatDistance <= combatAttackDistance + 1.5f
                // x19: with no shot line the route walks on until it opens.
                && now - m_TryhardTargetSeenAt <= CombatShotLineGraceSeconds;
            // Going after a zombie still far away is walking a route like any
            // other: corners reached at 0.3m, a new route off the line or when
            // stuck. The combat steering, which picks a "safe" direction every
            // few tenths of a second and knows nothing of the route's corners,
            // only takes over close to it. In the 0.1.135 test 43 "no safe
            // direction" stops and 42 of 81 physical recoveries were in fights.
            m_CombatByRoute = m_ObjectiveType == ObjectiveType.Combat
                && IsTargetZombieAlive()
                && !preparingRangedAttack
                && !IsTryhardMegaGunFight(hasCombatLineOfSight)
                && m_CombatMovementPhase != CombatMovementPhase.Retreat
                && (combatDistance > CombatRouteApproachMeters || now < m_CombatForceRouteUntil)
                && HasMeshRoute();
            if (m_CombatByRoute)
            {
                m_CombatShouldSprint = combatDistance > ChasedSprintMeters;
            }
            m_IsSprinting = !preparingRangedAttack
                && (m_ObjectiveType == ObjectiveType.Loot
                || isFleeingPlayer
                || m_ObjectiveType == ObjectiveType.EscapeHazard
                || m_ObjectiveType == ObjectiveType.RepositionFire
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || ShouldSprintWhileTraveling());
            // A sprinting player outruns zombies: a bot with one coming after
            // it never walks away from it. In the 0.1.123 test bots dropped a
            // fight and walked off on patrol with the zombie 3-6m behind; 6
            // of 8 deaths were hits in the back.
            // 0.1.173: marked zombies after the bot count too, and a burner
            // after it within 30m: it walks at 5.5 m/s, faster than a bot
            // walking (4.5), so only sprinting gains ground.
            var chasedMeters = Mathf.Min(GetNearestAggroedZombieDistance(), m_ThreatNearestHunterDistance);
            var chased = (chasedMeters < ChasedSprintMeters
                          || m_ThreatHuntingFireDistance < FireFleeHuntingMeters)
                && m_ObjectiveType != ObjectiveType.Combat
                && m_Player.stance.stance != EPlayerStance.SWIM;
            if (m_ObjectiveType == ObjectiveType.Loot
                && !chased
                && (m_ObjectivePosition - position).GetHorizontalMagnitude() < LootSlowDownMeters)
            {
                // Nobody sprints the last steps to an item on the floor.
                m_IsSprinting = false;
            }
            if (chased && !preparingRangedAttack)
            {
                m_IsSprinting = true;
            }

            // 0.2.2: shortcuts of the mesh round the bot (SkaliaBotShortcutLinks).
            TickShortcutScan(position, now);
            var navigationTarget = position;
            if (m_ObjectiveType != ObjectiveType.None)
            {
                if (IsSwimEntryLeg(position))
                {
                    // The walking mesh ends at the bank: straight into the water.
                    m_DirectFallbackUntil = now + 0.5f;
                }
                navigationTarget = GetNavigationTarget(position, now);
                if (m_HasKnownInteriorExit
                    && now < m_KnownInteriorExitExpiresAt
                    && ((m_ObjectiveType == ObjectiveType.Combat
                         && (m_CombatMovementPhase == CombatMovementPhase.Retreat
                             || !hasCombatLineOfSight))
                        || m_ObjectiveType == ObjectiveType.EscapeSwarm))
                {
                    navigationTarget = m_KnownInteriorExit;
                    m_DirectFallbackUntil = now + 1.25f;
                }
                var directObjective = m_ObjectivePosition - position;
                directObjective.y = 0f;
                var directDistance = directObjective.magnitude;
                if (m_ObjectiveType != ObjectiveType.Unstuck
                    && m_ObjectiveType != ObjectiveType.ExitWater
                    && !otherFloorRoute
                    && directDistance > 1f
                    && now >= m_ShortcutSuppressedUntil
                    && !HasMeshRoute()
                    && now >= m_RouteCommitUntil
                    && TryFindTraversableOpening(
                        position,
                        directObjective / directDistance,
                        Mathf.Min(8f, directDistance),
                        out var shortcutDistance)
                    && IsShortcutWorthIt(position, directObjective / directDistance, shortcutDistance, directDistance, now))
                {
                    // Route graphs generally omit windows and fences. Override
                    // the next graph corner with a short physical traversal.
                    navigationTarget = position
                        + directObjective / directDistance * (shortcutDistance + 1.7f);
                    m_DirectFallbackUntil = now + 1.5f;
                }
                if (m_ObjectiveType != ObjectiveType.Unstuck
                    && m_ObjectiveType != ObjectiveType.ExitWater
                    && now >= m_RouteCommitUntil)
                {
                    navigationTarget = ApplyFurnitureDetour(position, navigationTarget, now);
                }
                navigationTarget = ApplyWallAvoidance(
                    position,
                    navigationTarget,
                    m_ObjectivePosition,
                    now);
                if (now < m_FollowSideUntil && IsMeshFollowing())
                {
                    navigationTarget = m_FollowSideTarget;
                }
                var objectiveDirection = navigationTarget - position;
                objectiveDirection.y = 0f;
                // 0.2.2x (doc 15.2, item 14): a route point 10-50cm away
                // changes direction at every step and spun the tryhard on
                // the spot; it turns only to a point 1m or more away, and
                // holds its heading while it stands for a bandage or after
                // a spin.
                var routeYawMinimum = Tryhard ? 1f : 0.01f;
                var holdHeading = Tryhard
                    && (IsSpinHeld(now) || (m_TreatmentPhase != 0 && !m_IsWalking));
                if (objectiveDirection.sqrMagnitude > routeYawMinimum && !holdHeading)
                {
                    m_DesiredYaw = DirectionToYaw(objectiveDirection);
                }
            }

            var steeringAimTarget = (m_ObjectiveType == ObjectiveType.Combat
                 || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                && IsTargetZombieAlive()
                && !m_WallAvoidanceActive
                && !m_CombatByRoute
                && hasCombatLineOfSight;
            if (steeringAimTarget)
            {
                var aimDirection = (m_Player.equipment.asset is ItemGunAsset
                        ? GetGunSteerPoint(m_TargetZombie!)
                        : GetMeleeAimPoint(m_TargetZombie!))
                    - m_Player.look.aim.position;
                var horizontalAim = aimDirection;
                horizontalAim.y = 0f;
                if (horizontalAim.sqrMagnitude > 0.001f)
                {
                    // Combat aim overrides the route heading once a target exists.
                    m_DesiredYaw = DirectionToYaw(horizontalAim);
                }
                var horizontalDistance = new Vector2(aimDirection.x, aimDirection.z).magnitude;
                m_DesiredPitch = 90f
                    - Mathf.Atan2(aimDirection.y, Mathf.Max(0.01f, horizontalDistance))
                    * Mathf.Rad2Deg;
            }
            else if (m_ObjectiveType == ObjectiveType.Loot
                     && TryGetTargetLoot(out var aimedLoot)
                     && !m_WallAvoidanceActive
                     && IsLootLookWanted(aimedLoot)
                     && HasLootLineOfSight(aimedLoot.point)
                     && (aimedLoot.point - position).GetHorizontalMagnitude()
                        <= Mathf.Max(m_LootPickupDistanceMeters, LootSightReachMeters) * 1.2f)
            {
                var aimDirection = aimedLoot.point + Vector3.up * 0.15f
                    - m_Player.look.aim.position;
                var horizontalAim = new Vector3(aimDirection.x, 0f, aimDirection.z);
                if (horizontalAim.sqrMagnitude > 0.001f)
                {
                    m_DesiredYaw = DirectionToYaw(horizontalAim);
                }
                var horizontalDistance = new Vector2(aimDirection.x, aimDirection.z).magnitude;
                m_DesiredPitch = 90f
                    - Mathf.Atan2(aimDirection.y, Mathf.Max(0.01f, horizontalDistance))
                    * Mathf.Rad2Deg;
            }
            else if (now < m_LootLingerUntil
                     && m_ObjectiveType != ObjectiveType.Combat
                     && m_ObjectiveType != ObjectiveType.EscapeSwarm
                     && m_ObjectiveType != ObjectiveType.Flee
                     && m_ObjectiveType != ObjectiveType.EscapeHazard
                     && !chased)
            {
                m_DesiredYaw = m_LootLingerYaw;
                m_DesiredPitch = m_LootLingerPitch;
            }
            else if (TryGetOverlookLook(now, out var overlookYaw, out var overlookPitch))
            {
                m_DesiredYaw = overlookYaw;
                m_DesiredPitch = overlookPitch;
            }
            else
            {
                if (now >= m_NextWalkPitchAt)
                {
                    // 0.2.2x1 (doc 16.2, 16.3 item 8): the players walk
                    // looking about 21 degrees down (2-43, spread 16); the bots
                    // kept 4 (spread 6), "durasso olhando reto". Drawn from
                    // the players' spread every 2-6s; the turn eases there.
                    m_NextWalkPitchAt = now + Random.Range(2f, 6f);
                    m_WalkPitchOffset = DrawPlayerWalkPitch();
                }
                m_DesiredPitch = 90f + m_WalkPitchOffset;
            }

            // 0.2.2x (doc 15.2, item 8): backing off from a target it will
            // shoot again, the tryhard faces it; the 8-way step walks it
            // backwards or sideways to the escape point.
            if (!steeringAimTarget && TryGetRetreatFacing(position, now, out var retreatAim))
            {
                var retreatDirection = retreatAim - m_Player.look.aim.position;
                var retreatHorizontal = new Vector3(retreatDirection.x, 0f, retreatDirection.z);
                if (retreatHorizontal.sqrMagnitude > 0.001f)
                {
                    m_DesiredYaw = DirectionToYaw(retreatHorizontal);
                    m_DesiredPitch = 90f
                        - Mathf.Atan2(retreatDirection.y, Mathf.Max(0.01f, retreatHorizontal.magnitude))
                        * Mathf.Rad2Deg;
                }
            }

            if (!m_CombatByRoute)
            {
                UpdateCombatSteering(
                    position,
                    navigationTarget,
                    combatDistance,
                    combatAttackDistance,
                    now);
            }
            if ((m_ObjectiveType == ObjectiveType.Combat
                 || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                && IsTargetZombieAlive())
            {
                m_IsSprinting = m_CombatShouldSprint && !preparingRangedAttack;
            }
            if (m_StealthCrouch || m_MegaSneakWalk || IsShortcutCrouching(now))
            {
                m_IsSprinting = false;
            }

            // 0.2.0: short stops, glances, sprint bursts and hops on the way
            // (SkaliaBotPlayerHabits).
            UpdatePlayerHabits(position, navigationTarget, now, chased, steeringAimTarget);
            if (m_MegaSneakWalk)
            {
                // 0.2.2u: no sprint burst within 30m of a Mega that has not
                // seen the bot (a sprinting player is noticed at 22m).
                m_IsSprinting = false;
            }

            // 0.2.2x7 (doc 16.13.1): after a kill the gaze stays on the body
            // for a moment and the bot keeps stepping; a new target ends it.
            if (steeringAimTarget)
            {
                EndPostKillLook();
            }
            else
            {
                ApplyPostKillLook(position, now);
            }

            var aimingTurn = steeringAimTarget;
            // 0.2.2: up close the hand follows the zombie (ApplyCloseAimTracking).
            var closeTrack = aimingTurn && ApplyCloseAimTracking(position);
            m_CurrentYaw = Mathf.MoveTowardsAngle(
                m_CurrentYaw,
                m_DesiredYaw,
                (closeTrack
                    ? GetCloseTrackTurnSpeed(Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, m_DesiredYaw)))
                    : ApplyTurnRamp(
                        GetHumanTurnSpeed(Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, m_DesiredYaw)), aimingTurn),
                        Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, m_DesiredYaw)),
                        aimingTurn))
                * TurnStepSeconds);
            // 0.2.2x11 (the tester): lying down the gaze stays level, not tilted
            // at the ground (the x10 recordings had 110-135 prone); only the
            // aim at a zombie goes a little lower.
            if (m_Player.stance.stance == EPlayerStance.PRONE)
            {
                m_DesiredPitch = Mathf.Min(m_DesiredPitch, aimingTurn ? ProneAimMaxPitch : ProneMaxPitch);
            }
            m_CurrentPitch = Mathf.MoveTowardsAngle(
                m_CurrentPitch,
                m_DesiredPitch,
                (closeTrack
                    ? GetCloseTrackTurnSpeed(Mathf.Abs(Mathf.DeltaAngle(m_CurrentPitch, m_DesiredPitch)))
                    : GetHumanTurnSpeed(Mathf.Abs(Mathf.DeltaAngle(m_CurrentPitch, m_DesiredPitch)), aimingTurn) * 0.7f)
                * TurnStepSeconds);
            if (closeTrack)
            {
                ClampCloseTrackStep();
            }
            m_CurrentPitch = Mathf.Clamp(m_CurrentPitch, 0.5f, 179.5f);

            UpdateNavigationAnalog(position, navigationTarget);
            var movementAnalog = (m_ObjectiveType == ObjectiveType.Combat
                                  || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                                 && IsTargetZombieAlive()
                                 && !m_CombatByRoute
                ? m_CombatMovementAnalog
                : m_NavigationAnalog;
            var movementDirection = GetWorldMovementDirection(
                movementAnalog,
                m_CurrentYaw);
            var facingTraversableObstacle = movementDirection.sqrMagnitude > 0.01f
                && ShouldJumpTraversableObstacle(
                position,
                movementDirection);
            var following = IsMeshFollowing();
            var facingSolidWall = !following
                && !facingTraversableObstacle
                && movementDirection.sqrMagnitude > 0.01f
                && IsBodyRouteBlocked(position, movementDirection, 1.05f);

            var replanningObstacle = false;
            if (!following
                && m_PathPoints.Count > 0
                && !m_PathPending
                && m_RouteHopIndex < 0
                && now >= m_NextObstacleProbeTime)
            {
                m_NextObstacleProbeTime = now + 0.2f;
                var routeDirection = navigationTarget - position;
                routeDirection.y = 0f;
                var routeDistance = routeDirection.magnitude;
                var obstacleDetected = routeDistance > 0.1f
                    && IsPathBlocked(
                        position,
                        routeDirection / routeDistance,
                        Mathf.Min(routeDistance, m_ObstacleCheckDistanceMeters));

                if (!obstacleDetected)
                {
                    m_ObstacleDetectedAt = 0f;
                }
                else if (m_ObstacleDetectedAt <= 0f)
                {
                    m_ObstacleDetectedAt = now;
                }
                else if (now - m_ObstacleDetectedAt >= ObstacleConfirmationSeconds
                         && now >= m_NextObstacleReplanTime)
                {
                    var obstacleDuration = now - m_ObstacleDetectedAt;
                    m_NextObstacleReplanTime = now + ObstacleReplanCooldownSeconds;
                    m_ObstacleDetectedAt = 0f;
                    replanningObstacle = true;
                    if ((position - m_LastObstacleReplanPosition)
                            .GetHorizontalMagnitude() <= 2f)
                    {
                        m_ObstacleReplanAttempts++;
                    }
                    else
                    {
                        m_ObstacleReplanAttempts = 1;
                    }
                    m_LastObstacleReplanPosition = position;

                    if (m_ObstacleReplanAttempts >= 2)
                    {
                        BotLog(LogLevel.Debug,
                            "Rota permaneceu bloqueada apos uma recalculacao no ponto {Position}; entrando em recuperacao local.",
                            FormatPosition(position));
                        m_ObstacleReplanAttempts = 0;
                        EnterUnstuckState(position, now);
                    }
                    else
                    {
                        BotLog(LogLevel.Information,
                            "Obstaculo persistiu por {Duration:0.0}s na rota {PathIndex}/{PathCount}, estado {State}; fazendo uma unica recalculacao.",
                            obstacleDuration,
                            m_PathIndex + 1,
                            m_PathPoints.Count,
                            m_ObjectiveType);
                        ClearPath();
                    }
                }
            }

            // Stop inside punching range, otherwise continue applying forward
            // input while turning so obstacle handling cannot lock rotation.
            var lootSettled = m_ObjectiveType == ObjectiveType.Loot
                && UpdateLootSettled(position, navigationTarget, now);
            m_IsWalking = !replanningObstacle
                && !m_WallMovementBlocked
                && !facingSolidWall
                && m_ObjectiveType != ObjectiveType.None
                && !(m_PathPending && m_PathPoints.Count == 0)
                && !m_NavigationHold
                && !lootSettled
                && ((m_ObjectiveType != ObjectiveType.Combat
                     && m_ObjectiveType != ObjectiveType.EscapeSwarm)
                    || !IsTargetZombieAlive()
                    // x19: going by the route the steering is not run, and
                    // its last "stand and shoot" (0x11, left from the tick
                    // the gun was still in hand) held the bot still with the
                    // knife out: 98 stops in Combat in the x18 test, 4s
                    // each until the no-progress check dropped the fight.
                    || m_CombatByRoute
                    || m_CombatMovementAnalog != 0x11);
            // 0.2.2w (doc 14.3, item 7): between one objective and the next
            // (1035 changes in 32 min) and while a route is computed, the
            // bot stopped dead for a moment. Like a player it keeps going the
            // way it was for up to half a second, on open ground only.
            var coasting = Tryhard
                && !m_IsWalking
                && now < m_CoastUntil
                && !replanningObstacle
                && !m_WallMovementBlocked
                && !facingSolidWall
                && !lootSettled
                && (m_ObjectiveType == ObjectiveType.None
                    || (m_PathPending && m_PathPoints.Count == 0)
                    || (m_NavigationHold && m_NavigationHoldMayCoast))
                && m_CachedNearestZombieDistance > 6f
                && m_Player.stance.stance != EPlayerStance.SWIM
                && position.y - LevelGround.getHeight(position) < 1.5f;
            if (coasting)
            {
                m_IsWalking = true;
            }
            else if (m_IsWalking && m_ObjectiveType != ObjectiveType.None)
            {
                m_CoastUntil = now + TryhardCoastSeconds;
            }

            // Turning at 120 deg/s, a walking bot circles any point closer than
            // ~2m off its heading (sprinting, ~3.4m) and never reaches it: turn
            // first, then walk.
            var steeringByAim = (m_ObjectiveType == ObjectiveType.Combat
                                 || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                && IsTargetZombieAlive();
            if ((now < m_ThinkUntil || now < m_LootLingerUntil || IsHabitPaused(now))
                && !steeringByAim
                && !chased
                && m_ObjectiveType != ObjectiveType.Flee
                && m_ObjectiveType != ObjectiveType.EscapeHazard
                && m_Player.stance.stance != EPlayerStance.SWIM)
            {
                m_IsWalking = false;
                m_IsSprinting = false;
            }
            if (m_IsWalking && following)
            {
                ApplyFollowerPace(position, navigationTarget);
            }
            else if (m_IsWalking && !steeringByAim && m_Player.stance.stance != EPlayerStance.SWIM)
            {
                var toNavigation = navigationTarget - position;
                toNavigation.y = 0f;
                var navigationDistance = toNavigation.magnitude;
                if (navigationDistance > 0.1f)
                {
                    var turn = Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, DirectionToYaw(toNavigation)));
                    // A bot walking while it turns at a fixed rate moves on a
                    // circle of radius speed/turn rate. A point closer than
                    // 2r*sin(turn) can never be reached: the bot goes round it
                    // and the bearing stays the same, so a fixed 70 degree
                    // limit never fired. That orbit was the bulk of the
                    // "nothing ahead" circles. Stop and turn when the point
                    // is inside the circle, slow down when only the sprint
                    // circle misses it.
                    // 0.1.170: the turn is no longer a fixed 120 deg/s (see
                    // GetHumanTurnSpeed) and the 8-way step walks toward the
                    // point while the body turns. Stopping at every corner
                    // over 70 degrees within 10m made the stop-turn-go walk
                    // of the 0.1.169 test; only a point close behind stops it.
                    var turnRate = Mathf.Max(m_TurnSpeedDegreesPerSecond, GetHumanTurnSpeed(turn, false));
                    var turnRadians = turnRate * Mathf.Deg2Rad;
                    var sine = Mathf.Sin(Mathf.Min(turn, 90f) * Mathf.Deg2Rad);
                    var walkMiss = 2f * (WalkSpeedEstimate / turnRadians) * sine + OrbitReachMargin;
                    var sprintMiss = 2f * (SprintSpeedEstimate / turnRadians) * sine + OrbitReachMargin;
                    if (((turn > 110f && navigationDistance < 4f) || navigationDistance < walkMiss)
                        && chased)
                    {
                        // Stopping to turn lets the chaser catch up: turn
                        // at walking pace instead.
                        m_IsSprinting = false;
                    }
                    else if ((turn > 110f && navigationDistance < 4f) || navigationDistance < walkMiss)
                    {
                        // 0.2.2w (doc 14.3, item 7): the tryhard does not stop
                        // to turn; the 8-way step already walks to the point
                        // while the body turns (stop, turn, go was the
                        // stiffest part of its walk).
                        if (!Tryhard)
                        {
                            m_IsWalking = false;
                        }
                        m_IsSprinting = false;
                    }
                    else if ((turn > 45f && navigationDistance < 6f) || navigationDistance < sprintMiss)
                    {
                        m_IsSprinting = false;
                    }
                }
            }
            UpdateOrbitDetector(position, navigationTarget, now);
            UpdateFollowerProgress(position, following, now);

            if (m_IsWalking
                && m_Player.movement.isGrounded
                && now >= m_NextNavigationJumpAt)
            {
                var jumpDirection = navigationTarget - position;
                jumpDirection.y = 0f;
                if (jumpDirection.sqrMagnitude > 0.25f
                    && (ShouldJumpTraversableObstacle(position, jumpDirection.normalized)
                        || TryBarJump(position, jumpDirection, jumpDirection.magnitude, now)
                        || TryContactJump(position, GetWorldMovementDirection(movementAnalog, m_CurrentYaw), now)))
                {
                    m_NavigationJumpUntil = now + 0.55f;
                    m_NextNavigationJumpAt = now + 1.2f;
                    BotLog(LogLevel.Debug,
                        "Bot detectou janela ou obstaculo transponivel e iniciou salto em {Position}.",
                        FormatPosition(position));
                }
            }

            if (now >= m_NextStuckCheckTime)
            {
                // The follower has its own steps for a block (jump, side
                // step, new route); the 20s stall watchdog stays behind it.
                if ((position - m_LastStuckCheckPosition).GetHorizontalMagnitude() < 0.4f
                    && m_IsWalking
                    && !following)
                {
                    m_ConsecutiveStuckChecks++;
                    if (m_ConsecutiveStuckChecks >= 3)
                    {
                        if (m_Player.stance.stance == EPlayerStance.SWIM)
                        {
                            EnterUnstuckState(position, now);
                        }
                        else
                        {
                            EnterUnstuckState(position, now);
                        }
                    }
                }
                else
                {
                    m_ConsecutiveStuckChecks = 0;
                }

                m_LastStuckCheckPosition = position;
                m_NextStuckCheckTime = now + 2f;
            }
        }

        private bool TryConfirmRespawnPhysics(float now)
        {
            var currentSimulation = m_Player.input.simulation;
            var currentPosition = m_Player.transform.position;
            var displacement = currentPosition - m_RespawnPhysicsStartPosition;
            var simulationAdvanced = currentSimulation != m_RespawnPhysicsStartSimulation;
            var physicalResultObserved = m_Player.movement.isGrounded
                || displacement.sqrMagnitude > 0.0001f;

            if (simulationAdvanced && physicalResultObserved)
            {
                m_AwaitingRespawnPhysics = false;
                NoteAreaProgress(now);
                m_LastStuckCheckPosition = currentPosition;
                m_NextStuckCheckTime = now + 2f;
                BotLog(LogLevel.Debug,
                    "Primeiro tick fisico pos-renascimento confirmado: simulacao {Before}->{After}; "
                    + "deslocamento {Displacement:0.####}m; variacao vertical {Vertical:0.####}m; "
                    + "grounded {Grounded}. Selecionando objetivo agora.",
                    m_RespawnPhysicsStartSimulation,
                    currentSimulation,
                    displacement.magnitude,
                    displacement.y,
                    m_Player.movement.isGrounded);
                ChooseExplorationObjective(currentPosition, now);
                return true;
            }

            if (now >= m_RespawnPhysicsRetryAt)
            {
                BotLog(LogLevel.Warning,
                    "Tick fisico pos-renascimento ainda nao confirmado: simulacao {Before}->{After}; "
                    + "deslocamento {Displacement:0.####}m; grounded {Grounded}; fila {Queue}. "
                    + "Reiniciando somente o produtor de entradas neutras.",
                    m_RespawnPhysicsStartSimulation,
                    currentSimulation,
                    displacement.magnitude,
                    m_Player.movement.isGrounded,
                    m_Player.input.serversidePackets.Count);
                m_Player.input.serversidePackets.Clear();
                SkaliaBotMovementDiagnostics.ResetPending(m_Player);
                m_Packet = new PlayerInputPacket();
                m_InputFramesRemaining = 0;
                m_RespawnPhysicsStartSimulation = currentSimulation;
                m_RespawnPhysicsStartPosition = currentPosition;
                m_RespawnPhysicsRetryAt = now + 2f;
            }

            return false;
        }

        private void UpdateState(Vector3 position, float now)
        {
            TryTreatWounds(now);
            TryOpenNearbyDoor(position, now);
            // 0.2.2y: the gun in hand while shooting back at a player is the
            // fight's (ConfigurePvpInput). The gear work swaps, holsters,
            // drops and moves weapons between slots, and would take it out
            // of his hands mid-fight.
            // 0.2.2y3: and while the fight is on, out of sight too (seen or
            // hit in the last 10s): Ghost stripped an Eaglefire with the tester
            // at 15m (17/11 01:20:00) and was left with his fists.
            // 0.2.2y5: while he is remembered (a minute), not only 10s:
            // in the bot fight of 17/11 at the military base (03:10-03:15)
            // Vultox and LilJuninho tore 9 pieces of clothing into rags
            // 15-40s after seeing each other, and Vultox took a Sabertooth
            // with 1 round to hand mid-fight.
            var pvpActive = IsPvpActive(now) || m_PvpTarget != null;
            if (!IsPvpEngaged())
            {
                // Filling magazines from a crate out of his sight is what a
                // player does between exchanges: only the 10s are kept.
                if (!IsPvpActive(now))
                {
                    TryRefillMagazines(now);
                }
                if (!pvpActive)
                {
                    UpdateGearWork(now);
                }
                TryReloadWhenSafe(now);
                UpdateWeaponInHand(now);
            }
            UpdateSpinWatch(m_Player.transform.position, now);
            if (!IsPvpEngaged() && !pvpActive)
            {
                UpdateMegaApproachGun(m_Player.transform.position, now);
                TrySpendSkillPoints(now);
                DropWeakerMelee(now);
                DropWeakerGun(now);
                ArrangeWeaponSlots(now);
                WearBetterBags(now);
                WearBetterHeadgear(now);
                TakeOffUselessHeadgear(now);
                HolsterIdleMelee(now);
                DropExtraItems(now);
            }
            MarkPassedPatrolPoints(position, now);
            RecordBreadcrumb(position, now);
            CheckTeleportLanded(now);
            if (!IsPvpEngaged())
            {
                DiscardEmptyMagazines(now);
            }
            UpdatePendingLootObservations(now);
            if (now >= m_NextLootMemoryScanTime)
            {
                m_NextLootMemoryScanTime = now + 2f;
                ObserveNearbyLoot(position, now);
            }
            if (m_PathFailed && m_PathRejectedByBadSpot)
            {
                // Only this destination is skipped: the generic failure below
                // drops the whole area or treats the bot as stuck in a pocket.
                m_PathFailed = false;
                m_PathRejectedByBadSpot = false;
                if (m_ObjectiveType == ObjectiveType.Loot && m_LootInstanceId != 0)
                {
                    IgnoreLoot(m_LootInstanceId, now + OrbitBadSpotSeconds);
                    m_NextLootScanTime = now + 0.75f;
                }
                else if (m_ObjectiveType == ObjectiveType.Patrol
                         && m_PatrolTargetSet
                         && (m_ObjectivePosition - m_PatrolTargetPoint).GetHorizontalMagnitude() < 1f)
                {
                    NotePatrolPointFailed(m_PatrolTargetPoint, now, "rota passa onde um bot travou", false);
                    m_PatrolTargetSet = false;
                }
                else if (m_ObjectiveType == ObjectiveType.Explore)
                {
                    BlacklistCurrentExplorationDestination(now, m_LastPathFailureReason);
                }
                ClearObjective();
                return;
            }
            m_PathRejectedByBadSpot = false;
            if (m_PathFailed)
            {
                m_PathFailed = false;
                var failedObjective = m_ObjectiveType;
                if (failedObjective == ObjectiveType.Travel)
                {
                    if (m_TravelPhase == 1)
                    {
                        BeginTerrainLeg(position, now, "rota ate a borda falhou");
                    }
                    m_PathPoints.Clear();
                    m_PathIndex = 0;
                    m_PathPending = false;
                    return;
                }
                if (failedObjective == ObjectiveType.Explore)
                {
                    BlacklistCurrentExplorationDestination(now, m_LastPathFailureReason);
                }

                if (failedObjective == ObjectiveType.Combat
                    && IsTargetZombieAlive()
                    && (TryUseRampLink(position, now, m_TargetZombie!.transform.position, "zumbi em outra regiao")
                        || TryUseLinkTowardPoint(position, now, m_TargetZombie!.transform.position, "zumbi acima sem rota")))
                {
                }
                else if (failedObjective == ObjectiveType.Combat
                    && TryAbandonUnreachableCombatTarget(position, now))
                {
                    m_NextZombieScanTime = 0f;
                }
                else if (failedObjective == ObjectiveType.Combat)
                {
                    // Combat steering is local and can continue safely without an
                    // A* route. Keep the target and throttle the next path request;
                    // clearing it here caused a fail/retarget loop every physics tick.
                    m_PathPoints.Clear();
                    m_PathIndex = 0;
                    m_PathPending = false;
                    m_DirectFallbackUntil = now + 2f;
                    m_NextPathRequestTime = now + 2f;
                }
                else if (failedObjective == ObjectiveType.EscapeHazard)
                {
                    SetObjective(
                        ObjectiveType.EscapeHazard,
                        FindHazardEscapePoint(position, now),
                        now + 25f);
                }
                else if (failedObjective == ObjectiveType.RepositionFire)
                {
                    if (m_RememberedFireZombie != null
                        && !m_RememberedFireZombie.isDead
                        && TryFindConnectedRetreatPoint(
                            position,
                            m_RememberedFireZombie.transform.position,
                            now,
                            out var connectedRetreat))
                    {
                        SetObjective(
                            ObjectiveType.RepositionFire,
                            connectedRetreat,
                            now + 8f);
                    }
                    else
                    {
                        ClearObjective();
                        m_NextLootScanTime = now;
                    }
                }
                else if (failedObjective == ObjectiveType.EscapeSwarm)
                {
                    SetObjective(
                        ObjectiveType.EscapeSwarm,
                        FindZombieEscapePoint(position, now),
                        now + 20f);
                    if (m_SwarmDirectWindowEscape)
                    {
                        m_DirectFallbackUntil = now + 2.5f;
                    }
                }
                else if (failedObjective == ObjectiveType.Loot
                         && m_LootInstanceId != 0
                         && TryGetTargetLoot(out var unroutedLoot)
                         && TryUseLinkTowardPoint(position, now, unroutedLoot.point, "item no alto sem rota"))
                {
                }
                else if (failedObjective == ObjectiveType.Loot
                         && m_LootInstanceId != 0
                         && TryGetTargetLoot(out var doorLoot)
                         && TryStartDoorApproach(position, now, doorLoot.point, "item atras de porta fechada"))
                {
                }
                else if (failedObjective == ObjectiveType.Loot && m_LootInstanceId != 0)
                {
                    // Re-selecting an item with no route every scan froze the
                    // bot for half a minute; skip it, for long when unreachable.
                    var unreachable = m_LastPathFailureReason.IndexOf(
                        "no valid path",
                        System.StringComparison.OrdinalIgnoreCase) >= 0
                        || m_LastPathFailureReason.StartsWith(UnreachableRoutePrefix, System.StringComparison.Ordinal);
                    var ignoreSeconds = unreachable ? UnreachableLootIgnoreSeconds : 30f;
                    if (now - m_LootRouteFailWindowStart > 15f)
                    {
                        m_LootRouteFailWindowStart = now;
                        m_RecentRouteIgnoredLoot.Clear();
                    }
                    m_RecentRouteIgnoredLoot.Add(m_LootInstanceId);
                    IgnoreLoot(m_LootInstanceId, now + ignoreSeconds);
                    BotLog(LogLevel.Information,
                        "Loot {LootInstanceId} sem rota ({Reason}); ignorado por {Seconds:0}s.",
                        m_LootInstanceId,
                        m_LastPathFailureReason,
                        ignoreSeconds);
                    ClearObjective();
                    m_NextLootScanTime = now + 0.75f;
                    if (m_RecentRouteIgnoredLoot.Count >= 3)
                    {
                        // Three different items with no route in a few seconds:
                        // the bot is the one in a closed pocket of the graph (a
                        // barn loft). Ignoring items only wiped the whole area.
                        foreach (var id in m_RecentRouteIgnoredLoot)
                        {
                            m_IgnoredLoot.Remove(id);
                        }
                        m_RecentRouteIgnoredLoot.Clear();
                        m_LootRouteFailWindowStart = float.NegativeInfinity;
                        if (!TryUseRampLink(position, now, null, "varios itens sem rota"))
                        {
                            TryEscapeIsolatedRegion(position, now);
                        }
                    }
                }
                else if (failedObjective == ObjectiveType.Ladder)
                {
                    // The pit floor may have no mesh: walk straight to the foot.
                    m_PathPoints.Clear();
                    m_PathIndex = 0;
                    m_PathPending = false;
                    m_DirectFallbackUntil = now + 3f;
                    m_NextPathRequestTime = now + 3f;
                }
                else if (failedObjective == ObjectiveType.Patrol
                         && m_HasInterestArea
                         && ++m_PatrolRouteFailures < PatrolRouteFailuresBeforeLeaving)
                {
                    // 19 of the 29 "a ultima solicitacao de rota falhou" of the
                    // 0.1.166 test were patrols: one loot point with no route
                    // dropped the whole city. Skip the point, keep the area.
                    if (m_PatrolTargetSet
                        && (m_ObjectivePosition - m_PatrolTargetPoint).GetHorizontalMagnitude() < 1f)
                    {
                        NotePatrolPointFailed(m_PatrolTargetPoint, now, "sem rota: " + m_LastPathFailureReason, true);
                    }
                    m_PatrolTargetSet = false;
                    ClearObjective();
                    m_NextExplorationSelectionTime = now + 0.5f;
                }
                else if (failedObjective != ObjectiveType.ExitWater
                         && failedObjective != ObjectiveType.Flee)
                {
                    m_HasInterestArea = false;
                    ClearObjective();
                    m_NextExplorationSelectionTime = now + ExplorationRetryDelaySeconds;
                    m_ForceLocalExplorationOnNextSelection = true;
                    BotLog(LogLevel.Debug,
                        "Bot aguardara {Delay:0.0}s antes de selecionar uma rota local alternativa.",
                        ExplorationRetryDelaySeconds);
                }
            }

            if (m_RampPhase != 0)
            {
                UpdateRampTraversal(position, now);
            }
            m_BehaviorPosition = position;
            m_BehaviorNow = now;
            // x18: a burner out of sight is not chased (SkaliaBotFireX18).
            ForgetFarFireZombie(position, now);
            RefreshZombieThreatSnapshot(position, now);
            UpdatePendingSpitReaction(now);
            UpdateBossThreat(position, now);
            UpdateMegaSneak(now);
            UpdateMegaRouteGuard(position, now);
            UpdateRisk(position, now);
            UpdateStealthState(now);
            CheckDeathRecoveryDanger(position, now);
            UpdateFreshDeathEviction(position, now);
            if (m_ObjectiveType == ObjectiveType.Loot
                && !IsDropPickupWindow()
                && HasLootBlockingThreat(true)
                && !IsFireTacticalLootObjective()
                && !(m_LootTargetIsCombatEquipment && IsUnarmed()))
            {
                BotLog(LogLevel.Information,
                    "Bot cancelou loot {LootInstanceId}: {Why}.",
                    m_LootInstanceId,
                    m_LootCancelWhy);
                var lootSpot = m_ObjectivePosition;
                // Picked again 2s later and cancelled again: 15 times for one
                // item in the 0.1.103 log. Leave loot alone for a while.
                // 0.1.164: Tadeu went for 3 items 60m behind him and turned
                // back each time an aggroed zombie came within 25m, 35 times
                // in 8 min, logged as 15 circles. A second cancel at the same
                // spot leaves that loot for a minute.
                var sameSpot = now - m_LastLootCancelAt < 60f
                               && (lootSpot - m_LastLootCancelSpot).GetHorizontalMagnitude() < 20f;
                m_StatWindowLootCancels++;
                if (now - m_ObjectiveTypeSince <= 6f)
                {
                    m_StatWindowLootFastCancels++;
                }
                // 0.1.173: the item is remembered and taken back once the
                // zombie is dealt with (up to 3 tries in 60s), unless this is
                // the second cancel at the same spot.
                if (!sameSpot)
                {
                    RememberPendingLoot(now);
                }
                else
                {
                    m_PendingLootId = 0;
                }
                NoteLootGuarded(lootSpot, now);
                ClearObjective();
                m_NextLootScanTime = now + (sameSpot ? 60f : 8f);
                m_LastLootCancelAt = now;
                m_LastLootCancelSpot = lootSpot;
            }
            UpdateVisionLight(now);
            UpdateAcidAheadGuard(position, now);
            UpdateLootGuardKill(position, now);
            UpdateTreatmentCover(position, now);
            m_BehaviorTree.Tick();
            UpdateCombatProgressWatchdog(position, now);
            UpdateLootStallWatchdog(position, now);
            UpdateUnarmedAreaAvoidance(position, now);
            UpdateStallWatchdog(position, now);
            UpdateIdleWatchdog(position, now);
        }

        private void UpdateCombatProgressWatchdog(Vector3 position, float now)
        {
            if (m_ObjectiveType != ObjectiveType.Combat || !IsTargetZombieAlive())
            {
                m_CombatProgressTarget = null;
                return;
            }

            var target = m_TargetZombie!;
            var distance = m_FloorRouteActive
                ? (m_PathPoints.Count > 0 ? m_PathPoints.Count - m_PathIndex : 0) * 3f
                    + Mathf.Abs(target.transform.position.y - position.y)
                : (target.transform.position - position).GetHorizontalMagnitude();
            if (m_HasFiringSpot && m_FiringSpotTarget == target)
            {
                // Walking to a firing spot is progress even if it is not closer.
                distance = (m_FiringSpot - position).GetHorizontalMagnitude();
            }
            // Progress = a new target, 1.5m closer than at the last reset, a
            // blow that lands, or a zombie hitting the bot (it is in reach).
            if (target != m_CombatProgressTarget
                || distance < m_CombatProgressBestDistance - 1.5f
                || m_TotalAttackHits != m_CombatProgressHits
                || m_TotalDamageTaken != m_CombatProgressDamage)
            {
                m_CombatProgressTarget = target;
                m_CombatProgressBestDistance = distance;
                m_CombatProgressSince = now;
                m_CombatProgressAttackCount = m_PublishedAttackCount;
                m_CombatProgressHits = m_TotalAttackHits;
                m_CombatProgressDamage = m_TotalDamageTaken;
                m_CombatProgressStartPosition = position;
                return;
            }

            var progressTimeout = GetCombatProgressTimeout(position);
            if (now - m_CombatProgressSince < (m_FloorRouteActive ? 25f : progressTimeout))
            {
                return;
            }

            if (TryUseLinkTowardPoint(position, now, target.transform.position, "zumbi acima sem progresso"))
            {
                m_CombatProgressTarget = null;
                return;
            }
            if (TryKeepCloseCombatTarget(target, position, now))
            {
                return;
            }

            // A route can exist on the graph while the zombie still cannot be
            // reached or hit (other floor, behind a fence the graph ignores).
            // A zombie that fails again is not worth retrying every 30s: four
            // of them kept the bot cycling in place for five minutes.
            m_ZombieNoProgressStrikes.TryGetValue(target, out var strikes);
            strikes++;
            if (m_ZombieNoProgressStrikes.Count > 64)
            {
                m_ZombieNoProgressStrikes.Clear();
            }
            m_ZombieNoProgressStrikes[target] = strikes;
            var ignoreSeconds = strikes >= 2 ? OtherFloorIgnoreSeconds : UnreachableZombieIgnoreSeconds;
            m_UnreachableZombies[target] = now + ignoreSeconds;
            if (target == m_RememberedFireZombie)
            {
                m_IgnoredFireZombie = target;
                m_IgnoreFireZombieUntil = now + ignoreSeconds;
                m_RememberedFireZombie = null;
            }
            var walkedInPlace = m_IsWalking
                && (position - m_CombatProgressStartPosition).GetHorizontalMagnitude() < 1.5f;
            BotLog(LogLevel.Information,
                "Combate sem progresso por {Seconds:0}s contra zumbi {Kind} a {Distance:0.#}m em {Position}; ignorado por {Ignore:0}s"
                + " (falha {Strikes}; bot andando sem sair do lugar: {Stuck}; prazo {Timeout:0}s, arma {Weapon}).",
                now - m_CombatProgressSince,
                DescribeZombieKind(target),
                distance,
                FormatPosition(target.transform.position),
                ignoreSeconds,
                strikes,
                walkedInPlace,
                GetCombatProgressTimeout(position),
                m_Player.equipment.asset != null ? m_Player.equipment.asset.itemName : "punhos");
            m_CombatProgressTarget = null;
            m_TargetZombie = null;
            ClearObjective();
            m_NextZombieScanTime = 0f;
            if (walkedInPlace)
            {
                // The stall watchdog never fired: each retarget reset it.
                EnterUnstuckState(position, now);
            }
        }

        // XXlloq stood 4 min on one spot off the zombie mesh, swapping
        // objective every second (each swap through "None" reset the stall
        // watchdog), every route failing, and died of thirst. Same spot for
        // 90s with the last route failed: go to the nearest mesh node.
        private const float StrandedSeconds = 90f;
        private const float StrandedMaxTeleportMeters = 150f;
        private Vector3 m_StrandedAnchor;
        private float m_StrandedSince;
        private uint m_StrandedAttackCount;

        private bool UpdateStrandedWatchdog(Vector3 position, float now)
        {
            if ((position - m_StrandedAnchor).GetHorizontalMagnitude() > 3f
                || m_PublishedAttackCount != m_StrandedAttackCount
                || m_ObjectiveType == ObjectiveType.Combat
                || IsPvpPlanted())
            {
                m_StrandedAnchor = position;
                m_StrandedSince = now;
                m_StrandedAttackCount = m_PublishedAttackCount;
                return false;
            }
            if (now - m_StrandedSince < StrandedSeconds || !m_PathFailed)
            {
                return false;
            }
            m_StrandedSince = now;
            // 0.2.2x9: floor of the new mesh with a route to the objective
            // (8-40m), not the nearest zombie-mesh node.
            if (!SkaliaBotUnityNavmesh.TryFindTeleportPoint(position, m_ObjectivePosition, out var floor))
            {
                return false;
            }
            var nearest = (position: floor, node: (GraphNode?)null);
            BotLog(LogLevel.Warning,
                "Bot parado ha {Seconds:0}s em {Position} sem conseguir rota ({Reason}); teleportando para chao da malha nova com rota ate o objetivo em {Destination} ({Distance:0}m).",
                StrandedSeconds,
                FormatPosition(position),
                m_LastPathFailureReason,
                FormatPosition(nearest.position),
                (nearest.position - position).magnitude);
            ClearObjective();
            TeleportBot(nearest.position + Vector3.up * 0.3f, m_Player.look.yaw);
            m_StallAnchor = nearest.position;
            m_StrandedAnchor = nearest.position;
            m_NextExplorationSelectionTime = 0f;
            return true;
        }

        private void UpdateStallWatchdog(Vector3 position, float now)
        {
            if (UpdateStrandedWatchdog(position, now))
            {
                return;
            }
            // 3m tolerance: a bot wobbling around the same spot must still
            // count as stalled.
            if (m_ObjectiveType == ObjectiveType.None
                || (position - m_StallAnchor).GetHorizontalMagnitude() > 3f
                || m_PublishedAttackCount != m_StallAttackCount
                // 0.2.2x1: up to 45s still on the watch from high ground.
                || IsHighWatching(now)
                // 0.2.2x10: up to 30s waiting on purpose (SkaliaBotLadderX10).
                || IsDeliberateHold(now)
                // 0.2.2y: planted shooting back at a player.
                || IsPvpPlanted())
            {
                m_StallAnchor = position;
                m_StallSince = now;
                m_StallAttackCount = m_PublishedAttackCount;
                return;
            }
            if (now - m_StallSince < StallTimeoutSeconds)
            {
                return;
            }
            if (GetNearestAggroedZombieDistance() < 4f)
            {
                // Stuck with a zombie in reach: fight it first. A bot made 7
                // unstuck maneuvers in 30s with zombies under 4m (0.1.103
                // test) and died with its back to them.
                m_StallSince = now;
                return;
            }

            var repeated = now - m_LastStallRecoveryAt <= 90f
                && (position - m_LastStallRecoveryPosition).GetHorizontalMagnitude() <= 5f;
            m_LastStallRecoveryAt = now;
            m_LastStallRecoveryPosition = position;
            m_StallAnchor = position;
            m_StallSince = now;
            if (AstarPath.active != null)
            {
                var stuckNode = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
                if (stuckNode != null && SkaliaBotNavmeshAudit.IsFalseFloor(stuckNode))
                {
                    m_BlockedSteps.Block(stuckNode, now + BlockedStepSeconds);
                    BotLog(LogLevel.Information,
                        "Bot travado sobre malha sem chao firme (pedra) em {Position}; trecho proibido nas rotas por 10 min.",
                        FormatPosition(position));
                }
            }
            BlockStuckSpot(position, now);
            // 0.1.173: stuck again on an upper floor (or a teleport here did
            // not hold): down to the ground nearby instead of 3m along the
            // same floor.
            if (ShouldTeleportDown(position, repeated, now) && TryTeleportDownFromUpperFloor(position, now))
            {
                return;
            }
            if (!repeated)
            {
                BotLog(LogLevel.Information,
                    "Bot parado ha {Seconds:0}s em {Position} com objetivo {Objective}; iniciando manobra de recuperacao.",
                    StallTimeoutSeconds,
                    FormatPosition(position),
                    m_ObjectiveType);
                EnterUnstuckState(position, now);
                return;
            }

            if (m_ObjectiveType == ObjectiveType.Travel && m_TravelPhase == 2)
            {
                // Off the mesh the nearest walkable point is back in the flag
                // just left; contour the obstacle instead.
                m_TravelDetourSide = -m_TravelDetourSide;
                m_TravelForcedDetourUntil = now + 8f;
                BotLog(LogLevel.Information,
                    "Viagem por terreno travada de novo em {Position}; contornando pelo outro lado.",
                    FormatPosition(position));
                EnterUnstuckState(position, now);
                return;
            }

            if (TryEscapeStuckZone(position, now))
            {
                return;
            }
            // The local maneuver already failed here once: move the bot to the
            // nearest dry walkable point instead of leaving it frozen.
            var destination = FindNearestDryNavigablePoint(position, null);
            if (SkaliaBotUnityNavmesh.TryFindFreeSpot(position, 3f, 10f, out var freeSpot))
            {
                destination = freeSpot;
            }
            // 0.2.1: with a bed far away, the way a player gets out: /home.
            if (TryStartHome(now, "travado em " + FormatPosition(position)))
            {
                m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                return;
            }
            m_TeleportExpected = destination;
            m_TeleportCheckAt = now + 1.5f;
            m_TeleportExpectDown = false;
            BotLog(LogLevel.Warning,
                "Bot continua travado em {Position} (objetivo {Objective}); teleportando para {Destination}.",
                FormatPosition(position),
                m_ObjectiveType,
                FormatPosition(destination));
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            ClearObjective();
            TeleportBot(destination, m_Player.look.yaw);
            m_StallAnchor = destination;
            m_NextExplorationSelectionTime = 0f;
        }

        // Input packets already queued carry the old spot as the client's
        // position, and the server takes a client position within a few
        // meters of its own: a 3m unstuck teleport was undone by the next
        // packets (18 of 25 in the 0.1.131 test); a 60m one was not. Point
        // the queued packets at the new spot too.
        private void TeleportBot(Vector3 destination, float yaw)
        {
            m_Player.teleportToLocationUnsafe(destination, yaw);
            NoteOwnTeleport(destination);
            foreach (var queued in m_Player.input.serversidePackets)
            {
                if (queued is WalkingPlayerInputPacket walking)
                {
                    walking.clientPosition = destination;
                }
            }
        }

        private Vector3 m_TeleportExpected;
        private float m_TeleportCheckAt = -1f;

        // In the 0.1.123 test the bot at the Medic wall was "teleported" 3.7m
        // away and every next line still had it on the same spot.
        private bool m_TeleportExpectDown;

        private void CheckTeleportLanded(float now)
        {
            if (m_TeleportCheckAt < 0f || now < m_TeleportCheckAt)
            {
                return;
            }
            m_TeleportCheckAt = -1f;
            var position = m_Player.transform.position;
            var off = (position - m_TeleportExpected).GetHorizontalMagnitude();
            // 0.1.174: a drop from an upper floor held when the bot is on the
            // ground; it walks on within the 1.5s, so the horizontal gap said
            // "nao pegou" both times it worked in the 0.1.173 test.
            if (m_TeleportExpectDown)
            {
                m_TeleportExpectDown = false;
                if (!IsUpperFloor(position) || position.y <= m_TeleportExpected.y + 1.5f)
                {
                    off = 0f;
                }
            }
            if (off > 1.5f)
            {
                NoteStallTeleportFailed(position, now);
            }
            BotLog(off > 1.5f ? LogLevel.Warning : LogLevel.Information,
                off > 1.5f
                    ? "Teleporte de destravar nao pegou: bot em {Position}, a {Off:0.0}m de {Expected}."
                    : "Teleporte de destravar confirmado: bot em {Position} ({Off:0.0}m de {Expected}).",
                FormatPosition(position),
                off,
                FormatPosition(m_TeleportExpected));
        }

        private bool TryAbandonUnreachableCombatTarget(Vector3 position, float now)
        {
            var target = m_TargetZombie;
            if (target == null || !IsTargetZombieAlive())
            {
                return false;
            }

            if (target == m_CombatPathFailureTarget)
            {
                m_CombatPathFailures++;
            }
            else
            {
                m_CombatPathFailureTarget = target;
                m_CombatPathFailures = 1;
            }

            // A loaded gun with line of sight does not need a route to shoot, and
            // a zombie already inside attack range can still be hit locally.
            var canShoot = m_Player.equipment.asset is ItemGunAsset gun
                && IsEquippedGunLoaded(gun)
                && HasClearLineToPoint(GetZombieAimPoint(target));
            var distance = (target.transform.position - position).GetHorizontalMagnitude();
            if (m_CombatPathFailures < UnreachableZombiePathFailures
                || canShoot
                || distance <= GetCombatAttackDistance() + 1f)
            {
                return false;
            }

            m_UnreachableZombies[target] = now + UnreachableZombieIgnoreSeconds;
            if (target == m_RememberedFireZombie)
            {
                m_IgnoredFireZombie = target;
                m_IgnoreFireZombieUntil = now + UnreachableZombieIgnoreSeconds;
                m_RememberedFireZombie = null;
            }
            m_CombatPathFailureTarget = null;
            m_CombatPathFailures = 0;
            m_TargetZombie = null;
            BotLog(LogLevel.Information,
                "Zumbi {Kind} em {Position} sem rota apos {Failures} tentativas; ignorado por {Seconds:0}s.",
                DescribeZombieKind(target),
                FormatPosition(target.transform.position),
                UnreachableZombiePathFailures,
                UnreachableZombieIgnoreSeconds);
            ClearObjective();
            return true;
        }

        // At (1780, 114, -200) Tadeu restarted the fight with one zombie 15
        // times in 2 minutes (Combat, Unstuck, Patrol, Combat...) without getting any
        // closer. A route existed; the bot just could not follow it.
        private const int CombatRestartLimit = 4;
        private const float CombatRestartWindowSeconds = 45f;
        private const float CombatRestartIgnoreSeconds = 60f;
        private Zombie? m_CombatRestartZombie;
        private int m_CombatRestarts;
        private float m_CombatRestartWindowStart;
        private float m_CombatRestartBestDistance;

        private void NoteCombatRestart(Zombie target, float now)
        {
            var distance = (target.transform.position - m_Player.transform.position).GetHorizontalMagnitude();
            if (target != m_CombatRestartZombie
                || now - m_CombatRestartWindowStart > CombatRestartWindowSeconds
                || distance < m_CombatRestartBestDistance - 3f)
            {
                m_CombatRestartZombie = target;
                m_CombatRestarts = 1;
                m_CombatRestartWindowStart = now;
                m_CombatRestartBestDistance = distance;
                return;
            }
            m_CombatRestarts++;
            m_CombatRestartBestDistance = Mathf.Min(m_CombatRestartBestDistance, distance);
            if (m_CombatRestarts < CombatRestartLimit || distance <= GetCombatAttackDistance() + 1f)
            {
                return;
            }
            m_UnreachableZombies[target] = now + CombatRestartIgnoreSeconds;
            BotLog(LogLevel.Information,
                "Luta contra zumbi em {Position} recomecou {Count} vezes em {Seconds:0}s sem chegar mais perto (mais perto {Best:0.#}m); ignorado por {Ignore:0}s.",
                FormatPosition(target.transform.position),
                m_CombatRestarts,
                now - m_CombatRestartWindowStart,
                m_CombatRestartBestDistance,
                CombatRestartIgnoreSeconds);
            m_CombatRestartZombie = null;
            m_CombatRestarts = 0;
        }

        private readonly Dictionary<Zombie, float> m_UnreachableZombieDistance = new Dictionary<Zombie, float>();
        private float m_LastZombieBiteAt = float.NegativeInfinity;

        private bool IsZombieMarkedUnreachable(Zombie zombie, float now)
        {
            if (!m_UnreachableZombies.TryGetValue(zombie, out var ignoredUntil))
            {
                return false;
            }
            // A zombie that walked up to the bot is reachable again, whatever
            // the route graph said.
            // Same floor only: a zombie stuck on a roof right above the bot
            // is close horizontally but still out of reach.
            var closeOffset = zombie.transform.position - m_Player.transform.position;
            // Walked up means closer than when it was given up on, or biting
            // the bot: in the 0.1.135 test thigas stood 22 min at a zombie
            // stuck 1.3m away behind something, never hitting it, given up
            // on 111 times and taken back each time for being close.
            var closeDistance = closeOffset.GetHorizontalMagnitude();
            if (!m_UnreachableZombieDistance.TryGetValue(zombie, out var markedDistance))
            {
                markedDistance = closeDistance;
                m_UnreachableZombieDistance[zombie] = markedDistance;
            }
            var closeEnough = closeDistance <= 3f
                && Mathf.Abs(closeOffset.y) <= 2f
                && (closeDistance < markedDistance - 1f || now - m_LastZombieBiteAt < 3f);
            if (now < ignoredUntil && !closeEnough)
            {
                return true;
            }
            m_UnreachableZombies.Remove(zombie);
            m_UnreachableZombieDistance.Remove(zombie);
            return false;
        }

        // 0.1.166: a magazine or an unloaded gun fetched for the burner was
        // called off on the next tick (the burner is within 14m by then).
        private bool IsFireTacticalLootObjective()
        {
            return m_ObjectiveType == ObjectiveType.Loot
                && (m_LootTargetIsRangedWeapon
                    || (m_LootInstanceId != 0 && m_LootInstanceId == m_FireLootInstanceId))
                && m_RememberedFireZombie != null
                && !m_RememberedFireZombie.isDead
                && m_RememberedFireZombie.gameObject.activeInHierarchy;
        }

        private void RefreshZombieThreatSnapshot(Vector3 position, float now)
        {
            if (now < m_NextSwarmThreatScanAt)
            {
                return;
            }
            m_NextSwarmThreatScanAt = now + 0.25f;
            RefreshZombiePerception(position, now);
            ScanZombieThreats(
                position,
                out m_CachedSurroundedZombieCount,
                out m_CachedNearbyZombieCount,
                out m_CachedNearestFireZombieDistance,
                out m_CachedNearestZombieDistance);
            RefreshThreatSnapshot(position, now);
        }

        private void RefreshZombiePerception(Vector3 position, float now)
        {
            m_CachedOperationalAreaZombieCount = 0;
            m_PerceptionRemovalBuffer.Clear();
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie is null)
                {
                    continue;
                }
                if (zombie == null
                    || zombie.isDead
                    || !zombie.gameObject.activeInHierarchy
                    || now >= perceived.Value)
                {
                    m_PerceptionRemovalBuffer.Add(zombie!);
                }
            }
            foreach (var expired in m_PerceptionRemovalBuffer)
            {
                m_PerceivedZombies.Remove(expired);
            }

            // Always scan the live zombie regions. An empty perception memory means
            // the bot has not seen a zombie yet, not that the area is clear.
            s_UniqueZombieThreats.Clear();
            foreach (var region in ZombieManager.regions)
            {
                if (region?.zombies == null)
                {
                    continue;
                }
                foreach (var zombie in region.zombies)
                {
                    if (zombie == null
                        || zombie.isDead
                        || !zombie.gameObject.activeInHierarchy
                        || !s_UniqueZombieThreats.Add(zombie))
                    {
                        continue;
                    }
                    // 0.1.173: a marked zombie ("no progress", "no route")
                    // is still seen: it is left alone as a target but kept in
                    // the threat snapshot (m_MarkedSeenZombies), so a marked
                    // burner or hunter is fled from instead of vanishing.
                    var marked = IsZombieMarkedUnreachable(zombie, now);
                    if (!marked && IsInsideCurrentOperationalArea(zombie.transform.position, position))
                    {
                        m_CachedOperationalAreaZombieCount++;
                    }
                    var offset = zombie.transform.position - position;
                    if (Mathf.Abs(offset.y) > 12f)
                    {
                        continue;
                    }
                    var distance = offset.GetHorizontalMagnitude();
                    var visualRadius = IsBossZombie(zombie)
                        ? BossVisualRadiusMeters
                        : IsFireZombie(zombie)
                            ? FireZombieVisualRadiusMeters
                            : VisualZombieDetectionRadiusMeters;
                    var perceived = distance <= ProximityZombieAwarenessRadiusMeters
                        || (distance <= visualRadius
                            && HasClearLineToPoint(GetZombieAimPoint(zombie)));
                    if (!perceived)
                    {
                        continue;
                    }
                    if (marked)
                    {
                        NoteMarkedZombieSeen(zombie, now);
                        continue;
                    }
                    m_PerceivedZombies[zombie] = now + ZombieMemorySeconds;
                    // 0.1.166: every zombie seen, up to 50m off and not after
                    // the bot, counted as a combat threat and held back
                    // bandages, meals and loot. Only one coming after the bot
                    // or already close does now.
                    if (distance <= 6f
                        || (zombie.isHunting && zombie.player == m_Player && distance <= 25f))
                    {
                        m_LastCombatThreatAt = now;
                    }
                }
            }
        }

        private bool IsInsideCurrentOperationalArea(
            Vector3 candidate,
            Vector3 botPosition)
        {
            var center = m_HasInterestArea ? m_InterestAreaCenter : botPosition;
            var radius = m_HasInterestArea
                ? InterestAreaRadiusMeters + 10f
                : VisualZombieDetectionRadiusMeters;
            return Mathf.Abs(candidate.y - center.y) <= 20f
                && (candidate - center).GetHorizontalMagnitude() <= radius;
        }

        // Looting waits only for a zombie that matters: one hunting the bot,
        // one close, or a fire zombie nearby. Any zombie within 95m of the area
        // used to cancel every pickup: 1297 cancels and 68 items in three hours.
        // 0.1.166: starting and calling off a loot used the same limits, so a
        // zombie walking around 15m made the bot start and drop the same item
        // again and again (94 cancels in 3h45; 21 for one item in the 0.1.164
        // test). Once on its way only a much closer zombie, a burner or one
        // coming after the bot calls the loot off.
        private const float LootCancelZombieMeters = 5f;
        private string m_LootCancelWhy = string.Empty;
        private const float LootCancelAggroMeters = 15f;
        private const float LootCancelFireMeters = 14f;

        private bool HasLootBlockingThreat(bool continuing = false)
        {
            if (continuing)
            {
                // 0.1.174: 115 of 130 cancels came within 6s of starting, most
                // for a zombie that showed up 8-15m away while the bot was
                // ahead in the race. A loot under way now stops only for a
                // zombie within 5m, a burner within 14m, a zombie that gets
                // to the item first, or an aggroed one with low health.
                if (m_CachedNearestZombieDistance < LootCancelZombieMeters)
                {
                    m_LootCancelWhy = "zumbi a " + m_CachedNearestZombieDistance.ToString("0.#") + "m do bot";
                    return true;
                }
                if (m_CachedNearestFireZombieDistance < LootCancelFireMeters)
                {
                    m_LootCancelWhy = "zumbi de fogo a " + m_CachedNearestFireZombieDistance.ToString("0.#") + "m";
                    return true;
                }
                var aggroed = GetNearestAggroedZombieDistance();
                if (IsLowHealth() && aggroed < LootCancelAggroMeters)
                {
                    m_LootCancelWhy = "vida baixa com zumbi agrado a " + aggroed.ToString("0.#") + "m";
                    return true;
                }
                if (m_ObjectiveType == ObjectiveType.Loot
                    && IsLootRaceLost(m_ObjectivePosition, m_BehaviorPosition, out var botSeconds, out var zombieSeconds))
                {
                    m_LootCancelWhy = "zumbi chega ao item antes (" + zombieSeconds.ToString("0.#") + "s contra " + botSeconds.ToString("0.#") + "s do bot)";
                    return true;
                }
                return false;
            }
            if (IsTargetZombieAlive()
                && (m_TargetZombie!.transform.position - m_BehaviorPosition).GetHorizontalMagnitude()
                    < LootBlockAggroMeters)
            {
                return true;
            }
            return m_CachedNearestZombieDistance < LootBlockZombieMeters
                || m_CachedNearestFireZombieDistance < 20f
                || GetNearestAggroedZombieDistance() < LootBlockAggroMeters
                || (m_BehaviorNow - m_LastCombatThreatAt < LootAfterCombatDelaySeconds
                    && m_CachedNearestZombieDistance < LootBlockAggroMeters);
        }

        private int CountPerceivedLivingZombies()
        {
            var count = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null && !zombie.isDead && zombie.gameObject.activeInHierarchy)
                {
                    count++;
                }
            }
            return count;
        }

        // Half health in a horde: at 40-55 health the bot kept chasing zombies
        // 14m away with 12-16 of them around and died four times in one night.
        private bool IsHordeCaution()
        {
            return m_StealthActive && !IsLowHealth() && !IsFullMoonCrowd();
        }

        // 0.1.166: the crowd check flipped each time a zombie crossed 12m,
        // and caution with it: off and on again in the same second with the
        // same health and the same 5 zombies (17 of 64 changes within 5s).
        // The crowd now holds until at most one zombie is within 12m for 4s,
        // and caution keeps each state at least 8s unless the bot is unarmed.
        private bool m_FullMoonCrowd;
        private float m_FullMoonCrowdQuietSince = -1f;
        private float m_StealthChangedAt = float.NegativeInfinity;
        private const float StealthMinimumSeconds = 8f;
        private const float FullMoonCrowdQuietSeconds = 4f;

        private bool IsFullMoonCrowd()
        {
            return m_FullMoonCrowd;
        }

        private void UpdateFullMoonCrowd(float now)
        {
            if (!LightingManager.isFullMoon)
            {
                m_FullMoonCrowd = false;
                m_FullMoonCrowdQuietSince = -1f;
                return;
            }
            if (m_CachedNearbyZombieCount >= SurroundedZombieCount)
            {
                m_FullMoonCrowd = true;
                m_FullMoonCrowdQuietSince = -1f;
                return;
            }
            if (!m_FullMoonCrowd || m_CachedNearbyZombieCount > 1)
            {
                m_FullMoonCrowdQuietSince = -1f;
                return;
            }
            if (m_FullMoonCrowdQuietSince < 0f)
            {
                m_FullMoonCrowdQuietSince = now;
            }
            else if (now - m_FullMoonCrowdQuietSince >= FullMoonCrowdQuietSeconds)
            {
                m_FullMoonCrowd = false;
                m_FullMoonCrowdQuietSince = -1f;
            }
        }

        // Caution is sneaking, not running: crouched, a non-sprinting player is
        // heard at 6m instead of 12m (22m sprinting, which is how the bot moved
        // everywhere), and a zombie never notices one behind it. Under a full
        // moon every zombie hears at 24m, so caution starts earlier there.
        private void UpdateStealthState(float now)
        {
            UpdateFullMoonCrowd(now);
            var fullMoon = LightingManager.isFullMoon;
            var healthLimit = fullMoon ? FullMoonCautionHealth : HordeCautionHealth;
            var countLimit = fullMoon ? FullMoonCautionZombies : HordeCautionZombies;
            var count = CountPerceivedLivingZombies();
            var health = m_Player.life.health;
            bool active;
            // 0.2.2x2 (doc 16.7, item 3): caution came on during 4 of the 7
            // Mega deaths; near a Mega the bot fights or runs standing.
            var megaNear = Tryhard && (IsMegaNear() || IsMegaLostAlert() || m_BossHuntActive || m_BossFleeActive);
            if (!s_Settings.HordeCaution || IsUnarmed() || IsFullMoonCrowd() || megaNear)
            {
                active = false;
            }
            else if (m_StealthActive)
            {
                active = health < healthLimit + 10f && count >= countLimit - 2;
            }
            else
            {
                active = health < healthLimit && count >= countLimit;
            }
            if (active != m_StealthActive
                && !IsUnarmed()
                && !megaNear
                && now - m_StealthChangedAt < StealthMinimumSeconds)
            {
                active = m_StealthActive;
            }
            if (active != m_StealthActive)
            {
                m_StealthChangedAt = now;
                if (active)
                {
                    BotLog(LogLevel.Information,
                        "Cautela ligada (vida {Health}, {Count} zumbis{Moon}): andando agachado e atacando zumbi distraido pelas costas.",
                        health,
                        count,
                        fullMoon ? ", lua cheia" : string.Empty);
                }
                else
                {
                    BotLog(LogLevel.Information,
                        "Cautela desligada (vida {Health}, {Count} zumbis).",
                        health,
                        count);
                }
            }
            m_StealthActive = active;
            // 0.1.172: standing near the Mega: crouched, the bot could not get
            // out of the way of its boulders (Tadeu at 5m from it, 11-06).
            m_StealthCrouch = active
                && !IsLowHealth()
                && !IsMegaNear()
                && GetNearestAggroedZombieDistance() > (LightingManager.isFullMoon ? FullMoonStandUpMeters : StealthStandUpMeters)
                && m_Player.stance.stance != EPlayerStance.SWIM
                && m_ObjectiveType != ObjectiveType.Flee
                && m_ObjectiveType != ObjectiveType.EscapeSwarm
                && m_ObjectiveType != ObjectiveType.EscapeHazard
                && m_ObjectiveType != ObjectiveType.RepositionFire
                && m_ObjectiveType != ObjectiveType.ExitWater
                && m_ObjectiveType != ObjectiveType.Unstuck;
        }

        // First whatever already hunts the bot and is in reach, otherwise the
        // nearest zombie that has not noticed it.
        private bool TryPickStealthTarget(Vector3 position, out Zombie target)
        {
            target = null!;
            Zombie? hunting = null;
            Zombie? idle = null;
            var bestHunting = float.PositiveInfinity;
            var bestIdle = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null
                    || zombie.isDead
                    || !zombie.gameObject.activeInHierarchy
                    || IsZombieMarkedUnreachable(zombie, m_BehaviorNow)
                    || IsFireZombie(zombie)
                    || IsBossZombie(zombie)
                    || IsNearKnownBoss(zombie.transform.position))
                {
                    continue;
                }
                var offset = zombie.transform.position - position;
                var distance = offset.GetHorizontalMagnitude();
                if (zombie.isHunting)
                {
                    if (distance <= HordeCautionEngagementMeters && distance < bestHunting)
                    {
                        bestHunting = distance;
                        hunting = zombie;
                    }
                }
                else if (Mathf.Abs(offset.y) < 3f
                         && distance < bestIdle
                         && IsStealthApproachSafe(zombie, position, distance))
                {
                    bestIdle = distance;
                    idle = zombie;
                }
            }
            var chosen = hunting ?? idle;
            if (chosen == null)
            {
                return false;
            }
            target = chosen;
            return true;
        }

        // A step behind a zombie that has not noticed the bot.
        private Vector3 GetCombatDestination(Vector3 position, Zombie target)
        {
            var targetPosition = target.transform.position;
            // 0.2.2x14: the Mega after the bot comes into the line by itself.
            // thigas (18:52, x13) walked from 30m to a firing spot "22m from
            // it" while it came at 6 m/s, was at 7.9m with it and died.
            if (TryBackOffFromComingMega(position, target, out var backOff))
            {
                return backOff;
            }
            if ((IsFireZombie(target) || IsHuntedBoss(target))
                && HasLoadedRangedWeapon()
                && TryGetFiringSpot(position, target, m_BehaviorNow, out var firingSpot))
            {
                return firingSpot;
            }
            if (!m_StealthCrouch
                || target.isHunting
                || (targetPosition - position).GetHorizontalMagnitude() <= 2.2f)
            {
                return targetPosition;
            }
            var back = target.transform.forward;
            back.y = 0f;
            if (back.sqrMagnitude < 0.01f)
            {
                return targetPosition;
            }
            var behind = FindNearestNavigablePoint(targetPosition - back.normalized * 1.5f);
            return (behind - targetPosition).GetHorizontalMagnitude() <= 2.5f ? behind : targetPosition;
        }

        // The fire zombie inside the hospital and the bot outside: the
        // crossbow never had a line, the bot circled for 12s and gave up.
        // Without a line from where it stands, the bot looks around the
        // zombie for a reachable spot that sees it (a window, the door)
        // within shooting range, and goes there to shoot.
        // Not 6m: at 22:41 in the 0.1.150 test Tadeu walked to a spot 6m
        // from the burner, which reached him before the first shot.
        private static readonly float[] s_FiringSpotRadii = { 12f, 15f, 18f };
        private const int FiringSpotAngles = 16;
        private Zombie? m_FiringSpotTarget;
        private Vector3 m_FiringSpot;
        private Vector3 m_FiringSpotZombiePosition;
        private bool m_HasFiringSpot;
        private float m_FiringSpotUntil;
        private float m_NextFiringSpotSearchAt;
        private float m_FiringSpotHoldUntil;

        private static float DistanceToSegment2D(Vector3 point, Vector3 from, Vector3 to)
        {
            var a = new Vector2(from.x, from.z);
            var b = new Vector2(to.x, to.z);
            var p = new Vector2(point.x, point.z);
            var ab = b - a;
            var length = ab.sqrMagnitude;
            var t = length < 0.0001f ? 0f : Mathf.Clamp01(Vector2.Dot(p - a, ab) / length);
            return (p - (a + ab * t)).magnitude;
        }

        private bool TryGetFiringSpot(Vector3 position, Zombie target, float now, out Vector3 spot)
        {
            spot = position;
            var aim = GetZombieAimPoint(target);
            var targetPosition = target.transform.position;
            // 0.2.2v (doc 13.3, item 2): the Mega walks 6 m/s, so the 3m
            // limit threw the spot away every second (XX at Olympia,
            // 18:50:30-18:50:52: 11 spots, none reached). For the hunted
            // Mega the spot is kept while the Mega stayed within 12m of where
            // it was and the spot still sees it.
            var huntedSpot = Tryhard && IsHuntedBoss(target);
            // 0.2.2x2 (doc 16.7, item 2): the Mega moves 6 m/s, so the 12m
            // and line checks dropped the spot every 1-2s (Tadeu, 00:29:00-
            // 00:29:15: 8 spots, each one nearer). A spot for the hunted Mega
            // is now held 4s while the Mega is over 10m from the bot and from
            // the spot.
            var holdHuntedSpot = huntedSpot
                && m_HasFiringSpot
                && m_FiringSpotTarget == target
                && now < m_FiringSpotHoldUntil
                && (targetPosition - position).GetHorizontalMagnitude() > 10f
                && (targetPosition - m_FiringSpot).GetHorizontalMagnitude() > 10f;
            if (m_HasFiringSpot
                && !holdHuntedSpot
                && (m_FiringSpotTarget != target
                    || now >= m_FiringSpotUntil
                    || (targetPosition - m_FiringSpotZombiePosition).GetHorizontalMagnitude() > (huntedSpot ? 12f : 3f)
                    || (huntedSpot
                        && Physics.Linecast(
                            m_FiringSpot + Vector3.up * 1.5f,
                            aim,
                            RayMasks.BLOCK_COLLISION,
                            QueryTriggerInteraction.Ignore))))
            {
                m_HasFiringSpot = false;
            }
            if (m_HasFiringSpot)
            {
                var reached = (m_FiringSpot - position).GetHorizontalMagnitude() <= 1.2f;
                if (!reached || holdHuntedSpot || HasClearLineToPoint(aim))
                {
                    // Hold the spot while it gives a line: walking on toward
                    // the zombie would lose it again behind the wall.
                    spot = m_FiringSpot;
                    return true;
                }
                m_HasFiringSpot = false;
            }
            if (HasClearLineToPoint(aim) || now < m_NextFiringSpotSearchAt || !SkaliaBotUnityNavmesh.MapFilled)
            {
                return false;
            }
            m_NextFiringSpotSearchAt = now + 1.5f;
            GraphNode? botNode = null;
            var huntedBoss = IsHuntedBoss(target);
            // 0.2.2x1: for the Mega the search reaches 50m even while the gun
            // is being reloaded (it fell to 7m then, 22:44:23).
            var maximumRange = huntedBoss && Tryhard
                ? 51f
                : Mathf.Max(7f, GetCombatAttackDistance() + 1f);
            var bestScore = float.PositiveInfinity;
            var best = Vector3.zero;
            var minimumFromZombie = huntedBoss ? BossHuntKiteMeters + 3f : 10f;
            var targetLabel = huntedBoss ? "do Mega" : "do zumbi de fogo";
            foreach (var radius in huntedBoss ? s_BossFiringSpotRadii : s_FiringSpotRadii)
            {
                if (radius > maximumRange)
                {
                    break;
                }
                for (var index = 0; index < FiringSpotAngles; index++)
                {
                    var direction = Quaternion.Euler(0f, index * 360f / FiringSpotAngles, 0f) * Vector3.forward;
                    var desired = targetPosition + direction * radius;
                    var nearest = SnapToNewMesh(desired, 2.5f);
                    if (!nearest.found)
                    {
                        continue;
                    }
                    var candidate = nearest.position;
                    var fromZombie = (candidate - targetPosition).GetHorizontalMagnitude();
                    var rise = candidate.y - targetPosition.y;
                    if ((candidate - desired).GetHorizontalMagnitude() > 2f
                        || rise < -4f
                        || rise > (huntedBoss && Tryhard ? 12f : 4f)
                        || fromZombie < minimumFromZombie
                        || fromZombie > maximumRange
                        || !CanReach(botNode, nearest.node, position, candidate)
                        || Physics.Linecast(
                            candidate + Vector3.up * 1.5f,
                            aim,
                            RayMasks.BLOCK_COLLISION,
                            QueryTriggerInteraction.Ignore))
                    {
                        continue;
                    }
                    // Nearest to walk to, with a little weight on keeping
                    // distance from the burner.
                    var score = (candidate - position).GetHorizontalMagnitude() - fromZombie * 0.3f;
                    if (huntedBoss && Tryhard)
                    {
                        // The Mega: far, high and seen from a prone eye.
                        var proneLine = !Physics.Linecast(
                            candidate + Vector3.up * 0.55f,
                            aim,
                            RayMasks.BLOCK_COLLISION,
                            QueryTriggerInteraction.Ignore);
                        score -= fromZombie * 0.3f + Mathf.Clamp(rise, 0f, 10f) * 1.5f + (proneLine ? 8f : 0f);
                        // 0.2.2x2: a spot nearer the Mega than the bot is,
                        // or one whose way passes by the Mega, walks the bot
                        // into it.
                        var botFromZombie = (position - targetPosition).GetHorizontalMagnitude();
                        score += Mathf.Max(0f, botFromZombie - fromZombie) * 1.5f;
                        if (DistanceToSegment2D(targetPosition, position, candidate) < 10f)
                        {
                            score += 30f;
                        }
                    }
                    if (score < bestScore)
                    {
                        bestScore = score;
                        best = candidate;
                    }
                }
            }
            if (float.IsPositiveInfinity(bestScore))
            {
                if (m_FiringSpotTarget != target)
                {
                    m_FiringSpotTarget = target;
                    BotLog(LogLevel.Information,
                        "Sem linha de visao {Target} em {Position} e nenhum ponto alcancavel a ate {Range:0}m que enxergue ele.",
                        targetLabel,
                        FormatPosition(targetPosition),
                        maximumRange);
                }
                return false;
            }
            m_FiringSpotTarget = target;
            m_FiringSpot = best;
            m_FiringSpotZombiePosition = targetPosition;
            m_FiringSpotUntil = now + 10f;
            m_FiringSpotHoldUntil = now + 4f;
            m_HasFiringSpot = true;
            BotLog(LogLevel.Information,
                "Sem linha de visao {Target} em {Position}; indo para o ponto de tiro {Spot} a {Distance:0.#}m dele, que enxerga o alvo.",
                targetLabel,
                FormatPosition(targetPosition),
                FormatPosition(best),
                (best - targetPosition).GetHorizontalMagnitude());
            spot = best;
            return true;
        }

        private float GetCautionEngagementRadius(Zombie? zombie)
        {
            if (IsHordeCaution())
            {
                return zombie != null && !zombie.isHunting
                    ? s_Settings.StealthApproachMeters + 3f
                    : HordeCautionEngagementMeters;
            }
            return IsLowHealth() ? LowHealthEngagementRadiusMeters : float.PositiveInfinity;
        }

        private bool HasUnresolvedZombieThreat()
        {
            if (m_CachedOperationalAreaZombieCount > 0 || IsTargetZombieAlive())
            {
                return true;
            }
            if (m_RememberedFireZombie != null
                && !m_RememberedFireZombie.isDead
                && m_RememberedFireZombie.gameObject.activeInHierarchy)
            {
                return true;
            }
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null
                    && !zombie.isDead
                    && zombie.gameObject.activeInHierarchy
                    && !IsZombieMarkedUnreachable(zombie, m_BehaviorNow))
                {
                    return true;
                }
            }
            return false;
        }

        private BotBehaviorStatus TickHazardBehavior()
        {
            return UpdateHazardEscapeState(m_BehaviorPosition, m_BehaviorNow)
                ? BotBehaviorStatus.Running
                : BotBehaviorStatus.Failure;
        }

        private bool IsWaterBehaviorRequired()
        {
            var inWater = m_Player.stance.stance == EPlayerStance.SWIM
                || WaterUtility.isPointUnderwater(m_BehaviorPosition + Vector3.up * 0.5f);
            if (!inWater)
            {
                if (m_InWaterSince >= 0f && m_SwimExitActive)
                {
                    BotLog(LogLevel.Information,
                        "Bot saiu da agua nadando em {Position} apos {Seconds:0}s.",
                        FormatPosition(m_BehaviorPosition),
                        m_BehaviorNow - m_InWaterSince);
                    NoteWaterExit(m_BehaviorPosition, m_BehaviorNow);
                }
                m_InWaterSince = -1f;
                m_SwimExitActive = false;
            }
            return inWater;
        }

        // XXlloqiartyXX went into the river and out again 71 times in 3 min
        // at (260, -1440): the trip it was on kept sending it to the same
        // bank. A third swim at the same spot in 90s ends whatever led there.
        private readonly List<(float At, Vector3 Where)> m_WaterExits = new List<(float, Vector3)>();

        private void NoteWaterExit(Vector3 position, float now)
        {
            m_WaterExits.RemoveAll(exit => now - exit.At > 90f || (exit.Where - position).GetHorizontalMagnitude() > 20f);
            m_WaterExits.Add((now, position));
            if (m_WaterExits.Count < 3)
            {
                return;
            }
            m_WaterExits.Clear();
            BotLog(LogLevel.Information,
                "Entrou na agua 3 vezes em 90s perto de {Position} (objetivo {Objective}); desistindo do que levava ate la.",
                FormatPosition(position),
                m_ObjectiveType);
            if (m_TravelActive)
            {
                FailTerrainTravel(now, "entrou na agua 3 vezes no mesmo lugar");
            }
            else if (m_HasInterestArea)
            {
                FinishInterestArea(now);
            }
            ClearObjective();
            m_NextExplorationSelectionTime = now;
        }

        private BotBehaviorStatus TickWaterBehavior()
        {
            var now = m_BehaviorNow;
            // 0.1.173: in the water on purpose, out of stamina with the
            // burner after the bot: it stays there until the burner gives
            // up (at most 30s), and the long-swim rescue does not count it.
            if (IsHoldingInFireWaterRefuge(now))
            {
                m_WaterEpisodeSince = now;
                m_LastInWaterAt = now;
                return BotBehaviorStatus.Running;
            }
            // 0.2.2x14: a route across the water is swum to the far bank.
            if (TryTickSwimCrossing(now))
            {
                return BotBehaviorStatus.Running;
            }
            if (m_WaterEpisodeSince < 0f || now - m_LastInWaterAt > WaterEpisodeGapSeconds)
            {
                // Hopping onto the bank and back is one stay in the water: the
                // rescue timer and the failed banks only reset after 20s dry.
                m_WaterEpisodeSince = now;
                m_FailedSwimExits.Clear();
            }
            m_LastInWaterAt = now;
            if (m_InWaterSince < 0f)
            {
                m_InWaterSince = now;
            }
            else if (now - m_WaterEpisodeSince >= WaterRescueSeconds
                && now - m_LastWaterRescueAt >= 20f
                && TryTeleportOutOfWater(m_BehaviorPosition, now))
            {
                return BotBehaviorStatus.Running;
            }
            UpdateExitWaterState(m_BehaviorPosition, now);
            return BotBehaviorStatus.Running;
        }

        // Some spawn points sit by water the navmesh doesn't connect to land;
        // after 10s still swimming, move to dry land (nearest, else another
        // player spawn away from here).
        private bool TryTeleportOutOfWater(Vector3 position, float now)
        {
            m_LastWaterRescueAt = now;
            var destination = FindNearestDryNavigablePoint(position, null);
            var found = (destination - position).GetHorizontalMagnitude() > 4f
                && !WaterUtility.isPointUnderwater(destination + Vector3.up * 0.5f);
            if (!found)
            {
                found = TryPickDrySpawn(position, 60f, out destination);
            }
            if (!found)
            {
                return false;
            }
            BotLog(LogLevel.Warning,
                "Bot na agua ha {Seconds:0}s em {Position}; teleportando para terra firme em {Destination}.",
                now - m_WaterEpisodeSince,
                FormatPosition(position),
                FormatPosition(destination));
            m_InWaterSince = -1f;
            m_WaterEpisodeSince = -1f;
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            ClearObjective();
            TeleportBot(destination, m_Player.look.yaw);
            m_NextExplorationSelectionTime = 0f;
            return true;
        }

        private static bool TryPickDrySpawn(Vector3 position, float minimumDistance, out Vector3 destination)
        {
            destination = position;
            if (LevelPlayers.spawns == null)
            {
                return false;
            }
            var bestDistance = float.PositiveInfinity;
            foreach (var spawn in LevelPlayers.spawns)
            {
                if (spawn == null
                    || spawn.isAlt
                    || WaterUtility.isPointUnderwater(spawn.point + Vector3.up * 0.5f))
                {
                    continue;
                }
                var distance = (spawn.point - position).GetHorizontalMagnitude();
                if (distance <= minimumDistance || distance >= bestDistance)
                {
                    continue;
                }
                bestDistance = distance;
                destination = spawn.point + Vector3.up * 0.5f;
            }
            return bestDistance < float.PositiveInfinity;
        }

        private BotBehaviorStatus TickSwarmBehavior()
        {
            return UpdateSwarmEscapeState(m_BehaviorPosition, m_BehaviorNow)
                ? BotBehaviorStatus.Running
                : BotBehaviorStatus.Failure;
        }

        private BotBehaviorStatus TickForcedMovementBehavior()
        {
            // 0.2.2: on the ladder (or at its foot or top, taking hold) the
            // bot finishes it; a fight there only makes it fall.
            if (IsLadderInProgress() && m_LadderPhase >= 2)
            {
                return BotBehaviorStatus.Running;
            }
            if (m_ObjectiveType != ObjectiveType.Flee
                && m_ObjectiveType != ObjectiveType.ExitWater
                && m_ObjectiveType != ObjectiveType.Unstuck)
            {
                m_FleeStallSince = m_BehaviorNow;
                m_FleeStallAnchor = m_BehaviorPosition;
                return BotBehaviorStatus.Failure;
            }
            // 0.2.2x7 (doc 16.13): a zombie on the bot or a flee standing
            // still with one close turns into a fight (SkaliaBotGunFeelX7).
            if (TryYieldFleeToFight(m_BehaviorPosition, m_BehaviorNow))
            {
                return BotBehaviorStatus.Failure;
            }
            // The water refuge is only a refuge once the bot swims: it goes
            // all the way in.
            if (m_BehaviorNow < m_ObjectiveExpiresAt
                && (m_ObjectivePosition - m_BehaviorPosition).GetHorizontalMagnitude()
                   > (m_RampPhase != 0
                      || (m_ObjectiveType == ObjectiveType.Flee
                          && (m_FleeingFromPlayerName == FireWaterFleeName
                              || m_FleeingFromPlayerName == CoverFleeName
                              || IsPvpSpotRunName(m_FleeingFromPlayerName)))
                       ? 1.2f
                       : 4f))
            {
                return BotBehaviorStatus.Running;
            }
            ClearObjective();
            return BotBehaviorStatus.Failure;
        }

        private void EndFireFlee(float now, string reason)
        {
            m_FireFleeActive = false;
            m_FireFleeEndedAt = now;
            m_FireWaterRefugeUntil = 0f;
            if (m_ObjectiveType == ObjectiveType.Flee
                && (m_FleeingFromPlayerName == "zumbi de fogo" || m_FleeingFromPlayerName == FireWaterFleeName))
            {
                ClearObjective();
            }
            if (m_ObjectiveType == ObjectiveType.Combat && m_TargetZombie != null && m_TargetZombie == m_FireLastResortZombie)
            {
                ClearObjective();
            }
            m_FireLastResortZombie = null;
            BotLog(LogLevel.Information,
                "Fuga do zumbi de fogo concluida ({Reason}); vida {Health}, stamina {Stamina}.",
                reason,
                m_Player.life.health,
                m_Player.life.stamina);
            // 0.1.173: right after the flee the bot no longer turns back to
            // fight what it ran from: 20s of only an isolated zombie after it,
            // none within 20m of the burner, loot and patrol away from it.
            var fire = m_FireFleeZombie;
            m_FireFleeZombie = null;
            if (fire != null && !fire.isDead && fire.gameObject.activeInHierarchy)
            {
                StartDisengage(fire.transform.position, "fugir do zumbi de fogo", now, fire);
            }
        }

        private static bool CanZombieSee(Zombie zombie, Vector3 position)
        {
            return !Physics.Linecast(
                zombie.transform.position + Vector3.up * 1.5f,
                position + Vector3.up * 1.5f,
                RayMasks.BLOCK_COLLISION,
                QueryTriggerInteraction.Ignore);
        }

        // A point 20-35m farther from the burner, preferring one behind cover
        // and away from other zombies.
        private const float FireEscapePathMeters = 4f;
        private const float FireEscapeHunterPathMeters = 3f;
        private readonly List<Zombie> m_EscapeZombies = new List<Zombie>();

        // Leaving a burner the bot cannot fight: the place stays off limits
        // for a while, and a trip already heading there stops. At 15:19 in
        // the 0.1.141 test Tadeu "left" the area, but his trip to Vorkuta
        // Junction went on; he accepted it 10s later and died there.
        private readonly List<KeyValuePair<Vector3, float>> m_FireAvoidZones = new List<KeyValuePair<Vector3, float>>();

        private void AvoidFireArea(Vector3 firePosition, float seconds)
        {
            var realNow = Time.realtimeSinceStartup;
            m_FireAvoidZones.RemoveAll(zone => realNow >= zone.Value);
            m_FireAvoidZones.Add(new KeyValuePair<Vector3, float>(firePosition, realNow + seconds));
            m_PendingMeshAreaKey = string.Empty;
            if (m_TravelActive && (m_TravelTarget - firePosition).GetHorizontalMagnitude() <= DangerZoneAreaMeters)
            {
                BotLog(LogLevel.Information,
                    "Viagem ate {Name} cancelada: o destino fica a {Distance:0}m do zumbi de fogo que o bot esta deixando.",
                    m_TravelTargetName,
                    (m_TravelTarget - firePosition).GetHorizontalMagnitude());
                m_TravelActive = false;
                m_TravelPhase = 0;
                m_TravelMeshArea = false;
                if (m_ObjectiveType == ObjectiveType.Travel)
                {
                    ClearObjective();
                }
            }
        }

        private bool TryFindFireEscapePoint(Vector3 position, Zombie fire, float now, out Vector3 escapePoint)
        {
            escapePoint = position;
            var firePosition = fire.transform.position;
            var away = position - firePosition;
            away.y = 0f;
            if (away.sqrMagnitude < 0.01f)
            {
                away = Quaternion.Euler(0f, m_CurrentYaw, 0f) * Vector3.forward;
            }
            away.Normalize();
            var fireDistance = (firePosition - position).GetHorizontalMagnitude();
            m_EscapeZombies.Clear();
            if (ZombieManager.regions != null)
            {
                foreach (var region in ZombieManager.regions)
                {
                    if (region?.zombies == null)
                    {
                        continue;
                    }
                    foreach (var zombie in region.zombies)
                    {
                        if (zombie != null
                            && !zombie.isDead
                            && (zombie.transform.position - position).GetHorizontalMagnitude() <= 45f
                            && Mathf.Abs(zombie.transform.position.y - position.y) <= 8f)
                        {
                            m_EscapeZombies.Add(zombie);
                        }
                    }
                }
            }
            m_EscapeCandidates.Clear();
            for (var radius = 20f; radius <= 35f; radius += 15f)
            {
                for (var offsetStep = 0; offsetStep <= 6; offsetStep++)
                {
                    var angle = (offsetStep % 2 == 0 ? 1f : -1f) * ((offsetStep + 1) / 2) * 25f;
                    AddFireEscapeCandidate(position, fire, firePosition, away, fireDistance, radius, angle, now);
                }
            }
            // 0.1.173: everything ahead blocked (the 0.1.172 night had 9
            // flees with no point at all): try the sides before giving up.
            if (m_EscapeCandidates.Count == 0)
            {
                for (var radius = 20f; radius <= 35f; radius += 15f)
                {
                    AddFireEscapeCandidate(position, fire, firePosition, away, fireDistance, radius, 100f, now);
                    AddFireEscapeCandidate(position, fire, firePosition, away, fireDistance, radius, -100f, now);
                    AddFireEscapeCandidate(position, fire, firePosition, away, fireDistance, radius, 110f, now);
                    AddFireEscapeCandidate(position, fire, firePosition, away, fireDistance, radius, -110f, now);
                }
            }
            if (m_EscapeCandidates.Count == 0)
            {
                return false;
            }
            // The real route, not the straight line: the best three are
            // checked against every zombie near, the burner included.
            m_EscapeThreatPoints.Clear();
            foreach (var other in m_EscapeZombies)
            {
                if (other != null && !other.isDead)
                {
                    m_EscapeThreatPoints.Add(other.transform.position);
                }
            }
            return PickEscapeCandidateByRoute(
                position,
                m_EscapeThreatPoints,
                FireEscapeHunterPathMeters,
                FireEscapePathMeters,
                25f,
                0f,
                out escapePoint);
        }

        private void AddFireEscapeCandidate(
            Vector3 position,
            Zombie fire,
            Vector3 firePosition,
            Vector3 away,
            float fireDistance,
            float radius,
            float angle,
            float now)
        {
            var candidate = FindNearestNavigablePoint(
                position + Quaternion.Euler(0f, angle, 0f) * away * radius);
            var fromBot = (candidate - position).GetHorizontalMagnitude();
            var fromFire = (candidate - firePosition).GetHorizontalMagnitude();
            if (fromBot < 10f
                || fromFire < fireDistance + 8f
                || Mathf.Abs(candidate.y - position.y) > 8f
                || WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                || CrossesWater(position, candidate)
                || IsHazardousPosition(candidate, now, 2f))
            {
                return;
            }
            var score = fromFire - Mathf.Abs(angle) * 0.1f;
            if (!CanZombieSee(fire, candidate))
            {
                score += 15f;
            }
            if (IsInHordeMemory(candidate, HordeAvoidMeters))
            {
                score -= 20f;
            }
            // The way there counts, not only where it ends: in the
            // 0.1.135 test 6 of 13 deaths came seconds after fleeing
            // the fire zombie, killed by ordinary zombies the flight
            // ran through (Tadeu: 4 within 4m, 88 health gone in 2s).
            // Every zombie near, not only those seen and hunting: in
            // the 0.1.141 test Tadeu and thigas fled the burner at
            // full health at Vorkuta Junction past idle zombies that
            // woke up as they ran by, and died in about 2s with 5
            // zombies within 4m.
            var straightPenalty = 0f;
            var nearEnd = 0;
            var crowd = 0;
            foreach (var other in m_EscapeZombies)
            {
                if (other == null || other == fire || other.isDead)
                {
                    continue;
                }
                var otherPosition = other.transform.position;
                var fromCandidate = (otherPosition - candidate).GetHorizontalMagnitude();
                // 0.1.173: a point with 3+ zombies within 15m is not an
                // escape (the 0.1.172 flees ended next to groups).
                if (fromCandidate <= 15f && ++crowd >= 3)
                {
                    return;
                }
                if (fromCandidate <= 8f)
                {
                    score -= 20f;
                    if (++nearEnd >= 2)
                    {
                        return;
                    }
                }
                var fromPath = GetHorizontalDistanceToSegment(otherPosition, position, candidate);
                if (fromPath <= FireEscapeHunterPathMeters)
                {
                    straightPenalty = float.PositiveInfinity;
                }
                else if (fromPath <= FireEscapePathMeters)
                {
                    straightPenalty += 25f;
                }
            }
            m_EscapeCandidates.Add(new EscapeCandidate
            {
                Point = candidate,
                Score = score,
                StraightPenalty = straightPenalty
            });
        }

        private BotBehaviorStatus TickFireZombieBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            if (TryFindFireThreat(position, FireZombieVisualRadiusMeters, out var threatFire))
            {
                var threatDistance = (threatFire.transform.position - position).GetHorizontalMagnitude();
                if (m_FireFleeActive || ShouldStartFireFlee(threatFire, threatDistance, position, now))
                {
                    return TickFireFlee(threatFire, position, now);
                }
            }
            else if (m_FireFleeActive)
            {
                EndFireFlee(now, "zumbi de fogo sumiu");
                return BotBehaviorStatus.Failure;
            }
            if (TryPreferHuntingNormalZombie(position, now))
            {
                return BotBehaviorStatus.Running;
            }
            if (TryFindNearestFireZombie(
                    position,
                    FireZombieVisualRadiusMeters,
                    out var observedFireZombie)
                && (observedFireZombie != m_IgnoredFireZombie
                    || now >= m_IgnoreFireZombieUntil))
            {
                if (m_RememberedFireZombie != observedFireZombie)
                {
                    m_RememberedFireZombie = observedFireZombie;
                    m_FireZombieWeaponSearchExpiresAt = now
                        + FireZombieWeaponSearchSeconds;
                    BotLog(LogLevel.Information,
                        "Bot marcou zumbi de fogo em {Position} como ameaca prioritaria.",
                        FormatPosition(observedFireZombie.transform.position));
                }
            }
            if (m_RememberedFireZombie == null
                || m_RememberedFireZombie.isDead
                || !m_RememberedFireZombie.gameObject.activeInHierarchy
                || IsZombieMarkedUnreachable(m_RememberedFireZombie, now))
            {
                m_RememberedFireZombie = null;
                return BotBehaviorStatus.Failure;
            }

            if (HasLoadedRangedWeapon())
            {
                // Shooting at the fire zombie while ordinary zombies chew on
                // the bot got it killed; deal with whatever is in reach first.
                var keepRadius = IsTargetZombieAlive() && !IsFireZombie(m_TargetZombie!)
                    ? 6f
                    : 4f;
                if (TryFindNearestNormalZombie(position, keepRadius, out var closeZombie))
                {
                    if (m_TargetZombie != closeZombie && now >= m_NextFireMeleeLogAt)
                    {
                        m_NextFireMeleeLogAt = now + 5f;
                        BotLog(LogLevel.Information,
                            "Zumbi comum a {Distance:0.#}m; resolvendo no corpo a corpo antes de atirar no zumbi de fogo.",
                            (closeZombie.transform.position - position).GetHorizontalMagnitude());
                    }
                    ForceCombatTarget(closeZombie, now);
                    return BotBehaviorStatus.Running;
                }
                // Its death explosion turns every ordinary zombie within 4m
                // into a burner: with 2+ next to it, no shot.
                if (IsFireTooCrowdedToShoot(m_RememberedFireZombie, position))
                {
                    if (now >= m_NextFireCrowdLogAt)
                    {
                        m_NextFireCrowdLogAt = now + 10f;
                        BotLog(LogLevel.Information,
                            "Zumbi de fogo a {Distance:0.#}m com {Count} zumbis comuns a 4m dele; sem tiro (a explosao viraria todos em zumbis de fogo).",
                            (m_RememberedFireZombie.transform.position - position).GetHorizontalMagnitude(),
                            CountZombiesNear(m_RememberedFireZombie.transform.position, 4f, m_RememberedFireZombie, true));
                    }
                    if (m_TargetZombie == m_RememberedFireZombie)
                    {
                        m_TargetZombie = null;
                        if (m_ObjectiveType == ObjectiveType.Combat)
                        {
                            ClearObjective();
                        }
                    }
                    return BotBehaviorStatus.Failure;
                }
                SetCombatTarget(m_RememberedFireZombie, now);
                return BotBehaviorStatus.Running;
            }

            // 0.2.2x13: a blade, health and the burner alone: fight it.
            if (TryTryhardMeleeFire(m_RememberedFireZombie, position, now))
            {
                return BotBehaviorStatus.Running;
            }
            var fireDistance = (m_RememberedFireZombie.transform.position - position)
                .GetHorizontalMagnitude();
            // 0.1.173: a run for a gun only with health 50+, one burner, and
            // the gun farther from the burner than the bot is.
            var canRunForWeapon = CanRunForFireWeapon(position, out var weaponGateWhy);
            if (!canRunForWeapon)
            {
                LogFireWeaponGate(weaponGateWhy, now);
            }
            // Hysteresis: once repositioning, keep at it until 4m past the
            // avoid radius, so a bot near the edge doesn't swap between
            // Combat/Loot and RepositionFire several times per second.
            var avoidRadius = m_ObjectiveType == ObjectiveType.RepositionFire
                ? FireZombieAvoidRadiusMeters + 4f
                : FireZombieAvoidRadiusMeters;
            var meleeEngaged = m_ObjectiveType == ObjectiveType.Combat
                && IsTargetZombieAlive()
                && !IsFireZombie(m_TargetZombie!)
                && (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude() <= 4f;
            if (meleeEngaged && fireDistance > FireZombieMeleeReleaseMeters)
            {
                return BotBehaviorStatus.Failure;
            }
            if (fireDistance < avoidRadius)
            {
                // Running off first and looking only once 16-20m away sent
                // the bot into the fields: when there is something to shoot
                // with out of the burner's reach, the run goes there.
                if (m_ObjectiveType == ObjectiveType.Loot
                    && m_LootInstanceId == m_FireLootInstanceId
                    && !IsNearFireZombie(m_ObjectivePosition)
                    && canRunForWeapon
                    && IsFireWeaponItemSafe(m_ObjectivePosition, position))
                {
                    UpdateLootObjective(position, now);
                    return BotBehaviorStatus.Running;
                }
                if (canRunForWeapon
                    && now >= m_NextLootScanTime
                    && TryFindFireWeaponLoot(position, now, out var nearRegionX, out var nearRegionY, out var nearItem, out var nearAsset)
                    && IsFireWeaponItemSafe(nearItem.point, position))
                {
                    m_NextLootScanTime = now + 1f;
                    var nearDistance = (nearItem.point - position).GetHorizontalMagnitude();
                    if (nearItem.instanceID != m_FireLootTryId || now - m_FireLootTryFirstAt > 90f)
                    {
                        m_FireLootTryId = nearItem.instanceID;
                        m_FireLootTryFirstAt = now;
                        m_FireLootTryCount = 0;
                        m_FireLootTryBestDistance = nearDistance;
                    }
                    else if (nearDistance < m_FireLootTryBestDistance - 3f)
                    {
                        // Closer than on any earlier run: a swarm or a flee
                        // cut the run short, the item was not out of reach.
                        m_FireLootTryBestDistance = nearDistance;
                        m_FireLootTryCount = 0;
                    }
                    if (++m_FireLootTryCount > 3)
                    {
                        // Each run was called off (a zombie in the way, the
                        // burner too close) and picked again a second later:
                        // one bot ran 29 times for the same Paintball Gun
                        // 6-8m away in the 0.1.123 test.
                        IgnoreLoot(nearItem.instanceID, now + 120f);
                        BotLog(LogLevel.Information,
                            "Zumbi de fogo: desistindo de {Item} depois de 3 corridas sem pegar; ignorado por 2 min.",
                            nearAsset.itemName);
                        return BotBehaviorStatus.Running;
                    }
                    if (SetLootObjective(nearRegionX, nearRegionY, nearItem, now, true))
                    {
                        CommitFireWeapon(nearRegionX, nearRegionY, nearItem, now);
                        m_FireLootInstanceId = nearItem.instanceID;
                        BotLog(LogLevel.Information,
                            "Zumbi de fogo a {Fire:0}m: correndo para {Item} a {Distance:0}m em vez de so fugir.",
                            fireDistance,
                            nearAsset.itemName,
                            nearDistance);
                        return BotBehaviorStatus.Running;
                    }
                }
                if (m_ObjectiveType != ObjectiveType.RepositionFire
                    || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 2f)
                {
                    SetFireZombieRepositionObjective(position, now);
                }
                if (now >= m_NextFireZombieTacticalLogAt)
                {
                    m_NextFireZombieTacticalLogAt = now + 5f;
                    BotLog(LogLevel.Information,
                        "Bot correndo para longe do zumbi de fogo antes de procurar arma; distancia {Distance:0.##}m.",
                        fireDistance);
                }
                return BotBehaviorStatus.Running;
            }

            // Uma ameaca comum somente interrompe a busca da arma se ja estiver
            // em distancia imediata. Zumbis mais distantes nao removem a
            // prioridade tatica do burner.
            if (TryFindNearestZombie(position, out var immediateZombie)
                && (immediateZombie.transform.position - position)
                   .GetHorizontalMagnitude() <= (m_ObjectiveType == ObjectiveType.Combat ? 10f : 6f))
            {
                return BotBehaviorStatus.Failure;
            }

            if (m_ObjectiveType == ObjectiveType.Loot
                && (m_LootTargetIsRangedWeapon || m_LootInstanceId == m_FireLootInstanceId))
            {
                if (!canRunForWeapon || !IsFireWeaponItemSafe(m_ObjectivePosition, position))
                {
                    ClearObjective();
                }
                else if (IsNearFireZombie(m_ObjectivePosition))
                {
                    IgnoreLoot(m_LootInstanceId, now + FireLootIgnoreSeconds);
                    BotLog(LogLevel.Information,
                        "Arma em {Position} esta perto demais do zumbi de fogo; ignorada por {Seconds:0}s.",
                        FormatPosition(m_ObjectivePosition),
                        FireLootIgnoreSeconds);
                    ClearObjective();
                }
                else
                {
                    UpdateLootObjective(position, now);
                    return BotBehaviorStatus.Running;
                }
            }
            if (canRunForWeapon
                && now >= m_NextLootScanTime
                && TryGetCommittedFireWeapon(now, out var keptItem, out var keptAsset)
                && IsFireWeaponItemSafe(keptItem.point, position))
            {
                m_NextLootScanTime = now + 1f;
                if (SetLootObjective(m_FireWeaponTargetX, m_FireWeaponTargetY, keptItem, now, true))
                {
                    m_FireLootInstanceId = keptItem.instanceID;
                    if (now >= m_NextFireWeaponResumeLogAt)
                    {
                        m_NextFireWeaponResumeLogAt = now + 5f;
                        BotLog(LogLevel.Information,
                            "Zumbi de fogo: retomando {Item} a {Distance:0}m (escolhida ha {Seconds:0}s).",
                            keptAsset.itemName,
                            (keptItem.point - position).GetHorizontalMagnitude(),
                            now - m_FireWeaponTargetSince);
                    }
                    return BotBehaviorStatus.Running;
                }
            }
            if (canRunForWeapon
                && now >= m_NextLootScanTime
                && TryFindNearestLoot(
                    position,
                    now,
                    true,
                    out var rangedRegionX,
                    out var rangedRegionY,
                    out var rangedItem,
                    true)
                && !IsNearFireZombie(rangedItem.point)
                && !IsNearRecentFleeThreat(rangedItem.point, now)
                && IsFireWeaponItemSafe(rangedItem.point, position))
            {
                m_NextLootScanTime = now + 1f;
                if (SetLootObjective(rangedRegionX, rangedRegionY, rangedItem, now, true))
                {
                    CommitFireWeapon(rangedRegionX, rangedRegionY, rangedItem, now);
                    m_FireLootInstanceId = rangedItem.instanceID;
                    LogFireZombieWeaponSearch(now);
                    return BotBehaviorStatus.Running;
                }
            }
            if (canRunForWeapon
                && now >= m_NextLootScanTime
                && TryFindRememberedLoadedRangedLoot(
                    position,
                    now,
                    out var rememberedRegionX,
                    out var rememberedRegionY,
                    out var rememberedRangedItem)
                && !IsNearFireZombie(rememberedRangedItem.point)
                && !IsNearRecentFleeThreat(rememberedRangedItem.point, now)
                && IsFireWeaponItemSafe(rememberedRangedItem.point, position))
            {
                m_NextLootScanTime = now + 1f;
                if (SetLootObjective(
                        rememberedRegionX,
                        rememberedRegionY,
                        rememberedRangedItem,
                        now,
                        true))
                {
                    CommitFireWeapon(rememberedRegionX, rememberedRegionY, rememberedRangedItem, now);
                    m_FireLootInstanceId = rememberedRangedItem.instanceID;
                    BotLog(LogLevel.Information,
                        "Bot retornando a uma arma de alcance memorizada em {Position} para enfrentar zumbi de fogo.",
                        FormatPosition(rememberedRangedItem.point));
                    return BotBehaviorStatus.Running;
                }
            }

            if (canRunForWeapon
                && now >= m_NextLootScanTime
                && TryFindFireWeaponLoot(position, now, out var fireRegionX, out var fireRegionY, out var fireItem, out var fireAsset)
                && IsFireWeaponItemSafe(fireItem.point, position))
            {
                m_NextLootScanTime = now + 1f;
                if (SetLootObjective(fireRegionX, fireRegionY, fireItem, now, true))
                {
                    CommitFireWeapon(fireRegionX, fireRegionY, fireItem, now);
                    m_FireLootInstanceId = fireItem.instanceID;
                    BotLog(LogLevel.Information,
                        "Zumbi de fogo: indo pegar {Item} a {Distance:0}m para ter com o que atirar.",
                        fireAsset.itemName,
                        (fireItem.point - position).GetHorizontalMagnitude());
                    return BotBehaviorStatus.Running;
                }
            }

            // Nothing to shoot with in 120m: walking "a safe strip" for 20s
            // only took the bot out into the fields (383 times in 2h16) and
            // then back to the same burner. Leave it and the area at once;
            // the loot of the next town is where a gun or ammo can turn up.
            if (now >= m_FireZombieWeaponSearchExpiresAt || now >= m_NextLootScanTime)
            {
                var abandoned = m_RememberedFireZombie;
                m_IgnoredFireZombie = abandoned;
                m_IgnoreFireZombieUntil = now + FireZombieReconsiderSeconds;
                m_RememberedFireZombie = null;
                if (m_ObjectiveType == ObjectiveType.RepositionFire)
                {
                    ClearObjective();
                }
                FinishInterestArea(now);
                AvoidFireArea(abandoned != null ? abandoned.transform.position : position, FireZombieReconsiderSeconds);
                m_NextExplorationSelectionTime = now;
                if (canRunForWeapon)
                {
                    BotLog(LogLevel.Information,
                        "Zumbi de fogo: nenhuma arma carregada nem municao para {Weapon} em {Radius:0}m; deixando o zumbi e a area {Area} por {Seconds:0}s.",
                        DescribeCarriedGun(),
                        FireWeaponSearchMeters,
                        m_HasInterestArea ? m_InterestAreaName : "atual",
                        FireZombieReconsiderSeconds);
                }
                else
                {
                    BotLog(LogLevel.Information,
                        "Zumbi de fogo: sem corrida atras de arma ({Why}); deixando o zumbi e a area {Area} por {Seconds:0}s.",
                        weaponGateWhy,
                        m_HasInterestArea ? m_InterestAreaName : "atual",
                        FireZombieReconsiderSeconds);
                }
                return BotBehaviorStatus.Failure;
            }

            if (m_ObjectiveType != ObjectiveType.RepositionFire
                || now >= m_ObjectiveExpiresAt
                || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 3f)
            {
                SetFireZombieRepositionObjective(position, now);
            }
            if (now >= m_NextFireZombieTacticalLogAt)
            {
                m_NextFireZombieTacticalLogAt = now + 5f;
                BotLog(LogLevel.Information,
                    "Bot vasculhando uma faixa segura enquanto procura arma de alcance para o zumbi de fogo.");
            }
            return BotBehaviorStatus.Running;
        }

        private const float FireWeaponSearchMeters = 120f;
        private uint m_FireLootInstanceId;

        // 0.1.166: the nearest gun was chosen again on every scan, so each
        // step of a kite changed the target (thigas: Hawkhound 9m, Compound
        // Bow 27m, Hawkhound 25m, Crossbow 16m, Hawkhound 42m in 39s, none
        // picked up). The first choice is kept through any swarm or flee in
        // between until it is picked up or gone, for up to a minute, unless
        // another turns up at less than half the distance.
        private const float FireWeaponCommitSeconds = 60f;
        private uint m_FireWeaponTargetId;
        private byte m_FireWeaponTargetX = byte.MaxValue;
        private byte m_FireWeaponTargetY = byte.MaxValue;
        private float m_FireWeaponTargetSince;
        private float m_NextFireWeaponResumeLogAt;
        private float m_FireLootTryBestDistance;

        private void CommitFireWeapon(byte regionX, byte regionY, ItemData item, float now)
        {
            if (m_FireWeaponTargetId == item.instanceID)
            {
                return;
            }
            m_FireWeaponTargetId = item.instanceID;
            m_FireWeaponTargetX = regionX;
            m_FireWeaponTargetY = regionY;
            m_FireWeaponTargetSince = now;
        }

        private void ForgetFireWeapon()
        {
            m_FireWeaponTargetId = 0;
            m_FireWeaponTargetX = byte.MaxValue;
            m_FireWeaponTargetY = byte.MaxValue;
        }

        private bool TryGetCommittedFireWeapon(float now, out ItemData item, out ItemAsset asset)
        {
            item = null!;
            asset = null!;
            if (m_FireWeaponTargetId == 0)
            {
                return false;
            }
            if (now - m_FireWeaponTargetSince > FireWeaponCommitSeconds
                || IsLootIgnored(m_FireWeaponTargetId, now)
                || IsLootClaimedByAnotherBot(m_FireWeaponTargetId, now)
                || ItemManager.regions == null
                || !Regions.checkSafe(m_FireWeaponTargetX, m_FireWeaponTargetY))
            {
                ForgetFireWeapon();
                return false;
            }
            var region = ItemManager.regions[m_FireWeaponTargetX, m_FireWeaponTargetY];
            ItemData? found = null;
            if (region != null)
            {
                foreach (var candidate in region.items)
                {
                    if (candidate != null && candidate.instanceID == m_FireWeaponTargetId)
                    {
                        found = candidate;
                        break;
                    }
                }
            }
            var foundAsset = found != null
                ? Assets.find(EAssetType.ITEM, found.item.id) as ItemAsset
                : null;
            if (found == null || foundAsset == null)
            {
                ForgetFireWeapon();
                return false;
            }
            // Kept, not forgotten: the burner or the group may move away.
            if (IsNearFireZombie(found.point) || IsNearRecentFleeThreat(found.point, now))
            {
                return false;
            }
            item = found;
            asset = foundAsset;
            return true;
        }
        private readonly List<RegionCoordinate> m_FireSearchRegions = new List<RegionCoordinate>();

        // Something to shoot the burner with: a loaded gun, a gun the bot
        // carries a magazine for, or a magazine for a gun it carries. Up to
        // 120m and outside the interest area, but never near the burner.
        private bool TryFindFireWeaponLoot(
            Vector3 position,
            float now,
            out byte regionX,
            out byte regionY,
            out ItemData best,
            out ItemAsset bestAsset)
        {
            regionX = regionY = byte.MaxValue;
            best = null!;
            bestAsset = null!;
            if (ItemManager.regions == null)
            {
                return false;
            }
            m_FireSearchRegions.Clear();
            Regions.getRegionsInRadius(position, FireWeaponSearchMeters, m_FireSearchRegions);
            var bestDistance = FireWeaponSearchMeters * FireWeaponSearchMeters;
            foreach (var coordinate in m_FireSearchRegions)
            {
                var region = ItemManager.regions[coordinate.x, coordinate.y];
                if (region == null)
                {
                    continue;
                }
                foreach (var item in region.items)
                {
                    if (item == null)
                    {
                        continue;
                    }
                    var asset = Assets.find(EAssetType.ITEM, item.item.id) as ItemAsset;
                    if (asset == null
                        || !(asset is ItemGunAsset || (asset is ItemMagazineAsset && item.item.amount > 0)))
                    {
                        continue;
                    }
                    var offset = item.point - position;
                    var distance = offset.x * offset.x + offset.z * offset.z;
                    if (distance >= bestDistance
                        || Mathf.Abs(offset.y) > 12f
                        || IsNearFireZombie(item.point)
                        || IsNearRecentFleeThreat(item.point, now)
                        || IsLootIgnored(item.instanceID, now)
                        || IsLootClaimedByAnotherBot(item.instanceID, now)
                        || IsHazardousPosition(item.point, now, 2f)
                        || IsInRememberedIsland(item.point, now)
                        || !ShouldCollectLootAsset(asset, true, item.item.state, item.item.amount, item.item.quality))
                    {
                        continue;
                    }
                    if (asset is ItemGunAsset gun
                        && !IsLoadedGun(gun, item.item.state)
                        && !HasMagazineFor(gun))
                    {
                        continue;
                    }
                    bestDistance = distance;
                    best = item;
                    bestAsset = asset;
                    regionX = coordinate.x;
                    regionY = coordinate.y;
                }
            }
            if (TryGetCommittedFireWeapon(now, out var committed, out var committedAsset))
            {
                var keptOffset = committed.point - position;
                var keptDistance = keptOffset.x * keptOffset.x + keptOffset.z * keptOffset.z;
                if (best == null
                    || best.instanceID == committed.instanceID
                    || bestDistance >= keptDistance * 0.25f)
                {
                    best = committed;
                    bestAsset = committedAsset;
                    regionX = m_FireWeaponTargetX;
                    regionY = m_FireWeaponTargetY;
                }
            }
            return best != null;
        }

        private string DescribeCarriedGun()
        {
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var count = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < count; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemGunAsset gun)
                    {
                        return gun.itemName;
                    }
                }
            }
            return "nenhuma arma";
        }

        private bool IsNearFireZombie(Vector3 point)
        {
            return m_RememberedFireZombie != null
                && (m_RememberedFireZombie.transform.position - point).GetHorizontalMagnitude()
                   < FireZombieAvoidRadiusMeters;
        }

        // Points combat at this zombie and holds off the periodic rescan, which
        // would otherwise swap back to another (or a filtered-out) target.
        private void ForceCombatTarget(Zombie zombie, float now)
        {
            if (IsBossZombie(zombie) && !IsHuntedBoss(zombie))
            {
                return;
            }
            if (m_TargetZombie != zombie)
            {
                m_TargetZombie = zombie;
                m_CombatMovementPhase = CombatMovementPhase.Approach;
                m_CombatRetreatEndsAt = 0f;
                m_CombatRetreatPending = false;
                m_CombatAttackRecoveryUntil = 0f;
                m_CombatAttackFailsafeAt = 0f;
                m_MeleeBurstAttackCount = 0;
                m_MeleeBurstTargetCount = Random.Range(1, 3);
                m_CombatRetreatShouldSprint = false;
            }
            SetObjective(
                ObjectiveType.Combat,
                GetCombatDestination(m_BehaviorPosition, zombie),
                float.PositiveInfinity);
            m_NextZombieScanTime = now + 0.4f;
            m_ConsecutiveStuckChecks = 0;
        }

        // A burner that is not after the bot can wait: the bot went for it
        // while an ordinary zombie hunting it closed in from behind. Only a
        // burner within 3m, or one hunting the bot, keeps the priority.
        private float m_NextFirePreferNormalLogAt;
        private const float FirePreferNormalMeters = 20f;

        private bool TryPreferHuntingNormalZombie(Vector3 position, float now)
        {
            if (!TryFindNearestFireZombie(position, FireZombieVisualRadiusMeters, out var fire))
            {
                return false;
            }
            var fireDistance = (fire.transform.position - position).GetHorizontalMagnitude();
            if ((fire.isHunting && fire.player == m_Player) || fireDistance <= 3f)
            {
                return false;
            }
            Zombie? best = null;
            var bestDistance = FirePreferNormalMeters;
            var hasGun = HasLoadedRangedWeapon();
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                // 0.1.173: not one standing next to the burner (the bot would
                // walk up to it) nor one the window or a horde rules out.
                if (candidate == null
                    || candidate.isDead
                    || !candidate.gameObject.activeInHierarchy
                    || IsFireZombie(candidate)
                    || !(candidate.isHunting && candidate.player == m_Player)
                    || IsZombieMarkedUnreachable(candidate, now)
                    || (!hasGun && IsBaitNearFireZombie(candidate, fire, position))
                    || !IsCombatTargetAllowed(candidate, position, now, out _))
                {
                    continue;
                }
                var distance = (candidate.transform.position - position).GetHorizontalMagnitude();
                if (distance <= bestDistance)
                {
                    bestDistance = distance;
                    best = candidate;
                }
            }
            if (best == null)
            {
                return false;
            }
            if (m_TargetZombie != best && now >= m_NextFirePreferNormalLogAt)
            {
                m_NextFirePreferNormalLogAt = now + 5f;
                BotLog(LogLevel.Information,
                    "Zumbi de fogo a {Fire:0.#}m nao esta atras do bot; matando antes o zumbi comum a {Distance:0.#}m que esta.",
                    fireDistance,
                    bestDistance);
            }
            ForceCombatTarget(best, now);
            return true;
        }

        private bool TryFindNearestNormalZombie(Vector3 position, float maximumDistance, out Zombie zombie)
        {
            zombie = null!;
            var best = maximumDistance;
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                if (candidate == null
                    || candidate.isDead
                    || !candidate.gameObject.activeInHierarchy
                    || IsFireZombie(candidate)
                    || IsBossZombie(candidate)
                    || IsZombieMarkedUnreachable(candidate, m_BehaviorNow))
                {
                    continue;
                }
                var distance = (candidate.transform.position - position).GetHorizontalMagnitude();
                if (distance <= best)
                {
                    best = distance;
                    zombie = candidate;
                }
            }
            return zombie != null;
        }

        private void SetCombatTarget(Zombie zombie, float now)
        {
            if (IsBossZombie(zombie) && !IsHuntedBoss(zombie))
            {
                return;
            }
            var changedTarget = m_TargetZombie != zombie;
            m_TargetZombie = zombie;
            if (changedTarget)
            {
                m_CombatMovementPhase = CombatMovementPhase.Approach;
                m_CombatRetreatEndsAt = 0f;
                m_CombatRetreatPending = false;
                m_CombatAttackRecoveryUntil = 0f;
                m_CombatAttackFailsafeAt = 0f;
                BotLog(LogLevel.Information,
                    "Bot priorizando combate a distancia contra zumbi de fogo em {Position}.",
                    FormatPosition(zombie.transform.position));
            }
            SetObjective(
                ObjectiveType.Combat,
                GetCombatDestination(m_BehaviorPosition, zombie),
                float.PositiveInfinity);
            m_NextZombieScanTime = now + 0.4f;
            m_ConsecutiveStuckChecks = 0;
        }

        private void LogFireZombieWeaponSearch(float now)
        {
            if (now < m_NextFireZombieTacticalLogAt)
            {
                return;
            }
            m_NextFireZombieTacticalLogAt = now + 5f;
            BotLog(LogLevel.Information,
                "Bot detectou zumbi de fogo sem arma adequada e esta buscando uma arma de alcance carregada.");
        }

        private void SetFireZombieRepositionObjective(Vector3 position, float now)
        {
            if (m_RememberedFireZombie != null
                && TryFindConnectedRetreatPoint(
                    position,
                    m_RememberedFireZombie.transform.position,
                    now,
                    out var safeSearchPoint))
            {
                SetObjective(
                    ObjectiveType.RepositionFire,
                    safeSearchPoint,
                    now + 8f);
                return;
            }

            var threatPosition = m_RememberedFireZombie?.transform.position
                ?? position - Quaternion.Euler(0f, m_CurrentYaw, 0f) * Vector3.forward;
            var away = position - threatPosition;
            away.y = 0f;
            if (away.sqrMagnitude < 0.01f)
            {
                away = Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f)
                    * Vector3.forward;
            }
            // On a riverbank "away" is often the water: the bot left it and
            // stepped back in every second. Try the sides, else hold still.
            foreach (var angle in new[] { 0f, 45f, -45f, 90f, -90f })
            {
                var fallback = position
                    + Quaternion.Euler(0f, angle, 0f) * away.normalized * 5f;
                if (CrossesWater(position, fallback))
                {
                    continue;
                }
                SetObjective(
                    ObjectiveType.RepositionFire,
                    fallback,
                    now + 3f);
                m_DirectFallbackUntil = now + 3f;
                return;
            }
        }

        private BotBehaviorStatus TickAcquireCombatEquipmentBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            if (IsLadderInProgress())
            {
                // 0.2.2: the climb that leads to it goes on (doc 9.3).
                return BotBehaviorStatus.Running;
            }
            var unarmed = IsUnarmed();
            if (unarmed
                ? GetNearestLivingZombieDistance() <= UnarmedEngagementRadiusMeters && !IsGrabbingNearbyWeapon()
                : HasCompleteWeaponRoles()
                  || HasLootBlockingThreat(m_ObjectiveType == ObjectiveType.Loot && m_LootTargetIsCombatEquipment)
                  || GetNearestLivingZombieDistance() <= 6f)
            {
                return BotBehaviorStatus.Failure;
            }
            if (m_ObjectiveType == ObjectiveType.Loot
                && m_LootTargetIsCombatEquipment)
            {
                UpdateLootObjective(position, now);
                return BotBehaviorStatus.Running;
            }
            if (now >= m_NextLootScanTime
                && TryFindNearestLoot(
                    position,
                    now,
                    true,
                    out var regionX,
                    out var regionY,
                    out var item))
            {
                m_NextLootScanTime = now + 1f;
                SetLootObjective(regionX, regionY, item, now);
                return BotBehaviorStatus.Running;
            }
            return BotBehaviorStatus.Failure;
        }

        private BotBehaviorStatus TickCombatBehavior()
        {
            UpdateCombatObjective(m_BehaviorPosition, m_BehaviorNow);
            return m_ObjectiveType == ObjectiveType.Combat
                ? BotBehaviorStatus.Running
                : BotBehaviorStatus.Failure;
        }

        private BotBehaviorStatus TickLootBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            if (IsLadderInProgress())
            {
                return BotBehaviorStatus.Running;
            }
            var nearestZombieDistance = GetNearestLivingZombieDistance();
            if (IsDropPickupWindow())
            {
                if (m_ObjectiveType == ObjectiveType.Loot)
                {
                    UpdateLootObjective(position, now);
                    return BotBehaviorStatus.Running;
                }
                if (now < m_NextLootScanTime)
                {
                    // On the way to the Mega's body: keep that objective.
                    return Tryhard
                           && m_MegaDropPending
                           && m_ObjectiveType == ObjectiveType.Patrol
                           && (m_ObjectivePosition - m_DropPickupCenter).GetHorizontalMagnitude() <= 1f
                        ? BotBehaviorStatus.Running
                        : BotBehaviorStatus.Failure;
                }
                m_NextLootScanTime = now + 0.5f;
                if (m_MegaDropPending)
                {
                    if (TryFindLootAround(m_DropPickupCenter, MegaDropPileMeters, position, now,
                            out var megaRegionX, out var megaRegionY, out var megaItem)
                        && SetLootObjective(megaRegionX, megaRegionY, megaItem, now))
                    {
                        m_MegaDropPicked++;
                        return BotBehaviorStatus.Running;
                    }
                    // 0.1.0-y17.5: a pile in the open waits while another
                    // enemy is fresh news (SkaliaBotPvpMemoryY).
                    if (Tryhard && (IsPileInOpenAfterPvp(m_DropPickupCenter, now)
                        || IsLootInPvpEnemyLine(m_DropPickupCenter, "Monte " + m_DropPileName, now)))
                    {
                        if (m_ObjectiveType == ObjectiveType.Patrol
                            && (m_ObjectivePosition - m_DropPickupCenter).GetHorizontalMagnitude() <= 1f)
                        {
                            ClearObjective();
                        }
                        return BotBehaviorStatus.Failure;
                    }
                    // 0.2.2x (doc 15.2, item 13): nothing seen from here is
                    // not an empty pile; walk to the body and look there.
                    if (Tryhard && TryWalkToMegaPile(position, now))
                    {
                        return BotBehaviorStatus.Running;
                    }
                    if (Tryhard || now - m_LastKilledZombieAt >= 4f)
                    {
                        BotLog(LogLevel.Information,
                            "Drop {Pile}: {Count} item(ns) pego(s); nada mais que sirva a {Radius:0}m do corpo.",
                            m_DropPileName,
                            m_MegaDropPicked,
                            MegaDropPileMeters);
                        m_MegaDropPending = false;
                        m_MegaDropPicked = 0;
                        m_DropPickupUntil = 0f;
                    }
                    return BotBehaviorStatus.Failure;
                }
                if ((TryFindRememberedInterestingLoot(position, now, out var dropRegionX, out var dropRegionY, out var dropItem)
                        || TryFindNearestLoot(position, now, false, out dropRegionX, out dropRegionY, out dropItem))
                    && (dropItem.point - m_DropPickupCenter).GetHorizontalMagnitude() <= DropPickupRadiusMeters)
                {
                    BotLog(LogLevel.Information,
                        "Pegando drop do zumbi morto antes de voltar a lutar (zumbi mais perto a {Distance:0.#}m).",
                        nearestZombieDistance);
                    SetLootObjective(dropRegionX, dropRegionY, dropItem, now);
                    return BotBehaviorStatus.Running;
                }
                // Nothing worth taking near the body: back to normal. The drop
                // shows up a moment after the death, so give it 2.5s.
                if (now - m_LastKilledZombieAt >= 2.5f)
                {
                    m_DropPickupUntil = 0f;
                }
                return BotBehaviorStatus.Failure;
            }
            if (HasLootBlockingThreat(m_ObjectiveType == ObjectiveType.Loot))
            {
                if (m_ObjectiveType == ObjectiveType.Loot)
                {
                    ClearObjective();
                }
                return BotBehaviorStatus.Failure;
            }
            if (m_ObjectiveType == ObjectiveType.Loot)
            {
                if (!m_LootTargetIsCombatEquipment
                    && nearestZombieDistance <= LootCancelZombieMeters)
                {
                    ClearObjective();
                    return BotBehaviorStatus.Failure;
                }
                UpdateLootObjective(position, now);
                return BotBehaviorStatus.Running;
            }
            // 0.1.173: the item dropped because of a zombie is taken back
            // once it is dealt with, before searching anew.
            if (nearestZombieDistance > LootBlockZombieMeters && TryResumePendingLoot(now))
            {
                return BotBehaviorStatus.Running;
            }
            // 0.2.2t: everything around the bot first, in one pass. For a
            // moment after a pickup the bot stays on the pile: the piece it
            // just took is worn and the next item is looked for at once.
            if (IsLootPileActive(now) && nearestZombieDistance > LootBlockZombieMeters)
            {
                if (now >= m_NextLootScanTime)
                {
                    m_NextLootScanTime = now + 0.2f;
                    if (TryFindPileLoot(position, now, out var pileRegionX, out var pileRegionY, out var pileItem)
                        && SetLootObjective(pileRegionX, pileRegionY, pileItem, now))
                    {
                        return BotBehaviorStatus.Running;
                    }
                }
                return BotBehaviorStatus.Running;
            }
            if (now < m_NextLootScanTime
                || nearestZombieDistance <= LootBlockZombieMeters)
            {
                return BotBehaviorStatus.Failure;
            }

            m_NextLootScanTime = now + 2f;
            if (Tryhard
                && TryFindPileLoot(position, now, out var nearRegionX, out var nearRegionY, out var nearItem)
                && SetLootObjective(nearRegionX, nearRegionY, nearItem, now))
            {
                return BotBehaviorStatus.Running;
            }
            if (!TryFindRememberedInterestingLoot(
                    position,
                    now,
                    out var regionX,
                    out var regionY,
                    out var item)
                && !TryFindNearestLoot(
                    position,
                    now,
                    false,
                    out regionX,
                    out regionY,
                    out item))
            {
                return BotBehaviorStatus.Failure;
            }
            SetLootObjective(regionX, regionY, item, now);
            return BotBehaviorStatus.Running;
        }

        private BotBehaviorStatus TickExplorationBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            // Reaching exploration means combat did not win this tick. A combat
            // objective left behind (its target died or is out of reach) never
            // expires on its own, so drop it instead of standing on the spot.
            if (TickLowHealthRest(position, now))
            {
                return BotBehaviorStatus.Running;
            }
            if (m_ObjectiveType == ObjectiveType.Combat)
            {
                BotLog(LogLevel.Information,
                    "Objetivo de combate sem alvo valido descartado em {Position} (alvo vivo {TargetAlive}); voltando a explorar. "
                    + "Motivo: utilidade de combate {Utility:0}, drop {Drop}, tratamento {Treatment}, cautela de horda {Horde}, "
                    + "fuga em grupo {GroupFlee}, alvo a {Distance:0.#}m de {Radius:0.#}m.",
                    FormatPosition(position),
                    IsTargetZombieAlive(),
                    GetCombatUtility(),
                    IsDropPickupWindow(),
                    m_TreatmentPhase,
                    IsHordeCaution(),
                    m_UnarmedGroupFlee,
                    IsTargetZombieAlive()
                        ? (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude()
                        : -1f,
                    IsTargetZombieAlive() ? GetCautionEngagementRadius(m_TargetZombie!) : -1f);
                ClearObjective();
            }
            // 0.2.2: a look at the area from a high point first (SkaliaBotTactics).
            if (TickAreaOverlook(position, now))
            {
                return BotBehaviorStatus.Running;
            }
            if (m_ObjectiveType == ObjectiveType.Travel)
            {
                UpdateTerrainTravel(position, now);
            }
            else if (m_ObjectiveType == ObjectiveType.OpenDoor)
            {
                UpdateDoorApproach(position, now);
            }
            else if (m_ObjectiveType == ObjectiveType.Explore
                && (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 10f)
            {
                ChooseAreaPatrolObjective(position, now);
            }
            else if (m_ObjectiveType == ObjectiveType.Patrol
                     && ((m_ObjectivePosition - position).GetHorizontalMagnitude() <= 5f
                         || now >= m_ObjectiveExpiresAt))
            {
                ChooseAreaPatrolObjective(position, now);
            }

            if (m_ObjectiveType != ObjectiveType.None && now >= m_ObjectiveExpiresAt)
            {
                AbandonCurrentObjective(now);
            }
            if (m_ObjectiveType != ObjectiveType.None)
            {
                return BotBehaviorStatus.Running;
            }
            if (now < m_NextExplorationSelectionTime)
            {
                return BotBehaviorStatus.Running;
            }
            if (m_ForceLocalExplorationOnNextSelection && TryStartOffMeshTravel(position, now))
            {
                m_ForceLocalExplorationOnNextSelection = false;
            }
            else if (m_ForceLocalExplorationOnNextSelection)
            {
                m_ForceLocalExplorationOnNextSelection = false;
                ChooseLocalExplorationObjective(
                    position,
                    now,
                    "a ultima solicitacao de rota falhou");
            }
            else if (m_HasInterestArea && now < m_InterestAreaExpiresAt)
            {
                ChooseAreaPatrolObjective(position, now);
            }
            else
            {
                ChooseExplorationObjective(position, now);
            }
            return BotBehaviorStatus.Running;
        }

        private void UpdateExitWaterState(Vector3 position, float now)
        {
            if (m_ObjectiveType == ObjectiveType.ExitWater
                && now < m_ObjectiveExpiresAt)
            {
                if (!m_SwimExitActive)
                {
                    return;
                }
                var distance = (m_ObjectivePosition - position).GetHorizontalMagnitude();
                if (distance < m_SwimExitBestDistance - 0.75f)
                {
                    m_SwimExitBestDistance = distance;
                    m_SwimExitProgressSince = now;
                    return;
                }
                if (now - m_SwimExitProgressSince < 12f)
                {
                    return;
                }
                m_FailedSwimExits.Add(m_ObjectivePosition);
                BotLog(LogLevel.Information,
                    "Saida da agua por {Position} sem progresso a {Distance:0.#}m; procurando outra margem.",
                    FormatPosition(m_ObjectivePosition),
                    distance);
            }

            if (TryFindSwimExitPoint(position, out var shallows, out var land))
            {
                m_SwimExitActive = true;
                m_SwimExitShallows = shallows;
                m_SwimExitBestDistance = (land - position).GetHorizontalMagnitude();
                m_SwimExitProgressSince = now;
                SetObjective(ObjectiveType.ExitWater, land, now + 45f);
                BotLog(LogLevel.Information,
                    "Bot nadando ate uma margem baixa em {Position} ({Distance:0.#}m).",
                    FormatPosition(land),
                    m_SwimExitBestDistance);
                return;
            }
            m_SwimExitActive = false;
            SetExitWaterObjective(position, now, false);
        }

        // Swims out like a player: look for a bank that slopes into the water
        // (shallow ground 2m before dry land), not just the nearest navmesh
        // node, which often sits on top of a bank too steep to climb.
        private bool TryFindSwimExitPoint(Vector3 position, out Vector3 shallows, out Vector3 land)
        {
            shallows = position;
            land = position;
            WaterUtility.getUnderwaterInfo(position + Vector3.up * 0.5f, out var underwater, out var surface);
            if (!underwater)
            {
                return false;
            }
            // Under the bridge the bank search below gave up ("no free ground
            // near the exit") with a bank in reach; the new mesh knows every
            // climbable bank around.
            if (SkaliaBotUnityNavmesh.TryFindShore(position, surface, IsFailedSwimExit, out var meshLand))
            {
                var toLand = meshLand - position;
                toLand.y = 0f;
                var swimDirection = toLand.sqrMagnitude > 0.01f ? toLand.normalized : Vector3.forward;
                var swimLine = new Vector3(meshLand.x, surface + 0.3f, meshLand.z) - swimDirection * 2f;
                if (!Physics.Linecast(
                        new Vector3(position.x, surface + 0.3f, position.z),
                        swimLine,
                        SwimExitGroundMask,
                        QueryTriggerInteraction.Ignore))
                {
                    shallows = new Vector3(swimLine.x, surface, swimLine.z);
                    land = meshLand;
                    return true;
                }
            }
            for (var radius = 3f; radius <= 90f; radius += 3f)
            {
                for (var angle = 0; angle < 360; angle += 15)
                {
                    var direction = Quaternion.Euler(0f, angle, 0f) * Vector3.forward;
                    var edge = position + direction * radius;
                    if (!TryGetGroundHeight(edge, surface, out var landY)
                        || landY < surface + 0.05f
                        || IsFailedSwimExit(edge))
                    {
                        continue;
                    }
                    // Under a bridge the ray from above lands on the deck, 2m
                    // over the water: the bot swam circles below it for a
                    // minute. The shallows must be water and the bank low
                    // enough to climb out onto.
                    var shallow = edge - direction * 2f;
                    if (landY > surface + 1.3f
                        || !TryGetGroundHeight(shallow, surface, out var shallowY)
                        || shallowY < surface - 1.1f
                        || shallowY > surface + 0.3f
                        || landY - shallowY > 1.4f)
                    {
                        continue;
                    }
                    var lineHeight = Mathf.Max(surface, shallowY) + 0.3f;
                    if (Physics.Linecast(
                            new Vector3(position.x, lineHeight, position.z),
                            new Vector3(shallow.x, lineHeight, shallow.z),
                            SwimExitGroundMask,
                            QueryTriggerInteraction.Ignore))
                    {
                        continue;
                    }
                    shallows = new Vector3(shallow.x, shallowY, shallow.z);
                    var inland = edge + direction * 1.5f;
                    land = TryGetGroundHeight(inland, surface, out var inlandY) && inlandY >= surface
                        ? new Vector3(inland.x, inlandY, inland.z)
                        : new Vector3(edge.x, landY, edge.z);
                    return true;
                }
            }
            return false;
        }

        private static bool TryGetGroundHeight(Vector3 point, float surface, out float height)
        {
            height = 0f;
            if (!Physics.Raycast(
                    new Vector3(point.x, surface + 40f, point.z),
                    Vector3.down,
                    out var hit,
                    140f,
                    SwimExitGroundMask,
                    QueryTriggerInteraction.Ignore))
            {
                return false;
            }
            height = hit.point.y;
            return true;
        }

        private bool IsFailedSwimExit(Vector3 point)
        {
            if (Time.realtimeSinceStartup < m_PocketSwimUntil
                && (point - m_PocketSwimFrom).GetHorizontalMagnitude() < 40f)
            {
                return true;
            }
            foreach (var failed in m_FailedSwimExits)
            {
                if ((failed - point).GetHorizontalMagnitude() < 6f)
                {
                    return true;
                }
            }
            return false;
        }

        private void SetExitWaterObjective(Vector3 position, float now, bool forceDifferent)
        {
            m_SwimExitActive = false;
            var shore = FindNearestDryNavigablePoint(
                position,
                forceDifferent ? m_ObjectivePosition : (Vector3?)null);
            SetObjective(ObjectiveType.ExitWater, shore, now + 25f);
        }

        private void EnterUnstuckState(Vector3 position, float now)
        {
            if (m_LocalRecoveryPhase != LocalRecoveryPhase.None)
            {
                return;
            }
            if (TryFightBlockingZombie(position, 4f, now, "antes da manobra"))
            {
                return;
            }

            if (now - m_LastRecoveryAt <= 35f
                && (position - m_LastRecoveryAnchor).GetHorizontalMagnitude() <= 5f)
            {
                m_RepeatedRecoveryCount++;
            }
            else
            {
                m_RepeatedRecoveryCount = 1;
            }
            m_LastRecoveryAnchor = position;
            m_LastRecoveryAt = now;

            m_SuspendedObjectiveType = m_ObjectiveType;
            m_SuspendedObjectivePosition = m_ObjectivePosition;
            m_SuspendedObjectiveRemaining = float.IsPositiveInfinity(m_ObjectiveExpiresAt)
                ? float.PositiveInfinity
                : Mathf.Max(5f, m_ObjectiveExpiresAt - now);
            m_LocalRecoveryStartPosition = position;
            m_LocalRecoveryOriginalYaw = m_CurrentYaw;
            m_LocalRecoveryStartedInWater = m_Player.stance.stance == EPlayerStance.SWIM
                || WaterUtility.isPointUnderwater(position + Vector3.up * 0.5f);
            m_LocalRecoveryCandidateFound = false;
            m_LocalRecoveryCandidatePosition = position;
            m_LocalRecoveryCandidateYaw = m_CurrentYaw;
            m_ObjectiveType = ObjectiveType.Unstuck;
            m_ObjectivePosition = position;
            m_ObjectiveExpiresAt = float.PositiveInfinity;
            m_ConsecutiveStuckChecks = 0;
            ClearPath();
            BeginLocalRecoveryPhase(LocalRecoveryPhase.Stop, position, now);
            m_StatRecoveries++;
            m_StatWindowRecoveries++;
            BotLog(LogLevel.Information,
                "Navegacao suspensa no ponto {Position}; iniciando recuperacao fisica local. "
                + "Objetivo anterior {PreviousObjective}; agua {InWater}.",
                FormatPosition(position),
                m_SuspendedObjectiveType,
                m_LocalRecoveryStartedInWater);
        }

        private byte GetCurrentMovementAnalog()
        {
            // 0.2.2y: planted while shooting back at a player.
            if (TryGetPvpAnalog(out var pvpAnalog))
            {
                return pvpAnalog;
            }
            if (m_LocalRecoveryPhase != LocalRecoveryPhase.None)
            {
                return m_LocalRecoveryAnalog;
            }
            if (m_BoulderDodgePhase != 0)
            {
                return m_BoulderDodgeAnalog;
            }
            if (m_CrowdDodgeActive)
            {
                return m_CrowdDodgeAnalog;
            }
            if (!m_IsWalking)
            {
                // 0.2.2x7: the step after a kill (ApplyPostKillLook).
                return m_PostKillStepNow;
            }
            return (m_ObjectiveType == ObjectiveType.Combat
                    || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                   && IsTargetZombieAlive()
                ? m_CombatMovementAnalog
                : m_NavigationAnalog;
        }

        // Only walking forward while turning at a fixed rate draws a
        // curve about 3m wide at a run: a corner 1-2m to the side sits inside
        // it and the bot circles it. Like SAIN, step toward the target in
        // whichever of the 8 directions is closest while the body turns, and
        // stop running 1.5m before it.
        private byte m_NavigationAnalog = 0x12;

        // 0.1.170: a hand on a mouse turns fast on a big turn and slows on
        // the last degrees. The fixed 120 deg/s took 1.5s to turn round,
        // swung at the same speed on 5 degrees and on 150, and made every
        // corner a stop. Each bot gets its own hand; the config value
        // scales it (120 = as tuned). Aiming at a zombie is a bit slower.
        private bool m_TurnStyleSet;
        private float m_TurnEase = 6f;
        private float m_TurnMax = 330f;
        private float m_NextWalkPitchAt;
        private float m_WalkPitchOffset;

        // 0.2.1: the view is advanced once per FixedUpdate (UpdateMovementIntent
        // runs every frame; packets go out every SAMPLES frames), so the step is
        // one fixed frame, not PlayerInput.RATE (a whole packet). Using RATE made
        // every turn 4x faster than the configured degrees per second.
        private static float TurnStepSeconds => Time.fixedDeltaTime;
        // Local unstuck turns 90-180 degrees inside 0.7 s phases; ladders face
        // the rungs. Both keep a quick but human turn even with a slow config.
        private const float RecoveryTurnDegreesPerSecond = 360f;
        private const float LadderTurnDegreesPerSecond = 240f;

        private float GetHumanTurnSpeed(float delta, bool aiming)
        {
            if (!s_Settings.HumanTurning)
            {
                return m_TurnSpeedDegreesPerSecond;
            }
            if (!m_TurnStyleSet)
            {
                m_TurnStyleSet = true;
                m_TurnEase = Random.Range(4.5f, 7f);
                // 0.2.2x1: the players' peak in a turn of 60 degrees or more
                // is 360-660 deg/s (median 490); the start eases in (ApplyTurnRamp).
                m_TurnMax = Random.Range(360f, 540f);
                m_TurnAccel = Random.Range(1800f, 3000f);
            }
            var max = aiming ? m_TurnMax * 0.75f : m_TurnMax;
            return Mathf.Clamp(delta * m_TurnEase, 35f, max)
                * (m_TurnSpeedDegreesPerSecond / 120f);
        }

        private void UpdateNavigationAnalog(Vector3 position, Vector3 navigationTarget)
        {
            m_NavigationAnalog = 0x12;
            // 0.2.2x15: sideways onto the ladder's line (SkaliaBotLadderX15).
            if (m_ObjectiveType == ObjectiveType.Ladder && m_LadderStrafeAnalog != 0)
            {
                m_NavigationAnalog = m_LadderStrafeAnalog;
                return;
            }
            var wanted = navigationTarget - position;
            wanted.y = 0f;
            if (m_ObjectiveType == ObjectiveType.None
                || ((m_ObjectiveType == ObjectiveType.Combat || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                    && IsTargetZombieAlive())
                || m_ObjectiveType == ObjectiveType.Ladder
                || m_ObjectiveType == ObjectiveType.ExitWater
                || m_Player.stance.stance == EPlayerStance.SWIM
                || wanted.sqrMagnitude < 0.04f)
            {
                return;
            }
            if (wanted.magnitude < 1.5f)
            {
                m_IsSprinting = false;
            }
            var direction = wanted.normalized;
            if (Vector3.Angle(GetWorldMovementDirection(0x12, m_CurrentYaw), direction) <= 25f)
            {
                return;
            }
            var best = 0x12;
            var bestDot = float.MinValue;
            foreach (var candidate in s_CombatMovementCandidates)
            {
                var dot = Vector3.Dot(GetWorldMovementDirection(candidate, m_CurrentYaw), direction);
                if (dot > bestDot)
                {
                    bestDot = dot;
                    best = candidate;
                }
            }
            m_NavigationAnalog = (byte)best;
            // 0.2.2x11: the sprint works in all 8 directions (the tester tested;
            // PlayerStance.simulate only needs the body moving, stamina and
            // no aim with a gun that cannot aim sprinting). It used to stop
            // here on any key but W and the W diagonals.
        }

        private void RecordBreadcrumb(Vector3 position, float now)
        {
            if (now < m_NextBreadcrumbAt)
            {
                return;
            }
            m_NextBreadcrumbAt = now + 0.5f;
            if (m_Player.stance.stance == EPlayerStance.SWIM
                || (m_Breadcrumbs.Count > 0
                    && (m_Breadcrumbs[m_Breadcrumbs.Count - 1] - position).GetHorizontalMagnitude() < 1f))
            {
                return;
            }
            m_Breadcrumbs.Add(position);
            if (m_Breadcrumbs.Count > BreadcrumbCount)
            {
                m_Breadcrumbs.RemoveAt(0);
            }
        }

        // The most recent spot it walked through, 2.5-12m back, with a clear
        // way there: it came that way, so it can go back that way.
        private bool TryStartCombatBacktrack(Vector3 position, float now)
        {
            if (now - m_LastBacktrackAt > 20f)
            {
                m_BacktrackCount = 0;
            }
            if (m_BacktrackCount >= 3)
            {
                return false;
            }
            for (var i = m_Breadcrumbs.Count - 1; i >= 0; i--)
            {
                var crumb = m_Breadcrumbs[i];
                var back = crumb - position;
                back.y = 0f;
                var distance = back.magnitude;
                if (distance < 2.5f
                    || distance > 12f
                    || Mathf.Abs(crumb.y - position.y) > 2f
                    || IsHazardousPosition(crumb, now, 1.5f)
                    || IsBodyRouteBlocked(position, back / distance, Mathf.Min(distance, 3f))
                    || Physics.Linecast(
                        position + Vector3.up * 0.9f,
                        crumb + Vector3.up * 0.9f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    continue;
                }
                m_BacktrackPoint = crumb;
                m_BacktrackUntil = now + 2.5f;
                m_BacktrackCount++;
                m_LastBacktrackAt = now;
                return true;
            }
            return false;
        }

        private bool ApplyCombatBacktrack(Vector3 position, float now)
        {
            if (now >= m_BacktrackUntil)
            {
                return false;
            }
            var back = m_BacktrackPoint - position;
            back.y = 0f;
            if (back.magnitude <= 0.8f)
            {
                m_BacktrackUntil = 0f;
                ClearPath();
                return false;
            }
            back.Normalize();
            var bestAnalog = (byte)0x11;
            var bestDot = -2f;
            foreach (var analog in s_CombatMovementCandidates)
            {
                var dot = Vector3.Dot(GetWorldMovementDirection(analog, m_DesiredYaw), back);
                if (dot > bestDot)
                {
                    bestDot = dot;
                    bestAnalog = analog;
                }
            }
            m_CombatMovementAnalog = bestAnalog;
            m_CombatShouldSprint = false;
            m_NextCombatSteeringAt = now + 0.2f;
            return true;
        }

        private void UpdateCombatSteering(
            Vector3 position,
            Vector3 navigationTarget,
            float combatDistance,
            float attackDistance,
            float now)
        {
            if ((m_ObjectiveType != ObjectiveType.Combat
                 && m_ObjectiveType != ObjectiveType.EscapeSwarm)
                || !IsTargetZombieAlive())
            {
                m_CombatMovementAnalog = 0x12;
                m_CombatShouldSprint = false;
                m_BacktrackUntil = 0f;
                return;
            }
            if (ApplyCombatBacktrack(position, now))
            {
                return;
            }
            if (ShouldTryhardHoldFire(position, combatDistance, attackDistance))
            {
                // 0.2.2x (doc 15.2, item 1): stand and shoot.
                m_CombatMovementAnalog = 0x11;
                m_CombatShouldSprint = false;
                return;
            }
            if (TryTryhardMeleeStand(position, combatDistance, attackDistance, now))
            {
                return;
            }

            var currentDirection = GetWorldMovementDirection(
                m_CombatMovementAnalog,
                m_DesiredYaw);
            if (now < m_NextCombatSteeringAt
                && currentDirection.sqrMagnitude > 0.01f
                && IsCombatMovementDirectionSafe(position, currentDirection, now))
            {
                return;
            }

            var target = m_TargetZombie!;
            var targetPosition = target.transform.position;
            var routeDirection = navigationTarget - position;
            routeDirection.y = 0f;
            if (routeDirection.sqrMagnitude > 0.01f)
            {
                routeDirection.Normalize();
            }

            // A fence or shelf between the bot and the zombie: the straight line
            // is blocked, so follow the route around it instead of pushing into it.
            var toTarget = targetPosition - position;
            toTarget.y = 0f;
            var directBlocked = m_ObjectiveType == ObjectiveType.Combat
                && combatDistance > attackDistance + 2f
                && toTarget.sqrMagnitude > 0.01f
                && routeDirection.sqrMagnitude > 0.01f
                && IsBodyRouteBlocked(
                    position,
                    toTarget.normalized,
                    Mathf.Min(2.5f, toTarget.magnitude))
                && !ShouldJumpTraversableObstacle(position, toTarget.normalized);

            var bestAnalog = (byte)0x11;
            var bestScore = float.NegativeInfinity;
            foreach (var analog in s_CombatMovementCandidates)
            {
                var direction = GetWorldMovementDirection(analog, m_DesiredYaw);
                if (!IsCombatMovementDirectionSafe(position, direction, now))
                {
                    continue;
                }

                var candidate = position + direction * 2.5f;
                var targetDistance = (candidate - targetPosition).GetHorizontalMagnitude();
                var nearestThreatDistance = GetNearestPerceivedZombieDistance(candidate);
                var score = nearestThreatDistance * 1.5f;
                var local = DecodeMovementAnalog(analog);
                var isFireTarget = IsRangedFireTarget(target);

                // During a melee approach every accepted candidate must actually
                // close distance. Pure A/D circling is useful inside attack range,
                // but outside it can create an endless orbit around the target.
                var mustCloseDistance = m_ObjectiveType == ObjectiveType.Combat
                    && m_CombatMovementPhase == CombatMovementPhase.Approach
                    && !isFireTarget
                    && combatDistance > attackDistance + 0.75f;
                if (directBlocked)
                {
                    var routeDot = Vector3.Dot(direction, routeDirection);
                    if (routeDot < 0.2f)
                    {
                        continue;
                    }
                    score += routeDot * 14f;
                }
                else if (mustCloseDistance && local.y <= 0f)
                {
                    continue;
                }

                if (m_FloorRouteActive && IsCombatTargetOnOtherFloor(position))
                {
                    score += Vector3.Dot(direction, routeDirection) * 20f;
                }
                else if (m_ObjectiveType == ObjectiveType.EscapeSwarm)
                {
                    score += Vector3.Dot(direction, routeDirection) * 14f;
                    score += nearestThreatDistance * 2f;
                    var currentFireDistance = GetNearestPerceivedFireZombieDistance(position);
                    var candidateFireDistance = GetNearestPerceivedFireZombieDistance(candidate);
                    if (candidateFireDistance < FireZombieAvoidRadiusMeters
                        && candidateFireDistance <= currentFireDistance + 0.25f)
                    {
                        continue;
                    }
                }
                else
                {
                    var attackInProgress = m_CombatMovementPhase
                            == CombatMovementPhase.Attack
                        && m_PendingMeleeRaycast;
                    var desiredDistance = isFireTarget
                        ? 15f
                        : m_Player.equipment.asset is ItemGunAsset
                            ? GetGunKeepDistance(target, attackDistance)
                            : attackInProgress
                                ? Mathf.Max(1.4f, attackDistance * m_MeleeDistanceShare)
                            : m_CombatMovementPhase == CombatMovementPhase.Retreat
                                ? CombatRetreatDistanceMeters
                                : Mathf.Max(1.4f, attackDistance * m_MeleeDistanceShare);
                    score -= Mathf.Abs(targetDistance - desiredDistance) * 3.5f;

                    if (m_CombatMovementPhase == CombatMovementPhase.Retreat
                        && m_HasKnownInteriorExit
                        && now < m_KnownInteriorExitExpiresAt)
                    {
                        var exitDirection = m_KnownInteriorExit - position;
                        exitDirection.y = 0f;
                        if (exitDirection.sqrMagnitude > 0.01f)
                        {
                            score += Vector3.Dot(
                                direction,
                                exitDirection.normalized) * 18f;
                        }
                    }

                    if (isFireTarget
                        && targetDistance < 11f
                        && targetDistance <= combatDistance + 0.25f)
                    {
                        continue;
                    }
                    // 0.1.170 (the tester: "as vezes ele da uma volta meia lua no
                    // zumbi"): A/D while facing the zombie walks an arc
                    // around it, and that was the move scored best while a
                    // swing was in the air. A player steps back, straight or
                    // a little to a side.
                    if (attackInProgress)
                    {
                        score += local.y < 0f && Mathf.Abs(local.x) > 0f
                            ? 10f
                            : local.y < 0f
                                ? 9f
                                : Mathf.Abs(local.x) > 0f && Mathf.Abs(local.y) < 0.1f
                                    ? 3f
                                    : -7f;
                    }
                    else if (m_CombatMovementPhase == CombatMovementPhase.Retreat
                        || combatDistance <= attackDistance + 0.75f)
                    {
                        score += local.y < 0f ? 9f : local.x != 0f ? 3f : -5f;
                    }
                    else
                    {
                        score += local.y > 0f ? 8f : local.x != 0f ? 3f : -3f;
                    }
                }

                if (analog == m_CombatMovementAnalog)
                {
                    score += 1.5f;
                }
                if (score <= bestScore)
                {
                    continue;
                }
                bestScore = score;
                bestAnalog = analog;
            }

            m_CombatMovementAnalog = bestAnalog;
            if (bestAnalog == 0x11)
            {
                if (m_CombatSteeringBlockedSince <= 0f)
                {
                    m_CombatSteeringBlockedSince = now;
                }
                else if (TryForceCombatRoute(position, combatDistance, attackDistance, now))
                {
                    m_CombatSteeringBlockedSince = 0f;
                }
                else if (now - m_CombatSteeringBlockedSince >= 0.75f
                         && m_LocalRecoveryPhase == LocalRecoveryPhase.None
                         && combatDistance <= 4f)
                {
                    // No safe step with the zombie already in reach: stand
                    // and hit it. The unstuck maneuver turned thigas' back on
                    // three zombies (85 to 10 health in 6s, 0.1.123 test).
                    m_CombatSteeringBlockedSince = now;
                }
                else if (now - m_CombatSteeringBlockedSince >= 0.75f
                         && m_LocalRecoveryPhase == LocalRecoveryPhase.None)
                {
                    BotLog(LogLevel.Information,
                        "Combate sem direcao segura ate o zumbi a {Distance:0.#}m "
                        + "(caminho direto bloqueado {Blocked}) em {Position}; destravando.",
                        combatDistance,
                        directBlocked,
                        position);
                    m_StatWindowNoDirection++;
                    // 0.1.168: searching every direction for a free one kept
                    // the bot against the wall; it backs off the way it came
                    // and the spot is marked for every bot.
                    MarkOrbitBadSpot(position, now);
                    if (TryStartCombatBacktrack(position, now))
                    {
                        m_StatWindowBacktracks++;
                        BotLog(LogLevel.Information,
                            "Recuando {Distance:0.#}m pelo caminho por onde veio, ate {Point}; ponto marcado como ruim para todos os bots por {Minutes:0} min.",
                            (m_BacktrackPoint - position).GetHorizontalMagnitude(),
                            FormatPosition(m_BacktrackPoint),
                            OrbitBadSpotSeconds / 60f);
                        m_CombatSteeringBlockedSince = 0f;
                        ClearPath();
                        ApplyCombatBacktrack(position, now);
                        return;
                    }
                    if (directBlocked)
                    {
                        // The route itself pointed into the obstacle: ask for a new one.
                        ClearPath();
                    }
                    EnterUnstuckState(position, now);
                    m_CombatSteeringBlockedSince = 0f;
                }
            }
            else
            {
                m_CombatSteeringBlockedSince = 0f;
            }
            // 0.2.2x13: the tryhard steps back walking (the players sprint
            // back in 10-21% of the fights, even against groups).
            var urgentRetreat = m_CombatMovementPhase == CombatMovementPhase.Retreat
                && (m_CombatRetreatShouldSprint
                    || (m_CachedNearbyZombieCount >= 2 && !IsTryhardMeleeFootwork(position, out _)));
            var urgentApproach = m_ObjectiveType == ObjectiveType.Combat
                && m_CombatMovementPhase == CombatMovementPhase.Approach
                && !IsRangedFireTarget(target)
                && combatDistance > attackDistance + 5f;
            m_CombatShouldSprint = bestAnalog != 0x11
                && !(m_CombatMovementPhase == CombatMovementPhase.Attack
                     && m_PendingMeleeRaycast)
                && (m_ObjectiveType == ObjectiveType.EscapeSwarm
                    || IsRangedFireTarget(target) && combatDistance < 15f
                    || urgentApproach
                    || urgentRetreat);
            m_NextCombatSteeringAt = now + (urgentRetreat ? 0.35f : 0.65f);

            if (now >= m_NextCombatSteeringLogAt)
            {
                m_NextCombatSteeringLogAt = now + 3f;
                BotLog(LogLevel.Debug,
                    "Locomocao de combate escolheu {Direction}; distancia {Distance:0.##}m; "
                    + "fase {Phase}; correndo {Sprinting}.",
                    DescribeMovementAnalog(bestAnalog),
                    combatDistance,
                    m_CombatMovementPhase,
                    m_CombatShouldSprint);
            }
        }

        private bool IsCombatMovementDirectionSafe(
            Vector3 position,
            Vector3 direction,
            float now)
        {
            var probe = GetCombatStepProbeMeters(position, direction);
            if (direction.sqrMagnitude < 0.01f
                || (IsBodyRouteBlocked(position, direction, Mathf.Min(1.6f, probe))
                    && !ShouldJumpTraversableObstacle(position, direction))
                || IsEscapeTerrainUnsafe(position, direction, probe))
            {
                return false;
            }
            var desired = position + direction * probe;
            return TryGetWalkableGround(desired, out var grounded)
                && Mathf.Abs(grounded.y - position.y) <= 1.5f
                && !WaterUtility.isPointUnderwater(grounded + Vector3.up * 0.5f)
                && !IsHazardousPosition(grounded, now, 1.5f);
        }

        private float GetNearestPerceivedZombieDistance(Vector3 position)
        {
            var nearest = 100f;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null && !zombie.isDead && zombie.gameObject.activeInHierarchy)
                {
                    nearest = Mathf.Min(
                        nearest,
                        (position - zombie.transform.position).GetHorizontalMagnitude());
                }
            }
            return nearest;
        }

        private float GetNearestPerceivedFireZombieDistance(Vector3 position)
        {
            var nearest = 100f;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null
                    && !zombie.isDead
                    && zombie.gameObject.activeInHierarchy
                    && IsFireZombie(zombie))
                {
                    nearest = Mathf.Min(
                        nearest,
                        (position - zombie.transform.position).GetHorizontalMagnitude());
                }
            }
            return nearest;
        }

        private static Vector2 DecodeMovementAnalog(byte analog)
        {
            return new Vector2((analog >> 4) - 1f, (analog & 0x0F) - 1f);
        }

        private static Vector3 GetWorldMovementDirection(byte analog, float yaw)
        {
            var local = DecodeMovementAnalog(analog);
            if (local.sqrMagnitude < 0.01f)
            {
                return Vector3.zero;
            }
            return Quaternion.Euler(0f, yaw, 0f)
                * new Vector3(local.x, 0f, local.y).normalized;
        }

        private static string DescribeMovementAnalog(byte analog)
        {
            switch (analog)
            {
                case 0x10: return "S";
                case 0x00: return "S+A";
                case 0x20: return "S+D";
                case 0x01: return "A";
                case 0x21: return "D";
                case 0x02: return "W+A";
                case 0x22: return "W+D";
                case 0x12: return "W";
                default: return "parado";
            }
        }

        private void BeginLocalRecoveryPhase(
            LocalRecoveryPhase phase,
            Vector3 position,
            float now)
        {
            m_LocalRecoveryPhase = phase;
            m_LocalRecoveryPhaseStartPosition = position;
            m_LocalRecoveryJump = false;
            switch (phase)
            {
                case LocalRecoveryPhase.Stop:
                    m_LocalRecoveryAnalog = 0x11;
                    m_LocalRecoveryPhaseEndsAt = now + 0.3f;
                    break;
                case LocalRecoveryPhase.Backward:
                    m_LocalRecoveryAnalog = 0x10;
                    m_LocalRecoveryPhaseEndsAt = now + 0.9f;
                    break;
                case LocalRecoveryPhase.TurnLeft:
                case LocalRecoveryPhase.TurnRight:
                case LocalRecoveryPhase.TurnOpposite:
                    m_LocalRecoveryAnalog = 0x11;
                    m_LocalRecoveryPhaseEndsAt = now + 0.7f;
                    break;
                case LocalRecoveryPhase.ForwardLeft:
                case LocalRecoveryPhase.ForwardRight:
                    m_LocalRecoveryAnalog = 0x12;
                    m_LocalRecoveryJump = m_LocalRecoveryStartedInWater;
                    m_LocalRecoveryPhaseEndsAt = now + 1.15f;
                    break;
                case LocalRecoveryPhase.ForwardOpposite:
                    m_LocalRecoveryAnalog = 0x12;
                    m_LocalRecoveryJump = true;
                    m_LocalRecoveryPhaseEndsAt = now + 1.4f;
                    break;
                default:
                    m_LocalRecoveryAnalog = 0x11;
                    m_LocalRecoveryPhaseEndsAt = now + 0.35f;
                    break;
            }
            // 0.2.2w (doc 14.3, item 7): the tryhard does not spin in place
            // (left 90, right 180, back 180 was the "360 standing still").
            // It keeps facing the way it was and steps left, right or back.
            if (Tryhard)
            {
                switch (phase)
                {
                    case LocalRecoveryPhase.TurnLeft:
                    case LocalRecoveryPhase.TurnRight:
                    case LocalRecoveryPhase.TurnOpposite:
                        m_LocalRecoveryPhaseEndsAt = now + 0.05f;
                        break;
                    case LocalRecoveryPhase.ForwardLeft:
                        m_LocalRecoveryAnalog = 0x01;
                        break;
                    case LocalRecoveryPhase.ForwardRight:
                        m_LocalRecoveryAnalog = 0x21;
                        break;
                    case LocalRecoveryPhase.ForwardOpposite:
                        m_LocalRecoveryAnalog = 0x10;
                        break;
                }
            }

            m_IsWalking = m_LocalRecoveryAnalog != 0x11;
            m_IsSprinting = false;
            BotLog(LogLevel.Debug,
                "Recuperacao local entrou na etapa {Phase}; posicao {Position}; analog 0x{Analog:X2}.",
                phase,
                FormatPosition(position),
                m_LocalRecoveryAnalog);
        }

        // Usually "stuck" means zombies are body-blocking the bot: standing
        // still to maneuver while they hit is how it died. Fight them instead.
        private bool TryFightBlockingZombie(Vector3 position, float radius, float now, string when)
        {
            Zombie? nearest = null;
            var best = radius;
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                if (candidate == null || candidate.isDead || !candidate.gameObject.activeInHierarchy)
                {
                    continue;
                }
                // Killing a burner in melee is 40 damage on the bot: keep
                // maneuvering away from it instead.
                if (IsFireZombie(candidate))
                {
                    continue;
                }
                var offset = candidate.transform.position - position;
                if (Mathf.Abs(offset.y) > 2f)
                {
                    continue;
                }
                var distance = offset.GetHorizontalMagnitude();
                if (distance <= best)
                {
                    best = distance;
                    nearest = candidate;
                }
            }
            if (nearest == null)
            {
                return false;
            }
            if (m_LocalRecoveryPhase != LocalRecoveryPhase.None)
            {
                m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                m_LocalRecoveryAnalog = 0x11;
                m_LocalRecoveryJump = false;
            }
            m_StallAnchor = position;
            m_StallSince = now;
            m_ConsecutiveStuckChecks = 0;
            if (now >= m_NextBlockingFightLogAt)
            {
                m_NextBlockingFightLogAt = now + 5f;
                BotLog(LogLevel.Information,
                    "Bot bloqueado por zumbi a {Distance:0.#}m ({When}); lutando em vez de manobrar.",
                    best,
                    when);
            }
            ForceCombatTarget(nearest, now);
            return true;
        }

        private void UpdateLocalRecovery(Vector3 position, float now)
        {
            if (now >= m_NextRecoveryThreatCheckAt)
            {
                m_NextRecoveryThreatCheckAt = now + 0.25f;
                if (TryFightBlockingZombie(position, 3f, now, "durante a manobra"))
                {
                    return;
                }
            }
            m_IsWalking = m_LocalRecoveryAnalog != 0x11;
            m_IsSprinting = false;
            switch (Tryhard && m_LocalRecoveryPhase != LocalRecoveryPhase.Confirm
                    ? LocalRecoveryPhase.None
                    : m_LocalRecoveryPhase)
            {
                case LocalRecoveryPhase.TurnLeft:
                case LocalRecoveryPhase.ForwardLeft:
                    m_DesiredYaw = m_LocalRecoveryOriginalYaw - 90f;
                    break;
                case LocalRecoveryPhase.TurnRight:
                case LocalRecoveryPhase.ForwardRight:
                    m_DesiredYaw = m_LocalRecoveryOriginalYaw + 90f;
                    break;
                case LocalRecoveryPhase.TurnOpposite:
                case LocalRecoveryPhase.ForwardOpposite:
                    m_DesiredYaw = m_LocalRecoveryOriginalYaw + 180f;
                    break;
                case LocalRecoveryPhase.Confirm:
                    m_DesiredYaw = m_LocalRecoveryCandidateFound
                        ? m_LocalRecoveryCandidateYaw
                        : m_CurrentYaw;
                    break;
                default:
                    m_DesiredYaw = m_LocalRecoveryOriginalYaw;
                    break;
            }
            m_CurrentYaw = Mathf.MoveTowardsAngle(
                m_CurrentYaw,
                m_DesiredYaw,
                (Tryhard
                    ? GetHumanTurnSpeed(Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, m_DesiredYaw)), false)
                    : Mathf.Max(m_TurnSpeedDegreesPerSecond, RecoveryTurnDegreesPerSecond)) * TurnStepSeconds);
            m_DesiredPitch = m_LocalRecoveryStartedInWater ? 75f : 90f;
            m_CurrentPitch = Mathf.MoveTowardsAngle(
                m_CurrentPitch,
                m_DesiredPitch,
                Mathf.Max(m_TurnSpeedDegreesPerSecond, RecoveryTurnDegreesPerSecond) * TurnStepSeconds);

            var noLongerInWater = m_Player.stance.stance != EPlayerStance.SWIM
                && !WaterUtility.isPointUnderwater(position + Vector3.up * 0.5f);
            if (m_LocalRecoveryStartedInWater
                && noLongerInWater
                && m_Player.movement.isGrounded)
            {
                CompleteLocalRecovery(position, now, true, "saiu da agua e confirmou contato com o chao");
                return;
            }

            if (now < m_LocalRecoveryPhaseEndsAt)
            {
                return;
            }

            var phaseDistance = (position - m_LocalRecoveryPhaseStartPosition)
                .GetHorizontalMagnitude();
            var totalDistance = (position - m_LocalRecoveryStartPosition)
                .GetHorizontalMagnitude();
            BotLog(LogLevel.Debug,
                "Recuperacao local concluiu etapa {Phase}: deslocamento da etapa {PhaseDistance:0.##}m; "
                + "deslocamento total {TotalDistance:0.##}m.",
                m_LocalRecoveryPhase,
                phaseDistance,
                totalDistance);

            if (IsRecoveryMovementPhase(m_LocalRecoveryPhase)
                && IsRecoveryCandidateValid(position, phaseDistance, totalDistance))
            {
                m_LocalRecoveryCandidateFound = true;
                m_LocalRecoveryCandidatePosition = position;
                // The way it actually moved (a side step for the tryhard).
                var moved = GetWorldMovementDirection(m_LocalRecoveryAnalog, m_CurrentYaw);
                m_LocalRecoveryCandidateYaw = moved.sqrMagnitude > 0.01f ? DirectionToYaw(moved) : m_CurrentYaw;
                BeginLocalRecoveryPhase(LocalRecoveryPhase.Confirm, position, now);
                return;
            }

            if (m_LocalRecoveryPhase == LocalRecoveryPhase.Confirm)
            {
                CompleteLocalRecovery(
                    position,
                    now,
                    m_LocalRecoveryCandidateFound
                        && (position - m_LocalRecoveryStartPosition).GetHorizontalMagnitude() >= 1.8f
                        && (position - m_LocalRecoveryCandidatePosition).GetHorizontalMagnitude() <= 1f
                        && HasRecoveryClearance(position),
                    m_LocalRecoveryCandidateFound
                        ? "nova posicao e espaco livre confirmados"
                        : "nenhuma direcao produziu uma saida valida");
                return;
            }

            switch (m_LocalRecoveryPhase)
            {
                case LocalRecoveryPhase.Stop:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.Backward, position, now);
                    break;
                case LocalRecoveryPhase.Backward:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.TurnLeft, position, now);
                    break;
                case LocalRecoveryPhase.TurnLeft:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.ForwardLeft, position, now);
                    break;
                case LocalRecoveryPhase.ForwardLeft:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.TurnRight, position, now);
                    break;
                case LocalRecoveryPhase.TurnRight:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.ForwardRight, position, now);
                    break;
                case LocalRecoveryPhase.ForwardRight:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.TurnOpposite, position, now);
                    break;
                case LocalRecoveryPhase.TurnOpposite:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.ForwardOpposite, position, now);
                    break;
                case LocalRecoveryPhase.ForwardOpposite:
                    BeginLocalRecoveryPhase(LocalRecoveryPhase.Confirm, position, now);
                    break;
                default:
                    CompleteLocalRecovery(position, now, false, "todas as manobras locais falharam");
                    break;
            }
        }

        private static bool IsRecoveryMovementPhase(LocalRecoveryPhase phase)
        {
            return phase == LocalRecoveryPhase.ForwardLeft
                || phase == LocalRecoveryPhase.ForwardRight
                || phase == LocalRecoveryPhase.ForwardOpposite;
        }

        private bool IsRecoveryCandidateValid(
            Vector3 position,
            float phaseDistance,
            float totalDistance)
        {
            if (m_LocalRecoveryStartedInWater)
            {
                return m_Player.stance.stance != EPlayerStance.SWIM
                    && !WaterUtility.isPointUnderwater(position + Vector3.up * 0.5f)
                    && m_Player.movement.isGrounded;
            }

            // Recuar sozinho nunca conclui a recuperacao. O bot precisa avancar
            // por uma direcao alternativa e terminar com espaco a sua frente.
            return phaseDistance >= 1.25f
                && totalDistance >= 2f
                && HasRecoveryClearance(position);
        }

        private bool HasRecoveryClearance(Vector3 position)
        {
            var heading = Quaternion.Euler(0f, m_CurrentYaw, 0f) * Vector3.forward;
            return !IsPathBlocked(position, heading, 1.8f);
        }

        private void CompleteLocalRecovery(
            Vector3 position,
            float now,
            bool succeeded,
            string reason)
        {
            var previousType = m_SuspendedObjectiveType;
            var previousPosition = m_SuspendedObjectivePosition;
            var previousRemaining = m_SuspendedObjectiveRemaining;
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            m_LocalRecoveryAnalog = 0x11;
            m_LocalRecoveryJump = false;
            m_IsWalking = false;
            m_IsSprinting = false;
            m_LastStuckCheckPosition = position;
            m_NextStuckCheckTime = now + 3f;
            m_ConsecutiveStuckChecks = 0;

            if (succeeded
                && previousType == ObjectiveType.Combat
                && m_RepeatedRecoveryCount >= 2)
            {
                // At the airport thigas was sent back to the same pocket by
                // the same zombie 34 times in 6 minutes, teleported out each
                // time. The second time with one zombie, it is left for 60s.
                var blockedZombie = m_TargetZombie;
                if (blockedZombie != null
                    && blockedZombie == m_LastBlockedCombatZombie
                    && now - m_LastBlockedCombatAt < 90f)
                {
                    m_UnreachableZombies[blockedZombie] = now + 60f;
                    reason = "rota de combate retornou ao mesmo ponto bloqueado pela segunda vez com o mesmo zumbi; zumbi ignorado por 60s";
                }
                else
                {
                    m_IgnoredZombie = blockedZombie;
                    m_IgnoreZombieUntil = now + 5f;
                    reason = "rota de combate retornou ao mesmo ponto bloqueado; zumbi sera reavaliado em 5s";
                }
                m_LastBlockedCombatZombie = blockedZombie;
                m_LastBlockedCombatAt = now;
                m_TargetZombie = null;
                succeeded = false;
            }
            else if (succeeded && m_RepeatedRecoveryCount >= 2)
            {
                succeeded = false;
                reason = "a rota retornou a mesma regiao bloqueada pela segunda vez";
                if (previousType == ObjectiveType.Explore)
                {
                    BlacklistCurrentExplorationDestination(now, reason);
                    m_HasInterestArea = false;
                }
                // 0.1.0-y17.22 (the tester, 20/11: "bugando a movimentacao
                // dele as vezes"). Only the area and the item were given up
                // here: a trip stayed active (ClearObjective leaves
                // m_TravelActive), so the next pick (ChooseExplorationObjective)
                // resumed it and planned the same way back to the same block,
                // and a patrol picked the same loot point again. As the third
                // swim at one bank does (NoteWaterExit): the trip fails and
                // the point is skipped.
                else if (previousType == ObjectiveType.Travel && m_TravelActive)
                {
                    FailTerrainTravel(now, reason);
                }
                else if (previousType == ObjectiveType.Patrol
                         && m_PatrolTargetSet
                         && (m_PatrolTargetPoint - previousPosition).sqrMagnitude < 0.01f)
                {
                    NotePatrolPointFailed(m_PatrolTargetPoint, now, reason, true);
                }
            }

            if (succeeded && CanResumeSuspendedObjective(previousType))
            {
                SetObjective(
                    previousType,
                    previousPosition,
                    float.IsPositiveInfinity(previousRemaining)
                        ? float.PositiveInfinity
                        : now + previousRemaining);
                BotLog(LogLevel.Information,
                    "Recuperacao local confirmada ({Reason}); objetivo {Objective} retomado e rota sera recalculada.",
                    reason,
                    previousType);
                return;
            }

            if (previousType == ObjectiveType.Loot && m_LootInstanceId != 0)
            {
                // The route keeps leading to the same blocked spot: retrying
                // a minute later only repeats the same failure.
                IgnoreLoot(m_LootInstanceId, now + UnreachableLootIgnoreSeconds);
                BotLog(LogLevel.Information,
                    "Loot {LootInstanceId} inalcancavel apos manobra de travado; ignorado por 10 min.",
                    m_LootInstanceId);
            }

            if (!succeeded && !WaterUtility.isPointUnderwater(position + Vector3.up * 0.5f))
            {
                // The second failed maneuver on the same spot (e.g. standing on
                // top of a prop) won't be fixed by a third: move off it now.
                var repeatedFailure = now - m_LastRecoveryFailureAt <= 60f
                    && (position - m_LastRecoveryFailurePosition).GetHorizontalMagnitude() <= 5f;
                m_LastRecoveryFailureAt = now;
                m_LastRecoveryFailurePosition = position;
                if (repeatedFailure && TryEscapeStuckZone(position, now))
                {
                    m_LastRecoveryFailureAt = float.NegativeInfinity;
                    return;
                }
                if (repeatedFailure)
                {
                    var destination = FindNearestDryNavigablePoint(position, position);
                    BotLog(LogLevel.Warning,
                        "Manobra de travado falhou duas vezes em {Position} ({Reason}); teleportando para {Destination}.",
                        FormatPosition(position),
                        reason,
                        FormatPosition(destination));
                    m_LastRecoveryFailureAt = float.NegativeInfinity;
                    ClearObjective();
                    TeleportBot(destination, m_Player.look.yaw);
                    m_StallAnchor = destination;
                    m_NextExplorationSelectionTime = 0f;
                    return;
                }
            }

            ClearObjective();
            BotLog(LogLevel.Information,
                "Recuperacao local encerrada ({Reason}); objetivo {Objective} abandonado.",
                reason,
                previousType);
            if (m_HasInterestArea && now < m_InterestAreaExpiresAt)
            {
                ChooseAreaPatrolObjective(position, now);
            }
            else
            {
                ChooseExplorationObjective(position, now);
            }
        }

        // A hand-marked passage (/passagem) whose near end is in the bot's region of
        // the graph and whose far end is in another (the one of destination,
        // when given): route to the near end, then walk straight across.
        private bool TryUseRampLink(Vector3 position, float now, Vector3? destination, string reason)
        {
            if (m_RampPhase != 0 || now < m_NextRampAttemptAt)
            {
                return false;
            }
            if (!destination.HasValue && now < m_AvoidPassageUntil)
            {
                return false;
            }
            // Chasing a zombie through a passage with low health walked the bot
            // into a crowded barn twice.
            if (destination.HasValue && m_Player.life.health < PassageMinimumHealth)
            {
                return false;
            }
            var links = SkaliaBotPassageLinks.Links;
            if (links.Count == 0)
            {
                return false;
            }
            var originArea = SkaliaBotPassageLinks.GetArea(position);
            if (!originArea.HasValue)
            {
                return false;
            }
            var destinationArea = destination.HasValue
                ? SkaliaBotPassageLinks.GetArea(destination.Value)
                : null;
            var bestDistance = 150f;
            var found = false;
            foreach (var link in links)
            {
                for (var side = 0; side < 2; side++)
                {
                    var entry = side == 0 ? link.A : link.B;
                    var exit = side == 0 ? link.B : link.A;
                    var distance = (entry - position).magnitude;
                    if (distance >= bestDistance)
                    {
                        continue;
                    }
                    var entryArea = SkaliaBotPassageLinks.GetCachedArea(entry);
                    var exitArea = SkaliaBotPassageLinks.GetCachedArea(exit);
                    if (entryArea != originArea
                        || !exitArea.HasValue
                        || exitArea == originArea
                        || (destinationArea.HasValue && exitArea != destinationArea)
                        || distance >= bestDistance)
                    {
                        continue;
                    }
                    bestDistance = distance;
                    m_RampEntry = entry;
                    m_RampExit = exit;
                    found = true;
                }
            }
            if (!found)
            {
                return false;
            }
            if (m_Player.life.health < PassageMinimumHealth || IsUnarmed())
            {
                // Unarmed at full health the bot walked 67m and 111m to the barn
                // passage straight through the Chersky Farm horde, twice.
                var crowd = Mathf.Max(
                    CountLivingZombiesNear(m_RampExit, 20f),
                    CountLivingZombiesNearSegment(position, m_RampEntry, 12f));
                if (crowd >= 3)
                {
                    m_NextRampAttemptAt = now + 10f;
                    BotLog(LogLevel.Information,
                        "Passagem para {Exit} evitada: vida {Health}, {Armed}, {Count} zumbis no caminho ou na saida.",
                        FormatPosition(m_RampExit),
                        m_Player.life.health,
                        IsUnarmed() ? "desarmado" : "armado",
                        crowd);
                    return false;
                }
            }
            m_NextRampAttemptAt = now + 10f;
            m_RampHasFinal = false;
            m_RampPhase = 1;
            m_RampDeadline = now + 30f;
            m_FleeingFromPlayerName = "passagem";
            SetObjective(ObjectiveType.Flee, m_RampEntry, m_RampDeadline);
            BotLog(LogLevel.Information,
                "Usando passagem marcada ({Reason}): indo ate {Entry} ({Distance:0.#}m) para atravessar ate {Exit}.",
                reason,
                FormatPosition(m_RampEntry),
                bestDistance,
                FormatPosition(m_RampExit));
            return true;
        }

        // A target above the bot (zombie on a loft or furniture, item on a
        // shelf) whose floor the graph has no mesh for: both ends of the marked
        // passage share one region, so only height tells them apart. Walk to the
        // low end, straight up to the high end, then straight to the target.
        private bool TryUseLinkTowardPoint(Vector3 position, float now, Vector3 target, string reason)
        {
            if (m_RampPhase != 0
                || now < m_NextRampAttemptAt
                || target.y - position.y < 0.8f
                || m_Player.life.health < PassageMinimumHealth)
            {
                return false;
            }
            var links = SkaliaBotPassageLinks.Links;
            var bestScore = float.MaxValue;
            var bestDistance = 0f;
            var found = false;
            foreach (var link in links)
            {
                for (var side = 0; side < 2; side++)
                {
                    var entry = side == 0 ? link.A : link.B;
                    var exit = side == 0 ? link.B : link.A;
                    if (exit.y - entry.y < 0.4f
                        || (exit - target).GetHorizontalMagnitude() > 8f
                        || Mathf.Abs(exit.y - target.y) > 2f
                        || Mathf.Abs(entry.y - position.y) > 2.5f)
                    {
                        continue;
                    }
                    var distance = (entry - position).magnitude;
                    var score = distance + (exit - target).magnitude;
                    if (distance > 80f || score >= bestScore)
                    {
                        continue;
                    }
                    bestScore = score;
                    bestDistance = distance;
                    m_RampEntry = entry;
                    m_RampExit = exit;
                    found = true;
                }
            }
            if (!found)
            {
                return false;
            }
            m_NextRampAttemptAt = now + 10f;
            m_RampHasFinal = true;
            m_RampFinal = target;
            m_RampPhase = 1;
            m_RampDeadline = now + 30f;
            m_FleeingFromPlayerName = "passagem";
            SetObjective(ObjectiveType.Flee, m_RampEntry, m_RampDeadline);
            BotLog(LogLevel.Information,
                "Usando passagem marcada para subir ({Reason}): indo ate {Entry} ({Distance:0.#}m), subindo ate {Exit} e depois ate {Target}.",
                reason,
                FormatPosition(m_RampEntry),
                bestDistance,
                FormatPosition(m_RampExit),
                FormatPosition(target));
            return true;
        }

        private void UpdateRampTraversal(Vector3 position, float now)
        {
            var target = m_RampPhase == 1 ? m_RampEntry : m_RampPhase == 2 ? m_RampExit : m_RampFinal;
            var arrived = (target - position).GetHorizontalMagnitude() <= (m_RampPhase == 3 ? 1.5f : 1.6f)
                && Mathf.Abs(target.y - position.y) <= 2.5f;
            var ownObjective = m_ObjectiveType == ObjectiveType.Flee
                && (m_ObjectivePosition - target).GetHorizontalMagnitude() <= 1f;
            if (m_RampPhase == 1 && arrived)
            {
                m_RampPhase = 2;
                m_RampDeadline = now + 20f;
                SetObjective(ObjectiveType.Flee, m_RampExit, m_RampDeadline);
                m_DirectFallbackUntil = now + 1f;
                return;
            }
            if (m_RampPhase == 2 && arrived && m_RampHasFinal
                && (m_RampFinal - position).GetHorizontalMagnitude() > 1.5f)
            {
                m_RampPhase = 3;
                m_RampDeadline = now + 8f;
                SetObjective(ObjectiveType.Flee, m_RampFinal, m_RampDeadline);
                m_DirectFallbackUntil = now + 1f;
                return;
            }
            if (m_RampPhase >= 2 && arrived)
            {
                m_RampHasFinal = false;
                BotLog(LogLevel.Information,
                    "Passagem atravessada: chegou em {Position}.",
                    FormatPosition(position));
                m_RampPhase = 0;
                if (m_ObjectiveType == ObjectiveType.Flee)
                {
                    ClearObjective();
                }
                m_HasInterestArea = false;
                m_NextExplorationSelectionTime = 0f;
                m_NextLootScanTime = 0f;
                return;
            }
            if (!ownObjective || now >= m_RampDeadline)
            {
                BotLog(LogLevel.Information,
                    "Travessia da passagem interrompida na etapa {Phase} em {Position} (objetivo {Objective}).",
                    m_RampPhase,
                    FormatPosition(position),
                    m_ObjectiveType);
                m_RampPhase = 0;
                m_RampHasFinal = false;
                if (ownObjective)
                {
                    ClearObjective();
                }
                return;
            }
            if (m_RampPhase >= 2)
            {
                // Straight across: the graph has no route through the passage.
                m_DirectFallbackUntil = now + 1f;
                // Furniture, window sills, a loft edge: jump when the next
                // point is higher and close.
                if (target.y - position.y > 0.4f
                    && (target - position).GetHorizontalMagnitude() < 2.5f
                    && m_Player.movement.isGrounded
                    && now >= m_NextNavigationJumpAt)
                {
                    m_NavigationJumpUntil = now + 0.55f;
                    m_NextNavigationJumpAt = now + 1.2f;
                }
            }
        }

        // Move to the nearest walkable point that belongs to another part of
        // the navigation graph than the closed pocket the bot is standing in.
        private void RememberIsland(uint area, Vector3 center, float now)
        {
            for (var i = 0; i < m_Islands.Count; i++)
            {
                if (m_Islands[i].Area == area)
                {
                    m_Islands[i] = new IslandMemory { Area = area, Center = center, Until = now + IslandMemorySeconds };
                    return;
                }
            }
            m_Islands.Add(new IslandMemory { Area = area, Center = center, Until = now + IslandMemorySeconds });
        }

        private bool IsInRememberedIsland(Vector3 point, float now)
        {
            if (m_Islands.Count == 0 || AstarPath.active == null)
            {
                return false;
            }
            for (var i = m_Islands.Count - 1; i >= 0; i--)
            {
                var island = m_Islands[i];
                if (now >= island.Until)
                {
                    m_Islands.RemoveAt(i);
                    continue;
                }
                if ((point - island.Center).GetHorizontalMagnitude() > IslandRadiusMeters)
                {
                    continue;
                }
                var node = AstarPath.active.GetNearest(point, NNConstraint.Walkable).node;
                if (node != null && node.Area == island.Area)
                {
                    return true;
                }
            }
            return false;
        }

        // Circling under a step whose upper node is another region of the
        // navmesh: no route leaves the pocket, blocking the step only made
        // the bot circle the next one for 20 min.
        private bool TryEscapeIslandOnOrbit(Vector3 position, Vector3 navigationTarget, float now)
        {
            if (AstarPath.active == null)
            {
                return false;
            }
            var botInfo = AstarPath.active.GetNearest(position, NNConstraint.Walkable);
            if (botInfo.node == null || Mathf.Abs(botInfo.position.y - position.y) > 1f)
            {
                return false;
            }
            var island = false;
            for (var i = m_PathIndex - 1; i < m_PathPoints.Count && i < m_PathIndex + 3 && !island; i++)
            {
                var point = i < m_PathIndex ? navigationTarget : m_PathPoints[i];
                if ((point - position).GetHorizontalMagnitude() > 6f
                    || point.y - position.y < BlockedStepMinimumRise)
                {
                    continue;
                }
                var node = AstarPath.active.GetNearest(point, NNConstraint.Walkable).node;
                island = node != null && node.Area != botInfo.node.Area;
            }
            return island && TryEscapeIsolatedRegion(position, now, "andando em circulo sob um degrau de outra regiao");
        }

        // A ladder taken because a route goes up it, not to leave a dead end:
        // when it fails the bot just plans again instead of escaping.
        private bool m_LadderFromRoute;

        private bool UsesFailedLadder(List<Vector3> points, float now)
        {
            for (var index = 0; index + 1 < points.Count; index++)
            {
                var ladder = SkaliaBotUnityNavmesh.LadderBetween(points[index], points[index + 1]);
                if (ladder != null && IsLadderPaused(ladder.Index, now))
                {
                    return true;
                }
                var downLadder = SkaliaBotUnityNavmesh.LadderBetween(points[index + 1], points[index]);
                if (downLadder != null
                    && (!s_Settings.LadderDescend || IsLadderPaused(downLadder.Index, now)))
                {
                    return true;
                }
            }
            return false;
        }

        private void StartLadderClimb(BotLadder ladder, float now, string reason)
        {
            m_LadderFromRoute = true;
            m_Ladder = ladder;
            m_LadderDown = false;
            m_LadderPhase = 1;
            m_LadderClimbed = false;
            m_LadderStartedAt = now;
            m_LadderPhaseStartedAt = now;
            ResetLadderX9();
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            BotLog(LogLevel.Information,
                "Subindo a escada {Name} em {Bottom} ate {Top}: {Reason}.",
                ladder.Name,
                FormatPosition(ladder.Bottom),
                FormatPosition(ladder.Top),
                reason);
            SetObjective(ObjectiveType.Ladder, ladder.Bottom, now + 40f);
        }

        private bool TryStartLadderEscape(Vector3 position, float now, uint area, string reason, bool allowSameArea = false)
        {
            var ladder = SkaliaBotLadderMap.FindExit(
                position,
                area,
                allowSameArea ? 15f : LadderSearchMeters,
                candidate => !IsLadderPaused(candidate.Index, now),
                allowSameArea);
            if (ladder == null)
            {
                return false;
            }
            RememberIsland(area, position, now);
            m_LadderFromRoute = false;
            m_Ladder = ladder;
            m_LadderDown = false;
            m_LadderPhase = 1;
            m_LadderClimbed = false;
            m_LadderStartedAt = now;
            m_LadderPhaseStartedAt = now;
            ResetLadderX9();
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            BotLog(LogLevel.Information,
                "Bot preso numa regiao sem saida (regiao {Area}) em {Position}: {Reason}; saindo pela escada {Name} em {Bottom} ({Distance:0}m) ate {Top}.",
                area,
                FormatPosition(position),
                reason,
                ladder.Name,
                FormatPosition(ladder.Bottom),
                (ladder.Bottom - position).GetHorizontalMagnitude(),
                FormatPosition(ladder.Top));
            SetObjective(ObjectiveType.Ladder, ladder.Bottom, now + 40f);
            return true;
        }

        // Climbs like a player: stand at the foot, face the ladder, hold
        // forward. PlayerStance switches to CLIMB on its own and pushes the
        // bot onto the top when the ladder ends.
        private bool UpdateLadderClimb(Vector3 position, float now)
        {
            var ladder = m_Ladder;
            if (ladder == null)
            {
                ClearObjective();
                return false;
            }
            // 0.2.2x8: a zombie on the bot before it holds the ladder comes
            // first (SkaliaBotLadderX8).
            if (TryAbortLadderForZombie(position, now))
            {
                return false;
            }
            if (m_LadderDown)
            {
                return UpdateLadderDescent(position, now);
            }
            var climbing = m_Player.stance.stance == EPlayerStance.CLIMB;
            m_LadderStrafeAnalog = 0;
            if (m_LadderPhase == 1)
            {
                var footDistance = (ladder.Bottom - position).GetHorizontalMagnitude();
                if (footDistance <= 0.9f && Mathf.Abs(ladder.Bottom.y - position.y) <= 1.5f)
                {
                    // 0.2.2x15: at the foot from behind the ladder: round
                    // to its front first (SkaliaBotLadderX15).
                    if (TryWalkRoundToLadderFront(ladder, position, now))
                    {
                        return m_Ladder != null ? false : true;
                    }
                    m_LadderPhase = 2;
                    m_LadderPhaseStartedAt = now;
                    m_LadderStartY = position.y;
                    ClearPath();
                }
                else if (now - m_LadderStartedAt >= 25f)
                {
                    FailLadder(position, now, "nao chegou ao pe da escada");
                    return true;
                }
                else
                {
                    return false;
                }
            }
            if (climbing)
            {
                m_LadderClimbed = true;
            }
            // 0.2.2x10 (doc 16.18): the end of the climb below the top is a
            // gap between pieces, not the top (SkaliaBotLadderX10).
            var climbEnded = m_LadderClimbed && !climbing && position.y >= m_LadderStartY + 1f;
            if (climbEnded && !IsLadderClimbDone(ladder, position))
            {
                if (now - m_LadderPhaseStartedAt >= 20f)
                {
                    FailLadder(position, now, "subida parou num vao a " + position.y.ToString("0.0") + "m (topo " + ladder.Top.y.ToString("0.0") + "m): " + DescribeLadderContact(ladder, position, false));
                    return true;
                }
                SteerLadderGap(ladder, position, false, now);
                return true;
            }
            if (climbing && m_LadderInGap)
            {
                SteerLadderGap(ladder, position, true, now);
            }
            if (climbing && SteerLadderBlockedClimb(ladder, position, now))
            {
                return true;
            }
            // 0.2.2y11: off the ladder at the top but not on the floor yet
            // (SkaliaBotLadderY11).
            if (climbEnded && SteerLadderStepOff(ladder, position, now))
            {
                return true;
            }
            if (climbEnded)
            {
                BotLog(LogLevel.Information,
                    "Bot subiu a escada {Name} em {Seconds:0}s; agora em {Position}.",
                    ladder.Name,
                    now - m_LadderPhaseStartedAt,
                    FormatPosition(position));
                s_LadderFailCount.Remove(ladder.Index);
                m_LadderRetryAfter.Remove(ladder.Index);
                m_Ladder = null;
                m_LadderPhase = 0;
                ClearObjective();
                ClearPath();
                m_StallAnchor = position;
                m_NextExplorationSelectionTime = 0f;
                m_IsWalking = false;
                return true;
            }
            // 0.2.2x9: the walk-in did not take it: look up at it from the
            // foot and take it, as the players do (SkaliaBotLadderX9).
            if (!climbing
                && !m_LadderClimbed
                && now - m_LadderPhaseStartedAt >= LadderUpRequestAfterSeconds
                && TrySteerClimbRequestFromFoot(ladder, position, now))
            {
                return true;
            }
            if ((!m_LadderClimbed && now - m_LadderPhaseStartedAt >= 8f)
                || now - m_LadderPhaseStartedAt >= 20f)
            {
                FailLadder(position, now, (m_LadderClimbed ? "subida nao terminou: " : "o jogo nao iniciou a subida: ") + DescribeLadderContact(ladder, position, false));
                return true;
            }
            m_StealthCrouch = false;
            m_IsSprinting = false;
            // 0.2.2: forward, whatever the route's last step was (a strafe
            // left from the mesh following walked beside the ladder).
            m_NavigationAnalog = 0x12;
            m_DesiredYaw = climbing
                ? ladder.FacingYaw
                : LadderMustBackOffFirst(ladder, position) ? m_CurrentYaw : GetLadderApproachYaw(ladder, position);
            m_DesiredPitch = 60f;
            m_CurrentYaw = Mathf.MoveTowardsAngle(m_CurrentYaw, m_DesiredYaw, Mathf.Max(m_TurnSpeedDegreesPerSecond, LadderTurnDegreesPerSecond) * TurnStepSeconds);
            m_CurrentPitch = Mathf.MoveTowardsAngle(m_CurrentPitch, m_DesiredPitch, Mathf.Max(m_TurnSpeedDegreesPerSecond, LadderTurnDegreesPerSecond) * TurnStepSeconds);
            // 0.2.2x8: in to the ladder's line, never past it, jumping onto
            // a ladder that starts above the waist.
            SteerLadderApproach(ladder, position, climbing, now);
            return true;
        }

        private void FailLadder(Vector3 position, float now, string reason)
        {
            var ladder = m_Ladder;
            m_Ladder = null;
            m_LadderPhase = 0;
            m_IsWalking = false;
            if (ladder != null)
            {
                // 0.2.2x8: no ban for every bot (30 min to 4 h): this bot
                // tries again in 20s, and the log says why it failed.
                s_LadderFailCount.TryGetValue(ladder.Index, out var failures);
                s_LadderFailCount[ladder.Index] = ++failures;
                PauseLadder(ladder, now, LadderRetrySeconds);
                BotLog(LogLevel.Information,
                    "Escada {Name} em {Bottom} falhou ({Reason}, falha {Count}; pulo {Jump}); este bot tenta de novo em {Seconds:0}s.",
                    ladder.Name,
                    FormatPosition(ladder.Bottom),
                    reason,
                    failures,
                    ladder.JumpToGrab,
                    LadderRetrySeconds);
            }
            ClearObjective();
            ClearPath();
            if (!m_LadderFromRoute)
            {
                TryEscapeIsolatedRegion(position, now, "escada falhou");
            }
        }

        private bool TryEscapeIsolatedRegion(Vector3 position, float now, string reason = "varios itens sem rota")
        {
            if (AstarPath.active == null)
            {
                return false;
            }
            var origin = AstarPath.active.GetNearest(position, NNConstraint.Walkable);
            if (origin.node == null)
            {
                return false;
            }
            if (TryStartLadderEscape(position, now, origin.node.Area, reason))
            {
                return true;
            }
            for (var radius = 4f; radius <= 48f; radius += 4f)
            {
                for (var step = 0; step < 16; step++)
                {
                    var direction = Quaternion.Euler(0f, step * 22.5f, 0f) * Vector3.forward;
                    var nearest = AstarPath.active.GetNearest(position + direction * radius, NNConstraint.Walkable);
                    if (nearest.node == null
                        || nearest.node.Area == origin.node.Area
                        || Mathf.Abs(nearest.position.y - position.y) > 12f
                        || WaterUtility.isPointUnderwater(nearest.position + Vector3.up * 0.5f))
                    {
                        continue;
                    }
                    BotLog(LogLevel.Warning,
                        "Bot preso numa regiao sem saida da malha (regiao {Area}) em {Position}: {Reason}; teleportando para {Destination} (regiao {NewArea}); regiao evitada por 30 min.",
                        origin.node.Area,
                        FormatPosition(position),
                        reason,
                        FormatPosition(nearest.position),
                        nearest.node.Area);
                    RememberIsland(origin.node.Area, position, now);
                    m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                    ClearObjective();
                    TeleportBot(nearest.position + Vector3.up * 0.3f, m_Player.look.yaw);
                    m_StallAnchor = nearest.position;
                    m_NextExplorationSelectionTime = 0f;
                    m_NextLootScanTime = now + 1f;
                    return true;
                }
            }
            return false;
        }

        private bool CanResumeSuspendedObjective(ObjectiveType type)
        {
            if (type == ObjectiveType.None
                || type == ObjectiveType.Unstuck
                || type == ObjectiveType.ExitWater
                || type == ObjectiveType.EscapeHazard
                || type == ObjectiveType.EscapeSwarm)
            {
                return false;
            }
            if (type == ObjectiveType.Combat)
            {
                return IsTargetZombieAlive();
            }
            return true;
        }

        private bool UpdateSwarmEscapeState(Vector3 position, float now)
        {
            // 0.2.2x14: 6+ after the bot and no magazine for them: out
            // before they arrive (ShouldLeaveBigGroup).
            var surrounded = now >= m_SwarmCooldownUntil
                && ((m_CachedSurroundedZombieCount >= SurroundedZombieCount
                     && (m_SwarmEscapeActive || !ShouldFightSmallGroup(now)))
                    || ShouldLeaveBigGroup(now));

            // EscapeSwarm is exclusively the 8+ zombie close-range kite. A
            // lone fire zombie must not make the logs/state claim a swarm.
            if (!m_SwarmEscapeActive && !surrounded)
            {
                return false;
            }

            if (!m_SwarmEscapeActive)
            {
                m_SwarmEscapeActive = true;
                m_SwarmActivatedAt = now;
                m_SwarmSafeSince = 0f;
                m_NextSwarmReplanAt = 0f;
                m_SwarmLeftArea = false;
                m_SwarmLowStaminaHoldSince = -1f;
                m_SwarmStallSince = -1f;
                m_SwarmThreatCenter = GetThreatCentroid(position, 25f);
                m_StatWindowSwarms++;
                var restarted = now - m_LastSwarmEndAt <= 30f;
                if (restarted)
                {
                    m_StatWindowSwarmRestarts++;
                }
                ClearObjective();
                BotLog(LogLevel.Information,
                    "EscapeSwarm ativado: {Count} zumbis validos em ate {Radius:0.#}m; atras do bot a 8m {Hunters8}, a 20m {Hunters20}; vida {Health}, stamina {Stamina}{Restart}.",
                    m_CachedSurroundedZombieCount,
                    SurroundedRadiusMeters,
                    m_ThreatHunters8,
                    m_ThreatHunters20,
                    m_Player.life.health,
                    m_Player.life.stamina,
                    restarted ? "; recomecou " + (now - m_LastSwarmEndAt).ToString("0") + "s depois do ultimo" : string.Empty);
            }

            // 0.2.2x8 (doc 16.16): stalled with a zombie on the bot, fight.
            if (TryYieldSwarmToFight(position, now))
            {
                return false;
            }

            // 0.1.173: the escape ended with 7-14 zombies still seen and the
            // bot walked back into them (25 of 76 escapes restarted within
            // 30s). It lasts until nothing is after the bot within 8m and, for
            // up to 60s, no more than 2 within 20m, from the shared snapshot
            // (marked zombies included).
            var swarmElapsed = now - m_SwarmActivatedAt;
            var stillUnsafe = m_CachedSurroundedZombieCount > 1
                || m_ThreatHunters8 > 0
                || (m_ThreatHunters20 > 2 && swarmElapsed < SwarmMaximumSeconds);
            // 0.1.174: the escape ended with stamina 0 and the bot walked a
            // patrol with hunters still behind it (thigas 16:17, Tadeu 18:35):
            // swarmed again within seconds. Out of breath with anything still
            // after it within 20m, it keeps backing off for up to 30s more;
            // after that the disengage window lets it fight the closest one.
            var lowStaminaChased = m_Player.life.stamina <= SwarmLowStaminaHoldStamina
                && m_ThreatHunters20 > 0;
            if (!stillUnsafe && lowStaminaChased)
            {
                if (m_SwarmLowStaminaHoldSince < 0f)
                {
                    m_SwarmLowStaminaHoldSince = now;
                    BotLog(LogLevel.Information,
                        "Cerco aliviou mas o bot esta sem folego (stamina {Stamina}) com {Hunters} zumbis atras a 20m; continuando a se afastar por ate {Seconds:0}s.",
                        m_Player.life.stamina,
                        m_ThreatHunters20,
                        SwarmLowStaminaHoldSeconds);
                }
                if (now - m_SwarmLowStaminaHoldSince < SwarmLowStaminaHoldSeconds)
                {
                    stillUnsafe = true;
                }
            }
            else if (!lowStaminaChased)
            {
                m_SwarmLowStaminaHoldSince = -1f;
            }
            if (!m_SwarmLeftArea && swarmElapsed >= SwarmMaximumSeconds && stillUnsafe
                && TryInsistOnArea("fuga do cerco passou de " + SwarmMaximumSeconds.ToString("0") + "s", now))
            {
                m_SwarmLeftArea = true;
            }
            if (!m_SwarmLeftArea && swarmElapsed >= SwarmMaximumSeconds && stillUnsafe)
            {
                m_SwarmLeftArea = true;
                BotLog(LogLevel.Information,
                    "Fuga do cerco passou de {Seconds:0}s com {Hunters} zumbis atras do bot a 20m; saindo da area {Area}.",
                    SwarmMaximumSeconds,
                    m_ThreatHunters20,
                    m_HasInterestArea ? m_InterestAreaName : "atual");
                FinishInterestArea(now);
                m_NextExplorationSelectionTime = now;
            }
            if (!stillUnsafe)
            {
                if (m_SwarmSafeSince <= 0f)
                {
                    m_SwarmSafeSince = now;
                }
                else if (now - m_SwarmSafeSince >= SwarmSafeSeconds
                         && now - m_SwarmActivatedAt >= SwarmMinimumSeconds)
                {
                    // A short cooldown keeps the bot from re-entering the kite
                    // the moment it turns back to fight the zombies it left.
                    m_SwarmCooldownUntil = now + SwarmCooldownSeconds;
                    m_SwarmEscapeActive = false;
                    m_SwarmJumpUntil = 0f;
                    m_LastSwarmEndAt = now;
                    ClearObjective();
                    BotLog(LogLevel.Information,
                        "EscapeSwarm encerrado depois de {Seconds:0}s: restaram {Count} zumbis proximos, atras do bot a 20m {Hunters20}; vida {Health}, stamina {Stamina}; em {Position}.",
                        swarmElapsed,
                        m_CachedSurroundedZombieCount,
                        m_ThreatHunters20,
                        m_Player.life.health,
                        m_Player.life.stamina,
                        FormatPosition(position));
                    StartDisengage(m_SwarmThreatCenter, "escapar do cerco", now);
                    return false;
                }
            }
            else
            {
                m_SwarmSafeSince = 0f;
            }

            if (now >= m_NextSwarmReplanAt
                || m_ObjectiveType != ObjectiveType.EscapeSwarm
                || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 3f)
            {
                m_NextSwarmReplanAt = now + 2.5f;
                var center = GetThreatCentroid(position, 25f);
                if ((center - position).GetHorizontalMagnitude() > 0.5f)
                {
                    m_SwarmThreatCenter = center;
                }
                SetObjective(
                    ObjectiveType.EscapeSwarm,
                    FindZombieEscapePoint(position, now),
                    now + 20f);
                if (m_SwarmDirectWindowEscape)
                {
                    m_DirectFallbackUntil = now + 2.5f;
                }
            }

            // EscapeSwarm is combat kiting rather than blind flight. Keep the
            // nearest valid pursuer targeted while following the escape route.
            if (!IsTargetZombieAlive() || now >= m_NextZombieScanTime)
            {
                m_NextZombieScanTime = now + 0.25f;
                // 0.1.173: hurt with 4+ after it, the bot only runs: it hits
                // only what blocks the way (1.5m ahead). Stopping to fight
                // with half health is how the escapes ended in death.
                // 0.1.174: out of breath after the swarm eased, the same.
                if ((m_Player.life.health <= SwarmPureRunHealth && m_ThreatHunters20 >= SwarmPureRunHunters)
                    || m_SwarmLowStaminaHoldSince >= 0f)
                {
                    m_TargetZombie = FindSwarmBlocker(position);
                }
                else if (TryFindNearestZombie(position, out var swarmTarget))
                {
                    m_TargetZombie = swarmTarget;
                }
            }

            if (m_Player.movement.isGrounded && now >= m_NextSwarmJumpAt)
            {
                m_SwarmJumpUntil = now + 0.55f;
                m_NextSwarmJumpAt = now + 1.15f;
            }

            return true;
        }

        // Each zombie that has not noticed the bot and that the route passes
        // within hearing of is one more pursuer.
        private static float GetEscapeRouteWakePenalty(
            Vector3 origin,
            Vector3 candidate,
            List<Vector3> idleThreats)
        {
            var wake = LightingManager.isFullMoon ? FullMoonIdleZombieWakeMeters : IdleZombieWakeMeters;
            var penalty = 0f;
            foreach (var threat in idleThreats)
            {
                var distance = Mathf.Min(
                    GetHorizontalDistanceToSegment(threat, origin, candidate),
                    (threat - candidate).GetHorizontalMagnitude());
                if (distance < wake)
                {
                    penalty += 4f + (wake - distance) * 1.5f;
                }
            }
            return penalty;
        }

        // Running past zombies to reach a far point is how the unarmed bot
        // fled straight into the horde: penalize routes that brush them.
        private static float GetEscapeRouteThreatPenalty(
            Vector3 origin,
            Vector3 candidate,
            List<Vector3> threats)
        {
            var penalty = 0f;
            foreach (var threat in threats)
            {
                if ((threat - origin).GetHorizontalMagnitude() <= 3f)
                {
                    continue;
                }
                var distance = GetHorizontalDistanceToSegment(threat, origin, candidate);
                if (distance < 6f)
                {
                    penalty += (6f - distance) * 3f;
                }
            }
            return penalty;
        }

        private static float GetHorizontalDistanceToSegment(Vector3 point, Vector3 start, Vector3 end)
        {
            var segment = end - start;
            segment.y = 0f;
            var toPoint = point - start;
            toPoint.y = 0f;
            var lengthSquared = segment.sqrMagnitude;
            var t = lengthSquared > 0.0001f
                ? Mathf.Clamp01(Vector3.Dot(toPoint, segment) / lengthSquared)
                : 0f;
            return (toPoint - segment * t).magnitude;
        }

        // A flee or retreat point can be dry while the straight run to it
        // crosses a river; the bot then swims and strands itself.
        private static bool CrossesWater(Vector3 from, Vector3 to)
        {
            var offset = to - from;
            offset.y = 0f;
            var samples = Mathf.Clamp(Mathf.CeilToInt(offset.magnitude / 4f), 1, 10);
            var top = Mathf.Max(from.y, to.y) + 6f;
            for (var index = 1; index <= samples; index++)
            {
                var fraction = index / (float)samples;
                var point = from + offset * fraction;
                if (Physics.Raycast(
                        new Vector3(point.x, top, point.z),
                        Vector3.down,
                        out var groundHit,
                        30f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    point = groundHit.point;
                }
                else
                {
                    point.y = Mathf.Lerp(from.y, to.y, fraction);
                }
                if (WaterUtility.isPointUnderwater(point + Vector3.up * 0.5f))
                {
                    return true;
                }
            }
            // Nor end right at the water's edge, where one step back is swimming.
            for (var step = 0; step < 4; step++)
            {
                var edge = to + Quaternion.Euler(0f, step * 90f, 0f) * Vector3.forward * 1.5f;
                if (WaterUtility.isPointUnderwater(edge + Vector3.up * 0.3f))
                {
                    return true;
                }
            }
            return false;
        }

        private Vector3 FindZombieEscapePoint(Vector3 origin, float now)
        {
            var threats = new List<Vector3>();
            var fireThreats = new List<Vector3>();
            var idleThreats = new List<Vector3>();
            // 0.1.174: the Mega counted as one ordinary zombie and only within
            // 30m; Tadeu ran from a swarm toward it (49m away) and died to
            // its boulder at 11m. Now it pushes like a burner from 60m, and
            // no escape point within 25m of it is taken.
            var bossThreats = new List<Vector3>();
            var repulsion = Vector3.zero;
            if (ZombieManager.regions != null)
            {
                foreach (var region in ZombieManager.regions)
                {
                    if (region?.zombies == null)
                    {
                        continue;
                    }
                    foreach (var zombie in region.zombies)
                    {
                        if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                        {
                            continue;
                        }
                        var away = origin - zombie.transform.position;
                        away.y = 0f;
                        if (IsBossZombie(zombie) && away.sqrMagnitude <= SwarmEscapeBossMeters * SwarmEscapeBossMeters)
                        {
                            bossThreats.Add(zombie.transform.position);
                            repulsion += away.normalized * 12f / Mathf.Max(1f, away.magnitude);
                            if (away.sqrMagnitude > 30f * 30f)
                            {
                                continue;
                            }
                            threats.Add(zombie.transform.position);
                            continue;
                        }
                        if (away.sqrMagnitude > 30f * 30f)
                        {
                            continue;
                        }
                        threats.Add(zombie.transform.position);
                        if (!zombie.isHunting)
                        {
                            idleThreats.Add(zombie.transform.position);
                        }
                        var isFireThreat = IsFireZombie(zombie);
                        if (isFireThreat)
                        {
                            fireThreats.Add(zombie.transform.position);
                        }
                        var threatWeight = isFireThreat ? 12f : 1f;
                        // 1/d (not 1/d^2): the horde behind the nearest zombie
                        // must still push the escape direction.
                        repulsion += away.normalized * threatWeight
                            / Mathf.Max(1f, away.magnitude);
                    }
                }
            }

            // 0.1.0-y17.12 (the tester, 18/11: "DESPISTAR TODO MUNDO inclusive
            // eu/bot"): the man it fights pushes the run like the Mega, from
            // where it last saw him, and a point out of his sight is worth
            // more. No wallhack: only a man already found.
            var manKnown = IsPvpShooterKnown(Time.realtimeSinceStartup);
            if (manKnown)
            {
                var awayFromMan = origin - m_PvpLastSeenPoint;
                awayFromMan.y = 0f;
                threats.Add(m_PvpLastSeenPoint);
                repulsion += awayFromMan.normalized * 12f / Mathf.Max(1f, awayFromMan.magnitude);
            }

            if (repulsion.sqrMagnitude < 0.001f)
            {
                repulsion = Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f) * Vector3.forward;
            }
            repulsion.Normalize();

            // Janelas normalmente não pertencem ao grafo A*. Durante uma fuga,
            // teste a abertura fisicamente e atravesse localmente antes de voltar
            // para a navegação global.
            m_SwarmDirectWindowEscape = false;
            for (var offsetStep = -8; offsetStep <= 8; offsetStep++)
            {
                var direction = Quaternion.Euler(0f, offsetStep * 22.5f, 0f) * repulsion;
                if (!TryFindTraversableOpening(
                        origin,
                        direction.normalized,
                        8f,
                        out var openingDistance))
                {
                    continue;
                }
                var windowExit = origin
                    + direction.normalized * (openingDistance + 1.6f);
                if (!IsHazardousPosition(windowExit, now, 1f))
                {
                    if (IsInsideFireDangerZone(windowExit, fireThreats)
                        || IsNearAny(windowExit, bossThreats, SwarmEscapeBossAvoidMeters))
                    {
                        continue;
                    }
                    m_SwarmDirectWindowEscape = true;
                    BotLog(LogLevel.Debug,
                        "Bot escolheu uma janela como saida local durante a fuga em {Position}.",
                        FormatPosition(origin));
                    return windowExit;
                }
            }

            // 0.1.173: the best three points are checked along their real
            // route (a straight line through a wall said nothing of the way
            // round it); where the bot came from is known to be clear, where
            // a horde stood is not.
            m_EscapeCandidates.Clear();
            for (var radius = 14f; radius <= 34f; radius += 5f)
            {
                // Full circle: when every forward direction runs into the
                // horde, the way back out is the only safe one.
                for (var offsetStep = -7; offsetStep <= 8; offsetStep++)
                {
                    var direction = Quaternion.Euler(0f, offsetStep * 22.5f, 0f) * repulsion;
                    var candidate = FindNearestNavigablePoint(origin + direction * radius);
                    // 0.1.174: a point the navmesh snapped back next to the
                    // bot is no escape (17 of 51 points were under 6m).
                    if (WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                        || CrossesWater(origin, candidate)
                        || IsHazardousPosition(candidate, now, 2f)
                        || IsInsideFireDangerZone(candidate, fireThreats)
                        || IsNearAny(candidate, bossThreats, SwarmEscapeBossAvoidMeters)
                        || (candidate - origin).GetHorizontalMagnitude() < SwarmEscapeMinimumMeters
                        || Mathf.Abs(candidate.y - origin.y) > 8f)
                    {
                        continue;
                    }

                    var nearestThreat = 50f;
                    foreach (var threat in threats)
                    {
                        nearestThreat = Mathf.Min(
                            nearestThreat,
                            (candidate - threat).GetHorizontalMagnitude());
                    }
                    var nearestFire = 50f;
                    foreach (var fireThreat in fireThreats)
                    {
                        nearestFire = Mathf.Min(
                            nearestFire,
                            (candidate - fireThreat).GetHorizontalMagnitude());
                    }
                    var score = nearestThreat
                        + nearestFire * 2.5f
                        + Vector3.Dot(direction.normalized, repulsion) * 8f
                        - Mathf.Abs(candidate.y - origin.y) * 0.5f
                        - GetEscapeRouteWakePenalty(origin, candidate, idleThreats)
                        - (IsNearFreshDeath(candidate, FreshDeathMeters) ? FreshDeathEscapePenalty : 0f)
                        + (IsOnRecentTrail(candidate, 6f) ? 6f : 0f)
                        - (IsInHordeMemory(candidate, HordeAvoidMeters) ? 15f : 0f)
                        + (manKnown && !IsSeenFromPvpShooter(candidate) ? 8f : 0f);
                    m_EscapeCandidates.Add(new EscapeCandidate
                    {
                        Point = candidate,
                        Score = score,
                        StraightPenalty = GetEscapeRouteThreatPenalty(origin, candidate, threats)
                    });
                }
            }

            return PickEscapeCandidateByRoute(origin, threats, 1.5f, 6f, 0f, 3f, out var best)
                ? best
                : FindNearestNavigablePoint(origin + repulsion * 20f);
        }

        private const float SwarmEscapeMinimumMeters = 8f;
        private const float SwarmEscapeBossMeters = 60f;
        private const float SwarmEscapeBossAvoidMeters = 25f;

        private static bool IsNearAny(Vector3 position, List<Vector3> points, float meters)
        {
            foreach (var point in points)
            {
                if ((position - point).GetHorizontalMagnitude() < meters)
                {
                    return true;
                }
            }
            return false;
        }

        private static bool IsInsideFireDangerZone(
            Vector3 position,
            IReadOnlyList<Vector3> fireThreats)
        {
            foreach (var fireThreat in fireThreats)
            {
                if ((position - fireThreat).GetHorizontalMagnitude()
                    < FireZombieAvoidRadiusMeters)
                {
                    return true;
                }
            }
            return false;
        }

        private void ScanZombieThreats(
            Vector3 position,
            out int surroundedCount,
            out int nearbyCount,
            out float nearestFireDistance,
            out float nearestZombieDistance)
        {
            surroundedCount = 0;
            nearbyCount = 0;
            nearestFireDistance = float.PositiveInfinity;
            nearestZombieDistance = float.PositiveInfinity;
            if (ZombieManager.regions == null)
            {
                return;
            }

            var surroundedRadiusSquared = SurroundedRadiusMeters * SurroundedRadiusMeters;
            var safeRadiusSquared = SwarmSafeRadiusMeters * SwarmSafeRadiusMeters;
            var fullMoon = LightingManager.isFullMoon;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var offset = zombie.transform.position - position;
                var distance = offset.GetHorizontalMagnitude();
                nearestZombieDistance = Mathf.Min(nearestZombieDistance, distance);
                if (IsFireZombie(zombie))
                {
                    nearestFireDistance = Mathf.Min(nearestFireDistance, distance);
                }
                if (Mathf.Abs(offset.y) > SurroundedMaximumVerticalDifferenceMeters)
                {
                    continue;
                }
                var distanceSquared = distance * distance;
                if (distanceSquared <= surroundedRadiusSquared
                    || (fullMoon
                        && distance <= FullMoonSurroundedHunterMeters
                        && zombie.isHunting
                        && zombie.player == m_Player))
                {
                    surroundedCount++;
                }
                if (distanceSquared <= safeRadiusSquared)
                {
                    nearbyCount++;
                }
            }
            // Under a full moon every zombie hears at 24m, crouched or not:
            // with three within 12m the bot runs from the group right away
            // (the escape keeps hitting while it backs off) instead of
            // sneaking toward one of them.
            if (fullMoon && nearbyCount >= SurroundedZombieCount)
            {
                surroundedCount = Mathf.Max(surroundedCount, nearbyCount);
            }
        }

        private static readonly Dictionary<EZombieSpeciality, bool> s_BossSpecialities =
            new Dictionary<EZombieSpeciality, bool>();

        private static bool IsBossZombie(Zombie zombie)
        {
            var speciality = zombie.speciality;
            if (!s_BossSpecialities.TryGetValue(speciality, out var boss))
            {
                boss = speciality == EZombieSpeciality.MEGA
                    || speciality.ToString().StartsWith("BOSS_", System.StringComparison.Ordinal);
                s_BossSpecialities[speciality] = boss;
            }
            return boss;
        }

        private static string DescribeBoss(Zombie zombie)
        {
            return zombie.speciality == EZombieSpeciality.MEGA ? "o Mega" : "o chefe " + zombie.speciality;
        }

        // 0.1.167: 7 of 11 deaths in the 0.1.166 test (1h47) were the Mega at
        // Olympia Military Base: the bots picked it as a target from 50m and
        // went at it with a knife or bare fists, and the danger zone set after
        // a death only kept exploration out for 30 min. A Mega or boss is never
        // a target now: within 35m the bot runs from it until 55m (or out of
        // its sight past 35m), zombies within 20m of it are left alone, and
        // every bot keeps out of 150m around where one was last seen for 20 min.
        private const float BossFleeMeters = 35f;
        private const float BossFleeReleaseMeters = 55f;
        private const float BossBaitMeters = 20f;
        private const float BossZoneSeconds = 1200f;
        private static readonly List<KeyValuePair<Vector3, float>> s_BossZones = new List<KeyValuePair<Vector3, float>>();
        private Zombie? m_CachedNearestBoss;
        private float m_CachedNearestBossDistance = float.PositiveInfinity;
        private bool m_BossFleeActive;
        private float m_NextBossFleeReplanAt;
        private float m_NextBossZoneNoteAt;

        private void UpdateBossThreat(Vector3 position, float now)
        {
            m_CachedNearestBoss = null;
            m_CachedNearestBossDistance = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null
                    || zombie.isDead
                    || !zombie.gameObject.activeInHierarchy
                    || !IsBossZombie(zombie))
                {
                    continue;
                }
                var distance = (zombie.transform.position - position).GetHorizontalMagnitude();
                if (distance < m_CachedNearestBossDistance)
                {
                    m_CachedNearestBossDistance = distance;
                    m_CachedNearestBoss = zombie;
                }
            }
            var boss = m_CachedNearestBoss;
            if (boss == null)
            {
                return;
            }
            if (m_BossHuntActive && m_BossHuntTarget != null && m_PerceivedZombies.ContainsKey(m_BossHuntTarget))
            {
                m_BossHuntLastSeenAt = now;
            }
            if (m_TargetZombie != null && IsBossZombie(m_TargetZombie) && !IsHuntedBoss(m_TargetZombie))
            {
                m_TargetZombie = null;
                if (m_ObjectiveType == ObjectiveType.Combat)
                {
                    ClearObjective();
                }
            }
            NoteBossZone(boss, now);
            // 0.2.2c: the Mega walked up to where the bot was going.
            if ((m_ObjectiveType == ObjectiveType.Loot || m_ObjectiveType == ObjectiveType.Patrol)
                && IsWithinMegaReach(m_ObjectivePosition))
            {
                BotLog(LogLevel.Information,
                    "Desistindo de {Objective} em {Position}: fica a menos de {Radius:0}m de {Boss} (nao puxar o Mega).",
                    m_ObjectiveType == ObjectiveType.Loot ? "loot" : "ponto de patrulha",
                    FormatPosition(m_ObjectivePosition),
                    GetMegaNoLureMeters(),
                    DescribeBoss(boss));
                ClearObjective();
            }
        }

        private bool IsNearKnownBoss(Vector3 point)
        {
            var boss = m_CachedNearestBoss;
            return boss != null
                && !boss.isDead
                && (boss.transform.position - point).GetHorizontalMagnitude() < BossBaitMeters;
        }

        // 0.2.2c: "just don't lure the Mega". The bot used to drop its whole
        // area when a Mega showed up within 150m (XX left Olympia after one
        // minute). With megaNoLure it stays: loot and patrol points within
        // BossNoLureMeters of the Mega (about the reach at which a zombie
        // spots a standing player) are skipped, and only an area or trip
        // centered next to where it was seen is left.
        private const float BossNoLureMeters = 55f;
        private const float BossNoLureZoneMeters = 45f;

        private static bool MegaNoLure => s_Settings.MegaNoLure;

        private bool IsWithinMegaReach(Vector3 point)
        {
            if (IsMegaRouteAvoided(point))
            {
                return true;
            }
            if (!MegaNoLure)
            {
                return false;
            }
            var boss = m_CachedNearestBoss;
            if (boss != null
                && !boss.isDead
                && !IsHuntedBoss(boss)
                && (boss.transform.position - point).GetHorizontalMagnitude() < GetMegaNoLureMeters())
            {
                return true;
            }
            if (m_BossHuntActive)
            {
                return false;
            }
            // Where any bot saw it in the last 2 min (a zone lasts 20 min,
            // and an old one is only where the Mega walked past).
            // 0.2.2x1 (doc 16.5, item 13): the tryhard zone was 10m, meant
            // for loot next to a Mega in sight that has not seen the bot;
            // llo patrolled back 12m from where it was and met it at 2m
            // (22:47:03, 57 health in 2s). Out of sight it is 30m for 5 min,
            // 55m without an automatic gun.
            // 0.2.2x13: the tryhard goes by the Mega where it is now, as the
            // players do (36 visits to the Seattle Mega's block against 10 of
            // the bots, twice as long at Olympia); where it was seen is not a
            // no-go zone for 5 min any more.
            if (Tryhard)
            {
                return false;
            }
            var realNow = Time.realtimeSinceStartup;
            var zoneMeters = Tryhard ? GetTryhardMegaZoneMeters() : BossNoLureZoneMeters;
            var zoneAge = Tryhard ? 300f : 120f;
            foreach (var zone in s_BossZones)
            {
                if (realNow < zone.Value
                    && zone.Value - realNow > BossZoneSeconds - zoneAge
                    && (zone.Key - point).GetHorizontalMagnitude() < zoneMeters)
                {
                    return true;
                }
            }
            return false;
        }

        private void NoteBossZone(Zombie boss, float now)
        {
            if (now < m_NextBossZoneNoteAt)
            {
                return;
            }
            m_NextBossZoneNoteAt = now + 10f;
            var realNow = Time.realtimeSinceStartup;
            var bossPosition = boss.transform.position;
            var known = s_BossZones.Exists(zone => realNow < zone.Value
                && (zone.Key - bossPosition).GetHorizontalMagnitude() <= 40f);
            s_BossZones.RemoveAll(zone => realNow >= zone.Value
                || (zone.Key - bossPosition).GetHorizontalMagnitude() <= 40f);
            s_BossZones.Add(new KeyValuePair<Vector3, float>(bossPosition, realNow + BossZoneSeconds));
            if (!known)
            {
                BotLog(LogLevel.Information,
                    "Bot viu {Boss} em {Position}; todos os bots evitam {Radius:0}m em volta por {Seconds:0}s.",
                    DescribeBoss(boss),
                    FormatPosition(bossPosition),
                    Tryhard ? GetTryhardMegaZoneMeters() : MegaNoLure ? BossNoLureMeters : DangerZoneAreaMeters,
                    BossZoneSeconds);
            }
            if (Tryhard)
            {
                return;
            }
            var leaveRadius = MegaNoLure ? BossNoLureZoneMeters : DangerZoneAreaMeters;
            if (m_HasInterestArea
                && (m_InterestAreaCenter - bossPosition).GetHorizontalMagnitude() <= leaveRadius)
            {
                BotLog(LogLevel.Information,
                    "Area {Area} fica a {Distance:0}m de {Boss}; saindo dela.",
                    m_InterestAreaName,
                    (m_InterestAreaCenter - bossPosition).GetHorizontalMagnitude(),
                    DescribeBoss(boss));
                FinishInterestArea(now);
                m_NextExplorationSelectionTime = now;
                if (m_ObjectiveType == ObjectiveType.Patrol || m_ObjectiveType == ObjectiveType.Explore)
                {
                    ClearObjective();
                }
            }
            if (m_TravelActive && (m_TravelTarget - bossPosition).GetHorizontalMagnitude() <= leaveRadius)
            {
                BotLog(LogLevel.Information,
                    "Viagem ate {Name} cancelada: o destino fica a {Distance:0}m de {Boss}.",
                    m_TravelTargetName,
                    (m_TravelTarget - bossPosition).GetHorizontalMagnitude(),
                    DescribeBoss(boss));
                m_TravelActive = false;
                m_TravelPhase = 0;
                m_TravelMeshArea = false;
                if (m_ObjectiveType == ObjectiveType.Travel)
                {
                    ClearObjective();
                }
            }
        }

        private void EndBossFlee(string reason, bool escaped = true)
        {
            if (!m_BossFleeActive)
            {
                return;
            }
            m_BossFleeActive = false;
            if (m_ObjectiveType == ObjectiveType.Flee)
            {
                ClearObjective();
            }
            BotLog(LogLevel.Information,
                "Fuga do chefe encerrada: {Reason}; vida {Health}.",
                reason,
                m_Player.life.health);
            if (escaped)
            {
                var boss = m_CachedNearestBoss;
                StartDisengage(
                    boss != null && !boss.isDead && boss.gameObject.activeInHierarchy
                        ? boss.transform.position
                        : GetThreatCentroid(m_BehaviorPosition, 30f),
                    "fugir do chefe",
                    m_BehaviorNow);
            }
        }

        // ---- 0.1.167: hunting the Mega, only when the bot can win ----
        // By default the Mega is avoided (above). The bot goes for it only with
        // a gun that is not a bow and enough rounds to deal 1.3 times the
        // Mega's current health (with other bots hunting it close by, their
        // rounds count too, as long as this bot brings 40%), health 75+, not
        // bleeding or with a broken leg, and at most 2 other zombies within
        // 25m. It shoots from 15-35m (0.2.0: up to 70m), backs off to 22m when the Mega gets
        // within 15m, deals with a zombie within 6m first, and gives up (then
        // flees, no new try for 5 min) under 50 health, when the rounds no
        // longer cover the Mega's health, on a boulder hit, with 3+ zombies
        // within 20m, after 3 min, or with the Mega out of sight for 8s.
        // 0.2.0: 70m (was 60), the farthest a player hit the Mega on 11-08
        // was 66m; the bullets now fly with their drop (AttachGunHits).
        private const float BossHuntStartMeters = 70f;
        private const float BossHuntShootMeters = 70f;
        private const float BossHuntKiteMeters = 15f;
        private const float BossTreatmentRunMeters = 40f;
        private const float BossHuntKiteReleaseMeters = 22f;
        // 0.1.170: half again the Mega's health in expected damage. With
        // the share below a 99-damage rifle (Eaglefire, Heartbreaker,
        // Maplestrike) needs 114 rounds for a full Mega: the gun full and
        // three full magazines.
        private const float BossHuntDamageMargin = 1.5f;
        private const float BossHuntOwnShare = 0.4f;
        // 0.2.2x13: the players take a Mega on with what they carry (about
        // 30 hits a kill) and leave it when the ammo is gone.
        private const float TryhardHuntOwnShare = 0.25f;
        private const float TryhardHuntKeepShare = 0.25f;
        // 0.1.170: with real shots (0.1.169) misses and body hits put about
        // 40% of a gun's listed zombie damage into the Mega. thigas went
        // hunting it with 11781 of listed damage against 2999 of health, the
        // Mega was on him 4s later and he died 15s after starting; Tadeu
        // followed and died too.
        private const float BossHuntHitShare = 0.4f;
        // 0.1.170: the Mega closed from 50m to 15m in 4s on thigas. A gun must
        // put a quarter of its health in with one magazine (rules out bolt
        // rifles, pistols and 5-12 round guns), and start with the magazine
        // nearly full: Tadeu went with 3 rounds in his and was reloading with
        // the Mega on him.
        private const float BossHuntMagazineShare = 0.25f;
        private const float BossHuntLoadedShare = 0.8f;
        private const byte BossHuntStartHealth = 75;
        private const byte BossHuntAbortHealth = 50;
        private const float BossHuntCrowdMeters = 25f;
        private const int BossHuntCrowdStart = 2;
        private const float BossHuntCrowdAbortMeters = 20f;
        private const int BossHuntCrowdAbort = 3;
        private const float BossHuntMaxSeconds = 180f;
        private const float BossHuntLostSightSeconds = 8f;
        private const float BossHuntCooldownSeconds = 300f;
        private const float BossHuntTeamMeters = 80f;
        private const float BossHuntUtility = 940f;
        // 0.2.2x1 (doc 16.3, item 5): out to 50m, the far, high spot with a
        // line from a prone eye first (Tadeu killed one prone at 47m in 4s).
        private static readonly float[] s_BossFiringSpotRadii = { 22f, 28f, 34f, 40f, 45f, 50f };
        private bool m_BossHuntActive;
        private Zombie? m_BossHuntTarget;
        private float m_BossHuntSince;
        private float m_BossHuntLastSeenAt;
        private float m_BossHuntBlockedUntil;
        private bool m_BossHuntKiting;
        private bool m_BossBoulderHit;
        private float m_BossHuntOffer;
        private float m_BossHuntOfferAt = float.NegativeInfinity;
        private Zombie? m_BossHuntOfferBoss;
        private float m_NextBossHuntCheckAt;
        private float m_NextBossHuntRefusalLogAt;
        private float m_NextBossHuntMeleeLogAt;

        private bool IsHuntedBoss(Zombie? zombie)
        {
            return m_BossHuntActive && zombie != null && zombie == m_BossHuntTarget;
        }

        private int CountRoundsFor(ItemGunAsset gun)
        {
            if (!gun.allowMagazineChange)
            {
                return 0;
            }
            var rounds = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMagazineAsset magazine
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        rounds += jar.item.amount;
                    }
                }
            }
            return rounds;
        }

        // What the bot can still put into the Mega with its best gun that is
        // not a bow: the rounds in it plus those in magazines that fit it,
        // times the share of the listed damage that really lands. 0.1.170:
        // only guns whose one magazine puts a quarter of the Mega's health in
        // (a sniper rifle with many rounds is not picked over a rifle that
        // qualifies).
        private float GetBossHuntDamage(Zombie boss, out string weaponName)
        {
            return GetBossHuntDamage(boss, out weaponName, out _, out _, out _);
        }

        private static float BossHuntMagazineDamage(ItemGunAsset gun)
        {
            return gun.ammoMax
                * (gun.zombieDamageMultiplier != null ? gun.zombieDamageMultiplier.damage : 0f)
                * BossHuntHitShare;
        }

        // 0.2.2v (doc 13.3, item 1): the tryhard starts with 1.2 times the
        // Mega's health (the 0.4 hit share is already pessimistic: XX killed
        // it with 6890 expected); "equipped" uses the same number, so a bot
        // that calls itself ready can really hunt.
        private const float TryhardHuntMargin = 0.6f;
        private const float TryhardHuntLostSightSeconds = 20f;
        private const float TryhardHuntCrowdMeters = 10f;
        private const int TryhardHuntCrowd = 5;
        private const float TryhardHuntCooldownSeconds = 60f;

        private float GetBossHuntMargin()
        {
            return Tryhard ? TryhardHuntMargin : BossHuntDamageMargin;
        }

        private float GetBossHuntDamage(Zombie boss, out string weaponName, out ItemGunAsset? bestGun, out int bestLoaded, out bool bestEquipped)
        {
            return GetBossHuntDamageFor(boss.health, out weaponName, out bestGun, out bestLoaded, out bestEquipped);
        }

        private float GetBossHuntDamageFor(float bossHealth, out string weaponName, out ItemGunAsset? bestGun, out int bestLoaded, out bool bestEquipped)
        {
            var minimumMagazineDamage = bossHealth * BossHuntMagazineShare;
            weaponName = "nenhuma";
            bestGun = null;
            bestLoaded = 0;
            bestEquipped = false;
            var best = 0f;
            var equipment = m_Player.equipment;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemGunAsset gun)
                        || gun.ammoMax < 5
                        // 0.2.2x1 (doc 16.3, item 3): the tryhard takes on
                        // the Mega only with an automatic gun.
                        // 0.2.2x3 (doc 16.9, item 3): automatic and of
                        // Military or Ranger caliber; the Cobra (civilian,
                        // 20 rounds) killed no Mega in 4 hunts.
                        || (Tryhard && !IsTryhardMegaGun(gun))
                        || BossHuntMagazineDamage(gun) < minimumMagazineDamage)
                    {
                        continue;
                    }
                    var equipped = equipment.equippedPage == page
                        && equipment.equipped_x == jar.x
                        && equipment.equipped_y == jar.y;
                    var state = equipped ? equipment.state : jar.item.state;
                    var rounds = CountRoundsFor(gun);
                    var loaded = 0;
                    if (state != null
                        && state.Length > 10
                        && (equipped || !IsKnownEmptyGunSlot(page, jar.x, jar.y)))
                    {
                        loaded = state[10];
                        rounds += loaded;
                    }
                    var damage = (gun.zombieDamageMultiplier != null ? gun.zombieDamageMultiplier.damage : 0f) * rounds * BossHuntHitShare;
                    if (damage > best)
                    {
                        best = damage;
                        weaponName = gun.itemName;
                        bestGun = gun;
                        bestLoaded = loaded;
                        bestEquipped = equipped;
                    }
                }
            }
            return best;
        }

        // A partly empty magazine swapped for the fullest one carried, like
        // a player pressing R before the fight.
        private float m_HoldFireForReloadUntil;
        private float m_MegaBelowSince = -1f;

        private bool TryTopOffEquippedGun(ItemGunAsset gun, int loaded, float now, string when = "antes de cacar o Mega")
        {
            var useableGun = m_Player.equipment.useable as UseableGun;
            if (useableGun == null || !m_Player.equipment.IsEquipAnimationFinished)
            {
                return false;
            }
            if (useableGun.isReloading)
            {
                return true;
            }
            if (now < m_NextReloadAttemptAt
                || !gun.allowMagazineChange
                || !TryFindMagazineFor(gun, out var page, out var jar)
                || jar.item.amount <= loaded
                || !(jar.GetAsset() is ItemMagazineAsset magazine))
            {
                return false;
            }
            // 0.2.2x3 (doc 16.9, item 3): the server drops the swap while the
            // gun fires or the hands are busy (thigas, 14:59:30-35: 3 swaps
            // logged, none taken). The trigger is let go first.
            if (useableGun.isFired || m_GunTriggerHeld || m_Player.equipment.isBusy)
            {
                var realNow = Time.realtimeSinceStartup;
                m_HoldFireForReloadUntil = realNow + 0.6f;
                m_NextAttackTime = Mathf.Max(m_NextAttackTime, realNow + 0.6f);
                return false;
            }
            m_NextReloadAttemptAt = now + 1.5f;
            useableGun.ReceiveAttachMagazine(default, page, jar.x, jar.y, magazine.hash);
            ClearKnownEmptyGun();
            BotLog(LogLevel.Information,
                "Trocando o pente de {Gun} ({Loaded} de {Max}) por um com {Amount} {When}.",
                gun.itemName,
                loaded,
                gun.ammoMax,
                jar.item.amount,
                when);
            return true;
        }

        private int CountOtherZombiesWithin(Vector3 position, float radius)
        {
            var count = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null
                    && !zombie.isDead
                    && zombie.gameObject.activeInHierarchy
                    && !IsBossZombie(zombie)
                    && (zombie.transform.position - position).GetHorizontalMagnitude() <= radius)
                {
                    count++;
                }
            }
            return count;
        }

        private bool CanJoinBossHunt(Zombie boss, float now, out float damage, out string detail)
        {
            damage = 0f;
            var life = m_Player.life;
            if (boss.speciality != EZombieSpeciality.MEGA)
            {
                detail = "so o Mega e cacado";
                return false;
            }
            // 0.2.2x3 (doc 16.9, item 2): Tadeu started a hunt with the Mega
            // at 3m and was at 29 in 4s; that close, the flee opens room first.
            var startDistance = (boss.transform.position - m_BehaviorPosition).GetHorizontalMagnitude();
            if (Tryhard && !m_BossHuntActive && startDistance < TryhardMegaBreakMeters)
            {
                detail = "o Mega a " + startDistance.ToString("0.#") + "m, perto demais para comecar; abrindo distancia antes";
                return false;
            }
            if (life.health < BossHuntStartHealth || life.isBleeding || life.isBroken)
            {
                detail = "vida " + life.health + (life.isBleeding ? ", sangrando" : string.Empty)
                    + (life.isBroken ? ", perna quebrada" : string.Empty);
                return false;
            }
            damage = GetBossHuntDamage(boss, out var weapon, out var gun, out var loaded, out var equipped);
            if (damage <= 0f || gun == null)
            {
                detail = (Tryhard ? "sem automatica de calibre Military ou Ranger com municao que tire " : "sem arma com municao que tire ")
                    + (boss.health * BossHuntMagazineShare).ToString("0")
                    + " num pente (arco, pistola, escopeta e fuzil de ferrolho nao contam)";
                damage = 0f;
                return false;
            }
            if (loaded < Mathf.CeilToInt(gun.ammoMax * BossHuntLoadedShare))
            {
                detail = equipped && TryTopOffEquippedGun(gun, loaded, now)
                    ? "trocando o pente de " + weapon + " (" + loaded + " de " + gun.ammoMax + ") antes de cacar"
                    : weapon + " com " + loaded + " de " + gun.ammoMax + " no pente";
                damage = 0f;
                return false;
            }
            var startMeters = Tryhard ? TryhardHuntCrowdMeters : BossHuntCrowdMeters;
            var crowd = CountOtherZombiesWithin(m_BehaviorPosition, startMeters);
            if (Tryhard ? crowd >= TryhardHuntCrowd : crowd > BossHuntCrowdStart)
            {
                detail = crowd + " zumbis a " + startMeters.ToString("0") + "m";
                return false;
            }
            detail = weapon;
            m_BossHuntCandidateGun = gun;
            return true;
        }

        // Other bots that can hunt the same Mega and are close to it add their
        // rounds: each publishes its offer once a second.
        private float GetBossHuntTeamDamage(Zombie boss, float ownDamage)
        {
            var total = ownDamage;
            var realNow = Time.realtimeSinceStartup;
            foreach (var other in s_ActiveSimulations.Values)
            {
                if (other == this
                    || other.m_BossHuntOfferBoss != boss
                    || realNow - other.m_BossHuntOfferAt > 5f
                    || (other.m_Player.transform.position - boss.transform.position).GetHorizontalMagnitude() > BossHuntTeamMeters)
                {
                    continue;
                }
                total += other.m_BossHuntOffer;
            }
            return total;
        }

        private void PublishBossHuntOffer(Zombie? boss, float damage)
        {
            m_BossHuntOffer = damage;
            m_BossHuntOfferAt = Time.realtimeSinceStartup;
            m_BossHuntOfferBoss = boss;
        }

        private void LogBossHuntRefusal(float now, Zombie boss, string reason)
        {
            if (now < m_NextBossHuntRefusalLogAt)
            {
                return;
            }
            m_NextBossHuntRefusalLogAt = now + 30f;
            BotLog(LogLevel.Information,
                "Nao vai cacar {Boss} a {Distance:0}m (vida dele {BossHealth}): {Reason}.",
                DescribeBoss(boss),
                (boss.transform.position - m_BehaviorPosition).GetHorizontalMagnitude(),
                boss.health,
                reason);
        }

        private float GetBossHuntUtility()
        {
            var now = m_BehaviorNow;
            if (m_BossHuntActive)
            {
                if (TryGetBossHuntAbortReason(now, out var abort))
                {
                    EndBossHunt(now, abort);
                    return -1f;
                }
                return BossHuntUtility;
            }
            var boss = m_CachedNearestBoss;
            if (boss == null
                || boss.isDead
                || !boss.gameObject.activeInHierarchy
                || now < m_BossHuntBlockedUntil
                || m_CachedNearestBossDistance > BossHuntStartMeters)
            {
                return -1f;
            }
            if (now < m_NextBossHuntCheckAt)
            {
                return -1f;
            }
            m_NextBossHuntCheckAt = now + 1f;
            if (!CanJoinBossHunt(boss, now, out var damage, out var detail))
            {
                PublishBossHuntOffer(null, 0f);
                LogBossHuntRefusal(now, boss, detail);
                return -1f;
            }
            PublishBossHuntOffer(boss, damage);
            var team = GetBossHuntTeamDamage(boss, damage);
            if (damage < boss.health * (Tryhard ? TryhardHuntOwnShare : BossHuntOwnShare) || team < boss.health * GetBossHuntMargin())
            {
                LogBossHuntRefusal(now, boss,
                    "dano esperado " + team.ToString("0")
                    + (team > damage ? " (com outros bots)" : string.Empty)
                    + ", precisa de " + (boss.health * GetBossHuntMargin()).ToString("0"));
                return -1f;
            }
            m_BossHuntActive = true;
            m_BossHuntTarget = boss;
            m_BossHuntGun = m_BossHuntCandidateGun;
            m_BossHuntSince = now;
            m_BossHuntLastSeenAt = now;
            m_BossHuntKiting = false;
            m_BossBoulderHit = false;
            EndBossFlee("vai cacar " + DescribeBoss(boss), false);
            // 0.2.2x2 (doc 16.7, item 4): Tadeu held the Butterfly Knife for
            // 8s after choosing the hunt (23:41:30-38); the gun comes now.
            m_NextBossHuntEquipAt = 0f;
            m_MegaBelowSince = -1f;
            EquipBossHuntGun(now);
            BotLog(LogLevel.Information,
                "Cacando {Boss} a {Distance:0}m: vida dele {BossHealth}, dano esperado {Damage:0}{Team}, arma {Weapon}, vida do bot {Health}.",
                DescribeBoss(boss),
                m_CachedNearestBossDistance,
                boss.health,
                damage,
                team > damage ? " (" + team.ToString("0") + " com outros bots)" : string.Empty,
                detail,
                m_Player.life.health);
            return BossHuntUtility;
        }

        private bool TryGetBossHuntAbortReason(float now, out string reason)
        {
            var boss = m_BossHuntTarget;
            var life = m_Player.life;
            if (boss == null || boss.isDead || !boss.gameObject.activeInHierarchy)
            {
                reason = boss != null && boss.isDead ? "o Mega morreu" : "o Mega sumiu";
                return true;
            }
            // 0.2.2v (doc 13.3, item 2): a line from the bot counts as
            // seeing it (perception alone dropped the Mega at 40m+), and the
            // tryhard gives it 20s, walking to where it was last seen.
            if (Tryhard
                && (boss.transform.position - m_BehaviorPosition).GetHorizontalMagnitude() <= BossHuntStartMeters + 20f
                && HasClearLineToPoint(GetZombieAimPoint(boss)))
            {
                m_BossHuntLastSeenAt = now;
            }
            if (now - m_BossHuntLastSeenAt > (Tryhard ? TryhardHuntLostSightSeconds : BossHuntLostSightSeconds))
            {
                reason = "perdeu o Mega de vista";
                return true;
            }
            if (life.health < BossHuntAbortHealth)
            {
                reason = "vida " + life.health;
                return true;
            }
            // 0.2.2u: the tryhard goes on after a boulder (the health limit
            // above still ends the hunt).
            if (m_BossBoulderHit && !Tryhard)
            {
                reason = "levou uma pedrada";
                return true;
            }
            // 0.2.2x3 (doc 16.9, item 1): Tadeu on an upper floor (y 49.7)
            // with the Mega 11m below: 2 min of hunt with no line and no way
            // down to the firing spot. 6s above it with no line ends it.
            if (Tryhard)
            {
                var above = m_BehaviorPosition.y - boss.transform.position.y;
                if (above > 3f && !HasClearLineToPoint(GetZombieAimPoint(boss)))
                {
                    if (m_MegaBelowSince < 0f)
                    {
                        m_MegaBelowSince = now;
                    }
                    else if (now - m_MegaBelowSince > 6f)
                    {
                        m_MegaBelowSince = -1f;
                        reason = "o Mega " + above.ToString("0") + "m abaixo, sem linha daqui";
                        return true;
                    }
                }
                else
                {
                    m_MegaBelowSince = -1f;
                }
            }
            if (now - m_BossHuntSince > BossHuntMaxSeconds)
            {
                reason = "passou de " + BossHuntMaxSeconds.ToString("0") + "s";
                return true;
            }
            // 0.2.2v (doc 13.3, item 2): 3 commons within 20m ended the
            // Seattle hunt after 8s (18:59:34); the tryhard shoots those
            // that come within 4m and gives up only to a crowd on top of it.
            var crowdMeters = Tryhard ? TryhardHuntCrowdMeters : BossHuntCrowdAbortMeters;
            var crowd = CountOtherZombiesWithin(m_BehaviorPosition, crowdMeters);
            if (crowd >= (Tryhard ? TryhardHuntCrowd : BossHuntCrowdAbort))
            {
                reason = crowd + " zumbis a " + crowdMeters.ToString("0") + "m";
                return true;
            }
            if (now >= m_NextBossHuntCheckAt)
            {
                m_NextBossHuntCheckAt = now + 1f;
                var damage = GetBossHuntDamage(boss, out _);
                PublishBossHuntOffer(boss, damage);
                var team = GetBossHuntTeamDamage(boss, damage);
                if (damage <= 0f || team < boss.health * (Tryhard ? TryhardHuntKeepShare : 1f))
                {
                    reason = "a municao nao da mais (dano " + team.ToString("0") + ", vida do Mega " + boss.health + ")";
                    return true;
                }
            }
            reason = string.Empty;
            return false;
        }

        private void EndBossHunt(float now, string reason)
        {
            var boss = m_BossHuntTarget;
            var killed = boss != null && boss.isDead;
            if (Tryhard && boss != null && !boss.isDead && reason == "perdeu o Mega de vista")
            {
                StartMegaLostAlert(boss.transform.position, now);
            }
            m_BossHuntActive = false;
            m_BossHuntTarget = null;
            m_BossHuntGun = null;
            m_BossHuntKiting = false;
            m_BossBoulderHit = false;
            PublishBossHuntOffer(null, 0f);
            var cooldown = Tryhard ? TryhardHuntCooldownSeconds : BossHuntCooldownSeconds;
            if (!killed)
            {
                m_BossHuntBlockedUntil = now + cooldown;
            }
            if (boss != null && m_TargetZombie == boss)
            {
                m_TargetZombie = null;
            }
            if (m_ObjectiveType == ObjectiveType.Combat || m_ObjectiveType == ObjectiveType.Flee)
            {
                ClearObjective();
            }
            BotLog(LogLevel.Information,
                "Caca ao Mega encerrada: {Reason}; vida do bot {Health}, {Seconds:0}s de caca{Retry}.",
                reason,
                m_Player.life.health,
                now - m_BossHuntSince,
                killed ? string.Empty : "; nova tentativa so daqui a " + cooldown.ToString("0") + "s");
        }

        private void NoteBossBoulderHit(byte amount)
        {
            if (m_BoulderDodgePhase != 0 || m_BoulderDodgeResultPending)
            {
                m_BoulderDodgeHitDamage += amount;
            }
            if (!m_BossHuntActive)
            {
                return;
            }
            m_BossBoulderHit = true;
            BotLog(LogLevel.Information,
                "Pedrada do Mega durante a caca: {Amount} de dano (vida {Health}).",
                amount,
                m_Player.life.health);
        }

        // 0.1.170: the Mega stops and winds up for a second (throwTime)
        // before the boulder leaves, then aims at the player plus 10-20% of
        // the distance in the direction the player is moving
        // (Zombie.tick). Like a player: run sideways while it winds up and
        // turn back the moment the boulder leaves; it flies to where the bot
        // was heading. thigas took two boulders (120 health) running straight
        // away in the 0.1.169 test. The legs go 30-65 degrees off "away
        // from the Mega", not square to it: the Mega runs 6 m/s and the bot
        // sprints 7, so a dodge straight sideways handed it 6m every throw,
        // while these still gain 3-5m (the Mega stands still while it
        // winds up).
        private const float BoulderDodgeCheckMeters = 70f;
        // The boulder must be gone before the bot turns back, or the
        // direction it aims ahead by is the new one.
        // 0.1.170 (the tester: "vai seguir o mesmo padrao de movimento
        // previsivel?"): every dodge is drawn anew, like a player's: a
        // reaction of 0.1-0.35s, legs 30-65 degrees off "away", the side by
        // the room it has (a coin when both have room), the turn back
        // 0.05-0.25s after the boulder leaves and 0.8-1.3s on the way back.
        private const float BoulderDodgeLegSeconds = 1.3f;
        private int m_BoulderDodgePhase;
        private Zombie? m_BoulderDodgeBoss;
        private Vector3 m_BoulderDodgeSide;
        private Vector3 m_BoulderDodgeSecondLeg;
        private byte m_BoulderDodgeAnalog = 0x11;
        private float m_BoulderDodgeMoveAt;
        private float m_BoulderDodgeReleaseAt;
        private float m_BoulderDodgeTurnAt;
        private float m_BoulderDodgeEndsAt;
        private float m_BoulderDodgeLastSpecial = float.NegativeInfinity;
        private float m_BoulderDodgeDistance;
        private bool m_BoulderDodgeResultPending;
        private float m_BoulderDodgeResultAt;
        private int m_BoulderDodgeHitDamage;

        private bool UpdateBoulderDodge(Vector3 position)
        {
            var gameNow = Time.time;
            if (m_BoulderDodgeResultPending && m_BoulderDodgePhase == 0 && gameNow >= m_BoulderDodgeResultAt)
            {
                m_BoulderDodgeResultPending = false;
                BotLog(LogLevel.Information,
                    "Esquiva da pedrada a {Distance:0}m: {Result} (vida {Health}).",
                    m_BoulderDodgeDistance,
                    m_BoulderDodgeHitDamage > 0 ? "acertou, " + m_BoulderDodgeHitDamage + " de dano" : "a pedra errou",
                    m_Player.life.health);
            }
            if (m_BoulderDodgePhase == 0)
            {
                var thrower = FindBoulderThrower(position);
                if (thrower == null)
                {
                    return false;
                }
                StartBoulderDodge(thrower, position, gameNow);
            }
            var boss = m_BoulderDodgeBoss;
            if (boss == null
                || boss.isDead
                || m_Player.stance.stance == EPlayerStance.SWIM
                || m_Player.stance.stance == EPlayerStance.CLIMB
                || m_ObjectiveType == ObjectiveType.Ladder)
            {
                EndBoulderDodge(gameNow);
                return false;
            }
            if (m_BoulderDodgePhase == 1)
            {
                // Seen the boulder leave (or it is late): turn back a moment later.
                if (m_BoulderDodgeTurnAt <= 0f
                    && (!boss.isThrowingBoulder || gameNow >= m_BoulderDodgeReleaseAt + 0.15f))
                {
                    m_BoulderDodgeTurnAt = gameNow + Random.Range(0.05f, 0.25f);
                }
                if (m_BoulderDodgeTurnAt > 0f && gameNow >= m_BoulderDodgeTurnAt)
                {
                    m_BoulderDodgePhase = 2;
                    // The mirror leg from where the bot is now; with no room
                    // for it, back over the ground just run (toward the Mega,
                    // but still out of the line the boulder was aimed on).
                    m_BoulderDodgeSide = SideClearance(position, m_BoulderDodgeSecondLeg) >= 4f
                        ? m_BoulderDodgeSecondLeg
                        : -m_BoulderDodgeSide;
                    m_BoulderDodgeEndsAt = gameNow + Random.Range(0.8f, 1.3f);
                }
                else if (gameNow > m_BoulderDodgeReleaseAt + BoulderDodgeLegSeconds)
                {
                    EndBoulderDodge(gameNow);
                    return false;
                }
            }
            if (m_BoulderDodgePhase == 2 && gameNow >= m_BoulderDodgeEndsAt)
            {
                EndBoulderDodge(gameNow);
                return false;
            }
            if (gameNow < m_BoulderDodgeMoveAt)
            {
                // Still "seeing" the wind-up: the bot does what it was doing.
                return false;
            }
            m_IsWalking = true;
            m_IsSprinting = true;
            m_PrimaryAttackHeld = false;
            m_SecondaryAttackHeld = false;
            m_DesiredYaw = m_CurrentYaw;
            m_BoulderDodgeAnalog = AnalogToward(m_BoulderDodgeSide, m_CurrentYaw);
            return true;
        }

        private Zombie? FindBoulderThrower(Vector3 position)
        {
            if (IsThrowingBoulderAtBot(m_CachedNearestBoss, position))
            {
                return m_CachedNearestBoss;
            }
            foreach (var perceived in m_PerceivedZombies)
            {
                if (IsThrowingBoulderAtBot(perceived.Key, position))
                {
                    return perceived.Key;
                }
            }
            return null;
        }

        private bool IsThrowingBoulderAtBot(Zombie? zombie, Vector3 position)
        {
            return zombie != null
                && !zombie.isDead
                && zombie.isThrowingBoulder
                && zombie.player == m_Player
                && zombie.lastSpecial != m_BoulderDodgeLastSpecial
                && Time.time - zombie.lastSpecial < zombie.throwTime
                && (zombie.transform.position - position).GetHorizontalMagnitude() <= BoulderDodgeCheckMeters;
        }

        private static Vector3 DodgeLeg(Vector3 away, Vector3 right, float degrees)
        {
            var radians = degrees * Mathf.Deg2Rad;
            return (away * Mathf.Cos(radians) + right * Mathf.Sin(radians)).normalized;
        }

        private void StartBoulderDodge(Zombie boss, Vector3 position, float gameNow)
        {
            m_BoulderDodgeBoss = boss;
            m_BoulderDodgeLastSpecial = boss.lastSpecial;
            m_BoulderDodgeReleaseAt = boss.lastSpecial + boss.throwTime;
            m_BoulderDodgeMoveAt = gameNow + Random.Range(0.1f, 0.35f);
            m_BoulderDodgeTurnAt = 0f;
            m_BoulderDodgePhase = 1;
            m_BoulderDodgeHitDamage = 0;
            m_BoulderDodgeResultPending = false;
            var away = position - boss.transform.position;
            away.y = 0f;
            m_BoulderDodgeDistance = away.magnitude;
            var awayDirection = m_BoulderDodgeDistance > 0.01f ? away / m_BoulderDodgeDistance : Vector3.forward;
            var right = new Vector3(awayDirection.z, 0f, -awayDirection.x);
            // 0.2.2x8 (doc 16.16): under 12m a sideways leg kept the bot in
            // the Mega's swing; there the legs open backwards (20-35 degrees
            // from straight away).
            var closeDodge = m_BoulderDodgeDistance < 12f;
            var minLeg = closeDodge ? 20f : 30f;
            var maxLeg = closeDodge ? 35f : 65f;
            var rightLeg = DodgeLeg(awayDirection, right, Random.Range(minLeg, maxLeg));
            var leftLeg = DodgeLeg(awayDirection, right, -Random.Range(minLeg, maxLeg));
            // The first leg runs about a second: the side with more room,
            // a coin when both have it, and now and then the other one.
            var rightClear = SideClearance(position, rightLeg);
            var leftClear = SideClearance(position, leftLeg);
            bool goRight;
            if (rightClear >= 4f && leftClear >= 4f)
            {
                goRight = Random.value < 0.5f;
            }
            else if (rightClear != leftClear)
            {
                goRight = (rightClear > leftClear) == (Random.value < 0.85f);
            }
            else
            {
                goRight = Random.value < 0.5f;
            }
            m_BoulderDodgeSide = goRight ? rightLeg : leftLeg;
            m_BoulderDodgeSecondLeg = goRight ? leftLeg : rightLeg;
            BotLog(LogLevel.Information,
                "{Boss} preparando pedrada a {Distance:0}m: correndo para a {Side} ({Clear:0}m livres) e voltando quando a pedra sair.",
                DescribeBoss(boss),
                m_BoulderDodgeDistance,
                goRight ? "direita" : "esquerda",
                goRight ? rightClear : leftClear);
        }

        private static float SideClearance(Vector3 position, Vector3 side)
        {
            for (var meters = 6f; meters >= 2f; meters -= 2f)
            {
                if (SkaliaBotUnityNavmesh.IsStraight(position, position + side * meters))
                {
                    return meters;
                }
            }
            return 0f;
        }

        private void EndBoulderDodge(float gameNow)
        {
            if (m_BoulderDodgePhase == 0)
            {
                return;
            }
            m_BoulderDodgePhase = 0;
            m_BoulderDodgeBoss = null;
            m_BoulderDodgeResultPending = true;
            m_BoulderDodgeResultAt = gameNow + 0.8f;
        }

        // The key among the eight that moves closest to a world direction
        // with the body turned to yaw (0x12 is W, high nibble 0/2 is A/D).
        private static byte AnalogToward(Vector3 direction, float yaw)
        {
            var relative = Mathf.DeltaAngle(yaw, DirectionToYaw(direction));
            switch (Mathf.RoundToInt(relative / 45f))
            {
                case 0: return 0x12;
                case 1: return 0x22;
                case 2: return 0x21;
                case 3: return 0x20;
                case -1: return 0x02;
                case -2: return 0x01;
                case -3: return 0x00;
                default: return 0x10;
            }
        }

        private BotBehaviorStatus TickBossHuntBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            var boss = m_BossHuntTarget;
            if (!m_BossHuntActive || boss == null)
            {
                return BotBehaviorStatus.Failure;
            }
            var distance = (boss.transform.position - position).GetHorizontalMagnitude();
            if (Tryhard)
            {
                return TickTryhardBossHunt(boss, position, distance, now);
            }
            // A zombie on the bot first, like with the burner.
            if (TryFindNearestNormalZombie(position, 6f, out var closeZombie))
            {
                if (m_TargetZombie != closeZombie && now >= m_NextBossHuntMeleeLogAt)
                {
                    m_NextBossHuntMeleeLogAt = now + 5f;
                    BotLog(LogLevel.Information,
                        "Zumbi comum a {Distance:0.#}m; resolvendo antes de atirar no Mega.",
                        (closeZombie.transform.position - position).GetHorizontalMagnitude());
                }
                ForceCombatTarget(closeZombie, now);
                return BotBehaviorStatus.Running;
            }
            if (distance < BossHuntKiteMeters || (m_BossHuntKiting && distance < BossHuntKiteReleaseMeters))
            {
                if (!m_BossHuntKiting)
                {
                    m_BossHuntKiting = true;
                    BotLog(LogLevel.Information,
                        "Mega a {Distance:0.#}m: recuando ate {Release:0}m antes de atirar de novo (vida {Health}).",
                        distance,
                        BossHuntKiteReleaseMeters,
                        m_Player.life.health);
                }
                if (now >= m_NextBossFleeReplanAt
                    && (m_ObjectiveType != ObjectiveType.Flee
                        || now >= m_ObjectiveExpiresAt
                        || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 4f))
                {
                    m_NextBossFleeReplanAt = now + 1f;
                    if (TryFindFireEscapePoint(position, boss, now, out var escape)
                        || TryFindLowHealthEscapePoint(position, now, out escape))
                    {
                        m_FleeingFromPlayerName = "o Mega (recuo da caca)";
                        SetObjective(ObjectiveType.Flee, escape, now + 6f);
                    }
                }
                return BotBehaviorStatus.Running;
            }
            m_BossHuntKiting = false;
            EquipBossHuntGun(now);
            ForceCombatTarget(boss, now);
            return BotBehaviorStatus.Running;
        }

        // 0.1.170: the combat keeps whatever loaded gun is in hand, which
        // could be a bolt rifle the hunt did not count on.
        private ItemGunAsset? m_BossHuntCandidateGun;
        private ItemGunAsset? m_BossHuntGun;
        private float m_NextBossHuntEquipAt;

        private void EquipBossHuntGun(float now)
        {
            var gun = m_BossHuntGun;
            var equipment = m_Player.equipment;
            if (gun == null
                || equipment.asset == gun
                || equipment.isBusy
                || m_TreatmentPhase != 0
                || now < m_NextBossHuntEquipAt)
            {
                return;
            }
            m_NextBossHuntEquipAt = now + 1f;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar == null || jar.GetAsset() != gun)
                    {
                        continue;
                    }
                    if (!ItemTool.checkUseable(page, jar.item.id))
                    {
                        TryMoveToWeaponSlot(page, jar, gun);
                        return;
                    }
                    equipment.ServerEquip(page, jar.x, jar.y);
                    BotLog(LogLevel.Information,
                        "Pegando {Gun} para cacar o Mega (era a arma da conta).",
                        gun.itemName);
                    return;
                }
            }
        }

        private float GetBossFleeUtility()
        {
            if (m_BossHuntActive)
            {
                return -1f;
            }
            var boss = m_CachedNearestBoss;
            if (boss == null || boss.isDead || !boss.gameObject.activeInHierarchy)
            {
                EndBossFlee("o chefe sumiu da vista");
                return -1f;
            }
            var distance = m_CachedNearestBossDistance;
            // 0.2.2x7 (doc 16.13): the common zombie on the bot first (thigas
            // walked from the Mega with no stamina until a burner killed him).
            if (IsFleeYielding(m_BehaviorNow) && distance >= MegaYieldMeters)
            {
                return -1f;
            }
            if (m_BossFleeActive)
            {
                // 0.2.2u: the tryhard stops running once the Mega is no
                // longer after it and is 20m away.
                if (Tryhard && !IsBossAfterBot(boss) && !IsMegaClosing(boss) && distance > TryhardMegaFleeMeters * 2f)
                {
                    EndBossFlee(DescribeBoss(boss) + " a " + distance.ToString("0") + "m e sem vir atras do bot");
                    return -1f;
                }
                if (distance > BossFleeReleaseMeters
                    || (distance > BossFleeMeters && !CanZombieSee(boss, m_BehaviorPosition)))
                {
                    EndBossFlee(DescribeBoss(boss) + " a " + distance.ToString("0") + "m");
                    return -1f;
                }
                return 975f;
            }
            // 0.2.2u: the tryhard only runs from a Mega that is after it or
            // within 10m (thigas ran 7 times in 2 min from one 35m away that
            // never saw him).
            return distance <= BossFleeMeters && (!Tryhard || IsTryhardBossFleeWanted(boss, distance))
                ? 975f
                : -1f;
        }

        private BotBehaviorStatus TickBossFleeBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            var boss = m_CachedNearestBoss;
            if (boss == null)
            {
                return BotBehaviorStatus.Failure;
            }
            if (!m_BossFleeActive)
            {
                m_BossFleeActive = true;
                BotLog(LogLevel.Information,
                    "{Boss} a {Distance:0.#}m: fugindo em vez de lutar (vida {Health}, arma {Weapon}).",
                    DescribeBoss(boss),
                    m_CachedNearestBossDistance,
                    m_Player.life.health,
                    DescribeEquipped());
            }
            // 0.2.2x11: a flight that lost its objective (route failed) is
            // planned again at once, not 1.5s later standing by the Mega.
            if ((m_ObjectiveType != ObjectiveType.Flee && now >= m_NextBossFleeReplanAt - 1.2f)
                || (now >= m_NextBossFleeReplanAt
                    && (now >= m_ObjectiveExpiresAt
                        || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 4f)))
            {
                m_NextBossFleeReplanAt = now + 1.5f;
                if (TryFindFireEscapePoint(position, boss, now, out var escape)
                    || TryFindLowHealthEscapePoint(position, now, out escape))
                {
                    m_FleeingFromPlayerName = DescribeBoss(boss);
                    SetObjective(ObjectiveType.Flee, escape, now + 8f);
                }
            }
            return BotBehaviorStatus.Running;
        }

        private static bool IsFireZombie(Zombie zombie)
        {
            return zombie.speciality == EZombieSpeciality.BURNER
                || zombie.speciality == EZombieSpeciality.BOSS_FIRE
                || zombie.speciality == EZombieSpeciality.BOSS_MAGMA
                || zombie.speciality == EZombieSpeciality.BOSS_ALL
                || zombie.speciality == EZombieSpeciality.BOSS_BUAK_FIRE
                || zombie.speciality == EZombieSpeciality.BOSS_BUAK_FINAL;
        }

        private void UpdateObjective(Vector3 position, float now)
        {
            var nearestZombieDistance = GetNearestLivingZombieDistance();
            var hasCombatEquipment = HasUsableCombatEquipment();
            var hasLoadedRangedWeapon = HasLoadedRangedWeapon();
            if (TryFindNearestFireZombie(
                    position,
                    FireZombieVisualRadiusMeters,
                    out var observedFireZombie))
            {
                m_RememberedFireZombie = observedFireZombie;
                m_FireZombieWeaponSearchExpiresAt = now + 120f;
            }
            if (m_RememberedFireZombie == null
                || m_RememberedFireZombie.isDead
                || !m_RememberedFireZombie.gameObject.activeInHierarchy
                || now >= m_FireZombieWeaponSearchExpiresAt)
            {
                m_RememberedFireZombie = null;
            }

            // Fire zombies cannot be engaged safely with fists/melee. Finish
            // ordinary nearby threats first, then acquire a loaded ranged weapon
            // from the ground before selecting the fire zombie as a target.
            if (!hasLoadedRangedWeapon
                && m_RememberedFireZombie != null
                && !TryFindNearestZombie(position, out _))
            {
                if (m_ObjectiveType == ObjectiveType.Loot
                    && m_LootTargetIsRangedWeapon)
                {
                    UpdateLootObjective(position, now);
                    return;
                }
                if (now >= m_NextLootScanTime
                    && TryFindNearestLoot(
                        position,
                        now,
                        true,
                        out var rangedRegionX,
                        out var rangedRegionY,
                        out var rangedItem,
                        true))
                {
                    m_NextLootScanTime = now + 1f;
                    SetLootObjective(rangedRegionX, rangedRegionY, rangedItem, now);
                    if (now >= m_NextFireZombieTacticalLogAt)
                    {
                        m_NextFireZombieTacticalLogAt = now + 5f;
                        BotLog(LogLevel.Information,
                            "Bot detectou zumbi de fogo sem arma adequada e esta buscando uma arma de alcance carregada.");
                    }
                    return;
                }
                if (now >= m_NextLootScanTime
                    && TryFindRememberedLoadedRangedLoot(
                        position,
                        now,
                        out var rememberedRegionX,
                        out var rememberedRegionY,
                        out var rememberedRangedItem))
                {
                    m_NextLootScanTime = now + 1f;
                    SetLootObjective(
                        rememberedRegionX,
                        rememberedRegionY,
                        rememberedRangedItem,
                        now);
                    BotLog(LogLevel.Information,
                        "Bot retornando a uma arma de alcance memorizada em {Position} para enfrentar zumbi de fogo.",
                        FormatPosition(rememberedRangedItem.point));
                    return;
                }

                var fireDistance = (m_RememberedFireZombie.transform.position - position)
                    .GetHorizontalMagnitude();
                if (fireDistance < FireZombieAvoidRadiusMeters)
                {
                    if (m_ObjectiveType != ObjectiveType.RepositionFire
                        || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 2f)
                    {
                        if (TryFindConnectedRetreatPoint(
                                position,
                                m_RememberedFireZombie.transform.position,
                                now,
                                out var safeSearchPoint))
                        {
                            SetObjective(
                                ObjectiveType.RepositionFire,
                                safeSearchPoint,
                                now + 8f);
                        }
                        else
                        {
                            // No connected graph destination: use a short local
                            // physical maneuver instead of requesting an invalid path.
                            var away = position - m_RememberedFireZombie.transform.position;
                            away.y = 0f;
                            if (away.sqrMagnitude < 0.01f)
                            {
                                away = Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f)
                                    * Vector3.forward;
                            }
                            SetObjective(
                                ObjectiveType.RepositionFire,
                                position + away.normalized * 5f,
                                now + 3f);
                            m_DirectFallbackUntil = now + 3f;
                        }
                    }
                    if (now >= m_NextFireZombieTacticalLogAt)
                    {
                        m_NextFireZombieTacticalLogAt = now + 5f;
                        BotLog(LogLevel.Information,
                            "Bot sem arma de alcance mantendo distancia do zumbi de fogo enquanto procura equipamento.");
                    }
                    return;
                }
            }

            // When unarmed, a nearby weapon is a tactical objective, but an
            // immediate zombie at melee distance still takes precedence.
            if (!hasCombatEquipment && nearestZombieDistance > 6f)
            {
                if (m_ObjectiveType == ObjectiveType.Loot
                    && m_LootTargetIsCombatEquipment)
                {
                    UpdateLootObjective(position, now);
                    return;
                }
                if (now >= m_NextLootScanTime
                    && TryFindNearestLoot(
                        position,
                        now,
                        true,
                        out var weaponRegionX,
                        out var weaponRegionY,
                        out var weaponItem))
                {
                    m_NextLootScanTime = now + 1f;
                    SetLootObjective(weaponRegionX, weaponRegionY, weaponItem, now);
                    return;
                }
            }

            UpdateCombatObjective(position, now);
            if (m_ObjectiveType == ObjectiveType.Combat)
            {
                return;
            }

            if (m_ObjectiveType == ObjectiveType.Loot)
            {
                // Loot comum somente depois que a area imediata estiver limpa.
                if (!m_LootTargetIsCombatEquipment
                    && nearestZombieDistance <= GetZombieEngagementRadius())
                {
                    ClearObjective();
                }
                else
                {
                    UpdateLootObjective(position, now);
                }
            }
            else if (m_ObjectiveType == ObjectiveType.Explore
                     && (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 10f)
            {
                ChooseAreaPatrolObjective(position, now);
            }
            else if (m_ObjectiveType == ObjectiveType.Patrol
                     && ((m_ObjectivePosition - position).GetHorizontalMagnitude() <= 5f
                         || now >= m_ObjectiveExpiresAt))
            {
                ChooseAreaPatrolObjective(position, now);
            }

            if (m_ObjectiveType != ObjectiveType.None && now >= m_ObjectiveExpiresAt)
            {
                AbandonCurrentObjective(now);
            }

            if (now >= m_NextLootScanTime
                && nearestZombieDistance > GetZombieEngagementRadius())
            {
                m_NextLootScanTime = now + 2f;
                if (TryFindNearestLoot(
                    position,
                    now,
                    false,
                    out var regionX,
                    out var regionY,
                    out var item))
                {
                    if (m_ObjectiveType != ObjectiveType.Loot
                        || m_LootInstanceId != item.instanceID)
                    {
                        SetLootObjective(regionX, regionY, item, now);
                    }
                }
            }

            if (m_ObjectiveType == ObjectiveType.None)
            {
                if (now < m_NextExplorationSelectionTime)
                {
                    return;
                }

                if (m_ForceLocalExplorationOnNextSelection)
                {
                    m_ForceLocalExplorationOnNextSelection = false;
                    ChooseLocalExplorationObjective(
                        position,
                        now,
                        "a ultima solicitacao de rota falhou");
                }
                else if (m_HasInterestArea && now < m_InterestAreaExpiresAt)
                {
                    ChooseAreaPatrolObjective(position, now);
                }
                else
                {
                    ChooseExplorationObjective(position, now);
                }
            }
        }

        private void UpdateLootObjective(Vector3 position, float now)
        {
            RefreshLootClaim(now);
            if (!TryGetTargetLoot(out var loot))
            {
                m_LootMemories.RemoveAll(
                    memory => memory.InstanceId == m_LootInstanceId);
                ClearObjective();
                return;
            }

            var lootAsset = Assets.find(EAssetType.ITEM, loot.item.id) as ItemAsset;
            var allowRangedBeforeMelee = m_LootTargetIsRangedWeapon
                && m_RememberedFireZombie != null
                && !m_RememberedFireZombie.isDead;
            if (lootAsset == null
                || !ShouldCollectLootAsset(lootAsset, allowRangedBeforeMelee, loot.item.state, loot.item.amount, loot.item.quality))
            {
                BotLog(LogLevel.Information,
                    "Bot abandonou loot {LootInstanceId}: papel de equipamento ja preenchido.",
                    m_LootInstanceId);
                ClearObjective();
                m_NextLootScanTime = now + 1f;
                return;
            }

            m_ObjectivePosition = loot.point;
            var distance = (loot.point - position).GetHorizontalMagnitude();
            if (TryGiveUpLootPastRouteEnd(position, now, loot.point, distance, lootAsset.itemName))
            {
                return;
            }
            var resumedLater = now - m_LootProgressLastSeenAt > 3f;
            m_LootProgressLastSeenAt = now;
            if (m_LootProgressId != m_LootInstanceId
                || resumedLater
                || distance < m_LootProgressBestDistance - 1f)
            {
                m_LootProgressId = m_LootInstanceId;
                m_LootProgressBestDistance = distance;
                m_LootProgressSince = now;
                m_LootProgressOrigin = position;
            }
            else if (now - m_LootProgressSince >= GetLootProgressTimeout(position)
                     && TryUseLinkTowardPoint(position, now, loot.point, "item no alto sem progresso"))
            {
                m_LootProgressSince = now;
                m_LootProgressOrigin = position;
                return;
            }
            else if (now - m_LootProgressSince >= GetLootProgressTimeout(position)
                     && TryGiveLootSecondChance(lootAsset, position, now, distance))
            {
                return;
            }
            else if (now - m_LootProgressSince >= GetLootProgressTimeout(position))
            {
                // Not one meter closer in 15s (0.2.2t: 6s when the bot is
                // not covering ground either): the item sits somewhere the
                // bot can't walk to (behind a wall, on a roof, a locked room).
                var ignoreSeconds = GetUnreachableLootIgnoreSeconds(lootAsset);
                IgnoreLoot(m_LootInstanceId, now + ignoreSeconds);
                BotLog(LogLevel.Information,
                    "Loot {Item} sem progresso por {Seconds:0}s a {Distance:0.#}m; ignorado por {Ignore:0} min.",
                    lootAsset.itemName,
                    now - m_LootProgressSince,
                    distance,
                    ignoreSeconds / 60f);
                ClearObjective();
                m_NextLootScanTime = now + 0.75f;
                return;
            }
            if (TryGiveUpLootBehindFurniture(position, now, loot.point, distance, lootAsset.itemName))
            {
                return;
            }
            // The kitchen circles of the 0.1.100 log: an item on a counter at
            // 2-3m, the bot stepping in and out of reach around the counter,
            // and every step out restarted the clock, so it neither picked the
            // item up nor gave up until the 15s timeout. Keep the clock until
            // the bot is 1.5m past reach.
            var inReach = distance <= m_LootPickupDistanceMeters
                || IsLootWithinSightReach(loot.point, position);
            if (!inReach
                && (m_LootWithinReachSince <= 0f
                    || distance > Mathf.Max(m_LootPickupDistanceMeters, LootSightReachMeters) + 1.5f))
            {
                m_LootWithinReachSince = 0f;
                return;
            }

            if (!HasLootLineOfSight(loot.point))
            {
                if (m_LootWithinReachSince <= 0f)
                {
                    m_LootWithinReachSince = now;
                }
                else if (now - m_LootWithinReachSince >= 3f
                         && TryUseLinkTowardPoint(position, now, loot.point, "item no alto sem visao"))
                {
                    m_LootWithinReachSince = 0f;
                }
                else if (now - m_LootWithinReachSince >= 3f)
                {
                    IgnoreLoot(m_LootInstanceId, now + UnreachableLootIgnoreSeconds);
                    BotLog(LogLevel.Information,
                        "Bot abandonou loot {LootInstanceId}: sem linha visual mesmo estando proximo; ignorado por 10 min.",
                        m_LootInstanceId);
                    ClearObjective();
                    m_NextLootScanTime = now + 0.75f;
                }
                return;
            }

            if (!inReach)
            {
                return;
            }
            if (m_LootWithinReachSince <= 0f)
            {
                m_LootWithinReachSince = now;
                return;
            }

            // 0.1.170: stopped over it (or as close as the counter lets it),
            // look at it for half a second to a second, then take it. Still
            // walking after 4s in reach means something keeps it moving:
            // take it anyway, as before.
            if (m_LootSettledId != m_LootInstanceId)
            {
                if (now - m_LootWithinReachSince >= (Tryhard ? 1.5f : 4f) || IsLootHurried())
                {
                    TryCollectTargetLoot(now);
                }
                return;
            }
            if (IsLookingAtPoint(loot.point + Vector3.up * 0.15f, 12f))
            {
                if (m_LootLookSince <= 0f)
                {
                    m_LootLookSince = now;
                }
            }
            // 0.2.2w (doc 14.3, item 7): the tryhard glances and takes it; it
            // stood up to 2.3s looking at a wall when the item was not in
            // sight from where it stopped.
            var lookSeconds = Tryhard ? 0.25f : m_LootLookSeconds;
            if (IsLootHurried()
                || (m_LootLookSince > 0f && now - m_LootLookSince >= lookSeconds)
                || now - m_LootSettledAt >= lookSeconds + (Tryhard ? 0.4f : 1.5f))
            {
                TryCollectTargetLoot(now);
            }
        }

        private void TrackLootApproach(float distance, float now)
        {
            if (m_LootApproachId != m_LootInstanceId)
            {
                m_LootApproachId = m_LootInstanceId;
                m_LootApproachBest = distance;
                m_LootApproachImprovedAt = now;
                m_LootCloseMeters = Random.Range(0.6f, 1.2f);
                m_LootLookSince = 0f;
                m_LootLookSeconds = Random.Range(0.5f, 1.1f);
                m_LootApproachSeenAt = now;
                return;
            }
            // 0.1.172: back to the same item after a fight, a door or a
            // bandage, the time away does not count as standing still.
            if (now - m_LootApproachSeenAt > 1f)
            {
                m_LootApproachBest = distance;
                m_LootApproachImprovedAt = now;
            }
            m_LootApproachSeenAt = now;
            if (distance < m_LootApproachBest - 0.2f)
            {
                m_LootApproachBest = distance;
                m_LootApproachImprovedAt = now;
            }
        }

        // Done walking to the item: over it, or in reach and sight with no
        // way closer (a counter, table or shelf right at the knees, the route
        // turning away around it, or no progress for a second). Once
        // settled it stays settled unless pushed well out of reach.
        private bool UpdateLootSettled(Vector3 position, Vector3 navigationTarget, float now)
        {
            var toItem = m_ObjectivePosition - position;
            var dy = toItem.y;
            toItem.y = 0f;
            var distance = toItem.magnitude;
            if (m_LootSettledId == m_LootInstanceId)
            {
                // Only while it can still take the item from here: back to
                // the same item after a fight, it walks to it again.
                if ((distance <= m_LootCloseMeters + 0.5f && Mathf.Abs(dy) <= 2f)
                    || IsLootInReachAndSight(position))
                {
                    return true;
                }
                m_LootSettledId = 0;
                m_LootLookSince = 0f;
            }
            TrackLootApproach(distance, now);
            var settled = distance <= m_LootCloseMeters && Mathf.Abs(dy) <= 2f;
            if (!settled && IsLootInReachAndSight(position))
            {
                var toNavigation = navigationTarget - position;
                toNavigation.y = 0f;
                settled = now - m_LootApproachImprovedAt >= LootApproachStallSeconds
                    || m_WallMovementBlocked
                    || (toNavigation.sqrMagnitude > 0.04f
                        && Vector3.Angle(toNavigation, toItem) > 75f)
                    || (Physics.Raycast(
                            position + Vector3.up * 0.45f,
                            toItem / distance,
                            out var kneeHit,
                            Mathf.Max(0.1f, distance - 0.45f),
                            RayMasks.BLOCK_COLLISION,
                            QueryTriggerInteraction.Ignore)
                        // Up to the table or counter, not stopping 3m short
                        // of it the moment the item comes in sight.
                        && kneeHit.distance <= 0.9f);
            }
            if (settled)
            {
                m_LootSettledId = m_LootInstanceId;
                m_LootSettledAt = now;
                m_LootLookSince = 0f;
            }
            return settled;
        }

        // The 0.1.113 test: Tadeu and thigas went back and forth for minutes
        // by a shop at (-890, -722). The route to the bread on the counter
        // ended 6m short, outside the fence; at the end the bot turned to the
        // item, met the fence, detoured, asked for a route, got the same one.
        // 2.5s at the end of a route that stops past reach is enough to know.
        private bool TryGiveUpLootPastRouteEnd(
            Vector3 position,
            float now,
            Vector3 lootPoint,
            float distance,
            string itemName)
        {
            if (m_LastPathEndLootId != m_LootInstanceId
                || distance <= m_LootPickupDistanceMeters
                || IsLootWithinSightReach(lootPoint, position))
            {
                m_LootRouteEndSince = 0f;
                return false;
            }
            var endGap = (lootPoint - m_LastPathEnd).GetHorizontalMagnitude();
            var fromEnd = (m_LastPathEnd - position).GetHorizontalMagnitude();
            if (endGap <= m_LootPickupDistanceMeters + 0.5f || fromEnd > 5f)
            {
                m_LootRouteEndSince = 0f;
                return false;
            }
            if (fromEnd > 3f && m_LootRouteEndSince <= 0f)
            {
                return false;
            }
            if (m_LootRouteEndSince <= 0f)
            {
                m_LootRouteEndSince = now;
                return false;
            }
            if (now - m_LootRouteEndSince < 2.5f)
            {
                return false;
            }
            m_LootRouteEndSince = 0f;
            if (TryUseLinkTowardPoint(position, now, lootPoint, "rota termina longe do item"))
            {
                m_LastPathEndLootId = 0;
                return true;
            }
            IgnoreLoot(m_LootInstanceId, now + UnreachableLootIgnoreSeconds);
            BotLog(LogLevel.Information,
                "Rota para {Item} termina a {Gap:0.#}m dele em {End} (atras de cerca ou balcao); ignorado por 10 min em vez de ir e voltar.",
                itemName,
                endGap,
                FormatPosition(m_LastPathEnd));
            ClearObjective();
            m_NextLootScanTime = now + 0.75f;
            return true;
        }

        private float GetNearestLivingZombieDistance()
        {
            return m_CachedNearestZombieDistance;
        }

        private float GetZombieEngagementRadius()
        {
            return Mathf.Max(
                m_ZombieDetectionRadiusMeters,
                VisualZombieDetectionRadiusMeters);
        }

        private bool HasUsableCombatEquipment()
        {
            if (m_Player.equipment.equippedPage < PlayerInventory.SLOTS
                && ((m_Player.equipment.asset is ItemMeleeAsset equippedMelee && IsUsefulMelee(equippedMelee))
                    || (m_Player.equipment.asset is ItemGunAsset equippedGun
                        && IsUsefulGun(equippedGun)
                        && IsEquippedGunLoaded(equippedGun))))
            {
                return true;
            }
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                for (byte index = 0;
                     index < m_Player.inventory.getItemCount(page);
                     index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if ((jar?.GetAsset() is ItemMeleeAsset carriedMelee && IsUsefulMelee(carriedMelee))
                        || (jar?.GetAsset() is ItemGunAsset gun
                            && IsUsefulGun(gun)
                            && IsLoadedGun(gun, jar.item.state)))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private bool IsLookingAtPoint(Vector3 point, float toleranceDegrees)
        {
            var direction = point - m_Player.look.aim.position;
            var horizontal = new Vector3(direction.x, 0f, direction.z);
            if (horizontal.sqrMagnitude < 0.001f)
            {
                return true;
            }
            var targetYaw = DirectionToYaw(horizontal);
            var horizontalDistance = new Vector2(direction.x, direction.z).magnitude;
            var targetPitch = 90f
                - Mathf.Atan2(direction.y, Mathf.Max(0.01f, horizontalDistance))
                * Mathf.Rad2Deg;
            return Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, targetYaw)) <= toleranceDegrees
                && Mathf.Abs(Mathf.DeltaAngle(m_CurrentPitch, targetPitch)) <= toleranceDegrees;
        }

        private void UpdateCombatObjective(Vector3 position, float now)
        {
            if (m_TargetZombie != null && IsZombieMarkedUnreachable(m_TargetZombie, now))
            {
                m_TargetZombie = null;
            }
            if (IsTargetZombieAlive()
                && !IsFireZombie(m_TargetZombie!)
                && !HasLoadedRangedWeapon()
                && TryFindNearestFireZombie(position, FireDangerBotMeters, out var targetFire)
                && IsBaitNearFireZombie(m_TargetZombie!, targetFire, position))
            {
                if (now >= m_NextFireBaitLogAt)
                {
                    m_NextFireBaitLogAt = now + 5f;
                    BotLog(LogLevel.Information,
                        "Zumbi comum a {Distance:0.#}m esta a {FireDistance:0.#}m do zumbi de fogo; deixando de atacar para nao chegar perto dele.",
                        (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude(),
                        (m_TargetZombie!.transform.position - targetFire.transform.position).GetHorizontalMagnitude());
                }
                m_TargetZombie = null;
                if (m_ObjectiveType == ObjectiveType.Combat)
                {
                    ClearObjective();
                }
            }
            DropUnsafeStealthTarget(position, now);
            // 0.1.173: after an escape the bot does not turn back into what
            // it ran from, and a zombie inside a group of 4+ is left alone
            // (except from 12m with a gun, or at arm's length).
            if (IsTargetZombieAlive()
                && m_ObjectiveType != ObjectiveType.EscapeSwarm
                && !IsCombatTargetAllowed(m_TargetZombie!, position, now, out var declinedWhy))
            {
                LogCombatDeclined(m_TargetZombie!, position, now, declinedWhy);
                m_TargetZombie = null;
                if (m_ObjectiveType == ObjectiveType.Combat)
                {
                    ClearObjective();
                }
            }
            if (IsTargetZombieAlive()
                && (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude()
                    > GetCautionEngagementRadius(m_TargetZombie))
            {
                m_TargetZombie = null;
            }
            // 0.2.2w (doc 14.3, item 3): a zombie the bot already shot or
            // hit is finished, not left after one shot with the back turned
            // (13 "Largando zumbi" in the 0.2.2v test); it is let go only
            // past 30m.
            var committed = Tryhard
                && IsTargetZombieAlive()
                && m_CommittedZombie == m_TargetZombie
                && (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude() <= TryhardCommitMeters;
            if (IsTargetZombieAlive()
                && !committed
                && !IsHordeCaution()
                && !IsHuntedBoss(m_TargetZombie!)
                && !(IsFireZombie(m_TargetZombie!) && HasLoadedRangedWeapon())
                && !IsZombieWorthEngaging(m_TargetZombie!, position, GetEngageRadius(), true))
            {
                var offset = m_TargetZombie!.transform.position - position;
                BotLog(LogLevel.Information,
                    "Largando zumbi a {Distance:0.#}m (altura {Dy:0.#}m): {Why}; voltando ao que fazia.",
                    offset.GetHorizontalMagnitude(),
                    offset.y,
                    m_TargetZombie!.isHunting && m_TargetZombie.player == m_Player
                        ? "zumbi comum seguindo o bot no caminho, fica para tras na corrida"
                        : "nao vem atras do bot e nao esta no caminho");
                m_TargetZombie = null;
            }
            if (IsTargetZombieAlive())
            {
                var offset = m_TargetZombie!.transform.position - position;
                var maximumPursuitDistance = Mathf.Max(
                    m_ZombieDetectionRadiusMeters * 1.5f,
                    VisualZombieDetectionRadiusMeters);
                if (offset.x * offset.x + offset.z * offset.z
                    <= maximumPursuitDistance * maximumPursuitDistance)
                {
                    SetObjective(
                        ObjectiveType.Combat,
                        GetCombatDestination(position, m_TargetZombie),
                        float.PositiveInfinity);
                }
                else
                {
                    ClearObjective();
                }
            }
            else if (m_ObjectiveType == ObjectiveType.Combat)
            {
                ClearObjective();
            }

            if (now < m_NextZombieScanTime)
            {
                return;
            }

            m_NextZombieScanTime = now + 0.4f;
            Zombie zombie;
            var foundZombie = IsHordeCaution()
                ? TryPickStealthTarget(position, out zombie)
                : TryFindNearestZombie(position, out zombie, true);
            if (foundZombie
                && zombie != m_TargetZombie
                && m_ObjectiveType != ObjectiveType.EscapeSwarm
                && !IsCombatTargetAllowed(zombie, position, now, out var scanDeclinedWhy))
            {
                LogCombatDeclined(zombie, position, now, scanDeclinedWhy);
                foundZombie = false;
            }
            if (foundZombie
                && (zombie.transform.position - position).GetHorizontalMagnitude()
                    <= GetCautionEngagementRadius(zombie))
            {
                var changedTarget = m_TargetZombie != zombie;
                m_TargetZombie = zombie;
                if (changedTarget && IsHordeCaution() && !zombie.isHunting)
                {
                    BotLog(LogLevel.Information,
                        "Cautela: indo agachado ate zumbi distraido a {Distance:0.#}m para atacar pelas costas.",
                        (zombie.transform.position - position).GetHorizontalMagnitude());
                }
                if (changedTarget)
                {
                    m_StatWindowFights++;
                    if ((zombie.transform.position - position).GetHorizontalMagnitude() >= 20f)
                    {
                        m_StatWindowFarFights++;
                    }
                    m_CombatMovementPhase = CombatMovementPhase.Approach;
                    m_CombatRetreatEndsAt = 0f;
                    m_CombatRetreatPending = false;
                    m_CombatAttackRecoveryUntil = 0f;
                    m_CombatAttackFailsafeAt = 0f;
                    m_MeleeBurstAttackCount = 0;
                    m_MeleeBurstTargetCount = Random.Range(1, 3);
                    m_CombatRetreatShouldSprint = false;
                }
                SetObjective(
                    ObjectiveType.Combat,
                    GetCombatDestination(position, zombie),
                    float.PositiveInfinity);
                m_ConsecutiveStuckChecks = 0;
            }
        }

        private void UpdateCombatMovementPhase(
            float distance,
            float attackDistance,
            float now)
        {
            NoteFootworkHealth(now);
            if ((m_ObjectiveType != ObjectiveType.Combat
                 && m_ObjectiveType != ObjectiveType.EscapeSwarm)
                || !IsTargetZombieAlive())
            {
                m_CombatMovementPhase = CombatMovementPhase.Approach;
                m_CombatRetreatEndsAt = 0f;
                m_CombatRetreatPending = false;
                m_CombatAttackRecoveryUntil = 0f;
                m_CombatAttackFailsafeAt = 0f;
                return;
            }
            // 0.2.2x14: the blade hits the one about to swing; a swap or a
            // reload with a zombie close is done stepping back.
            TryRetargetStunKite(attackDistance, now);
            if (TryRetreatWhileSwapping(distance, attackDistance, now))
            {
                return;
            }

            // Contra zumbi de fogo, arma de alcance usa uma faixa segura: recua
            // se ele se aproximar demais e volta a disparar da borda da faixa.
            if (m_Player.equipment.asset is ItemGunAsset)
            {
                if (IsFireZombie(m_TargetZombie!))
                {
                    const float fireZombieMinimumDistance = 11f;
                    const float fireZombiePreferredDistance = 15f;
                    if (m_CombatMovementPhase == CombatMovementPhase.Approach
                        && distance < fireZombieMinimumDistance)
                    {
                        m_CombatMovementPhase = CombatMovementPhase.Retreat;
                        m_CombatRetreatEndsAt = now + 8f;
                        BotLog(LogLevel.Debug,
                            "Bot recuando do zumbi de fogo para recuperar distancia de tiro; distancia {Distance:0.##}m.",
                            distance);
                    }
                    else if (m_CombatMovementPhase == CombatMovementPhase.Retreat
                             && (distance >= fireZombiePreferredDistance
                                 || now >= m_CombatRetreatEndsAt))
                    {
                        m_CombatMovementPhase = CombatMovementPhase.Approach;
                        m_CombatRetreatEndsAt = 0f;
                    }
                    m_CombatRetreatPending = false;
                    return;
                }

                m_CombatMovementPhase = CombatMovementPhase.Approach;
                m_CombatRetreatEndsAt = 0f;
                m_CombatRetreatPending = false;
                return;
            }

            if (m_Player.equipment.asset is ItemMeleeAsset repeatedMelee
                && repeatedMelee.isRepeated)
            {
                // Motosserra e outros melee repetidos precisam permanecer
                // pressionados; não interrompa o ciclo para iniciar kite.
                if (m_CombatMovementPhase == CombatMovementPhase.Approach
                    && distance <= attackDistance)
                {
                    m_CombatMovementPhase = CombatMovementPhase.Retreat;
                    m_CombatRetreatEndsAt = now + 2f;
                }
                else if (m_CombatMovementPhase == CombatMovementPhase.Retreat
                         && (distance >= 3.75f || now >= m_CombatRetreatEndsAt))
                {
                    m_CombatMovementPhase = CombatMovementPhase.Approach;
                    m_CombatRetreatEndsAt = 0f;
                }
                m_CombatRetreatPending = false;
                return;
            }

            if (m_CombatRetreatPending
                && m_Player.equipment.isBusy
                && now >= m_CombatAttackFailsafeAt)
            {
                BotLog(LogLevel.Warning,
                    "Acao melee permaneceu ocupada alem do tempo esperado; reequipando antes de continuar o combate.");
                m_Player.equipment.dequip();
                m_CombatRetreatPending = false;
                m_CombatAttackRecoveryUntil = 0f;
                m_CombatAttackFailsafeAt = 0f;
                m_NextWeaponSelectionAt = 0f;
                m_NextAttackTime = now + 0.25f;
                return;
            }

            if (m_CombatMovementPhase == CombatMovementPhase.Approach
                || m_CombatMovementPhase == CombatMovementPhase.Attack)
            {
                // 0.2.2x13: the tryhard stands and swings again (the zombie
                // is stunned), stepping back only for a reason.
                if (TryTryhardMeleePhase(distance, attackDistance, now))
                {
                    return;
                }
                if (m_CombatRetreatPending
                    && now >= m_CombatAttackRecoveryUntil
                    && (!m_Player.equipment.isBusy
                        || m_TargetZombie!.speciality == EZombieSpeciality.CRAWLER)
                    && now >= m_CombatRetreatBlockedUntil)
                {
                    m_CombatMovementPhase = CombatMovementPhase.Retreat;
                    m_CombatRetreatEndsAt = now + CombatRetreatDurationSeconds;
                    m_CombatRetreatPending = false;
                    m_CombatRetreatShouldSprint = m_CachedNearbyZombieCount >= 2
                        || m_TargetZombie!.speciality == EZombieSpeciality.CRAWLER
                        || Random.value < 0.35f;
                    BotLog(LogLevel.Debug,
                        "Bot iniciou kite do zumbi: recuando enquanto ataca; distancia {Distance:0.##}m.",
                        distance);
                }
                return;
            }

            if (distance >= CombatRetreatDistanceMeters || now >= m_CombatRetreatEndsAt)
            {
                m_CombatMovementPhase = CombatMovementPhase.Approach;
                m_CombatRetreatEndsAt = 0f;
                m_MeleeBurstAttackCount = 0;
                m_MeleeBurstTargetCount = Random.Range(1, 3);
                m_CombatRetreatShouldSprint = false;
                BotLog(LogLevel.Debug,
                    "Bot concluiu recuo do kite; retomando aproximacao a {Distance:0.##}m.",
                    distance);
            }
        }

        private float GetCombatAttackDistance()
        {
            if (IsHuntedBoss(m_TargetZombie)
                && m_Player.equipment.asset is ItemGunAsset bossGun
                && IsEquippedGunLoaded(bossGun))
            {
                return Mathf.Clamp(bossGun.range * 0.6f, BossHuntKiteMeters, BossHuntShootMeters);
            }
            if (m_Player.equipment.asset is ItemGunAsset gun
                && IsEquippedGunLoaded(gun))
            {
                // 0.2.2x (doc 15.2, item 1): in sight, the tryhard shoots
                // from where it is, up to 3/4 of the gun's reach.
                if (TryGetTryhardGunAttackDistance(gun, out var tryhardMeters))
                {
                    return tryhardMeters;
                }
                return Mathf.Clamp(gun.range * 0.45f, 7f, 15f);
            }
            if (m_Player.equipment.asset is ItemMeleeAsset melee)
            {
                return Mathf.Max(
                    m_ZombieAttackDistanceMeters,
                    Mathf.Min(melee.range * 0.9f, 2.5f));
            }
            return m_ZombieAttackDistanceMeters;
        }

        // Both deaths came from chasing a common zombie 10-15m away that walked
        // next to the burner: the bot ran into the fire, fled, came back and
        // took 55 damage in one second. Without a loaded ranged weapon those
        // zombies are left alone unless they are already within reach.
        private static bool IsBaitNearFireZombie(Zombie candidate, Zombie fire, Vector3 position)
        {
            return (candidate.transform.position - position).GetHorizontalMagnitude() > CaughtByZombieMeters
                && (candidate.transform.position - fire.transform.position).GetHorizontalMagnitude()
                    <= FireDangerZombieMeters;
        }

        private float GetEngageRadius()
        {
            return HasLoadedRangedWeapon() && !IsMeleeForCommonActive() ? RangedEngageMeters : MeleeEngageMeters;
        }

        // 0.2.1: with a melee weapon for the common zombies, a zombie not
        // coming is only gone after within melee reach (12m), as with no gun:
        // the players fight only 11-13% of the time a zombie follows them.
        private bool IsMeleeForCommonActive()
        {
            return s_Settings.MeleeForCommon && HasMeleeWeapon();
        }

        private static bool IsTaskObjective(ObjectiveType type)
        {
            return type == ObjectiveType.Patrol
                || type == ObjectiveType.Explore
                || type == ObjectiveType.Loot
                || type == ObjectiveType.Travel;
        }

        // In front of the bot, at most 6m off the straight line to the loot
        // point or item it is walking to, or was until a fight took over.
        private bool IsOnTaskPath(Vector3 point, Vector3 position)
        {
            Vector3 task;
            if (IsTaskObjective(m_ObjectiveType))
            {
                task = m_ObjectivePosition;
            }
            else if (Time.realtimeSinceStartup - m_LastTaskAt <= 20f)
            {
                task = m_LastTaskPosition;
            }
            else
            {
                return false;
            }
            var toTask = task - position;
            toTask.y = 0f;
            var taskDistance = toTask.magnitude;
            if (taskDistance < 0.5f)
            {
                return false;
            }
            var direction = toTask / taskDistance;
            var toPoint = point - position;
            toPoint.y = 0f;
            var along = Vector3.Dot(toPoint, direction);
            if (along < 0f
                || along > Mathf.Min(taskDistance + PathEngageWidthMeters, PathEngageAheadMeters))
            {
                return false;
            }
            return (toPoint - direction * along).magnitude <= PathEngageWidthMeters;
        }

        private bool IsZombieWorthEngaging(Zombie zombie, Vector3 position, float closeRadius, bool isTarget)
        {
            // 0.2.2t: the lone zombie standing over the loot is killed.
            if (IsLootGuardZombie(zombie))
            {
                return true;
            }
            if (zombie.isHunting && zombie.player == m_Player)
            {
                // 0.2.2: on the way, a common one is outrun (SkaliaBotTactics).
                return !ShouldLeaveHunterBehind(zombie, position);
            }
            var offset = zombie.transform.position - position;
            var horizontal = new Vector2(offset.x, offset.z).magnitude;
            // 0.1.0-y17.5: in the minute after news of a living enemy, one
            // not after the bot is left alone (SkaliaBotPvpMemoryY).
            if (!zombie.isMega && IsAvoidingZombiesForPvp(zombie, horizontal))
            {
                return false;
            }
            // Up or down the stairs after one that is not coming.
            if (Mathf.Abs(offset.y) > 2.5f)
            {
                return false;
            }
            // Where a bot already got stuck, only one right next to it.
            if (IsNearOrbitBadSpot(zombie.transform.position, Time.realtimeSinceStartup, 4f))
            {
                return horizontal <= 4f;
            }
            if (horizontal <= closeRadius || (isTarget && horizontal <= KeepTargetMeters))
            {
                return true;
            }
            // 0.2.1: a zombie whose drop gives the gun or ammo the bot lacks.
            if (IsGoalZombie(zombie, horizontal))
            {
                return true;
            }
            return IsOnTaskPath(zombie.transform.position, position);
        }

        private bool TryFindNearestZombie(Vector3 position, out Zombie zombie, bool requireWorth = false)
        {
            zombie = null!;
            if (m_PerceivedZombies.Count == 0)
            {
                return false;
            }

            var searchRadius = Mathf.Max(
                m_ZombieDetectionRadiusMeters,
                VisualZombieDetectionRadiusMeters);
            var searchRadiusSquared = searchRadius * searchRadius;
            var bestDistanceSquared = searchRadiusSquared;
            var canFightFireZombie = HasLoadedRangedWeapon();
            // Under a full moon with three or more around, a zombie 40m away
            // is not worth crossing the group for.
            var crowded = false;
            if (LightingManager.isFullMoon)
            {
                var close = 0;
                foreach (var perceived in m_PerceivedZombies)
                {
                    var near = perceived.Key;
                    if (near != null
                        && !near.isDead
                        && near.gameObject.activeInHierarchy
                        && (near.transform.position - position).GetHorizontalMagnitude() <= FullMoonCrowdMeters)
                    {
                        close++;
                    }
                }
                crowded = close >= 3;
            }
            Zombie? dangerFire = null;
            if (!canFightFireZombie
                && TryFindNearestFireZombie(position, FireDangerBotMeters, out var nearbyFire))
            {
                dangerFire = nearbyFire;
            }
            var closeRadius = canFightFireZombie && !IsMeleeForCommonActive() ? RangedEngageMeters : MeleeEngageMeters;
            Zombie? skipped = null;
            var skippedDistanceSquared = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                if (candidate == null
                    || candidate.isDead
                    || !candidate.gameObject.activeInHierarchy
                    || (IsFireZombie(candidate)
                        && !(canFightFireZombie && IsFireShootable(candidate, position))
                        && !CanMeleeFireZombie(candidate))
                    || (dangerFire != null
                        && !IsFireZombie(candidate)
                        && IsBaitNearFireZombie(candidate, dangerFire, position))
                    || IsInRememberedIsland(candidate.transform.position, Time.realtimeSinceStartup)
                    || IsBossZombie(candidate)
                    || IsNearKnownBoss(candidate.transform.position)
                    || (candidate == m_IgnoredZombie
                        && Time.realtimeSinceStartup < m_IgnoreZombieUntil)
                    || IsZombieMarkedUnreachable(candidate, Time.realtimeSinceStartup))
                {
                    continue;
                }
                var offset = candidate.transform.position - position;
                var distanceSquared = offset.x * offset.x + offset.z * offset.z;
                if (distanceSquared >= bestDistanceSquared
                    || (crowded
                        && distanceSquared > FullMoonCrowdMeters * FullMoonCrowdMeters
                        && !(candidate.isHunting && candidate.player == m_Player)))
                {
                    continue;
                }
                // A burner is still worth a gun from afar (the tester: "ele nao
                // tentou matar o zumbi de fogo uma unica vez?").
                if (requireWorth
                    && !(canFightFireZombie && IsFireZombie(candidate))
                    && !IsZombieWorthEngaging(candidate, position, closeRadius, candidate == m_TargetZombie))
                {
                    m_StatSkippedZombies.Add(candidate);
                    if (distanceSquared < skippedDistanceSquared)
                    {
                        skippedDistanceSquared = distanceSquared;
                        skipped = candidate;
                    }
                    continue;
                }
                bestDistanceSquared = distanceSquared;
                zombie = candidate;
            }

            var now = Time.realtimeSinceStartup;
            if (skipped != null
                && skippedDistanceSquared < bestDistanceSquared
                && now >= m_NextSkipZombieLogAt)
            {
                m_NextSkipZombieLogAt = now + 20f;
                var offset = skipped.transform.position - position;
                BotLog(LogLevel.Information,
                    "Deixando em paz zumbi a {Distance:0.#}m (altura {Dy:0.#}m): nao esta atras do bot, nem a {Radius:0}m, nem no caminho.",
                    Mathf.Sqrt(skippedDistanceSquared),
                    offset.y,
                    closeRadius);
            }
            return zombie != null;
        }

        private bool TryFindNearestFireZombie(
            Vector3 position,
            float radius,
            out Zombie zombie)
        {
            zombie = null!;
            if (m_PerceivedZombies.Count == 0)
            {
                return false;
            }

            var bestDistanceSquared = radius * radius;
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                if (candidate == null
                    || candidate.isDead
                    || !candidate.gameObject.activeInHierarchy
                    || !IsFireZombie(candidate)
                    || IsZombieMarkedUnreachable(candidate, Time.realtimeSinceStartup))
                {
                    continue;
                }
                var offset = candidate.transform.position - position;
                if (Mathf.Abs(offset.y) > 12f)
                {
                    continue;
                }
                var distanceSquared = offset.x * offset.x + offset.z * offset.z;
                if (distanceSquared >= bestDistanceSquared)
                {
                    continue;
                }
                bestDistanceSquared = distanceSquared;
                zombie = candidate;
            }
            return zombie != null;
        }

        // 0.1.173: a burner is not fought up close (its death explosion is up
        // to 40 within 4m and turns ordinary zombies within 4m into burners)
        // except as the last resort of a flee: glued within 3m, no stamina,
        // no escape point, health above 55, a weapon, no ordinary zombie
        // within 5m of it (IsFireLastResort).
        private bool CanMeleeFireZombie(Zombie fireZombie)
        {
            var distance = (fireZombie.transform.position - m_Player.transform.position)
                .GetHorizontalMagnitude();
            return IsFireLastResort(fireZombie, distance, Time.realtimeSinceStartup)
                || CanTryhardMeleeFire(fireZombie, distance);
        }

        // Tracks how long a burner has stayed within 6m; true once it has kept
        // pace for FireZombieGluedFightSeconds.
        private bool UpdateFireGlue(Zombie fireZombie, float distance)
        {
            var realNow = Time.realtimeSinceStartup;
            if (distance <= 6f)
            {
                if (m_FireGluedZombie != fireZombie)
                {
                    m_FireGluedZombie = fireZombie;
                    m_FireGluedSince = realNow;
                }
            }
            else if (distance > 10f && m_FireGluedZombie == fireZombie)
            {
                m_FireGluedZombie = null;
            }
            return m_FireGluedZombie == fireZombie
                && realNow - m_FireGluedSince >= FireZombieGluedFightSeconds;
        }

        private int CountFireZombiesWithin(Vector3 position, float radius)
        {
            var count = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var candidate = perceived.Key;
                if (candidate == null
                    || candidate.isDead
                    || !candidate.gameObject.activeInHierarchy
                    || !IsFireZombie(candidate))
                {
                    continue;
                }
                if ((candidate.transform.position - position).GetHorizontalMagnitude() <= radius)
                {
                    count++;
                }
            }
            return count;
        }

        private bool IsRangedFireTarget(Zombie target)
        {
            return IsFireZombie(target) && HasLoadedRangedWeapon();
        }

        private bool HasLoadedRangedWeapon()
        {
            if (m_Player.equipment.equippedPage < PlayerInventory.SLOTS
                && m_Player.equipment.asset is ItemGunAsset equippedGun
                && (IsEquippedGunLoaded(equippedGun) || CanReloadGun(equippedGun)))
            {
                return true;
            }

            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                for (byte index = 0;
                     index < m_Player.inventory.getItemCount(page);
                     index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    // 0.1.174: only a gun that is, or can be put, in a slot.
                    if (jar?.GetAsset() is ItemGunAsset gun
                        && ((!IsKnownEmptyGunSlot(page, jar.x, jar.y)
                                && IsLoadedGun(gun, jar.item.state))
                            || CanReloadGun(gun))
                        && CanBecomeHoldable(page, gun))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private static bool IsLoadedGun(ItemGunAsset gun, byte[] state)
        {
            return gun.infiniteAmmo
                || (state != null
                    && state.Length > 10
                    && state[10] >= Mathf.Max(1, gun.ammoPerShot));
        }

        private bool IsEquippedGunLoaded(ItemGunAsset gun)
        {
            return !IsKnownEmptyGunSlot(
                       m_Player.equipment.equippedPage,
                       m_Player.equipment.equipped_x,
                       m_Player.equipment.equipped_y)
                && IsLoadedGun(gun, m_Player.equipment.state);
        }

        private bool IsKnownEmptyGunSlot(byte page, byte x, byte y)
        {
            // The flag only covers the short delay before the ammo count in
            // the item state catches up with the last shot; after that, trust
            // the state so a reloaded gun is usable again.
            if (m_KnownEquippedGunEmpty && Time.realtimeSinceStartup - m_KnownEmptyGunAt > 3f)
            {
                ClearKnownEmptyGun();
            }
            return m_KnownEquippedGunEmpty
                && page == m_KnownEmptyGunPage
                && x == m_KnownEmptyGunX
                && y == m_KnownEmptyGunY;
        }

        private void MarkEquippedGunEmpty()
        {
            m_KnownEquippedGunEmpty = true;
            m_KnownEmptyGunAt = Time.realtimeSinceStartup;
            m_KnownEmptyGunPage = m_Player.equipment.equippedPage;
            m_KnownEmptyGunX = m_Player.equipment.equipped_x;
            m_KnownEmptyGunY = m_Player.equipment.equipped_y;
        }

        private void ClearKnownEmptyGun()
        {
            m_KnownEquippedGunEmpty = false;
            m_KnownEmptyGunPage = byte.MaxValue;
            m_KnownEmptyGunX = byte.MaxValue;
            m_KnownEmptyGunY = byte.MaxValue;
        }

        // One crossbow bolt spent on a common zombie, then run to pick it up:
        // 66 weapon swaps in an hour, and every fire zombie met an empty bow.
        // A gun is used on common zombies only with shots to spare for one.
        private const int RangedReserveShots = 2;

        private bool HasSpareRangedShots(ItemGunAsset gun, byte[]? state)
        {
            if (gun.infiniteAmmo || !HasMeleeWeapon())
            {
                return true;
            }
            var shots = state != null && state.Length > 10 ? state[10] : 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMagazineAsset magazine
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        shots += jar.item.amount;
                    }
                }
            }
            return shots / Mathf.Max(1, (int)gun.ammoPerShot) > RangedReserveShots;
        }

        // A gun against a common zombie only from a distance: after a meal the
        // rearm took the crossbow (first slot) with a zombie at 4m and the bot
        // died in 3s at 50 health. With melee in the bag, a gun is not picked
        // with a zombie within 6m and is put away when one reaches 4m.
        private bool IsGunAllowedForCommonZombie(ItemGunAsset gun, byte[]? state, float closeMeters)
        {
            // 0.1.0-y17.7 (the tester, 18/11): with no blade the tryhard still
            // keeps the rounds for PvP and punches a lone common zombie.
            if (Tryhard && !HasMeleeWeapon() && !IsTryhardGunFightWithoutBlade(gun))
            {
                if (m_TargetZombie != null && !m_TargetZombie.isDead)
                {
                    LogTryhardBladeForCommon(m_TargetZombie);
                }
                return false;
            }
            if (!HasMeleeWeapon())
            {
                return true;
            }
            // 0.1.0-y16: a shot heard from someone not seen: the blade
            // (SkaliaBotPvpSpotY).
            if (IsPvpSilent())
            {
                return false;
            }
            if (Tryhard)
            {
                // 0.2.2x (doc 15.2, item 1): any distance, rounds to spare.
                // 0.2.2x1 (doc 16.3, item 7): unless this fight is a blade
                // fight by the bot's style (TryhardPrefersBlade).
                return HasSpareRangedShots(gun, state) && !TryhardPrefersBlade(state);
            }
            if (s_Settings.MeleeForCommon && !IsGunWorthyFight())
            {
                return false;
            }
            return m_CachedNearestZombieDistance > closeMeters
                && HasSpareRangedShots(gun, state);
        }

        // ---- 0.2.1: melee for the common zombie, like the players ----
        // 74-97% of the players' hits on 11-08 were within 3m: they walk up to
        // a common zombie with the knife or axe and keep the rounds for what
        // a blade can't handle. The gun stays for a zombie that is not a
        // plain walker or crawler (sprinter, burner, acid, stalker, boss),
        // the Mega, or 3+ zombies after the bot within 15m.
        private const float GunCrowdMeters = 15f;
        private const int GunCrowdCount = 3;

        // Without a blade the same cases as TryhardPrefersBlade keep the gun:
        // the Mega, a boss, a special zombie or 3+ zombies hunting the bot,
        // the Mega hunt or alert, an enemy player remembered, or an infinite
        // ammo gun.
        private bool IsTryhardGunFightWithoutBlade(ItemGunAsset gun)
        {
            return gun.infiniteAmmo
                || m_BossHuntActive
                || IsMegaNear()
                || IsMegaLostAlert()
                || m_PvpTarget != null
                || IsGunWorthyFight();
        }

        private bool IsGunWorthyFight()
        {
            var target = m_TargetZombie;
            if (target != null
                && !target.isDead
                && (target.isMega
                    || IsBossZombie(target)
                    || (target.speciality != EZombieSpeciality.NORMAL
                        && target.speciality != EZombieSpeciality.CRAWLER)))
            {
                return true;
            }
            var position = m_Player.transform.position;
            var hunting = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null
                    || zombie.isDead
                    || !zombie.gameObject.activeInHierarchy
                    || !zombie.isHunting
                    || zombie.player != m_Player
                    || (zombie.transform.position - position).GetHorizontalMagnitude() > GunCrowdMeters)
                {
                    continue;
                }
                if (++hunting >= GunCrowdCount)
                {
                    return true;
                }
            }
            return false;
        }

        private bool EnsureCombatWeapon(bool requireRanged, float now)
        {
            if (m_TreatmentPhase != 0)
            {
                // Hands are busy with a bandage; don't swap it out mid-use.
                return false;
            }
            var equipment = m_Player.equipment;
            var equippedAsset = equipment.asset;
            var equippedFromCombatSlot = equipment.equippedPage < PlayerInventory.SLOTS;
            // Reloading only pays off against a fire zombie or with no melee
            // weapon to fall back on; otherwise an empty gun is swapped out.
            // 0.2.2x (doc 15.2, item 1): the tryhard reloads the gun with no
            // zombie within 6m instead of taking the knife out.
            var allowReload = requireRanged || !HasMeleeWeapon()
                || (Tryhard && m_CachedNearestZombieDistance > WeaponSwapZombieMeters);
            var equippedIsValid = equippedFromCombatSlot
                && ((equippedAsset is ItemGunAsset equippedGun
                        && IsUsefulGun(equippedGun)
                        && (requireRanged || IsGunAllowedForCommonZombie(equippedGun, equipment.state, 4f))
                        && (IsEquippedGunLoaded(equippedGun)
                            || (allowReload && CanReloadGun(equippedGun))))
                    || (!requireRanged && equippedAsset is ItemMeleeAsset && ShouldTryhardKeepMelee()));
            if (equippedIsValid)
            {
                m_EquipAttemptCount = 0;
                return equipment.IsEquipAnimationFinished;
            }

            if (now < m_WeaponSwapBlockedUntil)
            {
                // A swap kept failing: fight with bare hands for a moment
                // instead of retrying the same equip while taking hits.
                if (!requireRanged && equipment.HasValidUseable && now >= m_NextWeaponSelectionAt)
                {
                    m_NextWeaponSelectionAt = now + 1f;
                    equipment.dequip();
                }
                return !requireRanged && !equipment.HasValidUseable;
            }

            if (now < m_NextWeaponSelectionAt)
            {
                return false;
            }
            m_NextWeaponSelectionAt = now + (m_CachedNearestZombieDistance <= 4f ? 0.3f : 0.5f);

            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                for (byte index = 0;
                     index < m_Player.inventory.getItemCount(page);
                     index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    var suitable = asset is ItemGunAsset gun
                        ? IsUsefulGun(gun)
                          && (requireRanged || IsGunAllowedForCommonZombie(gun, jar!.item.state, 6f))
                          && ((!IsKnownEmptyGunSlot(page, jar!.x, jar.y)
                                  && IsLoadedGun(gun, jar.item.state))
                              || (allowReload && CanReloadGun(gun)))
                        : !requireRanged && asset is ItemMeleeAsset && ShouldTryhardKeepMelee();
                    if (!suitable || jar == null)
                    {
                        continue;
                    }
                    if (!ItemTool.checkUseable(page, jar.item.id))
                    {
                        // A gun in the backpack can't be taken in hand: the game
                        // ignores the request ("Troca para 1911 falhou" 36 times
                        // in the 0.1.115 test, the bot fighting with a paddle).
                        // Put it in a weapon slot first, like a player; 0.1.174:
                        // freeing a slot held by an empty gun or a melee weapon,
                        // but not with a zombie within 6m.
                        if (asset is ItemGunAsset)
                        {
                            if (m_CachedNearestZombieDistance > WeaponSwapZombieMeters
                                && TryMakeGunHoldable(page, jar, asset, now))
                            {
                                return false;
                            }
                            if (m_CachedNearestZombieDistance > WeaponSwapZombieMeters)
                            {
                                LogWeaponSlotBlocked(asset, now);
                            }
                            continue;
                        }
                        if (TryMoveToWeaponSlot(page, jar, asset!))
                        {
                            return false;
                        }
                        continue;
                    }

                    if (equipment.asset is ItemConsumeableAsset
                        || now - m_TreatmentEndedAt < 4f)
                    {
                        // A bandage or snack still in hand, or just put away:
                        // the swap only fails until its animation ends, so keep
                        // asking instead of fighting with it in hand.
                        m_EquipAttemptCount = 0;
                        if (!equipment.isBusy)
                        {
                            equipment.ServerEquip(page, jar.x, jar.y);
                            BotLog(LogLevel.Information,
                                "Bot equipando {Item} da pagina {Page} para combater zumbis.",
                                asset!.itemName,
                                page);
                        }
                        return false;
                    }

                    if (asset!.id == m_EquipAttemptItemId && now - m_EquipAttemptSince <= 3f)
                    {
                        m_EquipAttemptCount++;
                    }
                    else
                    {
                        m_EquipAttemptItemId = asset.id;
                        m_EquipAttemptSince = now;
                        m_EquipAttemptCount = 1;
                    }
                    if (m_EquipAttemptCount > 2
                        && !requireRanged
                        && asset is ItemMeleeAsset
                        && equipment.asset is ItemGunAsset
                        && m_CachedNearestZombieDistance <= 4f)
                    {
                        // A zombie in reach and the gun busy reloading: waiting
                        // up to 6s with an empty gun in hand got the bot killed.
                        // Put the gun away (cancels the reload) and take the
                        // melee weapon on the next try.
                        if (now >= m_NextForcedSwapLogAt)
                        {
                            m_NextForcedSwapLogAt = now + 5f;
                            BotLog(LogLevel.Information,
                                "Troca para {Item} recusada com zumbi a {Distance:0.#}m; guardando {Gun} a forca.",
                                asset.itemName,
                                m_CachedNearestZombieDistance,
                                DescribeEquipped());
                        }
                        equipment.dequip();
                        m_EquipAttemptCount = 0;
                        m_NextWeaponSelectionAt = now + 0.3f;
                        return false;
                    }
                    if (m_EquipAttemptCount > 2
                        && equipment.asset is ItemGunAsset reloadingGun
                        && HasMagazineFor(reloadingGun)
                        && now - m_EquipAttemptSince < 6f)
                    {
                        // The swap is refused because the empty gun is being
                        // reloaded; wait for it instead of fighting barehanded.
                        if (now >= m_NextReloadWaitLogAt)
                        {
                            m_NextReloadWaitLogAt = now + 5f;
                            BotLog(LogLevel.Information,
                                "Troca para {Item} recusada; {Gun} provavelmente recarregando, aguardando.",
                                asset.itemName,
                                reloadingGun.itemName);
                        }
                        return false;
                    }
                    if (m_EquipAttemptCount > 2)
                    {
                        m_EquipAttemptCount = 0;
                        m_WeaponSwapBlockedUntil = now + 4f;
                        BotLog(LogLevel.Information,
                            "Troca para {Item} falhou {Attempts} vezes (em maos: {Current}); lutando sem trocar por 4s.",
                            asset.itemName,
                            3,
                            DescribeEquipped());
                        return false;
                    }

                    equipment.ServerEquip(page, jar.x, jar.y);
                    BotLog(LogLevel.Information,
                        "Bot equipando {Item} da pagina {Page} para combater zumbis.",
                        asset.itemName,
                        page);
                    return false;
                }
            }

            if (!requireRanged && equipment.HasValidUseable)
            {
                equipment.dequip();
                return false;
            }
            return !requireRanged && !equipment.HasValidUseable;
        }

        private void ConfigureCombatInput(WalkingPlayerInputPacket packet)
        {
            var now = Time.realtimeSinceStartup;
            if (m_PendingMeleeIsRepeated
                && (m_ObjectiveType != ObjectiveType.Combat
                    && m_ObjectiveType != ObjectiveType.EscapeSwarm
                    || !IsTargetZombieAlive()
                    || !(m_Player.equipment.asset is ItemMeleeAsset activeRepeatedMelee)
                    || !activeRepeatedMelee.isRepeated))
            {
                m_PendingMeleeRaycast = false;
                m_PendingMeleeIsRepeated = false;
                m_PendingMeleeTarget = null;
            }
            packet.primaryAttack = EAttackInputFlags.None;
            // 0.1.0-y17.12: a saw running on him stays down while the melee
            // fight with him goes on (SkaliaBotPvpMeleeY), and stops with it.
            var pvpSawRunning = m_PvpMeleeRepeating && m_PvpMelee && m_PvpEngaged;
            if (m_PvpMeleeRepeating && !pvpSawRunning)
            {
                m_PvpMeleeRepeating = false;
                m_PvpMeleePending = false;
            }
            if (m_PrimaryAttackHeld && !m_PendingMeleeRaycast && !pvpSawRunning)
            {
                packet.primaryAttack = EAttackInputFlags.Stop;
                m_PrimaryAttackHeld = false;
            }
            // 0.2.0: a held trigger stays down (no flag: UseableGun keeps
            // shooting) while the shot is still good, and is let go here.
            if (m_GunTriggerHeld && !ShouldKeepGunTrigger(now, out var triggerPause, out var triggerReason))
            {
                packet.primaryAttack = EAttackInputFlags.Stop;
                m_GunTriggerHeld = false;
                m_NextAttackTime = Mathf.Max(m_NextAttackTime, now + triggerPause);
                NoteGunBurstEnd(triggerReason, now);
            }
            TickGunBurstLog(now);
            packet.secondaryAttack = m_SecondaryAttackHeld
                ? EAttackInputFlags.Stop
                : EAttackInputFlags.None;
            m_SecondaryAttackHeld = false;
            if (m_TreatmentUseRequested)
            {
                // Same input a player sends to use a held bandage on self.
                m_TreatmentUseRequested = false;
                m_TreatmentPhaseSince = now;
                packet.primaryAttack = EAttackInputFlags.Start;
                m_PrimaryAttackHeld = true;
            }
            if (m_RefillUseRequested)
            {
                // What a player sends filling a canteen: the secondary button
                // with the point aimed at in the water.
                m_RefillUseRequested = false;
                packet.secondaryAttack = EAttackInputFlags.Start;
                m_SecondaryAttackHeld = true;
                var aim = m_RefillWater - m_Player.look.aim.position;
                var hit = new RaycastInfo(m_RefillGround)
                {
                    point = m_RefillWater,
                    direction = aim.sqrMagnitude > 0.001f ? aim.normalized : Vector3.down,
                    normal = m_RefillFromObject ? -(aim.sqrMagnitude > 0.001f ? aim.normalized : Vector3.down) : Vector3.up,
                    materialName = m_RefillFromObject ? null : "Water"
                };
                packet.clientsideInputs = new List<PlayerInputPacket.ClientRaycast>(1)
                {
                    new PlayerInputPacket.ClientRaycast(hit, ERaycastInfoUsage.Refill)
                };
            }

            // 0.2.2y: shooting back at a player comes before the zombie fight.
            if (ConfigurePvpInput(packet, now))
            {
                return;
            }
            var activeGunCombat = (m_ObjectiveType == ObjectiveType.Combat
                                   || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                && IsTargetZombieAlive()
                && m_Player.equipment.asset is ItemGunAsset activeGun
                && IsEquippedGunLoaded(activeGun);
            ReleaseDroppedGunAim(packet, now);
            if (m_GunAimHeld && !activeGunCombat && !ShouldKeepPostKillAim(now))
            {
                packet.secondaryAttack = EAttackInputFlags.Stop;
                m_GunAimHeld = false;
                m_GunAimReadyAt = 0f;
            }

            var packetSimulation = m_Player.input.simulation
                + (uint)m_Player.input.serversidePackets.Count;

            // 0.1.169: what a bullet hits is answered when the packet goes
            // out, from the bullet itself (AttachGunHits).
            m_GunCombatPacket = activeGunCombat;
            if (m_PendingMeleeRaycast
                && packetSimulation >= m_PendingMeleeImpactSimulation)
            {
                var pendingTarget = m_PendingMeleeTarget;
                var continueRepeated = m_PendingMeleeIsRepeated
                    && (m_ObjectiveType == ObjectiveType.Combat
                        || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                    && IsTargetZombieAlive()
                    && m_Player.equipment.asset is ItemMeleeAsset repeatedMelee
                    && repeatedMelee.isRepeated;
                if (continueRepeated)
                {
                    pendingTarget = m_TargetZombie;
                }
                if (pendingTarget != null
                    && !pendingTarget.isDead
                    && pendingTarget.gameObject.activeInHierarchy
                    && m_Player.equipment.asset is ItemMeleeAsset impactMelee)
                {
                    if (TryTraceMeleeSwing(pendingTarget, ERaycastInfoUsage.Melee, impactMelee.range, out var swingHit))
                    {
                        packet.clientsideInputs = new List<PlayerInputPacket.ClientRaycast>(1)
                        {
                            swingHit
                        };
                    }
                    if (!continueRepeated)
                    {
                        RerollMeleeAim();
                    }
                    BotLog(LogLevel.Debug,
                        "Golpe melee no quadro de impacto {Simulation} contra zumbi em {Target}: {Result}.",
                        packetSimulation,
                        FormatPosition(pendingTarget.transform.position),
                        packet.clientsideInputs != null && packet.clientsideInputs.Count > 0 ? "acertou" : "pegou no ar");
                }
                if (continueRepeated)
                {
                    m_PendingMeleeTarget = pendingTarget;
                    m_PendingMeleeImpactSimulation = packetSimulation
                        + m_PendingMeleeIntervalFrames;
                }
                else
                {
                    m_PendingMeleeRaycast = false;
                    m_PendingMeleeIsRepeated = false;
                    m_PendingMeleeTarget = null;
                }
                return;
            }

            if ((m_ObjectiveType != ObjectiveType.Combat
                 && m_ObjectiveType != ObjectiveType.EscapeSwarm)
                || !IsTargetZombieAlive()
                || now < m_NextAttackTime
                || m_GunTriggerHeld)
            {
                return;
            }

            var origin = m_Player.look.aim.position;
            var targetZombie = m_TargetZombie!;
            // 0.1.174: a gun still in the bag is not swapped in with a zombie
            // within 6m; then the fight goes on with what is in a slot.
            var requireRanged = (IsFireZombie(targetZombie) || IsHuntedBoss(targetZombie) || IsTryhardHuntShot()
                    || IsTryhardForcedGun(now))
                && (HasLoadedGunInSlot()
                    || (m_CachedNearestZombieDistance > WeaponSwapZombieMeters && HasLoadedRangedWeapon()));
            if (!EnsureCombatWeapon(requireRanged, now))
            {
                return;
            }

            var equippedAsset = m_Player.equipment.asset;
            var usage = ERaycastInfoUsage.Punch;
            var maximumRange = 1.75f;
            var attackName = "soco";
            var attackDelay = 0.55f;
            ItemMeleeAsset? meleeAsset = null;
            var meleeAnimationLength = 0f;
            var rangedShotWillDepleteWeapon = false;
            if (equippedAsset is ItemGunAsset gun)
            {
                var readyGun = m_Player.equipment.useable as UseableGun;
                if (readyGun != null && TrySetBestFiremode(gun, readyGun))
                {
                    return;
                }
                if (readyGun != null
                    && (readyGun.isReloading
                        || readyGun.isHammering
                        || readyGun.isAttaching
                        || readyGun.isUnjamming
                        || readyGun.needsRechamber
                        || readyGun.isFired
                        || m_Player.equipment.isBusy))
                {
                    // The server drops a shot sent during the reload/rechamber
                    // animation; counting it as fired made the bot reload a
                    // loaded bow again and again.
                    return;
                }
                if (!IsEquippedGunLoaded(gun))
                {
                    if (!TryReloadEquippedGun(gun, now))
                    {
                        m_NextWeaponSelectionAt = 0f;
                    }
                    return;
                }
                usage = ERaycastInfoUsage.Gun;
                maximumRange = gun.range;
                attackName = "disparo";
                attackDelay = Mathf.Max(0.18f, (gun.firerate + 1f) * 0.02f);
                rangedShotWillDepleteWeapon = !gun.infiniteAmmo
                    && m_Player.equipment.state != null
                    && m_Player.equipment.state.Length > 10
                    && m_Player.equipment.state[10]
                       <= Mathf.Max(1, gun.ammoPerShot);

                // All ranged weapons aim before firing. This is mandatory for
                // bows (EAction.String / MustAimToShoot), and avoids the server
                // rejecting primary input while the bot is still sprinting.
                // 0.2.2x7 (doc 16.13.1): the sights go up 0.3-0.8s before
                // the first round (0.25-0.5s within 6m); within 6m one fight
                // in four opens from the hip.
                var gunTargetDistance = (targetZombie.transform.position - m_Player.transform.position)
                    .GetHorizontalMagnitude();
                var hipOpening = !m_GunAimHeld
                    && IsGunHipFireOpening(targetZombie, gun, gunTargetDistance, now);
                if (!m_GunAimHeld && !hipOpening)
                {
                    if (m_Player.stance.stance == EPlayerStance.SPRINT)
                    {
                        return;
                    }
                    packet.secondaryAttack = EAttackInputFlags.Start;
                    m_GunAimHeld = true;
                    m_GunAimPressedAt = now;
                    m_GunAimReadyAt = now + DrawGunAimSettleSeconds(gunTargetDistance);
                    BotLog(LogLevel.Debug,
                        "Bot entrou em mira com {Weapon}; aguardando estabilizacao antes do disparo.",
                        gun.itemName);
                    return;
                }
                if (hipOpening && m_Player.stance.stance == EPlayerStance.SPRINT)
                {
                    return;
                }
                if (!hipOpening && now < m_GunAimReadyAt)
                {
                    return;
                }
                // 0.1.169: the trigger only with the gun on the zombie; the
                // bullet goes where the barrel points (AttachGunHits).
                if (!IsGunOnTarget(targetZombie))
                {
                    return;
                }
            }
            else if (equippedAsset is ItemMeleeAsset melee)
            {
                meleeAsset = melee;
                usage = ERaycastInfoUsage.Melee;
                maximumRange = melee.range;
                attackName = "golpe com " + melee.itemName;
                var animationName = melee.isRepeated ? "Start_Swing" : "Weak";
                meleeAnimationLength = m_Player.animator.GetAnimationLength(animationName);
                // 0.2.2y: the swing's own length (the game takes no new
                // swing before it ends). The 0.65s floor was slower than the
                // players: 0.65s median between blows, 0.44s p25 (08/11).
                // 0.1.0-y17.36: both over serverBot:modifiers:swingSpeed,
                // never under the swing itself.
                attackDelay = Mathf.Max(
                    0.44f / SkaliaBotModifiers.SwingSpeed,
                    meleeAnimationLength + 0.08f / SkaliaBotModifiers.SwingSpeed);
            }

            if (usage != ERaycastInfoUsage.Gun && m_CombatRetreatPending)
            {
                return;
            }
            if (meleeAsset?.isRepeated == true
                && m_PendingMeleeRaycast
                && m_PrimaryAttackHeld)
            {
                return;
            }

            var targetPoint = usage == ERaycastInfoUsage.Gun
                ? GetGunAimPoint(targetZombie)
                : GetMeleeAimPoint(targetZombie);
            var offset = targetPoint - origin;
            var horizontalOffset = new Vector2(offset.x, offset.z);
            // 0.2.2y: a zombie coming at the bot is met by the blade as it
            // gets in reach: the swing starts before (players' first swing:
            // 1.8m at a common one, 2.8m at a sprinter; bots' 1.4m and 1.2m).
            var swingLead = meleeAsset != null
                && !meleeAsset.isRepeated
                && IsMeleeSwingLeadReady(
                    targetZombie,
                    horizontalOffset.magnitude,
                    maximumRange,
                    (Mathf.Floor(Mathf.Max(1, Mathf.CeilToInt(meleeAnimationLength / PlayerInput.RATE)) * meleeAsset.weak) + 1f)
                        * PlayerInput.RATE,
                    now);
            if ((horizontalOffset.sqrMagnitude > maximumRange * maximumRange && !swingLead)
                || offset.sqrMagnitude < 0.001f
                || !HasClearLineToPoint(targetPoint))
            {
                return;
            }
            // 0.1.170: like a player, a swing starts with the weapon on the
            // zombie; it used to start whatever way the bot faced.
            if (usage != ERaycastInfoUsage.Gun && !IsFacingMeleePoint(targetZombie, targetPoint))
            {
                return;
            }

            // The fake connection has no Unity client process to perform the
            // clientside raycast. Build the same zombie hit payload a real
            // client sends. PlayerInput.read resolves the zombie by id, and
            // PlayerInput.getInput still performs the authoritative server-side
            // occlusion and range validation before PlayerEquipment applies damage.
            var usingFists = usage == ERaycastInfoUsage.Punch;
            var attackHand = m_UseSecondaryAttackNext ? "direito" : "esquerdo";
            if (usingFists && m_UseSecondaryAttackNext)
            {
                packet.secondaryAttack = EAttackInputFlags.Start;
                m_SecondaryAttackHeld = true;
            }
            else if (usage == ERaycastInfoUsage.Gun
                     && !rangedShotWillDepleteWeapon
                     && TryPickGunBurst(targetZombie, offset.magnitude, out var burstLimit))
            {
                // 0.2.0: held, not clicked: the gun fires at its own rate.
                packet.primaryAttack = EAttackInputFlags.Start;
                m_GunTriggerHeld = true;
                m_GunTriggerSince = now;
                m_GunTriggerTarget = targetZombie;
                NoteGunBurstStart(targetZombie, offset.magnitude);
                m_GunBurstShots = 0;
                m_GunBurstLimit = burstLimit;
            }
            else
            {
                packet.primaryAttack = EAttackInputFlags.Start;
                m_PrimaryAttackHeld = true;
            }
            m_UseSecondaryAttackNext = !m_UseSecondaryAttackNext;
            if (meleeAsset != null)
            {
                var animationFrames = Mathf.Max(
                    1,
                    Mathf.CeilToInt(meleeAnimationLength / PlayerInput.RATE));
                var impactFrameOffset = Mathf.Max(
                    1,
                    Mathf.FloorToInt(animationFrames * meleeAsset.weak) + 1);
                m_PendingMeleeRaycast = true;
                m_PendingMeleeIsRepeated = meleeAsset.isRepeated;
                m_PendingMeleeIntervalFrames = (uint)impactFrameOffset;
                m_PendingMeleeTarget = targetZombie;
                m_PendingMeleeImpactSimulation = packetSimulation
                    + (uint)impactFrameOffset;
                BotLog(LogLevel.Debug,
                    "Golpe melee iniciado no quadro {StartSimulation}; impacto previsto no quadro {ImpactSimulation}.",
                    packetSimulation,
                    m_PendingMeleeImpactSimulation);
            }
            else if (usage != ERaycastInfoUsage.Gun)
            {
                if (TryTraceMeleeSwing(targetZombie, usage, maximumRange, out var punchHit))
                {
                    packet.clientsideInputs = new List<PlayerInputPacket.ClientRaycast>(1)
                    {
                        punchHit
                    };
                }
                RerollMeleeAim();
            }
            m_PublishedAttackCount++;
            m_CommittedZombie = targetZombie;
            if (rangedShotWillDepleteWeapon)
            {
                MarkEquippedGunEmpty();
                m_NextWeaponSelectionAt = 0f;
                BotLog(LogLevel.Information,
                    "Bot consumiu a ultima municao da arma equipada; o disparo seguinte foi bloqueado.");
            }
            BotLog(LogLevel.Debug,
                "Bot enfileirou {Attack} {AttackNumber} contra zumbi em {Target}; distancia {Distance:0.##}m{HandSuffix}.",
                attackName,
                m_PublishedAttackCount,
                FormatPosition(targetZombie.transform.position),
                offset.magnitude,
                usingFists ? "; punho " + attackHand : string.Empty);
            m_NextAttackTime = now + attackDelay;
            if (usage != ERaycastInfoUsage.Gun
                && !(meleeAsset?.isRepeated ?? false))
            {
                m_CombatMovementPhase = CombatMovementPhase.Attack;
                m_MeleeBurstAttackCount++;
                m_CombatRetreatPending = m_MeleeBurstAttackCount
                    >= GetMeleeBurstTarget(targetZombie);
                m_CombatAttackRecoveryUntil = targetZombie.speciality
                    == EZombieSpeciality.CRAWLER
                        ? now + 0.2f
                        : m_NextAttackTime;
                m_CombatAttackFailsafeAt = m_NextAttackTime + 1f;
                if (m_CombatRetreatPending)
                {
                    BotLog(LogLevel.Debug,
                        "Bot concluiu rajada de {AttackCount} golpe(s); aguardando {Recovery:0.##}s antes do kite.",
                        m_MeleeBurstAttackCount,
                        attackDelay);
                }
            }
        }

        // 0.1.169: real gunfire. The server makes each bullet where the bot
        // looks (UseableGun.fire) and waits for the client to say what it
        // hit. The bot answered "this zombie's head" whatever the gun pointed
        // at, so it hit zombies off to the side (the tester: "como se tivesse
        // usando hack"). Now every bullet gets the gun's spread and flies
        // where the barrel pointed: the first zombie body on its line before
        // a wall is hit, on the limb at that height; a miss hits nothing.
        private readonly HashSet<BulletInfo> m_AnsweredBullets = new HashSet<BulletInfo>();

        // 0.2.0: each bullet flies like on a player's client (UseableGun
        // ballistics): every tick it moves velocity x 0.02s, the ray of that
        // step is traced, then gravity bends it. The hit is answered on the
        // tick the bullet gets there. The server only takes a hit within
        // Ballistic_Travel x (steps + 5) + 4m of the muzzle, steps being the
        // ticks the bullet has lived: answering every bullet on the next tick
        // threw away every hit past ~64m, and the line was straight (no drop).
        // The flight is kept one tick behind the server's (steps + 1), well
        // inside that check; a bullet that hits nothing before its last step
        // is not answered, as on a client.
        private sealed class BotBulletFlight
        {
            public Vector3 Position;
            public Vector3 Velocity;
            public int Steps;
            public bool CountShot;
            public bool Done;
        }

        private readonly Dictionary<BulletInfo, BotBulletFlight> m_BulletFlights =
            new Dictionary<BulletInfo, BotBulletFlight>();
        private const float BulletTickSeconds = 0.02f;

        private bool TryAdvanceBulletFlight(
            BotBulletFlight flight,
            BulletInfo bullet,
            ItemGunAsset gunAsset,
            out PlayerInputPacket.ClientRaycast hit)
        {
            hit = default!;
            var lastStep = Mathf.Max(1, (int)gunAsset.ballisticSteps);
            var target = Mathf.Min(bullet.steps + 1, lastStep);
            var gravity = Physics.gravity.y * bullet.gravityMultiplier;
            while (flight.Steps < target)
            {
                var segment = flight.Velocity * BulletTickSeconds;
                var length = segment.magnitude;
                if (length < 0.001f)
                {
                    flight.Done = true;
                    return false;
                }
                var countShot = flight.CountShot;
                flight.CountShot = false;
                if (TryTraceGunShot(flight.Position, segment / length, length, countShot, false, out hit))
                {
                    flight.Done = true;
                    return true;
                }
                flight.Position += segment;
                flight.Velocity.y += gravity * BulletTickSeconds;
                flight.Steps++;
            }
            if (flight.Steps >= lastStep)
            {
                flight.Done = true;
            }
            return false;
        }
        private bool m_GunCombatPacket;
        private readonly List<BulletInfo> m_BulletFlightRemoval = new List<BulletInfo>();

        // ---- 0.2.0: automatic fire held like a player ----
        // One click per shot capped the bots at about 5.5 shots/s: after each
        // round UseableGun keeps the hands busy 0.15s and a new pull is
        // refused. With the trigger held on AUTO the gun fires at its own
        // firerate (a PDW 10-12/s, as the players killed the Mega). Like the
        // players, the bot holds it close in, fires bursts of 3-6 at 25-50m
        // and single shots farther out. The trigger is let go when the gun
        // leaves the zombie, the target changes or dies, the line is blocked,
        // the magazine runs out, the bot sprints or after 6s.
        private const float GunHoldMeters = 25f;
        private const float GunBurstMeters = 50f;
        private const float GunHoldMaxSeconds = 6f;
        private bool m_GunTriggerHeld;
        private float m_GunTriggerSince;
        private Zombie? m_GunTriggerTarget;
        private int m_GunBurstShots;
        private int m_GunBurstLimit;

        // 0.2.2x7: the burst length is TryPickGunBurst (SkaliaBotGunFeelX7);
        // the reason the trigger was let go goes to the burst's log line.
        private bool ShouldKeepGunTrigger(float now, out float pause, out string reason)
        {
            pause = 0.08f;
            reason = string.Empty;
            // 0.2.2x3: the magazine swap is refused while the gun fires.
            if (now < m_HoldFireForReloadUntil)
            {
                reason = "recarga";
                return false;
            }
            if (!IsTargetZombieAlive() || m_TargetZombie != m_GunTriggerTarget)
            {
                reason = m_GunTriggerTarget == null || m_GunTriggerTarget.isDead ? "zumbi morreu" : "alvo trocou";
                return false;
            }
            if (!s_Settings.GunAutoFire
                || (m_ObjectiveType != ObjectiveType.Combat
                    && m_ObjectiveType != ObjectiveType.EscapeSwarm))
            {
                reason = "fim do combate";
                return false;
            }
            if (!(m_Player.equipment.asset is ItemGunAsset gun)
                || !(m_Player.equipment.useable is UseableGun useable)
                || useable.firemode != EFiremode.AUTO
                || useable.isReloading
                || useable.isHammering
                || useable.isAttaching
                || useable.isUnjamming
                || useable.needsRechamber)
            {
                reason = "arma ocupada";
                return false;
            }
            if (!IsEquippedGunLoaded(gun))
            {
                reason = "sem municao";
                return false;
            }
            if (m_Player.stance.stance == EPlayerStance.SPRINT
                || m_Player.stance.stance == EPlayerStance.SWIM)
            {
                reason = "correndo";
                return false;
            }
            if (now - m_GunTriggerSince > GunHoldMaxSeconds)
            {
                reason = "6s segurando";
                return false;
            }
            var target = m_TargetZombie!;
            var point = GetGunAimPoint(target);
            if ((point - m_Player.look.aim.position).magnitude > gun.range
                || !HasClearLineToPoint(point))
            {
                reason = "sem linha";
                return false;
            }
            if (!IsGunOnTarget(target, 1.5f))
            {
                reason = "mira saiu do zumbi";
                return false;
            }
            if (m_GunBurstLimit > 0 && m_GunBurstShots >= m_GunBurstLimit)
            {
                pause = NextGunBurstPause(target);
                reason = "fim da rajada";
                return false;
            }
            return true;
        }
        private int m_StatWindowShots;
        private int m_StatWindowShotHits;
        private int m_StatWindowHeadshots;
        private static Transform? s_GroundTagTransform;

        private static float ZombieBodyHeight(Zombie zombie)
        {
            return zombie.isMega ? 3.2f : zombie.speciality == EZombieSpeciality.CRAWLER ? 0.8f : 1.9f;
        }

        private static float ZombieBodyRadius(Zombie zombie)
        {
            return zombie.isMega ? 0.7f : zombie.speciality == EZombieSpeciality.CRAWLER ? 0.45f : 0.35f;
        }

        // 0.1.170: where a melee swing aims, drawn again after every swing.
        // 0.1.172: the head again about 9 swings in 10. Half the swings on
        // the body (0.6 of the damage) took 3.0 attacks per kill instead of
        // 2.1 in the 0.1.171 test, longer within the zombies' reach, and
        // deaths went from 4.7 to 8.9 an hour; the tester's own recording hit
        // the head nearly every time. What varies now is where on the head,
        // the distance kept and the timing, not the limb. The head aim stays
        // inside the head band (0.82 and up) with room for the pitch still
        // settling.
        private float m_MeleeAimHeight = 0.89f;
        private float m_MeleeAimSide;
        private float m_MeleeDistanceShare = 0.9f;
        private int m_StatWindowSwings;
        private int m_StatWindowSwingHits;
        private int m_StatWindowSwingHeads;

        private Vector3 GetMeleeAimPoint(Zombie zombie)
        {
            var root = zombie.transform.position;
            var toZombie = root - m_Player.transform.position;
            toZombie.y = 0f;
            var side = toZombie.sqrMagnitude > 0.01f
                ? new Vector3(toZombie.z, 0f, -toZombie.x).normalized
                : Vector3.zero;
            if (zombie.speciality == EZombieSpeciality.CRAWLER && !zombie.isMega)
            {
                // A crawler lies along its facing with the head in front;
                // its body center is the miss-proof point for the rest.
                return m_MeleeAimHeight >= 0.82f
                    ? GetCrawlerHeadPoint(zombie)
                    : root + Vector3.up * 0.4f;
            }
            return root
                + Vector3.up * (ZombieBodyHeight(zombie) * m_MeleeAimHeight)
                + side * (m_MeleeAimSide * ZombieBodyRadius(zombie));
        }

        private static Vector3 GetCrawlerHeadPoint(Zombie zombie)
        {
            var forward = zombie.transform.forward;
            forward.y = 0f;
            forward = forward.sqrMagnitude > 0.01f ? forward.normalized : Vector3.zero;
            // Inside the 0.45m body cylinder the swing trace tests, so a
            // swing at the head of a crawler facing the bot lands on it; from
            // behind the trace meets the back first and it is a body hit.
            return zombie.transform.position + forward * 0.35f + Vector3.up * 0.3f;
        }

        private void RerollMeleeAim()
        {
            if (!s_Settings.MeleeAimVariation)
            {
                m_MeleeAimHeight = 0.89f;
                m_MeleeAimSide = 0f;
                m_MeleeDistanceShare = 0.9f;
                return;
            }
            // 0.2.2y: the players hit the head with 96% of the blade
            // blows on 08/11 (345 of 361); a body blow of a worn blade
            // without Overkill does not stun.
            // 0.1.0-y17.36: times serverBot:modifiers:meleeHeadshots.
            m_MeleeAimHeight = Random.value < SkaliaBotModifiers.Share(0.96f, SkaliaBotModifiers.MeleeHeadshots)
                ? Random.Range(0.86f, 0.93f)
                : Random.Range(0.62f, 0.76f);
            m_MeleeAimSide = Random.Range(-0.25f, 0.25f);
            // The distance kept while swinging: 80-95% of the reach. Never
            // past it (a swing from outside reach is a miss, the old
            // complaint was standing too close).
            m_MeleeDistanceShare = Random.Range(0.8f, 0.95f);
        }

        private bool IsFacingMeleePoint(Zombie zombie, Vector3 point)
        {
            var toPoint = point - m_Player.look.aim.position;
            var distance = toPoint.magnitude;
            if (distance < 0.4f)
            {
                return true;
            }
            var tolerance = Mathf.Max(
                5f,
                Mathf.Atan2(ZombieBodyRadius(zombie) * 0.7f, distance) * Mathf.Rad2Deg);
            return Vector3.Angle(AimDirection(m_CurrentYaw, m_CurrentPitch), toPoint) <= tolerance;
        }

        // 0.1.170: a swing hits what the weapon points at when it lands, on
        // the limb at that height, the same way the bullets do since 0.1.169.
        // Every swing used to land on the target's head (ClientRaycast with
        // SKULL) wherever the bot looked. Nothing on the line: it misses.
        private bool TryTraceMeleeSwing(
            Zombie target,
            ERaycastInfoUsage usage,
            float range,
            out PlayerInputPacket.ClientRaycast result)
        {
            result = default;
            m_StatWindowSwings++;
            var origin = m_Player.look.aim.position;
            var direction = AimDirection(m_CurrentYaw, m_CurrentPitch);
            Zombie? struck = null;
            var reach = range + 0.25f;
            if (TryHitZombieBody(target, origin, direction, reach, out var targetDistance))
            {
                struck = target;
                reach = targetDistance;
            }
            foreach (var zombie in m_PerceivedZombies.Keys)
            {
                if (zombie != target && TryHitZombieBody(zombie, origin, direction, reach, out var distance))
                {
                    struck = zombie;
                    reach = distance;
                }
            }
            // 0.1.0-y17.12: the blow lands on what is first in front, as a
            // player's does. At 22:30:24 (18/11) the tester stood 0.9 to 1.4m in
            // front of LilJuninho, its saw down on a zombie behind him, and
            // the trace only knew the zombie: he was never cut.
            if (TryTraceMeleeSwingOnMan(origin, direction, reach, usage, out result))
            {
                return true;
            }
            if (struck == null)
            {
                return false;
            }
            var point = origin + direction * reach;
            if (!HasClearLineToPoint(point))
            {
                return false;
            }
            var limb = GetBodyLimb(struck, point);
            var info = new RaycastInfo(struck.transform)
            {
                zombie = struck,
                point = point,
                direction = direction,
                normal = -direction,
                limb = limb,
                materialName = struck.isRadioactive ? "Alien_Dynamic" : "Flesh_Dynamic"
            };
            m_StatWindowSwingHits++;
            m_TotalAttackHits++;
            if (limb == ELimb.SKULL)
            {
                m_StatWindowSwingHeads++;
            }
            result = new PlayerInputPacket.ClientRaycast(info, usage);
            return true;
        }

        // 0.2.0: the head at any distance, like the players (72% of their
        // gun hits on 11-08 were on the head, Onca's 96%; the bots, aiming at
        // the chest past 10m, 21%). A height inside the head band (0.82 and up) is
        // drawn per target; the gun's spread and the recoil decide the rest.
        // A crawler keeps the body center: its head sits 0.3m off the ground,
        // behind any kerb. serverBot:behavior:gunHeadAim false = up to 0.1.175.
        private float m_GunHeadAim = 0.91f;
        private Zombie? m_GunHeadAimTarget;

        private Vector3 GetGunAimPoint(Zombie zombie)
        {
            var root = zombie.transform.position;
            if (!s_Settings.GunHeadAim
                || (zombie.speciality == EZombieSpeciality.CRAWLER && !zombie.isMega))
            {
                var distance = (root - m_Player.look.aim.position).GetHorizontalMagnitude();
                return root + Vector3.up * (ZombieBodyHeight(zombie) * (distance <= 10f ? 0.9f : 0.68f));
            }
            if (zombie != m_GunHeadAimTarget)
            {
                m_GunHeadAimTarget = zombie;
                m_GunHeadAim = Random.Range(0.87f, 0.95f);
            }
            return root + Vector3.up * (ZombieBodyHeight(zombie) * m_GunHeadAim);
        }

        // ---- 0.2.0: holdover and lead ----
        // With ballistics on a bullet leaves at the gun's muzzle velocity
        // (Ballistic_Travel x 50 m/s) and falls by gravity x the gun's and
        // attachments' multiplier: 0.2m at 50m, 0.8m at 100m for a default
        // gun, far more for a bow. Like a player, the bot aims that much above
        // the head and ahead of a moving zombie by its flight time. The
        // estimate is off by a draw per target (holdover 80-120%, lead
        // 60-110%), so the farther, the larger the miss.
        private Zombie? m_GunSkillTarget;
        private float m_GunHoldoverSkill = 1f;
        private float m_GunLeadSkill = 1f;
        private Zombie? m_LeadZombie;
        private Vector3 m_LeadLastPosition;
        private float m_LeadLastTime;
        private Vector3 m_LeadVelocity;
        private const float LeadSampleSeconds = 0.1f;
        private const float LeadMaxSpeed = 12f;

        private Vector3 GetGunSteerPoint(Zombie zombie)
        {
            var point = GetGunAimPoint(zombie);
            if (!(Provider.modeConfigData?.Gameplay?.Ballistics ?? true)
                || !(m_Player.equipment.asset is ItemGunAsset gun)
                || gun.projectile != null
                || gun.muzzleVelocity < 1f)
            {
                return point;
            }
            if (zombie != m_GunSkillTarget)
            {
                m_GunSkillTarget = zombie;
                m_GunHoldoverSkill = Random.Range(0.8f, 1.2f);
                m_GunLeadSkill = Random.Range(0.6f, 1.1f);
            }
            var flight = (point - m_Player.look.aim.position).magnitude / gun.muzzleVelocity;
            var gravityMultiplier = m_Player.equipment.useable is UseableGun useable
                ? useable.CalculateBulletGravityMultiplier()
                : gun.bulletGravityMultiplier;
            var drop = 0.5f * -Physics.gravity.y * gravityMultiplier * flight * flight;
            return point
                + GetZombieLeadVelocity(zombie) * (flight * m_GunLeadSkill)
                + Vector3.up * (drop * m_GunHoldoverSkill);
        }

        // Horizontal velocity sampled every 0.1s and smoothed; a jump in
        // position (respawn, teleport) is capped instead of trusted.
        private Vector3 GetZombieLeadVelocity(Zombie zombie)
        {
            var now = Time.realtimeSinceStartup;
            var position = zombie.transform.position;
            if (zombie != m_LeadZombie || now - m_LeadLastTime > 1f)
            {
                m_LeadZombie = zombie;
                m_LeadLastPosition = position;
                m_LeadLastTime = now;
                m_LeadVelocity = Vector3.zero;
                return m_LeadVelocity;
            }
            var elapsed = now - m_LeadLastTime;
            if (elapsed >= LeadSampleSeconds)
            {
                var sample = position - m_LeadLastPosition;
                sample.y = 0f;
                sample = Vector3.ClampMagnitude(sample / elapsed, LeadMaxSpeed);
                m_LeadVelocity = Vector3.Lerp(m_LeadVelocity, sample, 0.5f);
                m_LeadLastPosition = position;
                m_LeadLastTime = now;
            }
            return m_LeadVelocity;
        }

        private static Vector3 AimDirection(float yaw, float pitch)
        {
            return Quaternion.Euler(pitch - 90f, yaw, 0f) * Vector3.forward;
        }

        private bool IsGunOnTarget(Zombie zombie)
        {
            return IsGunOnTarget(zombie, 1f);
        }

        // 0.2.0: judged on the aim the server gets, recoil included. A held
        // trigger lets go a little later (slack 1.5) than a new pull starts,
        // so the recoil of one shot does not cut every burst at two rounds.
        private bool IsGunOnTarget(Zombie zombie, float slack)
        {
            var toTarget = GetGunSteerPoint(zombie) - m_Player.look.aim.position;
            var distance = toTarget.magnitude;
            if (distance < 0.5f)
            {
                return true;
            }
            var tolerance = Mathf.Max(
                1f,
                Mathf.Atan2(ZombieBodyRadius(zombie) * 0.6f, distance) * Mathf.Rad2Deg) * slack;
            return Vector3.Angle(AimDirection(GetSentYaw(), GetSentPitch()), toTarget) <= tolerance;
        }

        // ---- 0.2.0: recoil ----
        // Each round fired kicks the aim by the gun's own recoil (the same
        // numbers UseableGun.fire uses on a real client: stance, in the air,
        // aiming, attachments, the server's first-person multipliers), times
        // gunRecoilScale for what a hand on the mouse catches at once. The
        // rest fades in RecoilFadeSeconds, a player pulling the aim back down.
        // It sits on top of where the bot wants to look and goes out in the
        // packet, so the server makes the next bullets where the gun now
        // points: long bursts far away spread, short ones close in hit.
        private const float RecoilFadeSeconds = 0.15f;
        private const float RecoilMaxDegrees = 12f;
        private float m_RecoilPitch;
        private float m_RecoilYaw;

        private const float ProneMaxPitch = 92f;
        private const float ProneAimMaxPitch = 100f;

        private float GetSentPitch()
        {
            return Mathf.Clamp(m_CurrentPitch - m_RecoilPitch, 0f, 180f);
        }

        private float GetSentYaw()
        {
            return m_CurrentYaw + m_RecoilYaw;
        }

        private void FadeRecoil()
        {
            if (m_RecoilPitch == 0f && m_RecoilYaw == 0f)
            {
                return;
            }
            // 0.1.0-y15: pulled back between the rounds of a gun fight
            // (SkaliaBotPvpRecoilY).
            var keep = Mathf.Exp(-Time.fixedDeltaTime / (IsPvpRecoilPulled() ? PvpRecoilFadeSeconds : RecoilFadeSeconds));
            m_RecoilPitch *= keep;
            m_RecoilYaw *= keep;
            if (Mathf.Abs(m_RecoilPitch) < 0.01f && Mathf.Abs(m_RecoilYaw) < 0.01f)
            {
                m_RecoilPitch = 0f;
                m_RecoilYaw = 0f;
            }
        }

        private void ClearRecoil()
        {
            m_RecoilPitch = 0f;
            m_RecoilYaw = 0f;
        }

        private void ApplyGunRecoil(UseableGun gun, ItemGunAsset asset)
        {
            var scale = s_Settings.GunRecoilScale;
            if (scale <= 0f)
            {
                return;
            }
            var x = Random.Range(asset.recoilMin_x, asset.recoilMax_x);
            var y = Random.Range(asset.recoilMin_y, asset.recoilMax_y);
            var multiplier = scale;
            try
            {
                multiplier *= m_Player.skills.GetSharpshooterRecoilMultiplier();
                var aiming = gun.isAiming;
                if (aiming)
                {
                    multiplier *= asset.aimingRecoilMultiplier;
                }
                var attachments = gun.thirdAttachments;
                if (attachments != null)
                {
                    if (attachments.sightAsset != null)
                    {
                        x *= attachments.sightAsset.recoil_x;
                        y *= attachments.sightAsset.recoil_y;
                        if (aiming)
                        {
                            multiplier *= attachments.sightAsset.aimingRecoilMultiplier;
                        }
                    }
                    if (attachments.gripAsset != null
                        && (!attachments.gripAsset.ShouldOnlyAffectAimWhileProne
                            || m_Player.stance.stance == EPlayerStance.PRONE))
                    {
                        x *= attachments.gripAsset.recoil_x;
                        y *= attachments.gripAsset.recoil_y;
                        if (aiming)
                        {
                            multiplier *= attachments.gripAsset.aimingRecoilMultiplier;
                        }
                    }
                    if (attachments.barrelAsset != null)
                    {
                        x *= attachments.barrelAsset.recoil_x;
                        y *= attachments.barrelAsset.recoil_y;
                        if (aiming)
                        {
                            multiplier *= attachments.barrelAsset.aimingRecoilMultiplier;
                        }
                    }
                    if (attachments.magazineAsset != null)
                    {
                        x *= attachments.magazineAsset.recoil_x;
                        y *= attachments.magazineAsset.recoil_y;
                        if (aiming)
                        {
                            multiplier *= attachments.magazineAsset.aimingRecoilMultiplier;
                        }
                    }
                }
                switch (m_Player.stance.stance)
                {
                    case EPlayerStance.SPRINT:
                        multiplier *= asset.recoilSprint;
                        break;
                    case EPlayerStance.CROUCH:
                        multiplier *= asset.recoilCrouch;
                        break;
                    case EPlayerStance.PRONE:
                        multiplier *= asset.recoilProne;
                        break;
                    case EPlayerStance.SWIM:
                        multiplier *= asset.recoilSwimming;
                        break;
                }
                if (!m_Player.movement.isGrounded)
                {
                    multiplier *= asset.recoilMidair;
                }
                var gameplay = Provider.modeConfigData?.Gameplay;
                if (gameplay != null)
                {
                    multiplier *= gameplay.FirstPerson_RecoilMultiplier;
                    if (aiming)
                    {
                        multiplier *= gameplay.FirstPerson_AimingRecoilMultiplier;
                    }
                }
            }
            catch
            {
                // An attachment or a config the game changed: the gun's own
                // numbers times the scale still give a kick.
            }
            if (float.IsNaN(multiplier) || float.IsInfinity(multiplier) || multiplier < 0f)
            {
                return;
            }
            m_RecoilYaw = Mathf.Clamp(m_RecoilYaw + x * multiplier, -RecoilMaxDegrees, RecoilMaxDegrees);
            m_RecoilPitch = Mathf.Clamp(m_RecoilPitch + y * multiplier, -RecoilMaxDegrees, RecoilMaxDegrees);
        }

        private float GetGunSpreadRadians(UseableGun gun, ItemGunAsset asset)
        {
            var aimAlpha = Mathf.Clamp01(gun.GetSimulationAimAlpha());
            var spread = 0f;
            try
            {
                spread = gun.CalculateSpreadAngleRadians(m_Player.equipment.quality / 100f, aimAlpha);
            }
            catch
            {
                spread = 0f;
            }
            if (!(spread > 0.0001f))
            {
                spread = asset.baseSpreadAngleRadians * Mathf.Lerp(1f, asset.spreadAim, aimAlpha);
                if (m_Player.stance.stance == EPlayerStance.CROUCH)
                {
                    spread *= asset.spreadCrouch;
                }
                else if (m_Player.stance.stance == EPlayerStance.SPRINT)
                {
                    spread *= asset.spreadSprint;
                }
            }
            return Mathf.Clamp(spread, 0f, 0.3f);
        }

        private static Vector3 ApplySpread(Vector3 direction, float radians)
        {
            if (radians <= 0f || direction.sqrMagnitude < 0.0001f)
            {
                return direction;
            }
            var angle = radians * Mathf.Sqrt(Random.value) * Mathf.Rad2Deg;
            var roll = Random.value * 360f;
            return Quaternion.LookRotation(direction)
                * Quaternion.Euler(0f, 0f, roll)
                * Quaternion.Euler(angle, 0f, 0f)
                * Vector3.forward;
        }

        // A vertical body: where the line enters it, if before maxDistance.
        private static bool TryHitZombieBody(
            Zombie zombie,
            Vector3 origin,
            Vector3 direction,
            float maxDistance,
            out float distance)
        {
            distance = 0f;
            if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
            {
                return false;
            }
            var root = zombie.transform.position;
            var radius = ZombieBodyRadius(zombie);
            var top = root.y + ZombieBodyHeight(zombie);
            var ox = origin.x - root.x;
            var oz = origin.z - root.z;
            var a = direction.x * direction.x + direction.z * direction.z;
            if (a < 0.000001f)
            {
                return false;
            }
            var b = 2f * (ox * direction.x + oz * direction.z);
            var c = ox * ox + oz * oz - radius * radius;
            var discriminant = b * b - 4f * a * c;
            if (discriminant < 0f)
            {
                return false;
            }
            var root2 = Mathf.Sqrt(discriminant);
            var enter = Mathf.Max(0f, (-b - root2) / (2f * a));
            var leave = (-b + root2) / (2f * a);
            if (leave < 0f)
            {
                return false;
            }
            var enterY = origin.y + direction.y * enter;
            var leaveY = origin.y + direction.y * leave;
            float hit;
            if (enterY >= root.y && enterY <= top)
            {
                hit = enter;
            }
            else if (enterY > top && leaveY <= top && direction.y < 0f)
            {
                hit = (top - origin.y) / direction.y;
            }
            else if (enterY < root.y && leaveY >= root.y && direction.y > 0f)
            {
                hit = (root.y - origin.y) / direction.y;
            }
            else
            {
                return false;
            }
            if (hit > maxDistance)
            {
                return false;
            }
            distance = hit;
            return true;
        }

        private static ELimb GetBodyLimb(Zombie zombie, Vector3 point)
        {
            if (zombie.speciality == EZombieSpeciality.CRAWLER)
            {
                return !zombie.isMega && (point - GetCrawlerHeadPoint(zombie)).sqrMagnitude <= 0.3f * 0.3f
                    ? ELimb.SKULL
                    : ELimb.SPINE;
            }
            var root = zombie.transform.position;
            var height = (point.y - root.y) / ZombieBodyHeight(zombie);
            var side = Vector3.Dot(point - root, zombie.transform.right);
            if (height >= 0.82f)
            {
                return ELimb.SKULL;
            }
            if (height >= 0.45f)
            {
                if (Mathf.Abs(side) > ZombieBodyRadius(zombie) * 0.75f)
                {
                    return side < 0f ? ELimb.LEFT_ARM : ELimb.RIGHT_ARM;
                }
                return ELimb.SPINE;
            }
            return side < 0f ? ELimb.LEFT_LEG : ELimb.RIGHT_LEG;
        }

        // A miss is answered "nothing here": the server then lets the bullet
        // go with no damage (the puff shows on the wall it struck). That
        // answer has to name ground or environment.
        private static Transform? GetGroundTagTransform(Transform? candidate)
        {
            if (candidate != null && (candidate.CompareTag("Ground") || candidate.CompareTag("Environment")))
            {
                return candidate;
            }
            if (s_GroundTagTransform == null)
            {
                try
                {
                    s_GroundTagTransform = GameObject.FindWithTag("Ground")?.transform;
                }
                catch
                {
                    s_GroundTagTransform = null;
                }
            }
            return s_GroundTagTransform;
        }

        private bool TryTraceGunShot(
            Vector3 origin,
            Vector3 direction,
            float range,
            bool countShot,
            bool answerAirMiss,
            out PlayerInputPacket.ClientRaycast result)
        {
            result = default!;
            if (countShot)
            {
                m_StatWindowShots++;
            }
            var reach = range;
            var wallFound = Physics.Raycast(
                origin,
                direction,
                out var wall,
                range,
                RayMasks.DAMAGE_SERVER,
                QueryTriggerInteraction.Ignore);
            if (wallFound)
            {
                reach = wall.distance;
            }
            Zombie? struck = null;
            var struckDistance = reach;
            foreach (var zombie in m_PerceivedZombies.Keys)
            {
                if (TryHitZombieBody(zombie, origin, direction, struckDistance, out var distance))
                {
                    struck = zombie;
                    struckDistance = distance;
                }
            }
            if (m_TargetZombie != null
                && TryHitZombieBody(m_TargetZombie, origin, direction, struckDistance, out var targetDistance))
            {
                struck = m_TargetZombie;
                struckDistance = targetDistance;
            }
            // 0.2.2y: the player the bot is shooting back at, when nearer than
            // the wall and the zombies on the line.
            if (m_PvpTarget != null
                && TryHitPvpTarget(origin, direction, struckDistance, out _, out var pvpHit))
            {
                m_PvpHits++;
                m_TotalAttackHits++;
                result = new PlayerInputPacket.ClientRaycast(pvpHit, ERaycastInfoUsage.Gun);
                return true;
            }
            if (struck != null)
            {
                var point = origin + direction * struckDistance;
                var limb = GetBodyLimb(struck, point);
                var info = new RaycastInfo(struck.transform)
                {
                    zombie = struck,
                    point = point,
                    direction = direction,
                    normal = -direction,
                    limb = limb,
                    materialName = struck.isRadioactive ? "Alien_Dynamic" : "Flesh_Dynamic"
                };
                m_StatWindowShotHits++;
                m_TotalAttackHits++;
                if (limb == ELimb.SKULL)
                {
                    m_StatWindowHeadshots++;
                }
                result = new PlayerInputPacket.ClientRaycast(info, ERaycastInfoUsage.Gun);
                return true;
            }
            if (!wallFound && !answerAirMiss)
            {
                return false;
            }
            var groundTag = GetGroundTagTransform(wallFound ? wall.transform : null);
            if (groundTag == null)
            {
                return false;
            }
            var miss = new RaycastInfo(groundTag)
            {
                point = wallFound ? wall.point - direction * 0.05f : origin + direction * range,
                direction = direction,
                normal = wallFound ? wall.normal : -direction,
                materialName = wallFound ? PhysicsTool.GetMaterialName(wall) : null
            };
            result = new PlayerInputPacket.ClientRaycast(miss, ERaycastInfoUsage.Gun);
            return true;
        }

        private void AttachGunHits(WalkingPlayerInputPacket packet)
        {
            var equipment = m_Player.equipment;
            if (!(equipment.useable is UseableGun gun)
                || !(equipment.asset is ItemGunAsset gunAsset)
                || gunAsset.projectile != null)
            {
                m_AnsweredBullets.Clear();
                m_BulletFlights.Clear();
                m_GunCombatPacket = false;
                return;
            }
            var spread = GetGunSpreadRadians(gun, gunAsset);
            List<PlayerInputPacket.ClientRaycast>? hits = null;
            if (Provider.modeConfigData?.Gameplay?.Ballistics ?? true)
            {
                // A bullet waits on the server, a few ticks, for its answer.
                var bullets = gun.bullets;
                if (bullets == null || bullets.Count == 0)
                {
                    m_AnsweredBullets.Clear();
                    m_BulletFlights.Clear();
                }
                else
                {
                    m_AnsweredBullets.RemoveWhere(answered => !bullets.Contains(answered));
                    if (m_BulletFlights.Count > 0)
                    {
                        m_BulletFlightRemoval.Clear();
                        foreach (var tracked in m_BulletFlights.Keys)
                        {
                            if (!m_AnsweredBullets.Contains(tracked))
                            {
                                m_BulletFlightRemoval.Add(tracked);
                            }
                        }
                        foreach (var gone in m_BulletFlightRemoval)
                        {
                            m_BulletFlights.Remove(gone);
                        }
                    }
                    var fired = 0;
                    var muzzleVelocity = gunAsset.muzzleVelocity > 1f
                        ? gunAsset.muzzleVelocity
                        : Mathf.Max(1f, gunAsset.ballisticTravel) * PlayerInput.TOCK_PER_SECOND;
                    foreach (var bullet in bullets)
                    {
                        if (bullet == null)
                        {
                            continue;
                        }
                        if (m_AnsweredBullets.Add(bullet))
                        {
                            if (bullet.pellet == 0)
                            {
                                fired++;
                            }
                            if (bullet.magazineAsset != null && bullet.magazineAsset.isExplosive)
                            {
                                continue;
                            }
                            var aim = bullet.ApproximatePlayerAimDirection.sqrMagnitude > 0.5f
                                ? bullet.ApproximatePlayerAimDirection.normalized
                                : m_Player.look.aim.forward;
                            m_BulletFlights[bullet] = new BotBulletFlight
                            {
                                Position = bullet.origin,
                                Velocity = ApplySpread(aim, spread) * muzzleVelocity,
                                CountShot = bullet.pellet == 0
                            };
                        }
                        if (!m_BulletFlights.TryGetValue(bullet, out var flight) || flight.Done)
                        {
                            continue;
                        }
                        if (TryAdvanceBulletFlight(flight, bullet, gunAsset, out var hit))
                        {
                            hits ??= new List<PlayerInputPacket.ClientRaycast>();
                            hits.Add(hit);
                        }
                    }
                    // 0.2.0: the kick comes after the round left, on the aim
                    // of the next ones; a held trigger counts its burst here.
                    for (var shot = 0; shot < fired; shot++)
                    {
                        // 0.1.0-y14: in a gun fight the kick does not pile
                        // up (SkaliaBotPvpRecoilY).
                        PullPvpRecoilBack();
                        ApplyGunRecoil(gun, gunAsset);
                    }
                    // 0.1.0-y16: the rounds from this spot (SkaliaBotPvpSpotY).
                    NotePvpRounds(fired);
                    if (m_GunTriggerHeld)
                    {
                        m_GunBurstShots += fired;
                    }
                }
            }
            else if (m_GunCombatPacket)
            {
                // Without ballistics a bullet lives one tick: answer every
                // packet, as a client predicting its shot.
                if (TryTraceGunShot(
                        m_Player.look.aim.position,
                        ApplySpread(AimDirection(m_CurrentYaw, m_CurrentPitch), spread),
                        gunAsset.range,
                        false,
                        true,
                        out var hit))
                {
                    hits = new List<PlayerInputPacket.ClientRaycast>(1) { hit };
                }
            }
            m_GunCombatPacket = false;
            if (hits == null)
            {
                return;
            }
            if (packet.clientsideInputs == null)
            {
                packet.clientsideInputs = hits;
            }
            else
            {
                packet.clientsideInputs.AddRange(hits);
            }
        }

        private PlayerInputPacket.ClientRaycast CreateZombieRaycast(
            Zombie targetZombie,
            ERaycastInfoUsage usage)
        {
            var targetPoint = GetZombieAimPoint(targetZombie);
            var offset = targetPoint - m_Player.look.aim.position;
            var hit = new RaycastInfo(targetZombie.transform)
            {
                zombie = targetZombie,
                point = targetPoint,
                direction = offset.sqrMagnitude > 0.001f
                    ? offset.normalized
                    : m_Player.look.aim.forward,
                normal = offset.sqrMagnitude > 0.001f
                    ? -offset.normalized
                    : -m_Player.look.aim.forward,
                limb = ELimb.SKULL,
                materialName = targetZombie.isRadioactive
                    ? "Alien_Dynamic"
                    : "Flesh_Dynamic"
            };
            return new PlayerInputPacket.ClientRaycast(hit, usage);
        }

        private bool IsTargetZombieAlive()
        {
            return m_TargetZombie != null
                && !m_TargetZombie.isDead
                && m_TargetZombie.gameObject.activeInHierarchy;
        }

        private float GetCombatDistance(Vector3 position)
        {
            if ((m_ObjectiveType != ObjectiveType.Combat
                 && m_ObjectiveType != ObjectiveType.EscapeSwarm)
                || !IsTargetZombieAlive())
            {
                return float.PositiveInfinity;
            }

            var offset = m_TargetZombie!.transform.position - position;
            var horizontal = offset.GetHorizontalMagnitude();
            // A zombie on another floor is not "in reach" just because it is
            // straight above: count the climb so the bot keeps following the route.
            return IsOtherFloorOffset(offset)
                ? Mathf.Max(horizontal, Mathf.Abs(offset.y)) + 3f
                : horizontal;
        }

        private bool IsOtherFloorOffset(Vector3 offset)
        {
            // A zombie lower down a hill 30m away is on the same "floor".
            // 0.2.2t: a blade does not reach 2.1m up (the tower fight took
            // 24s with the bot standing under the zombie): from 1.7m it is
            // another floor for melee and the bot takes the stairs.
            var up = Tryhard && !(m_Player.equipment.asset is ItemGunAsset) ? 1.7f : 2.2f;
            return (offset.y > up || offset.y < -2.6f)
                && offset.GetHorizontalMagnitude() < Mathf.Abs(offset.y) * 2.5f;
        }

        private bool IsCombatTargetOnOtherFloor(Vector3 position)
        {
            return (m_ObjectiveType == ObjectiveType.Combat)
                && IsTargetZombieAlive()
                && IsOtherFloorOffset(m_TargetZombie!.transform.position - position);
        }

        // Once per target: is the other floor on the route graph? If yes, follow
        // the route (stairs, ramp); if not, the zombie can't be reached on foot.
        private void UpdateOtherFloorTarget(Vector3 position, float now)
        {
            if (!IsCombatTargetOnOtherFloor(position))
            {
                m_FloorRouteActive = false;
                if (!IsTargetZombieAlive())
                {
                    m_FloorCheckedTarget = null;
                }
                return;
            }
            var target = m_TargetZombie!;
            if (target == m_FloorCheckedTarget)
            {
                return;
            }
            m_FloorCheckedTarget = target;
            var targetPosition = target.transform.position;
            var nodeHeight = float.NaN;
            if (AstarPath.active != null)
            {
                var nearest = AstarPath.active.GetNearest(targetPosition, NNConstraint.Walkable);
                if (nearest.node != null)
                {
                    nodeHeight = nearest.position.y;
                }
            }
            if (float.IsNaN(nodeHeight) || Mathf.Abs(nodeHeight - targetPosition.y) > 1.5f)
            {
                m_FloorRouteActive = false;
                m_UnreachableZombies[target] = now + OtherFloorIgnoreSeconds;
                BotLog(LogLevel.Information,
                    "Zumbi em outro andar ({Height:0.#}m de diferenca) em {Position} fora da malha de rota (no mais proximo a {Node}); ignorado por {Seconds:0}s.",
                    targetPosition.y - position.y,
                    FormatPosition(targetPosition),
                    float.IsNaN(nodeHeight) ? "nenhum" : nodeHeight.ToString("0.#"),
                    OtherFloorIgnoreSeconds);
                m_TargetZombie = null;
                ClearObjective();
                m_NextZombieScanTime = 0f;
                return;
            }
            m_FloorRouteActive = true;
            m_PathPoints.Clear();
            m_PathIndex = 0;
            m_NextPathRequestTime = 0f;
            m_DirectFallbackUntil = 0f;
            BotLog(LogLevel.Information,
                "Zumbi em outro andar ({Height:0.#}m de diferenca) em {Position}; seguindo a rota (escada/rampa) ate ele.",
                targetPosition.y - position.y,
                FormatPosition(targetPosition));
        }

        private Vector3 GetZombieAimPoint(Zombie zombie)
        {
            if (m_ZombieHeadTransforms.TryGetValue(zombie, out var cached)
                && cached != null)
            {
                return GetTransformAimPoint(cached);
            }

            foreach (var collider in zombie.GetComponentsInChildren<Collider>())
            {
                var name = collider.name;
                if (name.IndexOf("head", System.StringComparison.OrdinalIgnoreCase) < 0
                    && name.IndexOf("skull", System.StringComparison.OrdinalIgnoreCase) < 0)
                {
                    continue;
                }

                m_ZombieHeadTransforms[zombie] = collider.transform;
                return collider.bounds.center;
            }

            // Vanilla zombie eyes/head are approximately 1.55m above the root.
            return zombie.transform.position + Vector3.up * 1.55f;
        }

        private static Vector3 GetTransformAimPoint(Transform transform)
        {
            return transform.TryGetComponent<Collider>(out var collider)
                ? collider.bounds.center
                : transform.position;
        }

        private void ObserveNearbyLoot(Vector3 position, float now)
        {
            ObserveNearbyLoot(
                position,
                now,
                m_LootSearchRadiusMeters * 2f,
                false);
        }

        private void UpdatePendingLootObservations(float now)
        {
            for (var index = m_PendingLootObservations.Count - 1; index >= 0; index--)
            {
                var pending = m_PendingLootObservations[index];
                if (now >= pending.NextScanAt)
                {
                    ObserveNearbyLoot(pending.Position, now, 14f, true);
                    pending.NextScanAt = now + 0.5f;
                }
                if (now >= pending.ExpiresAt)
                {
                    m_PendingLootObservations.RemoveAt(index);
                }
            }
        }

        private void ObserveNearbyLoot(
            Vector3 position,
            float now,
            float radius,
            bool markAsCombatDrop)
        {
            for (var index = m_LootMemories.Count - 1; index >= 0; index--)
            {
                if (now >= m_LootMemories[index].ExpiresAt)
                {
                    m_LootMemories.RemoveAt(index);
                }
            }
            if (ItemManager.regions == null)
            {
                return;
            }

            m_LootSearchRegions.Clear();
            Regions.getRegionsInRadius(
                position,
                radius,
                m_LootSearchRegions);
            foreach (var coordinate in m_LootSearchRegions)
            {
                var region = ItemManager.regions[coordinate.x, coordinate.y];
                if (region == null)
                {
                    continue;
                }
                foreach (var item in region.items)
                {
                    if (item == null || item.item == null)
                    {
                        continue;
                    }
                    if ((item.point - position).GetHorizontalMagnitude() > radius)
                    {
                        continue;
                    }
                    var memory = m_LootMemories.Find(
                        candidate => candidate.InstanceId == item.instanceID);
                    if (memory == null)
                    {
                        if (m_LootMemories.Count >= 256)
                        {
                            m_LootMemories.RemoveAt(0);
                        }
                        memory = new LootMemory();
                        m_LootMemories.Add(memory);
                        memory.ObservedDuringCombat = markAsCombatDrop
                            || now - m_LastCombatThreatAt <= 2f;
                        if (memory.ObservedDuringCombat)
                        {
                            BotLog(LogLevel.Debug,
                                "Bot memorizou loot {LootInstanceId} surgido durante o combate em {Position}; coleta foi adiada.",
                                item.instanceID,
                                FormatPosition(item.point));
                        }
                    }
                    memory.RegionX = coordinate.x;
                    memory.RegionY = coordinate.y;
                    memory.InstanceId = item.instanceID;
                    memory.ItemId = item.item.id;
                    memory.Position = item.point;
                    memory.ExpiresAt = now + 600f;
                }
            }
        }

        private bool TryFindRememberedLoadedRangedLoot(
            Vector3 position,
            float now,
            out byte regionX,
            out byte regionY,
            out ItemData item)
        {
            regionX = byte.MaxValue;
            regionY = byte.MaxValue;
            item = null!;
            if (ItemManager.regions == null || HasWeaponRole(true))
            {
                return false;
            }

            GraphNode? originNode = null;
            if (AstarPath.active != null)
            {
                originNode = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
            }
            var bestDistance = float.PositiveInfinity;
            for (var index = m_LootMemories.Count - 1; index >= 0; index--)
            {
                var memory = m_LootMemories[index];
                if (now >= memory.ExpiresAt
                    || !Regions.checkSafe(memory.RegionX, memory.RegionY))
                {
                    m_LootMemories.RemoveAt(index);
                    continue;
                }
                var region = ItemManager.regions[memory.RegionX, memory.RegionY];
                var rememberedItem = region?.items.Find(
                    candidate => candidate.instanceID == memory.InstanceId);
                if (rememberedItem == null)
                {
                    m_LootMemories.RemoveAt(index);
                    continue;
                }
                var asset = Assets.find(EAssetType.ITEM, memory.ItemId) as ItemGunAsset;
                if (asset == null || !IsLoadedGun(asset, rememberedItem.item.state))
                {
                    continue;
                }
                if (IsLootClaimedByAnotherBot(memory.InstanceId, now))
                {
                    continue;
                }
                // Also with no zombie node near the bot: in the 0.1.150 test
                // XXlloqiartyXX, on a strip with no zombie graph, picked a
                // bandage 935m away and milk 480m away 886 times in 40 min.
                if (AstarPath.active != null)
                {
                    var destinationNode = AstarPath.active
                        .GetNearest(memory.Position, NNConstraint.Walkable).node;
                    if (!CanReach(originNode, destinationNode, position, memory.Position))
                    {
                        continue;
                    }
                }
                var distance = (memory.Position - position).GetHorizontalMagnitude();
                // A gun for the burner here, not one remembered across the map.
                if (distance >= bestDistance || distance > FireWeaponSearchMeters)
                {
                    continue;
                }
                bestDistance = distance;
                regionX = memory.RegionX;
                regionY = memory.RegionY;
                item = rememberedItem;
            }
            return item != null;
        }

        private bool TryFindRememberedInterestingLoot(
            Vector3 position,
            float now,
            out byte regionX,
            out byte regionY,
            out ItemData item)
        {
            regionX = byte.MaxValue;
            regionY = byte.MaxValue;
            item = null!;
            if (ItemManager.regions == null)
            {
                return false;
            }

            GraphNode? originNode = null;
            if (AstarPath.active != null)
            {
                originNode = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
            }
            var bestPriority = int.MaxValue;
            var bestDistance = float.PositiveInfinity;
            var bestWasCombatDrop = false;
            var unarmed = IsUnarmed();
            if (unarmed)
            {
                CollectZombiesNear(position, InterestAreaRadiusMeters * 2f + UnarmedWeaponZombieMeters);
            }
            GetConsumableLootNeeds(out var needFood, out var needWater);
            for (var index = m_LootMemories.Count - 1; index >= 0; index--)
            {
                var memory = m_LootMemories[index];
                if (now >= memory.ExpiresAt
                    || !Regions.checkSafe(memory.RegionX, memory.RegionY))
                {
                    m_LootMemories.RemoveAt(index);
                    continue;
                }
                var region = ItemManager.regions[memory.RegionX, memory.RegionY];
                var rememberedItem = region?.items.Find(
                    candidate => candidate.instanceID == memory.InstanceId);
                if (rememberedItem == null)
                {
                    m_LootMemories.RemoveAt(index);
                    continue;
                }
                var asset = Assets.find(EAssetType.ITEM, memory.ItemId) as ItemAsset;
                if (asset == null
                    || !ShouldCollectLootAsset(asset, false, null, rememberedItem.item.amount, rememberedItem.item.quality)
                    || IsLootIgnored(memory.InstanceId, now)
                    || IsLootClaimedByAnotherBot(memory.InstanceId, now)
                    || IsHazardousPosition(memory.Position, now, 2f)
                    || IsInRememberedIsland(memory.Position, now)
                    || IsWithinMegaReach(memory.Position)
                    || IsSkippedContainerLoot(memory.Position)
                    || (IsInFinishedAreaFarAway(memory.Position, position, now)
                        && !((needFood && asset.type == EItemType.FOOD)
                             || (needWater && asset.type == EItemType.WATER)))
                    || (IsHuntSweep && !unarmed && IsHuntLootSkipped(asset, memory.Position, position, needFood, needWater))
                    || (IsStrongSweep && !unarmed && IsStrongLootSkipped(asset, memory.Position, position, needFood, needWater))
                    || !(m_HasInterestArea && IsInsideInterestArea(memory.Position, 12f)
                         || (memory.Position - position).GetHorizontalMagnitude() <= RememberedLootReach(asset, needFood, needWater))
                    || (unarmed && IsUnarmedLootCrowded(memory.Position)))
                {
                    continue;
                }
                // Also with no zombie node near the bot: in the 0.1.150 test
                // XXlloqiartyXX, on a strip with no zombie graph, picked a
                // bandage 935m away and milk 480m away 886 times in 40 min.
                if (AstarPath.active != null)
                {
                    var destinationNode = AstarPath.active
                        .GetNearest(memory.Position, NNConstraint.Walkable).node;
                    if (!CanReach(originNode, destinationNode, position, memory.Position))
                    {
                        continue;
                    }
                }
                var priority = AdjustNeedLootPriority(asset, GetLootPriority(asset), needFood, needWater);
                var distance = (memory.Position - position).GetHorizontalMagnitude();
                if (priority > bestPriority
                    || priority == bestPriority
                       && bestWasCombatDrop
                       && !memory.ObservedDuringCombat
                    || priority == bestPriority
                       && bestWasCombatDrop == memory.ObservedDuringCombat
                       && distance >= bestDistance)
                {
                    continue;
                }
                bestWasCombatDrop = memory.ObservedDuringCombat;
                bestPriority = priority;
                bestDistance = distance;
                regionX = memory.RegionX;
                regionY = memory.RegionY;
                item = rememberedItem;
            }
            return item != null;
        }

        private bool TryFindNearestLoot(
            Vector3 position,
            float now,
            bool onlyCombatEquipment,
            out byte targetRegionX,
            out byte targetRegionY,
            out ItemData targetItem,
            bool onlyLoadedRangedWeapon = false)
        {
            targetRegionX = byte.MaxValue;
            targetRegionY = byte.MaxValue;
            targetItem = null!;
            if (ItemManager.regions == null)
            {
                return false;
            }

            var bestDistanceSquared = m_LootSearchRadiusMeters * m_LootSearchRadiusMeters;
            var bestPriority = int.MaxValue;
            var unarmed = IsUnarmed();
            var dropWindow = IsDropPickupWindow();
            GetConsumableLootNeeds(out var needFood, out var needWater);
            // 0.2.2t: sweeping the hunting ground, houses are not looted.
            var huntSweep = IsHuntSweep && !unarmed && !dropWindow;
            var strongSweep = IsStrongSweep && !unarmed && !dropWindow;
            if (unarmed)
            {
                CollectZombiesNear(position, m_LootSearchRadiusMeters + UnarmedWeaponZombieMeters);
            }
            m_LootSearchRegions.Clear();
            Regions.getRegionsInRadius(position, m_LootSearchRadiusMeters, m_LootSearchRegions);
            foreach (var coordinate in m_LootSearchRegions)
            {
                var region = ItemManager.regions[coordinate.x, coordinate.y];
                if (region == null)
                {
                    continue;
                }

                foreach (var item in region.items)
                {
                    var asset = Assets.find(EAssetType.ITEM, item?.item.id ?? 0) as ItemAsset;
                    var isCombatEquipment = asset is ItemGunAsset || asset is ItemMeleeAsset;
                    var isLoadedRangedWeapon = asset is ItemGunAsset rangedGun
                        && item != null
                        && IsLoadedGun(rangedGun, item.item.state);
                    if (item == null
                        || asset == null
                        || IsOutsideLootPile(item.point, position)
                        || !ShouldCollectLootAsset(asset, onlyLoadedRangedWeapon, item.item.state, item.item.amount, item.item.quality)
                        || (onlyCombatEquipment && !isCombatEquipment)
                        || (onlyLoadedRangedWeapon && !isLoadedRangedWeapon)
                        || IsLootIgnored(item.instanceID, now)
                        || IsLootClaimedByAnotherBot(item.instanceID, now)
                        || IsHazardousPosition(item.point, now, 2f)
                        || IsInRememberedIsland(item.point, now)
                        || IsWithinMegaReach(item.point)
                        || IsSkippedContainerLoot(item.point)
                        || IsRadiationClosedFor(item.point)
                        || (IsInFinishedAreaFarAway(item.point, position, now)
                            && !((needFood && asset.type == EItemType.FOOD)
                                 || (needWater && asset.type == EItemType.WATER)))
                        || (!huntSweep
                            && !IsInsideInterestArea(item.point, 8f)
                            && !((needFood && asset.type == EItemType.FOOD)
                                 || (needWater && asset.type == EItemType.WATER)))
                        || (huntSweep && IsHuntLootSkipped(asset, item.point, position, needFood, needWater))
                        || (strongSweep && IsStrongLootSkipped(asset, item.point, position, needFood, needWater))
                        || (unarmed && IsUnarmedLootCrowded(item.point))
                        || IsLootRaceDeferred(item.instanceID, now)
                        || IsLootSpotAvoided(item.point, now, (unarmed && isCombatEquipment) || onlyLoadedRangedWeapon || dropWindow))
                    {
                        continue;
                    }

                    var offset = item.point - position;
                    if (Mathf.Abs(offset.y) > 12f)
                    {
                        continue;
                    }

                    var distanceSquared = offset.x * offset.x + offset.z * offset.z;
                    var priority = AdjustNeedLootPriority(asset, GetLootPriority(asset), needFood, needWater);
                    // 0.2.2w (doc 14.3, item 2): the floor the bot is on
                    // first. An item one floor up or down was worth the same
                    // as one next to it, and the bot went up and down the
                    // stairs between loot and patrol points.
                    if (Tryhard && Mathf.Abs(offset.y) > TryhardFloorMeters)
                    {
                        priority += 2;
                        distanceSquared += 400f;
                    }
                    if (priority > bestPriority
                        || (priority == bestPriority && distanceSquared >= bestDistanceSquared))
                    {
                        continue;
                    }

                    bestPriority = priority;
                    bestDistanceSquared = distanceSquared;
                    targetRegionX = coordinate.x;
                    targetRegionY = coordinate.y;
                    targetItem = item;
                }
            }

            return targetItem != null;
        }

        // Bandages come from torn clothes in the early game: find every recipe
        // that produces a bleeding-stopping medical item, and every recipe that
        // produces one of its ingredients (clothing -> cloth -> rag).
        private static void EnsureMedicalRecipes()
        {
            if (s_MedicalBlueprints != null)
            {
                return;
            }
            var medical = new List<Blueprint>();
            var materials = new List<Blueprint>();
            var supplyIds = new HashSet<ushort>();
            var sourceIds = new HashSet<ushort>();
            var items = new List<ItemAsset>();
            Assets.find(items);
            foreach (var item in items)
            {
                if (item?.blueprints == null)
                {
                    continue;
                }
                foreach (var blueprint in item.blueprints)
                {
                    if (blueprint?.outputs == null || blueprint.supplies == null)
                    {
                        continue;
                    }
                    foreach (var output in blueprint.outputs)
                    {
                        if (output?.FindItemAsset() is ItemMedicalAsset produced
                            && produced.bleedingModifier == ItemConsumeableAsset.Bleeding.Heal
                            && !UsesCombatSupplies(blueprint))
                        {
                            medical.Add(blueprint);
                            foreach (var supply in blueprint.supplies)
                            {
                                var supplyAsset = supply?.FindItemAsset();
                                if (supplyAsset != null && supplyAsset.id != 0)
                                {
                                    supplyIds.Add(supplyAsset.id);
                                }
                            }
                            break;
                        }
                    }
                }
            }
            foreach (var item in items)
            {
                if (item?.blueprints == null)
                {
                    continue;
                }
                foreach (var blueprint in item.blueprints)
                {
                    if (blueprint?.outputs == null
                        || blueprint.supplies == null
                        || medical.Contains(blueprint))
                    {
                        continue;
                    }
                    // Only tearing clothes counts: never salvage arrows, food
                    // or tools into scraps.
                    var onlyClothes = blueprint.supplies.Length > 0;
                    foreach (var supply in blueprint.supplies)
                    {
                        var supplyAsset = supply?.FindItemAsset();
                        if (supplyAsset == null || supplyAsset.id == 0 || !IsClothingType(supplyAsset.type))
                        {
                            onlyClothes = false;
                            break;
                        }
                    }
                    if (!onlyClothes)
                    {
                        continue;
                    }
                    foreach (var output in blueprint.outputs)
                    {
                        var outputAsset = output?.FindItemAsset();
                        if (outputAsset != null && supplyIds.Contains(outputAsset.id))
                        {
                            materials.Add(blueprint);
                            foreach (var supply in blueprint.supplies)
                            {
                                sourceIds.Add(supply.FindItemAsset()!.id);
                            }
                            break;
                        }
                    }
                }
            }
            s_MedicalSupplyIds = supplyIds;
            s_MedicalMaterialSourceIds = sourceIds;
            s_MedicalMaterialBlueprints = materials;
            s_MedicalBlueprints = medical;
        }

        private static bool UsesCombatSupplies(Blueprint blueprint)
        {
            foreach (var supply in blueprint.supplies)
            {
                var asset = supply?.FindItemAsset();
                if (asset == null
                    || asset is ItemWeaponAsset && !(asset is ItemConsumeableAsset)
                    || asset.type == EItemType.MAGAZINE
                    || asset is ItemFoodAsset
                    || asset is ItemWaterAsset)
                {
                    return true;
                }
            }
            return false;
        }

        private static bool IsClothingType(EItemType type)
        {
            switch (type)
            {
                case EItemType.SHIRT:
                case EItemType.PANTS:
                case EItemType.HAT:
                case EItemType.VEST:
                case EItemType.MASK:
                case EItemType.BACKPACK:
                    return true;
                default:
                    return false;
            }
        }

        // Treat like a player does: equip the bandage, press use, and let the
        // game apply it at the end of the use animation.
        private void TryTreatWounds(float now)
        {
            var life = m_Player.life;
            if (life.isDead)
            {
                m_TreatmentPhase = 0;
                m_TreatmentUseRequested = false;
                return;
            }
            if (m_TreatmentPhase != 0)
            {
                m_IdleConsumableSince = -1f;
                UpdateTreatment(now);
                return;
            }
            // 0.2.2y: no bandage while trading shots with a player.
            // 0.2.2y2: but at 35 health or less (SkaliaBotPvpHealY).
            // 0.2.2y5: and not with him seen or a hit taken in the last 10s
            // either (Ghost bandaged at 78 and 43 health with the tester 4 to 8m
            // away and in sight, 17/11 03:08:44 and 03:09:19).
            // 0.1.0-y17.3: nor on the way to him or around him
            // (SkaliaBotPvpLookCoverY, IsPvpMovingOnHim).
            // 0.1.0-y17.7 (test of 18/11, 17:38:27-35): ToxicSniper, 63
            // health and not bleeding, prone behind a stone fence, heard
            // the tester's steps running at it, lost sight of him 3s before,
            // took the Cobra back and then a third bandage with him at 2m;
            // the use cannot be undone, and it fired 4.3s after it saw him.
            // the tester ("rushei seco, dei uma brecha que ele nao aproveitou").
            // His steps heard in the last 10s are the fight too.
            if ((IsPvpEngaged() || IsPvpActive(now) || IsPvpMovingOnHim()
                    || (m_PvpTarget != null && now - m_PvpLastHeardAt <= PvpActiveSeconds))
                && !IsPvpLowHealthBreak(now))
            {
                return;
            }
            // 0.1.0-y17.5: still hurt with the next bandage already in the
            // hands: no gun in between. Ghost (13:09:32 of 18/11) put the
            // bandage away, took the Heartbreaker out and the bandage again
            // at 27 health, the tester 22m off. The players of 08/11 held a
            // medical item 3.1s (median) to 7.6s (p75) at a time
            // (rec/m19a.py): one after the other.
            var nextInHand = m_Player.equipment.asset is ItemMedicalAsset
                && (life.isBleeding || life.health < HurtTreatmentHealth)
                && GetNearestAggroedZombieDistance() >= 10f
                && m_CachedNearestZombieDistance >= 6f;
            if (nextInHand)
            {
                m_IdleConsumableSince = -1f;
                m_RearmPending = false;
            }
            else
            {
                PutAwayIdleConsumable(now);
            }
            if (!m_MedicalRecipesLogged)
            {
                m_MedicalRecipesLogged = true;
                LogMedicalRecipes();
            }
            if (now < m_NextTreatmentAt)
            {
                return;
            }
            if (m_RearmPending)
            {
                TryRearm(now);
                return;
            }
            // 0.1.0-y17.25: a filter into the gas mask (SkaliaBotRadiationY).
            if (TryStartFilterUse(now))
            {
                return;
            }
            // x19: the virus under the line falls by itself (SkaliaBotX19).
            if (TryTreatVirus(now))
            {
                return;
            }
            var bleeding = life.isBleeding;
            var hurt = life.health < HurtTreatmentHealth;
            if (!bleeding && !hurt && !life.isBroken)
            {
                TryEatOrDrink(now);
                return;
            }
            // Only a zombie coming after the bot (or already in reach) stops a
            // bandage or a drink; one standing around 15m away doesn't, and the
            // bot walks away from a chaser while the item is used.
            var aggroed = GetNearestAggroedZombieDistance();
            // Bleeding at 61 health with three zombies in 4m, the bot stopped
            // to tear a shirt, make a rag and use it (0.1.115 test, 00:56):
            // 61 -> 15 health while bandaging, dead seconds later. Bleeding
            // costs a point at a time; keep running until they're 6m back.
            // 0.1.166: 64 treatments were put off with no zombie after the
            // bot, 55 of them under 40 health: any zombie seen in the last 2s
            // (up to 50m away) counted as combat, and so did a burner within
            // 15m that was not coming or a Combat objective with nothing close.
            // 0.2.2x7 (doc 16.13): any zombie within 6m, coming or not (Tadeu
            // took out a bandage with a crawler at 4.7m and was bitten).
            var blocked = bleeding
                ? aggroed < 10f || m_CachedNearestZombieDistance < 6f
                : aggroed < TreatAggroMeters
                  || m_CachedNearestZombieDistance < 6f
                  || IsFireZombieThreatWithin(15f, 8f)
                  || (m_ObjectiveType == ObjectiveType.Combat && m_CachedNearestZombieDistance < 8f)
                  || (m_ObjectiveType == ObjectiveType.EscapeSwarm && m_CachedSurroundedZombieCount > 0)
                  || now - m_LastZombieBiteAt < 2f;
            // 0.2.2x1 (doc 16.5): no stop to treat with a Mega after the bot
            // within 15m; it puts distance first.
            blocked = blocked
                || (Tryhard
                    && m_CachedNearestBoss != null
                    && !m_CachedNearestBoss.isDead
                    && IsBossAfterBot(m_CachedNearestBoss)
                    && m_CachedNearestBossDistance < 15f);
            if (blocked)
            {
                if (!bleeding)
                {
                    LogMealBlocked(now, "curativo/refeicao adiados (zumbi a "
                        + m_CachedNearestZombieDistance.ToString("0.#") + "m, atras do bot a "
                        + aggroed.ToString("0.#") + "m, objetivo " + m_ObjectiveType + ")");
                }
                return;
            }
            m_NextTreatmentAt = now + 1f;
            if (m_Player.equipment.isBusy)
            {
                return;
            }
            // 0.1.0-y16.2: only the leg broken is only for what mends a bone
            // (Bones_Modifier Heal). Vultox, fallen from the tower at
            // Olympia (17:29:47), used Painkillers and a Bandage at 100
            // health and stopped twice for them in the open (17:29:52-17:30:09).
            if (!bleeding && !hurt)
            {
                if (TryFindBoneTreatment(out var bonePage, out var boneJar, out var boneMedical))
                {
                    StartTreatment(bonePage, boneJar, boneMedical, life, false, now);
                    return;
                }
                TryEatOrDrink(now);
                return;
            }
            // Not bleeding there is time to craft: cloth into rags, two rags
            // into a bandage, then use the best one.
            // 0.2.2y3: with a ready one in the bag the fight is no time for
            // crafting (Vultox tore 4 pieces of clothing into rags with
            // LilJuninho shooting at him, 17/11 01:2x).
            if (!bleeding
                && !(IsPvpActive(now) && TryFindTreatment(false, out _, out _, out _))
                && TryCraftMedicalOnly(now))
            {
                return;
            }
            if (TryFindTreatment(bleeding, out var page, out var jar, out var medical))
            {
                StartTreatment(page, jar, medical, life, bleeding, now);
                return;
            }
            if (!bleeding && life.health >= 50)
            {
                TryEatOrDrink(now);
                return;
            }
            TryCraftTreatment(now);
            if (!bleeding && m_TreatmentPhase == 0)
            {
                // Health only regenerates when fed: don't starve waiting for a bandage.
                TryEatOrDrink(now);
            }
        }

        // A burner close by, or one coming after the bot.
        private bool IsFireZombieThreatWithin(float huntingMeters, float anyMeters)
        {
            if (m_CachedNearestFireZombieDistance >= huntingMeters)
            {
                return false;
            }
            if (m_CachedNearestFireZombieDistance < anyMeters)
            {
                return true;
            }
            var position = m_Player.transform.position;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null
                    && !zombie.isDead
                    && zombie.gameObject.activeInHierarchy
                    && IsFireZombie(zombie)
                    && zombie.isHunting
                    && zombie.player == m_Player
                    && (zombie.transform.position - position).GetHorizontalMagnitude() < huntingMeters)
                {
                    return true;
                }
            }
            return false;
        }

        private const byte HungerThreshold = 45;
        private bool m_RegenThresholdsLogged;

        private static void GetRegenThresholds(out uint food, out uint water)
        {
            var players = Provider.modeConfigData?.Players;
            food = players != null ? players.Health_Regen_Min_Food : 90u;
            water = players != null ? players.Health_Regen_Min_Water : 90u;
        }

        private void LogMealBlocked(float now, string reason)
        {
            if (m_Player.life.health >= 85 || now < m_NextMealBlockedLogAt)
            {
                return;
            }
            m_NextMealBlockedLogAt = now + 30f;
            BotLog(LogLevel.Information,
                "Bot quer comer/beber (vida {Health}, comida {Food}, agua {Water}) mas nao pode: {Reason}.",
                m_Player.life.health,
                m_Player.life.food,
                m_Player.life.water,
                reason);
        }

        private void TryEatOrDrink(float now)
        {
            var life = m_Player.life;
            // The game only regenerates health above these food/water levels
            // (90 on default servers), so a hurt bot tops them up like a player.
            GetRegenThresholds(out var regenFood, out var regenWater);
            if (!m_RegenThresholdsLogged)
            {
                m_RegenThresholdsLogged = true;
                BotLog(LogLevel.Information,
                    "Regeneracao de vida do servidor exige comida > {Food} e agua > {Water}.",
                    regenFood,
                    regenWater);
            }
            var wantsRegen = life.health < 85 && !life.isBleeding;
            var hungry = life.food < HungerThreshold || (wantsRegen && life.food <= regenFood);
            var thirsty = life.water < HungerThreshold || (wantsRegen && life.water <= regenWater);
            if (!hungry && !thirsty)
            {
                return;
            }
            string? blocked = null;
            var aggroedForMeal = GetNearestAggroedZombieDistance();
            // At 22:11 in the 0.1.150 test Tadeu, fleeing at 78 health with a
            // zombie 6.7m away, took out a chocolate bar, had nothing in hand
            // and was down to 13 in seconds. Only starving (under 10) eats
            // with a fight around.
            var starving = life.food < 10 || life.water < 10;
            // 0.1.0-y16: the fight is remembered 5 minutes; starving eats
            // (SkaliaBotPvpSpotY).
            if ((m_PvpTarget != null || IsPvpLeftRecently(now)) && !starving)
            {
                // 0.2.2y3 (rec/pvp15.py): no food in the players' hands in
                // their fights. 0.2.2y4 (rec/pvp17.py): nor in the minute
                // after, 1 time in 61 (Ghost drank and ate 26s after
                // trading shots with the tester, who was 1m away, 17/11 02:50).
                blocked = "luta com jogador";
            }
            else if (!starving && (aggroedForMeal < 15f || m_CachedNearestZombieDistance < 8f))
            {
                blocked = aggroedForMeal < 15f
                    ? "zumbi agrado a " + aggroedForMeal.ToString("0.#") + "m"
                    : "zumbi a " + m_CachedNearestZombieDistance.ToString("0.#") + "m";
            }
            else if (aggroedForMeal < 10f || m_CachedNearestZombieDistance < 4f)
            {
                blocked = "zumbi a " + Mathf.Min(aggroedForMeal, m_CachedNearestZombieDistance).ToString("0.#") + "m";
            }
            else if (m_ObjectiveType == ObjectiveType.Combat
                     || m_ObjectiveType == ObjectiveType.EscapeSwarm
                     || (!starving && (m_ObjectiveType == ObjectiveType.Flee || now - m_LastCombatThreatAt < 5f)))
            {
                blocked = "objetivo " + m_ObjectiveType;
            }
            else if (m_Player.equipment.isBusy)
            {
                // A held attack keeps the weapon swinging and the hands busy
                // forever: let go so the next try can equip the food.
                m_PrimaryAttackHeld = false;
                m_SecondaryAttackHeld = false;
                blocked = "maos ocupadas com " + DescribeEquipped();
            }
            if (blocked != null)
            {
                LogMealBlocked(now, blocked);
                return;
            }
            var drinkFirst = thirsty && (!hungry || life.water <= life.food);
            if (!TryFindMeal(drinkFirst, out var page, out var jar, out var meal)
                && !((drinkFirst ? hungry : thirsty) && TryFindMeal(!drinkFirst, out page, out jar, out meal)))
            {
                if (thirsty
                    && TryFindRefill(true, life.water < 30, out var refillPage, out var refillJar, out var refillAsset, out var refillType))
                {
                    m_NextTreatmentAt = now + 1f;
                    m_TreatmentEquipIssuedAt = now;
                    m_Player.equipment.ServerEquip(refillPage, refillJar.x, refillJar.y);
                    m_TreatmentIsMeal = true;
                    m_TreatmentPhase = 1;
                    m_TreatmentItemId = refillAsset.id;
                    m_TreatmentItemName = refillAsset.itemName + " (" + refillType + ")";
                    m_TreatmentPhaseSince = now;
                    m_TreatmentHealthBefore = life.health;
                    m_TreatmentBleedingBefore = life.isBleeding;
                    m_TreatmentFoodBefore = life.food;
                    m_TreatmentWaterBefore = life.water;
                    BotLog(LogLevel.Information,
                        "Bot equipando {Item} ({Type}) para beber (comida {Food}, agua {Water}).",
                        refillAsset.itemName,
                        refillType,
                        life.food,
                        life.water);
                    return;
                }
                if (thirsty && TryStartRefillErrand(m_Player.transform.position, now))
                {
                    m_NextTreatmentAt = now + 10f;
                    return;
                }
                LogMealBlocked(now, "nenhuma comida/agua utilizavel no inventario" + DescribeUnusableMeals());
                m_NextTreatmentAt = now + 10f;
                return;
            }
            m_NextTreatmentAt = now + 1f;
            m_TreatmentEquipIssuedAt = now;
            m_Player.equipment.ServerEquip(page, jar.x, jar.y);
            m_TreatmentIsMeal = true;
            m_TreatmentPhase = 1;
            m_TreatmentItemId = meal.id;
            m_TreatmentItemName = meal.itemName;
            m_TreatmentPhaseSince = now;
            m_TreatmentHealthBefore = life.health;
            m_TreatmentBleedingBefore = life.isBleeding;
            m_TreatmentFoodBefore = life.food;
            m_TreatmentWaterBefore = life.water;
            BotLog(LogLevel.Information,
                "Bot equipando {Item} para {Action} (comida {Food}, agua {Water}; qualidade {Quality}%, deve ganhar {Gain} de {Bar}).",
                meal.itemName,
                m_LastMealForWater ? "beber" : "comer",
                life.food,
                life.water,
                jar.item.quality,
                m_LastMealGain,
                m_LastMealForWater ? "agua" : "comida");
        }

        // Best item for the most urgent need. The game scales food and water
        // by the item's quality, infects below 50% quality, and for items that
        // feed at least as much as they quench (Glue 5/5, pies, sandwiches)
        // gives no more water than the food it could add: at food 100 Tadeu
        // ate two Glues for water 87 -> 87. Raw/spoiled food (virus), low
        // quality and hallucinogens (Glue, berries, red mushroom) only when
        // starving. Among the rest, the item that fills the need without
        // wasting a big meal wins.
        private bool m_LastMealForWater;
        private int m_LastMealGain;

        private float GetMealGain(ItemJar jar, ItemConsumeableAsset meal, bool water)
        {
            var life = m_Player.life;
            var quality = jar.item.quality / 100f;
            var food = Mathf.Min(Mathf.Floor(meal.food * quality), 100 - life.food);
            if (!water)
            {
                return food;
            }
            var drink = Mathf.Floor(meal.water * quality);
            if (meal.foodConstrainsWater)
            {
                drink = Mathf.Min(drink, food);
            }
            return Mathf.Min(drink, 100 - life.water);
        }

        private static bool HasMealSideEffect(ItemJar jar, ItemConsumeableAsset meal)
        {
            return meal.virus > 0 || meal.vision > 0 || jar.item.quality < 50;
        }

        private bool TryFindMeal(bool wantWater, out byte bestPage, out ItemJar bestJar, out ItemConsumeableAsset bestAsset)
        {
            bestPage = byte.MaxValue;
            bestJar = null!;
            bestAsset = null!;
            var bestScore = float.MinValue;
            var bestGain = 0f;
            var starving = m_Player.life.food < 15 || m_Player.life.water < 15;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemConsumeableAsset meal)
                        || !(meal is ItemFoodAsset || meal is ItemWaterAsset))
                    {
                        continue;
                    }
                    var sideEffect = HasMealSideEffect(jar, meal);
                    if (sideEffect && !starving)
                    {
                        continue;
                    }
                    var gain = GetMealGain(jar, meal, wantWater);
                    var full = Mathf.Floor((wantWater ? meal.water : meal.food) * (jar.item.quality / 100f));
                    var score = gain - 0.5f * Mathf.Max(0f, full - gain) - (sideEffect ? 25f : 0f);
                    // With food at 100 and water at 86 the bot ate ten eggs and
                    // vegetables for a point of water each.
                    // Not when the other bar is running out: Tadeu died of
                    // thirst at food 100 holding three drinks that fed more
                    // than they quenched.
                    if (gain < 5
                        || (wantWater && m_Player.life.food >= 95 && m_Player.life.water > 30 && meal.food > meal.water)
                        || (!wantWater && m_Player.life.water >= 95 && m_Player.life.food > 30 && meal.water > meal.food))
                    {
                        continue;
                    }
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestGain = gain;
                        bestPage = page;
                        bestJar = jar;
                        bestAsset = meal;
                    }
                }
            }
            if (bestJar != null)
            {
                m_LastMealForWater = wantWater;
                m_LastMealGain = (int)bestGain;
            }
            return bestJar != null;
        }

        private void TryRearm(float now)
        {
            var equipment = m_Player.equipment;
            if (now > m_RearmUntil
                || m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || equipment.asset is ItemMeleeAsset
                || equipment.asset is ItemGunAsset)
            {
                m_RearmPending = false;
                return;
            }
            // 0.1.169: hands stay empty away from zombies (HolsterIdleMelee);
            // 3m short of its 15m so the two never take turns.
            // 0.2.2t: that rule is from when the melee was put away between
            // fights; with it kept in hand the weapon comes back at once.
            if (!s_Settings.KeepMeleeInHand
                && !Tryhard
                && m_CachedNearestZombieDistance > MeleeHolsterZombieMeters - 3f)
            {
                m_RearmPending = false;
                return;
            }
            if (equipment.isBusy)
            {
                return;
            }
            if (equipment.asset is ItemConsumeableAsset)
            {
                // A canteen or a partly used item stays in the hands.
                equipment.dequip();
                return;
            }
            if (EnsureCombatWeapon(false, now))
            {
                m_RearmPending = false;
            }
        }

        // After a rag is used the game can put the next one in the hands; the
        // bot then walked around holding it. Any bandage, food or drink held
        // for 2s with no treatment or meal going on is put away.
        private float m_IdleConsumableSince = -1f;

        // Trips between towns were walked end to end. Travel and exploration
        // now run while stamina lasts (down to 30%, then walk back up to 70%),
        // but not with a zombie within 25m: running only draws it in.
        private const byte TravelSprintStopStamina = 30;
        private const byte TravelSprintResumeStamina = 70;
        private const float TravelSprintZombieMeters = 25f;
        private bool m_TravelSprintResting;

        private bool ShouldSprintWhileTraveling()
        {
            // 0.1.0-y17.27: the search of an area too, under the open sky
            // (the players sprinted 59-71% of the time moving outdoors; the
            // bots searching an area 1%, SkaliaBotMoveFeelY).
            if (m_ObjectiveType != ObjectiveType.Travel
                && m_ObjectiveType != ObjectiveType.Explore
                && !(m_ObjectiveType == ObjectiveType.Patrol
                     && IsOpenSkyCached(m_Player.transform.position, Time.realtimeSinceStartup)))
            {
                return false;
            }
            var stamina = m_Player.life.stamina;
            if (m_TravelSprintResting)
            {
                if (stamina < TravelSprintResumeStamina)
                {
                    return false;
                }
                m_TravelSprintResting = false;
            }
            else if (stamina <= TravelSprintStopStamina)
            {
                m_TravelSprintResting = true;
                return false;
            }
            return m_CachedNearestZombieDistance > TravelSprintZombieMeters;
        }

        // 0.1.169: the knife was carried in hand across the map after every
        // fight. 4s after the fight, with no zombie within 15m, it goes back
        // in the bag; the next fight takes it out (EnsureCombatWeapon). A gun
        // stays in hand.
        private const float MeleeHolsterSeconds = 4f;
        private const float MeleeHolsterZombieMeters = 15f;
        private float m_LastFightAt = float.NegativeInfinity;

        private void HolsterIdleMelee(float now)
        {
            if (IsFightObjective())
            {
                m_LastFightAt = now;
                return;
            }
            if (Tryhard)
            {
                // 0.2.2v (doc 13.3, item 4): the tryhard walks with the gun;
                // the knife comes out for the fight and goes back after it.
                DrawGunAfterMelee(now);
                return;
            }
            if (s_Settings.KeepMeleeInHand)
            {
                // 0.2.2: like a player, the melee stays out between fights
                // (it was put away and drawn again 2s later, doc 9.5).
                return;
            }
            var equipment = m_Player.equipment;
            if (!(equipment.asset is ItemMeleeAsset melee)
                || equipment.isBusy
                || m_TreatmentPhase != 0
                || m_PendingMeleeRaycast
                || now - m_LastFightAt < MeleeHolsterSeconds
                || m_CachedNearestZombieDistance <= MeleeHolsterZombieMeters)
            {
                return;
            }
            BotLog(LogLevel.Information,
                "Guardando {Item}: a luta acabou e nao ha zumbi a {Meters:0}m.",
                melee.itemName,
                MeleeHolsterZombieMeters);
            equipment.dequip();
        }

        private const float TryhardGunDrawSeconds = 1.5f;
        private const float TryhardGunDrawZombieMeters = 8f;
        private float m_NextGunDrawAt;

        private void DrawGunAfterMelee(float now)
        {
            var equipment = m_Player.equipment;
            if (!(equipment.asset is ItemMeleeAsset melee)
                || equipment.isBusy
                || m_TreatmentPhase != 0
                || m_PendingMeleeRaycast
                || now < m_NextGunDrawAt
                || now - m_LastFightAt < TryhardGunDrawSeconds
                || m_CachedNearestZombieDistance <= TryhardGunDrawZombieMeters
                || m_Player.stance.stance == EPlayerStance.SWIM)
            {
                return;
            }
            TryEquipKeeperGun(now, melee.itemName);
        }

        // The best gun in hand (also from empty hands). True when it was
        // asked for (or moved to a weapon slot first).
        private bool TryEquipKeeperGun(float now, string from)
        {
            if (now < m_NextGunDrawAt
                || !TryGetKeeperGun(out var page, out var jar, out var gun)
                || !IsUsableCarriedGun(page, jar, gun)
                // 0.2.2x11: a gun with no round to spare is not drawn over
                // the blade (llo took the Zubeknakov with 1 round back after
                // each fight, and the next fight began as a gun fight).
                || (m_Player.equipment.asset is ItemMeleeAsset && !HasSpareRangedShots(gun, jar.item.state)))
            {
                return false;
            }
            m_NextGunDrawAt = now + 2f;
            if (!ItemTool.checkUseable(page, jar.item.id))
            {
                return TryMoveToWeaponSlot(page, jar, gun);
            }
            m_Player.equipment.ServerEquip(page, jar.x, jar.y);
            BotLog(LogLevel.Information,
                "Guardando {From} e voltando para {Gun}: fora de luta e sem zumbi a {Meters:0}m.",
                from,
                gun.itemName,
                TryhardGunDrawZombieMeters);
            return true;
        }

        private float m_LastItemPickupAt = float.NegativeInfinity;

        private void PutAwayIdleConsumable(float now)
        {
            var equipment = m_Player.equipment;
            if (!(equipment.asset is ItemConsumeableAsset held) || equipment.isBusy)
            {
                m_IdleConsumableSince = -1f;
                return;
            }
            if (m_IdleConsumableSince < 0f)
            {
                m_IdleConsumableSince = now;
                return;
            }
            // 0.1.174: the game puts a picked-up snack or medicine straight in
            // empty hands (about 125 times in the 0.1.173 test); right after a
            // pickup it goes back at once, logged only at Debug.
            var justPicked = now - m_LastItemPickupAt < 2f;
            if (now - m_IdleConsumableSince < (justPicked ? 0.3f : 2f))
            {
                return;
            }
            m_IdleConsumableSince = -1f;
            BotLog(justPicked ? LogLevel.Debug : LogLevel.Information,
                "Bot estava com {Item} na mao sem usar; guardando e voltando para a arma.",
                held.itemName);
            equipment.dequip();
            m_RearmPending = true;
            m_RearmUntil = now + 6f;
        }

        private void StartTreatment(byte page, ItemJar jar, ItemMedicalAsset medical, PlayerLife life, bool bleeding, float now)
        {
            m_TreatmentEquipIssuedAt = now;
            // 0.1.0-y17.5: the one already in the hands is used as it is
            // (asking the game to equip the item held takes it away).
            var equipment = m_Player.equipment;
            if (!(equipment.equippedPage == page && equipment.equipped_x == jar.x && equipment.equipped_y == jar.y))
            {
                equipment.ServerEquip(page, jar.x, jar.y);
            }
            m_TreatmentIsMeal = false;
            m_TreatmentPhase = 1;
            m_TreatmentItemId = medical.id;
            m_TreatmentItemName = medical.itemName;
            m_TreatmentPhaseSince = now;
            m_TreatmentHealthBefore = life.health;
            m_TreatmentBleedingBefore = bleeding;
            m_TreatmentVirusBefore = life.virus;
            BotLog(LogLevel.Information,
                "Bot equipando {Item} para fazer curativo (vida {Health}, sangrando {Bleeding}).",
                medical.itemName,
                life.health,
                bleeding);
        }

        private void UpdateTreatment(float now)
        {
            var equipment = m_Player.equipment;
            var holding = equipment.asset != null && equipment.asset.id == m_TreatmentItemId;
            // A snack is not worth a hit: put it away as soon as a fight starts.
            if (m_TreatmentIsMeal
                && (GetNearestAggroedZombieDistance() < 10f
                    || m_PvpTarget != null
                    || m_ObjectiveType == ObjectiveType.Combat
                    || m_ObjectiveType == ObjectiveType.EscapeSwarm
                    || m_ObjectiveType == ObjectiveType.Flee))
            {
                BotLog(LogLevel.Information,
                    "Refeicao com {Item} interrompida: zumbi a {Distance:0.#}m (objetivo {Objective}).",
                    m_TreatmentItemName,
                    m_CachedNearestZombieDistance,
                    m_ObjectiveType);
                if (holding && !equipment.isBusy)
                {
                    equipment.dequip();
                }
                EndTreatment(now, 15f);
                return;
            }
            // 0.2.2y5: above the break health a bandage is not worth a man
            // in sight (players in their fights: a medical item in hand in
            // 4.9% of the rows, rec/pvp15.py; at 35 or less 10 of 15).
            if (!m_TreatmentIsMeal
                && m_PvpTarget != null
                && m_PvpVisible
                && (m_Player.life.health > PvpBreakHealth || IsPvpEnemyTooCloseToHeal(now)))
            {
                BotLog(LogLevel.Information,
                    "Curativo com {Item} interrompido: {Name} a vista, vida {Health}.",
                    m_TreatmentItemName,
                    m_PvpTarget.channel?.owner?.playerID.characterName ?? "?",
                    m_Player.life.health);
                if (holding && !equipment.isBusy)
                {
                    equipment.dequip();
                }
                EndTreatment(now, 3f);
                return;
            }
            if (!m_TreatmentIsMeal && GetNearestAggroedZombieDistance() <= 3f)
            {
                // Fighting with a rag in hand is worse than bandaging later.
                BotLog(LogLevel.Information,
                    "Curativo com {Item} interrompido: zumbi a {Distance:0.#}m.",
                    m_TreatmentItemName,
                    m_CachedNearestZombieDistance);
                if (holding && !equipment.isBusy)
                {
                    equipment.dequip();
                }
                EndTreatment(now, 2f);
                return;
            }
            KeepAwayWhileTreating(now);
            if (m_TreatmentPhase == 1)
            {
                if (!holding
                    && !equipment.isBusy
                    && now - m_TreatmentEquipIssuedAt > 1f
                    && TryFindInventoryItem(m_TreatmentItemId, out var retryPage, out var retryJar))
                {
                    // An equip request can be dropped (previous item still
                    // animating): ask again instead of giving up after 4s.
                    m_TreatmentEquipIssuedAt = now;
                    equipment.ServerEquip(retryPage, retryJar.x, retryJar.y);
                }
                if (holding && equipment.IsEquipAnimationFinished && !equipment.isBusy)
                {
                    m_TreatmentUseRequested = true;
                    m_TreatmentPhase = 2;
                    m_TreatmentPhaseSince = now;
                }
                else if (now - m_TreatmentPhaseSince > 4f)
                {
                    BotLog(LogLevel.Information,
                        "Curativo cancelado: {Item} nao foi equipado (em maos: {Current}).",
                        m_TreatmentItemName,
                        DescribeEquipped());
                    EndTreatment(now, 3f);
                }
                return;
            }
            // Use requested: wait for the packet to go out and the animation
            // to finish (the item leaves the hands once consumed).
            // 0.1.0-y17.5: with more of the same in the stack the next one
            // stays in the hands, and the wait ran its full 6s: Ghost's
            // bandage took 15 -> 27 at 13:09:26 of 18/11 and the bot only
            // saw it at 13:09:30, holding it with the tester running in. Done
            // as soon as the health or the bleeding shows it.
            var landed = m_TreatmentIsFilter
                ? m_Player.clothing.maskQuality > m_TreatmentFilterBefore
                : !m_TreatmentIsMeal
                    && (m_Player.life.health > m_TreatmentHealthBefore
                        || (m_TreatmentBleedingBefore && !m_Player.life.isBleeding));
            if (m_TreatmentUseRequested
                || (holding && !landed && now - m_TreatmentPhaseSince < 6f)
                || (equipment.isBusy && now - m_TreatmentPhaseSince < 6f))
            {
                return;
            }
            var life = m_Player.life;
            if (m_TreatmentIsFilter)
            {
                BotLog(LogLevel.Information,
                    "Radiacao: filtro {Item} usado: mascara {Before}% -> {After}% ({Filters} filtro(s) restantes).",
                    m_TreatmentItemName,
                    m_TreatmentFilterBefore,
                    m_Player.clothing.maskQuality,
                    CountFilters());
                EndTreatment(now, 2f);
                return;
            }
            if (m_TreatmentIsMeal)
            {
                BotLog(LogLevel.Information,
                    "Bot consumiu {Item}: comida {FoodBefore} -> {Food}; agua {WaterBefore} -> {Water}.",
                    m_TreatmentItemName,
                    m_TreatmentFoodBefore,
                    life.food,
                    m_TreatmentWaterBefore,
                    life.water);
                EndTreatment(now, 2f);
                return;
            }
            BotLog(LogLevel.Information,
                "Bot usou {Item}: vida {Before} -> {After}; sangrando {WasBleeding} -> {Bleeding}; imunidade {VirusBefore} -> {Virus}.",
                m_TreatmentItemName,
                m_TreatmentHealthBefore,
                life.health,
                m_TreatmentBleedingBefore,
                life.isBleeding,
                m_TreatmentVirusBefore,
                life.virus);
            EndTreatment(now, 2f);
        }

        // Eating and bandaging work on the move: with a zombie coming, walk
        // away from it while the item is used instead of standing still.
        // Distance to the nearest zombie hunting this bot; anything within 3m
        // counts too, hunting or not.
        private float GetNearestAggroedZombieDistance()
        {
            var position = m_Player.transform.position;
            var best = float.PositiveInfinity;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var distance = (zombie.transform.position - position).GetHorizontalMagnitude();
                if (distance < best
                    && ((zombie.isHunting && zombie.player == m_Player) || distance < 3f))
                {
                    best = distance;
                }
            }
            return best;
        }

        private void KeepAwayWhileTreating(float now)
        {
            if (now < m_NextTreatFleeAt || GetNearestAggroedZombieDistance() >= 25f)
            {
                return;
            }
            var position = m_Player.transform.position;
            if (m_ObjectiveType == ObjectiveType.Flee
                && (m_ObjectivePosition - position).GetHorizontalMagnitude() > 4f)
            {
                return;
            }
            m_NextTreatFleeAt = now + 1f;
            if (!TryFindLowHealthEscapePoint(position, now, out var escapePoint))
            {
                return;
            }
            m_FleeingFromPlayerName = "zumbis";
            SetObjective(ObjectiveType.Flee, escapePoint, now + 8f);
            BotLog(LogLevel.Information,
                "Se afastando de zumbi a {Distance:0.#}m enquanto usa {Item}.",
                m_CachedNearestZombieDistance,
                m_TreatmentItemName);
        }

        private bool TryFindInventoryItem(ushort id, out byte foundPage, out ItemJar foundJar)
        {
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.item != null && jar.item.id == id)
                    {
                        foundPage = page;
                        foundJar = jar;
                        return true;
                    }
                }
            }
            foundPage = byte.MaxValue;
            foundJar = null!;
            return false;
        }

        private bool IsFightObjective()
        {
            return m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || m_ObjectiveType == ObjectiveType.Flee
                || m_ObjectiveType == ObjectiveType.EscapeHazard
                || m_ObjectiveType == ObjectiveType.RepositionFire;
        }

        private void EndTreatment(float now, float cooldown)
        {
            m_TreatmentPhase = 0;
            m_TreatmentUseRequested = false;
            m_TreatmentIsFilter = false;
            m_TreatmentEndedAt = now;
            m_WeaponSwapBlockedUntil = 0f;
            m_EquipAttemptCount = 0;
            m_RearmPending = true;
            m_RearmUntil = now + cooldown + 6f;
            m_NextTreatmentAt = now + cooldown;
            m_NextWeaponSelectionAt = 0f;
        }

        private bool TryFindTreatment(bool bleeding, out byte bestPage, out ItemJar bestJar, out ItemMedicalAsset bestAsset)
        {
            bestPage = byte.MaxValue;
            bestJar = null!;
            bestAsset = null!;
            var bestScore = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemMedicalAsset medical))
                    {
                        continue;
                    }
                    var stopsBleeding = medical.bleedingModifier == ItemConsumeableAsset.Bleeding.Heal;
                    if (medical.bleedingModifier == ItemConsumeableAsset.Bleeding.Cut
                        || (bleeding && !stopsBleeding)
                        || (!bleeding && medical.health == 0))
                    {
                        continue;
                    }
                    var score = medical.health + (stopsBleeding ? 1 : 0);
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestPage = page;
                        bestJar = jar;
                        bestAsset = medical;
                    }
                }
            }
            return bestJar != null;
        }

        private bool TryFindBoneTreatment(out byte bestPage, out ItemJar bestJar, out ItemMedicalAsset bestAsset)
        {
            bestPage = byte.MaxValue;
            bestJar = null!;
            bestAsset = null!;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMedicalAsset medical
                        && medical.bonesModifier == ItemConsumeableAsset.Bones.Heal
                        && medical.bleedingModifier != ItemConsumeableAsset.Bleeding.Cut
                        && (bestAsset == null || medical.health < bestAsset.health))
                    {
                        // The least the cure takes: a Splint before a Medkit.
                        bestPage = page;
                        bestJar = jar;
                        bestAsset = medical;
                    }
                }
            }
            return bestJar != null;
        }

        private bool TryCraftMedicalOnly(float now)
        {
            EnsureMedicalRecipes();
            foreach (var blueprint in s_MedicalBlueprints!)
            {
                if (m_Player.crafting.HandleCraftRequestInternal(default, blueprint, false, true, false))
                {
                    m_NextTreatmentAt = now + 0.5f;
                    BotLog(LogLevel.Information,
                        "Bot fabricou {Item} para se curar (vida {Health}).",
                        DescribeBlueprintOutput(blueprint),
                        m_Player.life.health);
                    return true;
                }
            }
            return false;
        }

        private void TryCraftTreatment(float now)
        {
            EnsureMedicalRecipes();
            foreach (var blueprint in s_MedicalBlueprints!)
            {
                if (m_Player.crafting.HandleCraftRequestInternal(default, blueprint, false, true, false))
                {
                    m_NextTreatmentAt = now + 0.5f;
                    BotLog(LogLevel.Information,
                        "Bot fabricou {Item} para tratar ferimentos.",
                        DescribeBlueprintOutput(blueprint));
                    return;
                }
            }
            foreach (var blueprint in s_MedicalMaterialBlueprints!)
            {
                if (m_Player.crafting.HandleCraftRequestInternal(default, blueprint, false, true, false))
                {
                    m_NextTreatmentAt = now + 0.5f;
                    BotLog(LogLevel.Information,
                        "Bot rasgou {Source} e obteve {Item} para fazer bandagem.",
                        blueprint.sourceItem?.itemName ?? "item",
                        DescribeBlueprintOutput(blueprint));
                    return;
                }
            }
            // No bandage, no cloth, no spare clothes: tear what the bot is
            // wearing, like a player does.
            if (m_Player.life.isBleeding && TryTakeOffClothForBandage())
            {
                m_NextTreatmentAt = now + 0.6f;
                return;
            }
            if (m_Player.life.isBleeding && now >= m_NextNoBandageLogAt)
            {
                m_NextNoBandageLogAt = now + 20f;
                BotLog(LogLevel.Information,
                    "Bot sangrando (vida {Health}) sem bandagem, pano ou roupa para rasgar.",
                    m_Player.life.health);
            }
            m_NextTreatmentAt = now + 5f;
        }

        private bool TryTakeOffClothForBandage()
        {
            var clothing = m_Player.clothing;
            var sources = s_MedicalMaterialSourceIds!;
            var shirtUsable = clothing.shirt != 0 && sources.Contains(clothing.shirt);
            var pantsUsable = clothing.pants != 0 && sources.Contains(clothing.pants);
            if (!shirtUsable && !pantsUsable)
            {
                return false;
            }
            // Prefer the piece with fewer items in its pockets.
            var shirtItems = shirtUsable ? m_Player.inventory.getItemCount(PlayerInventory.SHIRT) : int.MaxValue;
            var pantsItems = pantsUsable ? m_Player.inventory.getItemCount(PlayerInventory.PANTS) : int.MaxValue;
            var takeShirt = shirtItems <= pantsItems;
            var asset = Assets.find(EAssetType.ITEM, takeShirt ? clothing.shirt : clothing.pants) as ItemAsset;
            if (asset == null)
            {
                return false;
            }
            BotLog(LogLevel.Information,
                "Bot sangrando sem pano: tirando {Item} ({Pockets} itens no bolso) para rasgar em bandagem.",
                asset.itemName,
                takeShirt ? shirtItems : pantsItems);
            if (takeShirt)
            {
                clothing.ReceiveSwapShirtRequest(byte.MaxValue, 0, 0);
            }
            else
            {
                clothing.ReceiveSwapPantsRequest(byte.MaxValue, 0, 0);
            }
            return true;
        }

        private void LogMedicalRecipes()
        {
            EnsureMedicalRecipes();
            var sourceNames = new List<string>();
            foreach (var id in s_MedicalMaterialSourceIds!)
            {
                if (sourceNames.Count >= 6)
                {
                    break;
                }
                if (Assets.find(EAssetType.ITEM, id) is ItemAsset asset)
                {
                    sourceNames.Add(asset.itemName);
                }
            }
            var medicalNames = new List<string>();
            foreach (var blueprint in s_MedicalBlueprints!)
            {
                var name = DescribeBlueprintOutput(blueprint);
                if (!medicalNames.Contains(name))
                {
                    medicalNames.Add(name);
                }
            }
            BotLog(LogLevel.Information,
                "Receitas de curativo: {Medical} receitas ({MedicalNames}); {Materials} receitas de pano a partir de {Sources} itens (ex.: {SourceNames}).",
                s_MedicalBlueprints!.Count,
                string.Join(", ", medicalNames),
                s_MedicalMaterialBlueprints!.Count,
                s_MedicalMaterialSourceIds!.Count,
                string.Join(", ", sourceNames));
        }

        private static string DescribeBlueprintOutput(Blueprint blueprint)
        {
            foreach (var output in blueprint.outputs)
            {
                var asset = output?.FindItemAsset();
                if (asset != null)
                {
                    return asset.itemName + (output!.amount > 1 ? " x" + output.amount : "");
                }
            }
            return "item";
        }

        private int CountInventoryItemsWithIds(HashSet<ushort> ids)
        {
            var count = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var asset = m_Player.inventory.getItem(page, index)?.GetAsset();
                    if (asset != null && ids.Contains(asset.id))
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        private bool ShouldCollectLootAsset(
            ItemAsset asset,
            bool allowRangedBeforeMelee,
            byte[]? state = null,
            byte amount = 1,
            byte quality = 100)
        {
            // 0.1.0-y17.26: a key some door of the map asks for, one of each
            // (SkaliaBotKeysY).
            if (IsMapKeyItem(asset.id))
            {
                return CountCarried(asset.id) == 0 && HasInventorySpaceFor(asset);
            }
            if (asset is ItemMeleeAsset uselessMelee && !IsUsefulMelee(uselessMelee))
            {
                return false;
            }
            if (asset is ItemGunAsset uselessGun && !IsUsefulGun(uselessGun))
            {
                return false;
            }
            if (asset is ItemMeleeAsset groundMelee)
            {
                // The first melee weapon found used to be the last: one bot
                // fought the whole 0.1.123 test with a Flashlight (21) and
                // walked past pitchforks (34) and axes. A clearly stronger one
                // replaces it; the weaker one is dropped (DropWeakerMelee).
                return HasWeaponRole(false)
                    ? MeleeHitDamage(groundMelee, quality) >= BestCarriedMeleeDamage() * MeleeUpgradeRatio
                      && HasMeleeUpgradeSpace()
                    : HasInventorySpaceFor(asset);
            }
            // 0.2.2t: a gun whose loaded magazine fits the bot's own is
            // picked up to be stripped (TryStripSpareGun).
            if (asset is ItemGunAsset stripGun && WantsGunForStrip(stripGun, state))
            {
                return HasInventorySpaceFor(asset);
            }
            if (asset is ItemGunAsset groundGun)
            {
                // Any gun filled the ranged role, even an empty one with no
                // ammo for it: 278 status lines of the 0.1.103 log read "armas
                // 1/0 carregadas" and every loaded gun found for the fire
                // zombie was refused. A gun the bot can shoot now replaces one
                // it can't.
                // 0.1.167: like the knife, a clearly better gun the bot can
                // shoot replaces a weak one (a bow with 1 arrow next to a
                // Cobra); the weaker one is dropped (DropWeakerGun).
                if (HasWeaponRole(true))
                {
                    if (state == null
                        || !(IsLoadedGun(groundGun, state) || HasMagazineFor(groundGun)))
                    {
                        return false;
                    }
                    var bestGun = BestCarriedUsableGunScore();
                    return (bestGun <= 0f || GunScore(groundGun) >= bestGun * GunUpgradeRatio)
                        && (HasInventorySpaceFor(asset) || TryFindReplaceableItem(asset, out _, out _));
                }
                return (allowRangedBeforeMelee || HasWeaponRole(false))
                    && HasInventorySpaceFor(asset);
            }
            switch (asset.type)
            {
                case EItemType.MAGAZINE:
                    // Ammo only for a gun the bot carries, and only a few.
                    // 0.2.2t: over the cap, one that pours whole into the
                    // partial ones (TryJoinAmmo) and is dropped empty.
                    return asset is ItemMagazineAsset magazine
                        && WantsMagazineRounds(magazine, amount)
                        && HasInventorySpaceFor(asset);
                case EItemType.MEDICAL:
                    // 0.1.170: Purification Tablets (5 of health) were picked up
                    // and dropped again for anything better, 13 times at
                    // Scorpion-7 in the 0.1.169 test.
                    if (!(asset is ItemMedicalAsset medicalLoot))
                    {
                        return false;
                    }
                    // x19: something against the virus when it is falling.
                    if (medicalLoot.disinfectant > 0 && IsVirusFalling() && !HasDisinfectant())
                    {
                        return HasInventorySpaceFor(asset);
                    }
                    if (MedicalValue(medicalLoot) < MedicalMinimumValue)
                    {
                        return false;
                    }
                    if (Tryhard)
                    {
                        // 0.2.2w (doc 14.3, item 1): bandages by the stock,
                        // other medicine by its own count.
                        return (IsBleedHeal(medicalLoot)
                                ? GetBandageStock() + BleedHealWorth(medicalLoot) <= BandageStockCap + 0.01f
                                : CountOtherMedical() < TryhardOtherMedicalCap)
                            && HasInventorySpaceFor(asset);
                    }
                    if (CountInventoryItems(EItemType.MEDICAL) < MaximumMedicalItems)
                    {
                        return HasInventorySpaceFor(asset);
                    }
                    // Full of rags: a dressing or a medkit takes the place of
                    // the worst one (DropExtraItems).
                    return TryFindReplaceableItem(asset, out _, out _);
                case EItemType.FOOD:
                case EItemType.WATER:
                    // Washington test: Tadeu carried three water items that
                    // gave no water (empty containers), so the cap of three
                    // was full, it never looked for a drink and died of
                    // thirst. Only what feeds or quenches counts, and an item
                    // that does neither is not picked up.
                    if (!(IsUsableConsumable(asset, true) || IsUsableConsumable(asset, false)))
                    {
                        return false;
                    }
                    // x19: under 50% it infects and gives almost nothing.
                    if (!IsGoodGroundMeal(asset, quality))
                    {
                        return false;
                    }
                    if (CountConsumableGroup(IsDrinkOnly(asset)) < MaximumFoodOrWaterItems)
                    {
                        return HasInventorySpaceFor(asset);
                    }
                    // Bag full of crackers: beans or a pizza take the place of
                    // the worst one.
                    return TryFindReplaceableItem(asset, out _, out _);
                case EItemType.REFILL:
                    // One canteen or reusable bottle to fill at rivers.
                    return !TryFindRefill(false, false, out _, out _, out _, out _)
                        && !TryFindRefill(true, true, out _, out _, out _, out _)
                        && HasInventorySpaceFor(asset);
                case EItemType.BACKPACK:
                case EItemType.VEST:
                    // A bigger backpack or vest is put on and the old one
                    // dropped (WearBetterBags).
                    // 0.2.2t: protection first, room as the tie-break.
                    return GetWornBagId(asset.type) == 0
                        || (IsBetterBagOrArmor(asset, GetWornBagId(asset.type)) && HasInventorySpaceFor(asset))
                        || WantsClothingAsMaterial(asset);
                case EItemType.SHIRT:
                case EItemType.PANTS:
                    if (GetWornBagId(asset.type) == 0)
                    {
                        return true;
                    }
                    // 0.1.0-y17.26: one radiation suit in the bag.
                    if (WantsSuitLoot(asset))
                    {
                        return true;
                    }
                    if (IsBetterBagOrArmor(asset, GetWornBagId(asset.type)) && HasInventorySpaceFor(asset))
                    {
                        return true;
                    }
                    // Clothes to tear into bandages while the stock is short.
                    return WantsClothingAsMaterial(asset);
                case EItemType.HAT:
                case EItemType.MASK:
                case EItemType.GLASSES:
                    // 0.1.169: hats, helmets, masks and glasses were left on
                    // the ground. The first one is put on; a later one only
                    // when it protects more (WearBetterHeadgear).
                    return (IsBetterHeadgear(asset) && HasInventorySpaceFor(asset))
                        || WantsClothingAsMaterial(asset);
                case EItemType.SIGHT:
                case EItemType.TACTICAL:
                case EItemType.GRIP:
                case EItemType.BARREL:
                    // 0.2.2t: a part for the bot's gun (TryFitAttachment).
                    return WantsAttachmentLoot(asset) && HasInventorySpaceFor(asset);
                case EItemType.BARRICADE:
                    // 0.2.1: one bed, to place and claim (SkaliaBotHome).
                    return WantsBedLoot(asset);
                case EItemType.FILTER:
                    // 0.1.0-y17.25: filters for the gas mask (SkaliaBotRadiationY).
                    return WantsFilterLoot(asset);
                case EItemType.SUPPLY:
                    if (IsAmmoBox(asset.id))
                    {
                        // 0.2.2t: the crate for the map's strong guns is
                        // taken before the gun; crates are joined into full
                        // ones and the log says why one in sight was left.
                        if (!WantsAmmoBox(asset, amount, out var boxWhy))
                        {
                            LogAmmoBoxRefusal(asset, boxWhy, Time.realtimeSinceStartup);
                            return false;
                        }
                        return HasInventorySpaceFor(asset);
                    }
                    // Cloth and other bandage ingredients.
                    EnsureMedicalRecipes();
                    return s_MedicalSupplyIds!.Contains(asset.id)
                        && CountInventoryItemsWithIds(s_MedicalSupplyIds) < MaximumMedicalItems
                        && (!Tryhard || IsBandageStockShort())
                        && HasInventorySpaceFor(asset);
                default:
                    // Seeds, tools, diving tanks and other items the bot can't
                    // use only fill the inventory.
                    return false;
            }
        }

        private void IgnoreLoot(uint instanceId, float until)
        {
            if (m_IgnoredLoot.Count >= 64)
            {
                var now = Time.realtimeSinceStartup;
                var expired = new List<uint>();
                foreach (var entry in m_IgnoredLoot)
                {
                    if (entry.Value <= now)
                    {
                        expired.Add(entry.Key);
                    }
                }
                foreach (var key in expired)
                {
                    m_IgnoredLoot.Remove(key);
                }
            }
            m_IgnoredLoot[instanceId] = until;
        }

        private bool IsLootIgnored(uint instanceId, float now)
        {
            return m_IgnoredLoot.TryGetValue(instanceId, out var until) && now < until;
        }

        // 0.1.0-y17.10: as the bag is, or with it in order (/sort,
        // SkaliaBotSortY).
        private bool HasInventorySpaceFor(ItemAsset asset)
        {
            return HasInventorySpaceNow(asset) || CanSortOpenRoomFor(asset);
        }

        private bool HasInventorySpaceNow(ItemAsset asset)
        {
            // Weapons go straight to an empty primary (page 0) or secondary
            // (page 1) slot before using backpack space.
            if ((asset is ItemGunAsset || asset is ItemMeleeAsset)
                && (m_Player.inventory.getItemCount(0) == 0
                    || m_Player.inventory.getItemCount(1) == 0))
            {
                return true;
            }
            return m_Player.inventory.tryFindSpace(
                asset.size_x,
                asset.size_y,
                out _,
                out _,
                out _,
                out _);
        }

        // What the bot carries that looks like food or drink but was not
        // picked, with its values, to see why.
        private string DescribeUnusableMeals()
        {
            var names = new List<string>();
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var asset = m_Player.inventory.getItem(page, index)?.GetAsset();
                    if (asset is ItemConsumeableAsset meal && (meal is ItemFoodAsset || meal is ItemWaterAsset))
                    {
                        names.Add(meal.itemName + " (comida " + meal.food + ", agua " + meal.water + ", virus " + meal.virus
                            + (meal.vision > 0 ? ", alucinogeno" : string.Empty)
                            + ", qualidade " + m_Player.inventory.getItem(page, index)!.item.quality + "%)");
                    }
                    else if (asset is ItemRefillAsset)
                    {
                        names.Add(asset.itemName + " (recipiente)");
                    }
                }
            }
            return names.Count > 0 ? "; carregando " + string.Join(", ", names) : string.Empty;
        }

        // ---- Filling a canteen ----
        // A canteen or reusable bottle is filled with the secondary button
        // aimed at river or lake water (never the sea: salty water takes
        // water away) and drunk with the primary one.
        private int m_RefillPhase;
        private Vector3 m_RefillBank;
        private Vector3 m_RefillWater;
        private Transform? m_RefillGround;
        private bool m_RefillFromObject;
        private string m_RefillSourceName = string.Empty;
        private ushort m_RefillItemId;
        private string m_RefillItemName = string.Empty;
        private float m_RefillPhaseSince;
        private float m_RefillStartedAt;
        private float m_NextRefillSearchAt;
        private int m_RefillTries;
        private bool m_RefillUseRequested;
        private const float RefillSearchMeters = 150f;

        private static ERefillWaterType RefillType(Item item)
        {
            return item.state != null && item.state.Length > 0
                ? (ERefillWaterType)item.state[0]
                : ERefillWaterType.EMPTY;
        }

        private static bool IsFilledRefill(Item item, bool allowDirty)
        {
            var type = RefillType(item);
            return type == ERefillWaterType.CLEAN || (allowDirty && type == ERefillWaterType.DIRTY);
        }

        private bool TryFindRefill(bool filled, bool allowDirty, out byte foundPage, out ItemJar foundJar, out ItemRefillAsset foundAsset, out ERefillWaterType foundType)
        {
            foundPage = byte.MaxValue;
            foundJar = null!;
            foundAsset = null!;
            foundType = ERefillWaterType.EMPTY;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemRefillAsset refill))
                    {
                        continue;
                    }
                    var type = RefillType(jar.item);
                    if (filled ? IsFilledRefill(jar.item, allowDirty) : type == ERefillWaterType.EMPTY)
                    {
                        foundPage = page;
                        foundJar = jar;
                        foundAsset = refill;
                        foundType = type;
                        return true;
                    }
                }
            }
            return false;
        }

        // The nearest fresh water within 150m with dry ground at most 3m from
        // it: where the bot stands, and the point in the water it aims at.
        private bool TryFindWaterSource(Vector3 position, out Vector3 bank, out Vector3 water, out Transform? ground)
        {
            bank = position;
            water = position;
            ground = null;
            for (var radius = 4f; radius <= RefillSearchMeters; radius += 4f)
            {
                var bestDistance = float.PositiveInfinity;
                var found = false;
                for (var angle = 0; angle < 360; angle += 15)
                {
                    var direction = Quaternion.Euler(0f, angle, 0f) * Vector3.forward;
                    var probe = position + direction * radius;
                    if (!Landscape.getWorldHeight(probe, out var bed))
                    {
                        continue;
                    }
                    probe.y = bed + 0.3f;
                    if (!WaterUtility.isPointUnderwater(probe, out WaterVolume volume)
                        || volume == null
                        || volume.waterType == ERefillWaterType.SALTY)
                    {
                        continue;
                    }
                    WaterUtility.getUnderwaterInfo(probe, out _, out var surface);
                    // Walk back toward the bot to the first dry ground.
                    var back = -direction;
                    for (var step = 0.5f; step <= 6f; step += 0.5f)
                    {
                        var dry = probe + back * step;
                        if (!Landscape.getWorldHeight(dry, out var dryY))
                        {
                            break;
                        }
                        dry.y = dryY;
                        if (WaterUtility.isPointUnderwater(dry + Vector3.up * 0.3f))
                        {
                            continue;
                        }
                        if (step > 3f || dryY - surface > 1.6f)
                        {
                            break;
                        }
                        if (!SkaliaBotUnityNavmesh.TrySnap(dry, 1.5f, out var snapped))
                        {
                            break;
                        }
                        var distance = (snapped - position).GetHorizontalMagnitude();
                        if (distance >= bestDistance)
                        {
                            break;
                        }
                        if (SkaliaBotUnityNavmesh.MapFilled && distance > 8f && !SkaliaBotUnityNavmesh.IsReachable(position, snapped))
                        {
                            break;
                        }
                        var target = snapped + direction * 1.5f;
                        target.y = surface - 0.15f;
                        if (!WaterUtility.isPointUnderwater(target))
                        {
                            break;
                        }
                        if (Physics.Raycast(target + Vector3.up * 2f, Vector3.down, out var groundHit, 40f, RayMasks.GROUND | RayMasks.GROUND2))
                        {
                            ground = groundHit.transform;
                        }
                        if (ground == null)
                        {
                            break;
                        }
                        bestDistance = distance;
                        bank = snapped;
                        water = target;
                        found = true;
                        break;
                    }
                }
                if (found)
                {
                    return true;
                }
            }
            return false;
        }

        // Washington 0.1.162: 25 searches, no fresh water volume anywhere
        // (a volume is salty unless the map marks it). Wells and pumps fill
        // a canteen with dirty water.
        private bool TryFindWaterObject(Vector3 position, out Vector3 bank, out Vector3 point, out Transform? owner, out string name)
        {
            bank = position;
            point = position;
            owner = null;
            name = string.Empty;
            if (LevelObjects.objects == null || !Regions.tryGetCoordinate(position, out var cx, out var cy))
            {
                return false;
            }
            var reach = (int)Mathf.Ceil(RefillSearchMeters / Regions.REGION_SIZE);
            var best = float.PositiveInfinity;
            var colliders = new List<Collider>();
            for (var x = Mathf.Max(0, cx - reach); x <= Mathf.Min(Regions.WORLD_SIZE - 1, cx + reach); x++)
            {
                for (var y = Mathf.Max(0, cy - reach); y <= Mathf.Min(Regions.WORLD_SIZE - 1, cy + reach); y++)
                {
                    var objects = LevelObjects.objects[x, y];
                    if (objects == null)
                    {
                        continue;
                    }
                    foreach (var levelObject in objects)
                    {
                        var transform = levelObject?.transform;
                        if (levelObject?.asset == null
                            || transform == null
                            || levelObject.asset.interactability != EObjectInteractability.WATER
                            || !(levelObject.interactable is InteractableObjectResource resource)
                            || resource.amount == 0
                            || !resource.IsRubbleNullOrAllAlive
                            || !(transform.CompareTag("Small") || transform.CompareTag("Medium") || transform.CompareTag("Large")))
                        {
                            continue;
                        }
                        var distance = (transform.position - position).GetHorizontalMagnitude();
                        if (distance > RefillSearchMeters || distance >= best)
                        {
                            continue;
                        }
                        colliders.Clear();
                        transform.GetComponentsInChildren(false, colliders);
                        Collider? body = null;
                        foreach (var collider in colliders)
                        {
                            if (!collider.isTrigger && collider.enabled)
                            {
                                body = collider;
                                break;
                            }
                        }
                        if (body == null)
                        {
                            continue;
                        }
                        // Stand about a metre out from the side facing the bot.
                        var toward = position - transform.position;
                        toward.y = 0f;
                        toward = toward.sqrMagnitude > 0.01f ? toward.normalized : Vector3.forward;
                        Vector3 standing = default;
                        var snapped = false;
                        for (var turn = 0; turn < 360 && !snapped; turn += 45)
                        {
                            var direction = Quaternion.Euler(0f, turn, 0f) * toward;
                            var edge = body.ClosestPoint(body.bounds.center + direction * (body.bounds.extents.magnitude + 2f));
                            var probe = edge + direction * 0.9f;
                            if (SkaliaBotUnityNavmesh.TrySnap(probe, 1.2f, out standing)
                                && (standing - edge).GetHorizontalMagnitude() < 2.2f
                                && (!SkaliaBotUnityNavmesh.MapFilled || distance <= 8f || SkaliaBotUnityNavmesh.IsReachable(position, standing)))
                            {
                                snapped = true;
                            }
                        }
                        if (!snapped)
                        {
                            continue;
                        }
                        best = distance;
                        bank = standing;
                        point = body.ClosestPoint(standing + Vector3.up * 1.5f);
                        owner = transform;
                        name = levelObject.asset.name;
                    }
                }
            }
            return owner != null;
        }

        private bool TryStartRefillErrand(Vector3 position, float now)
        {
            if (m_RefillPhase != 0 || now < m_NextRefillSearchAt)
            {
                return m_RefillPhase != 0;
            }
            m_NextRefillSearchAt = now + 30f;
            if (!TryFindRefill(false, false, out _, out _, out var refill, out _))
            {
                return false;
            }
            var fromObject = false;
            var sourceName = "agua doce";
            if (!TryFindWaterSource(position, out var bank, out var water, out var ground))
            {
                if (!TryFindWaterObject(position, out bank, out water, out ground, out var objectName))
                {
                    BotLog(LogLevel.Information,
                        "Bot com sede e {Item} vazio, mas sem agua doce com margem nem poco/bomba d'agua a ate {Meters:0}m.",
                        refill.itemName,
                        RefillSearchMeters);
                    m_NextRefillSearchAt = now + 60f;
                    return false;
                }
                fromObject = true;
                sourceName = objectName + " (agua suja)";
            }
            m_RefillFromObject = fromObject;
            m_RefillSourceName = sourceName;
            m_RefillPhase = 1;
            m_RefillBank = bank;
            m_RefillWater = water;
            m_RefillGround = ground;
            m_RefillItemId = refill.id;
            m_RefillItemName = refill.itemName;
            m_RefillStartedAt = now;
            m_RefillPhaseSince = now;
            m_RefillTries = 0;
            if (m_TravelActive)
            {
                m_TravelActive = false;
                m_TravelPhase = 0;
                m_TravelMeshArea = false;
            }
            BotLog(LogLevel.Information,
                "Bot com sede indo encher {Item} em {Source} em {Water} (ponto de parada a {Distance:0}m).",
                refill.itemName,
                sourceName,
                FormatPosition(water),
                (bank - position).GetHorizontalMagnitude());
            SetObjective(ObjectiveType.Explore, bank, now + 120f);
            return true;
        }

        private float GetRefillUtility()
        {
            return m_RefillPhase != 0 ? 460f : -1f;
        }

        private void EndRefill(float now, string reason, bool failed)
        {
            BotLog(LogLevel.Information,
                "Enchimento de {Item} {Result}: {Reason}.",
                m_RefillItemName,
                failed ? "abandonado" : "concluido",
                reason);
            m_RefillPhase = 0;
            m_RefillUseRequested = false;
            if (failed)
            {
                m_NextRefillSearchAt = now + 120f;
            }
            m_NextTreatmentAt = now + 0.5f;
            if (m_ObjectiveType == ObjectiveType.Explore)
            {
                ClearObjective();
            }
        }

        private BotBehaviorStatus TickRefillBehavior()
        {
            var position = m_BehaviorPosition;
            var now = m_BehaviorNow;
            if (now - m_RefillStartedAt > 150f)
            {
                EndRefill(now, "demorou mais de 150s", true);
                return BotBehaviorStatus.Failure;
            }
            var equipment = m_Player.equipment;
            if (m_RefillPhase == 1)
            {
                if ((m_RefillBank - position).GetHorizontalMagnitude() > 1.5f)
                {
                    if (m_ObjectiveType != ObjectiveType.Explore
                        || (m_ObjectivePosition - m_RefillBank).sqrMagnitude > 0.25f)
                    {
                        SetObjective(ObjectiveType.Explore, m_RefillBank, now + 120f);
                    }
                    return BotBehaviorStatus.Running;
                }
                if (!TryFindInventoryItem(m_RefillItemId, out var page, out var jar))
                {
                    EndRefill(now, "recipiente sumiu do inventario", true);
                    return BotBehaviorStatus.Failure;
                }
                ClearObjective();
                m_WeaponSwapBlockedUntil = now + 10f;
                equipment.ServerEquip(page, jar.x, jar.y);
                m_RefillPhase = 2;
                m_RefillPhaseSince = now;
                return BotBehaviorStatus.Running;
            }
            var holding = equipment.asset != null && equipment.asset.id == m_RefillItemId;
            if (m_RefillPhase == 2)
            {
                m_WeaponSwapBlockedUntil = now + 10f;
                if (holding && equipment.IsEquipAnimationFinished && !equipment.isBusy)
                {
                    m_RefillUseRequested = true;
                    m_RefillPhase = 3;
                    m_RefillPhaseSince = now;
                }
                else if (now - m_RefillPhaseSince > 5f)
                {
                    EndRefill(now, "o recipiente nao foi equipado (em maos: " + DescribeEquipped() + ")", true);
                    return BotBehaviorStatus.Failure;
                }
                return BotBehaviorStatus.Running;
            }
            // Phase 3: wait for the fill.
            m_WeaponSwapBlockedUntil = now + 10f;
            if (now - m_RefillPhaseSince < 2.5f)
            {
                return BotBehaviorStatus.Running;
            }
            if (holding && equipment.state != null && equipment.state.Length > 0
                && (ERefillWaterType)equipment.state[0] != ERefillWaterType.EMPTY)
            {
                EndRefill(now, "agora com agua " + (ERefillWaterType)equipment.state[0], false);
                return BotBehaviorStatus.Success;
            }
            if (++m_RefillTries < 3 && holding)
            {
                m_RefillUseRequested = true;
                m_RefillPhaseSince = now;
                return BotBehaviorStatus.Running;
            }
            EndRefill(now, "o servidor nao encheu depois de 3 tentativas (" + m_RefillSourceName + " em " + FormatPosition(m_RefillWater) + ", olho a " + (m_RefillWater - m_Player.look.aim.position).magnitude.ToString("0.0") + "m)", true);
            return BotBehaviorStatus.Failure;
        }

        // The 0.1.166 test picked Glue up 20 times as food: it feeds 5, makes
        // the bot hallucinate, and filled a food slot. Hallucinogens are not
        // carried or counted as food; one already in the bag is eaten only
        // when starving.
        private static bool IsUsableConsumable(ItemAsset? asset, bool water)
        {
            return asset is ItemConsumeableAsset meal
                && (meal is ItemFoodAsset || meal is ItemWaterAsset)
                && meal.vision == 0
                && (water ? meal.water : meal.food) >= 5;
        }

        // Food is anything that feeds; a drink only quenches. Corn, with
        // both, is food.
        private static bool IsDrinkOnly(ItemAsset? asset)
        {
            return IsUsableConsumable(asset, true) && !IsUsableConsumable(asset, false);
        }

        private static bool IsInConsumableGroup(ItemAsset? asset, bool drinks)
        {
            return drinks ? IsDrinkOnly(asset) : IsUsableConsumable(asset, false);
        }

        private int CountConsumableGroup(bool drinks)
        {
            var count = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    // x19: only what really feeds counts (quality 50%+).
                    if ((IsInConsumableGroup(asset, drinks) && IsGoodMealJar(jar, drinks))
                        || (drinks && asset is ItemRefillAsset && IsFilledRefill(jar!.item, true)))
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        // 0.1.169: what the bot drops is left on the ground for 10 min, so
        // no rule that disagrees with the one that dropped it picks it up again.
        private const float DroppedItemIgnoreSeconds = 600f;

        private void DropAndForget(byte page, byte x, byte y)
        {
            var before = ItemManager.instanceCount;
            m_Player.inventory.ReceiveDropItem(page, x, y);
            var after = ItemManager.instanceCount;
            if (after != before)
            {
                IgnoreLoot(after, Time.realtimeSinceStartup + DroppedItemIgnoreSeconds);
            }
        }

        private int CountUsableConsumables(bool water)
        {
            var count = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if ((IsUsableConsumable(jar?.GetAsset(), water) && IsGoodMealJar(jar, water))
                        || (water && jar?.GetAsset() is ItemRefillAsset && IsFilledRefill(jar.item, true)))
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        private int CountInventoryItems(EItemType type)
        {
            var count = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset()?.type == type)
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        // True when a carried gun accepts this magazine; carried is how many
        // magazines for the bot's guns are already in the inventory.
        private bool CountCompatibleMagazines(ItemMagazineAsset magazine, out int carried)
        {
            carried = 0;
            var compatible = false;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    if (asset is ItemGunAsset gun && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        compatible = true;
                    }
                    else if (asset is ItemMagazineAsset carriedMagazine
                             && jar!.item.amount > 0
                             && SharesCaliber(carriedMagazine.calibers, magazine.calibers))
                    {
                        carried++;
                    }
                }
            }
            if (m_Player.equipment.asset is ItemGunAsset equippedGun
                && SharesCaliber(equippedGun.magazineCalibers, magazine.calibers))
            {
                compatible = true;
            }
            return compatible;
        }

        private bool TryMoveToWeaponSlot(byte page, ItemJar jar, ItemAsset asset)
        {
            for (byte slot = 0; slot < PlayerInventory.SLOTS; slot++)
            {
                if (!asset.slot.canEquipInPage(slot) || m_Player.inventory.getItemCount(slot) > 0)
                {
                    continue;
                }
                m_Player.inventory.ReceiveDragItem(page, jar.x, jar.y, slot, 0, 0, 0);
                if (m_Player.inventory.getItemCount(slot) > 0)
                {
                    BotLog(LogLevel.Information,
                        "Bot passou {Item} da mochila para o slot {Slot} para poder empunhar.",
                        asset.itemName,
                        slot);
                    return true;
                }
            }
            return false;
        }

        private bool HasMeleeWeapon()
        {
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemMeleeAsset)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private bool CanReloadGun(ItemGunAsset gun)
        {
            return gun.allowMagazineChange && TryFindMagazineFor(gun, out _, out _);
        }

        private bool TryFindMagazineFor(ItemGunAsset gun, out byte bestPage, out ItemJar bestJar)
        {
            bestPage = byte.MaxValue;
            bestJar = null!;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMagazineAsset magazine
                        && jar.item.amount > 0
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers)
                        && (bestJar == null || jar.item.amount > bestJar.item.amount))
                    {
                        bestPage = page;
                        bestJar = jar;
                    }
                }
            }
            return bestJar != null;
        }

        // Attaches the fullest compatible magazine (arrows for bows) to the
        // equipped empty gun, the same request the client sends on reload.
        private bool TryReloadEquippedGun(ItemGunAsset gun, float now)
        {
            if (now < m_NextReloadAttemptAt)
            {
                return true;
            }
            var useableGun = m_Player.equipment.useable as UseableGun;
            if (useableGun == null
                || useableGun.isReloading
                || !m_Player.equipment.IsEquipAnimationFinished)
            {
                return useableGun != null && useableGun.isReloading;
            }
            if (useableGun.ammo >= Mathf.Max(1, gun.ammoPerShot))
            {
                // Already loaded (a shot that never left): trust the gun.
                ClearKnownEmptyGun();
                return true;
            }
            if (!gun.allowMagazineChange
                || !TryFindMagazineFor(gun, out var page, out var jar)
                || !(jar.GetAsset() is ItemMagazineAsset magazine))
            {
                return false;
            }
            m_NextReloadAttemptAt = now + 1.5f;
            useableGun.ReceiveAttachMagazine(default, page, jar.x, jar.y, magazine.hash);
            ClearKnownEmptyGun();
            BotLog(LogLevel.Information,
                "Bot recarregando {Gun} com {Magazine} ({Amount}).",
                gun.itemName,
                magazine.itemName,
                jar.item.amount);
            return true;
        }

        // In a fight an empty gun is swapped for the melee weapon, and it was
        // never reloaded afterwards: 100 status lines in the 0.1.123 test show
        // a bot with "municao 0" and 3-4 full magazines in the bag, walking
        // into the next fight with it. Like a player, reload when it's calm.
        private void TryReloadWhenSafe(float now)
        {
            if (now < m_NextSafeReloadAt)
            {
                return;
            }
            m_NextSafeReloadAt = now + 2f;
            if (m_TreatmentPhase != 0
                || m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.Flee
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || m_ObjectiveType == ObjectiveType.RepositionFire
                || m_CachedNearestZombieDistance < 10f
                || GetNearestAggroedZombieDistance() < 20f
                || m_Player.stance.stance == EPlayerStance.SWIM)
            {
                return;
            }
            var equipment = m_Player.equipment;
            if (equipment.asset is ItemGunAsset equippedGun && equipment.equippedPage < PlayerInventory.SLOTS)
            {
                if (!IsLoadedGun(equippedGun, equipment.state) && CanReloadGun(equippedGun))
                {
                    TryReloadEquippedGun(equippedGun, now);
                }
                return;
            }
            if (equipment.isBusy || !equipment.IsEquipAnimationFinished)
            {
                return;
            }
            for (byte page = 0; page < PlayerInventory.SLOTS; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemGunAsset gun
                        && !IsLoadedGun(gun, jar.item.state)
                        && CanReloadGun(gun))
                    {
                        BotLog(LogLevel.Information,
                            "Sem zumbis por perto: pegando {Gun} vazia para recarregar.",
                            gun.itemName);
                        equipment.ServerEquip(page, jar.x, jar.y);
                        return;
                    }
                }
            }
        }

        // A reload hands back the old magazine with 0 rounds. In the 0.1.103
        // log those empty magazines filled the 4-magazine quota ("armas 1/0
        // carregadas, carregadores 4" in 83 status lines), so the bot refused
        // every new magazine it walked past. Ammo boxes refill magazines, so
        // it keeps a couple of empty ones (its own gun's first) and throws
        // away the rest.
        private const int MaximumEmptyMagazinesKept = 2;

        private void DiscardEmptyMagazines(float now)
        {
            if (now < m_NextEmptyMagazineCheckAt)
            {
                return;
            }
            m_NextEmptyMagazineCheckAt = now + 2f;
            // 0.2.2t: an empty magazine is only worth its room while a
            // crate that fills it is carried (the tester: "os vazios ele joga
            // fora").
            var emptiesKept = CarriesAmmoBoxWithRounds() ? MaximumEmptyMagazinesKept : 0;
            var empties = new List<(byte Page, byte Index, bool ForCarriedGun)>();
            for (byte page = PlayerInventory.SLOTS; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMagazineAsset magazine && jar.item.amount == 0)
                    {
                        empties.Add((page, index, CountCompatibleMagazines(magazine, out _)));
                    }
                }
            }
            if (empties.Count <= emptiesKept)
            {
                return;
            }
            var discard = empties
                .OrderByDescending(empty => empty.ForCarriedGun)
                .Skip(emptiesKept)
                // Highest index first so the remaining indexes stay valid.
                .OrderByDescending(empty => empty.Index)
                .ToList();
            foreach (var empty in discard)
            {
                var name = m_Player.inventory.getItem(empty.Page, empty.Index)?.GetAsset()?.itemName;
                m_Player.inventory.removeItem(empty.Page, empty.Index);
                BotLog(LogLevel.Information,
                    "Jogou fora carregador vazio {Magazine}; guardando {Kept} vazios para caixas de municao.",
                    name,
                    MaximumEmptyMagazinesKept);
            }
        }

        private static void EnsureAmmoRecipes()
        {
            if (s_AmmoBoxRefills != null)
            {
                return;
            }
            var refills = new Dictionary<ushort, List<(ItemMagazineAsset, Blueprint)>>();
            var items = new List<ItemAsset>();
            Assets.find(items);
            foreach (var item in items)
            {
                if (!(item is ItemMagazineAsset magazine) || magazine.blueprints == null)
                {
                    continue;
                }
                foreach (var blueprint in magazine.blueprints)
                {
                    if (blueprint == null
                        || blueprint.Operation != EBlueprintOperation.FillTargetItem
                        || blueprint.supplies == null
                        || blueprint.supplies.Length != 1)
                    {
                        continue;
                    }
                    // Skip "InputItems this" (pouring one magazine into another).
                    var box = blueprint.supplies[0]?.FindItemAsset();
                    if (box == null || box.id == 0 || box is ItemMagazineAsset)
                    {
                        continue;
                    }
                    if (!refills.TryGetValue(box.id, out var list))
                    {
                        list = new List<(ItemMagazineAsset, Blueprint)>();
                        refills.Add(box.id, list);
                    }
                    list.Add((magazine, blueprint));
                }
            }
            s_AmmoBoxRefills = refills;
        }

        private bool CarriesGunFor(ItemMagazineAsset magazine)
        {
            if (m_Player.equipment.asset is ItemGunAsset equippedGun
                && SharesCaliber(equippedGun.magazineCalibers, magazine.calibers))
            {
                return true;
            }
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemGunAsset gun
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private bool IsAmmoBoxForCarriedGun(ushort itemId)
        {
            EnsureAmmoRecipes();
            if (!s_AmmoBoxRefills!.TryGetValue(itemId, out var refills))
            {
                return false;
            }
            foreach (var refill in refills)
            {
                if (CarriesGunFor(refill.Magazine))
                {
                    return true;
                }
            }
            return false;
        }

        private int CountAmmoBoxes()
        {
            EnsureAmmoRecipes();
            var count = 0;
            for (byte page = PlayerInventory.SLOTS; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar != null && jar.item.amount > 0 && s_AmmoBoxRefills!.ContainsKey(jar.item.id))
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        // Pours an ammo box into the magazines of the bot's guns, the same
        // craft a player does from the Ammunition tab. The game picks a
        // magazine that isn't full and moves only what fits.
        private void TryRefillMagazines(float now)
        {
            if (now < m_NextMagazineRefillAt)
            {
                return;
            }
            m_NextMagazineRefillAt = now + 1f;
            EnsureAmmoRecipes();
            for (byte page = PlayerInventory.SLOTS; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var box = m_Player.inventory.getItem(page, index);
                    if (box == null
                        || box.item.amount == 0
                        || !s_AmmoBoxRefills!.TryGetValue(box.item.id, out var refills))
                    {
                        continue;
                    }
                    foreach (var refill in refills)
                    {
                        if (!CarriesGunFor(refill.Magazine)
                            || !HasPartialMagazine(refill.Magazine))
                        {
                            continue;
                        }
                        var boxName = box.GetAsset()?.itemName;
                        var before = box.item.amount;
                        if (m_Player.crafting.HandleCraftRequestInternal(default, refill.Recipe, false, true, false))
                        {
                            BotLog(LogLevel.Information,
                                "Encheu {Magazine} com {Box} (caixa tinha {Before}).",
                                refill.Magazine.itemName,
                                boxName,
                                before);
                            // One craft per pass: the inventory just changed.
                            return;
                        }
                    }
                }
            }
        }

        private bool HasPartialMagazine(ItemMagazineAsset magazine)
        {
            for (byte page = PlayerInventory.SLOTS; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar != null && jar.item.id == magazine.id && jar.item.amount < magazine.amount)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private bool HasMagazineFor(ItemGunAsset gun)
        {
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMagazineAsset magazine
                        && jar.item.amount > 0
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private static bool SharesCaliber(ushort[]? gunCalibers, ushort[]? magazineCalibers)
        {
            if (gunCalibers == null || magazineCalibers == null)
            {
                return false;
            }
            foreach (var gunCaliber in gunCalibers)
            {
                foreach (var magazineCaliber in magazineCalibers)
                {
                    if (gunCaliber == magazineCaliber)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private const float MeleeUpgradeRatio = 1.25f;

        private static float MeleeDamage(ItemMeleeAsset melee)
        {
            return melee.zombieDamageMultiplier != null ? melee.zombieDamageMultiplier.damage : 0f;
        }

        private float BestCarriedMeleeDamage()
        {
            var best = 0f;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMeleeAsset melee)
                    {
                        // 0.2.2y: with its wear (a worn knife hit for 26).
                        best = Mathf.Max(best, MeleeHitDamage(melee, jar.item.quality));
                    }
                }
            }
            return best;
        }

        // Room for the better weapon: anywhere a weapon fits now, or the slot
        // the weaker one leaves once dropped.
        private bool HasMeleeUpgradeSpace()
        {
            for (byte page = 0; page < PlayerInventory.SLOTS; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemMeleeAsset)
                    {
                        return true;
                    }
                }
            }
            return m_Player.inventory.getItemCount(0) == 0 || m_Player.inventory.getItemCount(1) == 0;
        }

        private float m_NextMeleeTidyAt;

        // Two melee weapons: keep the strongest, drop the rest, so the weapon
        // pick (first melee found) takes the good one and it gets a slot.
        private void DropWeakerMelee(float now)
        {
            if (now < m_NextMeleeTidyAt || m_TreatmentPhase != 0)
            {
                return;
            }
            m_NextMeleeTidyAt = now + 1f;
            byte bestPage = byte.MaxValue, bestX = 0, bestY = 0;
            var best = -1f;
            var count = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemMeleeAsset melee)
                    {
                        count++;
                        if (MeleeHitDamage(melee, jar.item.quality) > best)
                        {
                            best = MeleeHitDamage(melee, jar.item.quality);
                            bestPage = page;
                            bestX = jar.x;
                            bestY = jar.y;
                        }
                    }
                }
            }
            if (count < 2)
            {
                return;
            }
            var equipment = m_Player.equipment;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemMeleeAsset melee)
                        || (page == bestPage && jar.x == bestX && jar.y == bestY))
                    {
                        continue;
                    }
                    if (equipment.equippedPage == page && equipment.equipped_x == jar.x && equipment.equipped_y == jar.y)
                    {
                        if (equipment.isBusy)
                        {
                            return;
                        }
                        equipment.dequip();
                    }
                    BotLog(LogLevel.Information,
                        "Trocando {Old} ({OldDamage:0}) por uma arma melhor ({Best:0} de dano); largando a mais fraca.",
                        melee.itemName,
                        MeleeHitDamage(melee, jar.item.quality),
                        best);
                    DropAndForget(page, jar.x, jar.y);
                    return;
                }
            }
        }

        // ---- 0.1.167: better items replace worse ones, like the knife ----

        private const float GunUpgradeRatio = 1.3f;
        private const float MedicalUpgradeMargin = 5f;
        private const float MedicalMinimumValue = 10f;
        private const float MealUpgradeRatio = 1.5f;
        private float m_NextGunTidyAt;
        private float m_NextBagTidyAt;
        private float m_NextExtraTidyAt;

        // 0.2.2c: damage per shot on a player, rounds per magazine (up to
        // 30), fire rate and reach (up to 200m). The zombie damage it used
        // before is 99 on nearly every gun of the game (Viper, Colt, AK,
        // Heartbreaker, Eaglefire): a Viper was worth a Heartbreaker and no
        // gun was ever an upgrade. Now about: Colt 140, Viper 300, AK 640,
        // Heartbreaker and Eaglefire 690, Matamorez 910.
        private static float GunScore(ItemGunAsset gun)
        {
            var damage = gun.playerDamageMultiplier != null ? gun.playerDamageMultiplier.damage : 0f;
            if (damage <= 0f)
            {
                damage = gun.zombieDamageMultiplier != null ? gun.zombieDamageMultiplier.damage : 0f;
            }
            var rounds = Mathf.Clamp(gun.ammoMax, 1, 30);
            // 0.2.2x1 (doc 16.3, item 1): the rate the bot really gets. The
            // cap at 5/s made a Heartbreaker (Auto, 6.25/s) equal to an
            // Eaglefire (Semi and burst only) and the bots stripped and
            // dropped the Heartbreaker and the PDW 6 times in one test. With
            // the trigger held an Auto gun fires at its own rate; Semi or
            // burst is a click per shot, about 5.5/s at best. Auto counts
            // 1.3 times on top (the gun every player took to the Mega).
            var rate = gun.CalculateRoundsPerSecond();
            rate = gun.hasAuto ? Mathf.Clamp(rate, 0.5f, 12f) : Mathf.Clamp(rate, 0.5f, 5.5f);
            var reach = Mathf.Sqrt(Mathf.Clamp(gun.range, 25f, 200f) / 100f);
            return damage * Mathf.Sqrt(rounds) * Mathf.Sqrt(rate) * reach * (gun.hasAuto ? 1.3f : 1f);
        }

        // 0.2.2c: a gun the players take to a Mega: the assault rifles
        // (AK, Heartbreaker, Eaglefire, Maplestrike), the Matamorez, the
        // Desert Falcon, the Grizzly.
        private const float MegaGunScore = 430f;

        private bool IsUsableCarriedGun(byte page, ItemJar jar, ItemGunAsset gun)
        {
            var equipment = m_Player.equipment;
            var loaded = equipment.equippedPage == page && equipment.equipped_x == jar.x && equipment.equipped_y == jar.y
                ? IsEquippedGunLoaded(gun)
                : !IsKnownEmptyGunSlot(page, jar.x, jar.y) && IsLoadedGun(gun, jar.item.state);
            return loaded || CanReloadGun(gun);
        }

        private float BestCarriedUsableGunScore()
        {
            var best = 0f;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (jar?.GetAsset() is ItemGunAsset gun
                        && IsUsableCarriedGun(page, jar, gun)
                        && CanBecomeHoldable(page, gun))
                    {
                        best = Mathf.Max(best, GunScore(gun));
                    }
                }
            }
            return best;
        }

        private static float MedicalValue(ItemMedicalAsset medical)
        {
            if (medical.bleedingModifier == ItemConsumeableAsset.Bleeding.Cut)
            {
                return -1f;
            }
            return medical.health
                + (medical.bleedingModifier == ItemConsumeableAsset.Bleeding.Heal ? 10f : 0f)
                + (medical.bonesModifier == ItemConsumeableAsset.Bones.Heal ? 10f : 0f);
        }

        // Food plus water, a third for raw food and hallucinogens.
        private static float MealValue(ItemConsumeableAsset meal)
        {
            var value = (float)(meal.food + meal.water);
            return meal.virus > 0 || meal.vision > 0 ? value / 3f : value;
        }

        // The carried item a ground item would replace: the weakest of the
        // same kind, when the ground one is clearly better.
        private bool TryFindReplaceableItem(ItemAsset groundAsset, out byte foundPage, out ItemJar foundJar, byte groundQuality = 100)
        {
            foundPage = byte.MaxValue;
            foundJar = null!;
            var groundIsDrink = IsUsableConsumable(groundAsset, true) && !IsUsableConsumable(groundAsset, false);
            var worst = float.MaxValue;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    float value;
                    if (groundAsset is ItemGunAsset && asset is ItemGunAsset carriedGun)
                    {
                        value = IsUsableCarriedGun(page, jar!, carriedGun) ? GunScore(carriedGun) : 0f;
                    }
                    else if (groundAsset is ItemMeleeAsset && asset is ItemMeleeAsset carriedMelee)
                    {
                        value = MeleeHitDamage(carriedMelee, jar!.item.quality);
                    }
                    else if (groundAsset is ItemMedicalAsset && asset is ItemMedicalAsset carriedMedical)
                    {
                        value = MedicalValue(carriedMedical);
                    }
                    else if ((groundAsset.type == EItemType.FOOD || groundAsset.type == EItemType.WATER)
                             && asset is ItemConsumeableAsset carriedMeal
                             && IsInConsumableGroup(carriedMeal, groundIsDrink)
                             && IsGoodMealJar(jar, groundIsDrink))
                    {
                        value = MealValue(carriedMeal);
                    }
                    else
                    {
                        continue;
                    }
                    if (!CanSpotTakeItem(page, jar!, asset!, groundAsset))
                    {
                        continue;
                    }
                    if (value < worst)
                    {
                        worst = value;
                        foundPage = page;
                        foundJar = jar!;
                    }
                }
            }
            if (foundJar == null)
            {
                return false;
            }
            switch (groundAsset)
            {
                case ItemGunAsset groundGun:
                    return GunScore(groundGun) >= Mathf.Max(worst, 1f) * GunUpgradeRatio;
                case ItemMeleeAsset groundMelee:
                    return MeleeHitDamage(groundMelee, groundQuality) >= worst * MeleeUpgradeRatio;
                case ItemMedicalAsset groundMedical:
                    return MedicalValue(groundMedical) >= worst + MedicalUpgradeMargin;
                case ItemConsumeableAsset groundMeal:
                    return MealValue(groundMeal) >= worst * MealUpgradeRatio + 10f;
                default:
                    return false;
            }
        }

        // 0.1.0-y17.10 (test of 18/11, 18:37:49): AlemaoGamer, a Butterfly
        // Knife in the primary slot and the Cobra in the secondary, dropped
        // the Cobra for a Sabertooth on the ground; the secondary slot
        // takes no rifle and the bag had no room, the pickup failed and it
        // was left with the knife in the middle of the fight with the tester.
        // The item given up has to leave a place the new one goes into: a
        // weapon slot that takes it, or in the bag a cell block it fits
        // (either way round).
        private static bool CanSpotTakeItem(byte page, ItemJar jar, ItemAsset carried, ItemAsset ground)
        {
            if (page < PlayerInventory.SLOTS)
            {
                return ground.slot.canEquipInPage(page);
            }
            var width = jar.rot % 2 == 0 ? carried.size_x : carried.size_y;
            var height = jar.rot % 2 == 0 ? carried.size_y : carried.size_x;
            return (ground.size_x <= width && ground.size_y <= height)
                || (ground.size_y <= width && ground.size_x <= height);
        }

        // No room for the better item: drop the one it replaces first, at the
        // bot's feet. If the pickup then fails, the old one is still there.
        private void MakeRoomForUpgrade(ItemData loot)
        {
            if (!(Assets.find(EAssetType.ITEM, loot.item.id) is ItemAsset asset)
                || asset is ItemBagAsset
                || HasInventorySpaceNow(asset)
                || !TryFindReplaceableItem(asset, out var page, out var jar, loot.item.quality))
            {
                return;
            }
            var equipment = m_Player.equipment;
            if (equipment.equippedPage == page && equipment.equipped_x == jar.x && equipment.equipped_y == jar.y)
            {
                if (equipment.isBusy)
                {
                    return;
                }
                equipment.dequip();
            }
            BotLog(LogLevel.Information,
                "Sem espaco para {New}: largando {Old} para pegar o melhor.",
                asset.itemName,
                jar.GetAsset()?.itemName ?? "item");
            m_Player.inventory.ReceiveDropItem(page, jar.x, jar.y);
        }

        // Two guns: keep the best one the bot can shoot; a usable spare close
        // to it stays as backup, anything clearly worse or with no ammo for
        // it goes. Then magazines that fit no carried gun go too.
        private void DropWeakerGun(float now)
        {
            if (now < m_NextGunTidyAt || m_TreatmentPhase != 0 || IsFightObjective() || m_Player.equipment.isBusy)
            {
                return;
            }
            m_NextGunTidyAt = now + 1f;
            var best = BestCarriedUsableGunScore();
            var guns = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemGunAsset)
                    {
                        guns++;
                    }
                }
            }
            if (guns >= 2 && best > 0f)
            {
                for (byte page = 0; page < PlayerInventory.STORAGE; page++)
                {
                    var itemCount = m_Player.inventory.getItemCount(page);
                    for (byte index = 0; index < itemCount; index++)
                    {
                        var jar = m_Player.inventory.getItem(page, index);
                        if (!(jar?.GetAsset() is ItemGunAsset gun))
                        {
                            continue;
                        }
                        // 0.1.175: a loaded spare in the bag is usable again
                        // (0.1.174 counted it only when it could take a slot,
                        // and dropped a second Viper with its magazines). The
                        // best score counts a bag gun that can take a slot,
                        // also from a clearly weaker gun (ArrangeWeaponSlots).
                        var usable = IsUsableCarriedGun(page, jar, gun);
                        var score = GunScore(gun);
                        if (usable && score * GunUpgradeRatio > best)
                        {
                            continue;
                        }
                        // 0.1.0-y16.1: not for a better gun short of rounds
                        // (SkaliaBotPvpStableY).
                        if (usable && !IsBestGunStocked(page, jar, gun, best))
                        {
                            continue;
                        }
                        // 0.1.168: thigas dropped an empty Eaglefire (990) for
                        // a Nailgun (230), then picked up another Eaglefire.
                        // An empty gun better than the one with ammo is kept
                        // for the magazines it may find; it goes only when the
                        // room is needed (MakeRoomForUpgrade).
                        if (!usable && score > best)
                        {
                            continue;
                        }
                        // 0.2.2t: its magazine fits the bot's gun: kept until
                        // the strip takes it out (TryStripSpareGun).
                        if (IsStripCandidate(jar))
                        {
                            continue;
                        }
                        var equipment = m_Player.equipment;
                        if (equipment.equippedPage == page && equipment.equipped_x == jar.x && equipment.equipped_y == jar.y)
                        {
                            equipment.dequip();
                        }
                        if (usable)
                        {
                            BotLog(LogLevel.Information,
                                "Trocando {Old} ({OldScore:0}) por uma arma de fogo melhor ({Best:0}); largando a pior.",
                                gun.itemName,
                                score,
                                best);
                        }
                        else
                        {
                            BotLog(LogLevel.Information,
                                "Largando {Old} ({OldScore:0}, sem municao): ja carrega uma arma igual ou melhor com municao ({Best:0}).",
                                gun.itemName,
                                score,
                                best);
                        }
                        DropAndForget(page, jar.x, jar.y);
                        return;
                    }
                }
            }
            if (guns == 0)
            {
                return;
            }
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    if (!(jar?.GetAsset() is ItemMagazineAsset magazine) || FitsCarriedGun(magazine))
                    {
                        continue;
                    }
                    BotLog(LogLevel.Information,
                        "Largando {Magazine}: nao serve em nenhuma arma que o bot carrega.",
                        magazine.itemName);
                    DropAndForget(page, jar.x, jar.y);
                    return;
                }
            }
        }

        private bool FitsCarriedGun(ItemMagazineAsset magazine)
        {
            var equipment = m_Player.equipment;
            if (equipment.asset is ItemGunAsset held && SharesCaliber(held.magazineCalibers, magazine.calibers))
            {
                return true;
            }
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    if (m_Player.inventory.getItem(page, index)?.GetAsset() is ItemGunAsset gun
                        && SharesCaliber(gun.magazineCalibers, magazine.calibers))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private ushort GetWornBagId(EItemType type)
        {
            var clothing = m_Player.clothing;
            switch (type)
            {
                case EItemType.BACKPACK:
                    return clothing.backpack;
                case EItemType.VEST:
                    return clothing.vest;
                case EItemType.SHIRT:
                    return clothing.shirt;
                case EItemType.PANTS:
                    return clothing.pants;
                default:
                    return 0;
            }
        }

        // Bigger in both directions, so nothing in the old one is pushed out.
        private static bool IsBiggerBag(ItemAsset asset, ushort wornId)
        {
            if (!(asset is ItemBagAsset bag))
            {
                return false;
            }
            if (!(Assets.find(EAssetType.ITEM, wornId) is ItemBagAsset worn))
            {
                return bag.width * bag.height > 0;
            }
            // 0.2.2x11 (the tester): more room wins whatever the shape (a bot kept
            // Firefighter Bottom 5x2 over Military Bottom 4x3); what does not
            // fit the new shape is repacked first (TryRepackForWear).
            return bag.width * bag.height > worn.width * worn.height;
        }

        private static string DescribeBagSize(ItemAsset? asset)
        {
            return asset is ItemBagAsset bag ? bag.width + "x" + bag.height : "0x0";
        }

        // A bigger backpack, vest, shirt or pants in the bag is put on; the old
        // one comes back to the inventory and is dropped on the next pass. A
        // shirt or pants is only swapped while one is worn: the bot takes its
        // shirt off to tear it into bandages and must not put it back on.
        private void WearBetterBags(float now)
        {
            if (now < m_NextBagTidyAt
                || m_TreatmentPhase != 0
                || IsFightObjective()
                || m_Player.equipment.isBusy
                || m_Player.life.isBleeding)
            {
                return;
            }
            m_NextBagTidyAt = now + (Tryhard ? 0.5f : 1.5f);
            // 0.1.0-y17.26: the radiation suit (SkaliaBotRadiationY).
            var suitUp = IsSuitUpWanted();
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    if (asset == null
                        || !(asset.type == EItemType.BACKPACK || asset.type == EItemType.VEST
                             || asset.type == EItemType.SHIRT || asset.type == EItemType.PANTS))
                    {
                        continue;
                    }
                    var wornId = GetWornBagId(asset.type);
                    var isClothes = asset.type == EItemType.SHIRT || asset.type == EItemType.PANTS;
                    var suitDecision = isClothes ? GetSuitWearDecision(asset, wornId, suitUp) : 0;
                    if (suitDecision < 0)
                    {
                        continue;
                    }
                    var forceSuit = suitDecision > 0;
                    // 0.2.2t: by protection first (IsBetterBagOrArmor), and a
                    // bot with no shirt or pants puts one on again: the spare
                    // clothes are the bandages now, not the ones it wears.
                    if (forceSuit || IsBetterBagOrArmor(asset, wornId) || (wornId == 0 && isClothes))
                    {
                        // 0.2.2x11: a repack that failed is tried again in 30s.
                        if (m_WearRepackFailedUntil.TryGetValue(asset.id, out var repackRetry) && now < repackRetry)
                        {
                            continue;
                        }
                        var worn = Assets.find(EAssetType.ITEM, wornId) as ItemAsset;
                        BotLog(LogLevel.Information,
                            "Vestindo {New} ({NewSize}) no lugar de {Old} ({OldSize}).",
                            asset.itemName,
                            DescribeWear(asset),
                            worn?.itemName ?? "nada",
                            DescribeWear(worn));
                        if (asset is ItemBagAsset smallerBag
                            && worn is ItemBagAsset wornBag
                            && (smallerBag.width < wornBag.width || smallerBag.height < wornBag.height))
                        {
                            // 0.2.2x11: the whole bag repacked so nothing
                            // lies outside the new shape; with no such
                            // packing a piece that only holds more is left.
                            var repack = TryRepackForWear(GetBagPage(asset.type), smallerBag, wornBag, jar!, now, out var newPage, out var newJar);
                            if (repack == WearRepack.Done)
                            {
                                page = newPage;
                                jar = newJar;
                            }
                            else if (repack == WearRepack.Later
                                     || (!forceSuit
                                         && !(asset is ItemClothingAsset newGear && worn is ItemClothingAsset oldGear
                                              && newGear.armor < oldGear.armor - 0.04f)))
                            {
                                continue;
                            }
                            if (repack != WearRepack.Done)
                            {
                                var kept = MoveItemsOutOfPage(GetBagPage(asset.type), jar!);
                                BotLog(LogLevel.Information,
                                    "{New} tem menos espaco que {Old}: {Moved} item(ns) passados para os outros bolsos antes da troca.",
                                    asset.itemName,
                                    worn.itemName,
                                    kept);
                            }
                        }
                        var clothing = m_Player.clothing;
                        switch (asset.type)
                        {
                            case EItemType.BACKPACK:
                                clothing.ReceiveSwapBackpackRequest(page, jar!.x, jar.y);
                                break;
                            case EItemType.VEST:
                                clothing.ReceiveSwapVestRequest(page, jar!.x, jar.y);
                                break;
                            case EItemType.SHIRT:
                                clothing.ReceiveSwapShirtRequest(page, jar!.x, jar.y);
                                break;
                            default:
                                clothing.ReceiveSwapPantsRequest(page, jar!.x, jar.y);
                                break;
                        }
                        return;
                    }
                    if (wornId == 0)
                    {
                        continue;
                    }
                    // 0.2.2t: the piece that lost is torn into bandages on
                    // the next pass of the craft (TryCraftBandages); it is
                    // only dropped with the stock full or nothing to tear.
                    if (IsTearable(asset) && IsBandageStockShort())
                    {
                        continue;
                    }
                    BotLog(LogLevel.Information,
                        "Largando {Item} ({Size}): ja veste {Worn} ({WornSize}) e o estoque de curativo esta cheio ou a peca nao rasga.",
                        asset.itemName,
                        DescribeWear(asset),
                        (Assets.find(EAssetType.ITEM, wornId) as ItemAsset)?.itemName ?? "outro",
                        DescribeWear(Assets.find(EAssetType.ITEM, wornId) as ItemAsset));
                    DropAndForget(page, jar!.x, jar.y);
                    return;
                }
            }
        }

        private ushort GetWornHeadgearId(EItemType type)
        {
            var clothing = m_Player.clothing;
            switch (type)
            {
                case EItemType.HAT:
                    return clothing.hat;
                case EItemType.MASK:
                    return clothing.mask;
                case EItemType.GLASSES:
                    return clothing.glasses;
                default:
                    return 0;
            }
        }

        // Armor is what a hit still does: 0.8 takes 20% off a blow to the
        // head. Nothing that slows the bot down.
        private bool IsBetterHeadgear(ItemAsset asset)
        {
            if (!(asset is ItemClothingAsset gear) || gear.movementSpeedMultiplier < 0.99f)
            {
                return false;
            }
            // 0.2.2x (doc 15.2, item 11): the tryhard wears on the head only
            // what protects or sees at night, even on an empty head.
            if (Tryhard && !IsUsefulHeadgear(gear))
            {
                return false;
            }
            var wornId = GetWornHeadgearId(asset.type);
            if (wornId == 0)
            {
                return true;
            }
            // 0.1.0-y17.25: the gas mask on a map with deadzones.
            var maskOrder = wornId == asset.id
                ? 0
                : RadiationMaskOrder(gear, Assets.find(EAssetType.ITEM, wornId) as ItemClothingAsset);
            if (maskOrder != 0)
            {
                return maskOrder > 0;
            }
            return wornId != asset.id
                && Assets.find(EAssetType.ITEM, wornId) is ItemClothingAsset worn
                && gear.armor < worn.armor - 0.04f;
        }

        private static float HeadProtection(ItemClothingAsset? gear)
        {
            return gear == null ? 0f : Mathf.Max(0f, (1f - gear.armor) * 100f);
        }

        private float m_NextHeadgearTidyAt;

        // A hat, mask or glasses in the bag: put on when the slot is empty or
        // it protects more; otherwise dropped (the old one comes back to the
        // bag after a swap and goes on the next pass).
        private void WearBetterHeadgear(float now)
        {
            if (now < m_NextHeadgearTidyAt
                || m_TreatmentPhase != 0
                || IsFightObjective()
                || m_Player.equipment.isBusy)
            {
                return;
            }
            m_NextHeadgearTidyAt = now + (Tryhard ? 0.5f : 1.5f);
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    if (jar == null
                        || asset == null
                        || !(asset.type == EItemType.HAT || asset.type == EItemType.MASK || asset.type == EItemType.GLASSES))
                    {
                        continue;
                    }
                    var worn = Assets.find(EAssetType.ITEM, GetWornHeadgearId(asset.type)) as ItemClothingAsset;
                    if (IsBetterHeadgear(asset))
                    {
                        BotLog(LogLevel.Information,
                            "Vestindo {New} na cabeca (protecao {Armor:0}%) no lugar de {Old} ({OldArmor:0}%).",
                            asset.itemName,
                            HeadProtection(asset as ItemClothingAsset),
                            worn?.itemName ?? "nada",
                            HeadProtection(worn));
                        var clothing = m_Player.clothing;
                        switch (asset.type)
                        {
                            case EItemType.HAT:
                                clothing.ReceiveSwapHatRequest(page, jar.x, jar.y);
                                break;
                            case EItemType.MASK:
                                clothing.ReceiveSwapMaskRequest(page, jar.x, jar.y);
                                break;
                            default:
                                clothing.ReceiveSwapGlassesRequest(page, jar.x, jar.y);
                                break;
                        }
                        return;
                    }
                    if (IsTearable(asset) && IsBandageStockShort())
                    {
                        // 0.2.2t: torn into bandages (TryCraftBandages).
                        continue;
                    }
                    BotLog(LogLevel.Information,
                        "Largando {Item} ({Armor:0}%): ja usa {Worn} ({WornArmor:0}%) na cabeca.",
                        asset.itemName,
                        HeadProtection(asset as ItemClothingAsset),
                        worn?.itemName ?? "outro",
                        HeadProtection(worn));
                    DropAndForget(page, jar.x, jar.y);
                    return;
                }
            }
        }

        // An upgrade picked up with room to spare leaves one item over the cap:
        // the worst medical item, food or drink goes.
        private void DropExtraItems(float now)
        {
            if (now < m_NextExtraTidyAt || m_TreatmentPhase != 0 || IsFightObjective())
            {
                return;
            }
            m_NextExtraTidyAt = now + 1f;
            if (Tryhard)
            {
                // 0.2.2w (doc 14.3, item 1): the count of 6 medical items
                // took the rags too. 5 Bandages and 2 Rags (stock 6) were 7
                // items: a Rag went, the stock fell to 5.5, a uniform was
                // picked up to tear, and so on (57 uniforms in 32 min).
                if (GetBleedHealStock() > BandageStockCap + 0.01f)
                {
                    DropWorstCarried(jarAsset => jarAsset is ItemMedicalAsset medical && IsBleedHeal(medical)
                        ? MedicalValue(medical)
                        : (float?)null);
                    return;
                }
                if (CountOtherMedical() > TryhardOtherMedicalCap)
                {
                    DropWorstCarried(jarAsset => jarAsset is ItemMedicalAsset medical && !IsBleedHeal(medical)
                        ? MedicalValue(medical)
                        : (float?)null);
                    return;
                }
            }
            else if (CountInventoryItems(EItemType.MEDICAL) > MaximumMedicalItems)
            {
                DropWorstCarried(jarAsset => jarAsset is ItemMedicalAsset medical ? MedicalValue(medical) : (float?)null);
                return;
            }
            // 0.1.169: the same groups as the pickup (ShouldCollectLootAsset).
            // Corn has food and water: it counted as food to be picked up and
            // as a drink to be dropped, and Tadeu picked up and dropped the
            // same corn four times.
            foreach (var drink in new[] { false, true })
            {
                if (CountConsumableGroup(drink) > MaximumFoodOrWaterItems)
                {
                    DropWorstCarried(jarAsset => IsInConsumableGroup(jarAsset, drink)
                        ? MealValue((ItemConsumeableAsset)jarAsset!)
                        : (float?)null);
                    return;
                }
            }
        }

        private void DropWorstCarried(System.Func<ItemAsset?, float?> valueOf)
        {
            byte worstPage = byte.MaxValue;
            ItemJar? worstJar = null;
            var worst = float.MaxValue;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var itemCount = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < itemCount; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var value = valueOf(jar?.GetAsset());
                    if (value.HasValue && value.Value < worst)
                    {
                        worst = value.Value;
                        worstPage = page;
                        worstJar = jar;
                    }
                }
            }
            if (worstJar == null)
            {
                return;
            }
            var equipment = m_Player.equipment;
            if (equipment.equippedPage == worstPage && equipment.equipped_x == worstJar.x && equipment.equipped_y == worstJar.y)
            {
                if (equipment.isBusy)
                {
                    return;
                }
                equipment.dequip();
            }
            BotLog(LogLevel.Information,
                "Largando {Item}: pegou um melhor e passou do limite que carrega.",
                worstJar.GetAsset()?.itemName ?? "item");
            DropAndForget(worstPage, worstJar.x, worstJar.y);
        }

        private bool HasWeaponRole(bool ranged)
        {
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                for (byte index = 0;
                     index < m_Player.inventory.getItemCount(page);
                     index++)
                {
                    var asset = m_Player.inventory.getItem(page, index)?.GetAsset();
                    if (ranged
                            ? asset is ItemGunAsset rangedGun && IsUsefulGun(rangedGun)
                            : asset is ItemMeleeAsset roleMelee && IsUsefulMelee(roleMelee))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private bool HasCompleteWeaponRoles()
        {
            return HasWeaponRole(false) && HasWeaponRole(true);
        }

        // Every live zombie, not only the perceived ones: right after a
        // respawn the bot has seen none yet, and ran back unarmed to its own
        // body where the horde that killed it was still standing.
        private void CollectZombiesNear(Vector3 center, float radius)
        {
            m_UnarmedLootZombies.Clear();
            if (ZombieManager.regions == null)
            {
                return;
            }
            foreach (var region in ZombieManager.regions)
            {
                if (region?.zombies == null)
                {
                    continue;
                }
                foreach (var zombie in region.zombies)
                {
                    if (zombie != null
                        && !zombie.isDead
                        && (zombie.transform.position - center).GetHorizontalMagnitude() <= radius)
                    {
                        m_UnarmedLootZombies.Add(zombie.transform.position);
                    }
                }
            }
        }

        private bool IsUnarmedLootCrowded(Vector3 point)
        {
            var count = 0;
            foreach (var zombiePosition in m_UnarmedLootZombies)
            {
                if ((zombiePosition - point).GetHorizontalMagnitude() <= UnarmedWeaponZombieMeters
                    && ++count >= UnarmedWeaponZombieCount)
                {
                    return true;
                }
            }
            return false;
        }

        private static int CountLivingZombiesNearSegment(Vector3 from, Vector3 to, float radius)
        {
            var count = 0;
            if (ZombieManager.regions == null)
            {
                return count;
            }
            var a = new Vector2(from.x, from.z);
            var b = new Vector2(to.x, to.z);
            var ab = b - a;
            var lengthSquared = Mathf.Max(ab.sqrMagnitude, 0.01f);
            foreach (var region in ZombieManager.regions)
            {
                if (region?.zombies == null)
                {
                    continue;
                }
                foreach (var zombie in region.zombies)
                {
                    if (zombie == null || zombie.isDead)
                    {
                        continue;
                    }
                    var p = new Vector2(zombie.transform.position.x, zombie.transform.position.z);
                    var t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / lengthSquared);
                    if ((a + ab * t - p).magnitude <= radius)
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        private int CountPerceivedZombiesNear(Vector3 point, float radius)
        {
            var count = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null
                    && !zombie.isDead
                    && zombie.gameObject.activeInHierarchy
                    && (zombie.transform.position - point).GetHorizontalMagnitude() <= radius)
                {
                    count++;
                }
            }
            return count;
        }

        // Health only regenerates above the server's food/water minimum: with
        // nothing to eat or drink in the bag, fetching it beats clothes.
        // How far a remembered item is worth walking to. "Inside the area"
        // was true whenever the bot had no area (travel, local exploration):
        // in the 0.1.150 test a bandage 935m away and milk 480m away were
        // picked 886 times. Now: the area being searched, or 85m around a
        // bot with no area; food or water it lacks, farther the more urgent.
        private float RememberedLootReach(ItemAsset asset, bool needFood, bool needWater)
        {
            var reach = m_HasInterestArea ? 0f : InterestAreaRadiusMeters;
            var life = m_Player.life;
            if (needFood && asset.type == EItemType.FOOD)
            {
                reach = Mathf.Max(reach, life.food <= 20 ? 250f : 150f);
            }
            if (needWater && asset.type == EItemType.WATER)
            {
                reach = Mathf.Max(reach, life.water <= 20 ? 250f : 150f);
            }
            return reach;
        }

        private void GetConsumableLootNeeds(out bool food, out bool water)
        {
            GetRegenThresholds(out var regenFood, out var regenWater);
            var life = m_Player.life;
            food = life.food <= regenFood + 5 && CountUsableConsumables(false) == 0;
            water = life.water <= regenWater + 5 && CountUsableConsumables(true) == 0;
        }

        private static int GetLootPriority(ItemAsset asset)
        {
            switch (asset.type)
            {
                case EItemType.GUN:
                case EItemType.MELEE:
                    return 0;
                case EItemType.MEDICAL:
                    return 1;
                case EItemType.BACKPACK:
                case EItemType.VEST:
                case EItemType.MAGAZINE:
                    return 2;
                case EItemType.FOOD:
                case EItemType.WATER:
                case EItemType.SHIRT:
                case EItemType.PANTS:
                case EItemType.HAT:
                case EItemType.MASK:
                case EItemType.GLASSES:
                    return 3;
                default:
                    return 5;
            }
        }

        private bool SetLootObjective(byte regionX, byte regionY, ItemData item, float now, bool fireWeapon = false)
        {
            var asset = Assets.find(EAssetType.ITEM, item.item.id) as ItemAsset;
            // 0.1.166: a magazine or an unloaded gun picked for the burner was
            // refused here (a burner within 20m is a loot threat) while the
            // log said the bot was running for it: 105 runs, 3 guns picked up.
            var isRequiredFireWeapon = (fireWeapon
                    || (asset is ItemGunAsset requiredFireGun
                        && IsLoadedGun(requiredFireGun, item.item.state)))
                && m_RememberedFireZombie != null
                && !m_RememberedFireZombie.isDead
                && m_RememberedFireZombie.gameObject.activeInHierarchy;
            var isNeededWeapon = IsUnarmed()
                && (asset is ItemMeleeAsset || asset is ItemGunAsset);
            if (HasLootBlockingThreat() && !isRequiredFireWeapon && !isNeededWeapon && !IsDropPickupWindow())
            {
                m_StatLootRejects++;
                BotLog(LogLevel.Debug,
                    "Bot rejeitou loot {LootInstanceId}: a limpeza de {ZombieCount} zumbi(s) ainda nao terminou.",
                    item.instanceID,
                    m_CachedOperationalAreaZombieCount);
                return false;
            }
            if (!isRequiredFireWeapon && !IsDropPickupWindow() && IsLootInFreshDeathZone(item, now))
            {
                m_StatLootRejects++;
                return false;
            }
            if (!isRequiredFireWeapon && IsLootTowardPvpEnemy(item, now))
            {
                m_StatLootRejects++;
                return false;
            }
            // 0.1.0-y17.4: nor by another man it remembers, nor in the open
            // in the minute after one (SkaliaBotPvpMemoryY).
            if (!isRequiredFireWeapon && (IsLootTowardRememberedOther(item, now)
                || IsLootInPvpEnemyLine(item.point, "Loot " + item.instanceID, now)
                || (!isNeededWeapon && IsLootInOpenAfterPvp(item, now))))
            {
                m_StatLootRejects++;
                return false;
            }
            // 0.1.173: never into an acid puddle or fire; not where a horde
            // was seen, nor right back where the bot just escaped from.
            if (IsPointInAcidOrFire(item.point))
            {
                m_StatLootRejects++;
                IgnoreLoot(item.instanceID, now + AcidLootIgnoreSeconds);
                BotLog(LogLevel.Information,
                    "Loot {Item} em {Position} esta dentro de acido ou fogo; ignorado por {Seconds:0}s.",
                    DescribeItem(item.item),
                    FormatPosition(item.point),
                    AcidLootIgnoreSeconds);
                return false;
            }
            if (!isRequiredFireWeapon
                && !isNeededWeapon
                && !IsDropPickupWindow()
                && IsLootSpotAvoided(item.point, now, false))
            {
                m_StatLootRejects++;
                return false;
            }
            // 0.1.173: who gets there first. A hunter 25-30m away covered
            // the 10m between "start" (25m) and "cancel" (15m) in 2s: 117 of
            // the 126 cancels of the 0.1.172 night came within 6s.
            if (!isRequiredFireWeapon
                && !isNeededWeapon
                && !IsDropPickupWindow()
                && IsLootRaceLost(item.point, m_BehaviorPosition, out var botSeconds, out var zombieSeconds))
            {
                m_StatLootRejects++;
                m_StatWindowLootRaceLost++;
                DeferLootRace(item.instanceID, now);
                NoteLootGuarded(item.point, now);
                if (now >= m_NextLootRaceLogAt)
                {
                    m_NextLootRaceLogAt = now + 10f;
                    BotLog(LogLevel.Information,
                        "Loot adiado: {Item} a {Distance:0.#}m; zumbi chega em {Zombie:0.#}s, o bot levaria {BotSeconds:0.#}s.",
                        DescribeItem(item.item),
                        (item.point - m_BehaviorPosition).GetHorizontalMagnitude(),
                        zombieSeconds,
                        botSeconds);
                }
                return false;
            }

            ReleaseLootClaim();
            m_LootRegionX = regionX;
            m_LootRegionY = regionY;
            m_LootInstanceId = item.instanceID;
            m_LootTargetIsCombatEquipment = asset is ItemGunAsset || asset is ItemMeleeAsset;
            m_LootTargetIsRangedWeapon = asset is ItemGunAsset rangedGun
                && IsLoadedGun(rangedGun, item.item.state);
            m_LootWithinReachSince = 0f;
            s_LootClaims[item.instanceID] = new LootClaim
            {
                Owner = m_Player,
                ExpiresAt = now + LootClaimSeconds
            };
            SetObjective(
                ObjectiveType.Loot,
                item.point,
                now + m_ObjectiveTimeoutSeconds);
            m_ConsecutiveStuckChecks = 0;
            return true;
        }

        private bool IsLootClaimedByAnotherBot(uint instanceId, float now)
        {
            if (!s_LootClaims.TryGetValue(instanceId, out var claim))
            {
                return false;
            }
            if (now >= claim.ExpiresAt
                || claim.Owner == null
                || !s_ActiveSimulations.ContainsKey(claim.Owner))
            {
                s_LootClaims.Remove(instanceId);
                return false;
            }
            return claim.Owner != m_Player;
        }

        private void RefreshLootClaim(float now)
        {
            if (m_LootInstanceId != 0
                && s_LootClaims.TryGetValue(m_LootInstanceId, out var claim)
                && claim.Owner == m_Player)
            {
                claim.ExpiresAt = now + LootClaimSeconds;
            }
        }

        private void ReleaseLootClaim()
        {
            if (m_LootInstanceId != 0
                && s_LootClaims.TryGetValue(m_LootInstanceId, out var claim)
                && claim.Owner == m_Player)
            {
                s_LootClaims.Remove(m_LootInstanceId);
            }
        }

        // 0.2.2c: players look at and pause on what they take out of a
        // fridge or wardrobe; the items lying on the floor are grabbed from
        // the inventory's "nearby" list without looking at each one. With
        // lootLookFurnitureOnly the aim, the half-second look and the pause
        // after the pickup are only for an item in openable furniture.
        private bool m_LastLootInFurniture = true;
        private uint m_FurnitureCheckId;
        private bool m_FurnitureCheckResult;

        private bool IsLootLookWanted(ItemData loot)
        {
            if (!s_Settings.LootLookFurnitureOnly)
            {
                return true;
            }
            if (loot.instanceID != m_FurnitureCheckId)
            {
                m_FurnitureCheckId = loot.instanceID;
                m_FurnitureCheckResult = SkaliaBotStructureMap.IsInOpenableFurniture(loot.point);
            }
            return m_FurnitureCheckResult;
        }

        private bool TryGetTargetLoot(out ItemData target)
        {
            target = null!;
            if (m_ObjectiveType != ObjectiveType.Loot
                || ItemManager.regions == null
                || !Regions.checkSafe(m_LootRegionX, m_LootRegionY))
            {
                return false;
            }

            var region = ItemManager.regions[m_LootRegionX, m_LootRegionY];
            if (region == null)
            {
                return false;
            }

            foreach (var item in region.items)
            {
                if (item.instanceID == m_LootInstanceId)
                {
                    target = item;
                    return true;
                }
            }

            return false;
        }

        private void TryCollectTargetLoot(float now)
        {
            if (ItemManager.instance == null || m_Player.channel.owner == null)
            {
                return;
            }

            var lootName = TryGetTargetLoot(out var lootBefore)
                ? DescribeItem(lootBefore.item)
                : m_LootInstanceId.ToString();
            if (lootBefore != null)
            {
                // 0.1.0-y17.10: no room as the bag is: /sort first, then
                // the pickup (SkaliaBotSortY).
                if (Assets.find(EAssetType.ITEM, lootBefore.item.id) is ItemAsset lootAsset
                    && !(lootAsset is ItemBagAsset)
                    && !HasInventorySpaceNow(lootAsset)
                    && (IsSortSettling(now) || TryTypeSort(lootAsset, "pegar " + lootName, now)))
                {
                    return;
                }
                MakeRoomForUpgrade(lootBefore);
            }
#pragma warning disable CS0612
            ItemManager.instance.askTakeItem(
                m_Player.channel.owner.playerID.steamID,
                m_LootRegionX,
                m_LootRegionY,
                m_LootInstanceId,
                0,
                0,
                0,
                byte.MaxValue);
#pragma warning restore CS0612

            var wasCombatEquipment = m_LootTargetIsCombatEquipment;
            m_LastLootInFurniture = lootBefore == null || IsLootLookWanted(lootBefore);
            var collected = !TryGetTargetLoot(out _);
            if (!collected)
            {
                // Most commonly the inventory is full. Avoid selecting the same
                // item repeatedly while allowing it to become eligible later.
                IgnoreLoot(m_LootInstanceId, now + 30f);
                BotLog(LogLevel.Information,
                    "Coleta de {Item} falhou (inventario cheio?); item ignorado por 30s. Inventario: {Inventory}.",
                    lootName,
                    DescribeInventory());
            }
            else
            {
                m_LootMemories.RemoveAll(
                    memory => memory.InstanceId == m_LootInstanceId);
                m_StatLoots++;
                m_StatLootsTotal++;
                m_StatWindowLoots++;
                m_LastItemPickupAt = now;
                MarkOrbitWindowBusy();
                BotLog(LogLevel.Information,
                    "Bot coletou {Item} em {AreaName} (equipamento de combate {Combat}). Inventario: {Inventory}.",
                    lootName,
                    m_InterestAreaName,
                    wasCombatEquipment,
                    DescribeInventory());
            }

            ClearObjective();
            m_LootSettledId = 0;
            m_NextLootScanTime = now + (wasCombatEquipment ? 0.75f : 3f);
            if (collected)
            {
                NoteLootPilePickup(now);
            }
            if (collected && !IsLootHurried() && m_LastLootInFurniture)
            {
                m_LootLingerUntil = now + Random.Range(0.35f, 0.9f);
                m_LootLingerYaw = m_CurrentYaw;
                m_LootLingerPitch = m_CurrentPitch;
                // Another item of the same pile is taken after the pause,
                // not 3s later after walking off and coming back.
                m_NextLootScanTime = Mathf.Min(m_NextLootScanTime, m_LootLingerUntil + 0.1f);
            }
        }

        // A dead bot drops its whole inventory where it fell and came back with
        // nothing, starting the run over. Within 10 min of the death it goes
        // back for it (by terrain if that spot is in another town), unless it
        // died twice at the same place or the place is crowded and it is unarmed.
        private const float DeathRecoverySeconds = 600f;
        private const float DeathRecoveryArriveMeters = 6f;
        private const float DeathRecoveryRepeatMeters = 40f;
        private const float DeathRecoveryRepeatSeconds = 1800f;
        private bool m_DeathRecoveryPending;
        private Vector3 m_DeathRecoveryPosition;
        private float m_DeathRecoveryDiedAt = float.NegativeInfinity;
        private Vector3 m_PreviousDeathPosition;
        // 0.1.170: an hour (was 30 min). Everett killed XXlloqiartyXX at
        // 21:57 and 22:05, Tadeu at 22:55 (50 min later, the zone had ended
        // and that death no longer counted as a second one) and
        // XXlloqiartyXX again at 23:18.
        private const float DangerZoneSeconds = 3600f;
        private const float DangerZoneAreaMeters = 150f;
        private const float DangerZoneLootMeters = 40f;
        // Shared by every bot: in the 0.1.141 test Vorkuta Junction killed
        // Tadeu once and thigas twice, and two bots died 60m apart at Camp
        // Kazan, while each bot only remembered its own deaths.
        private static readonly List<KeyValuePair<Vector3, float>> m_DangerZones = new List<KeyValuePair<Vector3, float>>();
        private static readonly List<KeyValuePair<Vector3, float>> s_RecentDeaths = new List<KeyValuePair<Vector3, float>>();
        private const float SharedDeathMeters = 80f;

        private bool IsInDangerZone(Vector3 point, float radius)
        {
            var realNow = Time.realtimeSinceStartup;
            foreach (var zone in m_FireAvoidZones)
            {
                if (realNow < zone.Value && (point - zone.Key).GetHorizontalMagnitude() <= radius)
                {
                    return true;
                }
            }
            foreach (var zone in m_DangerZones)
            {
                if (realNow < zone.Value && (point - zone.Key).GetHorizontalMagnitude() <= radius)
                {
                    return true;
                }
            }
            // 0.2.2t: for the tryhard a Mega never closes an area or a trip;
            // only the points within its reach are skipped while it is there.
            if (Tryhard)
            {
                return false;
            }
            var bossRadius = MegaNoLure ? Mathf.Min(radius, BossNoLureZoneMeters) : radius;
            foreach (var zone in s_BossZones)
            {
                if (realNow < zone.Value && (point - zone.Key).GetHorizontalMagnitude() <= bossRadius)
                {
                    return true;
                }
            }
            return IsNearFreshDeath(point, radius);
        }
        private float m_PreviousDeathAt = float.NegativeInfinity;
        private bool m_DeathRecoveryActive;
        private float m_NextDeathRecoveryLogAt;

        // 0.1.166: thigas was killed by a Mega, walked back for the items four
        // minutes later and died again 34m from the spot (21:18 and 21:22).
        // The bot now remembers what killed it and does not go back while
        // that Mega, boss or burner is still near the spot, or, after dying
        // in a crowd, while three zombies are still there.
        private const float DeathKillerGuardMeters = 40f;
        private const float DeathCrowdGuardMeters = 15f;
        private Zombie? m_DeathKiller;
        private EZombieSpeciality m_DeathKillerSpeciality;
        private string m_DeathKillerName = string.Empty;
        private bool m_DeathByCrowd;
        private float m_NextDeathDangerCheckAt;

        private void NoteDeathKiller(Vector3 deathPosition)
        {
            m_DeathKiller = null;
            m_DeathKillerName = string.Empty;
            m_DeathByCrowd = false;
            if (ZombieManager.regions == null)
            {
                return;
            }
            var crowd = 0;
            var bestDistance = float.PositiveInfinity;
            foreach (var region in ZombieManager.regions)
            {
                if (region?.zombies == null)
                {
                    continue;
                }
                foreach (var zombie in region.zombies)
                {
                    if (zombie == null || zombie.isDead || !zombie.gameObject.activeInHierarchy)
                    {
                        continue;
                    }
                    var distance = (zombie.transform.position - deathPosition).GetHorizontalMagnitude();
                    if (distance <= 10f)
                    {
                        crowd++;
                    }
                    // A Mega kills with boulders from well beyond arm's reach:
                    // XXlloqiartyXX died to one at 01:37 in the 0.1.165 test.
                    var boss = zombie.speciality == EZombieSpeciality.MEGA
                        || zombie.speciality.ToString().StartsWith("BOSS_", System.StringComparison.Ordinal);
                    var special = boss
                        ? distance <= DeathKillerGuardMeters
                        : IsFireZombie(zombie) && distance <= 6f;
                    if (special && distance < bestDistance)
                    {
                        bestDistance = distance;
                        m_DeathKiller = zombie;
                    }
                }
            }
            m_DeathByCrowd = crowd >= 3;
            var killer = m_DeathKiller;
            if (killer != null)
            {
                m_DeathKillerSpeciality = killer.speciality;
                m_DeathKillerName = killer.speciality == EZombieSpeciality.MEGA
                    ? "o Mega"
                    : IsFireZombie(killer)
                        ? "o zumbi de fogo"
                        : "o chefe " + killer.speciality;
            }
            // 0.1.174: logged on every death (5 of 19 had no line), so the
            // log alone counts them.
            BotLog(LogLevel.Information,
                "Bot morreu em {Position} com {Killer} e {Crowd} zumbis a 10m; {Guard}.",
                FormatPosition(deathPosition),
                killer != null
                    ? m_DeathKillerName + " a " + bestDistance.ToString("0.#") + "m"
                    : "nenhum zumbi especial perto",
                crowd,
                "zumbi e Mega nao impedem a volta para os itens");
            // 0.2.2x2 (doc 16.7, item 7): the hunt used to end after the
            // respawn as "a municao nao da mais (dano 0)".
            if (m_BossHuntActive)
            {
                EndBossHunt(m_BehaviorNow, "bot morreu");
            }
        }

        // 0.1.170: XXlloqiartyXX went back for his items, was hurt down to
        // 17 on the way and kept going through the zombies that had killed
        // him; a spitter finished him. The way back waits for this much.
        private const byte DeathRecoveryMinHealth = 50;

        private bool IsDeathSpotStillDangerous(out string reason)
        {
            reason = string.Empty;
            if (m_Player.life.health < DeathRecoveryMinHealth)
            {
                reason = "vida " + m_Player.life.health + ", espera chegar a " + DeathRecoveryMinHealth;
                return true;
            }
            // 0.1.0-y16.2 (the tester, 17/11: "nessa altura zombi e mega n eh
            // pra ser mais problema"): the zombie, the Mega or the crowd that
            // killed it no longer keep the bot from its items.
            if (s_Settings.FreshDeathAvoidance
                && TryGetFreshDeathNear(m_DeathRecoveryPosition, FreshDeathMeters, out var freshDeath, out var freshAge))
            {
                reason = freshDeath.Name + " morreu a "
                    + (freshDeath.Position - m_DeathRecoveryPosition).GetHorizontalMagnitude().ToString("0")
                    + "m do lugar ha " + freshAge.ToString("0") + "s";
                return true;
            }
            return false;
        }

        private void CheckDeathRecoveryDanger(Vector3 position, float now)
        {
            if (!m_DeathRecoveryActive
                || now < m_NextDeathDangerCheckAt
                || m_ObjectiveType != ObjectiveType.Explore
                || m_InterestAreaName != "recuperar itens da morte")
            {
                return;
            }
            m_NextDeathDangerCheckAt = now + 1f;
            var distance = (m_DeathRecoveryPosition - position).GetHorizontalMagnitude();
            if ((distance > 90f && m_Player.life.health >= DeathRecoveryMinHealth)
                || !IsDeathSpotStillDangerous(out var reason))
            {
                return;
            }
            m_DeathRecoveryActive = false;
            m_HasInterestArea = false;
            ClearObjective();
            m_NextDeathRecoveryLogAt = now + 30f;
            BotLog(LogLevel.Information,
                "Volta para os itens interrompida a {Distance:0}m de {Position}: {Reason}.",
                distance,
                FormatPosition(m_DeathRecoveryPosition),
                reason);
        }

        private void RecordDeathForRecovery(Vector3 deathPosition)
        {
            var realNow = Time.realtimeSinceStartup;
            NoteDeathKiller(deathPosition);
            var repeated = realNow - m_PreviousDeathAt <= DeathRecoveryRepeatSeconds
                && (deathPosition - m_PreviousDeathPosition).GetHorizontalMagnitude() <= DeathRecoveryRepeatMeters;
            m_PreviousDeathPosition = deathPosition;
            m_PreviousDeathAt = realNow;
            m_DeathRecoveryActive = false;
            s_RecentDeaths.RemoveAll(death => realNow - death.Value > DangerZoneSeconds);
            var earlierDeathsHere = 0;
            foreach (var death in s_RecentDeaths)
            {
                if ((death.Key - deathPosition).GetHorizontalMagnitude() <= SharedDeathMeters)
                {
                    earlierDeathsHere++;
                }
            }
            s_RecentDeaths.Add(new KeyValuePair<Vector3, float>(deathPosition, realNow));
            RecordFreshDeath(deathPosition, realNow);
            // 0.1.0-y16.2 (the tester, 17/11: "remove isso ai e mantenha a regra
            // de voltar so se tiver loot importante"): the dangerous place
            // (a second death within 150m in the hour: no way back, and every
            // bot kept off 150m round it for an hour) is gone. It came from
            // zombie deaths (0.1.131), and in the session of 17:28 it was set
            // 13 times, 11 with no zombie near, after PvP deaths, at the
            // Seattle strongpoints. The way back is the x19 one: only for
            // loot worth it (HasWorthyDeathLoot), and only while the place is
            // not still guarded (IsDeathSpotStillDangerous).
            _ = repeated;
            _ = earlierDeathsHere;
            // 0.1.0-y16.2 (the tester, 17/11: "faz sentido ele desistir do loot
            // se morreu pra um jogador/bot pq o bot vai lootear ele"): the last
            // hurt before the death from a player or a bot (not a zombie):
            // the items are his (SkaliaBotPvpKillLootY), no way back.
            if (m_LastHurtByPlayerAt > m_LastZombieBiteAt && realNow - m_LastHurtByPlayerAt <= 60f)
            {
                m_DeathRecoveryPending = false;
                BotLog(LogLevel.Information,
                    "Morri para {Name}; o que ficou no chao e dele, nao volto para buscar.",
                    m_LastHurtByPlayerName);
                return;
            }
            m_DeathRecoveryPending = true;
            m_DeathRecoveryPosition = deathPosition;
            m_DeathRecoveryDiedAt = realNow;
        }

        private const float DeathRecoveryWalkSpeed = 3f;

        private bool TryStartDeathRecovery(Vector3 position, float now, GraphNode originNode)
        {
            if (!m_DeathRecoveryPending)
            {
                return false;
            }
            var realNow = Time.realtimeSinceStartup;
            if (realNow - m_DeathRecoveryDiedAt > DeathRecoverySeconds)
            {
                m_DeathRecoveryPending = false;
                BotLog(LogLevel.Information,
                    "Itens deixados na morte em {Position} abandonados: passaram 10 min.",
                    FormatPosition(m_DeathRecoveryPosition));
                return false;
            }
            var distance = (m_DeathRecoveryPosition - position).GetHorizontalMagnitude();
            if (m_DeathRecoveryActive && distance <= DeathRecoveryArriveMeters)
            {
                m_DeathRecoveryPending = false;
                m_DeathRecoveryActive = false;
                m_NextLootScanTime = 0f;
                BotLog(LogLevel.Information,
                    "Bot chegou onde morreu em {Position}; recolhendo o que sobrou.",
                    FormatPosition(m_DeathRecoveryPosition));
                return false;
            }
            // Dropped items vanish 10 min after the death. The respawn put the
            // bots 1.7 to 2.1 km away: three such trips in the 0.1.103 log ran
            // out of time or found no way, after up to 11 min of walking, and
            // the items were gone by then anyway. Go only when the walk ends
            // before they vanish.
            // x19: only for loot worth the walk (SkaliaBotX19).
            if (!m_DeathRecoveryActive)
            {
                if (!HasWorthyDeathLoot(m_DeathRecoveryPosition, out var worthy))
                {
                    m_DeathRecoveryPending = false;
                    BotLog(LogLevel.Information,
                        "Itens deixados na morte em {Position} ({Distance:0}m): nenhuma arma que sirva nem mochila ou colete melhor; nao volta.",
                        FormatPosition(m_DeathRecoveryPosition),
                        distance);
                    return false;
                }
                if (now >= m_NextDeathRecoveryLogAt)
                {
                    m_NextDeathRecoveryLogAt = now + 30f;
                    BotLog(LogLevel.Information,
                        "Itens deixados na morte em {Position} ({Distance:0}m) valem a volta: {Item}.",
                        FormatPosition(m_DeathRecoveryPosition),
                        distance,
                        worthy);
                }
            }
            if (!m_DeathRecoveryActive)
            {
                var walkSeconds = distance / DeathRecoveryWalkSpeed;
                if (realNow - m_DeathRecoveryDiedAt + walkSeconds > DeathRecoverySeconds)
                {
                    m_DeathRecoveryPending = false;
                    BotLog(LogLevel.Information,
                        "Itens deixados na morte em {Position} longe demais: {Distance:0}m, uns {Walk:0}s de caminhada, e somem {Left:0}s depois da morte; recomecando daqui.",
                        FormatPosition(m_DeathRecoveryPosition),
                        distance,
                        walkSeconds,
                        DeathRecoverySeconds);
                    return false;
                }
            }
            if (IsDeathSpotStillDangerous(out var dangerReason))
            {
                if (now >= m_NextDeathRecoveryLogAt)
                {
                    m_NextDeathRecoveryLogAt = now + 30f;
                    BotLog(LogLevel.Information,
                        "Volta para os itens em {Position} adiada: {Reason}.",
                        FormatPosition(m_DeathRecoveryPosition),
                        dangerReason);
                }
                return false;
            }
            // A route on the new mesh goes straight there, whatever pocket of
            // the zombie mesh either end is in.
            if (SkaliaBotUnityNavmesh.TryFindPath(position, m_DeathRecoveryPosition, m_UnityPathScratch))
            {
                if (!m_DeathRecoveryActive || now >= m_NextDeathRecoveryLogAt)
                {
                    m_NextDeathRecoveryLogAt = now + 30f;
                    BotLog(LogLevel.Information,
                        "Voltando pela malha nova para buscar os itens deixados na morte em {Position} ({Distance:0}m; morreu ha {Seconds:0}s).",
                        FormatPosition(m_DeathRecoveryPosition),
                        distance,
                        realNow - m_DeathRecoveryDiedAt);
                }
                m_DeathRecoveryActive = true;
                m_HasInterestArea = false;
                m_InterestAreaName = "recuperar itens da morte";
                SetObjective(ObjectiveType.Explore, m_DeathRecoveryPosition, now + 120f);
                return true;
            }
            var target = AstarPath.active.GetNearest(m_DeathRecoveryPosition, NNConstraint.Walkable);
            if (target.node == null
                || (target.position - m_DeathRecoveryPosition).GetHorizontalMagnitude() > 8f)
            {
                m_DeathRecoveryPending = false;
                BotLog(LogLevel.Information,
                    "Itens deixados na morte em {Position} fora da malha; nao da para voltar.",
                    FormatPosition(m_DeathRecoveryPosition));
                return false;
            }
            if (target.node.Area == originNode.Area)
            {
                if (!m_DeathRecoveryActive || now >= m_NextDeathRecoveryLogAt)
                {
                    m_NextDeathRecoveryLogAt = now + 30f;
                    BotLog(LogLevel.Information,
                        "Voltando para buscar os itens deixados na morte em {Position} ({Distance:0}m; morreu ha {Seconds:0}s).",
                        FormatPosition(m_DeathRecoveryPosition),
                        distance,
                        realNow - m_DeathRecoveryDiedAt);
                }
                m_DeathRecoveryActive = true;
                m_HasInterestArea = false;
                m_InterestAreaName = "recuperar itens da morte";
                SetObjective(ObjectiveType.Explore, target.position, now + 120f);
                return true;
            }
            if (target.node.GraphIndex == originNode.GraphIndex
                || m_Player.life.health < TravelMinimumHealth)
            {
                // Same town but another pocket of the mesh: not reachable.
                m_DeathRecoveryPending = false;
                BotLog(LogLevel.Information,
                    "Itens deixados na morte em {Position} sem rota daqui; desistindo.",
                    FormatPosition(m_DeathRecoveryPosition));
                return false;
            }
            BotLog(LogLevel.Information,
                "Voltando por terreno para buscar os itens deixados na morte em {Position} ({Distance:0}m).",
                FormatPosition(m_DeathRecoveryPosition),
                distance);
            m_DeathRecoveryActive = true;
            StartTerrainTravelTo(
                position,
                now,
                originNode,
                originNode.GraphIndex,
                target.position,
                "itens da morte",
                target.node.GraphIndex,
                "recuperar itens da morte");
            return true;
        }

        private void ChooseExplorationObjective(Vector3 position, float now)
        {
            // 0.2.1: waiting for /home: the next area is picked from the bed.
            if (m_HomeRequestedAt >= 0f)
            {
                return;
            }
            if (m_TravelActive)
            {
                if (now < m_TravelDeadline)
                {
                    ResumeTerrainTravel(position, now);
                    return;
                }
                FailTerrainTravel(now, "tempo esgotado");
            }
            if (AstarPath.active == null)
            {
                ChooseLocalExplorationObjective(position, now, "AstarPath indisponivel");
                return;
            }

            var originInfo = AstarPath.active.GetNearest(position, NNConstraint.Walkable);
            if (originInfo.node != null && TryStartDeathRecovery(position, now, originInfo.node))
            {
                return;
            }
            if (originInfo.node == null)
            {
                TrackPocket(position, now);
                if (TryStartOffMeshTravel(position, now))
                {
                    return;
                }
                if (TryEscapePocket(position, now))
                {
                    return;
                }
                ChooseLocalExplorationObjective(
                    position,
                    now,
                    "nenhum no caminhavel foi encontrado perto do bot");
                return;
            }

            var chosen = Vector3.zero;
            var chosenKey = string.Empty;
            var candidateCount = 0;
            m_ExplorationWeightTotal = 0f;
            var blacklistedCount = 0;
            var missingNodeCount = 0;
            var disconnectedCount = 0;

            var usePending = m_PendingMeshAreaKey.Length > 0
                && now < m_PendingMeshAreaUntil
                && (m_PendingMeshAreaPoint - position).GetHorizontalMagnitude() <= MeshExplorationMeters;
            if (usePending)
            {
                chosen = m_PendingMeshAreaPoint;
                chosenKey = m_PendingMeshAreaKey;
                m_InterestAreaName = m_PendingMeshAreaName;
                candidateCount = 1;
                BotLog(LogLevel.Information,
                    "Chegou a {Distance:0}m de {AreaName} pela viagem; vasculhando a area em vez de escolher outra.",
                    (chosen - position).GetHorizontalMagnitude(),
                    m_InterestAreaName);
            }
            m_PendingMeshAreaKey = string.Empty;

            // 0.2.1: ready for the Mega and it is alive: its spawn first.
            var megaSpot = Vector3.zero;
            var megaName = string.Empty;
            var megaTrip = !usePending
                && TryPickMegaTrip(position, now, out megaSpot, out megaName);
            if (megaTrip)
            {
                ConsiderExplorationCandidate(
                    position,
                    megaSpot,
                    megaName,
                    0f,
                    TravelMaximumMeters,
                    now,
                    originInfo.node,
                    ref chosen,
                    ref m_InterestAreaName,
                    ref chosenKey,
                    ref candidateCount,
                    ref blacklistedCount,
                    ref missingNodeCount,
                    ref disconnectedCount,
                    false,
                    true);
                megaTrip = candidateCount > 0;
                if (!megaTrip)
                {
                    BotLog(LogLevel.Information,
                        "Posicao de tiro do Mega em {Spot} sem rota pela malha; seguindo a exploracao.",
                        FormatPosition(megaSpot));
                }
            }

            // 0.2.2t: the tryhard does not draw: strong spot, Mega, hunt.
            var tryhardPick = !usePending
                && !megaTrip
                && Tryhard
                && TryPickTryhardDestination(
                    position,
                    now,
                    originInfo.node,
                    ref chosen,
                    ref chosenKey,
                    ref candidateCount,
                    ref blacklistedCount,
                    ref missingNodeCount,
                    ref disconnectedCount);
            var locations = usePending || megaTrip || tryhardPick ? null : LocationDevkitNodeSystem.Get()?.GetAllNodes();
            if (locations != null)
            {
                foreach (var location in locations)
                {
                    ConsiderExplorationCandidate(
                        position,
                        location.transform.position,
                        string.IsNullOrWhiteSpace(location.locationName)
                            ? "local sem nome"
                            : location.locationName,
                        35f,
                        900f,
                        now,
                        originInfo.node,
                        ref chosen,
                        ref m_InterestAreaName,
                        ref chosenKey,
                        ref candidateCount,
                        ref blacklistedCount,
                        ref missingNodeCount,
                        ref disconnectedCount);
                }
            }

            if (candidateCount == 0 && LevelItems.spawns != null)
            {
                for (byte x = 0; x < Regions.WORLD_SIZE; x++)
                {
                    for (byte y = 0; y < Regions.WORLD_SIZE; y++)
                    {
                        foreach (var spawn in LevelItems.spawns[x, y])
                        {
                            ConsiderExplorationCandidate(
                                position,
                                spawn.point,
                                "area de loot",
                                35f,
                                600f,
                                now,
                                originInfo.node,
                                ref chosen,
                                ref m_InterestAreaName,
                                ref chosenKey,
                                ref candidateCount,
                                ref blacklistedCount,
                                ref missingNodeCount,
                                ref disconnectedCount,
                                false);
                        }
                    }
                }
            }

            if (candidateCount == 0)
            {
                BotLog(LogLevel.Information,
                    "Nenhuma area global conectada a regiao {OriginArea}/grafo {OriginGraph}: "
                    + "{Disconnected} desconectada(s), {MissingNode} sem no proximo e "
                    + "{Blacklisted} em blacklist. Usando exploracao local.",
                    originInfo.node.Area,
                    originInfo.node.GraphIndex,
                    disconnectedCount,
                    missingNodeCount,
                    blacklistedCount);
                if (TryStartTerrainTravel(position, now, originInfo.node, "nenhuma area conectada na malha"))
                {
                    return;
                }
                if (TryUseRampLink(position, now, null, "nenhuma area conectada"))
                {
                    return;
                }
                // Fresh out of the water into a pocket with no route anywhere:
                // the bot swam onto an island and would loop on its banks.
                if (now - m_LastInWaterAt < StrandedAfterWaterSeconds
                    && TryPickDrySpawn(position, 60f, out var mainland))
                {
                    BotLog(LogLevel.Warning,
                        "Bot ilhado em {Position} depois de sair da agua (regiao sem conexao); teleportando para {Destination}.",
                        FormatPosition(position),
                        FormatPosition(mainland));
                    m_InWaterSince = -1f;
                    m_WaterEpisodeSince = -1f;
                    // One teleport per swim: the zombie graph called the
                    // landing spot an island too, and in the 0.1.123 test two
                    // bots were thrown between the same two spots 16 times a
                    // second for minutes (1085 teleports).
                    m_LastInWaterAt = float.NegativeInfinity;
                    m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                    ClearObjective();
                    TeleportBot(mainland, m_Player.look.yaw);
                    m_StallAnchor = mainland;
                    m_NextExplorationSelectionTime = 0f;
                    return;
                }
                TrackPocket(position, now);
                if (TryEscapePocket(position, now))
                {
                    return;
                }
                ChooseLocalExplorationObjective(
                    position,
                    now,
                    "nenhuma area de interesse esta conectada a regiao atual");
                return;
            }

            if (s_Settings.GoalLoot && !megaTrip && !usePending && !tryhardPick)
            {
                BotLog(LogLevel.Information,
                    "Meta do equipamento: falta {Needs}; area {AreaName} a {Distance:0}m (peso da meta {Factor:0.00}).",
                    DescribeGoalNeeds(),
                    m_InterestAreaName,
                    (chosen - position).GetHorizontalMagnitude(),
                    GetAreaGoalFactor(chosenKey, chosen));
            }
            // 0.2.1: far from the area, with the bed near it: /home first.
            if (!megaTrip && TryHomeBeforeTrip(position, chosen, now))
            {
                return;
            }

            if (SkaliaBotUnityNavmesh.MapFilled
                && (chosen - position).GetHorizontalMagnitude() > MeshExplorationMeters)
            {
                var chosenNode = AstarPath.active.GetNearest(chosen, NNConstraint.Walkable);
                if (chosenNode.node == null || !PathUtilities.IsPathPossible(originInfo.node, chosenNode.node))
                {
                    BotLog(LogLevel.Information,
                        "Area {AreaName} a {Distance:0}m escolhida pela malha nova; o grafo dos zumbis nao liga ate la, indo por viagem pelo terreno.",
                        m_InterestAreaName,
                        (chosen - position).GetHorizontalMagnitude());
                    // Not blacklisted here: in the 0.1.141 test the trip ended
                    // 262m short, on the flag's zombie mesh, the area was
                    // already ignored and Tadeu went Zavod <-> Volk for
                    // minutes. It is blacklisted only if the trip fails.
                    m_NextTravelIsMeshArea = true;
                    m_NextTravelAreaKey = chosenKey;
                    StartTerrainTravelTo(
                        position,
                        now,
                        originInfo.node,
                        originInfo.node.GraphIndex,
                        chosen,
                        m_InterestAreaName,
                        chosenNode.node != null ? chosenNode.node.GraphIndex : uint.MaxValue,
                        "area escolhida pela malha nova");
                    return;
                }
            }
            if (!(Tryhard
                  && s_HasHuntGround
                  && chosenKey == s_HuntKey
                  && BuildHuntSweepPoints(ref chosen, originInfo.node, now)))
            {
                BuildAreaLootPoints(ref chosen, originInfo.node, Tryhard && chosenKey == m_StrongAreaKey);
            }
            var noLootHere = m_AreaLootPoints.Count == 0;
            if ((noLootHere || CountUnvisitedAreaPoints(now) == 0)
                && !TryRestartHuntSweep(chosenKey, noLootHere))
            {
                // Every loot point here was just visited: in a closed pocket of
                // the graph all picks landed on the same farm, 53 times in a row.
                // An area with no reachable loot point at all is never worth the
                // trip: in the 0.1.131 test one was picked 81 times because
                // nothing remembered that it was empty.
                m_ExplorationDestinationBlacklist[chosenKey] = now + (noLootHere ? EmptyAreaBlacklistSeconds : 600f);
                if (noLootHere)
                {
                    BotLog(LogLevel.Information,
                        "Area {AreaName} sem nenhum ponto de loot alcancavel; ignorando por {Seconds:0}s.",
                        m_InterestAreaName,
                        EmptyAreaBlacklistSeconds);
                }
                MarkAreaFinished(chosen, now);
                m_AreaLootPoints.Clear();
                if (m_ExplorationRetryDepth < 2)
                {
                    m_ExplorationRetryDepth++;
                    try
                    {
                        ChooseExplorationObjective(position, now);
                    }
                    finally
                    {
                        m_ExplorationRetryDepth--;
                    }
                    return;
                }
                if (TryStartTerrainTravel(position, now, originInfo.node,
                        Tryhard ? "tryhard sem area alcancavel por terra" : "areas da flag ja vasculhadas"))
                {
                    return;
                }
                if (TryUseRampLink(position, now, null, "areas proximas ja vasculhadas"))
                {
                    return;
                }
                ChooseLocalExplorationObjective(position, now, "todas as areas proximas ja foram vasculhadas");
                return;
            }
            m_HasInterestArea = true;
            m_InterestAreaCenter = chosen;
            m_InterestAreaKey = chosenKey;
            m_InterestAreaExpiresAt = now + 420f;
            StartInterestAreaBookkeeping(now);
            NoteAreaProgress(now);
            s_AreaClaims[chosenKey] = new KeyValuePair<Player, float>(m_Player, now + InterestAreaMaxSeconds);

            var destinationInfo = AstarPath.active.GetNearest(chosen, NNConstraint.Walkable);
            BotLog(LogLevel.Information,
                "Area {AreaName} aceita: origem regiao {OriginArea}/grafo {OriginGraph}; "
                + "destino regiao {DestinationArea}/grafo {DestinationGraph}; "
                + "{CandidateCount} candidato(s) conectado(s).",
                m_InterestAreaName,
                originInfo.node.Area,
                originInfo.node.GraphIndex,
                destinationInfo.node?.Area,
                destinationInfo.node?.GraphIndex,
                candidateCount);

            SetObjective(
                ObjectiveType.Explore,
                chosen,
                now + m_ObjectiveTimeoutSeconds);
            m_ConsecutiveStuckChecks = 0;
            TryStartAreaOverlook(position, now, chosen, chosenKey, m_InterestAreaName);
        }

        // The item spawn points of the area: inside the houses and barns, where
        // the loot is. Its center is their middle, not the map label.
        private void BuildAreaLootPoints(ref Vector3 center, GraphNode originNode, bool strongOnly = false)
        {
            m_AreaLootPoints.Clear();
            var skippedWeak = 0;
            if (LevelItems.spawns == null || AstarPath.active == null)
            {
                return;
            }
            var regions = new List<RegionCoordinate>();
            Regions.getRegionsInRadius(center, InterestAreaRadiusMeters, regions);
            var sum = Vector3.zero;
            foreach (var coordinate in regions)
            {
                var spawns = LevelItems.spawns[coordinate.x, coordinate.y];
                if (spawns == null)
                {
                    continue;
                }
                foreach (var spawn in spawns)
                {
                    // 0.2.2v (doc 13.3, item 5): at a strong spot only the
                    // spawn points of the strong tables (at Everett the bot
                    // went through House #06, #03, #02 and the diners).
                    if (strongOnly && !IsStrongTable(spawn.type))
                    {
                        skippedWeak++;
                        continue;
                    }
                    if ((spawn.point - center).GetHorizontalMagnitude() > InterestAreaRadiusMeters
                        || IsInDangerZone(spawn.point, DangerZoneLootMeters)
                        || IsSkippedContainerLoot(spawn.point)
                        || IsRadiationClosedFor(spawn.point))
                    {
                        continue;
                    }
                    var nearest = AstarPath.active.GetNearest(spawn.point, NNConstraint.Walkable);
                    var graphOk = nearest.node != null
                        && (nearest.position - spawn.point).GetHorizontalMagnitude() <= 3f
                        && Mathf.Abs(nearest.position.y - spawn.point.y) <= 2.5f
                        && PathUtilities.IsPathPossible(originNode, nearest.node);
                    var point = nearest.position;
                    // An area reached by a trip the zombie graph does not
                    // link had no loot point at all: the bot walks the new
                    // mesh, so a spawn on it counts too.
                    if (!graphOk)
                    {
                        if (!SkaliaBotUnityNavmesh.MapFilled
                            || !SkaliaBotUnityNavmesh.TrySnap(spawn.point, 1.5f, out point)
                            || Mathf.Abs(point.y - spawn.point.y) > 2.5f)
                        {
                            continue;
                        }
                    }
                    if (WaterUtility.isPointUnderwater(point + Vector3.up * 0.5f))
                    {
                        continue;
                    }
                    m_AreaLootPoints.Add(point);
                    sum += point;
                }
            }
            if (m_AreaLootPoints.Count >= 3)
            {
                center = FindNearestNavigablePoint(sum / m_AreaLootPoints.Count);
            }
            BotLog(LogLevel.Information,
                "Area de interesse com {Count} ponto(s) de loot alcancaveis; centro em {Center}{Strong}.",
                m_AreaLootPoints.Count,
                FormatPosition(center),
                strongOnly ? "; so tabela forte (" + skippedWeak + " ponto(s) comuns de fora)" : string.Empty);
        }

        // Bare hands against a horde ends in death: an unarmed bot that sees
        // five or more zombies leaves the area and keeps away for 10 minutes.
        private void UpdateUnarmedAreaAvoidance(Vector3 position, float now)
        {
            if (now < m_NextUnarmedAreaCheckAt || !m_HasInterestArea || !IsUnarmed())
            {
                return;
            }
            m_NextUnarmedAreaCheckAt = now + 2f;
            var count = 0;
            foreach (var perceived in m_PerceivedZombies)
            {
                var zombie = perceived.Key;
                if (zombie != null && !zombie.isDead && zombie.gameObject.activeInHierarchy)
                {
                    count++;
                }
            }
            if (count < 5)
            {
                return;
            }
            BotLog(LogLevel.Information,
                "Bot desarmado viu {Count} zumbis em {Area}; saindo da area por 10 min.",
                count,
                m_InterestAreaName);
            // Leaving a horde through a passage walked the bot into the next
            // one inside the Chersky barn, twice.
            m_AvoidPassageUntil = now + 30f;
            m_NextUnarmedAreaCheckAt = now + 15f;
            FinishInterestArea(now);
            if (m_ObjectiveType == ObjectiveType.Loot
                || m_ObjectiveType == ObjectiveType.Patrol
                || m_ObjectiveType == ObjectiveType.Explore
                || m_ObjectiveType == ObjectiveType.None)
            {
                ClearObjective();
                ChooseExplorationObjective(position, now);
            }
        }

        // The 0.1.150 test: thigas finished the airport, every trip out
        // failed, and with no area of its own each loot scan sent it back
        // for the items it had already given up on there, for 20 minutes.
        // An area just searched keeps its leftovers off the list, except
        // what is right by the bot.
        private bool IsInFinishedAreaFarAway(Vector3 point, Vector3 position, float now)
        {
            if (m_HasInterestArea || (point - position).GetHorizontalMagnitude() <= 25f)
            {
                return false;
            }
            foreach (var finished in m_FinishedAreas)
            {
                if (now < finished.Value
                    && (point - finished.Key).GetHorizontalMagnitude() < InterestAreaRadiusMeters)
                {
                    return true;
                }
            }
            return false;
        }

        private void MarkAreaFinished(Vector3 center, float now, float seconds = 600f)
        {
            m_FinishedAreas.RemoveAll(entry => now >= entry.Value);
            m_FinishedAreas.Add(new KeyValuePair<Vector3, float>(center, now + seconds));
        }

        private int CountUnvisitedAreaPoints(float now)
        {
            var count = 0;
            foreach (var point in m_AreaLootPoints)
            {
                if (!m_VisitedPatrolPoints.TryGetValue(point, out var until) || now >= until)
                {
                    count++;
                }
            }
            return count;
        }

        private void FinishInterestArea(float now)
        {
            if (m_HasInterestArea && !string.IsNullOrEmpty(m_InterestAreaKey))
            {
                // 0.2.2w (doc 14.3, item 5): a strong spot done stays out for
                // 30 min, so the tryhard goes round the map instead of
                // Seattle and Olympia only.
                var strongDone = Tryhard && m_InterestAreaKey == m_StrongAreaKey;
                // 0.2.2x13: a rich place left largely unseen comes back soon.
                var comeBack = TryShortRestForWorth(now, out var comeBackSeconds);
                m_ExplorationDestinationBlacklist[m_InterestAreaKey] = now + (comeBack ? comeBackSeconds : strongDone ? TryhardSpotRestSeconds : 600f);
                if (strongDone && !comeBack)
                {
                    BotLog(LogLevel.Information,
                        "Tryhard: {Name} feito; fora da lista dele por {Minutes:0} min.",
                        m_InterestAreaName,
                        TryhardSpotRestSeconds / 60f);
                    m_StrongAreaKey = string.Empty;
                }
                if (comeBack)
                {
                    m_StrongAreaKey = string.Empty;
                }
                MarkAreaFinished(m_InterestAreaCenter, now, comeBack ? comeBackSeconds : 600f);
                NoteAreaLooted(now);
                if (s_AreaClaims.TryGetValue(m_InterestAreaKey, out var claim) && claim.Key == m_Player)
                {
                    s_AreaClaims.Remove(m_InterestAreaKey);
                }
            }
            m_HasInterestArea = false;
            m_AreaLootPoints.Clear();
            m_PatrolTargetSet = false;
        }

        // A region refills Respawn_Time after it was emptied (ItemManager.
        // respawnItems). Coming back sooner than 10 min was the ir-e-vir
        // between Camano, Clearwater and Bellevue in the 0.1.166 test.
        private void NoteAreaLooted(float now)
        {
            if (m_AreaLootPoints.Count == 0 || m_InterestAreaName == "exploracao local" || IsHuntSweep)
            {
                return;
            }
            var visited = m_AreaLootPoints.Count - CountUnvisitedAreaPoints(now) - m_AreaPointsGivenUp;
            if (visited * 2 < m_AreaLootPoints.Count)
            {
                return;
            }
            var seconds = LootRespawnSeconds();
            s_LootedAreas.RemoveAll(entry => now >= entry.Until
                || (entry.Center - m_InterestAreaCenter).GetHorizontalMagnitude() < 20f);
            s_LootedAreas.Add((m_InterestAreaCenter, now + seconds));
            BotLog(LogLevel.Information,
                "Area {Area} saqueada ({Visited} de {Count} pontos); nenhum bot volta nela por {Minutes:0} min, ate o loot renascer.",
                m_InterestAreaName,
                visited,
                m_AreaLootPoints.Count,
                seconds / 60f);
        }

        private static bool IsAreaLootedByAnyBot(Vector3 point, float now)
        {
            foreach (var entry in s_LootedAreas)
            {
                if (now < entry.Until
                    && (point - entry.Center).GetHorizontalMagnitude() < InterestAreaRadiusMeters)
                {
                    return true;
                }
            }
            return false;
        }

        private bool IsAreaClaimedByOtherBot(string key, float now)
        {
            return s_AreaClaims.TryGetValue(key, out var claim)
                && claim.Key != m_Player
                && now < claim.Value;
        }

        // Item spawn points around a place: how much loot the trip is worth.
        private static int GetAreaSpawnCount(string key, Vector3 center)
        {
            if (s_AreaSpawnCounts.TryGetValue(key, out var cached))
            {
                return cached;
            }
            var count = 0;
            if (LevelItems.spawns != null)
            {
                var regions = new List<RegionCoordinate>();
                Regions.getRegionsInRadius(center, InterestAreaRadiusMeters, regions);
                foreach (var coordinate in regions)
                {
                    var spawns = LevelItems.spawns[coordinate.x, coordinate.y];
                    if (spawns == null)
                    {
                        continue;
                    }
                    foreach (var spawn in spawns)
                    {
                        if ((spawn.point - center).GetHorizontalMagnitude() <= InterestAreaRadiusMeters)
                        {
                            count++;
                        }
                    }
                }
            }
            s_AreaSpawnCounts[key] = count;
            return count;
        }

        private static bool IsAtPatrolPoint(Vector3 point, Vector3 position, float radius)
        {
            return (point - position).GetHorizontalMagnitude() <= radius
                && Mathf.Abs(point.y - position.y) < 2.5f;
        }

        // On the same floor and not behind a wall: walking around a house
        // outside, a point inside is near but not visited.
        private bool IsPatrolPointSeen(Vector3 point, Vector3 position, float radius)
        {
            return IsAtPatrolPoint(point, position, radius)
                && ((point - position).GetHorizontalMagnitude() <= 1.5f || HasLootLineOfSight(point));
        }

        // Standing at a point the bot sees the room: the points a few meters
        // away on the same floor, in sight, count too.
        private void MarkPatrolRoomVisited(Vector3 point, float now)
        {
            m_VisitedPatrolPoints[point] = now + PatrolVisitedSeconds;
            m_PatrolPointTries.Remove(point);
            foreach (var other in m_AreaLootPoints)
            {
                if ((other - point).GetHorizontalMagnitude() < 5f
                    && Mathf.Abs(other.y - point.y) < 2f
                    && (!m_VisitedPatrolPoints.TryGetValue(other, out var until) || now >= until)
                    && HasLootLineOfSight(other))
                {
                    m_VisitedPatrolPoints[other] = now + PatrolVisitedSeconds;
                    m_PatrolPointTries.Remove(other);
                }
            }
        }

        // Points walked past during a fight or on the way to another one.
        private void MarkPassedPatrolPoints(Vector3 position, float now)
        {
            if (now < m_NextPassedPointsCheckAt || !m_HasInterestArea || m_AreaLootPoints.Count == 0)
            {
                return;
            }
            m_NextPassedPointsCheckAt = now + 0.5f;
            foreach (var point in m_AreaLootPoints)
            {
                if ((!m_VisitedPatrolPoints.TryGetValue(point, out var until) || now >= until)
                    && IsPatrolPointSeen(point, position, 2.5f))
                {
                    m_VisitedPatrolPoints[point] = now + PatrolVisitedSeconds;
                    m_PatrolPointTries.Remove(point);
                }
            }
        }

        private void NotePatrolPointFailed(Vector3 point, float now, string reason, bool giveUp)
        {
            m_PatrolPointTries.TryGetValue(point, out var tries);
            tries++;
            if (!giveUp && tries < PatrolPointMaxTries)
            {
                m_PatrolPointTries[point] = tries;
                return;
            }
            m_PatrolPointTries.Remove(point);
            m_VisitedPatrolPoints[point] = now + PatrolVisitedSeconds;
            m_AreaPointsGivenUp++;
            m_StatWindowPointsGivenUp++;
            BotLog(LogLevel.Information,
                "Ponto de loot em {Point} nao alcancado ({Reason}, tentativa {Tries}); pulando ele nesta area.",
                FormatPosition(point),
                reason,
                tries);
            // 0.1.169: after the ladder of Military Tower #2 failed, Tadeu
            // stood under it for 40s, 10s under each of four points on its
            // top. A point on another floor given up takes that floor along.
            var position = m_Player.transform.position;
            if (Mathf.Abs(point.y - position.y) < 2.5f)
            {
                return;
            }
            var sameFloor = 0;
            foreach (var other in m_AreaLootPoints)
            {
                if (other == point
                    || (m_VisitedPatrolPoints.TryGetValue(other, out var visitedUntil) && now < visitedUntil)
                    || (other - point).GetHorizontalMagnitude() > 8f
                    || Mathf.Abs(other.y - point.y) > 1.5f)
                {
                    continue;
                }
                m_VisitedPatrolPoints[other] = now + PatrolVisitedSeconds;
                m_PatrolPointTries.Remove(other);
                m_AreaPointsGivenUp++;
                m_StatWindowPointsGivenUp++;
                sameFloor++;
            }
            if (sameFloor > 0)
            {
                BotLog(LogLevel.Information,
                    "Pulando tambem {Count} ponto(s) de loot no mesmo andar ({Height:0.#}m de altura em relacao ao bot).",
                    sameFloor,
                    point.y - position.y);
            }
        }

        private void StartInterestAreaBookkeeping(float now)
        {
            ResetSweepPlan();
            m_InterestAreaStartedAt = now;
            m_AreaPointsGivenUp = 0;
            m_PatrolRouteFailures = 0;
            m_PatrolPointTries.Clear();
            m_PatrolTargetSet = false;
            m_PatrolNearSince = 0f;
        }

        private void ChooseAreaPatrolObjective(Vector3 position, float now)
        {
            if (m_HasInterestArea && m_PatrolTargetSet)
            {
                var targetDistance = (m_PatrolTargetPoint - position).GetHorizontalMagnitude();
                var headingThere = m_ObjectiveType == ObjectiveType.Patrol
                    && (m_ObjectivePosition - m_PatrolTargetPoint).GetHorizontalMagnitude() < 1f;
                if (IsPatrolPointSeen(m_PatrolTargetPoint, position, 5f))
                {
                    MarkPatrolRoomVisited(m_PatrolTargetPoint, now);
                    m_PatrolRouteFailures = 0;
                    NoteAreaProgress(now);
                    // A city takes longer than 7 min building by building:
                    // every point reached keeps the area 2 min more.
                    m_InterestAreaExpiresAt = Mathf.Min(
                        Mathf.Max(m_InterestAreaExpiresAt, now + 120f),
                        m_InterestAreaStartedAt + InterestAreaMaxSeconds);
                    m_PatrolTargetSet = false;
                }
                else if (headingThere && now >= m_ObjectiveExpiresAt)
                {
                    NotePatrolPointFailed(m_PatrolTargetPoint, now, "30s sem chegar", false);
                    m_PatrolTargetSet = false;
                }
                else if (headingThere && targetDistance <= 5f)
                {
                    // Under or over the point, or a wall between: the route
                    // goes on round to the stairs or the door. 10s that close
                    // without getting there and it leads nowhere.
                    if (m_PatrolNearSince <= 0f)
                    {
                        m_PatrolNearSince = now;
                        m_PatrolNearBestLeft = float.MaxValue;
                    }
                    // 0.2.2x11: the visit order takes the next room by the
                    // walk, often through a door with the point 3-4m away
                    // behind the wall: still getting closer along the route
                    // is not "near without getting there".
                    var routeLeft = GetRouteMetersLeft(position);
                    if (routeLeft >= 0f && routeLeft < m_PatrolNearBestLeft - 0.5f)
                    {
                        m_PatrolNearBestLeft = routeLeft;
                        m_PatrolNearSince = now;
                    }
                    if (now - m_PatrolNearSince < (Tryhard ? 3f : 10f))
                    {
                        return;
                    }
                    NotePatrolPointFailed(m_PatrolTargetPoint, now, (Tryhard ? "3s" : "10s") + " perto sem chegar: outro andar ou atras de parede", true);
                    m_PatrolTargetSet = false;
                }
            }
            if (!m_HasInterestArea || now >= m_InterestAreaExpiresAt)
            {
                FinishInterestArea(now);
                ChooseExplorationObjective(position, now);
                return;
            }

            if (m_AreaLootPoints.Count > 0)
            {
                if (m_VisitedPatrolPoints.Count > 2000)
                {
                    m_VisitedPatrolPoints.Clear();
                }
                var found = false;
                var best = Vector3.zero;
                var bestDistance = float.MaxValue;
                m_SweepCandidates.Clear();
                foreach (var point in m_AreaLootPoints)
                {
                    if (m_VisitedPatrolPoints.TryGetValue(point, out var until) && now < until)
                    {
                        continue;
                    }
                    var distance = (point - position).magnitude;
                    if (IsPatrolPointSeen(point, position, 2.5f))
                    {
                        m_VisitedPatrolPoints[point] = now + PatrolVisitedSeconds;
                        continue;
                    }
                    if (IsNearOrbitBadSpot(point, now, OrbitBadSpotMeters)
                        || IsInRememberedIsland(point, now))
                    {
                        m_VisitedPatrolPoints[point] = now + OrbitBadSpotSeconds;
                        continue;
                    }
                    // 0.2.2c: skipped this round only; the Mega walks off.
                    if (IsWithinMegaReach(point))
                    {
                        continue;
                    }
                    // Finish the house the bot is in before the next one.
                    var score = m_PatrolBuilding == null || m_PatrolBuilding.Contains(point, 0.25f)
                        ? distance
                        : distance + 1000f;
                    // 0.2.2w (doc 14.3, item 2): the whole floor before the
                    // next one, and the next floor in the same direction.
                    if (Tryhard)
                    {
                        score += GetFloorChangeCost(point.y - position.y);
                    }
                    // 0.1.173: last, not never: where the bot just escaped
                    // from (20s) and where a horde was seen (2 min).
                    if (IsAvoidedAfterEscape(point, now) || IsInHordeMemory(point, HordeAvoidMeters))
                    {
                        score += 500f;
                    }
                    else
                    {
                        // 0.2.2x11: the points the visit order may take.
                        m_SweepCandidates.Add(point);
                    }
                    if (score >= bestDistance || IsHazardousPosition(point, now, 2f))
                    {
                        continue;
                    }
                    bestDistance = score;
                    best = point;
                    found = true;
                }
                if (!found)
                {
                    var left = CountUnvisitedAreaPoints(now);
                    BotLog(LogLevel.Information,
                        "Area {Area} vasculhada em {Seconds:0}s: {Visited} de {Count} ponto(s) de loot visitados, {GivenUp} sem acesso, {Left} deixados por perigo; escolhendo outra area.",
                        m_InterestAreaName,
                        now - m_InterestAreaStartedAt,
                        m_AreaLootPoints.Count - left - m_AreaPointsGivenUp,
                        m_AreaLootPoints.Count,
                        m_AreaPointsGivenUp,
                        left);
                    m_StatWindowAreas++;
                    FinishInterestArea(now);
                    ChooseExplorationObjective(position, now);
                    return;
                }
                // 0.2.2x11: the nearest point was taken again at every pick,
                // in a straight line through the walls, and counted as seen
                // from 5m: the next one was often behind the bot, a new route
                // each time (llo and thigas at the Arlington Farm house,
                // the tester's back and forth). Now one visit order per floor of
                // the house, by the walk, kept until the floor is done.
                best = PickSweepPoint(position, best, now);
                // 0.2.2w (doc 14.3, item 4): the hunting sweep stays on the
                // street (Office #1, Apartment #3 and #4 were entered in Seattle).
                var building = IsHuntSweep ? null : SkaliaBotStructureMap.FindBuilding(best);
                if (Tryhard && Mathf.Abs(best.y - position.y) > TryhardFloorMeters)
                {
                    m_PatrolFloorDirection = best.y > position.y ? 1 : -1;
                }
                if (building != null && building != m_PatrolBuilding)
                {
                    m_PatrolFloorDirection = 0;
                    m_PatrolBuilding = building;
                    var inside = building.Contains(position, 0.5f);
                    if (!inside && TryPickDoorway(position, building, out var doorway))
                    {
                        BotLog(LogLevel.Information,
                            "Vasculhando {Name}: {Count} ponto(s) de loot; entrando pela entrada em {Doorway} ({Distance:0}m).",
                            building.Name,
                            building.LootPoints.Count,
                            FormatPosition(doorway),
                            (doorway - position).GetHorizontalMagnitude());
                        SetObjective(ObjectiveType.Patrol, doorway, now + 30f);
                        m_PatrolTargetSet = false;
                        return;
                    }
                    BotLog(LogLevel.Information,
                        "Vasculhando {Name}: {Count} ponto(s) de loot ({Where}).",
                        building.Name,
                        building.LootPoints.Count,
                        inside ? "ja dentro" : building.Doorways.Count == 0 ? "sem entrada conhecida" : "entrada fora da rota");
                }
                // The room counts once the bot stands in it (MarkPatrolRoomVisited).
                if (!m_PatrolTargetSet || (m_PatrolTargetPoint - best).sqrMagnitude > 0.01f)
                {
                    m_PatrolNearSince = 0f;
                }
                SetObjective(ObjectiveType.Patrol, best, now + 30f);
                m_PatrolTargetPoint = best;
                m_PatrolTargetSet = true;
                return;
            }

            var chosen = m_InterestAreaCenter;
            for (var attempt = 0; attempt < 16; attempt++)
            {
                var direction = Quaternion.Euler(0f, Random.Range(0f, 360f), 0f)
                    * Vector3.forward;
                var requested = m_InterestAreaCenter + direction * Random.Range(5f, 45f);
                var candidate = FindNearestNavigablePoint(requested);
                // Off the mesh the point snaps to its edge: all such points
                // landed on one border line far from the buildings.
                if ((candidate - requested).GetHorizontalMagnitude() > 3f
                    || WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                    || IsHazardousPosition(candidate, now, 2f)
                    || !IsInsideInterestArea(candidate, 0f)
                    || (candidate - position).GetHorizontalMagnitude() < 10f)
                {
                    continue;
                }

                chosen = candidate;
                break;
            }

            SetObjective(ObjectiveType.Patrol, chosen, now + 30f);
        }

        private void ConsiderExplorationCandidate(
            Vector3 origin,
            Vector3 candidate,
            string candidateName,
            float minimumDistance,
            float maximumDistance,
            float now,
            GraphNode originNode,
            ref Vector3 selected,
            ref string selectedName,
            ref string selectedKey,
            ref int candidateCount,
            ref int blacklistedCount,
            ref int missingNodeCount,
            ref int disconnectedCount,
            bool countLoot = true,
            bool forced = false)
        {
            var destinationKey = BuildExplorationDestinationKey(candidateName, candidate);
            // An island no piece of dry mesh reaches: every bot kept picking
            // it (Rainbridge Island, 133 searches in the Washington test).
            if (SkaliaBotUnityNavmesh.MapFilled
                && SkaliaBotUnityNavmesh.IsKnownUnreachable(m_Player.transform.position, candidate))
            {
                blacklistedCount++;
                return;
            }
            if (s_FailedTripAreas.TryGetValue(destinationKey, out var failedTripUntil)
                && now < failedTripUntil)
            {
                blacklistedCount++;
                return;
            }
            if (m_ExplorationDestinationBlacklist.TryGetValue(
                    destinationKey,
                    out var blacklistedUntil))
            {
                if (now < blacklistedUntil)
                {
                    blacklistedCount++;
                    return;
                }

                m_ExplorationDestinationBlacklist.Remove(destinationKey);
            }

            // 0.2.1: the Mega's spawn is a goal of its own: a finished,
            // looted or danger area does not stop the trip there.
            if (!forced)
            {
                foreach (var finished in m_FinishedAreas)
                {
                    if (now < finished.Value
                        && (candidate - finished.Key).GetHorizontalMagnitude() < InterestAreaRadiusMeters)
                    {
                        blacklistedCount++;
                        return;
                    }
                }
                if (IsAreaLootedByAnyBot(candidate, now))
                {
                    blacklistedCount++;
                    return;
                }

                if (IsInDangerZone(candidate, DangerZoneAreaMeters))
                {
                    blacklistedCount++;
                    return;
                }
            }

            // With the whole new mesh built, a place is a candidate when the
            // mesh has floor there; the route to the one picked is checked
            // when the bot sets off. The zombie graph is cut in thousands of
            // pieces: 1190 times in the 0.1.123 test it called every area of
            // the map unreachable and the bot only wandered around.
            // Only within reach of a route on the new mesh: an area farther
            // away is walked to on the zombie graph, which can't get there
            // when the two are in different pieces. In the 0.1.131 test 496
            // trips to such areas failed at once ("no valid path") and the
            // bots kept exploring around the same camp.
            if (SkaliaBotUnityNavmesh.MapFilled
                && (candidate - origin).GetHorizontalMagnitude() <= MeshExplorationMeters
                && SkaliaBotUnityNavmesh.TrySnap(candidate, MaximumDestinationNodeSnapMeters, out var onMesh))
            {
                candidate = onMesh;
            }
            else
            {
                var nearest = AstarPath.active.GetNearest(candidate, NNConstraint.Walkable);
                var graphReaches = nearest.node != null
                    && (nearest.position - candidate).GetHorizontalMagnitude() <= MaximumDestinationNodeSnapMeters
                    && PathUtilities.IsPathPossible(originNode, nearest.node);
                if (graphReaches)
                {
                    candidate = nearest.position;
                }
                // The zombie graph is cut in thousands of pieces (6134 areas
                // "disconnected" from Camp Oleksandr in the 0.1.135 test): a
                // bot that had searched its camp wandered there instead of
                // leaving. With the whole new mesh built, a farther place on
                // it is a candidate too, reached by a trip over the terrain.
                // The flag's trips already failed (17:05 in the 0.1.141 test:
                // the same area 4 times in 10s while banned for 2 h).
                else if (SkaliaBotUnityNavmesh.MapFilled
                         && (candidate - origin).GetHorizontalMagnitude() <= TravelMaximumMeters
                         && !IsTravelGraphBlocked(nearest.node, now)
                         && SkaliaBotUnityNavmesh.TrySnap(candidate, MaximumDestinationNodeSnapMeters, out var farOnMesh))
                {
                    candidate = farOnMesh;
                }
                else
                {
                    if (nearest.node == null
                        || (nearest.position - candidate).GetHorizontalMagnitude() > MaximumDestinationNodeSnapMeters)
                    {
                        missingNodeCount++;
                    }
                    else
                    {
                        disconnectedCount++;
                    }
                    return;
                }
            }
            if (WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f))
            {
                return;
            }
            if (IsHazardousPosition(candidate, now, 2f) || IsRadiationClosedFor(candidate, 15f))
            {
                return;
            }

            var distance = (candidate - origin).GetHorizontalMagnitude();
            if (distance < minimumDistance || distance > maximumDistance)
            {
                return;
            }

            candidateCount++;
            // Nearer areas weigh more: a uniform pick sent the bot across the map.
            // 0.1.168: and richer ones too, loot per distance: a farm with three
            // crates weighed as much as a city at the same distance. An area
            // another bot is searching now weighs a fifth.
            var clampedDistance = Mathf.Max(distance, 60f);
            var spawnCount = countLoot ? GetAreaSpawnCount(destinationKey, candidate) : 0;
            var weight = (spawnCount + 5f) / (clampedDistance * clampedDistance);
            if (IsAreaClaimedByOtherBot(destinationKey, now))
            {
                weight *= 0.2f;
            }
            // 0.2.1: and by what the bot's gear lacks there (SkaliaBotGoals).
            if (countLoot)
            {
                weight *= GetAreaGoalWeight(destinationKey, candidate);
            }
            m_ExplorationWeightTotal += weight;
            if (Random.value * m_ExplorationWeightTotal <= weight)
            {
                selected = candidate;
                selectedName = candidateName;
                selectedKey = destinationKey;
            }
        }

        // Walking a lot without getting anywhere: the bot is circling a point it
        // cannot reach (a waypoint on another floor, an item under a shelf).
        // the tester would rather see a bot stand still while it works out the way
        // than run circles: every detected circle stops it for 1.5s while the
        // route is recalculated.
        private const float OrbitThinkSeconds = 1.5f;
        private float m_ThinkUntil;
        private float m_NextTerrainWaitLogAt;

        // 24 of the 93 circles of the last log had a fight inside the 8s
        // window and the objective only changed back at its end: kiting a
        // zombie, fleeing or picking up its drop is not a circle, but each
        // one marked a bad spot that routes then refused for 10 min.
        private bool m_OrbitWindowBusy;
        private Vector3 m_OrbitLastTarget;
        private (int Jumps, int Reversals, float Turn) m_OrbitWindowCounters;
        private readonly Dictionary<string, int> m_OrbitJumpSources = new Dictionary<string, int>();
        private string m_OrbitWindowSources = "nenhuma";
        private readonly Dictionary<string, int> m_OrbitClearSources = new Dictionary<string, int>();
        private string m_OrbitWindowClears = "nenhuma";
        private int m_OrbitLastGeneration;
        private int m_OrbitNewRoutes;
        private int m_OrbitWindowNewRoutes;
        private ObjectiveType m_OrbitLastObjective;
        private int m_OrbitObjectiveChanges;
        private int m_OrbitWindowObjectiveChanges;

        private void CloseOrbitWindowCounters()
        {
            m_OrbitWindowCounters = (m_OrbitTargetJumps, m_OrbitReversals, m_OrbitTurnDegrees);
            m_OrbitTargetJumps = m_OrbitReversals = 0;
            m_OrbitTurnDegrees = 0f;
            var sources = new System.Text.StringBuilder();
            foreach (var entry in m_OrbitJumpSources)
            {
                if (sources.Length > 0)
                {
                    sources.Append(", ");
                }
                sources.Append(entry.Key).Append(' ').Append(entry.Value);
            }
            m_OrbitWindowSources = sources.Length > 0 ? sources.ToString() : "nenhuma";
            m_OrbitJumpSources.Clear();
            var clears = new System.Text.StringBuilder();
            foreach (var entry in m_OrbitClearSources)
            {
                if (clears.Length > 0)
                {
                    clears.Append(", ");
                }
                clears.Append(entry.Key).Append(' ').Append(entry.Value);
            }
            m_OrbitWindowClears = clears.Length > 0 ? clears.ToString() : "nenhuma";
            m_OrbitClearSources.Clear();
            m_OrbitWindowNewRoutes = m_OrbitNewRoutes;
            m_OrbitNewRoutes = 0;
            m_OrbitWindowObjectiveChanges = m_OrbitObjectiveChanges;
            m_OrbitObjectiveChanges = 0;
        }
        private int m_OrbitTargetJumps;
        private int m_OrbitReversals;
        private float m_OrbitTurnDegrees;
        private Vector3 m_OrbitLastHeading;
        private Vector3 m_OrbitHeadingFrom;
        private float m_OrbitNextHeadingSample;

        private void MarkOrbitWindowBusy()
        {
            m_OrbitWindowBusy = true;
        }

        // 0.1.170: the height walked in the window. In the 0.1.169 test 20
        // of the 75 "circles" were up a floor or on stairs (XXlloqiartyXX
        // "circled" 4 times in a minute going up and down the Arlington Farm
        // barn), and 18 more had one single turn back: going for an item and
        // coming back. Each false alarm marked the spot bad for 10 min,
        // skipped a corner and, the third time, dropped the objective.
        private const float OrbitClimbMeters = 1.5f;
        private const float OrbitMinimumTurnDegrees = 300f;
        private float m_OrbitMinY = float.MaxValue;
        private float m_OrbitMaxY = float.MinValue;

        private void UpdateOrbitDetector(Vector3 position, Vector3 navigationTarget, float now)
        {
            m_OrbitMinY = Mathf.Min(m_OrbitMinY, position.y);
            m_OrbitMaxY = Mathf.Max(m_OrbitMaxY, position.y);
            var stepVector = position - m_OrbitLastPosition;
            stepVector.y = 0f;
            var step = stepVector.magnitude;
            m_OrbitLastPosition = position;
            if (step < 2f)
            {
                m_OrbitTravel += step;
            }
            // 0.1.95 showed the bot facing its target with W held at every
            // circle: no turning arc. Count what moved instead: the target
            // jumping and the walk turning back on itself.
            if ((navigationTarget - m_OrbitLastTarget).GetHorizontalMagnitude() > 1.5f)
            {
                m_OrbitTargetJumps++;
                var source = DescribeNavigationTargetSource(navigationTarget, now);
                m_OrbitJumpSources.TryGetValue(source, out var seen);
                m_OrbitJumpSources[source] = seen + 1;
            }
            if (m_OrbitLastGeneration != m_PathRequestGeneration)
            {
                m_OrbitLastGeneration = m_PathRequestGeneration;
                m_OrbitNewRoutes++;
            }
            if (m_OrbitLastObjective != m_ObjectiveType)
            {
                m_OrbitLastObjective = m_ObjectiveType;
                m_OrbitObjectiveChanges++;
            }
            m_OrbitLastTarget = navigationTarget;
            if (now >= m_OrbitNextHeadingSample && (position - m_OrbitHeadingFrom).GetHorizontalMagnitude() > 0.8f)
            {
                var heading = position - m_OrbitHeadingFrom;
                heading.y = 0f;
                heading.Normalize();
                if (m_OrbitLastHeading.sqrMagnitude > 0.5f)
                {
                    var dot = Vector3.Dot(heading, m_OrbitLastHeading);
                    if (dot < -0.5f)
                    {
                        m_OrbitReversals++;
                    }
                    m_OrbitTurnDegrees += Vector3.Angle(m_OrbitLastHeading, heading);
                }
                m_OrbitLastHeading = heading;
                m_OrbitHeadingFrom = position;
                m_OrbitNextHeadingSample = now + 0.5f;
            }
            if (m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || m_ObjectiveType == ObjectiveType.Flee
                || m_ObjectiveType == ObjectiveType.EscapeHazard
                || m_ObjectiveType == ObjectiveType.RepositionFire
                || IsPvpPlanted())
            {
                // 0.2.2y6: the steps to the sides in a gunfight are not a
                // bot walking in circles (test of 17/11, Ghost at 41-49m).
                m_OrbitWindowBusy = true;
            }
            if (m_OrbitWindowBusy)
            {
                if (now - m_OrbitWindowStart >= 8f)
                {
                    m_OrbitWindowStart = now;
                    m_OrbitStartPosition = position;
                    m_OrbitTravel = 0f;
                    m_OrbitMinY = m_OrbitMaxY = position.y;
                    CloseOrbitWindowCounters();
                    m_OrbitWindowBusy = false;
                }
                return;
            }
            // A quick look after 4s: 10m walked for under 2m gained is already
            // a circle; the bot stops to think instead of running 8s more.
            var quickOrbit = now - m_OrbitWindowStart >= 4f
                && m_OrbitTravel >= 10f
                && (position - m_OrbitStartPosition).GetHorizontalMagnitude() < 2f;
            if (now - m_OrbitWindowStart < 8f && !quickOrbit)
            {
                return;
            }
            var net = (position - m_OrbitStartPosition).GetHorizontalMagnitude();
            var travel = m_OrbitTravel;
            var climb = m_OrbitMaxY - m_OrbitMinY;
            m_OrbitWindowStart = now;
            m_OrbitStartPosition = position;
            m_OrbitTravel = 0f;
            m_OrbitMinY = m_OrbitMaxY = position.y;
            CloseOrbitWindowCounters();
            if (travel < 12f
                || net >= 3f
                || climb >= OrbitClimbMeters
                || (m_OrbitWindowCounters.Reversals <= 1 && m_OrbitWindowCounters.Turn < OrbitMinimumTurnDegrees)
                || m_ObjectiveType == ObjectiveType.None
                || m_ObjectiveType == ObjectiveType.Combat
                || m_ObjectiveType == ObjectiveType.EscapeSwarm
                || m_ObjectiveType == ObjectiveType.Unstuck)
            {
                return;
            }
            m_OrbitCount = now - m_LastOrbitAt <= 60f ? m_OrbitCount + 1 : 1;
            m_LastOrbitAt = now;
            m_StatWindowCircles++;
            // Switching to the zombie mesh for 60s after a circle on the new
            // one put the bot back under the wall detours that made 968 of the
            // 980 local detours of the 0.1.100 log: stay on the new mesh.
            m_ThinkUntil = now + (Tryhard ? 0.5f : OrbitThinkSeconds);
            BotLog(LogLevel.Information,
                "Andando em circulo: {Travel:0}m percorridos e {Net:0.#}m de deslocamento em 8s em {Position}; objetivo {Objective} a {ObjectiveDistance:0.#}m; alvo da navegacao {Target} a {TargetDistance:0.#}m (altura {Dy:0.#}m); rota {Index}/{Count}; desvio de parede {Wall}; vez {Count2}; tecla {Key} (corpo {Yaw:0} graus, quer {DesiredYaw:0}), correndo {Sprint}, manobra local {Recovery}, no chao {Grounded}; nos 8s: alvo pulou {Jumps} vezes, voltou para tras {Reversals} vezes, girou {Turn:0} graus; trocas de alvo por origem: {Sources}; rotas novas {Routes} (rota jogada fora por: {Clears}); trocas de objetivo {Objectives}.",
                travel,
                net,
                FormatPosition(position),
                m_ObjectiveType,
                (m_ObjectivePosition - position).GetHorizontalMagnitude(),
                FormatPosition(navigationTarget),
                (navigationTarget - position).GetHorizontalMagnitude(),
                navigationTarget.y - position.y,
                m_PathIndex,
                m_PathPoints.Count,
                m_WallAvoidanceActive,
                m_OrbitCount,
                DescribeMovementAnalog(GetCurrentMovementAnalog()),
                Mathf.Repeat(m_CurrentYaw, 360f),
                Mathf.Repeat(m_DesiredYaw, 360f),
                m_IsSprinting,
                m_LocalRecoveryPhase,
                m_Player.movement.isGrounded,
                m_OrbitWindowCounters.Jumps,
                m_OrbitWindowCounters.Reversals,
                m_OrbitWindowCounters.Turn,
                m_OrbitWindowSources,
                m_OrbitWindowNewRoutes,
                m_OrbitWindowClears,
                m_OrbitWindowObjectiveChanges);
            MarkOrbitBadSpot(position, now);
            var orbitsHere = CountOrbitsHere(position, now);
            if (orbitsHere >= OrbitSpotTeleportCount && TryTeleportOutOfOrbitSpot(position, now, orbitsHere))
            {
                return;
            }
            if (orbitsHere >= OrbitSpotWalkOutCount && TryWalkOutOfOrbitSpot(position, now, orbitsHere))
            {
                return;
            }
            if (m_OrbitCount < 3 && TryStepAwayFromFurniture(position, now))
            {
                ClearPath();
                m_NextPathRequestTime = 0f;
                return;
            }
            if (TryEscapeIslandOnOrbit(position, navigationTarget, now))
            {
                ClearPath();
                return;
            }
            // The return point to the mesh is the nearest node, which can be
            // behind a fence: 4 min circling it at Vladimir Farm.
            if (m_HasNavmeshReturnPoint
                && (navigationTarget - m_NavmeshReturnPoint).GetHorizontalMagnitude() < 0.1f)
            {
                m_HasNavmeshReturnPoint = false;
                m_SkipNavmeshReturnUntil = now + 30f;
                ClearPath();
                m_NextPathRequestTime = 0f;
                return;
            }
            if (TryBlockUnclimbableStep(position, now))
            {
                ClearPath();
                m_NextPathRequestTime = 0f;
                m_DirectFallbackUntil = 0f;
                m_WallAvoidanceActive = false;
                // A step too high in a pit: the ladder next to it is the way up.
                if (m_Ladder == null && AstarPath.active != null)
                {
                    var stepNode = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
                    if (stepNode != null && TryStartLadderEscape(position, now, stepNode.Area, "degrau alto demais", allowSameArea: true))
                    {
                        return;
                    }
                }
                if (m_OrbitCount >= 3)
                {
                    AbandonCurrentObjective(now);
                }
                return;
            }
            BotLog(LogLevel.Information,
                "Circulo em {Position}: alvo vem de {Source}; proximos pontos da rota {Waypoints}; ponto marcado como ruim por {Minutes:0} min. Objetos perto: {Objects}. Na frente, rumo a {Ahead}: {Blockers}.",
                FormatPosition(position),
                DescribeNavigationTargetSource(navigationTarget, now),
                DescribeNextWaypoints(position),
                OrbitBadSpotSeconds / 60f,
                SkaliaBotObjectMap.DescribeNear(position, 3f),
                FormatPosition(OrbitProbeTarget(navigationTarget)),
                DescribeBlockersAhead(position, OrbitProbeTarget(navigationTarget)));
            if (m_OrbitCount >= 3)
            {
                AbandonCurrentObjective(now);
                return;
            }
            if (m_PathIndex < m_PathPoints.Count - 1)
            {
                m_PathIndex++;
            }
            else
            {
                ClearPath();
            }
            m_DirectFallbackUntil = 0f;
            m_WallAvoidanceActive = false;
        }

        // Among boulders at (-1705, 93, -303) thigas circled 60 times in 6
        // minutes: every circle dropped the objective and the next one led
        // back in. Circles counted by place, not by objective: the 3rd within
        // 5m in 2 minutes walks straight to open mesh ground nearby, the 5th
        // teleports (SAIN's last resort: to the next point of the route).
        private const int OrbitSpotWalkOutCount = 3;
        private const int OrbitSpotTeleportCount = 5;
        private const float OrbitSpotMeters = 5f;
        // XXlloqiartyXX circled for 5 min in the roundhouse pit at (713, -690):
        // the circles spread 9m apart, so the 5m count never reached 5.
        private const float OrbitSpotCountMeters = 10f;
        private const float OrbitSpotSeconds = 120f;
        private readonly List<(Vector3 Position, float At)> m_OrbitSpots = new List<(Vector3 Position, float At)>();

        private int CountOrbitsHere(Vector3 position, float now)
        {
            m_OrbitSpots.RemoveAll(spot => now - spot.At > OrbitSpotSeconds);
            m_OrbitSpots.Add((position, now));
            var count = 0;
            foreach (var spot in m_OrbitSpots)
            {
                if ((spot.Position - position).GetHorizontalMagnitude() <= OrbitSpotCountMeters)
                {
                    count++;
                }
            }
            return count;
        }

        private bool TryWalkOutOfOrbitSpot(Vector3 position, float now, int orbits)
        {
            if (!SkaliaBotUnityNavmesh.TryFindEscapePoint(position, m_ObjectivePosition - position, out var exit))
            {
                return false;
            }
            BotLog(LogLevel.Information,
                "{Count} circulos em ate {Meters:0}m em {Seconds:0}s; saindo andando em linha reta para chao livre em {Exit} ({Distance:0.0}m).",
                orbits,
                OrbitSpotMeters,
                OrbitSpotSeconds,
                FormatPosition(exit),
                (exit - position).GetHorizontalMagnitude());
            ClearPath();
            m_DirectFallbackUntil = 0f;
            m_WallAvoidanceActive = false;
            m_HasNavmeshReturnPoint = true;
            m_NavmeshReturnPoint = exit;
            m_NavmeshReturnUntil = now + 8f;
            m_NextPathRequestTime = now + 8f;
            return true;
        }

        private bool TryTeleportOutOfOrbitSpot(Vector3 position, float now, int orbits)
        {
            Vector3? destination = null;
            for (var index = m_PathIndex; index < m_PathPoints.Count; index++)
            {
                var distance = (m_PathPoints[index] - position).GetHorizontalMagnitude();
                if (distance > 30f)
                {
                    break;
                }
                if (distance > OrbitSpotMeters)
                {
                    destination = m_PathPoints[index];
                    break;
                }
            }
            if (destination == null
                && SkaliaBotUnityNavmesh.TryFindEscapePoint(position, m_ObjectivePosition - position, out var exit)
                && (exit - position).GetHorizontalMagnitude() > OrbitSpotMeters)
            {
                destination = exit;
            }
            if (destination == null
                && SkaliaBotUnityNavmesh.TryFindTeleportPoint(position, m_ObjectivePosition, out var floor))
            {
                destination = floor;
            }
            if (destination == null)
            {
                return false;
            }
            BotLog(LogLevel.Warning,
                "{Count} circulos em ate {Meters:0}m em {Seconds:0}s em {Position}; teleportando para {Destination} ({Distance:0}m).",
                orbits,
                OrbitSpotMeters,
                OrbitSpotSeconds,
                FormatPosition(position),
                FormatPosition(destination.Value),
                (destination.Value - position).magnitude);
            m_OrbitSpots.Clear();
            ClearPath();
            TeleportBot(destination.Value + Vector3.up * 0.3f, m_Player.look.yaw);
            m_StallAnchor = destination.Value;
            m_NextPathRequestTime = 0f;
            return true;
        }

        // A* walks steps the player capsule cannot climb: a 1.9m ledge next
        // to a train car held a bot for 5 min, a 3.3m bank under a bridge
        // another one. The waypoint only counts as reached within 1.8m of
        // height, so the bot circled under it. The node above is closed to
        // routes for 10 min so A* takes another way up.
        private sealed class BlockedNodeTraversalProvider : ITraversalProvider
        {
            private readonly Dictionary<GraphNode, float> m_Until = new Dictionary<GraphNode, float>();
            private readonly List<GraphNode> m_Expired = new List<GraphNode>();

            public bool HasAny => m_Until.Count > 0;

            public void Block(GraphNode node, float until)
            {
                m_Until[node] = until;
            }

            // A* may search on its own thread: each request gets a copy.
            public BlockedNodeTraversalProvider Snapshot()
            {
                var copy = new BlockedNodeTraversalProvider();
                foreach (var entry in m_Until)
                {
                    copy.m_Until[entry.Key] = entry.Value;
                }
                return copy;
            }

            public void Prune(float now)
            {
                m_Expired.Clear();
                foreach (var entry in m_Until)
                {
                    if (now >= entry.Value)
                    {
                        m_Expired.Add(entry.Key);
                    }
                }
                foreach (var node in m_Expired)
                {
                    m_Until.Remove(node);
                }
            }

            public bool CanTraverse(Path path, GraphNode node)
            {
                return DefaultITraversalProvider.CanTraverse(path, node) && !m_Until.ContainsKey(node);
            }

            public uint GetTraversalCost(Path path, GraphNode node)
            {
                // Mesh draped over a boulder (the floor under it is lower):
                // routes go around unless the boulder is where they end.
                return DefaultITraversalProvider.GetTraversalCost(path, node)
                    + (SkaliaBotNavmeshAudit.IsFalseFloor(node) || SkaliaBotObjectMap.IsOnFurniture(node)
                        ? FalseFloorPenalty
                        : 0u)
                    + (SkaliaBotNavmeshAudit.IsBodyBlocked(node) ? BodyBlockedPenalty : 0u);
            }
        }

        // Ground halfway between the feet and the higher point sits halfway
        // up too: a slope, not a ledge.
        private static bool IsRampBetween(Vector3 position, Vector3 point)
        {
            var middle = (position + point) * 0.5f;
            if (!Physics.Raycast(
                    new Vector3(middle.x, point.y + 0.5f, middle.z),
                    Vector3.down,
                    out var hit,
                    point.y - position.y + 1f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore))
            {
                return false;
            }
            var rise = point.y - position.y;
            return hit.normal.y >= WalkableSlopeNormalY
                && hit.point.y > position.y + rise * 0.25f
                && hit.point.y < point.y - rise * 0.25f;
        }

        private bool TryBlockUnclimbableStep(Vector3 position, float now)
        {
            if (AstarPath.active == null)
            {
                return false;
            }
            for (var i = m_PathIndex; i < m_PathPoints.Count && i < m_PathIndex + 3; i++)
            {
                var point = m_PathPoints[i];
                var rise = point.y - position.y;
                if ((point - position).GetHorizontalMagnitude() > 6f || rise < BlockedStepMinimumRise)
                {
                    continue;
                }
                if (IsRampBetween(position, point))
                {
                    // A ramp climbs the same height without a step.
                    continue;
                }
                var node = AstarPath.active.GetNearest(point, NNConstraint.Walkable).node;
                var botNode = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
                if (node == null || node == botNode)
                {
                    return false;
                }
                m_BlockedSteps.Block(node, now + BlockedStepSeconds);
                BotLog(LogLevel.Information,
                    "Degrau de {Rise:0.#}m em {Point} que o bot nao sobe; trecho da malha proibido nas rotas por {Minutes:0} min.",
                    rise,
                    FormatPosition(point),
                    BlockedStepSeconds / 60f);
                return true;
            }
            return false;
        }

        // St. Petersburg's metro has its exit up a ramp of boulders and debris
        // (52m to 65m); bots stood there for minutes, each stall ending in a
        // 2m teleport onto the same rocks. Three stuck teleports within 20m
        // in 5 min mark the spot, and underground the bot goes to the surface.
        private readonly List<Vector3> m_StuckTeleportPositions = new List<Vector3>();
        private readonly List<float> m_StuckTeleportTimes = new List<float>();
        private const float StuckZoneSeconds = 300f;
        private const float StuckZoneMeters = 20f;
        private const int StuckZoneCount = 3;

        private bool TryEscapeStuckZone(Vector3 position, float now)
        {
            for (var i = m_StuckTeleportTimes.Count - 1; i >= 0; i--)
            {
                if (now - m_StuckTeleportTimes[i] > StuckZoneSeconds)
                {
                    m_StuckTeleportTimes.RemoveAt(i);
                    m_StuckTeleportPositions.RemoveAt(i);
                }
            }
            m_StuckTeleportTimes.Add(now);
            m_StuckTeleportPositions.Add(position);
            var nearby = 0;
            foreach (var stuck in m_StuckTeleportPositions)
            {
                if ((stuck - position).GetHorizontalMagnitude() <= StuckZoneMeters)
                {
                    nearby++;
                }
            }
            if (nearby < StuckZoneCount)
            {
                return false;
            }
            m_StuckTeleportTimes.Clear();
            m_StuckTeleportPositions.Clear();
            MarkOrbitBadSpot(position, now);
            var ground = LevelGround.getHeight(position);
            if (ground < position.y + 4f || !SkaliaBotUnityNavmesh.MapFilled)
            {
                BotLog(LogLevel.Information,
                    "Bot travou {Count} vezes em 5 min perto de {Position}; trecho marcado como ruim por 10 min.",
                    nearby,
                    FormatPosition(position));
                return false;
            }
            for (var radius = 0f; radius <= 48f; radius += 4f)
            {
                for (var step = 0; step < 16; step++)
                {
                    var direction = Quaternion.Euler(0f, step * 22.5f, 0f) * Vector3.forward;
                    var probe = position + direction * radius;
                    var height = LevelGround.getHeight(probe);
                    var nearest = SnapToNewMesh(new Vector3(probe.x, height, probe.z), 3f);
                    if (!nearest.found
                        || nearest.position.y < height - 1.5f
                        || (nearest.position - probe).GetHorizontalMagnitude() > 3f
                        || WaterUtility.isPointUnderwater(nearest.position + Vector3.up * 0.5f))
                    {
                        continue;
                    }
                    BotLog(LogLevel.Warning,
                        "Bot preso no subsolo em {Position} ({Count} travamentos em 5 min, chao {Depth:0.#}m acima); subindo para {Destination}; trecho marcado como ruim por 10 min.",
                        FormatPosition(position),
                        nearby,
                        ground - position.y,
                        FormatPosition(nearest.position));
                    m_LocalRecoveryPhase = LocalRecoveryPhase.None;
                    ClearObjective();
                    TeleportBot(nearest.position + Vector3.up * 0.3f, m_Player.look.yaw);
                    m_StallAnchor = nearest.position;
                    m_NextExplorationSelectionTime = 0f;
                    return true;
                }
            }
            return false;
        }

        private void MarkOrbitBadSpot(Vector3 position, float now)
        {
            for (var i = 0; i < s_OrbitBadSpots.Count; i++)
            {
                if ((s_OrbitBadSpots[i] - position).GetHorizontalMagnitude() < 3f)
                {
                    s_OrbitBadSpotUntil[i] = now + OrbitBadSpotSeconds;
                    s_OrbitBadSpotBots[i].Add(m_Player);
                    return;
                }
            }
            s_OrbitBadSpots.Add(position);
            s_OrbitBadSpotUntil.Add(now + OrbitBadSpotSeconds);
            s_OrbitBadSpotBots.Add(new HashSet<Player> { m_Player });
        }

        private bool IsBadSpotForMe(int index)
        {
            if (!Tryhard)
            {
                return true;
            }
            var bots = s_OrbitBadSpotBots[index];
            return bots.Count >= 2 || bots.Contains(m_Player);
        }

        private bool IsNearOrbitBadSpot(Vector3 point, float now, float radius)
        {
            for (var i = s_OrbitBadSpots.Count - 1; i >= 0; i--)
            {
                if (now >= s_OrbitBadSpotUntil[i])
                {
                    s_OrbitBadSpots.RemoveAt(i);
                    s_OrbitBadSpotUntil.RemoveAt(i);
                    s_OrbitBadSpotBots.RemoveAt(i);
                    continue;
                }
                var spot = s_OrbitBadSpots[i];
                if (IsBadSpotForMe(i)
                    && (spot - point).GetHorizontalMagnitude() <= radius
                    && Mathf.Abs(spot.y - point.y) <= 4f)
                {
                    return true;
                }
            }
            return false;
        }

        // The bot circled 10 times at the same stair in Novosibirsk because
        // every new patrol route went through it again. Routes that pass a
        // spot where it already circled are refused, unless the spot is where
        // the route starts or ends.
        private bool PathCrossesOrbitBadSpot(List<Vector3> points, Vector3 origin, Vector3 destination, float now)
        {
            if (s_OrbitBadSpots.Count == 0 || points.Count < 2 || now < m_IgnoreBadSpotsUntil)
            {
                return false;
            }
            for (var i = 0; i < s_OrbitBadSpots.Count; i++)
            {
                if (now >= s_OrbitBadSpotUntil[i] || !IsBadSpotForMe(i))
                {
                    continue;
                }
                var spot = s_OrbitBadSpots[i];
                if ((spot - origin).GetHorizontalMagnitude() <= 8f
                    || (spot - destination).GetHorizontalMagnitude() <= 8f)
                {
                    continue;
                }
                for (var j = 1; j < points.Count; j++)
                {
                    if (Mathf.Abs(points[j].y - spot.y) > 4f && Mathf.Abs(points[j - 1].y - spot.y) > 4f)
                    {
                        continue;
                    }
                    if (HorizontalSegmentDistance(spot, points[j - 1], points[j]) <= 3f)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        private static float HorizontalSegmentDistance(Vector3 point, Vector3 a, Vector3 b)
        {
            var abX = b.x - a.x;
            var abZ = b.z - a.z;
            var apX = point.x - a.x;
            var apZ = point.z - a.z;
            var lengthSquared = abX * abX + abZ * abZ;
            var t = lengthSquared > 0.0001f
                ? Mathf.Clamp01((apX * abX + apZ * abZ) / lengthSquared)
                : 0f;
            var dx = apX - abX * t;
            var dz = apZ - abZ * t;
            return Mathf.Sqrt(dx * dx + dz * dz);
        }

        private string DescribeNavigationTargetSource(Vector3 navigationTarget, float now)
        {
            if (m_WallAvoidanceActive
                && (navigationTarget - m_WallAvoidanceTarget).GetHorizontalMagnitude() < 0.1f)
            {
                return "desvio de parede";
            }
            if (m_FurnitureDetourActive
                && (navigationTarget - m_FurnitureDetourTarget).GetHorizontalMagnitude() < 0.1f)
            {
                return "desvio de movel";
            }
            if (m_HasKnownInteriorExit
                && (navigationTarget - m_KnownInteriorExit).GetHorizontalMagnitude() < 0.1f)
            {
                return "saida conhecida da casa";
            }
            if (m_HasNavmeshReturnPoint
                && (navigationTarget - m_NavmeshReturnPoint).GetHorizontalMagnitude() < 0.1f)
            {
                return "volta para a malha";
            }
            if (now < m_DirectFallbackUntil)
            {
                return "objetivo direto (sem rota)";
            }
            if (m_PathIndex < m_PathPoints.Count
                && (navigationTarget - m_PathPoints[m_PathIndex]).GetHorizontalMagnitude() < 0.1f)
            {
                return "ponto da rota";
            }
            if ((navigationTarget - m_ObjectivePosition).GetHorizontalMagnitude() < 0.1f)
            {
                return "objetivo";
            }
            return "outro";
        }

        // The route's next point when there is one: the wall-avoidance
        // target is only where the bot was sent to get around.
        private Vector3 OrbitProbeTarget(Vector3 navigationTarget)
        {
            return m_PathIndex < m_PathPoints.Count ? m_PathPoints[m_PathIndex] : navigationTarget;
        }

        // What the body hits walking from here toward the target, at step,
        // knee, hip and head height: a circle at the back of a house in
        // Novosibirsk named only the bed upstairs.
        private static readonly float[] s_BlockerHeights = { 0.25f, 0.6f, 1.1f, 1.7f };

        private static string DescribeBlockersAhead(Vector3 position, Vector3 target)
        {
            var direction = target - position;
            direction.y = 0f;
            var distance = Mathf.Min(3f, direction.magnitude);
            if (distance < 0.2f)
            {
                return "alvo em cima do bot";
            }
            direction /= direction.magnitude;
            var text = new System.Text.StringBuilder();
            foreach (var height in s_BlockerHeights)
            {
                if (text.Length > 0)
                {
                    text.Append("; ");
                }
                text.Append(height.ToString("0.0#")).Append("m: ");
                if (!Physics.Raycast(position + Vector3.up * height, direction, out var hit, distance, RayMasks.BLOCK_COLLISION, QueryTriggerInteraction.Ignore))
                {
                    text.Append("livre");
                    continue;
                }
                var transform = hit.collider.transform;
                var name = SkaliaBotObjectMap.TryGetByCollider(hit.collider, out var mapObject)
                    ? mapObject.Name
                    : transform.root != transform ? transform.name + " (" + transform.root.name + ")" : transform.name;
                text.Append(name)
                    .Append(" a ").Append(hit.distance.ToString("0.0"))
                    .Append("m, normal y ").Append(hit.normal.y.ToString("0.0"))
                    .Append(", camada ").Append(LayerMask.LayerToName(hit.collider.gameObject.layer));
            }
            return text.ToString();
        }

        private string DescribeNextWaypoints(Vector3 position)
        {
            var text = new System.Text.StringBuilder();
            for (var i = m_PathIndex; i < m_PathPoints.Count && i < m_PathIndex + 4; i++)
            {
                var point = m_PathPoints[i];
                if (text.Length > 0)
                {
                    text.Append("; ");
                }
                text.Append(FormatPosition(point))
                    .Append(" a ")
                    .Append((point - position).GetHorizontalMagnitude().ToString("0.#"))
                    .Append("m altura ")
                    .Append((point.y - position.y).ToString("0.#"));
            }
            return text.Length > 0 ? text.ToString() : "nenhum";
        }

        // The entrance of the building nearest the bot that the route reaches.
        private bool TryPickDoorway(Vector3 position, BotBuilding building, out Vector3 doorway)
        {
            doorway = Vector3.zero;
            // 0.2.2x11: by the new mesh when it is whole (no zombie mesh).
            if (SkaliaBotUnityNavmesh.MapFilled)
            {
                return TryPickDoorwayOnMesh(position, building, out doorway);
            }
            if (AstarPath.active == null || building.Doorways.Count == 0)
            {
                return false;
            }
            var origin = AstarPath.active.GetNearest(position, NNConstraint.Walkable).node;
            if (origin == null)
            {
                return false;
            }
            var bestDistance = float.MaxValue;
            foreach (var candidate in building.Doorways)
            {
                var distance = (candidate - position).GetHorizontalMagnitude();
                if (distance < 3f
                    || distance >= bestDistance
                    || IsNearOrbitBadSpot(candidate, m_BehaviorNow, OrbitBadSpotMeters))
                {
                    continue;
                }
                var node = AstarPath.active.GetNearest(candidate, NNConstraint.Walkable).node;
                if (!CanReach(origin, node, position, candidate))
                {
                    continue;
                }
                bestDistance = distance;
                doorway = candidate;
            }
            return bestDistance < float.MaxValue;
        }

        // Like a player pressing the use key: a closed door, container or
        // fridge within reach is opened when the bot is heading to it or past it.
        private void TryOpenNearbyDoor(Vector3 position, float now)
        {
            if (now < m_NextDoorCheckAt || !SkaliaBotStructureMap.Ready)
            {
                return;
            }
            m_NextDoorCheckAt = now + 0.5f;
            BlockOpenContainerLeaves(position, now);
            var door = SkaliaBotStructureMap.FindClosedDoor(position, 2.5f);
            if (door == null || IsSkippedContainerDoor(door, position))
            {
                return;
            }
            // 0.2.2x8 (doc 16.16): running from the Mega the bot opened two
            // counters on the way, and every opening threw the route away
            // and planned again with the Mega closing. While escaping only a
            // real door (one that swings out of the way) is opened.
            if ((m_ObjectiveType == ObjectiveType.Flee
                    || m_ObjectiveType == ObjectiveType.EscapeSwarm
                    || m_ObjectiveType == ObjectiveType.EscapeHazard
                    || m_BossFleeActive)
                && !SkaliaBotUnityNavmesh.IsRealDoor(door.State))
            {
                return;
            }
            var usePoint = door.UsePoint;
            var toDoor = usePoint - position;
            toDoor.y = 0f;
            var heading = Quaternion.Euler(0f, m_CurrentYaw, 0f) * Vector3.forward;
            var wanted = m_ObjectiveType != ObjectiveType.None
                && ((m_ObjectivePosition - door.Center).GetHorizontalMagnitude() <= 6f
                    || (m_ObjectivePosition - usePoint).GetHorizontalMagnitude() <= 6f
                    || (toDoor.sqrMagnitude > 0.01f && Vector3.Dot(heading, toDoor.normalized) > 0.5f)
                    || m_DoorApproachDoor == door);
            // Fridges and cupboards against an outer wall were opened from
            // the street, 2.5m away through the wall: open only what the bot
            // can reach with nothing but the thing itself in between.
            // 0.1.170: a route through a closed container door (the bake
            // leaves door leaves out) had the bot walk into it when nothing
            // else made it "wanted": walking into a door opens it.
            var brushing = !wanted
                && (SkaliaBotUnityNavmesh.IsRealDoor(door.State) || IsWalkInContainer(door))
                && IsTouchingLeaf(door, position);
            if ((!wanted && !brushing) || !CanReachToOpen(door))
            {
                return;
            }
            if (!door.CanOpen(m_Player))
            {
                // 0.1.0-y17.26: a key door (SkaliaBotKeysY).
                NoteLockedDoor(door, now);
                return;
            }
            if (!SkaliaBotStructureMap.Open(door, m_Player))
            {
                return;
            }
            NoteDoorOpened(door);
            BotLog(LogLevel.Information,
                "Abriu {Name} em {Position}.",
                door.Name,
                FormatPosition(door.Center));
            BlockOpenedFurniture(door);
            // The closed door cut the navmesh; the open one doesn't. Plan again.
            ClearPath();
            m_NextPathRequestTime = now + 0.5f;
            if (m_DoorApproachDoor == door && m_ObjectiveType == ObjectiveType.OpenDoor)
            {
                m_DoorApproachDoor = null;
                ClearObjective();
                m_NextLootScanTime = now + 0.5f;
            }
        }

        private const float DoorBrushMeters = 0.7f;

        private static bool IsTouchingLeaf(BotDoor door, Vector3 position)
        {
            foreach (var leaf in door.Leaves)
            {
                if (leaf == null || !leaf.enabled || !leaf.gameObject.activeInHierarchy)
                {
                    continue;
                }
                var bounds = leaf.bounds;
                if (position.y > bounds.max.y || position.y + 1.8f < bounds.min.y)
                {
                    continue;
                }
                var probe = new Vector3(position.x, Mathf.Clamp(position.y + 0.9f, bounds.min.y, bounds.max.y), position.z);
                var closest = leaf is MeshCollider mesh && !mesh.convex
                    ? bounds.ClosestPoint(probe)
                    : leaf.ClosestPoint(probe);
                if ((closest - probe).GetHorizontalMagnitude() <= DoorBrushMeters)
                {
                    return true;
                }
            }
            return false;
        }

        // 0.1.170: a shipping container's doors swing out beside it, where
        // the bake (which leaves door leaves out) has open floor. In the
        // 0.1.169 test bots stuck on an open container door 7 times, 20s
        // each. Once a container has stood open for 2s its leaves are cut out
        // of the mesh where they are, for every bot.
        private const float OpenLeafSettleSeconds = 2f;
        private const float OpenLeafBlockSeconds = 600f;
        private const float OpenLeafMargin = 0.4f;
        private static readonly Dictionary<BotDoor, float> s_OpenLeafSeenAt = new Dictionary<BotDoor, float>();
        private static readonly Dictionary<BotDoor, float> s_OpenLeafBlockedUntil = new Dictionary<BotDoor, float>();
        private static readonly Dictionary<BotDoor, bool> s_WalkInDoors = new Dictionary<BotDoor, bool>();
        private readonly List<BotDoor> m_OpenDoorScratch = new List<BotDoor>();

        // 0.2.2c: Tadeu opened 15 shipping containers at Scorpion-7 and the
        // bots got stuck on their open doors. With skipContainers the loot in
        // one is left alone and the bot does not open one, unless it is
        // inside it (shut in by someone else).
        private static bool IsSkippedContainerLoot(Vector3 point)
        {
            return s_Settings.SkipContainers && SkaliaBotStructureMap.IsInsideContainer(point);
        }

        private static bool IsSkippedContainerDoor(BotDoor door, Vector3 position)
        {
            return s_Settings.SkipContainers
                && (SkaliaBotStructureMap.IsContainerName(door.Name) || IsWalkInContainer(door))
                && !SkaliaBotStructureMap.IsInsideContainer(position);
        }

        // A container the bot walks into: the body, without the leaves, is
        // more than 1.5m across both ways.
        private static bool IsWalkInContainer(BotDoor door)
        {
            if (door.Transform == null)
            {
                return false;
            }
            if (s_WalkInDoors.TryGetValue(door, out var known))
            {
                return known;
            }
            var any = false;
            var bounds = new Bounds(door.Center, Vector3.zero);
            foreach (var collider in door.Transform.GetComponentsInChildren<Collider>())
            {
                if (collider == null || collider.isTrigger || door.Leaves.Contains(collider))
                {
                    continue;
                }
                if (!any)
                {
                    bounds = collider.bounds;
                    any = true;
                }
                else
                {
                    bounds.Encapsulate(collider.bounds);
                }
            }
            var walkIn = any && bounds.size.y >= 1.8f && Mathf.Min(bounds.size.x, bounds.size.z) > 1.5f;
            s_WalkInDoors[door] = walkIn;
            return walkIn;
        }

        private void BlockOpenContainerLeaves(Vector3 position, float now)
        {
            var realNow = Time.realtimeSinceStartup;
            SkaliaBotStructureMap.FindOpenDoors(position, 8f, m_OpenDoorScratch);
            foreach (var door in m_OpenDoorScratch)
            {
                if (!IsWalkInContainer(door)
                    || (s_OpenLeafBlockedUntil.TryGetValue(door, out var until) && realNow < until))
                {
                    continue;
                }
                // First seen open (or not seen for a while): let the doors
                // finish swinging.
                if (!s_OpenLeafSeenAt.TryGetValue(door, out var seenAt) || realNow - seenAt > 5f)
                {
                    s_OpenLeafSeenAt[door] = realNow;
                    continue;
                }
                if (realNow - seenAt < OpenLeafSettleSeconds)
                {
                    continue;
                }
                s_OpenLeafSeenAt.Remove(door);
                s_OpenLeafBlockedUntil[door] = realNow + OpenLeafBlockSeconds;
                var cuts = 0;
                foreach (var leaf in door.Leaves)
                {
                    if (leaf == null || !leaf.enabled || !leaf.gameObject.activeInHierarchy)
                    {
                        continue;
                    }
                    GetLeafBox(leaf, out var center, out var size, out var yaw);
                    SkaliaBotUnityNavmesh.BlockArea(center, size, yaw, OpenLeafBlockSeconds);
                    cuts++;
                }
                if (cuts == 0)
                {
                    continue;
                }
                ClearPath();
                m_NextPathRequestTime = now + 0.3f;
                BotLog(LogLevel.Information,
                    "{Name} aberto em {Position}: {Count} porta(s) aberta(s) tirada(s) da malha por 10 min.",
                    door.Name,
                    FormatPosition(door.Center),
                    cuts);
            }
        }

        // The leaf's own box as it stands, turned only around the vertical.
        private static void GetLeafBox(Collider leaf, out Vector3 center, out Vector3 size, out float yaw)
        {
            if (leaf is BoxCollider box)
            {
                var t = box.transform;
                center = t.TransformPoint(box.center);
                var axes = new[]
                {
                    t.TransformVector(new Vector3(box.size.x, 0f, 0f)),
                    t.TransformVector(new Vector3(0f, box.size.y, 0f)),
                    t.TransformVector(new Vector3(0f, 0f, box.size.z)),
                };
                var up = 0;
                for (var i = 1; i < 3; i++)
                {
                    if (Mathf.Abs(axes[i].y) > Mathf.Abs(axes[up].y))
                    {
                        up = i;
                    }
                }
                var along = axes[(up + 1) % 3];
                var across = axes[(up + 2) % 3];
                along.y = 0f;
                across.y = 0f;
                yaw = along.sqrMagnitude > 0.0001f ? Mathf.Atan2(along.x, along.z) * Mathf.Rad2Deg : 0f;
                size = new Vector3(
                    across.magnitude + OpenLeafMargin,
                    Mathf.Max(Mathf.Abs(axes[up].y), 1.8f),
                    along.magnitude + OpenLeafMargin);
            }
            else
            {
                var bounds = leaf.bounds;
                center = bounds.center;
                yaw = 0f;
                size = new Vector3(bounds.size.x + OpenLeafMargin, Mathf.Max(bounds.size.y, 1.8f), bounds.size.z + OpenLeafMargin);
            }
            // Down past the floor under the leaf, so the cut reaches the mesh.
            size.y += 0.6f;
            center.y -= 0.3f;
        }

        private bool CanReachToOpen(BotDoor door)
        {
            var origin = m_Player.look.aim.position;
            var target = door.UsePoint;
            var direction = target - origin;
            var distance = direction.magnitude;
            if (distance < 0.05f)
            {
                return true;
            }
            var hits = Physics.RaycastAll(origin, direction / distance, distance, RayMasks.BLOCK_COLLISION, QueryTriggerInteraction.Ignore);
            foreach (var hit in hits)
            {
                // The thing itself, or the frame right around it.
                if ((hit.transform != null
                        && (hit.transform == door.Transform || hit.transform.IsChildOf(door.Transform)))
                    || (hit.point - target).sqrMagnitude <= 0.6f * 0.6f)
                {
                    continue;
                }
                return false;
            }
            return true;
        }

        // An item with no route because a closed door (container, fridge)
        // cuts the navmesh in front of it: walk to the door and open it.
        private bool TryStartDoorApproach(Vector3 position, float now, Vector3 target, string reason)
        {
            if (!SkaliaBotUnityNavmesh.MapFilled || !SkaliaBotStructureMap.Ready)
            {
                return false;
            }
            var door = SkaliaBotStructureMap.FindClosedDoor(target, 5f);
            if (door == null || IsSkippedContainerDoor(door, position))
            {
                return false;
            }
            if (!door.CanOpen(m_Player))
            {
                // 0.1.0-y17.26: no key for it; the key becomes a goal
                // (SkaliaBotKeysY) and the item behind it waits.
                NoteLockedDoor(door, now);
                return false;
            }
            GraphNode? origin = null;
            var forward = door.Transform.forward;
            var right = door.Transform.right;
            var usePoint = door.UsePoint;
            forward.y = 0f;
            right.y = 0f;
            Vector3[] offsets =
            {
                forward.normalized * 1.6f, -forward.normalized * 1.6f,
                right.normalized * 1.6f, -right.normalized * 1.6f, Vector3.zero
            };
            var found = false;
            var approach = Vector3.zero;
            var bestDistance = float.MaxValue;
            foreach (var offset in offsets)
            {
                var nearest = SnapToNewMesh(usePoint + offset, 3f);
                if (!nearest.found
                    || (nearest.position - usePoint).GetHorizontalMagnitude() > 3f
                    || !CanReach(origin, nearest.node, position, nearest.position))
                {
                    continue;
                }
                var distance = (nearest.position - position).GetHorizontalMagnitude();
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    approach = nearest.position;
                    found = true;
                }
            }
            if (!found)
            {
                return false;
            }
            m_DoorApproachDoor = door;
            m_NextLootScanTime = now + 25f;
            SetObjective(ObjectiveType.OpenDoor, approach, now + 25f);
            BotLog(LogLevel.Information,
                "Indo abrir {Name} em {Position} ({Reason}).",
                door.Name,
                FormatPosition(door.Center),
                reason);
            return true;
        }

        private void UpdateDoorApproach(Vector3 position, float now)
        {
            var door = m_DoorApproachDoor;
            if (door == null || !door.IsClosed)
            {
                m_DoorApproachDoor = null;
                ClearObjective();
                m_NextLootScanTime = now;
                return;
            }
            if ((door.UsePoint - position).GetHorizontalMagnitude() <= 2.5f
                && !door.CanOpen(m_Player))
            {
                NoteLockedDoor(door, now);
                m_DoorApproachDoor = null;
                ClearObjective();
                m_NextLootScanTime = now + 0.5f;
                return;
            }
            if ((door.UsePoint - position).GetHorizontalMagnitude() <= 2.5f
                && SkaliaBotStructureMap.Open(door, m_Player))
            {
                NoteDoorOpened(door);
                BotLog(LogLevel.Information,
                    "Abriu {Name} em {Position}.",
                    door.Name,
                    FormatPosition(door.Center));
                BlockOpenedFurniture(door);
                m_DoorApproachDoor = null;
                ClearObjective();
                ClearPath();
                m_NextLootScanTime = now + 0.5f;
                return;
            }
            if (now >= m_ObjectiveExpiresAt - 0.1f)
            {
                BotLog(LogLevel.Information,
                    "Nao conseguiu chegar em {Name} em {Position}; desistindo.",
                    door.Name,
                    FormatPosition(door.Center));
                m_DoorApproachDoor = null;
                ClearObjective();
                m_NextLootScanTime = now;
            }
        }

        // The nearest town (map location) whose navmesh is in another flag,
        // preferring flags not left in the last 30 minutes.
        private bool TryStartTerrainTravel(Vector3 position, float now, GraphNode? originNode, string reason)
        {
            // Right after a restart the terrain map was still loading: the bot
            // set off feeling its way 7m at a time and circled on a hillside
            // for a minute. It now waits for the map.
            if (!SkaliaBotTerrainMap.Ready)
            {
                if (now >= m_NextTerrainWaitLogAt)
                {
                    m_NextTerrainWaitLogAt = now + 30f;
                    BotLog(LogLevel.Information,
                        "Viagem por terreno aguardando o mapa de terreno ({Status}).",
                        SkaliaBotTerrainMap.Status);
                }
                return false;
            }
            if (AstarPath.active == null
                || m_Player.life.health < TravelMinimumHealth
                || m_Player.stance.stance == EPlayerStance.SWIM)
            {
                return false;
            }
            var locations = LocationDevkitNodeSystem.Get()?.GetAllNodes();
            if (locations == null)
            {
                return false;
            }
            var originGraph = originNode != null ? originNode.GraphIndex : uint.MaxValue;
            var hasTryhardGoal = TryGetTryhardGoal(position, now, out var tryhardGoal, out var tryhardGoalName);
            var found = false;
            var bestScore = float.MaxValue;
            var bestPoint = Vector3.zero;
            var bestName = string.Empty;
            uint bestGraph = 0;
            foreach (var location in locations)
            {
                var point = location.transform.position;
                var distance = (point - position).GetHorizontalMagnitude();
                if (distance < TravelMinimumMeters || distance > TravelMaximumMeters)
                {
                    continue;
                }
                var nearest = AstarPath.active.GetNearest(point, NNConstraint.Walkable);
                if (nearest.node == null
                    || nearest.node.GraphIndex == originGraph
                    || (nearest.position - point).GetHorizontalMagnitude() > MaximumDestinationNodeSnapMeters
                    || WaterUtility.isPointUnderwater(nearest.position + Vector3.up * 0.5f))
                {
                    continue;
                }
                // SecretLab's flag and mesh sit at (2068, -2214), past the edge
                // of the 4096m map: the planner clamped the goal to the corner
                // and three bots ran circles there for minutes, every session.
                if (!SkaliaBotTerrainMap.IsInsideMap(nearest.position)
                    || !Level.checkSafeIncludingClipVolumes(nearest.position + Vector3.up))
                {
                    continue;
                }
                var graph = nearest.node.GraphIndex;
                if ((m_TravelFailedGraphs.TryGetValue(graph, out var failedUntil) && now < failedUntil)
                    || (s_TravelGraphBannedUntil.TryGetValue(graph, out var bannedUntil) && now < bannedUntil))
                {
                    continue;
                }
                var finished = false;
                foreach (var area in m_FinishedAreas)
                {
                    if (now < area.Value
                        && (nearest.position - area.Key).GetHorizontalMagnitude() < InterestAreaRadiusMeters)
                    {
                        finished = true;
                        break;
                    }
                }
                if (finished)
                {
                    continue;
                }
                var score = distance;
                // 0.2.2v (doc 13.3, item 6): the tryhard's trip leads toward
                // its goal (strong spot or hunting ground), not to the
                // nearest flag (Kent Raceway, Kennewick Farm, Camano in the
                // 0.2.2u test).
                if (hasTryhardGoal)
                {
                    score = (nearest.position - tryhardGoal).GetHorizontalMagnitude() + distance * 0.25f;
                }
                if (m_TravelLeftGraphs.TryGetValue(graph, out var leftUntil) && now < leftUntil)
                {
                    score += 1000f;
                }
                if (score < bestScore)
                {
                    bestScore = score;
                    bestPoint = nearest.position;
                    bestName = string.IsNullOrWhiteSpace(location.locationName)
                        ? "local sem nome"
                        : location.locationName;
                    bestGraph = graph;
                    found = true;
                }
            }
            if (!found)
            {
                return false;
            }
            if (hasTryhardGoal)
            {
                reason += "; rumo a " + tryhardGoalName;
            }
            StartTerrainTravelTo(position, now, originNode, originGraph, bestPoint, bestName, bestGraph, reason);
            return true;
        }

        private void StartTerrainTravelTo(
            Vector3 position,
            float now,
            GraphNode? originNode,
            uint originGraph,
            Vector3 bestPoint,
            string bestName,
            uint bestGraph,
            string reason)
        {
            if (originNode != null)
            {
                var exitConstraint = new NNConstraint
                {
                    constrainWalkability = true,
                    walkable = true,
                    constrainArea = true,
                    area = (int)originNode.Area,
                    constrainDistance = false
                };
                var exitInfo = AstarPath.active.GetNearest(bestPoint, exitConstraint);
                m_TravelExit = exitInfo.node != null ? exitInfo.position : position;
                m_TravelExit = FindDryTravelExit(m_TravelExit, position, exitConstraint);
            }
            else
            {
                // Already off the mesh: the terrain leg starts here.
                m_TravelExit = position;
            }
            m_TravelActive = true;
            m_TravelReplans = 0;
            m_TravelMeshArea = m_NextTravelIsMeshArea;
            m_TravelAreaKey = m_NextTravelIsMeshArea ? m_NextTravelAreaKey : string.Empty;
            m_NextTravelIsMeshArea = false;
            m_NextTravelAreaKey = string.Empty;
            m_TravelTarget = bestPoint;
            m_TravelTargetName = bestName;
            m_TravelOriginGraph = originGraph;
            m_TravelTargetGraph = bestGraph;
            m_TravelStartedAt = now;
            m_TravelStartedUpper = IsUpperFloor(position);
            var totalDistance = (bestPoint - position).GetHorizontalMagnitude();
            m_TravelDeadline = now + totalDistance / 2f + 180f;
            if (originNode != null)
            {
                m_TravelLeftGraphs[originGraph] = now + TravelLeftGraphSeconds;
            }
            m_HasInterestArea = false;
            m_InterestAreaName = "viagem para " + bestName;
            BotLog(LogLevel.Information,
                "Viagem por terreno ({Reason}): de flag {Origin} para {Name} (flag {Graph}) a {Distance:0}m; saindo da malha em {Exit} ({ExitDistance:0}m daqui).",
                reason,
                originGraph,
                bestName,
                bestGraph,
                totalDistance,
                FormatPosition(m_TravelExit),
                (m_TravelExit - position).GetHorizontalMagnitude());
            if ((m_TravelExit - position).GetHorizontalMagnitude() <= 4f)
            {
                BeginTerrainLeg(position, now, "ja esta na borda");
            }
            else if (SkaliaBotUnityNavmesh.IsReadyAt(position))
            {
                // The edge of the zombie mesh was 146m the wrong way for a
                // trip the new mesh walks from here in 240m stretches.
                BeginTerrainLeg(position, now, "malha nova cobre o caminho");
            }
            else
            {
                m_TravelPhase = 1;
                m_TravelPhaseDeadline = now + 90f;
                SetObjective(ObjectiveType.Travel, m_TravelExit, m_TravelDeadline + 30f);
            }
        }

        // The mesh edge nearest the destination can be a bank under water:
        // at (253, 24, -1398) the bot walked in, swam out, went back in for
        // 70s until the water teleport. Step back toward the bot until the
        // nearest mesh point is dry.
        private static Vector3 FindDryTravelExit(Vector3 exit, Vector3 position, NNConstraint constraint)
        {
            if (!WaterUtility.isPointUnderwater(exit + Vector3.up * 0.5f) || AstarPath.active == null)
            {
                return exit;
            }
            for (var step = 1; step <= 10; step++)
            {
                var probe = Vector3.Lerp(exit, position, step / 10f);
                var info = AstarPath.active.GetNearest(probe, constraint);
                if (info.node != null && !WaterUtility.isPointUnderwater(info.position + Vector3.up * 0.5f))
                {
                    return info.position;
                }
            }
            return exit;
        }

        // Off the mesh with no route ("regiao null"), local exploration only
        // wandered the SecretLab plateau for 8 min: head to the nearest flag.
        private bool TryStartOffMeshTravel(Vector3 position, float now)
        {
            if (m_TravelActive
                || now < m_NextOffMeshTravelAt
                || AstarPath.active == null
                || AstarPath.active.GetNearest(position, NNConstraint.Walkable).node != null)
            {
                return false;
            }
            m_NextOffMeshTravelAt = now + 10f;
            return TryStartTerrainTravel(position, now, null, "fora da malha sem rota");
        }

        private void ResumeTerrainTravel(Vector3 position, float now)
        {
            if (m_TravelPhase == 1)
            {
                m_TravelPhaseDeadline = Mathf.Max(m_TravelPhaseDeadline, now + 30f);
                SetObjective(ObjectiveType.Travel, m_TravelExit, m_TravelDeadline + 30f);
                return;
            }
            // Progress keeps counting across interruptions; resetting it here
            // let a loop of interruptions never give up.
            m_TravelBestDistance = Mathf.Min(
                m_TravelBestDistance,
                (m_TravelTarget - position).GetHorizontalMagnitude());
            m_NextTravelWaypointAt = 0f;
            if (!PlanTerrainRoute(position, now))
            {
                return;
            }
            SetObjective(ObjectiveType.Travel, ComputeTerrainWaypoint(position, now), m_TravelDeadline + 30f);
        }

        // Plans the whole crossing on the terrain map. Without the map (still
        // scanning) the bot keeps the old step-by-step walk; with the map and
        // no route the target is given up before walking into a river.
        private bool PlanTerrainRoute(Vector3 position, float now)
        {
            m_TravelPlan.Clear();
            m_TravelPlanIndex = 0;
            m_TravelBestPlanIndex = 0;
            m_TravelSwimMeters = 0f;
            m_TravelStraightPlan = false;
            m_TravelStraightWaitSince = 0f;
            m_NextTravelReplanAt = now + 5f;
            if (SkaliaBotUnityNavmesh.MapFilled)
            {
                var meshWatch = System.Diagnostics.Stopwatch.StartNew();
                if (SkaliaBotUnityNavmesh.TryPlanLong(position, m_TravelTarget, m_TravelPlan, out var meshFailure, out var meshLength, out var meshChecks))
                {
                    // Only mesh legs walk it, like the straight line did.
                    m_TravelStraightPlan = true;
                    BotLog(LogLevel.Information,
                        "Rota longa pela malha nova ate {Name}: {Points} pontos, {Length:0}m (linha reta {Straight:0}m), {Checks} rotas conferidas, {Ms:0}ms.",
                        m_TravelTargetName,
                        m_TravelPlan.Count,
                        meshLength,
                        (m_TravelTarget - position).GetHorizontalMagnitude(),
                        meshChecks,
                        meshWatch.Elapsed.TotalMilliseconds);
                    return true;
                }
                BotLog(LogLevel.Information,
                    "Sem rota longa pela malha nova ate {Name} ({Failure}; {Checks} rotas conferidas, {Ms:0}ms); tentando o mapa de terreno.",
                    m_TravelTargetName,
                    meshFailure,
                    meshChecks,
                    meshWatch.Elapsed.TotalMilliseconds);
                m_TravelPlan.Clear();
            }
            if (!SkaliaBotTerrainMap.Ready)
            {
                BotLog(LogLevel.Information,
                    "Mapa de terreno indisponivel ({Status}); viagem sem rota planejada.",
                    SkaliaBotTerrainMap.Status);
                return true;
            }
            var watch = System.Diagnostics.Stopwatch.StartNew();
            if (!SkaliaBotTerrainMap.TryPlan(position, m_TravelTarget, m_TravelPlan, out var failure))
            {
                if (!SkaliaBotTerrainMap.TryPlan(
                        position,
                        m_TravelTarget,
                        m_TravelPlan,
                        out var wideFailure,
                        SkaliaBotTerrainMap.WidePlanMarginMeters))
                {
                    // The terrain grid sees no way, but the new mesh has the
                    // buildings, bridges and stairs it lacks: give the mesh
                    // stretches a straight line of points to aim at.
                    if (SkaliaBotUnityNavmesh.IsReadyAt(position))
                    {
                        m_TravelPlan.Clear();
                        var straight = m_TravelTarget - position;
                        var steps = Mathf.Max(1, Mathf.CeilToInt(straight.GetHorizontalMagnitude() / 100f));
                        for (var step = 1; step <= steps; step++)
                        {
                            m_TravelPlan.Add(position + straight * step / steps);
                        }
                        m_TravelStraightPlan = true;
                        BotLog(LogLevel.Information,
                            "Sem rota por terreno ate {Name} ({Failure}); seguindo em linha reta pelos trechos da malha nova.",
                            m_TravelTargetName,
                            failure);
                        return true;
                    }
                    FailTerrainTravel(now, failure + "; faixa de 500m: " + wideFailure);
                    return false;
                }
                BotLog(LogLevel.Information,
                    "Rota por terreno ate {Name} so existe contornando por fora da faixa de 160m ({Failure}); usando a faixa de 500m.",
                    m_TravelTargetName,
                    failure);
            }
            var length = 0f;
            for (var i = 1; i < m_TravelPlan.Count; i++)
            {
                length += (m_TravelPlan[i] - m_TravelPlan[i - 1]).GetHorizontalMagnitude();
            }
            BotLog(LogLevel.Information,
                "Rota por terreno planejada ate {Name}: {Points} pontos, {Length:0}m (linha reta {Straight:0}m), calculada em {Ms:0}ms.",
                m_TravelTargetName,
                m_TravelPlan.Count,
                length,
                (m_TravelTarget - position).GetHorizontalMagnitude(),
                watch.Elapsed.TotalMilliseconds);
            NoteTravelSwimPlan();
            return true;
        }

        private void BeginTerrainLeg(Vector3 position, float now, string reason)
        {
            m_TravelPhase = 2;
            m_TravelMeshLeg = false;
            m_NextTravelMeshTryAt = 0f;
            m_TravelBestDistance = (m_TravelTarget - position).GetHorizontalMagnitude();
            m_TravelLastProgressAt = now;
            m_TravelBlockedSteps = 0;
            m_NextTravelWaypointAt = 0f;
            BotLog(LogLevel.Information,
                "Saindo da malha em {Position} ({Reason}); seguindo pelo terreno ate {Name} ({Distance:0}m).",
                FormatPosition(position),
                reason,
                m_TravelTargetName,
                m_TravelBestDistance);
            if (!PlanTerrainRoute(position, now))
            {
                return;
            }
            SetObjective(ObjectiveType.Travel, ComputeTerrainWaypoint(position, now), m_TravelDeadline + 30f);
        }

        private void UpdateTerrainTravel(Vector3 position, float now)
        {
            if (!m_TravelActive)
            {
                ClearObjective();
                return;
            }
            if (now >= m_TravelDeadline)
            {
                FailTerrainTravel(now, "tempo esgotado");
                return;
            }
            if (m_TravelPhase == 1)
            {
                if ((m_TravelExit - position).GetHorizontalMagnitude() <= 3f
                    || now >= m_TravelPhaseDeadline)
                {
                    BeginTerrainLeg(
                        position,
                        now,
                        now >= m_TravelPhaseDeadline ? "nao chegou na borda a tempo" : "chegou na borda");
                }
                return;
            }

            var distance = (m_TravelTarget - position).GetHorizontalMagnitude();
            // 94 of 206 trips in the 0.1.141 test "ended" more than 100m
            // from their destination: any foreign zombie flag counted.
            if (distance <= 8f
                || (m_TravelMeshArea ? distance <= MeshAreaArrivalMeters : HasReachedOtherFlag(position)))
            {
                if (m_TravelMeshArea && m_TravelAreaKey.Length > 0)
                {
                    m_PendingMeshAreaKey = m_TravelAreaKey;
                    m_PendingMeshAreaName = m_TravelTargetName;
                    m_PendingMeshAreaPoint = m_TravelTarget;
                    m_PendingMeshAreaUntil = now + 120f;
                }
                m_TravelMeshArea = false;
                var graph = AstarPath.active?.GetNearest(position, NNConstraint.Walkable).node?.GraphIndex;
                NoteAreaProgress(now);
                BotLog(LogLevel.Information,
                    "Viagem por terreno concluida em {Seconds:0}s: chegou na malha da flag {Graph} em {Position} (destino {Name} a {Distance:0}m).",
                    now - m_TravelStartedAt,
                    graph,
                    FormatPosition(position),
                    m_TravelTargetName,
                    distance);
                m_TravelActive = false;
                m_TravelPhase = 0;
                ClearObjective();
                m_HasInterestArea = false;
                m_NextExplorationSelectionTime = 0f;
                return;
            }

            var planAdvanced = m_TravelPlan.Count > 0 && m_TravelPlanIndex > m_TravelBestPlanIndex;
            if (planAdvanced)
            {
                m_TravelBestPlanIndex = m_TravelPlanIndex;
            }
            if (distance < m_TravelBestDistance - 3f || planAdvanced)
            {
                m_TravelBestDistance = Mathf.Min(m_TravelBestDistance, distance);
                m_TravelLastProgressAt = now;
                // The SecretLab climb timed out after 10 min while still
                // closing in; the deadline only stops a trip that stalls.
                m_TravelDeadline = Mathf.Max(m_TravelDeadline, now + 120f);
            }
            else if (now - m_TravelLastProgressAt >= TravelGiveUpSeconds)
            {
                FailTerrainTravel(now, "sem progresso por " + TravelGiveUpSeconds.ToString("0") + "s");
                return;
            }
            else if (now - m_TravelLastProgressAt >= TravelProgressWindowSeconds
                     && now >= m_TravelForcedDetourUntil)
            {
                m_TravelDetourSide = -m_TravelDetourSide;
                m_TravelForcedDetourUntil = now + 10f;
                BotLog(LogLevel.Information,
                    "Viagem por terreno sem avancar ha {Seconds:0}s em {Position}; contornando pelo outro lado.",
                    now - m_TravelLastProgressAt,
                    FormatPosition(position));
            }

            if (UpdateTravelMeshLeg(position, now))
            {
                return;
            }
            if (m_TravelStraightPlan)
            {
                // The 0.1.115 test: 45 of 59 circles were death-item trips on
                // this straight line. The terrain map had already said there
                // is no way (water, cliff, walls); stepping 4m at a time
                // toward it, every blocked step flipped the detour side and
                // the bot turned in place.
                // In the 0.1.150 test most of these failed after 0s, on the
                // first try, while the mesh pieces ahead were still being
                // loaded: give the legs 20s of retries first.
                if (m_TravelStraightWaitSince <= 0f)
                {
                    m_TravelStraightWaitSince = now;
                    // Pushed off the plan (a fight, a detour): plan again
                    // from here, up to three times a trip.
                    if (m_TravelReplans < 3 && SkaliaBotUnityNavmesh.MapFilled)
                    {
                        m_TravelReplans++;
                        BotLog(LogLevel.Information,
                            "Viagem ate {Name}: nenhum trecho da rota alcancavel daqui ({Failure}); planejando de novo ({Count}/3).",
                            m_TravelTargetName,
                            SkaliaBotUnityNavmesh.LastFailure,
                            m_TravelReplans);
                        if (PlanTerrainRoute(position, now))
                        {
                            m_NextTravelMeshTryAt = 0f;
                            m_TravelStraightWaitSince = 0f;
                        }
                        return;
                    }
                }
                if (now - m_TravelStraightWaitSince < 20f)
                {
                    return;
                }
                FailTerrainTravel(now,
                    "a malha nova nao chega ao proximo ponto e o terreno nao tem caminho; malha: "
                    + (SkaliaBotUnityNavmesh.LastFailure.Length > 0 ? SkaliaBotUnityNavmesh.LastFailure : "sem motivo"));
                return;
            }

            if (now >= m_NextTravelWaypointAt
                || (m_ObjectivePosition - position).GetHorizontalMagnitude() <= 2f)
            {
                var waypoint = ComputeTerrainWaypoint(position, now);
                if (!m_TravelActive)
                {
                    return;
                }
                if (m_TravelBlockedSteps >= 6)
                {
                    FailTerrainTravel(now, "terreno bloqueado (agua, penhasco ou parede) em todas as direcoes");
                    return;
                }
                SetObjective(ObjectiveType.Travel, waypoint, m_TravelDeadline + 30f);
            }
            // Off the mesh there is no route to request: steer straight at the
            // waypoint; wall avoidance and window/fence shortcuts still apply.
            m_DirectFallbackUntil = now + 1f;
        }

        // A third of the circles of the last two logs came from trips over
        // the terrain: 4m steps straight at the next point, blind to boulders
        // and fences, and over the cliff into the boulder pit at
        // (-1040, 27, -1171) where three bots circled. The new mesh now covers
        // the map: walk each stretch of the trip as a mesh route to the
        // farthest planned point it reaches within 240m, and step over the
        // terrain only where it has none.
        private const float TravelMeshLegMeters = 240f;
        private bool m_TravelMeshLeg;
        // The plan is the straight line of the "no terrain route" fallback:
        // only mesh legs may walk it.
        private bool m_TravelStraightPlan;
        private int m_TravelMeshPlanIndex;
        private float m_TravelMeshBest;
        private float m_NextTravelMeshTryAt;
        private float m_TravelMeshStartedAt;
        private float m_TravelMeshRouteSeenAt;
        private float m_TravelStraightWaitSince;
        private int m_TravelReplans;

        private bool UpdateTravelMeshLeg(Vector3 position, float now)
        {
            if (m_TravelMeshLeg)
            {
                var left = (m_ObjectivePosition - position).GetHorizontalMagnitude();
                if (left < m_TravelMeshBest - 3f)
                {
                    m_TravelMeshBest = left;
                    m_TravelLastProgressAt = now;
                }
                // A failed request clears the route (UpdateState resets the
                // failure flag before this runs).
                // A route cleared to ask a new one (off the line, stuck at a
                // corner) is not a failed leg: the gap before the new request
                // ended the leg and the bot walked the terrain plan straight
                // into a stone fence for 10s (Tadeu, 15:48 in the 0.1.141
                // test, 38 circles "without a route" like it).
                if (m_PathPending || m_PathPoints.Count > 0)
                {
                    m_TravelMeshRouteSeenAt = now;
                }
                var failed = !m_PathPending
                    && (m_PathFailed
                        || (m_PathPoints.Count == 0
                            && now - m_TravelMeshStartedAt > 2f
                            && now - m_TravelMeshRouteSeenAt > 2f));
                if (left > 6f && !failed && m_ObjectiveType == ObjectiveType.Travel)
                {
                    return true;
                }
                m_TravelMeshLeg = false;
                if (!failed && m_TravelMeshPlanIndex > m_TravelPlanIndex && m_TravelPlan.Count > 0)
                {
                    // planIndex is the plan's count when the leg went to the
                    // destination itself: the one crash of the 0.1.103 log.
                    m_TravelPlanIndex = Mathf.Min(m_TravelMeshPlanIndex, m_TravelPlan.Count - 1);
                }
                if (failed)
                {
                    m_NextTravelMeshTryAt = now + (m_TravelStraightPlan ? 3f : 10f);
                }
                else
                {
                    // Leg done: pick the next one now.
                    m_NextTravelMeshTryAt = 0f;
                }
            }
            if (now < m_NextTravelMeshTryAt)
            {
                return false;
            }
            m_NextTravelMeshTryAt = now + (m_TravelStraightPlan ? 3f : 5f);
            if (!TryPickTravelMeshTarget(position, out var target, out var planIndex))
            {
                return false;
            }
            m_TravelStraightWaitSince = 0f;
            m_TravelMeshLeg = true;
            m_TravelMeshStartedAt = now;
            m_TravelMeshRouteSeenAt = now;
            m_TravelMeshPlanIndex = planIndex;
            m_TravelMeshBest = (target - position).GetHorizontalMagnitude();
            m_TravelLastProgressAt = now;
            BotLog(LogLevel.Information,
                "Viagem ate {Name}: trecho de {Distance:0}m pela malha nova ate {Target}.",
                m_TravelTargetName,
                m_TravelMeshBest,
                FormatPosition(target));
            SetObjective(ObjectiveType.Travel, target, m_TravelDeadline + 30f);
            return true;
        }

        private bool TryPickTravelMeshTarget(Vector3 position, out Vector3 target, out int planIndex)
        {
            target = m_TravelTarget;
            planIndex = m_TravelPlan.Count;
            if ((m_TravelTarget - position).GetHorizontalMagnitude() <= TravelMeshLegMeters
                && SkaliaBotUnityNavmesh.TryFindPath(position, m_TravelTarget, m_UnityPathScratch))
            {
                return true;
            }
            var farthest = -1;
            for (var index = m_TravelPlanIndex; index < m_TravelPlan.Count; index++)
            {
                if ((m_TravelPlan[index] - position).GetHorizontalMagnitude() > TravelMeshLegMeters)
                {
                    break;
                }
                farthest = index;
            }
            // Farthest first, then three nearer ones spread back toward the bot.
            for (var attempt = 0; attempt < 4 && farthest >= m_TravelPlanIndex; attempt++)
            {
                var index = farthest - (farthest - m_TravelPlanIndex) * attempt / 4;
                var point = m_TravelPlan[index];
                if (m_TravelStraightPlan
                    && SkaliaBotUnityNavmesh.TrySnap(point, 20f, out var snapped))
                {
                    point = snapped;
                }
                if ((point - position).GetHorizontalMagnitude() > 12f
                    && SkaliaBotUnityNavmesh.TryFindPath(position, point, m_UnityPathScratch))
                {
                    target = point;
                    planIndex = index;
                    return true;
                }
            }
            if (m_TravelStraightPlan && farthest >= m_TravelPlanIndex
                && TryPickPartialTravelStop(position, m_TravelPlan[farthest], out target))
            {
                planIndex = m_TravelPlanIndex;
                return true;
            }
            return false;
        }

        // No straight-line point is reachable: walk to where the mesh gets
        // closest to the far one, if that is at least 25m nearer the
        // destination.
        private bool TryPickPartialTravelStop(Vector3 position, Vector3 far, out Vector3 target)
        {
            target = m_TravelTarget;
            if (!SkaliaBotUnityNavmesh.TryFindClosestStop(position, far, out var stop))
            {
                return false;
            }
            var gain = (m_TravelTarget - position).GetHorizontalMagnitude()
                - (m_TravelTarget - stop).GetHorizontalMagnitude();
            if (gain < 25f
                || (stop - position).GetHorizontalMagnitude() <= 12f
                || !SkaliaBotUnityNavmesh.TryFindPath(position, stop, m_UnityPathScratch))
            {
                SkaliaBotUnityNavmesh.TryFindPath(position, far, m_UnityPathScratch);
                return false;
            }
            BotLog(LogLevel.Information,
                "Viagem ate {Name}: nenhum ponto da linha reta e alcancavel; indo ate onde a malha chega mais perto ({Stop}, {Gain:0}m mais perto do destino).",
                m_TravelTargetName,
                FormatPosition(stop),
                gain);
            target = stop;
            return true;
        }

        // The zombie graph links the two, or the new mesh has a complete
        // route between them.
        // 0.2.2x9: reachable on the new mesh, the one routes are made on.
        // The zombie mesh said yes to points no route of the new mesh gets
        // to (a roof, the far side of a fence), and the pick failed at once.
        private static bool CanReach(GraphNode? origin, GraphNode? node, Vector3 from, Vector3 point)
        {
            return SkaliaBotUnityNavmesh.IsReachable(from, point);
        }

        private bool IsTravelGraphBlocked(GraphNode? node, float now)
        {
            if (node == null)
            {
                return false;
            }
            var graph = node.GraphIndex;
            return (m_TravelFailedGraphs.TryGetValue(graph, out var failedUntil) && now < failedUntil)
                || (s_TravelGraphBannedUntil.TryGetValue(graph, out var bannedUntil) && now < bannedUntil);
        }

        private bool HasReachedOtherFlag(Vector3 position)
        {
            if (AstarPath.active == null)
            {
                return false;
            }
            var nearest = AstarPath.active.GetNearest(position, NNConstraint.Walkable);
            return nearest.node != null
                && nearest.node.GraphIndex != m_TravelOriginGraph
                && (nearest.position - position).GetHorizontalMagnitude() <= 3f
                && Mathf.Abs(nearest.position.y - position.y) <= 2f;
        }

        // A point a few meters ahead on dry ground the bot can walk to: straight
        // at the target when possible, otherwise the smallest detour, keeping to
        // one side so it contours obstacles instead of zigzagging.
        private Vector3 ComputeTerrainWaypoint(Vector3 position, float now)
        {
            m_NextTravelWaypointAt = now + 0.75f;
            var goal = m_TravelTarget;
            if (m_TravelPlan.Count > 0)
            {
                // A plan replaced by a shorter one kept the old index: out of
                // range in the 0.1.103 test (bot loop stopped mid-trip).
                m_TravelPlanIndex = Mathf.Clamp(m_TravelPlanIndex, 0, m_TravelPlan.Count - 1);
                while (m_TravelPlanIndex < m_TravelPlan.Count - 1
                       && (m_TravelPlan[m_TravelPlanIndex] - position).GetHorizontalMagnitude() <= 4f)
                {
                    m_TravelPlanIndex++;
                }
                // Look ahead: skip to a later point when it is closer (cut corners
                // the bot already passed while contouring an obstacle).
                for (var i = m_TravelPlanIndex + 1; i < Mathf.Min(m_TravelPlan.Count, m_TravelPlanIndex + 6); i++)
                {
                    if ((m_TravelPlan[i] - position).GetHorizontalMagnitude()
                        < (m_TravelPlan[m_TravelPlanIndex] - position).GetHorizontalMagnitude())
                    {
                        m_TravelPlanIndex = i;
                    }
                }
                goal = m_TravelPlan[m_TravelPlanIndex];
                // Straight-line points are 100m apart by design: being 30m
                // from one is not being pushed off it.
                if (!m_TravelStraightPlan
                    && (goal - position).GetHorizontalMagnitude() > 30f
                    && now >= m_NextTravelReplanAt)
                {
                    // Pushed off the route (fight, flight, water): plan again from here.
                    BotLog(LogLevel.Information,
                        "Bot a {Distance:0}m da rota planejada; recalculando.",
                        (goal - position).GetHorizontalMagnitude());
                    if (!PlanTerrainRoute(position, now) || m_TravelPlan.Count == 0)
                    {
                        return position;
                    }
                    goal = m_TravelPlan[0];
                }
            }
            // 0.2.2x14: the route goes into the water here; straight in.
            if (TrySwimWaypoint(position, goal, out var swimPoint))
            {
                return swimPoint;
            }
            var toTarget = goal - position;
            toTarget.y = 0f;
            if (toTarget.sqrMagnitude < 0.01f)
            {
                return m_TravelTarget;
            }
            var forward = toTarget.normalized;
            var step = Mathf.Min(TravelStepMeters, toTarget.magnitude);
            var forced = now < m_TravelForcedDetourUntil;
            float[] angles = forced
                ? new[] { 70f, 90f, 50f, 110f, 30f, 135f }
                : new[] { 0f, 20f, 40f, 60f, 80f, 100f, 125f };
            for (var pass = 0; pass < 2; pass++)
            {
                var length = pass == 0 ? step : step * 0.5f;
                foreach (var magnitude in angles)
                {
                    for (var side = 0; side < (magnitude == 0f ? 1 : 2); side++)
                    {
                        var sign = side == 0 ? m_TravelDetourSide : -m_TravelDetourSide;
                        if (forced && side == 1)
                        {
                            continue;
                        }
                        var direction = Quaternion.Euler(0f, magnitude * sign, 0f) * forward;
                        if (TryTerrainStep(position, direction, length, now, out var ground))
                        {
                            if (magnitude >= 40f)
                            {
                                m_TravelDetourSide = sign;
                            }
                            m_TravelBlockedSteps = 0;
                            return ground;
                        }
                    }
                }
            }
            m_TravelBlockedSteps++;
            m_TravelDetourSide = -m_TravelDetourSide;
            m_TravelForcedDetourUntil = now + 6f;
            return position + Quaternion.Euler(0f, 90f * m_TravelDetourSide, 0f) * forward * 3f;
        }

        private bool TryTerrainStep(Vector3 position, Vector3 direction, float length, float now, out Vector3 ground)
        {
            ground = position;
            var probe = position + direction * length;
            // From the sky the first hit was a bridge deck 3m above a bot
            // walking the river bank; take the surface closest to its feet.
            var hits = Physics.RaycastAll(
                probe + Vector3.up * 30f,
                Vector3.down,
                60f,
                SwimExitGroundMask,
                QueryTriggerInteraction.Ignore);
            if (hits.Length == 0)
            {
                return false;
            }
            var hit = hits[0];
            for (var i = 1; i < hits.Length; i++)
            {
                if (Mathf.Abs(hits[i].point.y - position.y) < Mathf.Abs(hit.point.y - position.y))
                {
                    hit = hits[i];
                }
            }
            if (SkaliaBotTerrainMap.TryGetCell(hit.point, out _, out var cellFlags)
                && (cellFlags & SkaliaBotTerrainMap.FlagWater) != 0)
            {
                return false;
            }
            var rise = hit.point.y - position.y;
            // The plan crosses the river on the bridge deck; steps that went
            // down the bank beside it led two bots, 4m at a time, onto a
            // ledge 8m under the deck and then into the river. A step may
            // not end more than 3m below the planned point it heads for.
            if (m_TravelPlan.Count > 0
                && m_TravelPlanIndex < m_TravelPlan.Count
                && hit.point.y < m_TravelPlan[m_TravelPlanIndex].y - 3f
                && hit.point.y < position.y - 0.5f)
            {
                return false;
            }
            // Unturned players climb about 45 degrees; a drop of more than 4m
            // over one step is a cliff or a roof edge.
            if (hit.normal.y < 0.7f
                || rise > length * 0.9f
                || rise < -4f
                || WaterUtility.isPointUnderwater(hit.point + Vector3.up * 0.5f)
                || IsHazardousPosition(hit.point, now, 2f))
            {
                return false;
            }
            if (Physics.Linecast(
                    position + Vector3.up * 1.1f,
                    hit.point + Vector3.up * 1.1f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore)
                && !TryFindTraversableOpening(position, direction, length, out _))
            {
                return false;
            }
            ground = hit.point;
            return true;
        }

        // 0.1.173: a bot on top of a tower failed one trip after another and
        // got 5 areas banned for 2 h for every bot; the areas were fine, the
        // bot just could not get down.
        private bool m_TravelStartedUpper;

        private void FailTerrainTravel(float now, string reason)
        {
            var failPosition = m_Player.transform.position;
            var stillUpper = IsUpperFloor(failPosition);
            // 0.1.175: only a trip that started up there. The Rainbridge
            // bridge deck is 23m above the ground too, and 8 trips failed on
            // it in the 0.1.174 test without the area ever being set aside.
            var fromUpper = m_TravelStartedUpper;
            BotLog(LogLevel.Information,
                "Viagem por terreno para {Name} falhou ({Reason}) depois de {Seconds:0}s; flag {Graph} ignorada por 10 min.",
                m_TravelTargetName,
                reason,
                now - m_TravelStartedAt,
                m_TravelTargetGraph);
            m_TravelFailedGraphs[m_TravelTargetGraph] = now + TravelFailedGraphSeconds;
            m_TripFailuresSinceProgress++;
            if (fromUpper)
            {
                BotLog(LogLevel.Information,
                    "Viagem para {Name} saiu de um andar alto; a falha nao conta contra a area nem contra a flag.",
                    m_TravelTargetName);
            }
            if (!fromUpper && m_TravelMeshArea && m_TravelAreaKey.Length > 0)
            {
                m_ExplorationDestinationBlacklist[m_TravelAreaKey] = now + FailedTripAreaOwnSeconds;
                s_FailedTripAreaCounts.TryGetValue(m_TravelAreaKey, out var areaFailures);
                if (++areaFailures >= 2)
                {
                    s_FailedTripAreaCounts.Remove(m_TravelAreaKey);
                    s_FailedTripAreas[m_TravelAreaKey] = now + FailedTripAreaSeconds;
                    BotLog(LogLevel.Information,
                        "Viagem para a area {Name} falhou {Count} vezes entre os bots; nenhum bot escolhe essa area por 2 h.",
                        m_TravelTargetName,
                        areaFailures);
                }
                else
                {
                    s_FailedTripAreaCounts[m_TravelAreaKey] = areaFailures;
                }
            }
            m_TravelMeshArea = false;
            if (m_DeathRecoveryActive)
            {
                // The way back to the death spot is the route that just failed.
                m_DeathRecoveryPending = false;
                m_DeathRecoveryActive = false;
            }
            var graphFailures = 0;
            if (!fromUpper)
            {
                s_TravelGraphFailures.TryGetValue(m_TravelTargetGraph, out graphFailures);
                s_TravelGraphFailures[m_TravelTargetGraph] = ++graphFailures;
            }
            if (!fromUpper && graphFailures >= TravelGraphFailuresToBan)
            {
                s_TravelGraphFailures[m_TravelTargetGraph] = 0;
                s_TravelGraphBannedUntil[m_TravelTargetGraph] = now + TravelGraphBanSeconds;
                BotLog(LogLevel.Information,
                    "Viagem para {Name} falhou {Count} vezes entre os bots; flag {Graph} fora das viagens por 2 h.",
                    m_TravelTargetName,
                    graphFailures,
                    m_TravelTargetGraph);
            }
            m_TravelActive = false;
            m_TravelPhase = 0;
            if (m_ObjectiveType == ObjectiveType.Travel)
            {
                ClearObjective();
            }
            m_NextExplorationSelectionTime = now + 2f;
            // Started up there and never got down: the next trip would fail
            // the same way, so go down now instead of after more failures.
            if (m_TravelStartedUpper && stillUpper)
            {
                TryTeleportDownFromUpperFloor(failPosition, now);
            }
            m_TravelStartedUpper = false;
        }

        private void ChooseLocalExplorationObjective(
            Vector3 position,
            float now,
            string reason)
        {
            if (IsStuckWithoutProgress(now))
            {
                BotLog(LogLevel.Warning,
                    "Bot sem progresso ha {Minutes:0} min em {Position}: {Trips} viagens falharam e nenhuma area foi alcancada; procurando saida (a nado ou teleporte).",
                    (now - m_LastAreaProgressAt) / 60f,
                    FormatPosition(position),
                    m_TripFailuresSinceProgress);
                if (TryEscapePocket(position, now, true))
                {
                    NoteAreaProgress(now);
                    return;
                }
                // No crossing and no dry spawn: try again in 4 min.
                m_LastAreaProgressAt = now;
            }
            var chosen = position;
            GraphNode? originNode = null;
            GraphNode? destinationNode = null;
            // 0.2.2x11: on the new mesh when it is whole. The zombie graph
            // has no node upstairs or on furniture: thigas on the bed of the
            // Arlington Farm house got points 25m away at its own height,
            // in the air outside the house, and walked straight at the wall.
            var meshChosen = SkaliaBotUnityNavmesh.MapFilled
                && TryPickLocalExplorationOnMesh(position, now, out chosen);

            if (!meshChosen && AstarPath.active != null)
            {
                var originInfo = AstarPath.active.GetNearest(position, NNConstraint.Walkable);
                originNode = originInfo.node;
                if (originNode != null)
                {
                    var localConstraint = new NNConstraint
                    {
                        constrainWalkability = true,
                        walkable = true,
                        // With the new mesh whole, any point it reaches will
                        // do, not only the bot's piece of the zombie graph.
                        constrainArea = !SkaliaBotUnityNavmesh.MapFilled,
                        area = (int)originNode.Area,
                        constrainDistance = true
                    };

                    for (var attempt = 0; attempt < 24; attempt++)
                    {
                        var direction = Quaternion.Euler(
                            0f,
                            Random.Range(0f, 360f),
                            0f) * Vector3.forward;
                        var desired = position + direction * Random.Range(25f, 75f);
                        var nearest = AstarPath.active.GetNearest(desired, localConstraint);
                        if (nearest.node == null
                            || !CanReach(originNode, nearest.node, position, nearest.position)
                            || WaterUtility.isPointUnderwater(
                                nearest.position + Vector3.up * 0.5f)
                            || IsHazardousPosition(nearest.position, now, 2f)
                            || (nearest.position - position).GetHorizontalMagnitude() < 15f)
                        {
                            continue;
                        }

                        chosen = nearest.position;
                        destinationNode = nearest.node;
                        break;
                    }
                }
            }

            var hasConnectedDestination = meshChosen || (originNode != null && destinationNode != null);
            if (!hasConnectedDestination)
            {
                var direction = Quaternion.Euler(
                    0f,
                    Random.Range(0f, 360f),
                    0f) * Vector3.forward;
                chosen = position + direction * 25f;
            }

            m_InterestAreaName = "exploracao local";
            m_InterestAreaKey = BuildExplorationDestinationKey(
                m_InterestAreaName,
                chosen);
            m_HasInterestArea = true;
            m_InterestAreaCenter = chosen;
            m_InterestAreaExpiresAt = now + 60f;
            StartInterestAreaBookkeeping(now);
            SetObjective(ObjectiveType.Explore, chosen, now + 30f);

            if (!hasConnectedDestination)
            {
                // There is no useful graph node to request. Keep the controller
                // moving briefly while it searches again instead of standing still.
                m_DirectFallbackUntil = now + 8f;
            }

            BotLog(LogLevel.Information,
                "Bot iniciou exploracao local porque {Reason}: origem regiao {OriginArea}/grafo "
                + "{OriginGraph}; destino regiao {DestinationArea}/grafo {DestinationGraph}; "
                + "posicao {Destination}.",
                reason,
                originNode?.Area,
                originNode?.GraphIndex,
                destinationNode?.Area,
                destinationNode?.GraphIndex,
                FormatPosition(chosen));
        }

        private void BlacklistCurrentExplorationDestination(float now, string reason)
        {
            if (string.IsNullOrEmpty(m_InterestAreaKey))
            {
                m_InterestAreaKey = BuildExplorationDestinationKey(
                    m_InterestAreaName,
                    m_InterestAreaCenter);
            }

            m_ExplorationDestinationBlacklist[m_InterestAreaKey] =
                now + ExplorationBlacklistSeconds;

            GraphNode? originNode = null;
            GraphNode? destinationNode = null;
            if (AstarPath.active != null)
            {
                originNode = AstarPath.active
                    .GetNearest(m_Player.transform.position, NNConstraint.Walkable)
                    .node;
                destinationNode = AstarPath.active
                    .GetNearest(m_InterestAreaCenter, NNConstraint.Walkable)
                    .node;
            }

            BotLog(LogLevel.Information,
                "Area {AreaName} entrou na blacklist por {Seconds:0}s: {Reason}. "
                + "Origem regiao {OriginArea}/grafo {OriginGraph}; destino regiao "
                + "{DestinationArea}/grafo {DestinationGraph}.",
                m_InterestAreaName,
                ExplorationBlacklistSeconds,
                reason,
                originNode?.Area,
                originNode?.GraphIndex,
                destinationNode?.Area,
                destinationNode?.GraphIndex);
        }

        private static string BuildExplorationDestinationKey(
            string areaName,
            Vector3 position)
        {
            return areaName
                + ":"
                + Mathf.RoundToInt(position.x / 10f)
                + ":"
                + Mathf.RoundToInt(position.z / 10f);
        }

        private void AbandonCurrentObjective(float now)
        {
            var abandonedType = m_ObjectiveType;
            if (abandonedType == ObjectiveType.Patrol
                && m_PatrolTargetSet
                && (m_ObjectivePosition - m_PatrolTargetPoint).GetHorizontalMagnitude() < 1f)
            {
                NotePatrolPointFailed(m_PatrolTargetPoint, now, "objetivo abandonado", false);
                m_PatrolTargetSet = false;
            }
            if (m_ObjectiveType == ObjectiveType.Loot)
            {
                IgnoreLoot(m_LootInstanceId, now + 30f);
            }

            ClearObjective();
            if (abandonedType == ObjectiveType.Explore || !m_HasInterestArea)
            {
                m_HasInterestArea = false;
                ChooseExplorationObjective(m_Player.transform.position, now);
            }
            else
            {
                ChooseAreaPatrolObjective(m_Player.transform.position, now);
            }
        }

        private bool IsInsideInterestArea(Vector3 point, float tolerance)
        {
            if (!m_HasInterestArea)
            {
                return true;
            }

            var offset = point - m_InterestAreaCenter;
            var radius = InterestAreaRadiusMeters + tolerance;
            return offset.x * offset.x + offset.z * offset.z <= radius * radius;
        }

        private void ClearObjective()
        {
            if (m_ObjectiveType == ObjectiveType.Loot)
            {
                ReleaseLootClaim();
            }
            if (IsTaskObjective(m_ObjectiveType))
            {
                m_LastTaskPosition = m_ObjectivePosition;
                m_LastTaskAt = Time.realtimeSinceStartup;
            }
            m_ObjectiveType = ObjectiveType.None;
            m_TargetZombie = null;
            m_LootRegionX = byte.MaxValue;
            m_LootRegionY = byte.MaxValue;
            m_LootInstanceId = 0;
            m_LootTargetIsCombatEquipment = false;
            m_LootTargetIsRangedWeapon = false;
            m_LootWithinReachSince = 0f;
            ClearPath();
        }

        private void SetObjective(ObjectiveType type, Vector3 destination, float expiresAt)
        {
            var previousType = m_ObjectiveType;
            if (type == ObjectiveType.Combat
                && previousType != ObjectiveType.Combat
                && previousType != ObjectiveType.EscapeSwarm
                && m_TargetZombie != null)
            {
                NoteCombatRestart(m_TargetZombie, Time.realtimeSinceStartup);
            }
            if (previousType == ObjectiveType.Loot && type != ObjectiveType.Loot)
            {
                ReleaseLootClaim();
                m_LootInstanceId = 0;
                m_LootTargetIsCombatEquipment = false;
                m_LootTargetIsRangedWeapon = false;
                m_LootWithinReachSince = 0f;
            }
            var changed = m_ObjectiveType != type
                || (destination - m_ObjectivePosition).GetHorizontalMagnitude() > 4f;
            if (previousType != type)
            {
                m_ObjectiveTypeSince = Time.realtimeSinceStartup;
            }
            if (IsTaskObjective(previousType) && !IsTaskObjective(type))
            {
                m_LastTaskPosition = m_ObjectivePosition;
                m_LastTaskAt = Time.realtimeSinceStartup;
            }
            m_ObjectiveType = type;
            m_ObjectivePosition = destination;
            m_ObjectiveExpiresAt = expiresAt;
            if (changed)
            {
                m_ConsecutiveStuckChecks = 0;
                ClearPath();
                if (previousType != type
                    || type == ObjectiveType.Explore
                    || type == ObjectiveType.Patrol
                    || type == ObjectiveType.Loot
                    || type == ObjectiveType.Unstuck)
                {
                    LogObjectiveTransition(previousType, type, destination);
                }
            }
        }

        private void LogObjectiveTransition(ObjectiveType previousType, ObjectiveType type, Vector3 destination)
        {
            if (previousType != type)
            {
                m_StatObjectiveChanges++;
            }
            // Repeated patrol waypoints stay at Debug; every real change of
            // objective is logged at Information with the bot's condition.
            var level = previousType == type && type == ObjectiveType.Patrol
                ? LogLevel.Debug
                : LogLevel.Information;
            string reason;
            switch (type)
            {
                case ObjectiveType.Explore:
                    reason = "indo para area " + m_InterestAreaName;
                    break;
                case ObjectiveType.Patrol:
                    reason = "vasculhando " + m_InterestAreaName;
                    break;
                case ObjectiveType.Loot:
                    reason = "coletar " + DescribeTargetLoot()
                        + (m_LootTargetIsCombatEquipment ? " (equipamento de combate)" : string.Empty);
                    break;
                case ObjectiveType.Combat:
                    reason = "atacar zumbi a "
                        + (destination - m_Player.transform.position).GetHorizontalMagnitude().ToString("0.#")
                        + "m";
                    break;
                case ObjectiveType.Flee:
                    reason = "fugir de " + m_FleeingFromPlayerName;
                    break;
                case ObjectiveType.EscapeHazard:
                    reason = "sair de area perigosa";
                    break;
                case ObjectiveType.RepositionFire:
                    reason = "manter distancia do zumbi de fogo";
                    break;
                case ObjectiveType.EscapeSwarm:
                    reason = "escapar do cerco de zumbis";
                    break;
                case ObjectiveType.ExitWater:
                    reason = "sair da agua";
                    break;
                case ObjectiveType.Unstuck:
                    reason = "ponto de recuperacao de travamento";
                    break;
                case ObjectiveType.OpenDoor:
                    reason = "abrir " + (m_DoorApproachDoor?.Name ?? "porta");
                    break;
                case ObjectiveType.Travel:
                    reason = (m_TravelPhase == 1 ? "indo ate a borda da malha rumo a " : "viajando pelo terreno ate ")
                        + m_TravelTargetName;
                    break;
                default:
                    reason = type.ToString();
                    break;
            }
            BotLog(level,
                "Objetivo {Previous} -> {Objective} ({Class}): {Reason}; destino {Destination}; vida {Health}; stamina {Stamina}; arma {Weapon}; zumbis percebidos {Perceived} (marcados {Marked}); atras do bot a 8m {Hunters8}, a 20m {Hunters20}.",
                previousType,
                type,
                IsThreatObjective(type) ? "reacao" : "rotina",
                reason,
                FormatPosition(destination),
                m_Player.life.health,
                m_Player.life.stamina,
                DescribeEquipped(),
                m_PerceivedZombies.Count,
                m_MarkedSeenZombies.Count,
                m_ThreatHunters8,
                m_ThreatHunters20);
        }

        private string DescribeTargetLoot()
        {
            return TryGetTargetLoot(out var target)
                ? DescribeItem(target.item)
                : "loot " + m_LootInstanceId;
        }

        private static string DescribeItem(Item? item)
        {
            if (item == null)
            {
                return "?";
            }
            var asset = item.GetAsset();
            return asset != null
                ? asset.itemName + " #" + item.id
                : "item #" + item.id;
        }

        private string DescribeEquipped()
        {
            var asset = m_Player.equipment.asset;
            if (asset == null)
            {
                return "punhos";
            }
            if (asset is ItemGunAsset gun)
            {
                var state = m_Player.equipment.state;
                var ammo = state != null && state.Length > 10 ? state[10] : (byte)0;
                return gun.itemName + " (municao " + ammo + ")";
            }
            return asset.itemName;
        }

        private string DescribeInventory()
        {
            int total = 0, melee = 0, guns = 0, loadedGuns = 0, food = 0, water = 0, medical = 0, ammo = 0;
            for (byte page = 0; page < PlayerInventory.STORAGE; page++)
            {
                var count = m_Player.inventory.getItemCount(page);
                for (byte index = 0; index < count; index++)
                {
                    var jar = m_Player.inventory.getItem(page, index);
                    var asset = jar?.GetAsset();
                    if (asset == null)
                    {
                        continue;
                    }
                    total++;
                    switch (asset)
                    {
                        case ItemMeleeAsset _:
                            melee++;
                            break;
                        case ItemGunAsset gun:
                            guns++;
                            if (IsLoadedGun(gun, jar!.item.state))
                            {
                                loadedGuns++;
                            }
                            break;
                        case ItemMedicalAsset _:
                            medical++;
                            break;
                        case ItemWaterAsset _:
                            water++;
                            break;
                        case ItemFoodAsset _:
                            food++;
                            break;
                        case ItemMagazineAsset _:
                            ammo++;
                            break;
                    }
                }
            }
            return total + " itens (melee " + melee + ", armas " + guns + "/" + loadedGuns
                + " carregadas, carregadores " + ammo + ", comida " + food + ", agua " + water
                + ", medico " + medical + ")";
        }

        private Vector3 GetNavigationTarget(Vector3 position, float now)
        {
            m_NavigationHold = false;
            m_NavigationHoldMayCoast = false;
            // A new-mesh route is only its corners, each 0.4m off the wall.
            // Taking a corner as reached at 2.5m, or skipping it when a chest
            // ray clears it, cut the doorway and walked into the frame: 27 of
            // 41 circles in one test. A corner counts at 0.8m, or once the
            // next one is in a straight line on the mesh, which already keeps
            // the body's width from the walls.
            if (m_PathFromUnity)
            {
                // A ladder on the route: the corner at its foot and the next
                // one at its top. Climb it like the ladder escape does.
                if (m_PathIndex + 1 < m_PathPoints.Count
                    && (m_PathPoints[m_PathIndex] - position).GetHorizontalMagnitude() <= 2f
                    && Mathf.Abs(m_PathPoints[m_PathIndex].y - position.y) <= 1.8f)
                {
                    var ladder = SkaliaBotUnityNavmesh.LadderBetween(m_PathPoints[m_PathIndex], m_PathPoints[m_PathIndex + 1]);
                    if (ladder != null && !IsLadderPaused(ladder.Index, now))
                    {
                        StartLadderClimb(ladder, now, "a rota da malha nova sobe por ela");
                        return position;
                    }
                    // 0.2.2: and down it, the player way (SkaliaBotPlayerFeel).
                    var downLadder = s_Settings.LadderDescend
                        ? SkaliaBotUnityNavmesh.LadderBetween(m_PathPoints[m_PathIndex + 1], m_PathPoints[m_PathIndex])
                        : null;
                    if (downLadder != null && !IsLadderPaused(downLadder.Index, now))
                    {
                        StartLadderDescent(downLadder, now);
                        return position;
                    }
                }
                // As SAIN does (BotPathData.CheckCornerComplete): a corner is
                // reached at 0.3m, and skipped for the next one only from
                // under 1m and with the next in a straight line. Taking it at
                // 0.8m, or skipping it from anywhere, cut every door frame by
                // up to 0.8m: the turn the mesh drew at the wall's corner was
                // walked inside the wall.
                while (m_PathIndex < m_PathPoints.Count
                       && Mathf.Abs(m_PathPoints[m_PathIndex].y - position.y) <= 1.8f
                       && ((m_PathPoints[m_PathIndex] - position).GetHorizontalMagnitude() <= CornerReachMeters
                           || ((m_PathPoints[m_PathIndex] - position).GetHorizontalMagnitude() < CornerSkipMeters
                               && m_PathIndex + 1 < m_PathPoints.Count
                               && SkaliaBotUnityNavmesh.IsStraight(position, m_PathPoints[m_PathIndex + 1])
                               // A corner added to keep the body off a wall
                               // the mesh grazes is not cut short.
                               && SkaliaBotUnityNavmesh.IsBodyClear(position, m_PathPoints[m_PathIndex + 1]))
                           || HasPassedCorner(position)
                           // 0.2.2x10: stepped over it between two checks.
                           || PassedCornerSinceLastCheck(m_PathPoints[m_PathIndex], position)))
                {
                    m_PathIndex++;
                }
                NoteCornerCheck(position);
                // 0.2.2: a jump up a ledge or a low passage on the route.
                UpdateShortcutLeg(position, now);
                UpdateRouteHop(position, now);
                if (m_OffLineCornerGeneration != m_PathRequestGeneration || m_OffLineCornerIndex != m_PathIndex)
                {
                    m_OffLineCornerGeneration = m_PathRequestGeneration;
                    m_OffLineCornerIndex = m_PathIndex;
                    m_OffLineCornerSince = now;
                }
                // The corner ahead must be in a straight line on the mesh
                // from where the bot stands. Steering around zombies, side
                // steps and sliding along walls take it off the line between
                // two corners, and from there the next one can be behind a
                // wall. In the 0.1.132 test all 19 walls a route went through
                // were blocked on the mesh itself (live and rebuilt): the mesh
                // was right, the bot was aiming at a corner it could not see.
                // Route again from here instead of pushing into the wall.
                // SAIN's test as well (BotPathData.CheckStuck): a second into
                // a leg, heading more than ~41 degrees off it means off the line.
                // Close to the zombie the combat steering moves the body, not
                // the route: 232 of the 678 logged "off the line" repaths of
                // the 0.1.141 test were fights, each one a route thrown away.
                var steeredByCombat = m_ObjectiveType == ObjectiveType.Combat && !m_CombatByRoute;
                var offLeg = false;
                if (!steeredByCombat
                    && m_RouteHopIndex < 0
                    && !IsOnShortcutLeg()
                    && m_PathIndex < m_PathPoints.Count
                    && now >= m_NextOffLineRepathAt
                    && Mathf.Abs(m_PathPoints[m_PathIndex].y - position.y) <= 0.5f
                    && SkaliaBotUnityNavmesh.IsOnMesh(position)
                    // 0.2.2x11: a corner the body walks to in a straight line
                    // is not thrown away (llo 02:22:34: a corner 0.9m away
                    // "not in a straight line" by the mesh edge, 13 routes and
                    // a circle; the tester: the bot goes back and forth).
                    && !IsCornerWalkable(position, m_PathPoints[m_PathIndex])
                    && ((offLeg = IsOffLegHeading(position, now))
                        || SkaliaBotUnityNavmesh.IsWallBefore(position, m_PathPoints[m_PathIndex], 0.5f)))
                {
                    // 0.1.173: first try the route already in hand: the next
                    // corner, or the one just passed, in a straight line from
                    // here. 0.1.172 threw away 3-4 routes a minute this way.
                    if (TryRejoinRoute(position, now))
                    {
                        m_NextOffLineRepathAt = now + 1f;
                    }
                    else
                    {
                        if (now - m_OffLineRepathWindowAt > 10f)
                        {
                            m_OffLineRepathWindowAt = now;
                            m_OffLineRepathCount = 0;
                        }
                        m_OffLineRepathCount++;
                        // Three in 10s: routing again from here does not help;
                        // leave it to the stuck handling for a while.
                        m_NextOffLineRepathAt = now + (m_OffLineRepathCount >= 3 ? 15f : 2f);
                        m_OffLineRepaths++;
                        if (now >= m_NextOffLineLogAt)
                        {
                            m_NextOffLineLogAt = now + 10f;
                            BotLog(LogLevel.Information,
                                "Malha nova: ponto {Corner} da rota ({Index}/{Count}) nao esta em linha reta de {Position} ({Why}; objetivo {Objective}); pedindo rota nova daqui ({Total} no total).",
                                FormatPosition(m_PathPoints[m_PathIndex]),
                                m_PathIndex + 1,
                                m_PathPoints.Count,
                                FormatPosition(position),
                                offLeg ? "fora do rumo do trecho" : "borda da malha no caminho",
                                m_ObjectiveType,
                                m_OffLineRepaths);
                        }
                        ClearPath();
                        return position;
                    }
                }
            }
            while (!m_PathFromUnity
                   && m_PathIndex < m_PathPoints.Count
                   && (m_PathPoints[m_PathIndex] - position).GetHorizontalMagnitude() <= 2.5f
                   && Mathf.Abs(m_PathPoints[m_PathIndex].y - position.y) <= 1.8f)
            {
                m_PathIndex++;
            }

            if (now >= m_RouteCommitUntil && !m_PathFromUnity && CheckCornerOvershoot(position, now))
            {
                return position;
            }

            // Skip redundant corners when the following waypoint is directly
            // visible. This prevents left/right oscillation on dense paths.
            while (!m_PathFromUnity
                   && m_PathIndex + 1 < m_PathPoints.Count
                   && Mathf.Abs(m_PathPoints[m_PathIndex + 1].y - position.y) <= 1.5f
                   && !Physics.Linecast(
                       position + Vector3.up * 1.1f,
                       m_PathPoints[m_PathIndex + 1] + Vector3.up * 1.1f,
                       RayMasks.BLOCK_COLLISION,
                       QueryTriggerInteraction.Ignore))
            {
                m_PathIndex++;
            }

            if (m_ObjectiveType == ObjectiveType.ExitWater && m_SwimExitActive)
            {
                m_HasNavmeshReturnPoint = false;
                return m_Player.stance.stance == EPlayerStance.SWIM
                       && (m_SwimExitShallows - position).GetHorizontalMagnitude() > 1.5f
                       && (m_ObjectivePosition - position).GetHorizontalMagnitude()
                          > (m_ObjectivePosition - m_SwimExitShallows).GetHorizontalMagnitude()
                    ? m_SwimExitShallows
                    : m_ObjectivePosition;
            }
            var destinationChanged = (m_PlannedDestination - m_ObjectivePosition)
                .GetHorizontalMagnitude() > 4f;
            if (m_HasNavmeshReturnPoint)
            {
                if (now < m_NavmeshReturnUntil
                    && (m_NavmeshReturnPoint - position).GetHorizontalMagnitude() > 1.25f)
                {
                    // The route starts at the nearest graph node; walk there first.
                    return m_NavmeshReturnPoint;
                }
                m_HasNavmeshReturnPoint = false;
            }
            if (now < m_DirectFallbackUntil)
            {
                return m_ObjectivePosition;
            }
            // 0.2.2x9: waiting for a ladder that just failed, or for the mesh
            // to be ready, standing still (not walking blind at the wall).
            if (m_PathPoints.Count == 0
                && now < m_RouteWaitUntil
                && (m_RouteWaitDestination - m_ObjectivePosition).GetHorizontalMagnitude() <= 4f)
            {
                m_NavigationHold = true;
                return position;
            }
            // At most one route every 2s to the same place: the circles of
            // the last logs asked for 5 to 20 in 8s.
            var sameDestination = (m_LastRouteRequestDestination - m_ObjectivePosition).GetHorizontalMagnitude() <= 4f;
            var rateLimited = sameDestination && now - m_LastRouteRequestAt < RouteRequestSpacingSeconds;
            if (!m_PathPending
                && now >= m_NextPathRequestTime
                && (m_PathPoints.Count == 0 || destinationChanged)
                && !rateLimited)
            {
                m_LastRouteRequestAt = now;
                m_LastRouteRequestDestination = m_ObjectivePosition;
                RequestPath(position, m_ObjectivePosition, now);
            }

            if ((m_PathPending || rateLimited) && m_PathPoints.Count == 0)
            {
                // 0.2.2x9: this used to walk on in whatever heading the bot
                // had, into the fence it had just turned from.
                m_NavigationHold = true;
                m_NavigationHoldMayCoast = true;
                return position;
            }

            if (m_PathIndex < m_PathPoints.Count)
            {
                return m_PathPoints[m_PathIndex];
            }
            return GetRouteEndTarget(position, now);
        }

        // A bot that keeps falling back to local exploration because nothing
        // is reachable, without leaving 120m for 10 min, is in a pocket it
        // cannot walk out of (water or cliffs all around). In the 0.1.150
        // test XXlloqiartyXX swam onto such a strip and stayed 50 min until
        // it died of thirst. It is moved to the nearest dry spawn 200m+ away.
        private Vector3 m_PocketAnchor;
        private float m_PocketSince = float.NegativeInfinity;
        private const float PocketRadiusMeters = 120f;
        private const float PocketSeconds = 600f;
        // 0.1.168: Tadeu spent 37 of the 63 min of the 0.1.167 test south of
        // Seattle after a trip toward Rainbridge Island ended off the mesh:
        // 20 trips failed and 207 local searches in a row, but he wandered
        // 200m, so the 120m pocket clock kept starting over and the way out
        // came only after 11 min. Four minutes with no area reached, no
        // trip finished and three trips failed is enough to know.
        private float m_LastAreaProgressAt;
        private int m_TripFailuresSinceProgress;
        private const float NoProgressEscapeSeconds = 240f;
        private const int NoProgressTripFailures = 3;
        // Areas a trip failed to reach, for every bot: Rainbridge Island was
        // tried by two bots in three minutes.
        // Two failures, by any bots, keep the area out of the picks for 2 h;
        // the bot that failed leaves it alone for 30 min.
        private static readonly Dictionary<string, float> s_FailedTripAreas = new Dictionary<string, float>();
        private static readonly Dictionary<string, int> s_FailedTripAreaCounts = new Dictionary<string, int>();
        private const float FailedTripAreaSeconds = 7200f;
        private const float FailedTripAreaOwnSeconds = 1800f;

        private void NoteAreaProgress(float now)
        {
            m_LastAreaProgressAt = now;
            m_TripFailuresSinceProgress = 0;
        }

        private bool IsStuckWithoutProgress(float now)
        {
            return m_TripFailuresSinceProgress >= NoProgressTripFailures
                && now - m_LastAreaProgressAt >= NoProgressEscapeSeconds;
        }

        private void TrackPocket(Vector3 position, float now)
        {
            if (float.IsNegativeInfinity(m_PocketSince)
                || (position - m_PocketAnchor).GetHorizontalMagnitude() > PocketRadiusMeters)
            {
                m_PocketAnchor = position;
                m_PocketSince = now;
            }
        }

        // Out of the pocket like a player: swim across to the nearest dry
        // land on the new mesh that the pocket does not walk to. Only if no
        // crossing exists (cliffs all around) is the bot moved to a spawn.
        private Vector3 m_PocketSwimFrom;
        private float m_PocketSwimUntil = float.NegativeInfinity;
        private const float PocketCheckSeconds = 300f;

        private bool TryEscapePocket(Vector3 position, float now, bool force = false)
        {
            if (force)
            {
                m_PocketSince = m_LastAreaProgressAt;
            }
            else if (now - m_PocketSince < PocketCheckSeconds)
            {
                return false;
            }
            if (SkaliaBotUnityNavmesh.TryFindWaterCrossing(position, out var land, out var shallows, out var swim))
            {
                BotLog(LogLevel.Information,
                    "Bot sem saida a pe ha {Minutes:0} min em {Position}; atravessando a agua a nado ate {Land} ({Distance:0}m, {Swim:0}m nadando).",
                    (now - m_PocketSince) / 60f,
                    FormatPosition(position),
                    FormatPosition(land),
                    (land - position).GetHorizontalMagnitude(),
                    swim);
                m_PocketSince = now;
                m_PocketSwimFrom = position;
                m_PocketSwimUntil = now + 240f;
                m_TravelActive = false;
                m_TravelPhase = 0;
                ClearObjective();
                m_SwimExitActive = true;
                m_SwimExitShallows = shallows;
                m_SwimExitBestDistance = (land - position).GetHorizontalMagnitude();
                m_SwimExitProgressSince = now;
                SetObjective(ObjectiveType.ExitWater, land, now + 180f);
                return true;
            }
            if ((!force && now - m_PocketSince < PocketSeconds)
                || !TryPickDrySpawn(position, 200f, out var away))
            {
                return false;
            }
            BotLog(LogLevel.Warning,
                "Bot preso ha {Minutes:0} min num raio de {Radius:0}m em {Position}, sem area alcancavel nem travessia a nado; teleportando para {Destination} ({Distance:0}m).",
                (now - m_PocketSince) / 60f,
                PocketRadiusMeters,
                FormatPosition(position),
                FormatPosition(away),
                (away - position).GetHorizontalMagnitude());
            m_PocketSince = float.NegativeInfinity;
            m_InWaterSince = -1f;
            m_WaterEpisodeSince = -1f;
            m_LocalRecoveryPhase = LocalRecoveryPhase.None;
            m_TravelActive = false;
            m_TravelPhase = 0;
            ClearObjective();
            TeleportBot(away, m_Player.look.yaw);
            m_StallAnchor = away;
            m_NextExplorationSelectionTime = 0f;
            return true;
        }

        // 0.2.2x9 (doc 16.17): routes come from the new mesh only. When it
        // has no complete route, RequestRouteWithoutFullPath (SkaliaBotRouteX9)
        // decides per reason: wait for a ladder, walk as far as it reaches,
        // a long trip leg by leg, onto the mesh first, or fail the objective.
        private void RequestPath(Vector3 origin, Vector3 destination, float now)
        {
            NoteRouteRequest(origin, now);
            m_RouteWaitUntil = 0f;
            if (SkaliaBotUnityNavmesh.TryFindPath(origin, destination, m_UnityPathScratch))
            {
                if (TryWaitForRouteLadder(origin, destination, now))
                {
                    return;
                }
                AcceptUnityRoute(origin, destination, now, RouteEnd.Full, "malha nova");
                return;
            }
            RequestRouteWithoutFullPath(origin, destination, now);
        }

        private bool AcceptPathPoints(Vector3 origin, Vector3 destination, float now, string mesh)
        {
            if ((m_ObjectiveType == ObjectiveType.Patrol
                    || m_ObjectiveType == ObjectiveType.Explore
                    || m_ObjectiveType == ObjectiveType.Loot)
                && PathCrossesOrbitBadSpot(m_PathPoints, origin, destination, now))
            {
                m_PathPoints.Clear();
                m_PathFailed = true;
                m_PathRejectedByBadSpot = true;
                m_LastPathFailureReason = "a rota passa por um ponto onde o bot andou em circulo";
                m_StatPathFailures++;
                if (++m_BadSpotRejectStreak >= BadSpotRejectStreakLimit)
                {
                    m_BadSpotRejectStreak = 0;
                    m_IgnoreBadSpotsUntil = now + IgnoreBadSpotsSeconds;
                    BotLog(LogLevel.Information,
                        "{Count} rotas seguidas recusadas por passar onde o bot andou em circulo; aceitando essas rotas por {Seconds:0}s.",
                        BadSpotRejectStreakLimit,
                        IgnoreBadSpotsSeconds);
                }
                if (now >= m_NextBadSpotRouteLogAt)
                {
                    m_NextBadSpotRouteLogAt = now + 5f;
                    BotLog(LogLevel.Information,
                        "Rota para {Destination} ({State}) passa por ponto onde o bot andou em circulo; descartada.",
                        FormatPosition(destination),
                        m_ObjectiveType);
                }
                return false;
            }
            m_BadSpotRejectStreak = 0;
            if (m_PathPoints.Count > 0)
            {
                m_LastPathEnd = m_PathPoints[m_PathPoints.Count - 1];
                m_LastPathEndLootId = m_ObjectiveType == ObjectiveType.Loot ? m_LootInstanceId : 0;
            }
            BotLog(LogLevel.Debug,
                "Rota do bot calculada para {Destination}: {PointCount} ponto(s), estado {State}, {Mesh}.",
                FormatPosition(destination),
                m_PathPoints.Count,
                m_ObjectiveType,
                mesh);
            return true;
        }

        // 0.2.2x9: the nearest point of the new mesh (8m), not of the
        // zombie mesh.
        private static Vector3 FindNearestNavigablePoint(Vector3 desired)
        {
            return SkaliaBotUnityNavmesh.TrySnap(desired, 8f, out var snapped) ? snapped : desired;
        }

        // 0.2.2x9: the new-mesh point near `desired`, in the shape the
        // zombie-mesh lookups had (node is always null now).
        private static (Vector3 position, GraphNode? node, bool found) SnapToNewMesh(Vector3 desired, float radius)
        {
            if (SkaliaBotUnityNavmesh.TrySnap(desired, radius, out var snapped))
            {
                return (snapped, (GraphNode?)null, true);
            }
            return (desired, (GraphNode?)null, false);
        }

        private bool TryFindConnectedRetreatPoint(
            Vector3 origin,
            Vector3 threat,
            float now,
            out Vector3 retreatPoint)
        {
            retreatPoint = origin;
            if (!SkaliaBotUnityNavmesh.MapFilled)
            {
                return false;
            }
            var away = origin - threat;
            away.y = 0f;
            if (away.sqrMagnitude < 0.01f)
            {
                away = Quaternion.Euler(0f, m_CurrentYaw + 180f, 0f)
                    * Vector3.forward;
            }
            away.Normalize();

            var bestScore = float.NegativeInfinity;
            for (var radius = 6f; radius <= 18f; radius += 4f)
            {
                for (var step = -3; step <= 3; step++)
                {
                    var direction = Quaternion.Euler(0f, step * 25f, 0f) * away;
                    if (!SkaliaBotUnityNavmesh.TrySnap(origin + direction * radius, 3f, out var snapped))
                    {
                        continue;
                    }
                    var nearest = (position: snapped, node: (GraphNode?)null);
                    if (CrossesWater(origin, nearest.position)
                        || IsHazardousPosition(nearest.position, now, 2f)
                        || !m_Player.stance.wouldHaveHeightClearanceAtPosition(
                            nearest.position,
                            0.5f)
                        || !CanReach(null, null, origin, nearest.position))
                    {
                        continue;
                    }
                    var movement = (nearest.position - origin).GetHorizontalMagnitude();
                    if (movement < 3f)
                    {
                        continue;
                    }
                    var threatDistance = (nearest.position - threat).GetHorizontalMagnitude();
                    var score = threatDistance
                        + Vector3.Dot(direction.normalized, away) * 4f
                        - Mathf.Abs(nearest.position.y - origin.y) * 0.5f;
                    if (score <= bestScore)
                    {
                        continue;
                    }
                    bestScore = score;
                    retreatPoint = nearest.position;
                }
            }
            return bestScore > float.NegativeInfinity;
        }

        private static Vector3 FindNearestDryNavigablePoint(
            Vector3 origin,
            Vector3? excluded)
        {
            var best = Vector3.zero;
            var bestDistanceSquared = float.PositiveInfinity;
            for (var radius = 6f; radius <= 96f; radius += 6f)
            {
                for (var step = 0; step < 16; step++)
                {
                    var direction = Quaternion.Euler(0f, step * 22.5f, 0f)
                        * Vector3.forward;
                    var candidate = FindNearestNavigablePoint(origin + direction * radius);
                    if (WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                        || (excluded.HasValue
                            && (candidate - excluded.Value).GetHorizontalMagnitude() < 5f))
                    {
                        continue;
                    }

                    var offset = candidate - origin;
                    var distanceSquared = offset.x * offset.x + offset.z * offset.z;
                    if (distanceSquared < 4f || distanceSquared >= bestDistanceSquared)
                    {
                        continue;
                    }

                    best = candidate;
                    bestDistanceSquared = distanceSquared;
                }

                if (bestDistanceSquared < float.PositiveInfinity)
                {
                    return best;
                }
            }

            return FindNearestNavigablePoint(origin);
        }

        // SAIN's check: a second after a corner became the target, if it no
        // longer lies ahead along its leg of the route, the bot went past it.
        // Turning back to it is how a circle starts; a new route from here
        // is cheaper than the 8s the circle detector needs.
        private const float OvershootDot = 0.3f;
        private int m_CornerGeneration = -1;
        private int m_CornerIndex = -1;
        private float m_CornerSince;
        private float m_NextOvershootReplanAt;
        private float m_NextOvershootLogAt;

        private bool CheckCornerOvershoot(Vector3 position, float now)
        {
            if (m_PathIndex <= 0 || m_PathIndex >= m_PathPoints.Count)
            {
                return false;
            }
            if (m_CornerGeneration != m_PathRequestGeneration || m_CornerIndex != m_PathIndex)
            {
                m_CornerGeneration = m_PathRequestGeneration;
                m_CornerIndex = m_PathIndex;
                m_CornerSince = now;
                return false;
            }
            var corner = m_PathPoints[m_PathIndex];
            var toCorner = corner - position;
            toCorner.y = 0f;
            var leg = corner - m_PathPoints[m_PathIndex - 1];
            leg.y = 0f;
            if (now - m_CornerSince < 1f
                || now < m_NextOvershootReplanAt
                || toCorner.magnitude > 3f
                || leg.sqrMagnitude < 0.25f
                || Mathf.Abs(corner.y - position.y) > 1.8f
                || m_ObjectiveType == ObjectiveType.Ladder
                || m_ObjectiveType == ObjectiveType.ExitWater
                || m_Player.stance.stance == EPlayerStance.SWIM
                || Vector3.Dot(toCorner.normalized, leg.normalized) >= OvershootDot)
            {
                return false;
            }
            m_NextOvershootReplanAt = now + 3f;
            if (now >= m_NextOvershootLogAt)
            {
                m_NextOvershootLogAt = now + 10f;
                BotLog(LogLevel.Information,
                    "Passou do ponto da rota em {Corner} ({Distance:0.0}m, ponto {Index}/{Count}); pedindo rota nova daqui em vez de voltar.",
                    FormatPosition(corner),
                    toCorner.magnitude,
                    m_PathIndex,
                    m_PathPoints.Count);
            }
            ClearPath();
            return true;
        }

        // Route follower (0.1.106). Up to seven systems could change the
        // target or throw the route away on any step: wall detour, furniture
        // detour, shortcut, overshoot reset, obstacle replan, circle
        // detector, stuck rescue. Each fixed one case; together they made the
        // back and forth of 117 circles in 2h16. On a new-mesh route the
        // route alone now decides where to go, as SAIN does: the body turns
        // while the 8 keys keep walking toward the corner, a passed corner is
        // dropped, sprint stops before a sharp turn, and a real block gets a
        // jump, then a side step, then the spot cut out and one new route.
        private const float RouteRequestSpacingSeconds = 2f;
        private float m_LastRouteRequestAt = -10f;
        private Vector3 m_LastRouteRequestDestination;
        private float m_FollowSideUntil;
        private Vector3 m_FollowSideTarget;
        private int m_FollowSide = 1;
        private int m_FollowGeneration = -1;
        private int m_FollowIndex = -1;
        private float m_FollowBest;
        private float m_FollowSince;
        private Vector3 m_FollowAnchor;
        private int m_FollowEarlyRepaths;
        private int m_FollowStage;

        private bool IsMeshFollowing()
        {
            return HasMeshRoute()
                   && !m_HasNavmeshReturnPoint
                   && m_ObjectiveType != ObjectiveType.Unstuck
                   && m_ObjectiveType != ObjectiveType.Ladder
                   && m_ObjectiveType != ObjectiveType.ExitWater
                   && m_Player.stance.stance != EPlayerStance.SWIM
                   && !((m_ObjectiveType == ObjectiveType.Combat
                         || m_ObjectiveType == ObjectiveType.EscapeSwarm)
                        && IsTargetZombieAlive()
                        && !m_CombatByRoute);
        }

        private const float CombatRouteApproachMeters = 6f;
        private bool m_CombatByRoute;

        // Past the corner: it lies behind the bot along the leg that leads to
        // it, and the next corner is ahead.
        private const float CornerReachMeters = 0.3f;
        private const float CornerSkipMeters = 1f;
        private const float OffLegDot = 0.75f;
        private int m_OffLineCornerGeneration = -1;
        private int m_OffLineCornerIndex = -1;
        private float m_OffLineCornerSince;

        private bool IsOffLegHeading(Vector3 position, float now)
        {
            if (m_PathIndex <= 0 || now - m_OffLineCornerSince < 1f)
            {
                return false;
            }
            var toCorner = m_PathPoints[m_PathIndex] - position;
            toCorner.y = 0f;
            var leg = m_PathPoints[m_PathIndex] - m_PathPoints[m_PathIndex - 1];
            leg.y = 0f;
            if (toCorner.magnitude < 1f || leg.magnitude < 1f)
            {
                return false;
            }
            return Vector3.Dot(toCorner.normalized, leg.normalized) < OffLegDot;
        }

        private float m_NextOffLineRepathAt;
        private float m_OffLineRepathWindowAt = float.NegativeInfinity;
        private int m_OffLineRepathCount;
        private int m_OffLineRepaths;
        private float m_NextOffLineLogAt;

        private bool HasPassedCorner(Vector3 position)
        {
            if (m_PathIndex <= 0 || m_PathIndex + 1 >= m_PathPoints.Count)
            {
                return false;
            }
            var corner = m_PathPoints[m_PathIndex];
            var toCorner = corner - position;
            toCorner.y = 0f;
            var leg = corner - m_PathPoints[m_PathIndex - 1];
            leg.y = 0f;
            return toCorner.magnitude <= 2.5f
                   && leg.sqrMagnitude > 0.25f
                   && Vector3.Dot(toCorner, leg) < 0f
                   && SkaliaBotUnityNavmesh.IsStraight(position, m_PathPoints[m_PathIndex + 1])
                   && SkaliaBotUnityNavmesh.IsBodyClear(position, m_PathPoints[m_PathIndex + 1]);
        }

        // Walk through the turn instead of stopping to face it; only the
        // sprint waits, near a sharp corner or while the body is still far
        // off the heading.
        private void ApplyFollowerPace(Vector3 position, Vector3 navigationTarget)
        {
            var toTarget = navigationTarget - position;
            toTarget.y = 0f;
            var distance = toTarget.magnitude;
            if (distance < 0.1f)
            {
                return;
            }
            var turn = Mathf.Abs(Mathf.DeltaAngle(m_CurrentYaw, DirectionToYaw(toTarget)));
            if (turn > 30f)
            {
                m_IsSprinting = false;
                return;
            }
            if (m_PathIndex + 1 < m_PathPoints.Count && distance < 3f)
            {
                var next = m_PathPoints[m_PathIndex + 1] - m_PathPoints[m_PathIndex];
                next.y = 0f;
                if (next.sqrMagnitude > 0.01f && Vector3.Angle(toTarget, next) > 45f)
                {
                    m_IsSprinting = false;
                }
            }
        }

        private void UpdateFollowerProgress(Vector3 position, bool following, float now)
        {
            // "following" was decided earlier in the tick; the furniture
            // step-away ("Encostado em Couch_0") can clear the route since.
            if (!following || !m_IsWalking || m_PathIndex >= m_PathPoints.Count)
            {
                // The moment between a route dropped here and the new one
                // is not a fresh start either.
                if ((m_PathPending || m_PathPoints.Count == 0)
                    && m_FollowStage > 0
                    && now - m_FollowSince < 10f
                    && (position - m_FollowAnchor).GetHorizontalMagnitude() < 0.5f)
                {
                    return;
                }
                m_FollowAnchor = position;
                m_FollowStage = 0;
                m_FollowSince = now;
                m_FollowBest = float.MaxValue;
                return;
            }
            var corner = m_PathPoints[m_PathIndex];
            var distance = (corner - position).GetHorizontalMagnitude();
            var sameLeg = m_FollowGeneration == m_PathRequestGeneration && m_FollowIndex == m_PathIndex;
            var progressed = sameLeg && distance < m_FollowBest - 0.5f;
            if (!sameLeg || progressed)
            {
                m_FollowGeneration = m_PathRequestGeneration;
                m_FollowIndex = m_PathIndex;
                m_FollowBest = distance;
                // A new route asked from the same spot is not progress: the
                // stall clock keeps running until the body has moved 0.5m.
                if (progressed || (position - m_FollowAnchor).GetHorizontalMagnitude() >= 0.5f)
                {
                    m_FollowAnchor = position;
                    m_FollowSince = now;
                    m_FollowStage = 0;
                }
                return;
            }
            // As SAIN does (BotPathData.CheckStuck), quicker than before:
            // half a second without progress and something 1m ahead at chest
            // height, route again; a jump at 1s; route again at 2s; then the
            // side step (3.5s) and the cut out of the mesh (5s).
            // 0.2.2t: in tryhard the same steps in half the time (2.5s).
            var stalled = (now - m_FollowSince) * (Tryhard ? 2f : 1f);
            if (m_FollowStage == 0 && stalled >= 0.5f)
            {
                m_FollowStage = 1;
                var toCorner = corner - position;
                toCorner.y = 0f;
                if (toCorner.sqrMagnitude > 0.01f
                    && Physics.SphereCast(
                        position + Vector3.up,
                        0.2f,
                        toCorner.normalized,
                        out _,
                        1f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    m_FollowEarlyRepaths++;
                    ClearPath();
                }
            }
            else if (m_FollowStage == 1 && stalled >= 1f)
            {
                m_FollowStage = 2;
                if (m_Player.movement.isGrounded && now >= m_NextNavigationJumpAt)
                {
                    m_NavigationJumpUntil = now + 0.55f;
                    m_NextNavigationJumpAt = now + 1.2f;
                }
            }
            else if (m_FollowStage == 2 && stalled >= 2f)
            {
                m_FollowStage = 3;
                m_FollowEarlyRepaths++;
                ClearPath();
            }
            else if (m_FollowStage == 3 && stalled >= 3.5f)
            {
                m_FollowStage = 4;
                var ahead = corner - position;
                ahead.y = 0f;
                if (ahead.sqrMagnitude > 0.01f)
                {
                    ahead.Normalize();
                    var right = new Vector3(ahead.z, 0f, -ahead.x);
                    m_FollowSide = -m_FollowSide;
                    var side = right * m_FollowSide;
                    if (IsBodyRouteBlocked(position, side, 1.2f))
                    {
                        side = -side;
                    }
                    m_FollowSideTarget = position + side * 1.2f + ahead * 0.5f;
                    m_FollowSideUntil = now + 0.8f;
                }
            }
            else if (m_FollowStage == 4 && stalled >= 5f)
            {
                m_FollowStage = 5;
                BotLog(LogLevel.Information,
                    "Sem avancar {Seconds:0.#}s ate o ponto {Corner} da rota ({Index}/{Count}) em {Position}: pulou, deu um passo para o lado; cortando o trecho e pedindo uma rota nova.",
                    now - m_FollowSince,
                    FormatPosition(corner),
                    m_PathIndex + 1,
                    m_PathPoints.Count,
                    FormatPosition(position));
                if (!TryDropFailedShortcut(position))
                {
                    BlockStuckSpot(position, now);
                }
                ClearPath();
            }
        }

        // Running from zombies or fire the bot must never stop and wait.
        private bool IsEscapeObjective()
        {
            return m_ObjectiveType == ObjectiveType.Flee
                   || m_ObjectiveType == ObjectiveType.EscapeSwarm
                   || m_ObjectiveType == ObjectiveType.EscapeHazard
                   || m_ObjectiveType == ObjectiveType.RepositionFire
                   || m_ObjectiveType == ObjectiveType.Combat;
        }

        // Stuck 20s walking a mesh route: the bake missed whatever is in the
        // way here. Cut a body-sized piece out ahead for 10 min.
        private void BlockStuckSpot(Vector3 position, float now)
        {
            if (!HasMeshRoute())
            {
                return;
            }
            var ahead = m_PathPoints[m_PathIndex] - position;
            ahead.y = 0f;
            if (ahead.magnitude < 0.3f)
            {
                return;
            }
            var legLength = ahead.magnitude;
            ahead.Normalize();
            // What the body really hits on the way to the corner: in the
            // 0.1.115 test 98 of these stops were at one wall of the Medic
            // building (-924, -716), cut 0.7m ahead 1.2m wide each time and
            // routed 1m around the cut into the same wall.
            var bottom = position + Vector3.up * (PlayerStance.RADIUS + 0.45f);
            var top = position + Vector3.up * (PlayerMovement.HEIGHT_STAND - PlayerStance.RADIUS);
            string blocker;
            Vector3 center;
            if (Physics.CapsuleCast(
                    bottom,
                    top,
                    PlayerStance.RADIUS - 0.02f,
                    ahead,
                    out var hit,
                    Mathf.Min(legLength, 3f),
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore))
            {
                blocker = SkaliaBotUnityNavmesh.DescribeMeshRole(hit.collider) + " a " + hit.distance.ToString("0.0") + "m";
                var explained = SkaliaBotUnityNavmesh.ExplainBlocker(hit.collider, position, m_PathPoints[m_PathIndex]);
                if (explained != null)
                {
                    BotLog(LogLevel.Information,
                        "Malha nova: rota atravessando {Blocker}: {Report}.",
                        hit.collider.name,
                        explained);
                }
                center = position + ahead * (hit.distance + 0.5f);
            }
            else
            {
                blocker = "nada no caminho na altura do corpo (degrau ou chao)";
                center = position + ahead * 0.7f;
            }
            // From 1m under the feet: a 0.3m step down to the corner left the
            // old cut above the mesh it was meant to remove.
            center.y = position.y + 0.5f;
            SkaliaBotUnityNavmesh.BlockArea(center, new Vector3(2f, 3f, 1f), DirectionToYaw(ahead), 600f);
            BotLog(LogLevel.Information,
                "Travado numa rota da malha nova em {Position} rumo a {Corner}: {Blocker}; {Standing}; trecho em {Block} cortado da malha por 10 min ({Count} cortes ativos).",
                FormatPosition(position),
                FormatPosition(m_PathPoints[m_PathIndex]),
                blocker,
                SkaliaBotUnityNavmesh.DescribeStanding(position),
                FormatPosition(center),
                SkaliaBotUnityNavmesh.BlockCount);
        }

        // An opened wardrobe or fridge swings its door into the room, where
        // the mesh (baked with it closed) still has floor: cut the object and
        // half a meter around it out of the mesh while it stays open.
        private static void BlockOpenedFurniture(BotDoor door)
        {
            if (door.Transform == null || SkaliaBotUnityNavmesh.IsRealDoor(door.State))
            {
                return;
            }
            var colliders = door.Transform.GetComponentsInChildren<Collider>();
            var any = false;
            var bounds = new Bounds(door.Center, Vector3.zero);
            foreach (var collider in colliders)
            {
                if (collider == null || collider.isTrigger)
                {
                    continue;
                }
                if (!any)
                {
                    bounds = collider.bounds;
                    any = true;
                }
                else
                {
                    bounds.Encapsulate(collider.bounds);
                }
            }
            if (!any)
            {
                return;
            }
            // Counters (73 opened in the 0.1.103 log) line every kitchen: cut
            // out with a meter of margin they closed the aisle. Only tall
            // furniture, the wardrobe kind, and a narrower margin.
            if (bounds.size.y < 1.4f)
            {
                return;
            }
            // 0.1.169: a shipping container is walked into; cut out, the
            // loot inside could not be reached once it was opened.
            if (Mathf.Min(bounds.size.x, bounds.size.z) > 1.5f)
            {
                return;
            }
            var size = bounds.size + new Vector3(0.6f, 0f, 0.6f);
            size.y = Mathf.Max(size.y, 1.8f);
            SkaliaBotUnityNavmesh.BlockArea(bounds.center, size, 0f, 600f);
        }

        private bool HasMeshRoute()
        {
            return m_PathFromUnity
                   && !m_PathPending
                   && !m_PathFailed
                   && m_PathIndex < m_PathPoints.Count;
        }

        // Safety net for any other source: 5 routes in 6s without leaving
        // 3m means something keeps throwing the route away. Follow the next
        // route as it is for 6s, with no shortcut, detour or overshoot reset.
        private const int RouteChurnRequests = 5;
        private const float RouteChurnSeconds = 6f;
        private const float RouteCommitSeconds = 6f;
        private readonly float[] m_RouteRequestTimes = new float[RouteChurnRequests];
        private readonly Vector3[] m_RouteRequestPositions = new Vector3[RouteChurnRequests];
        private int m_RouteRequestCursor;
        private float m_RouteCommitUntil;

        private void NoteRouteRequest(Vector3 position, float now)
        {
            var oldest = m_RouteRequestCursor;
            var oldestTime = m_RouteRequestTimes[oldest];
            var oldestPosition = m_RouteRequestPositions[oldest];
            m_RouteRequestTimes[oldest] = now;
            m_RouteRequestPositions[oldest] = position;
            m_RouteRequestCursor = (oldest + 1) % RouteChurnRequests;
            if (now < m_RouteCommitUntil
                || IsEscapeObjective()
                || oldestTime <= 0f
                || now - oldestTime > RouteChurnSeconds
                || (position - oldestPosition).GetHorizontalMagnitude() > 3f)
            {
                return;
            }
            m_RouteCommitUntil = now + RouteCommitSeconds;
            BotLog(LogLevel.Information,
                "{Count} rotas novas em {Seconds:0.0}s sem sair de 3m em {Position} (objetivo {Objective}, alvo atual: {Source}); seguindo so a rota por {Commit:0}s.",
                RouteChurnRequests,
                now - oldestTime,
                FormatPosition(position),
                m_ObjectiveType,
                DescribeNavigationTargetSource(m_OrbitLastTarget, now),
                RouteCommitSeconds);
        }

        // 0.2.2x11: who threw the route away, for the circle log.
        private void ClearPath(
            [System.Runtime.CompilerServices.CallerMemberName] string caller = "",
            [System.Runtime.CompilerServices.CallerLineNumber] int line = 0)
        {
            var key = caller + ":" + line;
            m_OrbitClearSources.TryGetValue(key, out var cleared);
            m_OrbitClearSources[key] = cleared + 1;
            m_HasNavmeshReturnPoint = false;
            m_PathRequestGeneration++;
            m_PathPending = false;
            m_PathPoints.Clear();
            m_PathIndex = 0;
            m_PlannedDestination = Vector3.zero;
            m_NextPathRequestTime = 0f;
            m_PathRequestedAt = 0f;
            m_DirectFallbackUntil = 0f;
            m_ObstacleDetectedAt = 0f;
        }

        private void RecoverTimedOutPath(float now)
        {
            if (!m_PathPending || now - m_PathRequestedAt < 3f)
            {
                return;
            }

            m_PathRequestGeneration++;
            m_PathPending = false;
            m_PathPoints.Clear();
            m_PathIndex = 0;
            m_DirectFallbackUntil = now + 6f;
            BotLog(LogLevel.Debug,
                "Rota do bot excedeu 3s no estado {State}; usando deslocamento direto temporario para {Destination}.",
                m_ObjectiveType,
                FormatPosition(m_ObjectivePosition));
        }

        private int GetActivityCategory()
        {
            if (m_LocalRecoveryPhase != LocalRecoveryPhase.None)
            {
                return 5;
            }
            switch (m_ObjectiveType)
            {
                case ObjectiveType.Travel:
                case ObjectiveType.Explore:
                    return 0;
                case ObjectiveType.Patrol:
                    return 1;
                case ObjectiveType.Loot:
                    return 2;
                case ObjectiveType.Combat:
                case ObjectiveType.RepositionFire:
                    return 3;
                case ObjectiveType.Flee:
                case ObjectiveType.EscapeSwarm:
                case ObjectiveType.EscapeHazard:
                    return 4;
                case ObjectiveType.Unstuck:
                case ObjectiveType.ExitWater:
                    return 5;
                default:
                    return m_TravelActive ? 0 : 6;
            }
        }

        private void UpdateActivityStats(float now)
        {
            if (m_ActivityWindowStart < 0f)
            {
                m_ActivityWindowStart = now;
            }
            if (m_ActivityLastAt >= 0f && now - m_ActivityLastAt <= 5f)
            {
                m_ActivitySeconds[GetActivityCategory()] += now - m_ActivityLastAt;
            }
            m_ActivityLastAt = now;
            if (now - m_ActivityWindowStart < 300f)
            {
                return;
            }
            var total = 0f;
            foreach (var seconds in m_ActivitySeconds)
            {
                total += seconds;
            }
            var parts = new System.Text.StringBuilder();
            for (var i = 0; i < m_ActivitySeconds.Length; i++)
            {
                if (total <= 1f || m_ActivitySeconds[i] < 0.5f)
                {
                    continue;
                }
                if (parts.Length > 0)
                {
                    parts.Append(", ");
                }
                parts.Append(s_ActivityNames[i])
                    .Append(' ')
                    .Append(Mathf.RoundToInt(100f * m_ActivitySeconds[i] / total))
                    .Append('%');
            }
            BotLog(LogLevel.Information,
                "Resumo de {Minutes:0} min: {Activities}; areas terminadas {Areas}, pontos de loot pulados sem acesso {GivenUp}, itens coletados {Loots}; "
                + "lutas {Fights} ({FarFights} comecadas a 20m ou mais), zumbis deixados em paz {Skipped}; "
                + "tiros {Shots} (acertaram zumbi {ShotHits}, na cabeca {Headshots}); "
                + "golpes {Swings} (acertaram {SwingHits}, na cabeca {SwingHeads}); "
                + "pulos de atalho {Hops} (nao chegaram {HopsFailed}); "
                + "areas olhadas de cima {Overlooks} (puladas por estarem cheias {OverlookSkips}), zumbis deixados para tras no caminho {LeftBehind}, "
                + "atalhos da malha usados {Shortcuts} (removidos por falha {ShortcutsFailed}); "
                + "risco alto {RiskPercent}% do tempo (entrou {RiskOn}x), zumbis distraidos deixados pela cautela {StealthBlocked}, "
                + "saidas de onde bot morreu {Evictions}, loot atras de movel desistido {LootBehind}; "
                + "travamentos: recuperacoes {Recoveries}, circulos {Circles}, combate sem direcao {NoDirection} (recuou pelo caminho {Backtracks}).",
                (now - m_ActivityWindowStart) / 60f,
                parts.Length > 0 ? parts.ToString() : "nada",
                m_StatWindowAreas,
                m_StatWindowPointsGivenUp,
                m_StatWindowLoots,
                m_StatWindowFights,
                m_StatWindowFarFights,
                m_StatSkippedZombies.Count,
                m_StatWindowShots,
                m_StatWindowShotHits,
                m_StatWindowHeadshots,
                m_StatWindowSwings,
                m_StatWindowSwingHits,
                m_StatWindowSwingHeads,
                m_StatWindowRouteHops,
                m_StatWindowRouteHopsFailed,
                m_StatWindowOverlooks,
                m_StatWindowOverlookSkips,
                m_StatWindowLeftBehind,
                m_StatWindowShortcutsTaken,
                m_StatWindowShortcutsFailed,
                GetRiskPercent(now),
                m_StatWindowRiskOn,
                m_StatStealthBlocked.Count,
                m_StatWindowEvictions,
                m_StatWindowLootBehindFurniture,
                m_StatWindowRecoveries,
                m_StatWindowCircles,
                m_StatWindowNoDirection,
                m_StatWindowBacktracks);
            for (var i = 0; i < m_ActivitySeconds.Length; i++)
            {
                m_ActivitySeconds[i] = 0f;
            }
            m_ActivityWindowStart = now;
            m_StatWindowRecoveries = 0;
            m_StatWindowCircles = 0;
            m_StatWindowNoDirection = 0;
            m_StatWindowBacktracks = 0;
            m_StatWindowFights = 0;
            m_StatWindowFarFights = 0;
            m_StatWindowLoots = 0;
            m_StatWindowAreas = 0;
            m_StatWindowPointsGivenUp = 0;
            m_StatWindowShots = 0;
            m_StatWindowShotHits = 0;
            m_StatWindowHeadshots = 0;
            m_StatWindowSwings = 0;
            m_StatWindowSwingHits = 0;
            m_StatWindowSwingHeads = 0;
            m_StatWindowRouteHops = 0;
            m_StatWindowRouteHopsFailed = 0;
            m_StatWindowOverlooks = 0;
            m_StatWindowOverlookSkips = 0;
            m_StatWindowLeftBehind = 0;
            m_StatWindowShortcutsTaken = 0;
            m_StatWindowShortcutsFailed = 0;
            ResetRiskStats();
            m_StatSkippedZombies.Clear();
        }

        private void LogPeriodicStatus(Vector3 position, float now)
