            m_NextStatusLogTime = now + 30f;
            var life = m_Player.life;
            var targetDistance = IsTargetZombieAlive()
                ? (m_TargetZombie!.transform.position - position).GetHorizontalMagnitude()
                : -1f;
            var attacks = m_PublishedAttackCount - m_StatAttacksAtLastStatus;
            m_StatAttacksAtLastStatus = m_PublishedAttackCount;
