                + "arma {Weapon}; inventario {Inventory}; zumbis percebidos {Perceived}, a 4m {Surrounded}, a 12m {Nearby}, mais proximo {Nearest:0.#}m, "
                + "alvo {Target:0.#}m, inalcancaveis {Unreachable}; rota {PathIndex}/{PathCount} pendente {PathPending}; "
                + "andando {Walking} correndo {Sprinting} agua {InWater}.",
                m_ObjectiveType,
                now - m_ObjectiveTypeSince,
                m_InterestAreaName,
                FormatPosition(position),
                FormatPosition(m_ObjectivePosition),
                m_ObjectiveType == ObjectiveType.None
                    ? 0f
                    : (m_ObjectivePosition - position).GetHorizontalMagnitude(),
                life.health,
                life.food,
                life.water,
                life.isBleeding,
                life.isBroken,
                DescribeEquipped(),
                DescribeInventory(),
                m_PerceivedZombies.Count,
                m_CachedSurroundedZombieCount,
                m_CachedNearbyZombieCount,
                float.IsInfinity(m_CachedNearestZombieDistance) ? -1f : m_CachedNearestZombieDistance,
                targetDistance,
                m_UnreachableZombies.Count,
                Mathf.Min(m_PathIndex + 1, m_PathPoints.Count),
