            m_StatLoots = 0;
            m_StatLootRejects = 0;
            m_StatDamageHits = 0;
            m_StatDamageTaken = 0;
            m_StatPathFailures = 0;
            m_StatRecoveries = 0;
            m_StatObjectiveChanges = 0;
        }

        private Vector3 CalculatePlayerAvoidance(Vector3 botPosition)
        {
            var result = Vector3.zero;
            var radiusSquared = m_AvoidPlayersWithinMeters * m_AvoidPlayersWithinMeters;
            var nearestDistanceSquared = float.PositiveInfinity;
            foreach (var candidate in Provider.clients)
            {
                if (candidate == null
                    || candidate == m_Player.channel.owner
                    || candidate.player == null
                    || candidate.player.life == null
                    || candidate.player.life.isDead
                    || candidate.transportConnection is SkaliaBotTransportConnection)
                {
                    continue;
                }

                var away = botPosition - candidate.player.transform.position;
                away.y = 0f;
                var distanceSquared = away.sqrMagnitude;
                if (distanceSquared < 0.01f || distanceSquared > radiusSquared)
                {
                    continue;
                }

                var distance = Mathf.Sqrt(distanceSquared);
                var weight = 1f - distance / m_AvoidPlayersWithinMeters;
                result += away / distance * (0.25f + weight);
                if (distanceSquared < nearestDistanceSquared)
                {
                    nearestDistanceSquared = distanceSquared;
                    m_FleeingFromPlayerName = candidate.playerID.characterName;
                }
            }

            return result.normalized;
        }

        // Furniture the route runs through: 7 of the 23 circles of the last
        // log had the bot pressed against a bed, a counter or a table. The
        // navmesh passes under them, so the bot walks to the nearest corner
        // of the piece, seen from the catalog, and goes on from there.
        private const float FurnitureMargin = 0.5f;
        private const float FurnitureLookAheadMeters = 4f;
        private static readonly List<BotMapObject> s_FurnitureQuery = new List<BotMapObject>();
        private static readonly Vector3[] s_FurnitureCorners = new Vector3[4];
        private bool m_FurnitureDetourActive;
        private Vector3 m_FurnitureDetourTarget;
        private float m_FurnitureDetourEndsAt;
        private float m_NextFurnitureCheckAt;
        private float m_NextFurnitureLogAt;

        private Vector3 ApplyFurnitureDetour(Vector3 position, Vector3 navigationTarget, float now)
        {
            if (!SkaliaBotObjectMap.Ready)
            {
                return navigationTarget;
            }
            // The mesh is baked around furniture: on a mesh route the detour
            // only aimed at a "corner" 0.3m away. Fleeing past a dumpster in
            // the 0.1.103 log the bot stood there until the zombies killed it.
            if (HasMeshRoute()
                && (navigationTarget - m_PathPoints[m_PathIndex]).GetHorizontalMagnitude() < 0.1f)
            {
                m_FurnitureDetourActive = false;
                return navigationTarget;
            }
            if (m_FurnitureDetourActive)
            {
                var offset = m_FurnitureDetourTarget - position;
                offset.y = 0f;
                if (offset.magnitude > 0.5f && now < m_FurnitureDetourEndsAt)
                {
                    return m_FurnitureDetourTarget;
                }
                m_FurnitureDetourActive = false;
                m_NextFurnitureCheckAt = 0f;
            }
            if (now < m_NextFurnitureCheckAt || IsDetourSuppressed(position, now))
            {
                return navigationTarget;
            }
            m_NextFurnitureCheckAt = now + 0.2f;
            var route = navigationTarget - position;
            route.y = 0f;
            var routeDistance = route.magnitude;
            if (routeDistance < 0.3f)
            {
                return navigationTarget;
            }
            var lookAhead = Mathf.Min(routeDistance, FurnitureLookAheadMeters);
            var end = position + route / routeDistance * lookAhead;
            SkaliaBotObjectMap.Query(position, lookAhead + 1f, s_FurnitureQuery);
            BotMapObject? blocker = null;
            var blockerDistance = float.PositiveInfinity;
            foreach (var mapObject in s_FurnitureQuery)
            {
                if (!SkaliaBotObjectMap.DetourAround(mapObject)
                    || !SkaliaBotObjectMap.OverlapsBodyHeight(mapObject, position.y)
                    // 0.2.2x1 (doc 16.3, item 11): a fence the bot can hop
                    // is hopped (TryContactJump), not walked round.
                    || IsHoppableFence(mapObject, position.y)
                    // Loot sits on counters and shelves: the bot must get there.
                    || SkaliaBotObjectMap.FootprintDistance(mapObject, navigationTarget) <= FurnitureMargin
                    || SkaliaBotObjectMap.FootprintDistance(mapObject, m_ObjectivePosition) <= FurnitureMargin + 0.5f
                    || SkaliaBotObjectMap.FootprintDistance(mapObject, position) <= 0.05f
                    || !SkaliaBotObjectMap.SegmentHitsFootprint(mapObject, position, end, FurnitureMargin))
                {
                    continue;
                }
                var distance = SkaliaBotObjectMap.FootprintDistance(mapObject, position);
                if (distance < blockerDistance)
                {
                    blockerDistance = distance;
                    blocker = mapObject;
                }
            }
            if (blocker == null)
            {
                return navigationTarget;
            }
            var corners = s_FurnitureCorners;
            SkaliaBotObjectMap.GetFootprintCorners(blocker, FurnitureMargin + 0.15f, position.y, corners);
            var bestCost = float.PositiveInfinity;
            var bestCorner = Vector3.zero;
            foreach (var corner in corners)
            {
                var leg = corner - position;
                leg.y = 0f;
                var legLength = leg.magnitude;
                if (legLength < 0.3f || !IsFurnitureLegClear(position, corner))
                {
                    continue;
                }
                if (IsBodyRouteBlocked(position, leg / legLength, Mathf.Min(1.5f, legLength)))
                {
                    continue;
                }
                var cost = legLength + (navigationTarget - corner).GetHorizontalMagnitude();
                if (cost < bestCost)
                {
                    bestCost = cost;
                    bestCorner = corner;
                }
            }
            if (float.IsPositiveInfinity(bestCost) || IsDetourPingPong(blocker, bestCorner, position, now))
            {
                return navigationTarget;
            }
            m_FurnitureDetourActive = true;
            SkaliaBotUnityNavmesh.CountDetour(m_PathFromUnity);
            m_FurnitureDetourTarget = bestCorner;
            m_FurnitureDetourEndsAt = now + 2.5f;
            if (now >= m_NextFurnitureLogAt)
            {
                m_NextFurnitureLogAt = now + 10f;
                BotLog(LogLevel.Information,
                    "{Name} no caminho em {Position}; contornando pela quina {Corner} em vez de empurrar contra.",
                    blocker.Name,
                    FormatPosition(position),
                    FormatPosition(bestCorner));
            }
            return bestCorner;
        }

        // The leg to a corner must not cut through this or another piece.
        private static bool IsFurnitureLegClear(Vector3 from, Vector3 to)
        {
            foreach (var mapObject in s_FurnitureQuery)
            {
                if (SkaliaBotObjectMap.DetourAround(mapObject)
                    && SkaliaBotObjectMap.OverlapsBodyHeight(mapObject, from.y)
                    && SkaliaBotObjectMap.FootprintDistance(mapObject, from) > 0.05f
                    && SkaliaBotObjectMap.SegmentHitsFootprint(mapObject, from, to, 0.3f))
                {
                    return false;
                }
            }
            return true;
        }

        // A circle with the bot pressed against furniture: step 1.3m away
        // from it, after the pause to think, then route again.
        private bool TryStepAwayFromFurniture(Vector3 position, float now)
        {
            if (!SkaliaBotObjectMap.Ready)
            {
                return false;
            }
            SkaliaBotObjectMap.Query(position, 1.5f, s_FurnitureQuery);
            BotMapObject? nearest = null;
            var nearestDistance = 0.6f;
            foreach (var mapObject in s_FurnitureQuery)
            {
                if (!SkaliaBotObjectMap.DetourAround(mapObject)
                    || !SkaliaBotObjectMap.OverlapsBodyHeight(mapObject, position.y))
                {
                    continue;
                }
                var distance = SkaliaBotObjectMap.FootprintDistance(mapObject, position);
                if (distance <= nearestDistance)
                {
                    nearestDistance = distance;
                    nearest = mapObject;
                }
            }
            if (nearest == null)
            {
                return false;
            }
            const float stepMeters = 1.3f;
            var away = SkaliaBotObjectMap.AwayDirection(nearest, position);
            foreach (var angle in s_StepAwayAngles)
            {
                var direction = Quaternion.Euler(0f, angle, 0f) * away;
                var target = position + direction * stepMeters;
                if (IsBodyRouteBlocked(position, direction, stepMeters))
                {
                    continue;
                }
                var landsClear = true;
                foreach (var mapObject in s_FurnitureQuery)
                {
                    if (SkaliaBotObjectMap.DetourAround(mapObject)
                        && SkaliaBotObjectMap.OverlapsBodyHeight(mapObject, position.y)
                        && SkaliaBotObjectMap.FootprintDistance(mapObject, target) < 0.35f)
                    {
                        landsClear = false;
                        break;
                    }
                }
                if (!landsClear)
                {
                    continue;
                }
                m_FurnitureDetourActive = true;
                SkaliaBotUnityNavmesh.CountDetour(m_PathFromUnity);
                m_FurnitureDetourTarget = target;
                m_FurnitureDetourEndsAt = Mathf.Max(now, m_ThinkUntil) + 2f;
                m_WallAvoidanceActive = false;
                BotLog(LogLevel.Information,
                    "Encostado em {Name} em {Position}; afastando {Step:0.#}m antes de tentar de novo.",
                    nearest.Name,
                    FormatPosition(position),
                    stepMeters);
                return true;
            }
            return false;
        }

        private static readonly float[] s_StepAwayAngles = { 0f, 40f, -40f, 80f, -80f };

        private Vector3 ApplyWallAvoidance(
            Vector3 position,
            Vector3 navigationTarget,
            Vector3 finalObjective,
            float now)
        {
            m_WallMovementBlocked = false;
            if (m_WallAvoidanceActive)
            {
                var detourOffset = m_WallAvoidanceTarget - position;
                detourOffset.y = 0f;
                if (detourOffset.magnitude <= 1.1f || now >= m_WallAvoidanceEndsAt)
                {
                    m_WallAvoidanceActive = false;
                    ClearPath();
                }
                else if (IsBodyRouteBlocked(
                             position,
                             detourOffset.normalized,
                             Mathf.Min(1.5f, detourOffset.magnitude)))
                {
                    m_WallAvoidanceActive = false;
                    m_PreferredWallAvoidanceSide *= -1;
                    m_WallSideLockedUntil = now + WallSideLockSeconds;
                    m_WallSideLockAnchor = position;
                    m_NextWallAvoidanceAttemptAt = 0f;
                }
                else
                {
                    var detourYaw = DirectionToYaw(detourOffset);
                    m_WallMovementBlocked = Mathf.Abs(
                        Mathf.DeltaAngle(m_CurrentYaw, detourYaw)) > 25f;
                    return m_WallAvoidanceTarget;
                }
            }

            var route = navigationTarget - position;
            route.y = 0f;
            var routeDistance = route.magnitude;
            if (routeDistance <= 0.25f)
            {
                return navigationTarget;
            }

            // The 0.1.97 circles: the next corner of a mesh route is already
            // a body width from every wall, but the center rays still clipped
            // door frames and corners, so the bot detoured, threw the route
            // away and got the same corner back, 5 to 20 routes in 8s. While
            // the mesh says the line is floor, walk it; a real block is left
            // to the stuck check.
            if (m_ObjectiveType != ObjectiveType.EscapeSwarm
                && HasMeshRoute()
                && (navigationTarget - m_PathPoints[m_PathIndex]).GetHorizontalMagnitude() < 0.1f
                && (IsMeshFollowing()
                    || SkaliaBotUnityNavmesh.IsStraight(position, navigationTarget)
                    || (now < m_RouteCommitUntil
                        && !IsLedgeAhead(position, route / routeDistance, navigationTarget))))
            {
                return navigationTarget;
            }

            var direction = route / routeDistance;
            var predictiveDistance = m_ObjectiveType == ObjectiveType.EscapeSwarm
                ? 5.5f
                : 1.6f;
            var checkDistance = Mathf.Min(predictiveDistance, routeDistance);
            var ledgeAhead = IsLedgeAhead(position, direction, navigationTarget);
            if (ledgeAhead && now >= m_NextLedgeLogAt)
            {
                m_NextLedgeLogAt = now + 5f;
                BotLog(LogLevel.Information,
                    "Beirada com queda de mais de {Drop:0.#}m a frente em {Position} (objetivo {Objective}); desviando em vez de cair.",
                    LedgeDropMeters,
                    FormatPosition(position),
                    m_ObjectiveType);
            }
            if (!ledgeAhead
                && (ShouldJumpTraversableObstacle(position, direction)
                    || (!IsBodyRouteBlocked(position, direction, checkDistance)
                        && (m_ObjectiveType != ObjectiveType.EscapeSwarm
                            || !IsEscapeTerrainUnsafe(position, direction, checkDistance)))))
            {
                return navigationTarget;
            }

            // Nunca continue aplicando input frontal contra a parede. Primeiro
            // pare, gire para a lateral escolhida e apenas então volte a andar.
            m_WallMovementBlocked = true;
            if (now < m_NextWallAvoidanceAttemptAt || now < m_RouteCommitUntil)
            {
                return position;
            }
            m_NextWallAvoidanceAttemptAt = now + 0.5f;

            if (TryChooseWallDetour(position, direction, finalObjective, now, out var detour))
            {
                m_WallAvoidanceActive = true;
                SkaliaBotUnityNavmesh.CountDetour(m_PathFromUnity);
                m_WallAvoidanceTarget = detour;
                m_WallAvoidanceEndsAt = now + 3f;
                ClearPath();
                BotLog(LogLevel.Debug,
                    "Parede bloqueando objetivo {Objective}; bot contornando pela lateral ate {Detour}.",
                    FormatPosition(finalObjective),
                    FormatPosition(detour));
                return detour;
            }

            if (now >= m_NextObstacleReplanTime)
            {
                m_NextObstacleReplanTime = now + 1f;
                ClearPath();
                BotLog(LogLevel.Debug,
                    "Parede sem desvio local seguro em {Position}; bot parado enquanto recalcula a rota.",
                    FormatPosition(position));
            }
            return position;
        }

        private const float LedgeDropMeters = 1.5f;
        private float m_NextLedgeLogAt;

        // The bot walked into the pit next to the train cars chasing a zombie
        // 2.6m below and could only leave by teleport. Ground more than 1.5m
        // below one stride ahead (more further out, for stairs) is a wall, except where falling
        // is the plan (unstuck manoeuvre, water exit, a terrain crossing).
        // Routes step off porches and platform edges 1.5-2m high on purpose:
        // blocking those stalled the bots 34 times, so a drop up to 2.5m is
        // allowed when the route itself goes down there.
        private const float LedgeHardDropMeters = 2.5f;
        private const float TerrainLegDropMeters = 4f;
        private const float UnstuckDropMeters = 5f;
        // Two bots stood a minute on Camp Oleksandr's patio umbrellas (3.2m
        // above the ground) with every way down refused as a ledge. Held at
        // the same spot for 4s, the guard lets a drop of up to 4.5m through.
        // x16: llo stood 3min20s on a ledge at Olympia (00:14, x15 test)
        // with the mesh 3.6m away across a 4.9m drop. The players drop 4-6m
        // freely (73 drops in the recordings, 1 with health lost) and the
        // game hurts a fall only past 22 m/s, about 8m (PlayerLife.onLanded,
        // gravity x3). Held 4s, the guard now lets 6m through.
        private const float LedgeStrandedDropMeters = 6f;
        private const float LedgeStrandedSeconds = 4f;
        private Vector3 m_LedgeBlockAnchor;
        private float m_LedgeBlockSince = float.NegativeInfinity;
        private float m_LedgeLastBlockAt = float.NegativeInfinity;

        private bool IsStrandedByLedge(Vector3 position)
        {
            var now = Time.realtimeSinceStartup;
            if (now - m_LedgeLastBlockAt > 1.5f
                || (position - m_LedgeBlockAnchor).GetHorizontalMagnitude() > 4f)
            {
                m_LedgeBlockAnchor = position;
                m_LedgeBlockSince = now;
            }
            m_LedgeLastBlockAt = now;
            return now - m_LedgeBlockSince >= LedgeStrandedSeconds;
        }

        private bool IsLedgeAhead(Vector3 position, Vector3 direction, Vector3 navigationTarget)
        {
            var routeGoesDown = navigationTarget.y < position.y - 0.8f;
            // Crossing the bridge south of Novosibirsk two bots stepped off
            // the deck and fell 18m into the river, legs broken. On a terrain
            // leg a drop is allowed up to the 4m a terrain step allows.
            var terrainLeg = m_ObjectiveType == ObjectiveType.Travel && m_TravelActive && m_TravelPhase == 2;
            // The unstuck manoeuvre may fall, but not off a bridge abutment
            // into the river 13m down (a broken leg every time).
            var unstuck = m_ObjectiveType == ObjectiveType.Unstuck;
            if (m_ObjectiveType == ObjectiveType.ExitWater
                || m_Player.stance.stance == EPlayerStance.SWIM
                || !m_Player.movement.isGrounded)
            {
                return false;
            }
            for (var distance = 0.9f; distance <= 1.6f; distance += 0.7f)
            {
                var probe = position + direction * distance + Vector3.up * 1.5f;
                if (Physics.Raycast(
                        probe,
                        Vector3.down,
                        out var hit,
                        8f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    if (hit.point.y > position.y + 1.2f)
                    {
                        return false;
                    }
                    var allowedDrop = unstuck
                        ? UnstuckDropMeters
                        : terrainLeg
                        ? TerrainLegDropMeters
                        : routeGoesDown
                        ? LedgeHardDropMeters
                        : Mathf.Max(LedgeDropMeters, distance + 0.6f);
                    if (hit.point.y >= position.y - allowedDrop)
                    {
                        continue;
                    }
                    if (hit.point.y >= position.y - LedgeStrandedDropMeters
                        && IsStrandedByLedge(position))
                    {
                        continue;
                    }
                }
                return !WaterUtility.isPointUnderwater(probe + Vector3.down * 3f);
            }
            return false;
        }

        private bool TryChooseWallDetour(
            Vector3 position,
            Vector3 blockedDirection,
            Vector3 finalObjective,
            float now,
            out Vector3 detour)
        {
            detour = Vector3.zero;
            var bestScore = float.PositiveInfinity;
            var preferredSide = m_PreferredWallAvoidanceSide;
            var chosenSide = preferredSide;
            var sideLocked = now < m_WallSideLockedUntil
                && (position - m_WallSideLockAnchor).GetHorizontalMagnitude() <= WallSideLockMeters;
            for (var sideIndex = 0; sideIndex < 2; sideIndex++)
            {
                // The other side only when the locked one has no way at all.
                if (sideIndex == 1 && sideLocked && bestScore < float.PositiveInfinity)
                {
                    break;
                }
                var side = sideIndex == 0
                    ? preferredSide
                    : -preferredSide;
                foreach (var angle in new[] { 70f, 90f, 110f })
                {
                    var direction = Quaternion.Euler(0f, angle * side, 0f)
                        * blockedDirection;
                    if (IsBodyRouteBlocked(position, direction, 2.6f)
                        || IsLedgeAhead(position, direction, position))
                    {
                        continue;
                    }

                    var desired = position + direction * 3f;
                    if (!TryGetWalkableGround(desired, out var grounded)
                        || Mathf.Abs(grounded.y - position.y) > 1.25f
                        || WaterUtility.isPointUnderwater(grounded + Vector3.up * 0.5f)
                        || IsHazardousPosition(grounded, now, 1.5f))
                    {
                        continue;
                    }

                    var score = (grounded - finalObjective).GetHorizontalMagnitude()
                        + (side == preferredSide ? 0f : 0.75f);
                    if (score < bestScore)
                    {
                        bestScore = score;
                        detour = grounded;
                        chosenSide = side;
                    }
                }
            }
            if (bestScore < float.PositiveInfinity)
            {
                if (!sideLocked || chosenSide != m_PreferredWallAvoidanceSide)
                {
                    m_WallSideLockAnchor = position;
                }
                m_WallSideLockedUntil = now + WallSideLockSeconds;
                m_PreferredWallAvoidanceSide = chosenSide;
            }
            return bestScore < float.PositiveInfinity;
        }

        private void RefreshInteriorExitKnowledge(Vector3 position, float now)
        {
            if (now < m_NextInteriorExitScanAt)
            {
                if (m_HasKnownInteriorExit && now >= m_KnownInteriorExitExpiresAt)
                {
                    m_HasKnownInteriorExit = false;
                }
                return;
            }
            m_NextInteriorExitScanAt = now + 0.75f;

            const int directionCount = 16;
            const float enclosureProbeDistance = 5f;
            var blockedDirections = 0;
            var bestExit = Vector3.zero;
            var bestScore = float.NegativeInfinity;
            var bestIsWindow = false;
            for (var index = 0; index < directionCount; index++)
            {
                var direction = Quaternion.Euler(0f, index * 360f / directionCount, 0f)
                    * Vector3.forward;
                var chestBlocked = Physics.Raycast(
                    position + Vector3.up * 1.1f,
                    direction,
                    enclosureProbeDistance,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore);
                if (chestBlocked)
                {
                    blockedDirections++;
                }

                Vector3 candidate;
                var isWindow = TryFindTraversableOpening(
                    position,
                    direction,
                    7f,
                    out var openingDistance);
                if (isWindow)
                {
                    candidate = position + direction * (openingDistance + 1.7f);
                }
                else
                {
                    // A doorway is an unobstructed body-width corridor. Ground
                    // validation on the far side prevents mistaking a cliff or
                    // empty window opening for a door.
                    if (chestBlocked
                        || IsBodyRouteBlocked(position, direction, 4f)
                        || !TryGetWalkableGround(position + direction * 4f, out candidate))
                    {
                        continue;
                    }
                }

                if (WaterUtility.isPointUnderwater(candidate + Vector3.up * 0.5f)
                    || IsHazardousPosition(candidate, now, 1.5f))
                {
                    continue;
                }
                var threatClearance = GetNearestPerceivedZombieDistance(candidate);
                var objectiveProgress = m_ObjectiveType == ObjectiveType.None
                    ? 0f
                    : (position - m_ObjectivePosition).GetHorizontalMagnitude()
                      - (candidate - m_ObjectivePosition).GetHorizontalMagnitude();
                var score = threatClearance * 2f + objectiveProgress;
                if (score <= bestScore)
                {
                    continue;
                }
                bestScore = score;
                bestExit = candidate;
                bestIsWindow = isWindow;
            }

            // Outdoors usually has only a few blocked directions. Requiring at
            // least half of the radial probes to hit nearby walls limits this
            // memory to houses, tents and similarly enclosed structures.
            if (blockedDirections < directionCount / 2
                || bestScore == float.NegativeInfinity)
            {
                m_HasKnownInteriorExit = false;
                return;
            }

            var changed = !m_HasKnownInteriorExit
                || (bestExit - m_KnownInteriorExit).GetHorizontalMagnitude() > 1.5f;
            m_HasKnownInteriorExit = true;
            m_KnownInteriorExit = bestExit;
            m_KnownInteriorExitExpiresAt = now + 3f;
            if (changed)
            {
                BotLog(LogLevel.Debug,
                    "Bot memorizou {ExitType} como saida do interior em {ExitPosition}.",
                    bestIsWindow ? "janela" : "porta/corredor",
                    FormatPosition(bestExit));
            }
        }

        private static bool TryGetWalkableGround(Vector3 desired, out Vector3 grounded)
        {
            if (Physics.Raycast(
                    desired + Vector3.up * 2.5f,
                    Vector3.down,
                    out var hit,
                    5f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore)
                && hit.normal.y >= 0.45f)
            {
                grounded = hit.point + Vector3.up * 0.05f;
                return true;
            }
            grounded = desired;
            return false;
        }

        private static bool IsEscapeTerrainUnsafe(
            Vector3 position,
            Vector3 direction,
            float distance)
        {
            for (var probeDistance = 2.5f;
                 probeDistance <= distance + 0.1f;
                 probeDistance += 2.5f)
            {
                var probe = position + direction * probeDistance + Vector3.up * 3f;
                if (!Physics.Raycast(
                        probe,
                        Vector3.down,
                        out var hit,
                        7f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore)
                    || hit.normal.y < 0.55f
                    || Mathf.Abs(hit.point.y - position.y) > 2.5f)
                {
                    return true;
                }
            }
            return false;
        }

        private static bool IsBodyRouteBlocked(
            Vector3 position,
            Vector3 direction,
            float checkDistance)
        {
            var distance = Mathf.Max(0.1f, checkDistance - 0.2f);
            var offset = direction * 0.2f;
            return IsWallHit(position + Vector3.up * 0.8f + offset, direction, distance)
                   || IsWallHit(position + Vector3.up * 1.25f + offset, direction, distance);
        }

        // A ramp ahead is ground, not a wall: on the 45 degree scaffold
        // planks of the construction site the 0.8m ray hit the plank itself,
        // so the bot stopped and turned at the foot of every ramp. A surface
        // a player walks on is passed and the ray goes on behind it.
        private const float WalkableSlopeNormalY = 0.6f;

        private static bool IsWallHit(Vector3 origin, Vector3 direction, float distance)
        {
            for (var attempt = 0; attempt < 3; attempt++)
            {
                if (!Physics.Raycast(
                        origin,
                        direction,
                        out var hit,
                        distance,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    return false;
                }
                if (hit.normal.y < WalkableSlopeNormalY)
                {
                    return true;
                }
                var travelled = hit.distance + 0.05f;
                distance -= travelled;
                if (distance <= 0.05f)
                {
                    return false;
                }
                origin += direction * travelled;
            }
            return false;
        }

        // Items rest on shelves, tables and crates: a ray that stops on the
        // surface right under the item still means the bot can reach it.
        // In reach and in sight the bot stops and picks the item up; walking
        // on only took it around the counter the item sits on.
        private bool IsLootInReachAndSight(Vector3 position)
        {
            return (m_ObjectivePosition - position).GetHorizontalMagnitude()
                       <= Mathf.Max(m_LootPickupDistanceMeters, LootSightReachMeters) - 0.3f
                   && Mathf.Abs(m_ObjectivePosition.y - position.y) <= 2f
                   && HasLootLineOfSight(m_ObjectivePosition);
        }

        // 0.1.168: the server hands an item over up to 20m away; at 3m the
        // bot walked around counters and shelves for items it could see.
        private const float LootSightReachMeters = 4f;

        private bool IsLootWithinSightReach(Vector3 lootPoint, Vector3 position)
        {
            return (lootPoint - position).GetHorizontalMagnitude() <= LootSightReachMeters
                && Mathf.Abs(lootPoint.y - position.y) <= 2.2f
                && HasLootLineOfSight(lootPoint);
        }

        private bool HasLootLineOfSight(Vector3 lootPoint)
        {
            var origin = m_Player.look.aim.position;
            var aimPoint = lootPoint + Vector3.up * 0.15f;
            if (!Physics.Linecast(origin, aimPoint, out var hit, RayMasks.BLOCK_COLLISION, QueryTriggerInteraction.Ignore)
                || (hit.point - lootPoint).sqrMagnitude <= 0.75f * 0.75f)
            {
                return true;
            }
            return !Physics.Linecast(
                origin,
                lootPoint + Vector3.up * 0.5f,
                RayMasks.BLOCK_COLLISION,
                QueryTriggerInteraction.Ignore);
        }

        private bool HasClearLineToPoint(Vector3 point)
        {
            return !Physics.Linecast(
                m_Player.look.aim.position,
                point,
                RayMasks.BLOCK_COLLISION,
                QueryTriggerInteraction.Ignore);
        }

        private bool IsPathBlocked(
            Vector3 position,
            Vector3 direction,
            float checkDistance)
        {
            // Start beyond the character controller and probe toward the actual
            // route corner. This avoids detecting the bot itself or an obstacle
            // beside the route while the body is still turning.
            return IsWallHit(
                    position + Vector3.up * 1.2f + direction * 0.65f,
                    direction,
                    Mathf.Max(0.1f, checkDistance - 0.65f));
        }

        // Indoors a stove, a counter or a bed reads as a low fence: the bot
        // dropped its route to hop it straight at loot in the next room,
        // hit the wall behind and circled (most circles of the last logs had
        // that direct target). The hop is only taken when the far side has
        // a clear line to the objective, and after one that gained nothing
        // in 4s hops are off for 20s.
        private float m_ShortcutSuppressedUntil;
        private float m_ShortcutStartedAt = float.NegativeInfinity;
        private float m_ShortcutStartDistance;

        // 0.1.170: the mesh has no edge over a fence or through a window, so
        // a route goes round the yard to the gate or round the house to the
        // door. A player hops. When a route point at most 10m away in a
        // straight line is 6m or more (and 60%) further by the route, and the
        // straight line meets a low fence or a window with floor on the mesh
        // behind it and a clear way from there to the point, the bot skips
        // the corners in between and the jump at the obstacle (the same one
        // as for any window) takes it over. One that does not reach the point
        // in time turns hops and shortcuts off for 20s. Only from outdoors.
        private const float RouteHopMaxStraightMeters = 10f;
        private const float RouteHopMinimumGainMeters = 6f;
        private const int RouteHopLookAhead = 8;
        private int m_RouteHopIndex = -1;
        private int m_RouteHopGeneration = -1;
        private float m_RouteHopUntil;
        private float m_NextRouteHopCheckAt;
        private Vector3 m_RouteHopTarget;
        private int m_StatWindowRouteHops;
        private int m_StatWindowRouteHopsFailed;

        private void UpdateRouteHop(Vector3 position, float now)
        {
            if (!s_Settings.RouteHops)
            {
                m_RouteHopIndex = -1;
                return;
            }
            if (m_RouteHopIndex >= 0)
            {
                if (m_RouteHopGeneration != m_PathRequestGeneration
                    || m_PathIndex > m_RouteHopIndex)
                {
                    m_RouteHopIndex = -1;
                    return;
                }
                if (now < m_RouteHopUntil)
                {
                    return;
                }
                m_RouteHopIndex = -1;
                m_StatWindowRouteHopsFailed++;
                m_ShortcutSuppressedUntil = now + 20f;
                BotLog(LogLevel.Information,
                    "Pulo de atalho para {Point} nao chegou (parado em {Position}); seguindo so a rota por 20s.",
                    FormatPosition(m_RouteHopTarget),
                    FormatPosition(position));
                return;
            }
            if (now < m_NextRouteHopCheckAt
                || now < m_ShortcutSuppressedUntil
                || now < m_RouteCommitUntil
                || m_PathIndex >= m_PathPoints.Count
                || m_StealthCrouch
                || !m_Player.movement.isGrounded
                || m_Player.stance.stance == EPlayerStance.SWIM
                || m_Player.stance.stance == EPlayerStance.CROUCH
                || m_Player.stance.stance == EPlayerStance.PRONE
                || m_ObjectiveType == ObjectiveType.Unstuck
                || m_ObjectiveType == ObjectiveType.ExitWater
                || m_ObjectiveType == ObjectiveType.Ladder
                || m_ObjectiveType == ObjectiveType.None
                || (m_ObjectiveType == ObjectiveType.Combat && !m_CombatByRoute))
            {
                return;
            }
            m_NextRouteHopCheckAt = now + 0.6f;
            if (Physics.Raycast(
                    position + Vector3.up * 1.9f,
                    Vector3.up,
                    20f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore))
            {
                // Under a roof: a counter, a stove or a bed reads as a low
                // fence (the circles of the old direct shortcut).
                return;
            }
            var previous = m_PathPoints[m_PathIndex];
            var routeLength = (previous - position).GetHorizontalMagnitude();
            var last = Mathf.Min(m_PathPoints.Count - 1, m_PathIndex + RouteHopLookAhead);
            for (var index = m_PathIndex + 1; index <= last; index++)
            {
                var point = m_PathPoints[index];
                routeLength += (point - previous).GetHorizontalMagnitude();
                previous = point;
                var straight = point - position;
                var rise = straight.y;
                straight.y = 0f;
                var straightDistance = straight.magnitude;
                if (straightDistance < 3f
                    || straightDistance > RouteHopMaxStraightMeters
                    || Mathf.Abs(rise) > 1.2f
                    || routeLength < straightDistance + RouteHopMinimumGainMeters
                    || routeLength < straightDistance * 1.6f)
                {
                    continue;
                }
                var direction = straight / straightDistance;
                if (!TryFindTraversableOpening(position, direction, Mathf.Min(8f, straightDistance), out var openingDistance)
                    || openingDistance > straightDistance - 1f)
                {
                    continue;
                }
                var landing = position + direction * Mathf.Min(straightDistance, openingDistance + 1.7f);
                if (!SkaliaBotUnityNavmesh.TrySnap(landing, 0.8f, out var snapped)
                    || Mathf.Abs(snapped.y - position.y) > 1.5f
                    || Physics.Linecast(
                        snapped + Vector3.up * 1.1f,
                        point + Vector3.up * 1.1f,
                        RayMasks.BLOCK_COLLISION,
                        QueryTriggerInteraction.Ignore))
                {
                    continue;
                }
                m_RouteHopIndex = index;
                m_RouteHopGeneration = m_PathRequestGeneration;
                m_RouteHopTarget = point;
                m_RouteHopUntil = now + 3f + straightDistance / 3f;
                m_PathIndex = index;
                m_StatWindowRouteHops++;
                BotLog(LogLevel.Information,
                    "Atalho: pulando obstaculo baixo ou janela a {Opening:0.#}m de {Position} em vez de dar a volta ({Straight:0}m reto contra {Route:0}m pela rota; objetivo {Objective}).",
                    openingDistance,
                    FormatPosition(position),
                    straightDistance,
                    routeLength,
                    m_ObjectiveType);
                return;
            }
        }

        private bool IsShortcutWorthIt(Vector3 position, Vector3 direction, float openingDistance, float objectiveDistance, float now)
        {
            if (now - m_ShortcutStartedAt <= 4f)
            {
                if (objectiveDistance < m_ShortcutStartDistance - 1f)
                {
                    return true;
                }
                if (now - m_ShortcutStartedAt >= 3.5f)
                {
                    m_ShortcutSuppressedUntil = now + 20f;
                    m_ShortcutStartedAt = float.NegativeInfinity;
                    BotLog(LogLevel.Information,
                        "Atalho por cima de obstaculo em {Position} nao avancou; seguindo so a rota por 20s.",
                        FormatPosition(position));
                    return false;
                }
                return true;
            }
            var landing = position + direction * Mathf.Min(objectiveDistance, openingDistance + 1.7f);
            var beyond = objectiveDistance - (openingDistance + 1.7f);
            if (beyond > 2.5f
                && Physics.Linecast(
                    landing + Vector3.up * 1.1f,
                    m_ObjectivePosition + Vector3.up * 1.1f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore))
            {
                return false;
            }
            m_ShortcutStartedAt = now;
            m_ShortcutStartDistance = objectiveDistance;
            return true;
        }

        private static bool ShouldJumpTraversableObstacle(
            Vector3 position,
            Vector3 direction)
        {
            return TryFindTraversableOpening(position, direction, 1.8f, out _);
        }

        private static bool TryFindTraversableOpening(
            Vector3 position,
            Vector3 direction,
            float probeDistance,
            out float openingDistance)
        {
            openingDistance = 0f;
            var heights = s_WindowProbeHeights;
            var hits = s_WindowProbeHits;
            var hasHit = s_WindowProbeHasHit;
            var nearestDistance = float.PositiveInfinity;
            var forwardOffset = direction * 0.15f;
            for (var index = 0; index < heights.Length; index++)
            {
                hasHit[index] = Physics.Raycast(
                    position + Vector3.up * heights[index] + forwardOffset,
                    direction,
                    out hits[index],
                    probeDistance,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore);
                if (hasHit[index])
                {
                    nearestDistance = Mathf.Min(nearestDistance, hits[index].distance);
                }
            }

            if (float.IsPositiveInfinity(nearestDistance))
            {
                return false;
            }

            var blockedAtOpening = s_WindowProbeBlockedAtOpening;
            for (var index = 0; index < heights.Length; index++)
            {
                blockedAtOpening[index] = hasHit[index]
                    && hits[index].distance <= nearestDistance + 0.55f;
            }

            var lowerBlocked = blockedAtOpening[0] || blockedAtOpening[1];
            var middleOpening = !blockedAtOpening[2] || !blockedAtOpening[3];
            var upperBlocked = blockedAtOpening[4] || blockedAtOpening[5];
            if (!lowerBlocked)
            {
                return false;
            }

            var lowerHit = blockedAtOpening[1] ? hits[1] : hits[0];
            if (Mathf.Abs(lowerHit.normal.y) > 0.35f)
            {
                return false;
            }
            if (SkaliaBotObjectMap.TryGetByCollider(lowerHit.collider, out var lowerObject)
                && SkaliaBotObjectMap.BlocksBody(lowerObject))
            {
                // A table or a crate is walked around, never hopped onto.
                return false;
            }

            var isLowFenceOrObstacle = !blockedAtOpening[4]
                && !blockedAtOpening[5];
            var isWindow = middleOpening && upperBlocked;
            if (isWindow)
            {
                var upperHit = blockedAtOpening[4] ? hits[4] : hits[5];
                isWindow = Mathf.Abs(upperHit.normal.y) <= 0.35f
                    && Mathf.Abs(lowerHit.distance - upperHit.distance) <= 0.75f;
            }
            if (!isWindow && !isLowFenceOrObstacle)
            {
                return false;
            }

            var landingProbe = position
                + direction * (nearestDistance + 1.5f)
                + Vector3.up * 2.5f;
            if (!Physics.Raycast(
                    landingProbe,
                    Vector3.down,
                    out var landingHit,
                    6f,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore)
                || landingHit.normal.y < 0.4f
                || landingHit.point.y < position.y - 2.5f
                || landingHit.point.y > position.y + 1.5f)
            {
                return false;
            }

            openingDistance = nearestDistance;
            return true;
        }

        private static bool LegacyShouldJumpTraversableObstacle(
            Vector3 position,
            Vector3 direction)
        {
            const float probeDistance = 1.6f;
            var forwardOffset = direction * 0.2f;
            if (!Physics.Raycast(
                    position + Vector3.up * 0.35f + forwardOffset,
                    direction,
                    out var lowHit,
                    probeDistance,
                    RayMasks.BLOCK_COLLISION,
                    QueryTriggerInteraction.Ignore))
            {
                return false;
            }

            // Inclinação caminhável não é uma janela ou barreira para salto.
            if (lowHit.normal.y > 0.55f)
            {
                return false;
            }

            var middleBlocked = Physics.Raycast(
                position + Vector3.up * 1.05f + forwardOffset,
                direction,
                probeDistance,
                RayMasks.BLOCK_COLLISION,
                QueryTriggerInteraction.Ignore);
            var upperBlocked = Physics.Raycast(
                position + Vector3.up * 1.8f + forwardOffset,
                direction,
                probeDistance,
                RayMasks.BLOCK_COLLISION,
                QueryTriggerInteraction.Ignore);

            // Parede completa bloqueia os três níveis. Soleira de janela deixa
            // o centro livre; cerca ou objeto baixo deixa a parte superior livre.
            if (middleBlocked && upperBlocked)
            {
                return false;
            }

            var landingProbe = position + direction * 2.1f + Vector3.up * 2.5f;
            return Physics.Raycast(
                       landingProbe,
                       Vector3.down,
                       out var landingHit,
                       4f,
                       RayMasks.BLOCK_COLLISION,
                       QueryTriggerInteraction.Ignore)
                   && landingHit.normal.y >= 0.45f;
        }

        private static float DirectionToYaw(Vector3 direction)
        {
            return Mathf.Atan2(direction.x, direction.z) * Mathf.Rad2Deg;
        }

        private static string FormatPosition(Vector3 position)
        {
            return $"({position.x:0.0}, {position.y:0.0}, {position.z:0.0})";
        }
    }
}
